    private static (ushort[] RowOffsets, byte[] Bits, byte[] ByteOffsets)
        BuildClippedShallowSamples(
            ushort targetX,
            ushort targetY,
            ushort bytesPerRow,
            ushort rows)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(targetX, (ushort)2);
        ArgumentOutOfRangeException.ThrowIfNotEqual(targetY, (ushort)1);
        ArgumentOutOfRangeException.ThrowIfLessThan(bytesPerRow, (ushort)1);
        ArgumentOutOfRangeException.ThrowIfNotEqual(rows, (ushort)2);

        // The runtime arms are admitted only when the y=0 run fits the
        // first planar row.  Materialize exactly the visible columns; the
        // endpoint and stipple phase are advanced independently by the arm.
        var visibleColumns = checked(bytesPerRow * 8);
        var firstRowSamples = checked((ushort)((targetX + 1) >> 1));
        if (firstRowSamples > visibleColumns)
            throw new ArgumentOutOfRangeException(nameof(targetX));

        var rowOffsets = new ushort[visibleColumns];
        var bits = new byte[visibleColumns];
        var byteOffsets = new byte[visibleColumns];
        for (ushort x = 0; x < visibleColumns; x++)
        {
            rowOffsets[x] = x < firstRowSamples ? (ushort)0 : bytesPerRow;
            bits[x] = (byte)(7 - (x & 7));
            byteOffsets[x] = (byte)(x >> 3);
        }

        return (rowOffsets, bits, byteOffsets);
    }

    /// <summary>
    /// Construction-time observations for the signed-word branch contract.
    /// This type never enters the native image or its public ABI.
    /// </summary>
    internal sealed class NativeGraphicsBranchRangeAudit
    {
        internal readonly record struct BranchPatch(
            int ExtensionOffset,
            int TargetOffset,
            int Displacement);

        internal readonly record struct FragmentBoundary(
            string Name,
            int Offset);

        private readonly List<BranchPatch> patches = new();
        private readonly List<FragmentBoundary> fragmentBoundaries = new();
        private readonly HashSet<int> localFallbackOffsets = new();

        internal int BranchCount { get; private set; }
        internal int RelayCount { get; private set; }
        internal int ChainCount { get; private set; }
        internal int MaximumAbsoluteDisplacement { get; private set; }
        internal int MinimumDisplacement { get; private set; } = int.MaxValue;
        internal int MaximumDisplacement { get; private set; } = int.MinValue;
        internal IReadOnlyList<BranchPatch> Patches => patches;
        internal int FragmentBoundaryCount => fragmentBoundaries.Count;
        internal IReadOnlyList<FragmentBoundary> FragmentBoundaries => fragmentBoundaries;
        internal IReadOnlySet<int> LocalFallbackOffsets => localFallbackOffsets;

        internal void RecordLocalFallback(int offset) => localFallbackOffsets.Add(offset);

        internal void Record(int extensionOffset, int targetOffset, int displacement)
        {
            BranchCount++;
            patches.Add(new BranchPatch(extensionOffset, targetOffset, displacement));
            MaximumAbsoluteDisplacement = Math.Max(
                MaximumAbsoluteDisplacement,
                Math.Abs(displacement));
            MinimumDisplacement = Math.Min(MinimumDisplacement, displacement);
            MaximumDisplacement = Math.Max(MaximumDisplacement, displacement);
        }

        internal void RecordRelay() => RelayCount++;

        internal void RecordChain() => ChainCount++;

        internal void RecordFragmentBoundary(string name, int offset) =>
            fragmentBoundaries.Add(new FragmentBoundary(name, offset));
    }

