                fallbackEntryOffset,
                xorEmptySourceThreeNodeEntryOffset);
        var xorRegionRegionEmptyDispatchEntryOffset =
            AppendOrXorRegionRegionEmptySourceOnlyDispatchNative(
                code,
                xorRegionRegionBridgeDispatchEntryOffset,
                xorEmptySourceEntryOffset,
                orRegionRegionBridgeDispatchEntryOffset);
        entryOffsets[GraphicsLvo.OrRegionRegion] =
            orRegionRegionBridgeDispatchEntryOffset;
        entryOffsets[GraphicsLvo.XorRegionRegion] =
            xorRegionRegionEmptyDispatchEntryOffset;

        branchAllocator.Complete();
        if (enableNativeMonitorMutation)
            lastPrivateMonitorMutationEntryOffset = AppendSetDisplayInfoDataMutation(code);
        return code.ToArray();
    }

    private static int AppendSetByte(
        List<byte> code,
        int rastPortOffset,
        ushort moveOpcode)
    {
        if ((uint)rastPortOffset > ushort.MaxValue)
            throw new ArgumentOutOfRangeException(nameof(rastPortOffset));

        var offset = code.Count;
        Append(code, moveOpcode);
        Append(code, checked((ushort)rastPortOffset));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        return offset;
    }

    private static int AppendSetRastPortScalar(
        List<byte> code,
        int scalarOffset,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(3);
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x1F00); // D3-D7, reversed predecrement mask
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullBranch = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullBranch);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBranch = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddBranch);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFD0);
        Append(code, BranchHighWord);
        var rangeBranch = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rangeBranch);

        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)scalarOffset));
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, MoveByteA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, MoveByteA1DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        AppendRastPortMinterms(code);
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, AndImmediateWordD4);
        Append(code, 0xBFFF);
        Append(code, MoveWordD4ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x00F8); // retain the existing handled result and CCR
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x00F8); // after restoring the original scalar argument
        Append(code, BranchAlwaysWord);
        var fallbackJump = code.Count;
        Append(code, 0);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        PatchBranch(code, fallbackJump, fallbackEntryOffset);
        return offset;
    }

    // D5=background, D6=foreground, D7=draw mode. Emits the exact eight-byte
    // private minterm cache used by the classic RastPort setters. D3/D4 are
    // scratch and the caller has already admitted the complete 0x28..0x2F
    // cache span. Keeping this generator beside the native bodies prevents
    // byte-order drift from the portable ComputeMinterms contract.
    private static void AppendRastPortMinterms(List<byte> code)
    {
        var complementBranchExtensions = new List<int>(1);
        Append(code, BitTestImmediateD7);
        Append(code, 1); // COMPLEMENT
        Append(code, BranchNotEqualWord);
        complementBranchExtensions.Add(code.Count);
        Append(code, 0);

        for (var plane = 0; plane < 8; plane++)
        {
            var foregroundZeroBranches = new List<int>(1);
            var jamOneBranches = new List<int>(1);
            var backgroundZeroBranches = new List<int>(1);
            var afterBackgroundBranches = new List<int>(1);
            var normalOrderBranches = new List<int>(1);
            var doneBranches = new List<int>(1);

            Append(code, MoveQuickZeroD4);
            Append(code, BitTestImmediateD6);
            Append(code, checked((ushort)plane));
            Append(code, BranchEqualWord);
            foregroundZeroBranches.Add(code.Count);
            Append(code, 0);
            Append(code, (ushort)(MoveQuickZeroD4 | 3));
            var foregroundDoneOffset = code.Count;

            Append(code, BitTestImmediateD7);
            Append(code, 0); // JAM2
            Append(code, BranchEqualWord);
            jamOneBranches.Add(code.Count);
            Append(code, 0);
            Append(code, MoveQuickZeroD3);
            Append(code, BitTestImmediateD5);
            Append(code, checked((ushort)plane));
            Append(code, BranchEqualWord);
            backgroundZeroBranches.Add(code.Count);
            Append(code, 0);
            Append(code, (ushort)(MoveQuickZeroD3 | 3));
            Append(code, BranchAlwaysWord);
            afterBackgroundBranches.Add(code.Count);
            Append(code, 0);
            var jamOneOffset = code.Count;
            Append(code, MoveQuickTwoD3);
            var backgroundDoneOffset = code.Count;

            Append(code, BitTestImmediateD7);
            Append(code, 2); // INVERSVID
            Append(code, BranchEqualWord);
            normalOrderBranches.Add(code.Count);
            Append(code, 0);
            Append(code, ShiftLeftLongD3);
            Append(code, ShiftLeftLongD3);
            Append(code, OrLongD4ToD3);
            Append(code, MoveLongD3ToD1);
            Append(code, ShiftLeftLongD1);
            Append(code, ShiftLeftLongD1);
            Append(code, ShiftLeftLongD1);
            Append(code, ShiftLeftLongD1);
            Append(code, OrImmediateByteD1);
            Append(code, 0x000A);
            Append(code, MoveByteD1ToA1Displacement);
            Append(code, checked((ushort)(GraphicsLayouts.RastPortMinterms + plane)));
            Append(code, BranchAlwaysWord);
            doneBranches.Add(code.Count);
            Append(code, 0);
            var normalOrderOffset = code.Count;
            Append(code, ShiftLeftLongD4);
            Append(code, ShiftLeftLongD4);
            Append(code, OrLongD3ToD4);
            Append(code, MoveLongD4ToD1);
            Append(code, ShiftLeftLongD1);
            Append(code, ShiftLeftLongD1);
            Append(code, ShiftLeftLongD1);
            Append(code, ShiftLeftLongD1);
            Append(code, OrImmediateByteD1);
            Append(code, 0x000A);
            Append(code, MoveByteD1ToA1Displacement);
            Append(code, checked((ushort)(GraphicsLayouts.RastPortMinterms + plane)));
            var doneOffset = code.Count;

            foreach (var branch in foregroundZeroBranches)
                PatchBranch(code, branch, foregroundDoneOffset);
            foreach (var branch in jamOneBranches)
                PatchBranch(code, branch, jamOneOffset);
            foreach (var branch in backgroundZeroBranches)
                PatchBranch(code, branch, backgroundDoneOffset);
            foreach (var branch in afterBackgroundBranches)
                PatchBranch(code, branch, backgroundDoneOffset);
            foreach (var branch in normalOrderBranches)
                PatchBranch(code, branch, normalOrderOffset);
            foreach (var branch in doneBranches)
                PatchBranch(code, branch, doneOffset);
        }

        Append(code, BranchAlwaysWord);
        var normalDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        var complementOffset = code.Count;
        Append(code, BitTestImmediateD7);
        Append(code, 2); // INVERSVID
        Append(code, BranchEqualWord);
        var complementNormalBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, 0x766A); // MOVEQ #$6A,D3
        Append(code, BranchAlwaysWord);
        var complementValueDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        var complementNormalOffset = code.Count;
        Append(code, 0x769A); // MOVEQ #$9A,D3
        var complementValueDoneOffset = code.Count;
        for (var plane = 0; plane < 8; plane++)
        {
            Append(code, MoveByteD3ToA1Displacement);
            Append(code, checked((ushort)(GraphicsLayouts.RastPortMinterms + plane)));
        }
        var normalDoneOffset = code.Count;
        foreach (var branch in complementBranchExtensions)
            PatchBranch(code, branch, complementOffset);
        PatchBranch(code, normalDoneBranchExtensionOffset, normalDoneOffset);
        PatchBranch(code, complementNormalBranchExtensionOffset, complementNormalOffset);
        PatchBranch(code, complementValueDoneBranchExtensionOffset, complementValueDoneOffset);
    }

    private static int AppendSetRawByte(
        List<byte> code,
        int rastPortOffset,
        ushort moveOpcode,
        int fallbackEntryOffset)
    {
        if ((uint)rastPortOffset > ushort.MaxValue)
            throw new ArgumentOutOfRangeException(nameof(rastPortOffset));

        var offset = code.Count;
        var fallbackBranches = new List<int>(3);
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x0800); // D4, reversed predecrement mask.

        // SetWriteMask takes A0 and owns a one-byte write-only transition.
        // It does not consume pen ownership, minterms, bitmap, or layer state.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        var maxAddress = uint.MaxValue - (uint)rastPortOffset;
        Append(code, checked((ushort)(maxAddress >> 16)));
        Append(code, checked((ushort)(maxAddress & ushort.MaxValue)));
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);

        Append(code, moveOpcode);
        Append(code, checked((ushort)rastPortOffset));
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x0010); // Restore public D4 after discarding the saved argument.
        Append(code, MoveQuickMinusOneD0); // Supported per-bit mask: public ULONG success.
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x0010); // Keep the original D0 and prior CCR on decline.
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    /// <summary>
    /// Admits exact identity of two canonical two-node native Regions and,
    /// for the AND-only form, a matching public envelope whose corresponding
    /// destination nodes are contained by the source nodes. An OR-only
    /// continuation can instead prove the source contains the destination and
    /// rewrite the existing destination rectangles in place. Empty/one-node
    /// destinations can re-enter an operation-specific continuation; every
    /// malformed or unsupported pair restores the caller's D0 and remains on
    /// the portable fallback.
    /// </summary>
    private static int AppendRegionRegionTwoNodeIdentityNative(
        List<byte> code,
        int fallbackEntryOffset,
        int twoNodeSourceFallbackEntryOffset,
        bool clearOnSuccess,
        bool allowContainedNodes,
        int nonIdentityEntryOffset = -1,
        bool sourceContainsDestination = false)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(48);
        var oneOrEmptyDestinationBranches = new List<int>(2);
        var nonIdentityBranches = new List<int>(8);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void DeclineNonIdentity(ushort compareOpcode)
        {
            Append(code, compareOpcode);
            Append(code, BranchNotEqualWord);
            if (nonIdentityEntryOffset >= 0)
            {
                nonIdentityBranches.Add(code.Count);
                Append(code, 0);
            }
            else
            {
                fallbackBranches.Add(code.Count);
                Append(code, 0);
            }
        }

        void DeclineSourceContainment(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            if (nonIdentityEntryOffset >= 0)
            {
                nonIdentityBranches.Add(code.Count);
                Append(code, 0);
            }
            else
            {
                fallbackBranches.Add(code.Count);
                Append(code, 0);
            }
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitRelativeEnvelopeValidation(
            ushort nodeMinXToD4,
            ushort nodeMinYToD4,
            ushort nodeMaxXToD5,
            ushort nodeMaxYToD5)
        {
            Append(code, nodeMinXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, nodeMaxXToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, nodeMinYToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, nodeMaxYToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        void EmitNodeEquality(ushort sourceNodeToA2, ushort destinationNodeToA2)
        {
            Append(code, sourceNodeToA2);
            Append(code, MoveWordA2DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA2DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA2DisplacementToD7);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, destinationNodeToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA2DisplacementToD1);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA2DisplacementToD2);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA2DisplacementToD3);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            if (sourceContainsDestination)
            {
                // The source node must contain the corresponding destination
                // node. Equal edges are admitted; OR still needs the
                // destination's public node rewritten to the source result.
                Append(code, CompareWordD4ToD0);
                DeclineSourceContainment(BranchLessThanWord);
                Append(code, CompareWordD5ToD1);
                DeclineSourceContainment(BranchLessThanWord);
                Append(code, CompareWordD6ToD2);
                DeclineSourceContainment(BranchGreaterThanWord);
                Append(code, CompareWordD7ToD3);
                DeclineSourceContainment(BranchGreaterThanWord);
            }
            else if (!allowContainedNodes)
            {
                DeclineNonIdentity(CompareWordD4ToD0);
                DeclineNonIdentity(CompareWordD5ToD1);
                DeclineNonIdentity(CompareWordD6ToD2);
                DeclineNonIdentity(CompareWordD7ToD3);
            }
            else
            {
                // The public envelopes are required to match below, so these
                // relative comparisons prove that every destination node is
                // contained by its corresponding source node. The existing
                // destination chain is therefore already the exact AND
                // result and can be returned without mutation.
                Append(code, CompareWordD4ToD0); Decline(BranchLessThanWord);
                Append(code, CompareWordD5ToD1); Decline(BranchLessThanWord);
                Append(code, CompareWordD6ToD2); Decline(BranchGreaterThanWord);
                Append(code, CompareWordD7ToD3); Decline(BranchGreaterThanWord);
            }
        }

        Append(code, MoveLongD0ToPreDecrementA7);

        // Admit and completely validate the canonical two-node source.  A2
        // and A3 retain its nodes; A5 snapshots the first node before the
        // destination admission reuses A2.
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA2);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA0ToA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, MoveLongA5ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA3);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitRelativeEnvelopeValidation(
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD5,
            MoveWordA2DisplacementToD5);
        EmitRelativeEnvelopeValidation(
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD5,
            MoveWordA3DisplacementToD5);
        Append(code, MoveLongA2ToD6); Append(code, MoveAddressD6ToA5);

        // Preserve the source header in D4..D7 while the destination header
        // and its two-node chain are admitted and checked.
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);

        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        oneOrEmptyDestinationBranches.Add(code.Count); Append(code, 0);
        Append(code, MoveAddressD0ToA4);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA4DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA1ToA2);
        Append(code, AddQuickTwoLongA2); Append(code, AddQuickTwoLongA2);
        Append(code, AddQuickTwoLongA2); Append(code, AddQuickTwoLongA2);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, MoveLongD6ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        oneOrEmptyDestinationBranches.Add(code.Count); Append(code, 0);
        Append(code, MoveAddressD0ToA6);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA4ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitRelativeEnvelopeValidation(
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD5,
            MoveWordA4DisplacementToD5);
        EmitRelativeEnvelopeValidation(
            MoveWordA6DisplacementToD4,
            MoveWordA6DisplacementToD4,
            MoveWordA6DisplacementToD5,
            MoveWordA6DisplacementToD5);

        // Compare the absolute public envelopes, then the two relative node
        // rectangles in list order. No public byte has been written.
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        DeclineNonIdentity(CompareWordD4ToD0);
        DeclineNonIdentity(CompareWordD5ToD1);
        DeclineNonIdentity(CompareWordD6ToD2);
        DeclineNonIdentity(CompareWordD7ToD3);
        EmitNodeEquality(MoveAddressA5ToA2, MoveAddressA4ToA2);
        EmitNodeEquality(MoveAddressA3ToA2, MoveAddressA6ToA2);

        if (sourceContainsDestination)
        {
            // The public envelopes are already equal. Copy only the source
            // relative rectangles into the existing destination nodes; the
            // list links and node addresses remain unchanged.
            Append(code, MoveAddressA0ToA2);
            Append(code, MoveAddressA4ToA0);
            foreach (var displacement in new[] { 0, 2, 4, 6 })
            {
                Append(code, MoveWordA5DisplacementToD0);
                Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
                Append(code, MoveWordD0ToA0Displacement);
                Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
            }
            Append(code, MoveAddressA6ToA0);
            foreach (var displacement in new[] { 0, 2, 4, 6 })
            {
                Append(code, MoveWordA3DisplacementToD0);
                Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
                Append(code, MoveWordD0ToA0Displacement);
                Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
            }
            Append(code, MoveAddressA2ToA0);
        }

        if (!clearOnSuccess)
        {
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);
        }
        else
        {
            // XOR of identical canonical two-node Regions is empty. Resolve
            // Exec only after the complete identity proof, then retire each
            // destination node exactly once and publish the empty header.
            Append(code, MoveLongA6ToD6); // preserve the second node
            Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
            Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0);
            Decline(BranchEqualWord);
            Append(code, MoveAddressA1ToA5);
            Append(code, MoveAddressD0ToA6); // ExecBase
            Append(code, MoveAddressD6ToA0);
            Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
            AppendExecFreeMemFromA0PreservingA1(code);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
            AppendExecFreeMemFromA0PreservingA1(code);
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveQuickZeroD0);
            Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionBounds);
            Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionBounds + 4));
            Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);
        }

        if (nonIdentityEntryOffset >= 0)
        {
            var nonIdentityRestoreOffset = code.Count;
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, BranchAlwaysWord);
            var nonIdentityJumpExtensionOffset = code.Count;
            Append(code, 0);
            PatchBranch(code, nonIdentityJumpExtensionOffset, nonIdentityEntryOffset);
            foreach (var branch in nonIdentityBranches)
                PatchBranch(code, branch, nonIdentityRestoreOffset);
        }

        var twoNodeFallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var twoNodeFallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, twoNodeFallbackJumpExtensionOffset, twoNodeSourceFallbackEntryOffset);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        foreach (var branch in oneOrEmptyDestinationBranches)
            PatchBranch(code, branch, twoNodeFallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Admits exact identity of three canonical native Regions for OR/AND/XOR.
    /// The source and destination chains are fully validated before any public
    /// mutation. OR returns the existing destination unchanged; XOR reduces
    /// the identical operands to an empty destination, retiring all three
    /// destination nodes tail-to-head. Every malformed, non-identical, or
    /// missing-Exec form restores the caller's D0 frame and enters the
    /// established portable/native chain.
    /// </summary>
    private static int AppendRegionRegionThreeNodeIdentityNative(
        List<byte> code,
        int fallbackEntryOffset,
        bool clearOnSuccess)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(96);
        var earlyFallbackBranches = new List<int>(32);
        var sourcePointersSaved = false;

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            (sourcePointersSaved ? fallbackBranches : earlyFallbackBranches).Add(extensionOffset);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0);
            Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0);
            Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitPointerAdmission(ushort movePointerToD0)
        {
            Append(code, movePointerToD0);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0);
            Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        void EmitRelativeBoundsValidation(
            ushort moveNodeToA5,
            bool sourceHeader)
        {
            Append(code, moveNodeToA5);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA5DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA5DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA5DisplacementToD7);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD6); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, CompareWordD5ToD7); Decline(BranchLessThanWord);
            Append(code, TestWordD5); Decline(BranchLessThanWord);

            var headerMinX = sourceHeader
                ? MoveWordA0DisplacementToD0
                : MoveWordA6DisplacementToD0;
            var headerMaxX = sourceHeader
                ? MoveWordA0DisplacementToD1
                : MoveWordA6DisplacementToD1;
            var headerMinY = sourceHeader
                ? MoveWordA0DisplacementToD0
                : MoveWordA6DisplacementToD0;
            var headerMaxY = sourceHeader
                ? MoveWordA0DisplacementToD1
                : MoveWordA6DisplacementToD1;

            // Region rectangles are stored relative to the public envelope.
            // Check the envelope extent rather than comparing relative
            // coordinates with its absolute origin.
            Append(code, headerMinX); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, headerMaxX); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, SubWordD0ToD1); Decline(BranchOverflowWord);
            Append(code, CompareWordD6ToD1); Decline(BranchLessThanWord);
            Append(code, headerMinY); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, headerMaxY); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, SubWordD0ToD1); Decline(BranchOverflowWord);
            Append(code, CompareWordD7ToD1); Decline(BranchLessThanWord);
        }

        void EmitNodeEquality(ushort moveDestinationToA5, int sourceStackOffset)
        {
            Append(code, moveDestinationToA5);
            Append(code, MoveLongA7DisplacementToD7);
            Append(code, checked((ushort)sourceStackOffset));
            Append(code, MoveAddressD7ToA6);
            foreach (var displacement in new[]
                     {
                         GraphicsLayouts.RectangleMinX,
                         GraphicsLayouts.RectangleMinY,
                         GraphicsLayouts.RectangleMaxX,
                         GraphicsLayouts.RectangleMaxY
                     })
            {
                Append(code, MoveWordA6DisplacementToD4);
                Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
                Append(code, MoveWordA5DisplacementToD0);
                Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
                Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
            }
        }

        // Keep the caller's seed below the three source node pointers.  The
        // saved source pointers are addressed at +8, +4, and +0 while the
        // destination admission reuses A2/A3/A4.
        Append(code, MoveLongD0ToPreDecrementA7);

        // Source: marker-owned canonical three-node Region.
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA2);
        EmitPointerAdmission(MoveLongA2ToD0);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA0ToA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, MoveLongA5ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA3);
        EmitPointerAdmission(MoveLongA3ToD0);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA4);
        EmitPointerAdmission(MoveLongA4ToD0);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveWordA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitRelativeBoundsValidation(MoveAddressA2ToA5, sourceHeader: true);
        EmitRelativeBoundsValidation(MoveAddressA3ToA5, sourceHeader: true);
        EmitRelativeBoundsValidation(MoveAddressA4ToA5, sourceHeader: true);

        // Canonical Region ordering is strict in Y.  This keeps an exact
        // identity arm from accepting overlapping or touching non-canonical
        // lists that belong to the portable boolean builder.
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA3DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD5ToD4);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA4DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD5ToD4);

        Append(code, MoveLongA2ToPreDecrementA7);
        Append(code, MoveLongA3ToPreDecrementA7);
        Append(code, MoveLongA4ToPreDecrementA7);
        sourcePointersSaved = true;

        // Destination: marker-owned canonical three-node Region.
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA2);
        EmitPointerAdmission(MoveLongA2ToD0);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA1ToA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, MoveLongA5ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA3);
        EmitPointerAdmission(MoveLongA3ToD0);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA4);
        EmitPointerAdmission(MoveLongA4ToD0);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveWordA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        Append(code, MoveAddressA1ToA6);
        EmitRelativeBoundsValidation(MoveAddressA2ToA5, sourceHeader: false);
        EmitRelativeBoundsValidation(MoveAddressA3ToA5, sourceHeader: false);
        EmitRelativeBoundsValidation(MoveAddressA4ToA5, sourceHeader: false);

        Append(code, MoveWordA2DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA3DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD5ToD4);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA4DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);

        // The public envelopes and all three relative rectangles must match.
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD5);
        Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD7);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, CompareWordD5ToD1); Decline(BranchNotEqualWord);
        Append(code, CompareWordD6ToD2); Decline(BranchNotEqualWord);
        Append(code, CompareWordD7ToD3); Decline(BranchNotEqualWord);
        EmitNodeEquality(MoveAddressA2ToA5, 8);
        EmitNodeEquality(MoveAddressA3ToA5, 4);
        EmitNodeEquality(MoveAddressA4ToA5, 0);

        // XOR must resolve Exec only after the complete identity proof because
        // it retires destination nodes. OR is allocation-free and leaves the
        // existing destination untouched, so it has no Exec dependency.
        if (clearOnSuccess)
        {
            Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
            Append(code, MoveLongA6IndirectToD0);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, MoveAddressD0ToA6); // ExecBase
        }
        Append(code, MoveLongA2ToPreDecrementA7);
        Append(code, MoveLongA3ToPreDecrementA7);
        Append(code, MoveLongA4ToPreDecrementA7);

        if (!clearOnSuccess)
        {
            // Discard the destination-node frame, restore the caller's seed,
            // and return the read-only OR identity without public writes.
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongA7DisplacementToD0); Append(code, 12);
            Append(code, AddQuickEightLongA7);
            Append(code, AddQuickEightLongA7);
            Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);
        }

        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);

        Append(code, MoveAddressA1ToA0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionBounds);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionBounds + 4));
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveLongA7DisplacementToD0); Append(code, 12);
        Append(code, AddQuickEightLongA7);
        Append(code, AddQuickEightLongA7);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var earlyFallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var earlyFallbackJumpExtensionOffset = code.Count; Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7DisplacementToD0); Append(code, 12);
        Append(code, AddQuickEightLongA7);
        Append(code, AddQuickEightLongA7);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, earlyFallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in earlyFallbackBranches)
            PatchBranch(code, branchExtensionOffset, earlyFallbackRestoreOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Emits the first result-record Screen-prefix allocator. It composes the
    /// depth-four owner, replaces its table with a twenty-byte table containing
    /// five planes, and writes the complete owned topology to the caller's A0
    /// result envelope only after publication succeeds. ABI: A6=ExecBase,
    /// A0=result record, D0/D1=width/height, D2=bytes per plane, D3=5;
    /// success returns D0=1 and failure returns D0=0 without touching the
    /// result record.
    /// </summary>
    private static int AppendAllocateScreenPrefixMultiPlaneDepth5ResultExec(
        List<byte> code,
        int depth4AllocatorOffset,
        int publisherOffset)
    {
        var offset = code.Count;
        var validationBranches = new List<int>(3);
        var prefixFailureBranches = new List<int>(1);
        var tableFailureBranches = new List<int>(1);
        var planeFailureBranches = new List<int>(1);
        var publishFailureBranches = new List<int>(1);

        void AppendBranch(ushort opcode, List<int> branches)
        {
            Append(code, opcode);
            branches.Add(code.Count);
            Append(code, 0);
        }

        void AppendAllocFixed(int byteCount, uint flags, List<int> failureBranches)
        {
            Append(code, MoveLongImmediateD0);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)(flags >> 16));
            Append(code, (ushort)flags);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
            Append(code, TestLongD0);
            AppendBranch(BranchEqualWord, failureBranches);
            Append(code, MoveLongD0ToPreDecrementA7);
        }

        void AppendFreeFixed(int byteCount)
        {
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            AppendExecFreeMemFromD0D1PreservingA1(code);
        }

        void AppendWriteResultLong(int fieldOffset)
        {
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, checked((ushort)fieldOffset));
        }

        // A0 is a caller-owned result envelope. Require a non-null, even
        // address before any Exec call; all result writes are deferred until
        // the new five-plane topology has been published.
        // Validation uses D0 as the scratch register for the caller's result
        // envelope. Preserve the requested width before that check so the
        // nested depth-four owner still receives the original D0/D1 geometry.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD0);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, validationBranches);
        Append(code, BitTestImmediateD0);
        Append(code, 0x0000);
        AppendBranch(BranchNotEqualWord, validationBranches);
        Append(code, CompareImmediateLongD3);
        Append(code, 0x0000);
        Append(code, 0x0005);
        AppendBranch(BranchNotEqualWord, validationBranches);
        Append(code, MoveLongD7ToD0);

        // Keep two copies of the result pointer below every private rollback
        // frame. One is consumed after success/failure; the second is simply
        // discarded, so no address register has to survive Exec or publisher
        // calls.
        Append(code, MoveLongA0ToPreDecrementA7);
        Append(code, MoveLongA0ToPreDecrementA7);
        Append(code, MoveLongD3ToPreDecrementA7);
        Append(code, MoveLongD2ToPreDecrementA7);
        Append(code, MoveQuickFourD3);
        AppendJsrPcRelative(code, depth4AllocatorOffset);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, prefixFailureBranches);

        // Depth-four success returns D0..D7 as Screen/View/RasInfo/table and
        // four planes. Preserve plane three and Screen while consuming our
        // saved byte/depth inputs; D7 then carries the dynamic plane size.
        Append(code, MoveAddressD7ToA2); // plane three
        Append(code, MoveAddressD0ToA1); // Screen
        Append(code, MoveLongA7PostIncrementToD7); // bytes per plane
        Append(code, MoveLongA7PostIncrementToD0); // requested depth
        Append(code, MoveLongA1ToD0); // restore Screen

        // Preserve the depth-four topology while the replacement table and
        // fifth plane are acquired. D7 is the saved dynamic byte count; the
        // old plane three remains in A2 until it is framed below.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongD2ToPreDecrementA7);
        Append(code, MoveLongD3ToPreDecrementA7);
        Append(code, MoveLongD4ToPreDecrementA7);
        Append(code, MoveLongD5ToPreDecrementA7);
        Append(code, MoveLongD6ToPreDecrementA7);
        Append(code, MoveLongD7ToPreDecrementA7);
        Append(code, MoveLongA2ToD0);
        Append(code, MoveLongD0ToPreDecrementA7); // plane three

        AppendAllocFixed(20, 0x0001_0001u, tableFailureBranches);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0003); // PUBLIC | CHIP | CLEAR
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, planeFailureBranches);
        Append(code, MoveLongD0ToPreDecrementA7); // plane four

        // Recover the new allocations and the depth-four topology. The stack
        // remains rooted at the two caller result pointers.
        Append(code, MoveLongA7PostIncrementToD0); // plane four
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveAddressA0ToA1); // retain plane four
        Append(code, MoveLongA7PostIncrementToD0); // replacement table
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA7PostIncrementToD3); // plane three
        Append(code, MoveAddressD3ToA0);
        Append(code, MoveAddressA0ToA2);
        Append(code, MoveLongA7PostIncrementToD7); // bytes per plane
        Append(code, MoveLongA7PostIncrementToD6); // plane two
        Append(code, MoveLongA7PostIncrementToD5); // plane one
        Append(code, MoveLongA7PostIncrementToD4); // plane zero
        Append(code, MoveLongA7PostIncrementToD3); // old table
        Append(code, MoveLongA7PostIncrementToD2); // RasInfo
        Append(code, MoveLongA7PostIncrementToD1); // View
        Append(code, MoveLongA7PostIncrementToD0); // Screen
        Append(code, MoveAddressD0ToA5); // retain Screen

        // The second result-pointer copy is no longer needed by the failure
        // paths once every allocation has succeeded. Keep it in A3 until the
        // rollback frame is complete, then place a dedicated copy above that
        // frame so the publisher cannot disturb the result destination.
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA5ToD0); // restore Screen for frame capture

        // Rollback frame order is Screen, View, old table, RasInfo, planes
        // zero through three, replacement table, plane four, byte size.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongD3ToPreDecrementA7); // old table
        Append(code, MoveLongD2ToPreDecrementA7); // RasInfo
        Append(code, MoveLongD4ToPreDecrementA7);
        Append(code, MoveLongD5ToPreDecrementA7);
        Append(code, MoveLongD6ToPreDecrementA7);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongA0ToD0);
        Append(code, MoveLongD0ToD3);
        Append(code, MoveLongD3ToPreDecrementA7); // plane three
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToPreDecrementA7); // replacement table
        Append(code, MoveLongA1ToD0);
        Append(code, MoveLongD0ToPreDecrementA7); // plane four
        Append(code, MoveLongD7ToPreDecrementA7); // bytes
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToPreDecrementA7); // result record

        // Publish all five pointers only after every allocation exists.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD3ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongA1ToD0); // plane four
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveAddressA5ToA0); // Screen
        Append(code, MoveAddressA4ToA1); // replacement table
        Append(code, MoveQuickFiveD0);
        AppendJsrPcRelative(code, publisherOffset);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, publishFailureBranches);

        // Success: consume the frame, publish the caller result record, then
        // release the obsolete depth-four table. The record is untouched on
        // every earlier failure path.
        Append(code, MoveLongA7PostIncrementToD0); // result record
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA7PostIncrementToD7); // bytes discard
        Append(code, MoveLongA7PostIncrementToD0); // plane four
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlane4);
        Append(code, MoveLongA7PostIncrementToD0); // replacement table
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlaneTable);
        Append(code, MoveLongA7PostIncrementToD0); // plane three
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlane3);
        Append(code, MoveLongA7PostIncrementToD0); // plane two
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlane2);
        Append(code, MoveLongA7PostIncrementToD0); // plane one
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlane1);
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlane0);
        Append(code, MoveLongA7PostIncrementToD0); // RasInfo
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultRasInfo);
        Append(code, MoveLongA7PostIncrementToD0); // old table
        Append(code, MoveAddressD0ToA1);
        Append(code, MoveLongA7PostIncrementToD0); // View
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultView);
        Append(code, MoveLongA7PostIncrementToD0); // Screen
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultScreen);
        Append(code, MoveLongA7PostIncrementToD0); // remaining result copy
        Append(code, MoveLongA1ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0000);
        Append(code, 0x0010);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        var publishFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // result record
        Append(code, MoveLongA7PostIncrementToD7); // bytes per plane
        Append(code, MoveLongA7PostIncrementToD0); // plane four
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(20); // replacement table
        Append(code, MoveLongA7PostIncrementToD0); // plane three
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane two
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane one
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(GraphicsLayouts.RasInfoSize);
        AppendFreeFixed(16); // old depth-four table
        AppendFreeFixed(GraphicsLayouts.ViewSize);
        AppendFreeFixed(GraphicsLayouts.ScreenSize);
        Append(code, MoveLongA7PostIncrementToD0); // remaining result copy
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var planeFailureOffset = code.Count;
        AppendFreeFixed(20); // replacement table
        Append(code, MoveLongA7PostIncrementToD0); // plane three
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA7PostIncrementToD7); // bytes
        Append(code, MoveLongA2ToD0);
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane two
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane one
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(16); // old depth-four table
        AppendFreeFixed(GraphicsLayouts.RasInfoSize);
        AppendFreeFixed(GraphicsLayouts.ViewSize);
        AppendFreeFixed(GraphicsLayouts.ScreenSize);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var tableFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // plane three
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA7PostIncrementToD7); // bytes
        Append(code, MoveLongA2ToD0);
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane two
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane one
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(16); // old depth-four table
        AppendFreeFixed(GraphicsLayouts.RasInfoSize);
        AppendFreeFixed(GraphicsLayouts.ViewSize);
        AppendFreeFixed(GraphicsLayouts.ScreenSize);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var prefixFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // bytes discard
        Append(code, MoveLongA7PostIncrementToD0); // depth discard
        Append(code, MoveLongA7PostIncrementToD0); // result copy
        Append(code, MoveLongA7PostIncrementToD0); // second result copy
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var validationFailureOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        foreach (var branch in publishFailureBranches)
            PatchBranch(code, branch, publishFailureOffset);
        foreach (var branch in planeFailureBranches)
            PatchBranch(code, branch, planeFailureOffset);
        foreach (var branch in tableFailureBranches)
            PatchBranch(code, branch, tableFailureOffset);
        foreach (var branch in prefixFailureBranches)
            PatchBranch(code, branch, prefixFailureOffset);
        foreach (var branch in validationBranches)
            PatchBranch(code, branch, validationFailureOffset);

        return offset;
    }

    /// <summary>
    /// Emits the extended native depth-six Screen-prefix result-record
    /// allocator. It composes the depth-five result-record owner, replaces its
    /// twenty-byte table with a twenty-four-byte table, and adds plane five.
    /// The caller supplies the extended eight-plane result envelope at A0;
    /// D0/D1/D2 carry width/height/plane bytes and D3=6. The original result
    /// envelope is snapshotted before composition, so a later allocation or
    /// publisher decline restores both guest bytes and all newly acquired
    /// ownership. Success returns D0=1 and keeps A6=ExecBase.
    /// </summary>
    private static int AppendAllocateScreenPrefixMultiPlaneDepth6ResultExec(
        List<byte> code,
        int depth5AllocatorOffset,
        int publisherOffset)
    {
        var offset = code.Count;
        var validationBranches = new List<int>(3);
        var prefixFailureBranches = new List<int>(1);
        var tableFailureBranches = new List<int>(1);
        var planeFailureBranches = new List<int>(1);
        var publishFailureBranches = new List<int>(1);
        var resultOffsets = new[]
        {
            GraphicsLayouts.ScreenPrefixExecResultScreen,
            GraphicsLayouts.ScreenPrefixExecResultView,
            GraphicsLayouts.ScreenPrefixExecResultRasInfo,
            GraphicsLayouts.ScreenPrefixExecResultPlaneTable,
            GraphicsLayouts.ScreenPrefixExecResultPlane0,
            GraphicsLayouts.ScreenPrefixExecResultPlane1,
            GraphicsLayouts.ScreenPrefixExecResultPlane2,
            GraphicsLayouts.ScreenPrefixExecResultPlane3,
            GraphicsLayouts.ScreenPrefixExecResultPlane4,
            GraphicsLayouts.ScreenPrefixExecResultPlane5,
            GraphicsLayouts.ScreenPrefixExecResultPlane6,
            GraphicsLayouts.ScreenPrefixExecResultPlane7
        };

        void AppendBranch(ushort opcode, List<int> branches)
        {
            Append(code, opcode);
            branches.Add(code.Count);
            Append(code, 0);
        }

        void AppendAllocFixed(int byteCount, uint flags, List<int> failures)
        {
            Append(code, MoveLongImmediateD0);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)(flags >> 16));
            Append(code, (ushort)flags);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
            Append(code, TestLongD0);
            AppendBranch(BranchEqualWord, failures);
            Append(code, MoveLongD0ToPreDecrementA7);
        }

        void AppendFreeFixed(int byteCount)
        {
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            AppendExecFreeMemFromD0D1PreservingA1(code);
        }

        void AppendWriteResultLong(int fieldOffset)
        {
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, checked((ushort)fieldOffset));
        }

        void AppendRestoreSnapshot()
        {
            for (var index = resultOffsets.Length - 1; index >= 0; index--)
            {
                Append(code, MoveLongA7PostIncrementToD0);
                AppendWriteResultLong(resultOffsets[index]);
            }
        }

        void AppendDiscardSnapshotAndOriginalResult()
        {
            foreach (var _ in resultOffsets)
                Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongA7PostIncrementToD0);
        }

        // A0 is the caller-owned extended result envelope. Preserve width
        // while A0 is used as validation scratch, then snapshot every result
        // long before the composed depth-five owner can publish anything.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD0);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, validationBranches);
        Append(code, BitTestImmediateD0);
        Append(code, 0x0000);
        AppendBranch(BranchNotEqualWord, validationBranches);
        Append(code, CompareImmediateLongD3);
        Append(code, 0x0000);
        Append(code, 0x0006);
        AppendBranch(BranchNotEqualWord, validationBranches);
        Append(code, MoveLongD7ToD0);

        // The bottom marker is the original result pointer. The snapshot is
        // followed by the requested byte count and a nested-call marker; all
        // of these remain below the private ownership frame.
        Append(code, MoveLongA0ToPreDecrementA7);
        foreach (var fieldOffset in resultOffsets)
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)fieldOffset));
            Append(code, MoveLongD0ToPreDecrementA7);
        }
        Append(code, MoveLongD2ToPreDecrementA7); // bytes per plane
        Append(code, MoveLongA0ToPreDecrementA7); // nested result marker
        Append(code, MoveLongD7ToD0); // restore width after snapshot loads
        Append(code, MoveQuickFiveD3);
        AppendJsrPcRelative(code, depth5AllocatorOffset);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, prefixFailureBranches);

        // Recover the result pointer and requested byte count, then retain a
        // second result marker below the old depth-five topology while the
        // replacement table and sixth plane are allocated.
        Append(code, MoveLongA7PostIncrementToD0); // nested result marker
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA7PostIncrementToD7); // bytes per plane
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToPreDecrementA7); // persistent result marker

        // Depth-five published fields become the old topology. Keep them on
        // the stack so every failure arm can release the complete composed
        // owner without depending on caller-visible address registers.
        foreach (var fieldOffset in new[]
        {
            GraphicsLayouts.ScreenPrefixExecResultScreen,
            GraphicsLayouts.ScreenPrefixExecResultView,
            GraphicsLayouts.ScreenPrefixExecResultRasInfo,
            GraphicsLayouts.ScreenPrefixExecResultPlaneTable,
            GraphicsLayouts.ScreenPrefixExecResultPlane0,
            GraphicsLayouts.ScreenPrefixExecResultPlane1,
            GraphicsLayouts.ScreenPrefixExecResultPlane2,
            GraphicsLayouts.ScreenPrefixExecResultPlane3,
            GraphicsLayouts.ScreenPrefixExecResultPlane4
        })
        {
            Append(code, MoveLongA3DisplacementToD0);
            Append(code, checked((ushort)fieldOffset));
            Append(code, MoveLongD0ToPreDecrementA7);
        }

        AppendAllocFixed(24, 0x0001_0001u, tableFailureBranches);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0003); // PUBLIC | CHIP | CLEAR
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, planeFailureBranches);
        Append(code, MoveLongD0ToPreDecrementA7); // plane five

        // Recover plane five, replacement table, old plane four through zero,
        // the old table/RasInfo/View/Screen, and the persistent result marker.
        Append(code, MoveLongA7PostIncrementToD0); // plane five
        Append(code, MoveAddressD0ToA1);
        Append(code, MoveLongA7PostIncrementToD0); // replacement table
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA7PostIncrementToD0); // plane four
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA7PostIncrementToD6); // plane three
        Append(code, MoveLongA7PostIncrementToD5); // plane two
        Append(code, MoveLongA7PostIncrementToD4); // plane one
        Append(code, MoveLongA7PostIncrementToD3); // plane zero
        Append(code, MoveLongA7PostIncrementToD2); // old table
        Append(code, MoveLongA7PostIncrementToD1); // RasInfo
        Append(code, MoveLongA7PostIncrementToD0); // View
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA7PostIncrementToD0); // Screen
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA7PostIncrementToD0); // persistent result
        Append(code, MoveAddressD0ToA3);

        // Rollback frame order is Screen, View, old table, RasInfo, planes
        // zero through four, replacement table, plane five, bytes, then two
        // result markers. The extension marker is consumed first; the second
        // marker remains available while Exec frees resources on failure.
        Append(code, MoveLongA5ToD0);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA0ToD0);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD2ToPreDecrementA7); // old table
        Append(code, MoveLongD1ToPreDecrementA7); // RasInfo
        Append(code, MoveLongD3ToPreDecrementA7);
        Append(code, MoveLongD4ToPreDecrementA7);
        Append(code, MoveLongD5ToPreDecrementA7);
        Append(code, MoveLongD6ToPreDecrementA7);
        Append(code, MoveLongA2ToD0);
        Append(code, MoveLongD0ToPreDecrementA7); // plane four
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToPreDecrementA7); // replacement table
        Append(code, MoveLongA1ToD0);
        Append(code, MoveLongD0ToPreDecrementA7); // plane five
        Append(code, MoveLongD7ToPreDecrementA7); // bytes
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToPreDecrementA7); // persistent result
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToPreDecrementA7); // extension result

        // Fill and publish all six pointers only after the new ownership is
        // complete. The existing publisher performs the guest preflight and
        // embedded BitMap update atomically for the selected depth.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongD3ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongA2ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongA1ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveAddressA4ToA1);
        Append(code, MoveQuickSixD0);
        AppendJsrPcRelative(code, publisherOffset);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, publishFailureBranches);

        // Success publishes the extended record, clears unused plane six and
        // seven slots, frees the obsolete twenty-byte table, and discards the
        // snapshot plus original marker before returning D0=1.
        Append(code, MoveLongA7PostIncrementToD0); // extension result
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA7PostIncrementToD0); // persistent result
        Append(code, MoveLongA7PostIncrementToD7); // bytes discard
        Append(code, MoveLongA7PostIncrementToD0); // plane five
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlane5);
        Append(code, MoveLongA7PostIncrementToD0); // replacement table
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlaneTable);
        Append(code, MoveLongA7PostIncrementToD0); // plane four
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlane4);
        Append(code, MoveLongA7PostIncrementToD0); // plane three
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlane3);
        Append(code, MoveLongA7PostIncrementToD0); // plane two
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlane2);
        Append(code, MoveLongA7PostIncrementToD0); // plane one
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlane1);
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlane0);
        Append(code, MoveLongA7PostIncrementToD0); // RasInfo
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultRasInfo);
        Append(code, MoveLongA7PostIncrementToD0); // old table
        Append(code, MoveAddressD0ToA1);
        Append(code, MoveLongA7PostIncrementToD0); // View
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultView);
        Append(code, MoveLongA7PostIncrementToD0); // Screen
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultScreen);
        Append(code, MoveQuickZeroD0);
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlane6);
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlane7);
        Append(code, MoveLongA1ToD0); // obsolete depth-five table
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0000);
        Append(code, 0x0014);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendDiscardSnapshotAndOriginalResult();
        Append(code, MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        var publishFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // extension result
        Append(code, MoveLongA7PostIncrementToD0); // persistent result
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA7PostIncrementToD7); // bytes
        Append(code, MoveLongA7PostIncrementToD0); // plane five
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(24); // replacement table
        Append(code, MoveLongA7PostIncrementToD0); // plane four
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane three
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane two
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane one
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(GraphicsLayouts.RasInfoSize);
        AppendFreeFixed(20); // depth-five table
        AppendFreeFixed(GraphicsLayouts.ViewSize);
        AppendFreeFixed(GraphicsLayouts.ScreenSize);
        Append(code, MoveAddressA3ToA0);
        AppendRestoreSnapshot();
        Append(code, MoveLongA7PostIncrementToD0); // original result marker
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var planeFailureOffset = code.Count;
        AppendFreeFixed(24); // replacement table
        Append(code, MoveLongA7PostIncrementToD0); // plane four
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane three
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane two
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane one
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(20); // depth-five table
        AppendFreeFixed(GraphicsLayouts.RasInfoSize);
        AppendFreeFixed(GraphicsLayouts.ViewSize);
        AppendFreeFixed(GraphicsLayouts.ScreenSize);
        Append(code, MoveLongA7PostIncrementToD0); // persistent result
        Append(code, MoveAddressD0ToA0);
        AppendRestoreSnapshot();
        Append(code, MoveLongA7PostIncrementToD0); // original result marker
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var tableFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // plane four
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane three
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane two
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane one
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(20); // depth-five table
        AppendFreeFixed(GraphicsLayouts.RasInfoSize);
        AppendFreeFixed(GraphicsLayouts.ViewSize);
        AppendFreeFixed(GraphicsLayouts.ScreenSize);
        Append(code, MoveLongA7PostIncrementToD0); // persistent result
        Append(code, MoveAddressD0ToA0);
        AppendRestoreSnapshot();
        Append(code, MoveLongA7PostIncrementToD0); // original result marker
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var prefixFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // nested result marker
        Append(code, MoveAddressD0ToA0); // restore destination after nested volatile calls
        Append(code, MoveLongA7PostIncrementToD0); // bytes
        AppendRestoreSnapshot();
        Append(code, MoveLongA7PostIncrementToD0); // original result marker
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var validationFailureOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        foreach (var branch in publishFailureBranches)
            PatchBranch(code, branch, publishFailureOffset);
        foreach (var branch in planeFailureBranches)
            PatchBranch(code, branch, planeFailureOffset);
        foreach (var branch in tableFailureBranches)
            PatchBranch(code, branch, tableFailureOffset);
        foreach (var branch in prefixFailureBranches)
            PatchBranch(code, branch, prefixFailureOffset);
        foreach (var branch in validationBranches)
            PatchBranch(code, branch, validationFailureOffset);

        return offset;
    }

    private static int AppendAllocateScreenPrefixMultiPlaneDepth7ResultExec(
        List<byte> code,
        int depth6AllocatorOffset,
        int publisherOffset) =>
        AppendAllocateScreenPrefixMultiPlaneExtendedDepthResultExec(
            code,
            requestedDepth: 7,
            nestedDepth: 6,
            depthAllocatorOffset: depth6AllocatorOffset,
            publisherOffset,
            oldTableBytes: 24,
            newTableBytes: 28,
            newPlaneResultOffset: GraphicsLayouts.ScreenPrefixExecResultPlane6);

    private static int AppendAllocateScreenPrefixMultiPlaneDepth8ResultExec(
        List<byte> code,
        int depth7AllocatorOffset,
        int publisherOffset) =>
        AppendAllocateScreenPrefixMultiPlaneExtendedDepthResultExec(
            code,
            requestedDepth: 8,
            nestedDepth: 7,
            depthAllocatorOffset: depth7AllocatorOffset,
            publisherOffset,
            oldTableBytes: 28,
            newTableBytes: 32,
            newPlaneResultOffset: GraphicsLayouts.ScreenPrefixExecResultPlane7);

    private static int AppendAllocateScreenPrefixMultiPlaneExtendedDepthResultExec(
        List<byte> code,
        int requestedDepth,
        int nestedDepth,
        int depthAllocatorOffset,
        int publisherOffset,
        int oldTableBytes,
        int newTableBytes,
        int newPlaneResultOffset)
    {
        var offset = code.Count;
        var validationBranches = new List<int>(3);
        var prefixFailureBranches = new List<int>(1);
        var tableFailureBranches = new List<int>(1);
        var planeFailureBranches = new List<int>(1);
        var publishFailureBranches = new List<int>(1);
        var resultOffsets = new[]
        {
            GraphicsLayouts.ScreenPrefixExecResultScreen,
            GraphicsLayouts.ScreenPrefixExecResultView,
            GraphicsLayouts.ScreenPrefixExecResultRasInfo,
            GraphicsLayouts.ScreenPrefixExecResultPlaneTable,
            GraphicsLayouts.ScreenPrefixExecResultPlane0,
            GraphicsLayouts.ScreenPrefixExecResultPlane1,
            GraphicsLayouts.ScreenPrefixExecResultPlane2,
            GraphicsLayouts.ScreenPrefixExecResultPlane3,
            GraphicsLayouts.ScreenPrefixExecResultPlane4,
            GraphicsLayouts.ScreenPrefixExecResultPlane5,
            GraphicsLayouts.ScreenPrefixExecResultPlane6,
            GraphicsLayouts.ScreenPrefixExecResultPlane7
        };
        var oldTopologyOffsets = new[]
        {
            GraphicsLayouts.ScreenPrefixExecResultScreen,
            GraphicsLayouts.ScreenPrefixExecResultView,
            GraphicsLayouts.ScreenPrefixExecResultRasInfo,
            GraphicsLayouts.ScreenPrefixExecResultPlaneTable
        };

        void AppendBranch(ushort opcode, List<int> branches)
        {
            Append(code, opcode);
            branches.Add(code.Count);
            Append(code, 0);
        }

        void AppendAllocFixed(int byteCount, uint flags, List<int> failures)
        {
            Append(code, MoveLongImmediateD0);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)(flags >> 16));
            Append(code, (ushort)flags);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
            Append(code, TestLongD0);
            AppendBranch(BranchEqualWord, failures);
            Append(code, MoveLongD0ToPreDecrementA7);
        }

        void AppendFreeFixed(int byteCount)
        {
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            AppendExecFreeMemFromD0D1PreservingA1(code);
        }

        void AppendWriteResultLong(int fieldOffset)
        {
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, checked((ushort)fieldOffset));
        }

        void AppendRestoreSnapshot()
        {
            for (var index = resultOffsets.Length - 1; index >= 0; index--)
            {
                Append(code, MoveLongA7PostIncrementToD0);
                AppendWriteResultLong(resultOffsets[index]);
            }
        }

        void AppendDiscardSnapshotAndOriginalResult()
        {
            foreach (var _ in resultOffsets)
                Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongA7PostIncrementToD0);
        }

        void AppendFreeOldTopology()
        {
            for (var plane = nestedDepth - 1; plane >= 0; plane--)
            {
                Append(code, MoveLongA7PostIncrementToD0);
                Append(code, MoveLongD7ToD1);
                AppendExecFreeMemFromD0D1PreservingA1(code);
            }
            AppendFreeFixed(oldTableBytes);
            AppendFreeFixed(GraphicsLayouts.RasInfoSize);
            AppendFreeFixed(GraphicsLayouts.ViewSize);
            AppendFreeFixed(GraphicsLayouts.ScreenSize);
        }

        // Validate the extended result envelope and snapshot all twelve
        // longwords before the nested owner can publish its lower depth.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD0);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, validationBranches);
        Append(code, BitTestImmediateD0);
        Append(code, 0x0000);
        AppendBranch(BranchNotEqualWord, validationBranches);
        Append(code, CompareImmediateLongD3);
        Append(code, 0x0000);
        Append(code, (ushort)requestedDepth);
        AppendBranch(BranchNotEqualWord, validationBranches);
        Append(code, MoveLongD7ToD0);

        Append(code, MoveLongA0ToPreDecrementA7); // original result marker
        foreach (var fieldOffset in resultOffsets)
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)fieldOffset));
            Append(code, MoveLongD0ToPreDecrementA7);
        }
        Append(code, MoveLongD2ToPreDecrementA7); // bytes per plane
        Append(code, MoveLongA0ToPreDecrementA7); // nested result marker
        Append(code, MoveLongD7ToD0); // restore width after snapshot loads
        Append(code, (ushort)(MoveQuickZeroD3 | nestedDepth));
        AppendJsrPcRelative(code, depthAllocatorOffset);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, prefixFailureBranches);

        Append(code, MoveLongA7PostIncrementToD0); // nested result marker
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA7PostIncrementToD7); // bytes per plane
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToPreDecrementA7); // persistent result marker

        // Save the lower-depth topology in publication order. The persistent
        // result marker remains immediately below it for every failure arm.
        foreach (var fieldOffset in oldTopologyOffsets)
        {
            Append(code, MoveLongA3DisplacementToD0);
            Append(code, checked((ushort)fieldOffset));
            Append(code, MoveLongD0ToPreDecrementA7);
        }
        for (var plane = 0; plane < nestedDepth; plane++)
        {
            Append(code, MoveLongA3DisplacementToD0);
            Append(code, checked((ushort)(GraphicsLayouts.ScreenPrefixExecResultPlane0 + (plane * 4))));
            Append(code, MoveLongD0ToPreDecrementA7);
        }

        AppendAllocFixed(newTableBytes, 0x0001_0001u, tableFailureBranches);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0003); // PUBLIC | CHIP | CLEAR
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, planeFailureBranches);
        Append(code, MoveLongD0ToPreDecrementA7); // new plane

        // Pull only the new resources; the old topology remains on the stack
        // and the result pointer is recovered from its known displacement.
        Append(code, MoveLongA7PostIncrementToD0); // new plane
        Append(code, MoveAddressD0ToA1);
        Append(code, MoveLongA1ToD0);
        Append(code, MoveAddressD0ToA2); // preserve new plane across publisher setup
        Append(code, MoveLongA7PostIncrementToD0); // replacement table
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA7DisplacementToD0);
        Append(code, checked((ushort)((4 + nestedDepth) * 4)));
        Append(code, MoveAddressD0ToA3); // persistent result marker

        // Copy the lower-depth planes and the newly allocated plane into the
        // replacement table, then publish depth seven/eight through the same
        // preflighting publisher used by the earlier owners.
        Append(code, MoveAddressA4ToA0);
        for (var plane = 0; plane < nestedDepth; plane++)
        {
            Append(code, MoveLongA3DisplacementToD0);
            Append(code, checked((ushort)(GraphicsLayouts.ScreenPrefixExecResultPlane0 + (plane * 4))));
            Append(code, MoveLongD0ToA0PostIncrement);
        }
        Append(code, MoveAddressA2ToA1);
        Append(code, MoveLongA1ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ScreenPrefixExecResultScreen));
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveAddressA4ToA1);
        Append(code, MoveLongD7ToD2); // bytes per plane for publisher
        Append(code, (ushort)(MoveQuickZeroD0 | requestedDepth));

        // Push stable new-resource/result markers above the old topology
        // before entering the publisher, whose address registers are scratch.
        Append(code, MoveLongA2ToD0);
        Append(code, MoveLongD0ToPreDecrementA7); // new plane
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToPreDecrementA7); // replacement table
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToPreDecrementA7); // result marker
        Append(code, (ushort)(MoveQuickZeroD0 | requestedDepth));
        AppendJsrPcRelative(code, publisherOffset);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, publishFailureBranches);

        // Success: use the stable marker as A0, publish table/new plane and
        // old planes into the extended record, clear unused slots, retire the
        // old table, and discard the lower-depth snapshot.
        Append(code, MoveLongA7PostIncrementToD0); // result marker
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA7PostIncrementToD0); // replacement table
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlaneTable);
        Append(code, MoveLongA7PostIncrementToD0); // new plane
        AppendWriteResultLong(newPlaneResultOffset);
        for (var plane = nestedDepth - 1; plane >= 0; plane--)
        {
            Append(code, MoveLongA7PostIncrementToD0);
            AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlane0 + (plane * 4));
        }
        Append(code, MoveLongA7PostIncrementToD0); // old table
        Append(code, MoveAddressD0ToA1);
        Append(code, MoveLongA7PostIncrementToD0); // RasInfo
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultRasInfo);
        Append(code, MoveLongA7PostIncrementToD0); // View
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultView);
        Append(code, MoveLongA7PostIncrementToD0); // Screen
        AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultScreen);
        Append(code, MoveQuickZeroD0);
        for (var plane = requestedDepth; plane < 8; plane++)
            AppendWriteResultLong(GraphicsLayouts.ScreenPrefixExecResultPlane0 + (plane * 4));
        Append(code, MoveLongA1ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0000);
        Append(code, (ushort)oldTableBytes);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // persistent result marker
        AppendDiscardSnapshotAndOriginalResult();
        Append(code, MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        var publishFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // result marker
        Append(code, MoveLongA7PostIncrementToD0); // replacement table
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0000);
        Append(code, (ushort)newTableBytes);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // new plane
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeOldTopology();
        Append(code, MoveLongA7PostIncrementToD0); // persistent result marker
        Append(code, MoveAddressD0ToA0);
        AppendRestoreSnapshot();
        Append(code, MoveLongA7PostIncrementToD0); // original result marker
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var planeFailureOffset = code.Count;
        AppendFreeFixed(newTableBytes);
        AppendFreeOldTopology();
        Append(code, MoveLongA7PostIncrementToD0); // persistent result marker
        Append(code, MoveAddressD0ToA0);
        AppendRestoreSnapshot();
        Append(code, MoveLongA7PostIncrementToD0); // original result marker
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var tableFailureOffset = code.Count;
        AppendFreeOldTopology();
        Append(code, MoveLongA7PostIncrementToD0); // persistent result marker
        Append(code, MoveAddressD0ToA0);
        AppendRestoreSnapshot();
        Append(code, MoveLongA7PostIncrementToD0); // original result marker
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var prefixFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // nested result marker
        Append(code, MoveLongA7PostIncrementToD0); // bytes
        AppendRestoreSnapshot();
        Append(code, MoveLongA7PostIncrementToD0); // original result marker
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var validationFailureOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        foreach (var branch in publishFailureBranches)
            PatchBranch(code, branch, publishFailureOffset);
        foreach (var branch in planeFailureBranches)
            PatchBranch(code, branch, planeFailureOffset);
        foreach (var branch in tableFailureBranches)
            PatchBranch(code, branch, tableFailureOffset);
        foreach (var branch in prefixFailureBranches)
            PatchBranch(code, branch, prefixFailureOffset);
        foreach (var branch in validationBranches)
            PatchBranch(code, branch, validationFailureOffset);

        return offset;
    }

    /// <summary>
    /// Emits the bounded native depth-four Screen-prefix allocator. It
    /// composes the depth-three allocator, replaces its table with a
    /// sixteen-byte table containing the existing three planes plus a newly
    /// allocated fourth plane, and frees the old table only after depth-four
    /// publication succeeds. ABI: A6=ExecBase, D0/D1=width/height,
    /// D2=bytes per plane, D3=4; success returns Screen, View, RasInfo,
    /// table, and planes zero through three in D0..D7.
    /// </summary>
    private static int AppendAllocateScreenPrefixMultiPlaneDepth4Exec(
        List<byte> code,
        int depth3AllocatorOffset,
        int publisherOffset)
    {
        var offset = code.Count;
        var validationBranches = new List<int>(1);
        var prefixFailureBranches = new List<int>(1);
        var tableFailureBranches = new List<int>(1);
        var planeFailureBranches = new List<int>(1);
        var publishFailureBranches = new List<int>(1);

        void AppendBranch(ushort opcode, List<int> branches)
        {
            Append(code, opcode);
            branches.Add(code.Count);
            Append(code, 0);
        }

        void AppendAllocFixed(int byteCount, uint flags, List<int> failureBranches)
        {
            Append(code, MoveLongImmediateD0);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)(flags >> 16));
            Append(code, (ushort)flags);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
            Append(code, TestLongD0);
            AppendBranch(BranchEqualWord, failureBranches);
            Append(code, MoveLongD0ToPreDecrementA7);
        }

        void AppendFreeFixed(int byteCount)
        {
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            AppendExecFreeMemFromD0D1PreservingA1(code);
        }

        Append(code, CompareImmediateLongD3);
        Append(code, 0x0000);
        Append(code, 0x0004);
        AppendBranch(BranchNotEqualWord, validationBranches);

        // Save the caller's depth/size while invoking the verified depth-three
        // owner with its fixed depth input.
        Append(code, MoveLongD3ToPreDecrementA7);
        Append(code, MoveLongD2ToPreDecrementA7);
        Append(code, MoveQuickThreeD3);
        AppendJsrPcRelative(code, depth3AllocatorOffset);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, prefixFailureBranches);
        Append(code, MoveLongA7PostIncrementToD7); // bytes per plane
        Append(code, MoveAddressD0ToA0); // retain Screen while discarding depth
        Append(code, MoveLongA7PostIncrementToD0); // requested depth
        Append(code, MoveLongA0ToD0); // restore Screen

        // Depth-three success returns D0..D6 as Screen/View/RasInfo/table/
        // plane zero/plane one/plane two. Keep all seven blocks while the
        // replacement table and fourth plane are acquired.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongD2ToPreDecrementA7);
        Append(code, MoveLongD3ToPreDecrementA7);
        Append(code, MoveLongD4ToPreDecrementA7);
        Append(code, MoveLongD5ToPreDecrementA7);
        Append(code, MoveLongD6ToPreDecrementA7);

        AppendAllocFixed(16, 0x0001_0001u, tableFailureBranches);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0003); // PUBLIC | CHIP | CLEAR
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, planeFailureBranches);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD7ToPreDecrementA7); // dynamic size for rollback

        // Recover the replacement resources and the old depth-three topology.
        // A4 keeps the replacement table and A5 the Screen while the public
        // table is filled. A0/A1 temporarily retain View/RasInfo so the old
        // table can be pushed into the rollback frame before D2 is reused.
        Append(code, MoveLongA7PostIncrementToD7); // bytes per plane
        Append(code, MoveLongA7PostIncrementToD6); // plane three
        Append(code, MoveLongA7PostIncrementToD0); // replacement table
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA7PostIncrementToD5); // plane two
        Append(code, MoveLongA7PostIncrementToD4); // plane one
        Append(code, MoveLongA7PostIncrementToD3); // plane zero
        Append(code, MoveLongA7PostIncrementToD2); // old table
        Append(code, MoveLongA7PostIncrementToD1); // RasInfo
        Append(code, MoveLongA7PostIncrementToD0); // View
        Append(code, MoveAddressD0ToA0); // View
        Append(code, MoveAddressD1ToA1); // RasInfo
        Append(code, MoveLongA7PostIncrementToD0); // Screen
        Append(code, MoveAddressD0ToA5); // retain Screen

        // Rollback frame order is Screen, View, old table, RasInfo, planes
        // zero through two, replacement table, plane three, byte size.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA0ToD1); // View
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongD2ToPreDecrementA7); // old table
        Append(code, MoveLongA1ToD2); // RasInfo
        Append(code, MoveLongD2ToPreDecrementA7);
        Append(code, MoveLongD3ToPreDecrementA7);
        Append(code, MoveLongD4ToPreDecrementA7);
        Append(code, MoveLongD5ToPreDecrementA7);
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD6ToPreDecrementA7);
        Append(code, MoveLongD7ToPreDecrementA7);

        // Fill and publish the replacement table only after all four planes
        // exist. The publisher preflights every pointer before any public
        // link changes.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongD3ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveAddressA5ToA0); // Screen
        Append(code, MoveAddressA4ToA1); // replacement table
        Append(code, MoveQuickFourD0);
        AppendJsrPcRelative(code, publisherOffset);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, publishFailureBranches);

        // Success: release the obsolete depth-three table and return the new
        // table plus all four planes in D0..D7.
        Append(code, MoveLongA7PostIncrementToD7); // size discard
        Append(code, MoveLongA7PostIncrementToD7); // plane three
        Append(code, MoveLongA7PostIncrementToD3); // replacement table
        Append(code, MoveLongA7PostIncrementToD6); // plane two
        Append(code, MoveLongA7PostIncrementToD5); // plane one
        Append(code, MoveLongA7PostIncrementToD4); // plane zero
        Append(code, MoveLongA7PostIncrementToD2); // RasInfo
        Append(code, MoveLongA7PostIncrementToD0); // old table
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0000);
        Append(code, 0x000C);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD1); // View
        Append(code, MoveLongA7PostIncrementToD0); // Screen
        Append(code, ReturnFromSubroutine);

        var publishFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD7); // bytes per plane
        Append(code, MoveLongA7PostIncrementToD0); // plane three
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(16); // replacement table
        Append(code, MoveLongA7PostIncrementToD0); // plane two
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane one
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(GraphicsLayouts.RasInfoSize);
        AppendFreeFixed(12); // old depth-three table
        AppendFreeFixed(GraphicsLayouts.ViewSize);
        AppendFreeFixed(GraphicsLayouts.ScreenSize);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var planeFailureOffset = code.Count;
        AppendFreeFixed(16); // replacement table
        Append(code, MoveLongA7PostIncrementToD0); // plane two
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane one
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(GraphicsLayouts.RasInfoSize);
        AppendFreeFixed(12); // old depth-three table
        AppendFreeFixed(GraphicsLayouts.ViewSize);
        AppendFreeFixed(GraphicsLayouts.ScreenSize);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var tableFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // plane two
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane one
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(GraphicsLayouts.RasInfoSize);
        AppendFreeFixed(12); // old depth-three table
        AppendFreeFixed(GraphicsLayouts.ViewSize);
        AppendFreeFixed(GraphicsLayouts.ScreenSize);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var prefixFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // bytes discard
        Append(code, MoveLongA7PostIncrementToD0); // depth discard
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var validationFailureOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        foreach (var branch in publishFailureBranches)
            PatchBranch(code, branch, publishFailureOffset);
        foreach (var branch in planeFailureBranches)
            PatchBranch(code, branch, planeFailureOffset);
        foreach (var branch in tableFailureBranches)
            PatchBranch(code, branch, tableFailureOffset);
        foreach (var branch in prefixFailureBranches)
            PatchBranch(code, branch, prefixFailureOffset);
        foreach (var branch in validationBranches)
            PatchBranch(code, branch, validationFailureOffset);

        return offset;
    }

    /// <summary>
    /// Emits the bounded native depth-three Screen-prefix allocator. It
    /// composes the depth-two allocator, replaces its table with a twelve-byte
    /// table containing the existing two planes plus a newly allocated third
    /// plane, and frees the old table only after the depth-three publication
    /// succeeds. ABI: A6=ExecBase, D0/D1=width/height, D2=bytes per plane,
    /// D3=3; success returns Screen, View, RasInfo, table, plane zero, plane
    /// one, and plane two in D0..D6.
    /// </summary>
    private static int AppendAllocateScreenPrefixMultiPlaneDepth3Exec(
        List<byte> code,
        int depth2AllocatorOffset,
        int publisherOffset)
    {
        var offset = code.Count;
        var validationBranches = new List<int>(1);
        var prefixFailureBranches = new List<int>(1);
        var tableFailureBranches = new List<int>(1);
        var planeFailureBranches = new List<int>(1);
        var publishFailureBranches = new List<int>(1);

        void AppendBranch(ushort opcode, List<int> branches)
        {
            Append(code, opcode);
            branches.Add(code.Count);
            Append(code, 0);
        }

        void AppendAllocFixed(int byteCount, uint flags, List<int> failureBranches)
        {
            Append(code, MoveLongImmediateD0);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)(flags >> 16));
            Append(code, (ushort)flags);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
            Append(code, TestLongD0);
            AppendBranch(BranchEqualWord, failureBranches);
            Append(code, MoveLongD0ToPreDecrementA7);
        }

        void AppendFreeFixed(int byteCount)
        {
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            AppendExecFreeMemFromD0D1PreservingA1(code);
        }

        Append(code, CompareImmediateLongD3);
        Append(code, 0x0000);
        Append(code, 0x0003);
        AppendBranch(BranchNotEqualWord, validationBranches);

        // Save the caller's depth/size while invoking the already verified
        // depth-two owner with its fixed depth input.
        Append(code, MoveLongD3ToPreDecrementA7);
        Append(code, MoveLongD2ToPreDecrementA7);
        Append(code, MoveQuickTwoD3);
        AppendJsrPcRelative(code, depth2AllocatorOffset);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, prefixFailureBranches);
        Append(code, MoveLongA7PostIncrementToD7); // bytes per plane
        Append(code, MoveLongA7PostIncrementToD6); // requested depth

        // Depth-two success returns D0..D5 as Screen/View/RasInfo/old table/
        // plane zero/plane one. Keep all six blocks until the replacement
        // table and third plane have been published.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongD2ToPreDecrementA7);
        Append(code, MoveLongD3ToPreDecrementA7);
        Append(code, MoveLongD4ToPreDecrementA7);
        Append(code, MoveLongD5ToPreDecrementA7);

        AppendAllocFixed(12, 0x0001_0001u, tableFailureBranches);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0003); // PUBLIC | CHIP | CLEAR
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, planeFailureBranches);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD7ToPreDecrementA7); // dynamic size for rollback

        // Recover the new resources and the old depth-two topology, retaining
        // the new table in A4 while the public table is populated.
        Append(code, MoveLongA7PostIncrementToD7); // bytes per plane
        Append(code, MoveLongA7PostIncrementToD6); // plane two
        Append(code, MoveLongA7PostIncrementToD0); // new table
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA7PostIncrementToD5); // plane one
        Append(code, MoveLongA7PostIncrementToD4); // plane zero
        Append(code, MoveLongA7PostIncrementToD3); // old table
        Append(code, MoveLongA7PostIncrementToD2); // RasInfo
        Append(code, MoveLongA7PostIncrementToD1); // View
        Append(code, MoveLongA7PostIncrementToD0); // Screen
        Append(code, MoveAddressD0ToA5); // retain Screen while D0 fills table

        // Rollback frame: Screen, View, RasInfo, old table, plane zero,
        // plane one, new table, plane two, bytes-per-plane.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongD2ToPreDecrementA7);
        Append(code, MoveLongD3ToPreDecrementA7);
        Append(code, MoveLongD4ToPreDecrementA7);
        Append(code, MoveLongD5ToPreDecrementA7);
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD6ToPreDecrementA7);
        Append(code, MoveLongD7ToPreDecrementA7);

        // Fill the replacement table and publish depth three only after the
        // complete topology exists.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveAddressA5ToA0); // Screen
        Append(code, MoveAddressA4ToA1); // replacement table
        Append(code, MoveQuickThreeD0);
        AppendJsrPcRelative(code, publisherOffset);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, publishFailureBranches);

        // Success: release the obsolete depth-two table and return the new
        // table plus all three planes in D0..D6.
        Append(code, MoveLongA7PostIncrementToD7); // size discard
        Append(code, MoveLongA7PostIncrementToD6); // plane two
        Append(code, MoveLongA7PostIncrementToD3); // new table
        Append(code, MoveLongA7PostIncrementToD5); // plane one
        Append(code, MoveLongA7PostIncrementToD4); // plane zero
        Append(code, MoveLongA7PostIncrementToD0); // old table
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0000);
        Append(code, 0x0008);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD2); // RasInfo
        Append(code, MoveLongA7PostIncrementToD1); // View
        Append(code, MoveLongA7PostIncrementToD0); // Screen
        Append(code, ReturnFromSubroutine);

        var publishFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD7); // bytes per plane
        Append(code, MoveLongA7PostIncrementToD0); // plane two
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(12); // replacement table
        Append(code, MoveLongA7PostIncrementToD0); // plane one
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(8); // old depth-two table
        AppendFreeFixed(GraphicsLayouts.RasInfoSize);
        AppendFreeFixed(GraphicsLayouts.ViewSize);
        AppendFreeFixed(GraphicsLayouts.ScreenSize);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var planeFailureOffset = code.Count;
        AppendFreeFixed(12); // replacement table
        Append(code, MoveLongA7PostIncrementToD0); // plane one
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(8); // old depth-two table
        AppendFreeFixed(GraphicsLayouts.RasInfoSize);
        AppendFreeFixed(GraphicsLayouts.ViewSize);
        AppendFreeFixed(GraphicsLayouts.ScreenSize);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var tableFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // plane one
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeFixed(8); // old depth-two table
        AppendFreeFixed(GraphicsLayouts.RasInfoSize);
        AppendFreeFixed(GraphicsLayouts.ViewSize);
        AppendFreeFixed(GraphicsLayouts.ScreenSize);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var prefixFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // bytes discard
        Append(code, MoveLongA7PostIncrementToD0); // depth discard
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var validationFailureOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        foreach (var branch in publishFailureBranches)
            PatchBranch(code, branch, publishFailureOffset);
        foreach (var branch in planeFailureBranches)
            PatchBranch(code, branch, planeFailureOffset);
        foreach (var branch in tableFailureBranches)
            PatchBranch(code, branch, tableFailureOffset);
        foreach (var branch in prefixFailureBranches)
            PatchBranch(code, branch, prefixFailureOffset);
        foreach (var branch in validationBranches)
            PatchBranch(code, branch, validationFailureOffset);

        return offset;
    }

    /// <summary>
    /// Emits the paired native teardown for the Exec-backed display bundle.
    /// The private ABI carries every allocation pointer and both dynamic
    /// sizes explicitly, so the body never guesses a provider-owned extent.
    /// It first validates the marker and classic View/CopList/CprList
    /// topology, then clears the links and frees SHF, LOF, CopList, raw
    /// copper, plane, RasInfo, View, and Screen in reverse order.
    /// </summary>
    private static int AppendTeardownDisplayResourcesExec(List<byte> code)
    {
        var offset = code.Count;
        var failureBranches = new List<int>(64);

        void BranchToFailure(ushort opcode)
        {
            Append(code, opcode);
            failureBranches.Add(code.Count);
            Append(code, 0);
        }

        void CheckAddress(ushort selectAddress, uint maximumAddress)
        {
            Append(code, selectAddress);
            Append(code, MoveLongA0ToD6);
            Append(code, TestLongD6);
            BranchToFailure(BranchEqualWord);
            Append(code, BitTestImmediateD6);
            Append(code, 0);
            BranchToFailure(BranchNotEqualWord);
            Append(code, CompareImmediateLongD6);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            BranchToFailure(BranchHighWord);
        }

        void CheckDynamicSpan(ushort pointerToA0)
        {
            // With a non-zero size, end <= start can only be a 32-bit wrap.
            Append(code, pointerToA0);
            Append(code, MoveLongA0ToD6);
            Append(code, MoveLongD6ToD0);
            Append(code, AddLongD2ToD6);
            Append(code, CompareLongD6ToD0);
            BranchToFailure(BranchHighWord);
        }

        // Save all incoming values below the return address. Validation may
        // freely use D0..D7/A0 as scratch; success restores the ABI from this
        // frame before issuing any Exec call, while failure discards it.
        Append(code, MoveLongD0ToPreDecrementA7); // SHF CprList
        Append(code, MoveLongD1ToPreDecrementA7); // raw copper
        Append(code, MoveLongD2ToPreDecrementA7); // plane bytes
        Append(code, MoveLongD3ToPreDecrementA7); // raw bytes
        Append(code, MoveLongD4ToPreDecrementA7); // marker
        Append(code, MoveLongA5ToD6);
        Append(code, MoveLongD6ToPreDecrementA7); // LOF CprList
        Append(code, MoveLongA4ToD6);
        Append(code, MoveLongD6ToPreDecrementA7); // CopList
        Append(code, MoveLongA3ToD6);
        Append(code, MoveLongD6ToPreDecrementA7); // plane
        Append(code, MoveLongA2ToD6);
        Append(code, MoveLongD6ToPreDecrementA7); // RasInfo
        Append(code, MoveLongA1ToD6);
        Append(code, MoveLongD6ToPreDecrementA7); // View
        Append(code, MoveLongA0ToPreDecrementA7); // Screen

        // Preserve the two pointer values that are not in address registers
        // after the dynamic checks. D7 remains the Screen identity and D5
        // remains the SHF CprList identity for the topology pass.
        Append(code, MoveLongA0ToD7);
        Append(code, MoveLongD0ToD5);

        CheckAddress(MoveAddressA0ToA0, 0xFFFF_FEA6u); // ScreenSize
        CheckAddress(MoveAddressA1ToA0, 0xFFFF_FFEEu); // ViewSize
        CheckAddress(MoveAddressA2ToA0, 0xFFFF_FFF4u); // RasInfoSize
        CheckAddress(MoveAddressA3ToA0, 0xFFFF_FFFEu); // plane envelope
        CheckAddress(MoveAddressA4ToA0, 0xFFFF_FFCAu); // CopListSize
        CheckAddress(MoveAddressA5ToA0, 0xFFFF_FFF4u); // LOF CprListSize

        // D0=SHF and D1=raw are not address registers, so check them through
        // D6 without changing the original values used below.
        Append(code, MoveLongD0ToD6);
        Append(code, TestLongD6);
        BranchToFailure(BranchEqualWord);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        BranchToFailure(BranchNotEqualWord);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4);
        BranchToFailure(BranchHighWord);
        Append(code, MoveLongD1ToD6);
        Append(code, TestLongD6);
        BranchToFailure(BranchEqualWord);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        BranchToFailure(BranchNotEqualWord);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE);
        BranchToFailure(BranchHighWord);

        // Dynamic extents are explicit ABI inputs. Keep them bounded and
        // reject both odd sizes and address wrap before reading raw memory.
        Append(code, TestLongD2);
        BranchToFailure(BranchEqualWord);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        BranchToFailure(BranchNotEqualWord);
        Append(code, CompareImmediateLongD2);
        Append(code, 0x00FF);
        Append(code, 0xFFFC);
        BranchToFailure(BranchHighWord);
        Append(code, TestLongD3);
        BranchToFailure(BranchEqualWord);
        Append(code, BitTestImmediateD3);
        Append(code, 0);
        BranchToFailure(BranchNotEqualWord);
        Append(code, CompareImmediateLongD3);
        Append(code, 0x00FF);
        Append(code, 0xFFFC);
        BranchToFailure(BranchHighWord);
        CheckDynamicSpan(MoveAddressA3ToA0);
        // The raw pointer is D1; use D6/D0 for the same wrap test.
        Append(code, MoveLongD1ToD6);
        Append(code, MoveLongD6ToD0);
        Append(code, AddLongD3ToD6);
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchHighWord);

        Append(code, CompareImmediateWordD4);
        Append(code, NativeDisplayResourceMarker);
        BranchToFailure(BranchNotEqualWord);

        // View -> embedded ViewPort, and View -> the two CprList wrappers.
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongImmediateD6);
        Append(code, 0x0000);
        Append(code, checked((ushort)GraphicsLayouts.ScreenViewPort));
        Append(code, AddLongD6ToD0);
        Append(code, MoveLongA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchNotEqualWord);

        Append(code, MoveLongA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ViewLoFCprList));
        Append(code, MoveLongA5ToD0);
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchNotEqualWord);
        Append(code, MoveLongA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ViewShFCprList));
        Append(code, CompareLongD6ToD5);
        BranchToFailure(BranchNotEqualWord);

        // ViewPort.DspIns and CopList.ViewPort must identify the same CopList.
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        Append(code, MoveLongA4ToD0);
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchNotEqualWord);

        // CopList ownership marker and the four raw-stream aliases.
        Append(code, MoveLongA4DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListSystem));
        Append(code, MoveLongD7ToD0);
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchNotEqualWord);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListFlags));
        Append(code, CompareImmediateWordD6);
        Append(code, NativeDisplayResourceMarker);
        BranchToFailure(BranchNotEqualWord);

        foreach (var fieldOffset in new[]
        {
            GraphicsLayouts.CopListCopIns,
            GraphicsLayouts.CopListCopPtr,
            GraphicsLayouts.CopListCopLStart,
            GraphicsLayouts.CopListCopSStart
        })
        {
            Append(code, MoveLongA4DisplacementToD6);
            Append(code, checked((ushort)fieldOffset));
            Append(code, CompareLongD6ToD1);
            BranchToFailure(BranchNotEqualWord);
        }
        Append(code, MoveLongA4DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListNext));
        Append(code, TestLongD6);
        BranchToFailure(BranchNotEqualWord);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, CompareImmediateWordD6);
        Append(code, 0x0002);
        BranchToFailure(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD6);
        Append(code, 0x0002);
        BranchToFailure(BranchNotEqualWord);

        // Both CprList wrappers must be the sole links to the raw stream.
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CprListNext));
        Append(code, TestLongD6);
        BranchToFailure(BranchNotEqualWord);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CprListStart));
        Append(code, CompareLongD6ToD1);
        BranchToFailure(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        Append(code, CompareImmediateWordD6);
        Append(code, 0x0002);
        BranchToFailure(BranchNotEqualWord);
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CprListNext));
        Append(code, TestLongD6);
        BranchToFailure(BranchNotEqualWord);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CprListStart));
        Append(code, CompareLongD6ToD1);
        BranchToFailure(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        Append(code, CompareImmediateWordD6);
        Append(code, 0x0002);
        BranchToFailure(BranchNotEqualWord);

        // The embedded ViewPort/RasInfo/BitMap identity is part of the
        // Screen-prefix ownership envelope initialized by the allocator.
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, MoveLongA2ToD1);
        Append(code, CompareLongD6ToD1);
        BranchToFailure(BranchNotEqualWord);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongImmediateD6);
        Append(code, 0x0000);
        Append(code, checked((ushort)GraphicsLayouts.ScreenBitMap));
        Append(code, AddLongD6ToD0);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoBitMap));
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchNotEqualWord);

        // Restore the saved ABI values into a stable free/clear frame.
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA1); // Screen
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0); // View
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongD0ToD7); // RasInfo
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongD0ToD6); // plane
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA4); // CopList
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA5); // LOF CprList
        Append(code, MoveLongA7PostIncrementToD0); // marker
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongD0ToD4); // raw bytes
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongD0ToD5); // plane bytes
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA3); // raw copper
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA2); // SHF CprList

        // D2/D3 are callee-preserved across Exec and carry the last two
        // public envelopes after A0/A1 are consumed by FreeMem.
        Append(code, MoveLongA0ToD2); // View
        Append(code, MoveLongA1ToD3); // Screen

        // Clear the public links before releasing any block.
        Append(code, MoveQuickZeroD0);
        foreach (var fieldOffset in new[]
        {
            GraphicsLayouts.ViewViewPort,
            GraphicsLayouts.ViewLoFCprList,
            GraphicsLayouts.ViewShFCprList
        })
        {
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, checked((ushort)fieldOffset));
        }
        Append(code, MoveAddressA4ToA0);
        foreach (var fieldOffset in new[]
        {
            GraphicsLayouts.CopListSystem,
            GraphicsLayouts.CopListViewPort,
            GraphicsLayouts.CopListCopIns,
            GraphicsLayouts.CopListCopPtr,
            GraphicsLayouts.CopListCopLStart,
            GraphicsLayouts.CopListCopSStart
        })
        {
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, checked((ushort)fieldOffset));
        }
        foreach (var fieldOffset in new[]
        {
            GraphicsLayouts.CopListCount,
            GraphicsLayouts.CopListMaxCount,
            GraphicsLayouts.CopListFlags
        })
        {
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, checked((ushort)fieldOffset));
        }
        foreach (var cprAddress in new[]
        {
            MoveAddressA5ToA0,
            MoveAddressA2ToA0
        })
        {
            Append(code, cprAddress);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, checked((ushort)GraphicsLayouts.CprListNext));
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, checked((ushort)GraphicsLayouts.CprListStart));
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        }

        void AppendFreeFromAddress(ushort addressToD0, int byteCount)
        {
            Append(code, addressToD0);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            AppendExecFreeMemFromD0D1PreservingA1(code);
        }

        // Retire wrappers before raw data. Exec preserves A2-A6/D2-D7, which
        // keeps all remaining pointers/sizes live across each FreeMem call.
        AppendFreeFromAddress(MoveLongA2ToD0, GraphicsLayouts.CprListSize); // SHF
        AppendFreeFromAddress(MoveLongA5ToD0, GraphicsLayouts.CprListSize); // LOF
        AppendFreeFromAddress(MoveLongA4ToD0, GraphicsLayouts.CopListSize); // CopList
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD4ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code); // raw
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD5ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code); // plane
        AppendFreeFromAddress(MoveLongD7ToD0, GraphicsLayouts.RasInfoSize);
        AppendFreeFromAddress(MoveLongD2ToD0, GraphicsLayouts.ViewSize);
        AppendFreeFromAddress(MoveLongD3ToD0, GraphicsLayouts.ScreenSize);
        Append(code, MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        var failureOffset = code.Count;
        for (var index = 0; index < 11; index++)
            Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        foreach (var branchExtensionOffset in failureBranches)
            PatchBranch(code, branchExtensionOffset, failureOffset);
        return offset;
    }

    private static int AppendGetRgb32(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(20);

        // This native slice owns exactly one RGB32 result entry.  It keeps the
        // public three-LONG destination envelope and nibble expansion, while
        // count>1, allocator/provider ownership, and host rollback remain on
        // the portable/provider path.
        Append(code, MoveLongD0ToD3); // preserve first on every decline
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var countBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(countBranchExtensionOffset);

        Append(code, MoveLongA1ToD2);
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var outputNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(outputNullBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var outputOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(outputOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD2);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4);
        Append(code, BranchHighWord);
        var outputWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(outputWrapBranchExtensionOffset);

        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var mapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(mapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var mapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(mapOddBranchExtensionOffset);

        Append(code, MoveLongD3ToD6);
        Append(code, TestLongD6);
        Append(code, BranchMinusWord);
        var indexNegativeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(indexNegativeBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0);
        Append(code, 0xFFFF);
        Append(code, BranchHighWord);
        var indexWideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(indexWideBranchExtensionOffset);

        Append(code, MoveQuickZeroD1);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapCount));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var mapCountZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(mapCountZeroBranchExtensionOffset);
        Append(code, CompareLongD6ToD1);
        Append(code, BranchLowerOrSameWord);
        var indexRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(indexRangeBranchExtensionOffset);
        Append(code, ShiftLeftLongD6);

        Append(code, MoveLongA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapColorTable));
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var tableNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableNullBranchExtensionOffset);
        Append(code, BitTestImmediateD7);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var tableOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableOddBranchExtensionOffset);
        Append(code, AddLongD6ToD7);
        Append(code, BranchCarryWord);
        var tableWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableWrapBranchExtensionOffset);
        Append(code, MoveAddressD7ToA2);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, 0);

        Append(code, MoveQuickZeroD5);
        Append(code, MoveQuickZeroD7);
        Append(code, MoveByteA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapType));
        Append(code, CompareImmediateWordD7);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var typeZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD7);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var typeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(typeBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapLowColorBits));
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var lowNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowNullBranchExtensionOffset);
        Append(code, BitTestImmediateD7);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var lowOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowOddBranchExtensionOffset);
        Append(code, AddLongD6ToD7);
        Append(code, BranchCarryWord);
        var lowWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowWrapBranchExtensionOffset);
        Append(code, MoveAddressD7ToA3);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordA3DisplacementToD5);
        Append(code, 0);

        var lowReadyOffset = code.Count;

        void AppendExpandD6()
        {
            Append(code, MoveLongD6ToD7);
            for (var byteShift = 0; byteShift < 3; byteShift++)
            {
                for (var bit = 0; bit < 8; bit++)
                    Append(code, ShiftLeftLongD7);
                Append(code, OrLongD7ToD6);
            }
        }

        // Red: high nibble is ColorTable bits 11..8, low nibble is
        // LowColorBits bits 11..8.
        var redOffset = code.Count;
        Append(code, MoveLongD4ToD6);
        Append(code, AndImmediateWordD6);
        Append(code, 0x0F00);
        for (var index = 0; index < 4; index++)
            Append(code, ShiftRightWordD6);
        Append(code, MoveLongD5ToD7);
        Append(code, AndImmediateWordD7);
        Append(code, 0x0F00);
        for (var index = 0; index < 8; index++)
            Append(code, ShiftRightWordD7);
        Append(code, OrLongD7ToD6);
        AppendExpandD6();
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA1Displacement);
        Append(code, 0);

        // Green: high nibble is already in bits 4..7; the low table nibble
        // moves from bits 4..7 down to bits 0..3.
        var greenOffset = code.Count;
        Append(code, MoveLongD4ToD6);
        Append(code, AndImmediateWordD6);
        Append(code, 0x00F0);
        Append(code, MoveLongD5ToD7);
        Append(code, AndImmediateWordD7);
        Append(code, 0x00F0);
        for (var index = 0; index < 4; index++)
            Append(code, ShiftRightWordD7);
        Append(code, OrLongD7ToD6);
        AppendExpandD6();
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA1Displacement);
        Append(code, 4);

        // Blue: both nibbles are low-word bits 3..0; move only the high
        // ColorTable nibble up to the upper half of the byte.
        var blueOffset = code.Count;
        Append(code, MoveLongD4ToD6);
        Append(code, AndImmediateWordD6);
        Append(code, 0x000F);
        for (var index = 0; index < 4; index++)
            Append(code, ShiftLeftLongD6);
        Append(code, MoveLongD5ToD7);
        Append(code, AndImmediateWordD7);
        Append(code, 0x000F);
        Append(code, OrLongD7ToD6);
        AppendExpandD6();
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA1Displacement);
        Append(code, 8);

        var successOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD3ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, typeZeroBranchExtensionOffset, lowReadyOffset);
        _ = redOffset;
        _ = greenOffset;
        _ = blueOffset;
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendSetABPenDrMd(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(3);
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x1F00); // D3-D7, reversed predecrement mask
        // Preserve the complete input tuple for a provider fallback. The
        // native body publishes FgPen/BgPen/DrawMode, all eight minterms,
        // line phase, and Flags as one admitted RastPort transition.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongD2ToPreDecrementA7);
        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullBranch = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullBranch);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBranch = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddBranch);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFD0); // through minterm byte 7 (offset 0x2F)
        Append(code, BranchHighWord);
        var rangeBranch = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rangeBranch);

        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, MoveByteD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, MoveByteD2ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));

        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, MoveByteA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, MoveByteA1DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        AppendRastPortMinterms(code);
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, AndImmediateWordD4);
        Append(code, 0xBFFF); // clear RPF_NO_PENS
        Append(code, MoveWordD4ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x00F8); // after all tuple discards, before the handled result
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD2);
        Append(code, MoveLongA7PostIncrementToD1);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x00F8); // leave the original tuple and prior CCR intact
        Append(code, BranchAlwaysWord);
        var fallbackJump = code.Count;
        Append(code, 0);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        PatchBranch(code, fallbackJump, fallbackEntryOffset);
        return offset;
    }

    private static int AppendGetByte(
        List<byte> code,
        int rastPortOffset,
        int fallbackEntryOffset)
    {
        if ((uint)rastPortOffset > ushort.MaxValue)
            throw new ArgumentOutOfRangeException(nameof(rastPortOffset));

        var offset = code.Count;
        var fallbackBranches = new List<int>(3);
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x0800); // D4, reversed predecrement mask.

        // These V39 getters take A0 and consume one public byte. Preserve the
        // original D0 on malformed-address decline, but do not inspect flags
        // or pen ownership: the portable contract reads the public byte even
        // when a provider has auxiliary colour state.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        var maxAddress = uint.MaxValue - (uint)rastPortOffset;
        Append(code, checked((ushort)(maxAddress >> 16)));
        Append(code, checked((ushort)(maxAddress & ushort.MaxValue)));
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);

        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)rastPortOffset));
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x0010); // Restore public D4 after discarding the saved argument.
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x0010); // Keep the original D0 and prior CCR on decline.
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendMove(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;

        // Cursor motion does not own raster storage or layer clipping, but it
        // does publish four RastPort fields.  Admit the entire public envelope
        // before the first store and preserve the caller coordinates for the
        // portable/provider path on malformed state.
        var fallbackBranches = new List<int>(3);
        Append(code, MoveLongD4ToPreDecrementA7);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFF9C); // RastPortSize (0x64) envelope
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);

        // Move() publishes the new cursor, restarts the line-pattern phase,
        // and marks the next Draw as a fresh segment. Read/modify/write the
        // Flags word so unrelated caller-owned state survives the body.
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentX));
        Append(code, MoveWordD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentY));
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, OrImmediateWordD0);
        Append(code, 1);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveLongA7PostIncrementToD4); // public D4, after both coordinate discards
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD1);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendUCopperListInitNativeOne(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(14);

        // Protect public callee-saved scratch on every native/decline path.
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x0702); // MOVEM.L D5-D7/A6,-(A7), reversed save mask

        // This is the first allocation-bearing public user-copper form.  It
        // intentionally claims exactly one instruction: a caller-owned,
        // even UCopList whose three public links are clear.  The native arm
        // reads ExecBase through the conventional absolute address four,
        // allocates one public CopList and one public CopIns, and publishes
        // the same CopIns/CopPtr/count/max-count fields as CINIT.  Larger or
        // already-owned lists remain with the registry/provider owner.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullUserListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullUserListBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddUserListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddUserListBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // UCopListSize (0x0C) envelope
        Append(code, BranchHighWord);
        var wrappedUserListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedUserListBranchExtensionOffset);

        Append(code, CompareImmediateWordD0);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var countBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(countBranchExtensionOffset);

        // A repeated native init would otherwise orphan the old buffers.
        // Require the caller-owned link envelope to be clear before the
        // first Exec call.
        foreach (var fieldOffset in new[]
        {
            GraphicsLayouts.UCopListNext,
            GraphicsLayouts.UCopListFirstCopList,
            GraphicsLayouts.UCopListCopList
        })
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)fieldOffset));
            Append(code, TestLongD0);
            Append(code, BranchNotEqualWord);
            var fieldBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(fieldBranchExtensionOffset);
        }

        // SysBase is the longword at address four in an Amiga ROM process.
        // The public graphics vector's A6 remains the graphics base until
        // this point; the Exec base is then held in A6 for both calls.
        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddExecBaseBranchExtensionOffset);
        Append(code, MoveAddressD0ToA6);

        Append(code, MoveLongD6ToPreDecrementA7); // user UCopList

        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.CopListSize));
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0001); // PUBLIC | CLEAR
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var copListAllocationFailureBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD0ToPreDecrementA7); // CopList

        // Retain the exact returned block for rollback, and validate its
        // complete logical span before requesting the instruction storage.
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddCopListAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFCA); // last valid even base for 54 bytes
        Append(code, BranchHighWord);
        var wrappedCopListAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.CopInsSize));
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0001); // PUBLIC | CLEAR
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var copInsAllocationFailureBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD0ToPreDecrementA7); // CopIns

        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddCopInsAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFA); // last valid even base for 6 bytes
        Append(code, BranchHighWord);
        var wrappedCopInsAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Remove the temporary ownership frame and retain the three public
        // values in stable registers while the envelopes are initialized.
        Append(code, MoveLongA7PostIncrementToD6); // CopIns
        Append(code, MoveLongA7PostIncrementToD5); // CopList
        Append(code, MoveLongA7PostIncrementToD0); // user list
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveAddressA0ToA1); // A1 keeps user list for marker

        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.UCopListNext));
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.UCopListFirstCopList));
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.UCopListCopList));
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.UCopListFirstCopList));
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.UCopListCopList));

        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopIns));
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, MoveQuickOneD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));

        // Native-owned marker: CopList.System carries the user-list link and
        // CopList.Flags carries a private word marker.  CMove/CWait/CBump do
        // not consume either field; the paired native FreeCopList uses them
        // to prove ownership before issuing Exec FreeMem.
        Append(code, MoveLongA1ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListSystem));
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, NativeUserCopperMarker);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListFlags));

        Append(code, MoveLongD5ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40E0); // MOVEM.L (A7)+,D5-D7/A6
        Append(code, ReturnFromSubroutine);

        var invalidCopInsAllocationOffset = code.Count;
        // Stack: rejected CopIns, valid CopList, caller UCopList. Release
        // both exact allocations without publishing any caller/header links.
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.CopInsSize));
        AppendExecFreeMemFromD0D1PreservingA1(code);

        var copInsAllocationFailureOffset = code.Count;
        // Stack: CopList, user UCopList. Free the first block, discard the
        // caller pointer, and preserve the original D0 for the fallback.
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.CopListSize));
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, BranchAlwaysWord);
        var secondFailureJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var copListAllocationFailureOffset = code.Count;
        // Stack: user UCopList. Discard it before restoring D0.
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, BranchAlwaysWord);
        var firstFailureJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40E0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, oddCopListAllocationBranchExtensionOffset, copInsAllocationFailureOffset);
        PatchBranch(code, wrappedCopListAllocationBranchExtensionOffset, copInsAllocationFailureOffset);
        PatchBranch(code, oddCopInsAllocationBranchExtensionOffset, invalidCopInsAllocationOffset);
        PatchBranch(code, wrappedCopInsAllocationBranchExtensionOffset, invalidCopInsAllocationOffset);
        PatchBranch(code, copInsAllocationFailureBranchExtensionOffset, copInsAllocationFailureOffset);
        PatchBranch(code, copListAllocationFailureBranchExtensionOffset, copListAllocationFailureOffset);
        PatchBranch(code, secondFailureJoinBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, firstFailureJoinBranchExtensionOffset, fallbackRestoreOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendFreeCopListNativeOne(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(30);

        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x0F02); // MOVEM.L D4-D7/A6,-(A7), reversed save mask

        // NULL remains the documented idempotent close.  Non-NULL native
        // ownership is proved by the marker written by the one-slot
        // UCopperListInit arm; foreign, linked, or provider lists decline.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullListBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddListBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFCA); // CopListSize envelope
        Append(code, BranchHighWord);
        var wrappedListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedListBranchExtensionOffset);

        // Preserve the classic read-only empty CopList form.  It has no
        // native ownership marker or buffers to release, so it is a direct
        // successful no-op before the allocation-bearing marker checks.
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopIns));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var emptyListBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListFlags));
        Append(code, CompareImmediateWordD0);
        Append(code, NativeUserCopperMarker);
        Append(code, BranchNotEqualWord);
        var markerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(markerBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.CopListSystem));
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var nullUserListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullUserListBranchExtensionOffset);
        Append(code, BitTestImmediateD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddUserListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddUserListBranchExtensionOffset);
        Append(code, CompareImmediateLongD5);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // UCopListSize envelope
        Append(code, BranchHighWord);
        var wrappedUserListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedUserListBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopIns));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullInstructionsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullInstructionsBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddInstructionsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddInstructionsBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFA); // CopInsSize envelope
        Append(code, BranchHighWord);
        var wrappedInstructionsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedInstructionsBranchExtensionOffset);

        Append(code, MoveAddressD5ToA1);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.UCopListFirstCopList));
        Append(code, CompareLongD4ToD0);
        Append(code, BranchNotEqualWord);
        var firstLinkBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(firstLinkBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.UCopListCopList));
        Append(code, CompareLongD4ToD0);
        Append(code, BranchNotEqualWord);
        var secondLinkBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondLinkBranchExtensionOffset);

        // Recover SysBase through address four only after every guest
        // envelope and ownership marker has passed.
        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddExecBaseBranchExtensionOffset);
        Append(code, MoveAddressD0ToA6);

        // Save CopList, user UCopList, and CopIns; the top item is freed
        // first, then the caller's three links are cleared, then CopList.
        Append(code, MoveLongD4ToPreDecrementA7);
        Append(code, MoveLongD5ToPreDecrementA7);
        Append(code, MoveLongD6ToPreDecrementA7);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.CopInsSize));
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.UCopListNext));
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.UCopListFirstCopList));
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.UCopListCopList));
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.CopListSize));
        AppendExecFreeMemFromD0D1PreservingA1(code);

        var successOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40F0); // MOVEM.L (A7)+,D4-D7/A6
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, nullListBranchExtensionOffset, successOffset);
        PatchBranch(code, emptyListBranchExtensionOffset, successOffset);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40F0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendUserCopperInstruction(
        List<byte> code,
        int fallbackEntryOffset,
        bool waitInstruction)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(20);

        // Claim only the allocation-free one-slot user-copper form.  The
        // public envelope is deliberately stricter than the portable owner:
        // UCopList must point at one complete CopList, that list must expose
        // one CopIns slot with Count==0/MaxCount==1, CopPtr must still equal
        // CopIns, and no successor may be linked.  Rollover, caller-owned
        // multi-slot lists, and registry/provider-owned chains remain on the
        // complete CMove/CWait implementation.
        Append(code, MoveLongD0ToD7); // preserve D0 for every decline
        Append(code, MoveLongD1ToD6); // preserve D1 for every decline

        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var userListNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(userListNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var userListOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(userListOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // UCopListSize (0x0C) envelope
        Append(code, BranchHighWord);
        var userListWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(userListWrapBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.UCopListCopList));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var copListNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copListNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var copListOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copListOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFCA); // CopListSize (0x36) envelope
        Append(code, BranchHighWord);
        var copListWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copListWrapBranchExtensionOffset);
        Append(code, MoveAddressD0ToA2);

        Append(code, MoveLongA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopIns));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var copInsNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copInsNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var copInsOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copInsOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFA); // CopInsSize (0x06) envelope
        Append(code, BranchHighWord);
        var copInsWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copInsWrapBranchExtensionOffset);

        // CopPtr must still designate the first and only instruction slot.
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var copPtrNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copPtrNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var copPtrOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copPtrOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFFA);
        Append(code, BranchHighWord);
        var copPtrWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copPtrWrapBranchExtensionOffset);
        Append(code, MoveLongD4ToD5);
        Append(code, CompareLongD5ToD1);
        Append(code, BranchNotEqualWord);
        var copPtrMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copPtrMismatchBranchExtensionOffset);

        Append(code, MoveWordA2DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, TestWordD2);
        Append(code, BranchNotEqualWord);
        var copCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copCountBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD3);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var copCapacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copCapacityBranchExtensionOffset);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListNext));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var copNextBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copNextBranchExtensionOffset);

        // A0 now addresses the six-byte CopIns record.  CMove/CWait write
        // the pseudo-opcode and both argument words but deliberately leave
        // pointer/count advancement to the separate CBump macro/vector.
        Append(code, MoveAddressD4ToA0);
        Append(code, waitInstruction ? MoveQuickOneD0 : MoveQuickZeroD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopInsOpCode));
        if (waitInstruction)
        {
            Append(code, MoveLongD7ToD0);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, checked((ushort)GraphicsLayouts.CopInsArg0));
            Append(code, MoveLongD6ToD0);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, checked((ushort)GraphicsLayouts.CopInsArg1));
        }
        else
        {
            Append(code, MoveLongD7ToD0);
            Append(code, AndImmediateWordD0);
            Append(code, 0x01FE);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, checked((ushort)GraphicsLayouts.CopInsArg0));
            Append(code, MoveLongD6ToD0);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, checked((ushort)GraphicsLayouts.CopInsArg1));
        }

        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongD6ToD1);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendUserCopperBumpOneSlot(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(20);

        // Claim only the first CBump transition of a resident one-slot
        // block.  The complete vector owns rollover, allocation, linked
        // blocks, and registry/provider state after this transition.
        Append(code, MoveLongD0ToD7); // preserve D0 for every decline
        Append(code, MoveLongD1ToD6); // preserve D1 for every decline

        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var userListNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(userListNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var userListOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(userListOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // UCopListSize (0x0C) envelope
        Append(code, BranchHighWord);
        var userListWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(userListWrapBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.UCopListCopList));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var copListNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copListNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var copListOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copListOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFCA); // CopListSize (0x36) envelope
        Append(code, BranchHighWord);
        var copListWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copListWrapBranchExtensionOffset);
        Append(code, MoveAddressD0ToA2);

        // CopIns must leave room for the six-byte record that CBump makes
        // current.  The stricter FFF4 bound rejects a wrapped +6 pointer.
        Append(code, MoveLongA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopIns));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var copInsNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copInsNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var copInsOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copInsOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4);
        Append(code, BranchHighWord);
        var copInsWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copInsWrapBranchExtensionOffset);

        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var copPtrNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copPtrNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var copPtrOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copPtrOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4);
        Append(code, BranchHighWord);
        var copPtrWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copPtrWrapBranchExtensionOffset);
        Append(code, MoveLongD4ToD5);
        Append(code, CompareLongD5ToD1);
        Append(code, BranchNotEqualWord);
        var copPtrMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copPtrMismatchBranchExtensionOffset);

        Append(code, MoveWordA2DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, TestWordD2);
        Append(code, BranchNotEqualWord);
        var copCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copCountBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD3);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var copCapacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copCapacityBranchExtensionOffset);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListNext));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var copNextBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(copNextBranchExtensionOffset);

        Append(code, AddImmediateLongD1);
        Append(code, 0);
        Append(code, 6);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD1ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        Append(code, MoveQuickOneD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongD6ToD1);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendAreaMove(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(15);
        var pendingFallbackBranches = new List<int>(8);

        // Claim a first MOVE into an empty, caller-initialized AreaInfo and the
        // single pending-MOVE replacement form. Polygon closure and every
        // other non-empty collector remain on the portable/provider
        // transaction so the native body never publishes a partial close.
        Append(code, MoveLongD0ToD6);
        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAreaInfo));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var areaBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(areaBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddAreaBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddAreaBranchExtensionOffset);

        Append(code, MoveAddressD2ToA0);
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoCount));
        Append(code, TestWordD3);
        Append(code, BranchEqualWord);
        var countZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD3);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var pendingDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var unsupportedCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedCountBranchExtensionOffset);
        var countZeroTargetOffset = code.Count;
        PatchBranch(code, countZeroBranchExtensionOffset, countZeroTargetOffset);

        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoMaxCount));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var capacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(capacityBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoVectorPointer));
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var vectorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(vectorBranchExtensionOffset);
        Append(code, BitTestImmediateD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddVectorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddVectorBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFlagPointer));
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var flagBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(flagBranchExtensionOffset);

        // Publish the two WORD coordinates and MOVE flag into the first
        // vector/flag cells. D6 retains the original x argument while D1 is
        // the y argument throughout the body.
        Append(code, MoveLongD5ToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveWordD0ToA0);
        Append(code, MoveWordD1ToA0Displacement);
        Append(code, 2);
        Append(code, MoveLongD5ToD4);
        Append(code, MoveLongD7ToD5);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteD0ToA0);

        // Rebuild A0 as the AreaInfo descriptor and publish the advanced
        // pointers, count, and first point metadata.
        Append(code, AddQuickFourLongD4);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoVectorPointer));
        Append(code, AddQuickOneLongD7);
        Append(code, MoveLongD7ToD5);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFlagPointer));
        Append(code, MoveQuickOneD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoCount));
        Append(code, MoveLongD6ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFirstX));
        Append(code, MoveWordD1ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFirstY));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD6ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        var pendingEntryOffset = code.Count;
        // A single pending AreaMove is replaced in place. The current
        // vector/flag pointers address the slot after the pending marker;
        // only a zero preceding flag is eligible for replacement.
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoMaxCount));
        Append(code, CompareImmediateWordD4);
        Append(code, 1);
        Append(code, BranchLowerOrSameWord);
        var pendingCapacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        pendingFallbackBranches.Add(pendingCapacityBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoVectorPointer));
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var pendingVectorNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        pendingFallbackBranches.Add(pendingVectorNullBranchExtensionOffset);
        Append(code, BitTestImmediateD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var pendingVectorOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        pendingFallbackBranches.Add(pendingVectorOddBranchExtensionOffset);
        Append(code, MoveLongD5ToD4);
        Append(code, CompareImmediateLongD4);
        Append(code, 0);
        Append(code, 3); // vector pointer-minus-four must not underflow
        Append(code, BranchLowerOrSameWord);
        var pendingVectorLowBranchExtensionOffset = code.Count;
        Append(code, 0);
        pendingFallbackBranches.Add(pendingVectorLowBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFlagPointer));
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var pendingFlagNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        pendingFallbackBranches.Add(pendingFlagNullBranchExtensionOffset);

        Append(code, MoveLongD7ToD0);
        Append(code, SubQuickOneLongD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, 0);
        Append(code, AndImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var pendingMarkerBranchExtensionOffset = code.Count;
        Append(code, 0);
        pendingFallbackBranches.Add(pendingMarkerBranchExtensionOffset);

        // Replace the pending coordinate pair and retain the collector count
        // while advancing neither pointer. FirstX/FirstY become the new move.
        Append(code, SubQuickFourLongD5);
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveWordD0ToA0);
        Append(code, MoveWordD1ToA0Displacement);
        Append(code, 2);
        Append(code, SubQuickOneLongD7);
        Append(code, MoveAddressD7ToA0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickFourLongD5);
        Append(code, AddQuickOneLongD7);

        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoVectorPointer));
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFlagPointer));
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoCount));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoCount));
        Append(code, MoveLongD6ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFirstX));
        Append(code, MoveWordD1ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFirstY));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, pendingDispatchBranchExtensionOffset, pendingEntryOffset);
        foreach (var branchExtensionOffset in pendingFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendAreaDraw(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(7);

        // Claim one DRAW append when the existing collector count is one or
        // two. Polygon closure, a third or later chain point, and pending /
        // ellipse state remain on the portable/provider transaction.
        Append(code, MoveLongD0ToD6);
        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAreaInfo));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var areaBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(areaBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddAreaBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddAreaBranchExtensionOffset);

        Append(code, MoveAddressD2ToA0);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoCount));
        Append(code, MoveWordD4ToD3);
        Append(code, CompareImmediateWordD4);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var countOneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var countBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(countBranchExtensionOffset);
        var countAcceptedOffset = code.Count;
        PatchBranch(code, countOneBranchExtensionOffset, countAcceptedOffset);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoMaxCount));
        Append(code, CompareWordD3ToD4);
        Append(code, BranchLowerOrSameWord);
        var capacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(capacityBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoVectorPointer));
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var vectorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(vectorBranchExtensionOffset);
        Append(code, BitTestImmediateD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddVectorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddVectorBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFlagPointer));
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var flagBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(flagBranchExtensionOffset);

        // Append the DRAW point and flag, retaining D4 as the vector pointer
        // scratch while D5 is reused for the flag pointer.
        Append(code, MoveLongD5ToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveWordD0ToA0);
        Append(code, MoveWordD1ToA0Displacement);
        Append(code, 2);
        Append(code, MoveLongD5ToD4);
        Append(code, MoveLongD7ToD5);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveQuickOneD0);
        Append(code, MoveByteD0ToA0);

        // Rebuild A0 as AreaInfo and publish vector/flag advances and count.
        Append(code, AddQuickFourLongD4);
        Append(code, CompareImmediateWordD3);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var secondSegmentBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoVectorPointer));
        Append(code, AddQuickOneLongD7);
        Append(code, MoveLongD7ToD5);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFlagPointer));
        Append(code, MoveQuickTwoD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var secondSegmentOffset = code.Count;
        // The count-two form has already appended its one point above; publish
        // the advanced pointers and the third collector entry here.
        Append(code, AddQuickOneLongD7);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoVectorPointer));
        Append(code, MoveLongD7ToD5);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFlagPointer));
        Append(code, MoveImmediateWordD0);
        Append(code, 3);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, secondSegmentBranchExtensionOffset, secondSegmentOffset);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD6ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendAreaEllipse(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(20);
        var pendingFallbackBranches = new List<int>(12);

        // Claim only an empty, caller-initialized AreaInfo.  This native unit
        // publishes the standard two-vector ellipse representation; pending
        // moves, polygon closure, layered ownership, and collector rollback
        // remain on the portable/provider transaction.
        Append(code, MoveLongD0ToD7); // preserve the classic D0 result ABI
        Append(code, TestWordD2);
        Append(code, BranchMinusWord);
        var radiusXNegativeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(radiusXNegativeBranchExtensionOffset);
        Append(code, BranchEqualWord);
        var radiusXZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(radiusXZeroBranchExtensionOffset);
        Append(code, TestWordD3);
        Append(code, BranchMinusWord);
        var radiusYNegativeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(radiusYNegativeBranchExtensionOffset);
        Append(code, BranchEqualWord);
        var radiusYZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(radiusYZeroBranchExtensionOffset);

        // Standard, unlayered RastPort envelope.
        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var rastPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortWrapBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var layeredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layeredBranchExtensionOffset);

        // Save radius X before D2 is reused for the AreaInfo pointer.
        Append(code, MoveLongD2ToD4);
        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAreaInfo));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var areaNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(areaNullBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var areaOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(areaOddBranchExtensionOffset);
        Append(code, MoveLongD2ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFE8); // AreaInfoSize (0x18) envelope
        Append(code, BranchHighWord);
        var areaWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(areaWrapBranchExtensionOffset);
        Append(code, MoveAddressD2ToA0);

        // Empty collectors and the single pending AreaMove form are claimed;
        // all other non-empty polygon state remains on the owner path.
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoCount));
        Append(code, TestWordD0);
        Append(code, BranchEqualWord);
        var countZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
         Append(code, CompareImmediateWordD0);
         Append(code, 1);
        Append(code, BranchEqualWord);
        var pendingDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var unsupportedCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedCountBranchExtensionOffset);

        var countZeroTargetOffset = code.Count;
        PatchBranch(code, countZeroBranchExtensionOffset, countZeroTargetOffset);

        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoMaxCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 1);
        Append(code, BranchLowerOrSameWord);
        var capacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(capacityBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoVectorPointer));
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var vectorNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(vectorNullBranchExtensionOffset);
        Append(code, BitTestImmediateD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var vectorOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(vectorOddBranchExtensionOffset);
        Append(code, MoveLongD5ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        // The two vectors occupy eight bytes and their advanced public cursor
        // is published afterwards, so that one-past pointer must not wrap.
        Append(code, 0xFFF7);
        Append(code, BranchHighWord);
        var vectorWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(vectorWrapBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFlagPointer));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var flagNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(flagNullBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFD); // two flag bytes occupy two bytes
        Append(code, BranchHighWord);
        var flagWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(flagWrapBranchExtensionOffset);

        // Publish center and radius vectors with the AreaEllipse flag (3).
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveWordD0ToA0);
        Append(code, MoveLongD1ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 2);
        Append(code, AddQuickFourLongD5);
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveWordD0ToA0);
        Append(code, MoveLongD3ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 2);
        Append(code, AddQuickFourLongD5);

        Append(code, MoveAddressD6ToA0);
        Append(code, MoveQuickTwoD0);
        Append(code, AddQuickOneLongD0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickOneLongD6);
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickOneLongD6);

        // Advance the collector and publish its first center point.
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoVectorPointer));
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFlagPointer));
        Append(code, MoveQuickTwoD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoCount));
        Append(code, MoveLongD7ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFirstX));
        Append(code, MoveLongD1ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFirstY));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        var pendingEntryOffset = code.Count;
        // A single pending AreaMove is replaced in place.  The portable
        // implementation's contract is deliberately mirrored here: the
        // existing center vector/flag is retained at pointer-4, the radius
        // vector/flag is appended at the current pointer, and FirstX/FirstY
        // remain the original move coordinates.
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoMaxCount));
         Append(code, CompareImmediateWordD0);
         Append(code, 2);
        Append(code, BranchLowerOrSameWord);
        var pendingCapacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        pendingFallbackBranches.Add(pendingCapacityBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoVectorPointer));
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var pendingVectorNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        pendingFallbackBranches.Add(pendingVectorNullBranchExtensionOffset);
        Append(code, BitTestImmediateD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var pendingVectorOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        pendingFallbackBranches.Add(pendingVectorOddBranchExtensionOffset);
        Append(code, MoveLongD5ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0);
        Append(code, 3); // pointer-4 must remain in the address domain
        Append(code, BranchLowerOrSameWord);
        var pendingVectorLowBranchExtensionOffset = code.Count;
        Append(code, 0);
        pendingFallbackBranches.Add(pendingVectorLowBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFB); // old pointer + 4 must stay below 2^32
        Append(code, BranchHighWord);
        var pendingVectorWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        pendingFallbackBranches.Add(pendingVectorWrapBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFlagPointer));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var pendingFlagNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        pendingFallbackBranches.Add(pendingFlagNullBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE); // old pointer + 1 must stay below 2^32
        Append(code, BranchHighWord);
        var pendingFlagWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        pendingFallbackBranches.Add(pendingFlagWrapBranchExtensionOffset);

        // The byte immediately preceding FlagPointer is the collector marker.
        // Marker 0 is the only native pending AreaMove form; any other marker
        // remains on the portable/provider transaction.
        Append(code, MoveLongD6ToD0);
        Append(code, SubQuickOneLongD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, 0);
        Append(code, AndImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var pendingMarkerBranchExtensionOffset = code.Count;
        Append(code, 0);
        pendingFallbackBranches.Add(pendingMarkerBranchExtensionOffset);

        Append(code, SubQuickFourLongD5);
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveWordD0ToA0);
        Append(code, MoveLongD1ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 2);
        Append(code, AddQuickFourLongD5);
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveWordD0ToA0);
        Append(code, MoveLongD3ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 2);
        Append(code, AddQuickFourLongD5);

        Append(code, SubQuickOneLongD6);
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveQuickTwoD0);
        Append(code, AddQuickOneLongD0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickOneLongD6);
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickOneLongD6);

        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoVectorPointer));
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFlagPointer));
        Append(code, MoveQuickTwoD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, pendingDispatchBranchExtensionOffset, pendingEntryOffset);
        foreach (var branchExtensionOffset in pendingFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendAreaEnd(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(10);

        // An empty AreaInfo is a complete AreaEnd transaction. A non-empty
        // collector is also claimed when the public write mask is zero: the
        // portable contract consumes the geometry and resets only the AreaInfo
        // metadata, without probing bitmap, pattern, pen, or temporary-raster
        // storage. Rendering remains on the portable/provider owner.
        Append(code, MoveLongD0ToD6);
        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD4);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var rastPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortWrapBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var layeredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layeredBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAreaInfo));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var areaBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(areaBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddAreaBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddAreaBranchExtensionOffset);
        Append(code, MoveLongD2ToD4);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFE8); // AreaInfoSize (0x18) envelope
        Append(code, BranchHighWord);
        var areaWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(areaWrapBranchExtensionOffset);
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoCount));
        Append(code, CompareImmediateWordD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var nonEmptyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var nonEmptyTargetOffset = code.Count;
        PatchBranch(code, nonEmptyBranchExtensionOffset, nonEmptyTargetOffset);
        Append(code, MoveByteA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, AndImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, TestWordD0);
        Append(code, BranchNotEqualWord);
        var nonZeroMaskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nonZeroMaskBranchExtensionOffset);

        // Reset the caller-owned collector to its initialized table starts.
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoVectorTable));
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoVectorPointer));
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFlagTable));
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFlagPointer));
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoCount));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFirstX));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.AreaInfoFirstY));
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD6ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendEraseRectDispatch(
        List<byte> code,
        int fallbackEntryOffset,
        int oneRowEntryOffset,
        int multiRowEntryOffset)
    {
        var offset = code.Count;

        // Keep the original one-row body as the first owner. A distinct
        // multi-row target is selected only when the inclusive Y bounds differ.
        // Validate both complete public headers before making that choice so
        // neither body can treat a wrapping guest descriptor as a low-memory
        // alias. D7 holds the caller's complete xMin until either owner runs.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C);
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var bitMapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitMapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var bitMapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD7ToD0);
        Append(code, CompareWordD1ToD3);
        Append(code, BranchEqualWord);
        var oneRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var multiRowBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, oneRowBranchExtensionOffset, oneRowEntryOffset);
        PatchBranch(code, multiRowBranchExtensionOffset, multiRowEntryOffset);
        PatchBranch(code, rastPortNullBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, rastPortOddBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, rastPortRangeBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, bitMapNullBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, bitMapOddBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, bitMapRangeBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendEraseRectMultiRow(
        List<byte> code,
        int fallbackEntryOffset,
        int multiPlaneEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(28);

        // Exact bounded multi-row arm: a byte-aligned eight-, sixteen-,
        // thirty-two-, or sixty-four-pixel span with nonnegative ordered
        // vertical bounds. This is intentionally narrower than the
        // portable EraseRect contract: it gives the native ROM path a
        // complete row/stride transaction without claiming clipping or
        // provider-owned surfaces.
        Append(code, MoveLongD0ToD7); // preserve xMin for fallback
        Append(code, MoveLongD2ToD6);
        Append(code, MoveAddressD6ToA6); // preserve xMax for the planar relay
        Append(code, TestWordD0);
        Append(code, BranchMinusWord);
        var xMinSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMinSignBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchMinusWord); // yMin must be nonnegative
        var yMinSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMinSignBranchExtensionOffset);
        Append(code, TestWordD3);
        Append(code, BranchMinusWord);
        var yMaxSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMaxSignBranchExtensionOffset);
        Append(code, CompareWordD1ToD3);
        Append(code, BranchCarryWord); // reject inverted y bounds
        var yOrderBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yOrderBranchExtensionOffset);
        Append(code, MoveWordD3ToD6);
        Append(code, SubWordD1ToD6);
        Append(code, AddQuickOneWordD6);
        Append(code, TestWordD6);
        Append(code, BranchEqualWord); // reject a 65536-row WORD overflow
        var rowCountOverflowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowCountOverflowBranchExtensionOffset);

        Append(code, MoveWordD2ToD6);
        Append(code, SubWordD0ToD6);
        Append(code, CompareImmediateWordD6);
        Append(code, 7); // exactly eight pixels
        Append(code, BranchEqualWord);
        var widthEightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 15); // exact sixteen-pixel companion
        Append(code, BranchEqualWord);
        var widthSixteenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 31); // exact thirty-two-pixel companion
        Append(code, BranchEqualWord);
        var widthThirtyTwoBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 63); // exact sixty-four-pixel companion
        Append(code, BranchNotEqualWord);
        var widthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthBranchExtensionOffset);
        Append(code, MoveQuickSevenD6);
        Append(code, MoveWordD6ToD2); // byte-count marker: seven extra bytes
        Append(code, BranchAlwaysWord);
        var widthReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var widthEightOffset = code.Count;
        Append(code, MoveQuickZeroD2); // byte-count marker: one byte
        Append(code, BranchAlwaysWord);
        var widthEightReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, widthEightBranchExtensionOffset, widthEightOffset);
        var widthSixteenOffset = code.Count;
        Append(code, MoveQuickOneD2); // byte-count marker: two bytes
        Append(code, BranchAlwaysWord);
        var widthSixteenReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var widthThirtyTwoOffset = code.Count;
        Append(code, MoveQuickTwoD6);
        Append(code, AddQuickOneWordD6);
        Append(code, MoveWordD6ToD2); // byte-count marker: three extra bytes
        Append(code, BranchAlwaysWord);
        var widthThirtyTwoReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var widthReadyOffset = code.Count;
        PatchBranch(code, widthSixteenBranchExtensionOffset, widthSixteenOffset);
        PatchBranch(code, widthThirtyTwoBranchExtensionOffset, widthThirtyTwoOffset);
        PatchBranch(code, widthEightReadyBranchExtensionOffset, widthReadyOffset);
        PatchBranch(code, widthSixteenReadyBranchExtensionOffset, widthReadyOffset);
        PatchBranch(code, widthThirtyTwoReadyBranchExtensionOffset, widthReadyOffset);
        PatchBranch(code, widthReadyBranchExtensionOffset, widthReadyOffset);
        Append(code, MoveWordD0ToD6);
        Append(code, AndImmediateWordD6);
        Append(code, 7);
        Append(code, TestWordD6);
        Append(code, BranchNotEqualWord);
        var xAlignmentBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xAlignmentBranchExtensionOffset);

        // Validate the caller-owned RastPort envelope before any bitmap read.
        Append(code, MoveLongA1ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var rastPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortWrapBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var layeredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layeredBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // bitmap header plus two-byte row span
        Append(code, BranchHighWord);
        var bitmapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapWrapBranchExtensionOffset);
        Append(code, MoveAddressD6ToA0);

        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var depthSkipRelayBranchExtensionOffset = code.Count;
        Append(code, 0);
        var multiPlaneRelayOffset = code.Count;
        Append(code, MoveLongA6ToD0);
        Append(code, MoveLongD0ToD2);
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var multiPlaneRelayBranchExtensionOffset = code.Count;
        Append(code, 0);
        var depthAfterRelayOffset = code.Count;
        PatchBranch(code, depthBranchExtensionOffset, multiPlaneRelayOffset);
        PatchBranch(code, depthSkipRelayBranchExtensionOffset, depthAfterRelayOffset);
        PatchBranch(code, multiPlaneRelayBranchExtensionOffset, multiPlaneEntryOffset);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var rowBytesZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesZeroBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rowBytesOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesOddBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 2); // minimum stride; the selected span is checked below
        Append(code, BranchCarryWord);
        var rowBytesShortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesShortBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD6);
        Append(code, 2);
        Append(code, BranchCarryWord);
        var rowsShortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsShortBranchExtensionOffset);
        Append(code, MoveWordD3ToD5);
        Append(code, CompareWordD5ToD6);
        Append(code, BranchLowerOrSameWord);
        var yMaxRowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMaxRowsBranchExtensionOffset);

        // xMin is byte-aligned; D2 carries the selected byte-count minus one.
        // The range check below derives the final selected byte for each
        // admitted marker (0, 1, 3, or 7).
        Append(code, MoveWordD0ToD6);
        Append(code, ShiftRightWordD6Count3);
        Append(code, AddQuickOneWordD6);
        Append(code, TestWordD2);
        Append(code, BranchEqualWord);
        var xByteEightWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, AddQuickOneWordD6);
        Append(code, CompareImmediateWordD2);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var xByteSixteenWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, AddQuickOneWordD6);
        Append(code, CompareImmediateWordD2);
        Append(code, 3);
        Append(code, BranchEqualWord);
        var xByteThirtyTwoWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, AddQuickOneWordD6);
        Append(code, AddQuickOneWordD6);
        Append(code, AddQuickOneWordD6);
        Append(code, AddQuickOneWordD6);
        var xByteRangeOffset = code.Count;
        PatchBranch(code, xByteEightWidthBranchExtensionOffset, xByteRangeOffset);
        PatchBranch(code, xByteSixteenWidthBranchExtensionOffset, xByteRangeOffset);
        PatchBranch(code, xByteThirtyTwoWidthBranchExtensionOffset, xByteRangeOffset);
        Append(code, CompareWordD6ToD4);
        Append(code, BranchLowerOrSameWord);
        var xByteRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xByteRangeBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD5);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8); // up to eight byte stores from the selected plane
        Append(code, BranchHighWord);
        var planeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeWrapBranchExtensionOffset);
        Append(code, MoveAddressD5ToA4);

        // Bound the last selected row before publishing any byte.  The
        // maximum admitted span is eight bytes, so rejecting a wrapped row
        // start at FFF8 or above is conservative for every narrower marker.
        Append(code, MoveLongA4ToD6);
        Append(code, MoveWordD3ToD5);
        Append(code, MultiplyUnsignedWordD4ToD5);
        Append(code, AddLongD5ToD6);
        Append(code, BranchCarryWord);
        var finalRowOffsetWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(finalRowOffsetWrapBranchExtensionOffset);
        Append(code, MoveWordD7ToD5);
        Append(code, ShiftRightWordD5Count3);
        Append(code, ExtendLongD5);
        Append(code, AddLongD5ToD6);
        Append(code, BranchCarryWord);
        var finalRowStartWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(finalRowStartWrapBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8);
        Append(code, BranchHighWord);
        var finalRowRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(finalRowRangeBranchExtensionOffset);

        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var backgroundPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(backgroundPenBranchExtensionOffset);
        Append(code, MoveImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, BranchAlwaysWord);
        var backgroundReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var backgroundZeroOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        var readyOffset = code.Count;

        // Build the first-row pointer from plane0 + yMin*BytesPerRow +
        // xMin/8. A4 advances exactly one public stride for row 1.
        Append(code, MoveWordD1ToD6);
        Append(code, MultiplyUnsignedWordD4ToD6);
        Append(code, AddLongD6ToA4);
        Append(code, MoveWordD7ToD6);
        Append(code, ShiftRightWordD6Count3);
        Append(code, ExtendLongD6);
        Append(code, AddLongD6ToA4);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveAddressA0ToA5);
        Append(code, MoveWordD3ToD6);
        Append(code, SubWordD1ToD6);
        Append(code, AddQuickOneWordD6);
        Append(code, MoveWordD6ToD1);
        Append(code, MoveWordD2ToD3);
        var rowWriteLoopOffset = code.Count;
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, TestWordD3);
        Append(code, BranchEqualWord);
        var rowByteDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickOneD6);
        Append(code, AddLongD6ToA5);
        Append(code, SubQuickOneWordD3);
        Append(code, BranchAlwaysWord);
        var rowByteLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        var rowDoneOffset = code.Count;
        PatchBranch(code, rowByteDoneBranchExtensionOffset, rowDoneOffset);
        PatchBranch(code, rowByteLoopBranchExtensionOffset, rowWriteLoopOffset);
        Append(code, SubQuickOneWordD1);
        Append(code, BranchEqualWord);
        var rowCompleteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, AddLongD4ToA4);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveAddressA0ToA5);
        Append(code, MoveWordD2ToD3);
        Append(code, BranchAlwaysWord);
        var nextRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, nextRowBranchExtensionOffset, rowWriteLoopOffset);

        var successOffset = code.Count;
        PatchBranch(code, rowCompleteBranchExtensionOffset, successOffset);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, backgroundZeroBranchExtensionOffset, backgroundZeroOffset);
        PatchBranch(code, backgroundReadyBranchExtensionOffset, readyOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        return offset;
    }

    private static int AppendEraseRectMultiPlane(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(32);
        var earlyFallbackBranches = new List<int>(8);

        // Bounded multi-plane companion: one aligned 8/16/32/64-pixel row
        // on a depth-2..8 standard bitmap. The write mask selects planes and
        // BPen's corresponding bit expands to a complete MSB-first byte.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, TestWordD0);
        Append(code, BranchMinusWord);
        var xMinSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        earlyFallbackBranches.Add(xMinSignBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchMinusWord);
        var yMinSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        earlyFallbackBranches.Add(yMinSignBranchExtensionOffset);
        Append(code, TestWordD2);
        Append(code, BranchMinusWord);
        var xMaxSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        earlyFallbackBranches.Add(xMaxSignBranchExtensionOffset);
        Append(code, CompareWordD1ToD3);
        Append(code, BranchEqualWord);
        var oneRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD3ToD6);
        Append(code, SubWordD1ToD6);
        Append(code, CompareImmediateWordD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var rowSpanBranchExtensionOffset = code.Count;
        Append(code, 0);
        earlyFallbackBranches.Add(rowSpanBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var twoRowModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        var oneRowModeOffset = code.Count;
        Append(code, MoveQuickZeroD6);
        Append(code, BranchAlwaysWord);
        var oneRowModeJumpExtensionOffset = code.Count;
        Append(code, 0);
        var rowModeReadyOffset = code.Count;
        PatchBranch(code, oneRowBranchExtensionOffset, oneRowModeOffset);
        PatchBranch(code, twoRowModeBranchExtensionOffset, rowModeReadyOffset);
        PatchBranch(code, oneRowModeJumpExtensionOffset, rowModeReadyOffset);

        // Keep the incoming D0, the original yMax, and the inclusive row
        // distance on the guest stack while the shared body reuses all data
        // registers.
        Append(code, MoveAddressD6ToA6);
        Append(code, MoveLongD3ToD6);
        Append(code, MoveLongD6ToPreDecrementA7);
        Append(code, MoveLongA6ToD6);
        Append(code, MoveLongD6ToPreDecrementA7);

        // D6 is the width marker (byte count minus one); keep it in A6 while
        // D6 is reused for stride/range checks and address arithmetic. The
        // saved row distance remains available for the publication loop.
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD2ToD6);
        Append(code, SubWordD0ToD6);
        Append(code, CompareImmediateWordD6);
        Append(code, 7);
        Append(code, BranchEqualWord);
        var widthEightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 15);
        Append(code, BranchEqualWord);
        var widthSixteenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 31);
        Append(code, BranchEqualWord);
        var widthThirtyTwoBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 63);
        Append(code, BranchNotEqualWord);
        var widthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthBranchExtensionOffset);
        Append(code, MoveQuickSevenD6);
        Append(code, BranchAlwaysWord);
        var widthReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var widthEightOffset = code.Count;
        Append(code, MoveQuickZeroD6);
        Append(code, BranchAlwaysWord);
        var widthEightReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var widthSixteenOffset = code.Count;
        Append(code, MoveQuickOneD6);
        Append(code, BranchAlwaysWord);
        var widthSixteenReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var widthThirtyTwoOffset = code.Count;
        Append(code, MoveQuickThreeD6);
        Append(code, BranchAlwaysWord);
        var widthThirtyTwoReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var widthReadyOffset = code.Count;
        PatchBranch(code, widthEightBranchExtensionOffset, widthEightOffset);
        PatchBranch(code, widthSixteenBranchExtensionOffset, widthSixteenOffset);
        PatchBranch(code, widthThirtyTwoBranchExtensionOffset, widthThirtyTwoOffset);
        PatchBranch(code, widthEightReadyBranchExtensionOffset, widthReadyOffset);
        PatchBranch(code, widthSixteenReadyBranchExtensionOffset, widthReadyOffset);
        PatchBranch(code, widthThirtyTwoReadyBranchExtensionOffset, widthReadyOffset);
        PatchBranch(code, widthReadyBranchExtensionOffset, widthReadyOffset);
        Append(code, MoveAddressD6ToA6);
        Append(code, MoveLongD0ToD6);
        Append(code, ShiftRightWordD6Count3);
        Append(code, ExtendLongD6);
        Append(code, MoveAddressD6ToA5);

        // Validate the public RastPort/BitMap envelopes before consuming
        // depth, stride, mask, or plane storage.
        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var rastPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortWrapBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var layeredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layeredBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var bitmapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapWrapBranchExtensionOffset);
        Append(code, MoveAddressD4ToA0);

        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD3);
        Append(code, 2);
        Append(code, BranchCarryWord);
        var depthLowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthLowBranchExtensionOffset);
        Append(code, CompareImmediateByteD3);
        Append(code, 8);
        Append(code, BranchHighWord);
        var depthHighBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthHighBranchExtensionOffset);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var rowBytesZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesZeroBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rowBytesOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesOddBranchExtensionOffset);

        // A5 holds xMin/8, A4 holds yMin, and A6 retains the width marker.
        Append(code, MoveWordA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, MoveWordD2ToD3);
        Append(code, MoveLongA7DisplacementToD2);
        Append(code, 4);
        Append(code, MoveLongA5ToD6);
        Append(code, MoveLongA6ToD0);
        Append(code, AddLongD0ToD6);
        Append(code, AddQuickOneLongD6);
        Append(code, CompareWordD6ToD4);
        Append(code, BranchLowerOrSameWord);
        var xByteRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xByteRangeBranchExtensionOffset);
        Append(code, MoveLongD2ToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0x0000);
        Append(code, 0xFFFF);
        Append(code, CompareWordD2ToD3);
        Append(code, BranchLowerOrSameWord);
        var rowsRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsRangeBranchExtensionOffset);
        Append(code, MoveAddressD0ToA4);

        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveByteA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));

        // Preflight every selected inline plane. Unselected links are not
        // required, so mask-one does not consume plane-one storage.
        Append(code, MoveAddressA0ToA2);
        Append(code, MoveAddressA2ToA3);
        Append(code, AddQuickEightLongA2);
        Append(code, MoveQuickZeroD7);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, SubQuickOneWordD3);
        var preflightLoopOffset = code.Count;
        Append(code, MoveLongA2IndirectToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, BitTestDynamicD7ToD0);
        Append(code, BranchEqualWord);
        var preflightSkipPlaneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA0ToD2);
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, MoveLongA4ToD6);
        Append(code, MultiplyUnsignedWordD4ToD6);
        Append(code, AddLongD6ToD2);
        Append(code, BranchCarryWord);
        var rowAddressCarryBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowAddressCarryBranchExtensionOffset);
        Append(code, MoveLongA5ToD0);
        Append(code, AddLongD0ToD2);
        Append(code, BranchCarryWord);
        var xAddressCarryBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xAddressCarryBranchExtensionOffset);
        Append(code, MoveLongA6ToD0);
        Append(code, AddLongD0ToD2);
        Append(code, BranchCarryWord);
        var finalAddressCarryBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(finalAddressCarryBranchExtensionOffset);
        var preflightNextPlaneOffset = code.Count;
        Append(code, AddQuickFourLongA2);
        Append(code, AddQuickOneLongD7);
        Append(code, DecrementBranchD3);
        var preflightLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Publish selected planes only after the complete preflight. D1/A5/A6
        // retain yMin/x-byte/width marker for each plane; the saved row
        // distance on the guest stack drives every remaining row.
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveQuickZeroD7);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, SubQuickOneWordD3);
        Append(code, MoveAddressA3ToA2);
        Append(code, AddQuickEightLongA2);
        Append(code, MoveAddressD1ToA4);
        var publicationLoopOffset = code.Count;
        Append(code, MoveLongA2IndirectToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, BitTestDynamicD7ToD0);
        Append(code, BranchEqualWord);
        var publicationSkipPlaneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA0ToD2);
        Append(code, MoveLongA4ToD6);
        Append(code, MultiplyUnsignedWordD4ToD6);
        Append(code, AddLongD6ToD2);
        Append(code, MoveLongA5ToD0);
        Append(code, AddLongD0ToD2);
        Append(code, MoveLongA6ToD0);
        Append(code, AddLongD0ToD2);
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongA7DisplacementToD2);
        Append(code, 0);
        Append(code, MoveLongD2ToD6);
        Append(code, MoveLongA0ToD2);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, BitTestDynamicD7ToD0);
        Append(code, BranchEqualWord);
        var clearBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickMinusOneD1);
        Append(code, BranchAlwaysWord);
        var fillReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var clearOffset = code.Count;
        Append(code, MoveQuickZeroD1);
        var fillReadyOffset = code.Count;
        Append(code, MoveLongA6ToD0);
        var byteLoopOffset = code.Count;
        Append(code, MoveByteD1ToA0PostIncrement);
        Append(code, DecrementBranchD0);
        var byteLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var secondRowSkipBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, SubQuickOneWordD6);
        var rowAdvanceOffset = code.Count;
        Append(code, MoveLongD4ToD0);
        Append(code, AddLongD0ToD2);
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongA6ToD0);
        var secondByteLoopOffset = code.Count;
        Append(code, MoveByteD1ToA0PostIncrement);
        Append(code, DecrementBranchD0);
        var secondByteLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, DecrementBranchD6);
        var rowAdvanceBranchExtensionOffset = code.Count;
        Append(code, 0);
        var afterPlaneOffset = code.Count;
        Append(code, AddQuickFourLongA2);
        Append(code, AddQuickOneLongD7);
        Append(code, DecrementBranchD3);
        var publicationLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        var earlyFallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var earlyFallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, preflightLoopBranchExtensionOffset, preflightLoopOffset);
        PatchBranch(code, preflightSkipPlaneBranchExtensionOffset, preflightNextPlaneOffset);
        PatchBranch(code, publicationLoopBranchExtensionOffset, publicationLoopOffset);
        PatchBranch(code, publicationSkipPlaneBranchExtensionOffset, afterPlaneOffset);
        PatchBranch(code, clearBranchExtensionOffset, clearOffset);
        PatchBranch(code, fillReadyBranchExtensionOffset, fillReadyOffset);
        PatchBranch(code, byteLoopBranchExtensionOffset, byteLoopOffset);
        PatchBranch(code, secondRowSkipBranchExtensionOffset, afterPlaneOffset);
        PatchBranch(code, secondByteLoopBranchExtensionOffset, secondByteLoopOffset);
        PatchBranch(code, rowAdvanceBranchExtensionOffset, rowAdvanceOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, earlyFallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in earlyFallbackBranches)
            PatchBranch(code, branchExtensionOffset, earlyFallbackRestoreOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendEraseRect(
        List<byte> code,
        int fallbackEntryOffset,
        int multiPlaneEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(48);

        // Claim the exact one-pixel, one-plane JAM1 form. The portable path
        // remains authoritative for rectangles, minterms, clipping, layers,
        // and provider-owned surfaces.
        Append(code, MoveLongD0ToD6);
        Append(code, CompareWordD2ToD0);
        Append(code, BranchEqualWord);
        var onePixelBoundsBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveWordD2ToD5);
        Append(code, SubWordD0ToD5);
        Append(code, CompareImmediateWordD5);
        Append(code, 7);
        Append(code, BranchEqualWord);
        var spanEightWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD5);
        Append(code, 15);
        Append(code, BranchEqualWord);
        var spanSixteenWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD5);
        Append(code, 31);
        Append(code, BranchEqualWord);
        var spanThirtyTwoWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD5);
        Append(code, 127);
        Append(code, BranchEqualWord);
        var spanOneHundredTwentyEightWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD5);
        Append(code, 63);
        Append(code, BranchNotEqualWord);
        var spanWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(spanWidthBranchExtensionOffset);
        var spanWidthReadyOffset = code.Count;
        Append(code, MoveLongD0ToD7);
        Append(code, AndImmediateWordD7);
        Append(code, 7);
        Append(code, TestWordD7);
        Append(code, BranchNotEqualWord);
        var spanAlignmentBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(spanAlignmentBranchExtensionOffset);
        Append(code, MoveQuickZeroD7);
        Append(code, MoveWordD2ToD7);
        Append(code, MoveWordD5ToD2); // width marker: 7, 15, 31, 63, or 127
        Append(code, MoveLongD6ToD0); // restore xMin
        Append(code, BranchAlwaysWord);
        var spanBoundsReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var onePixelBoundsOffset = code.Count;
        Append(code, MoveQuickZeroD2); // width marker for the one-pixel arm
        var boundsReadyOffset = code.Count;
        Append(code, CompareWordD3ToD1);
        Append(code, BranchNotEqualWord);
        var yBoundsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yBoundsBranchExtensionOffset);
        Append(code, TestWordD0);
        Append(code, BranchMinusWord);
        var xSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xSignBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchMinusWord);
        var ySignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ySignBranchExtensionOffset);

        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);

        // D2 carries the geometry arm marker (0 for one pixel, 7, 15, 31, or
        // 63 for an aligned byte span).  Consume the RastPort bitmap pointer
        // through D5 so that marker survives until the final dispatch.
        Append(code, MoveLongA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var bitmapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapBranchExtensionOffset);
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var depthSkipRelayBranchExtensionOffset = code.Count;
        Append(code, 0);
        var multiPlaneRelayOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongD0ToD2);
        Append(code, MoveLongD6ToD0);
        Append(code, BranchAlwaysWord);
        var multiPlaneRelayBranchExtensionOffset = code.Count;
        Append(code, 0);
        var depthAfterRelayOffset = code.Count;
        PatchBranch(code, depthBranchExtensionOffset, multiPlaneRelayOffset);
        PatchBranch(code, depthSkipRelayBranchExtensionOffset, depthAfterRelayOffset);
        PatchBranch(code, multiPlaneRelayBranchExtensionOffset, multiPlaneEntryOffset);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var rowBytesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesBranchExtensionOffset);
        // The wide arm must prove that the complete sixteen-byte row fits
        // after the selected x-byte offset.  The narrower forms retain their
        // established admission; only the new 128-pixel marker reaches this
        // dynamic stride check.
        Append(code, CompareImmediateWordD2);
        Append(code, 127);
        Append(code, BranchNotEqualWord);
        var wideStrideCheckSkipBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD6ToD7);
        Append(code, ShiftRightWordD7Count3);
        Append(code, AddImmediateWordD7);
        Append(code, 16);
        Append(code, CompareWordD7ToD4);
        Append(code, BranchCarryWord);
        var wideStrideFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wideStrideFallbackBranchExtensionOffset);
        var wideStrideCheckReadyOffset = code.Count;
        PatchBranch(code, wideStrideCheckSkipBranchExtensionOffset, wideStrideCheckReadyOffset);
        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var planesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planesBranchExtensionOffset);
        Append(code, MoveAddressD5ToA4);
        Append(code, MoveLongA4ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var planeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeBranchExtensionOffset);
        Append(code, MoveAddressD0ToA4);

        // D6 retains x for fallback; derive the MSB-first bit and row/byte
        // offset from the public bitmap stride and the single coordinate.
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD6ToD7);
        Append(code, AndImmediateWordD7);
        Append(code, 7);
        Append(code, MoveQuickSevenD6);
        Append(code, SubWordD7ToD6);
        Append(code, MoveWordD1ToD5);
        Append(code, MultiplyUnsignedWordD4ToD5);
        Append(code, ShiftRightWordD0Count3);
        Append(code, ExtendLongD0);
        Append(code, AddLongD0ToD5);
        Append(code, AddLongD5ToA4);

        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateWordD2);
        Append(code, 7);
        Append(code, BranchEqualWord);
        var spanDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 15);
        Append(code, BranchEqualWord);
        var wideSpanDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 31);
        Append(code, BranchEqualWord);
        var extraWideSpanDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 63);
        Append(code, BranchEqualWord);
        var maximumSpanDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 127);
        Append(code, BranchEqualWord);
        var oneHundredTwentyEightSpanDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var clearBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitSetDynamicD6AtA4);
        Append(code, BranchAlwaysWord);
        var successBranchExtensionOffset = code.Count;
        Append(code, 0);
        var clearPathOffset = code.Count;
        Append(code, BitClearDynamicD6AtA4);
        Append(code, BranchAlwaysWord);
        var clearSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        var successOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD6ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        var spanOperationOffset = code.Count;
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var spanBackgroundZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, BranchAlwaysWord);
        var spanStoreBranchExtensionOffset = code.Count;
        Append(code, 0);
        var spanBackgroundZeroOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        var spanStoreOffset = code.Count;
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, BranchAlwaysWord);
        var spanSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        var wideSpanOperationOffset = code.Count;
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var wideSpanBackgroundZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, BranchAlwaysWord);
        var wideSpanStoreBranchExtensionOffset = code.Count;
        Append(code, 0);
        var wideSpanBackgroundZeroOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        var wideSpanStoreOffset = code.Count;
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickOneLongA4);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, BranchAlwaysWord);
        var wideSpanSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        var extraWideSpanOperationOffset = code.Count;
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var extraWideSpanBackgroundZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, BranchAlwaysWord);
        var extraWideSpanStoreBranchExtensionOffset = code.Count;
        Append(code, 0);
        var extraWideSpanBackgroundZeroOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        var extraWideSpanStoreOffset = code.Count;
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickOneLongA4);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickOneLongA4);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickOneLongA4);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, BranchAlwaysWord);
        var extraWideSpanSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        var maximumSpanOperationOffset = code.Count;
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var maximumSpanBackgroundZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, BranchAlwaysWord);
        var maximumSpanStoreBranchExtensionOffset = code.Count;
        Append(code, 0);
        var maximumSpanBackgroundZeroOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        var maximumSpanStoreOffset = code.Count;
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickOneLongA4);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickOneLongA4);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickOneLongA4);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickOneLongA4);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickOneLongA4);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickOneLongA4);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, AddQuickOneLongA4);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, BranchAlwaysWord);
        var maximumSpanSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        var oneHundredTwentyEightSpanOperationOffset = code.Count;
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var oneHundredTwentyEightSpanBackgroundZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, BranchAlwaysWord);
        var oneHundredTwentyEightSpanStoreBranchExtensionOffset = code.Count;
        Append(code, 0);
        var oneHundredTwentyEightSpanBackgroundZeroOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        var oneHundredTwentyEightSpanStoreOffset = code.Count;
        for (var byteIndex = 0; byteIndex < 16; byteIndex++)
        {
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveByteD0ToA0);
            if (byteIndex + 1 < 16)
                Append(code, AddQuickOneLongA4);
        }
        Append(code, BranchAlwaysWord);
        var oneHundredTwentyEightSpanSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, clearBranchExtensionOffset, clearPathOffset);
        PatchBranch(code, successBranchExtensionOffset, successOffset);
        PatchBranch(code, clearSuccessBranchExtensionOffset, successOffset);
        PatchBranch(code, onePixelBoundsBranchExtensionOffset, onePixelBoundsOffset);
        PatchBranch(code, spanEightWidthBranchExtensionOffset, spanWidthReadyOffset);
        PatchBranch(code, spanSixteenWidthBranchExtensionOffset, spanWidthReadyOffset);
        PatchBranch(code, spanThirtyTwoWidthBranchExtensionOffset, spanWidthReadyOffset);
        PatchBranch(code, spanBoundsReadyBranchExtensionOffset, boundsReadyOffset);
        PatchBranch(code, spanDispatchBranchExtensionOffset, spanOperationOffset);
        PatchBranch(code, wideSpanDispatchBranchExtensionOffset, wideSpanOperationOffset);
        PatchBranch(code, extraWideSpanDispatchBranchExtensionOffset, extraWideSpanOperationOffset);
        PatchBranch(code, maximumSpanDispatchBranchExtensionOffset, maximumSpanOperationOffset);
        PatchBranch(code, spanOneHundredTwentyEightWidthBranchExtensionOffset, spanWidthReadyOffset);
        PatchBranch(code, oneHundredTwentyEightSpanDispatchBranchExtensionOffset, oneHundredTwentyEightSpanOperationOffset);
        PatchBranch(code, spanBackgroundZeroBranchExtensionOffset, spanBackgroundZeroOffset);
        PatchBranch(code, spanStoreBranchExtensionOffset, spanStoreOffset);
        PatchBranch(code, spanSuccessBranchExtensionOffset, successOffset);
        PatchBranch(code, wideSpanBackgroundZeroBranchExtensionOffset, wideSpanBackgroundZeroOffset);
        PatchBranch(code, wideSpanStoreBranchExtensionOffset, wideSpanStoreOffset);
        PatchBranch(code, wideSpanSuccessBranchExtensionOffset, successOffset);
        PatchBranch(code, extraWideSpanBackgroundZeroBranchExtensionOffset, extraWideSpanBackgroundZeroOffset);
        PatchBranch(code, extraWideSpanStoreBranchExtensionOffset, extraWideSpanStoreOffset);
        PatchBranch(code, extraWideSpanSuccessBranchExtensionOffset, successOffset);
        PatchBranch(code, maximumSpanBackgroundZeroBranchExtensionOffset, maximumSpanBackgroundZeroOffset);
        PatchBranch(code, maximumSpanStoreBranchExtensionOffset, maximumSpanStoreOffset);
        PatchBranch(code, maximumSpanSuccessBranchExtensionOffset, successOffset);
        PatchBranch(code, oneHundredTwentyEightSpanBackgroundZeroBranchExtensionOffset, oneHundredTwentyEightSpanBackgroundZeroOffset);
        PatchBranch(code, oneHundredTwentyEightSpanStoreBranchExtensionOffset, oneHundredTwentyEightSpanStoreOffset);
        PatchBranch(code, oneHundredTwentyEightSpanSuccessBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendFloodZeroMask(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(20);

        // Flood with no selected destination planes is a successful BOOL
        // no-write boundary after the public seed and bitmap envelope has
        // been validated.  Keep all real connectivity, pattern, pen, and
        // temporary-raster work on the portable/provider owner.
        Append(code, MoveLongD0ToD7); // preserve seed X for fallback

        Append(code, MoveLongA1ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);

        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 0); // Claim only the basic FLOODFILL mode
        Append(code, BranchHighWord);
        var modeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(modeBranchExtensionOffset);

        Append(code, TestWordD0);
        Append(code, BranchMinusWord);
        var xSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xSignBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchMinusWord);
        var ySignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ySignBranchExtensionOffset);

        // The layer is part of the native admission envelope.  A non-null
        // layer routes through the portable owner even when the destination
        // plane mask is zero.
        Append(code, MoveLongA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var layerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layerBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var bitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapRangeBranchExtensionOffset);
        Append(code, MoveAddressD6ToA2);

        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var rowBytesZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesZeroBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rowBytesOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesOddBranchExtensionOffset);

        // Seed X must address a byte within the declared row.  The bitmap
        // header has no explicit width, so the standard planar width is the
        // even bytes-per-row field multiplied by eight.
        Append(code, MoveLongD0ToD6);
        Append(code, ShiftRightWordD6Count3);
        Append(code, CompareWordD6ToD4);
        Append(code, BranchLowerOrSameWord);
        var xByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xByteBranchExtensionOffset);
        // Preserve the established zero-mask seed envelope: rows-1 and the
        // inclusive rows endpoint remain harmless, while larger Y declines.
        Append(code, MoveWordA2DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareWordD3ToD1);
        Append(code, BranchHighWord);
        var yRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yRangeBranchExtensionOffset);

        // A zero destination mask is a successful BOOL no-op after the
        // public RastPort/BitMap envelope and seed geometry have been
        // admitted.  It deliberately avoids any plane dereference.  Keep
        // non-zero masks on the portable/provider owner.
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA1DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, TestLongD3);
        Append(code, BranchEqualWord);
        var zeroMaskSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);

        // TryReadBitmap also requires the selected plane to be readable.  A
        // depth-one native seed therefore has exactly one even plane link.
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);

        var successOffset = code.Count;
        Append(code, MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, zeroMaskSuccessBranchExtensionOffset, successOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendBltBitMapRastPortCopy(
        List<byte> code,
        int fallbackEntryOffset,
        bool requireExternalMask = false,
        bool requireDestinationRastPortMask = true,
        bool voidResult = false,
        bool restoreSourceRastPortOnFallback = false,
        bool destinationIsBitmap = false,
        bool requireDestinationBitmapMask = false,
        bool requireTemporaryPlaneNull = false,
        int byteWidth = 1)
    {
        if (byteWidth is not (1 or 2 or 4 or 8 or 16))
            throw new ArgumentOutOfRangeException(nameof(byteWidth));

        var offset = code.Count;
        var fallbackBranches = new List<int>(48);

        // Claim deliberately small planar source-copy forms: an aligned
        // one-row source copy of byteWidth bytes (eight, sixteen, thirty-two,
        // sixty-four, or one-hundred-twenty-eight pixels,
        // minterm A / $C0) into plane zero
        // of either a standard one-plane RastPort or a direct one-plane
        // BitMap. The complete source/destination header and plane envelopes
        // are checked before the single byte store; all general blit geometry
        // remains on the portable/provider owner.
        // The masked entry reuses this proof only when its external mask is a
        // readable, all-on byte; it deliberately does not consult the
        // destination RastPort plane mask, matching the portable masked-blit
        // contract.  Its void ABI clears D0 on success and preserves D0 on
        // fallback just like the Kickstart entry.
        if (destinationIsBitmap)
        {
            // BltBitMap carries the destination write mask in D7 and an
            // optional temporary plane in A2. Preserve both the mask and the
            // minterm before the shared body snapshots source X in D7.
            Append(code, MoveAddressD7ToA4);
            Append(code, MoveAddressD6ToA6);
        }

        Append(code, MoveLongD0ToD7); // preserve source X for BOOL fallback

        if (requireTemporaryPlaneNull)
        {
            Append(code, MoveLongA2ToD6);
            Append(code, TestLongD6);
            Append(code, BranchNotEqualWord);
            var temporaryPlaneBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(temporaryPlaneBranchExtensionOffset);
            Append(code, MoveLongA6ToD6);
        }

        if (requireDestinationBitmapMask)
        {
            Append(code, MoveLongA4ToD0);
            Append(code, AndImmediateLongD0);
            Append(code, 0x0000);
            Append(code, 0x00FF);
            Append(code, CompareImmediateLongD0);
            Append(code, 0x0000);
            Append(code, 0x0001);
            Append(code, BranchNotEqualWord);
            var destinationBitmapMaskBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(destinationBitmapMaskBranchExtensionOffset);
            Append(code, MoveLongD7ToD0);
        }

        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var sourceXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceXBranchExtensionOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var sourceYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceYBranchExtensionOffset);
        Append(code, MoveLongD6ToD1); // retain the minterm byte

        Append(code, TestWordD2);
        Append(code, BranchMinusWord);
        var destinationXSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationXSignBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var destinationXBit0BranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationXBit0BranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var destinationXBit1BranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationXBit1BranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var destinationXBit2BranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationXBit2BranchExtensionOffset);
        Append(code, CompareImmediateWordD3);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var destinationYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationYBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, checked((ushort)(byteWidth * 8)));
        Append(code, BranchNotEqualWord);
        var widthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthBranchExtensionOffset);
        Append(code, CompareImmediateWordD5);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var heightBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(heightBranchExtensionOffset);
        Append(code, CompareImmediateByteD1);
        Append(code, 0x00C0);
        Append(code, BranchNotEqualWord);
        var mintermBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(mintermBranchExtensionOffset);

        if (requireExternalMask)
        {
            Append(code, MoveLongA2ToD6);
            Append(code, TestLongD6);
            Append(code, BranchEqualWord);
            var externalMaskNullBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(externalMaskNullBranchExtensionOffset);
            Append(code, BitTestImmediateD6);
            Append(code, 0);
            Append(code, BranchNotEqualWord);
            var externalMaskOddBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(externalMaskOddBranchExtensionOffset);
            Append(code, CompareImmediateLongD6);
            Append(code, 0xFFFF);
            Append(code, 0xFFFF); // first external-mask byte envelope
            Append(code, BranchHighWord);
            var externalMaskRangeBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(externalMaskRangeBranchExtensionOffset);
            if (byteWidth > 1)
            {
                Append(code, CompareImmediateLongD6);
                Append(code, 0xFFFF);
                Append(code, checked((ushort)(0x10000 - byteWidth)));
                Append(code, BranchHighWord);
                var externalMaskWidthBranchExtensionOffset = code.Count;
                Append(code, 0);
                fallbackBranches.Add(externalMaskWidthBranchExtensionOffset);
            }
            Append(code, MoveByteA2DisplacementToD6);
            Append(code, 0);
            Append(code, CompareImmediateByteD6);
            Append(code, 0x00FF);
            Append(code, BranchNotEqualWord);
            var externalMaskValueBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(externalMaskValueBranchExtensionOffset);
            for (var maskByteIndex = 1; maskByteIndex < byteWidth; maskByteIndex++)
            {
                Append(code, MoveByteA2DisplacementToD6);
                Append(code, checked((ushort)maskByteIndex));
                Append(code, CompareImmediateByteD6);
                Append(code, 0x00FF);
                Append(code, BranchNotEqualWord);
                var externalMaskByteBranchExtensionOffset = code.Count;
                Append(code, 0);
                fallbackBranches.Add(externalMaskByteBranchExtensionOffset);
            }
        }

        // Source bitmap envelope: source X/Y are zero, so only the selected
        // aligned source bytes are touched by this native form.
        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var sourceBitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceBitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var sourceBitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceBitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // source BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var sourceBitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceBitmapRangeBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var sourceDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceDepthBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var sourceBytesPerRowZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceBytesPerRowZeroBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var sourceBytesPerRowOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceBytesPerRowOddBranchExtensionOffset);
        if (byteWidth > 1)
        {
            Append(code, CompareImmediateWordD4);
            Append(code, checked((ushort)byteWidth));
            Append(code, BranchCarryWord);
            var sourceBytesPerRowWidthBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(sourceBytesPerRowWidthBranchExtensionOffset);
        }
        Append(code, MoveWordA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestWordD5);
        Append(code, BranchEqualWord);
        var sourceRowsZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceRowsZeroBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var sourcePlaneNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourcePlaneNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var sourcePlaneOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourcePlaneOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFF); // first source-plane byte envelope
        Append(code, BranchHighWord);
        var sourcePlaneRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourcePlaneRangeBranchExtensionOffset);
        if (byteWidth > 1)
        {
            Append(code, CompareImmediateLongD6);
            Append(code, 0xFFFF);
            Append(code, checked((ushort)(0x10000 - byteWidth)));
            Append(code, BranchHighWord);
            var sourcePlaneWidthBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(sourcePlaneWidthBranchExtensionOffset);
        }
        Append(code, MoveAddressD6ToA3);

        // Destination RastPort and bitmap envelope.
        Append(code, MoveLongA1ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var destinationRastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationRastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var destinationRastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationRastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, destinationIsBitmap ? (ushort)0xFFD8 : (ushort)0xFF4C);
        // direct BitMapSize (0x28), otherwise RastPortMinimumSize (0xB4)
        Append(code, BranchHighWord);
        var destinationRastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationRastPortRangeBranchExtensionOffset);
        if (!destinationIsBitmap)
        {
            Append(code, MoveLongA1DisplacementToD6);
            Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
            Append(code, TestLongD6);
            Append(code, BranchNotEqualWord);
            var destinationLayerBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(destinationLayerBranchExtensionOffset);
            if (requireDestinationRastPortMask)
            {
                Append(code, MoveByteA1DisplacementToD6);
                Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
                Append(code, CompareImmediateByteD6);
                Append(code, 1);
                Append(code, BranchNotEqualWord);
                var destinationMaskBranchExtensionOffset = code.Count;
                Append(code, 0);
                fallbackBranches.Add(destinationMaskBranchExtensionOffset);
            }
            Append(code, MoveLongA1DisplacementToD6);
            Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
            Append(code, TestLongD6);
            Append(code, BranchEqualWord);
            var destinationBitmapNullBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(destinationBitmapNullBranchExtensionOffset);
            Append(code, BitTestImmediateD6);
            Append(code, 0);
            Append(code, BranchNotEqualWord);
            var destinationBitmapOddBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(destinationBitmapOddBranchExtensionOffset);
            Append(code, CompareImmediateLongD6);
            Append(code, 0xFFFF);
            Append(code, 0xFFD8); // destination BitMapSize (0x28) envelope
            Append(code, BranchHighWord);
            var destinationBitmapRangeBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(destinationBitmapRangeBranchExtensionOffset);
        }
        Append(code, MoveAddressD6ToA2);
        Append(code, MoveByteA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var destinationDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationDepthBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestWordD3);
        Append(code, BranchEqualWord);
        var destinationRowsZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationRowsZeroBranchExtensionOffset);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD2ToD6);
        Append(code, ShiftRightWordD6Count3);
        Append(code, MoveLongD6ToD5); // retain destination byte offset
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var destinationBytesPerRowZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationBytesPerRowZeroBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var destinationBytesPerRowOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationBytesPerRowOddBranchExtensionOffset);
        Append(code, MoveLongD5ToD6);
        if (byteWidth > 1)
        {
            Append(code, AddImmediateWordD6);
            Append(code, checked((ushort)(byteWidth - 1)));
        }
        Append(code, CompareWordD6ToD4);
        Append(code, BranchLowerOrSameWord);
        var destinationByteRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationByteRangeBranchExtensionOffset);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var destinationPlaneNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationPlaneNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var destinationPlaneOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationPlaneOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // source RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var destinationPlaneRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationPlaneRangeBranchExtensionOffset);
        if (byteWidth > 1)
        {
            Append(code, CompareImmediateLongD6);
            Append(code, 0xFFFF);
            Append(code, checked((ushort)(0x10000 - byteWidth)));
            Append(code, BranchHighWord);
            var destinationPlaneWidthBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(destinationPlaneWidthBranchExtensionOffset);
        }
        Append(code, MoveAddressD6ToA5);
        Append(code, MoveLongD5ToD6);
        Append(code, AddLongD6ToA5);

        // Source byte(s) -> destination byte(s) publication.  D3..D7 are
        // free after the complete source/destination preflight, so retain
        // every source byte independently before touching the destination.
        if (byteWidth >= 8)
        {
            Append(code, MoveLongA3IndirectToD3);
            Append(code, MoveLongA3DisplacementToD4);
            Append(code, 4);
            if (byteWidth >= 16)
            {
                Append(code, MoveLongA3DisplacementToD5);
                Append(code, 8);
                Append(code, MoveLongA3DisplacementToD6);
                Append(code, 12);
            }
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveLongD3ToA0Displacement);
            Append(code, 0);
            Append(code, MoveLongD4ToA0Displacement);
            Append(code, 4);
            if (byteWidth >= 16)
            {
                Append(code, MoveLongD5ToA0Displacement);
                Append(code, 8);
                Append(code, MoveLongD6ToA0Displacement);
                Append(code, 12);
            }
        }
        else
        {
            var sourceByteLoads = new[]
            {
                MoveByteA3DisplacementToD3,
                MoveByteA3DisplacementToD4,
                MoveByteA3DisplacementToD5,
                MoveByteA3DisplacementToD6,
                MoveByteA3DisplacementToD7
            };
            var destinationByteStores = new[]
            {
                MoveByteD3ToA0Displacement,
                MoveByteD4ToA0Displacement,
                MoveByteD5ToA0Displacement,
                MoveByteD6ToA0Displacement,
                MoveByteD7ToA0Displacement
            };
            for (var byteIndex = 0; byteIndex < byteWidth; byteIndex++)
            {
                Append(code, sourceByteLoads[byteIndex]);
                Append(code, checked((ushort)byteIndex));
            }
            Append(code, MoveAddressA5ToA0);
            for (var byteIndex = 0; byteIndex < byteWidth; byteIndex++)
            {
                Append(code, destinationByteStores[byteIndex]);
                Append(code, checked((ushort)byteIndex));
            }
        }
        Append(code, voidResult ? MoveQuickZeroD0 : MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        if (restoreSourceRastPortOnFallback)
            Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendBltBitMapWidthDispatch(
        List<byte> code,
        int fallbackEntryOffset,
        int eightPixelEntryOffset,
        int sixteenPixelEntryOffset,
        int thirtyTwoPixelEntryOffset,
        int sixtyFourPixelEntryOffset,
        int oneHundredTwentyEightPixelEntryOffset)
    {
        var offset = code.Count;
        Append(code, CompareImmediateWordD4);
        Append(code, 8);
        Append(code, BranchEqualWord);
        var eightPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 16);
        Append(code, BranchEqualWord);
        var sixteenPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 32);
        Append(code, BranchEqualWord);
        var thirtyTwoPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 64);
        Append(code, BranchEqualWord);
        var sixtyFourPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 128);
        Append(code, BranchEqualWord);
        var oneHundredTwentyEightPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var fallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, eightPixelBranchExtensionOffset, eightPixelEntryOffset);
        PatchBranch(code, sixteenPixelBranchExtensionOffset, sixteenPixelEntryOffset);
        PatchBranch(code, thirtyTwoPixelBranchExtensionOffset, thirtyTwoPixelEntryOffset);
        PatchBranch(code, sixtyFourPixelBranchExtensionOffset, sixtyFourPixelEntryOffset);
        PatchBranch(
            code,
            oneHundredTwentyEightPixelBranchExtensionOffset,
            oneHundredTwentyEightPixelEntryOffset);
        PatchBranch(code, fallbackBranchExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendBltMaskWidthDispatch(
        List<byte> code,
        int fallbackEntryOffset,
        int eightPixelEntryOffset,
        int sixteenPixelEntryOffset,
        int thirtyTwoPixelEntryOffset,
        int sixtyFourPixelEntryOffset,
        int oneHundredTwentyEightPixelEntryOffset)
    {
        var offset = code.Count;
        Append(code, CompareImmediateWordD4);
        Append(code, 8);
        Append(code, BranchEqualWord);
        var eightPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 16);
        Append(code, BranchEqualWord);
        var sixteenPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 32);
        Append(code, BranchEqualWord);
        var thirtyTwoPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 64);
        Append(code, BranchEqualWord);
        var sixtyFourPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 128);
        Append(code, BranchEqualWord);
        var oneHundredTwentyEightPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var fallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, eightPixelBranchExtensionOffset, eightPixelEntryOffset);
        PatchBranch(code, sixteenPixelBranchExtensionOffset, sixteenPixelEntryOffset);
        PatchBranch(code, thirtyTwoPixelBranchExtensionOffset, thirtyTwoPixelEntryOffset);
        PatchBranch(code, sixtyFourPixelBranchExtensionOffset, sixtyFourPixelEntryOffset);
        PatchBranch(
            code,
            oneHundredTwentyEightPixelBranchExtensionOffset,
            oneHundredTwentyEightPixelEntryOffset);
        PatchBranch(code, fallbackBranchExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendBltPatternWidthDispatch(
        List<byte> code,
        int fallbackEntryOffset,
        int eightPixelEntryOffset,
        int sixteenPixelEntryOffset,
        int thirtyTwoPixelEntryOffset,
        int sixtyFourPixelEntryOffset,
        int oneHundredTwentyEightPixelEntryOffset)
    {
        var offset = code.Count;
        Append(code, CompareImmediateWordD2);
        Append(code, 7);
        Append(code, BranchEqualWord);
        var eightPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 15);
        Append(code, BranchEqualWord);
        var sixteenPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 31);
        Append(code, BranchEqualWord);
        var thirtyTwoPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 63);
        Append(code, BranchEqualWord);
        var sixtyFourPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 127);
        Append(code, BranchEqualWord);
        var oneHundredTwentyEightPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var fallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, eightPixelBranchExtensionOffset, eightPixelEntryOffset);
        PatchBranch(code, sixteenPixelBranchExtensionOffset, sixteenPixelEntryOffset);
        PatchBranch(code, thirtyTwoPixelBranchExtensionOffset, thirtyTwoPixelEntryOffset);
        PatchBranch(code, sixtyFourPixelBranchExtensionOffset, sixtyFourPixelEntryOffset);
        PatchBranch(
            code,
            oneHundredTwentyEightPixelBranchExtensionOffset,
            oneHundredTwentyEightPixelEntryOffset);
        PatchBranch(code, fallbackBranchExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendBltTemplateWidthDispatch(
        List<byte> code,
        int fallbackEntryOffset,
        int eightPixelEntryOffset,
        int sixteenPixelEntryOffset,
        int thirtyTwoPixelEntryOffset,
        int sixtyFourPixelEntryOffset,
        int oneHundredTwentyEightPixelEntryOffset)
    {
        var offset = code.Count;
        Append(code, CompareImmediateWordD4);
        Append(code, 8);
        Append(code, BranchEqualWord);
        var eightPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 16);
        Append(code, BranchEqualWord);
        var sixteenPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 32);
        Append(code, BranchEqualWord);
        var thirtyTwoPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 64);
        Append(code, BranchEqualWord);
        var sixtyFourPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 128);
        Append(code, BranchEqualWord);
        var oneHundredTwentyEightPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var fallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, eightPixelBranchExtensionOffset, eightPixelEntryOffset);
        PatchBranch(code, sixteenPixelBranchExtensionOffset, sixteenPixelEntryOffset);
        PatchBranch(code, thirtyTwoPixelBranchExtensionOffset, thirtyTwoPixelEntryOffset);
        PatchBranch(code, sixtyFourPixelBranchExtensionOffset, sixtyFourPixelEntryOffset);
        PatchBranch(
            code,
            oneHundredTwentyEightPixelBranchExtensionOffset,
            oneHundredTwentyEightPixelEntryOffset);
        PatchBranch(code, fallbackBranchExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendClipBlitRastPortCopy(
        List<byte> code,
        int fallbackEntryOffset,
        int bitmapCopyEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(8);

        // ClipBlit carries a RastPort in A0, while the already-proven native
        // copy body consumes its BitMap in A0.  Keep this bridge deliberately
        // narrow: source X/Y and destination Y are zero, destination X is
        // the aligned one-byte form accepted by the bitmap copy body, and
        // both source and destination ports must be classic layer-zero
        // descriptors.  General clipping, minterms, and provider surfaces
        // remain on the portable/provider owner.
        Append(code, MoveLongD0ToD7); // preserve source X for the void ABI
        Append(code, MoveAddressD6ToA4); // preserve the caller's minterm
        Append(code, MoveAddressA0ToA6);
        Append(code, MoveLongA6ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var sourceRastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceRastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var sourceRastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceRastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // source RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var sourceRastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceRastPortRangeBranchExtensionOffset);

        Append(code, MoveLongA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, MoveLongD0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var sourceLayerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceLayerBranchExtensionOffset);

        Append(code, MoveLongA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, MoveLongD0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var sourceBitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceBitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var sourceBitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceBitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // source BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var sourceBitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceBitmapRangeBranchExtensionOffset);
        Append(code, MoveAddressD6ToA0);

        // The bridge used D0 as a scratch register while reading the source
        // RastPort.  Restore the documented source-X value before entering
        // the shared copy body, whose first instruction snapshots D0 for its
        // own fallback path.
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToD6);
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var bitmapCopyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, bitmapCopyBranchExtensionOffset, bitmapCopyEntryOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendBltPatternNative(
        List<byte> code,
        int fallbackEntryOffset,
        int byteWidth = 1)
    {
        if (byteWidth is not (1 or 2 or 4 or 8 or 16))
            throw new ArgumentOutOfRangeException(nameof(byteWidth));

        var offset = code.Count;
        var fallbackBranches = new List<int>(40);

        // Claim two deliberately small source-free forms.  With no external
        // mask and no AreaPtrn, INVERSVID|JAM1 turns the implicit all-one
        // source into all zeroes and is a successful no-op.  Ordinary JAM1
        // additionally claims an aligned 8-, 16-, 32-, 64-, or 128-pixel rectangle covering
        // rows 0..yMax on a standard one-plane RastPort, publishing one or
        // more complete bytes per row from APen bit zero.  General patterns, clipping,
        // layers, and provider surfaces remain on their existing owners.
        Append(code, MoveLongD0ToD7); // preserve D0 for the void fallback

        Append(code, MoveLongA1ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var layerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layerBranchExtensionOffset);

        // A non-NULL A0 is an external stencil and therefore not this
        // source-free form.  Do not dereference it on the native path.
        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var externalMaskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(externalMaskBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAreaPtrn));
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var areaPatternBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(areaPatternBranchExtensionOffset);

        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD6);
        Append(code, 0x0004); // INVERSVID | JAM1
        Append(code, BranchEqualWord);
        var inverseNoOpBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD6);
        Append(code, 0x0000); // ordinary JAM1 for the aligned-row form
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);

        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var xMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var yMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD2);
        Append(code, checked((ushort)(byteWidth * 8 - 1)));
        Append(code, BranchNotEqualWord);
        var xMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMaxBranchExtensionOffset);
        // Rows are a word-sized unsigned bound.  Compare D3 against the
        // declared row count in the reversed order so BLS rejects yMax >=
        // Rows while accepting every non-negative in-range row.

        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var bitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapRangeBranchExtensionOffset);
        Append(code, MoveAddressD6ToA2);

        Append(code, MoveByteA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var bytesPerRowZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bytesPerRowZeroBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bytesPerRowOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bytesPerRowOddBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestWordD5);
        Append(code, BranchEqualWord);
        var rowsZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsZeroBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareWordD3ToD1);
        Append(code, BranchLowerOrSameWord);
        var yMaxRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMaxRangeBranchExtensionOffset);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, checked((ushort)(0x10000 - byteWidth)));
        Append(code, BranchHighWord);
        var planeRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeRangeBranchExtensionOffset);
        // Bound the final row address before publishing any byte.  The
        // multiply is unsigned WORDxWORD and the long add exposes 32-bit
        // address wrap through the carry flag; A3 remains the original plane
        // base for the row loop.
        Append(code, MoveWordD3ToD5);
        Append(code, MultiplyUnsignedWordD4ToD5);
        Append(code, MoveAddressD6ToA3);
        Append(code, MoveLongA3ToD6);
        Append(code, AddLongD5ToD6);
        Append(code, BranchCarryWord);
        var planeEndWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeEndWrapBranchExtensionOffset);
        if (byteWidth > 1)
        {
            Append(code, CompareImmediateLongD6);
            Append(code, 0xFFFF);
            Append(code, checked((ushort)(0x10000 - byteWidth)));
            Append(code, BranchHighWord);
            var planeEndByteRangeBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(planeEndByteRangeBranchExtensionOffset);
        }

        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var clearByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickMinusOneD0);
        Append(code, BranchAlwaysWord);
        var patternByteReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var clearByteOffset = code.Count;
        Append(code, MoveQuickZeroD0);

        var patternByteReadyOffset = code.Count;
        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordD4ToD5); // retain BytesPerRow as the row stride
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD3ToD6); // yMax
        // DBF executes once for an initial zero, so yMax already encodes the
        // final loop count (yMax + 1 rows) without an extra increment.

        var rowLoopOffset = code.Count;
        Append(code, MoveLongA3ToA0);
        Append(code, byteWidth switch
        {
            1 => MoveByteD0ToA0,
            2 => MoveWordD0ToA0,
            _ => MoveLongD0ToA0
        });
        if (byteWidth >= 8)
        {
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, 4);
            if (byteWidth >= 16)
            {
                Append(code, MoveLongD0ToA0Displacement);
                Append(code, 8);
                Append(code, MoveLongD0ToA0Displacement);
                Append(code, 12);
            }
        }
        Append(code, AddLongD5ToA3);
        Append(code, DecrementBranchD6);
        var rowLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var inverseNoOpSuccessOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        PatchBranch(code, inverseNoOpBranchExtensionOffset, inverseNoOpSuccessOffset);
        PatchBranch(code, clearByteBranchExtensionOffset, clearByteOffset);
        PatchBranch(code, patternByteReadyBranchExtensionOffset, patternByteReadyOffset);
        PatchBranch(code, rowLoopBranchExtensionOffset, rowLoopOffset);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendBltTemplate(
        List<byte> code,
        int fallbackEntryOffset,
        int byteWidth = 1)
    {
        if (byteWidth is not (1 or 2 or 4 or 8 or 16))
            throw new ArgumentOutOfRangeException(nameof(byteWidth));

        var offset = code.Count;
        var fallbackBranches = new List<int>(32);

        // Claim one deliberately small native template form: an aligned
        // eight-, sixteen-, thirty-two-, sixty-four-, or one-hundred-twenty-eight-pixel, all-on template repeated across SizeY rows
        // from a standard one-plane RastPort.  A zero source modulo repeats
        // the validated all-on source byte(s); JAM1 therefore reduces to
        // complete byte/word publication selected by APen bit zero.  General source masks,
        // nonzero source modulo, clipping, JAM2, complement/inverse modes,
        // layers, and provider surfaces stay on the portable/native-owner
        // path.
        Append(code, MoveLongD0ToD7); // preserve source X for fallback

        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var sourceNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var sourceOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceOddBranchExtensionOffset);
        if (byteWidth > 1)
        {
            // The admitted all-on source spans every byte of the selected
            // native width. Reject a high template whose final source byte
            // would wrap into unrelated low guest memory.
            Append(code, CompareImmediateLongD6);
            Append(code, 0xFFFF);
            Append(code, checked((ushort)(0x10000 - byteWidth)));
            Append(code, BranchHighWord);
            var sourceRangeBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(sourceRangeBranchExtensionOffset);
        }

        Append(code, MoveLongA1ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);

        Append(code, CompareImmediateWordD0);
        Append(code, 0); // source X == 0
        Append(code, BranchNotEqualWord);
        var sourceXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceXBranchExtensionOffset);
        Append(code, MoveWordD1ToD6);
        Append(code, CompareImmediateWordD6);
        Append(code, 0); // source Y == 0
        Append(code, BranchNotEqualWord);
        var sourceYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceYBranchExtensionOffset);
        Append(code, MoveWordD4ToD6);
        Append(code, CompareImmediateWordD6);
        Append(code, checked((ushort)(byteWidth * 8))); // SizeX == 8/16
        Append(code, BranchNotEqualWord);
        var widthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthBranchExtensionOffset);
        Append(code, MoveWordD5ToD6);
        Append(code, TestWordD6);
        Append(code, BranchEqualWord);
        var heightZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(heightZeroBranchExtensionOffset);

        Append(code, TestWordD2);
        Append(code, BranchMinusWord);
        var destinationXSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationXSignBranchExtensionOffset);
        Append(code, MoveWordD2ToD6);
        Append(code, AndImmediateWordD6);
        Append(code, 7);
        Append(code, TestWordD6);
        Append(code, BranchNotEqualWord);
        var destinationXAlignmentBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationXAlignmentBranchExtensionOffset);
        Append(code, TestWordD3);
        Append(code, BranchNotEqualWord);
        var destinationYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationYBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var layerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layerBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD6);
        Append(code, 0); // JAM1 only
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, BitTestImmediateD6);
        Append(code, 14);
        Append(code, BranchNotEqualWord);
        var noPensBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(noPensBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var bitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapRangeBranchExtensionOffset);
        Append(code, MoveAddressD6ToA2);

        Append(code, MoveByteA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var rowBytesZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesZeroBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rowBytesOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesOddBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var rowsZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsZeroBranchExtensionOffset);
        // CMP D1,D5 computes SizeY-Rows in D5.  BHI rejects only a height
        // beyond the bitmap while allowing the exact Rows-sized rectangle.
        Append(code, CompareWordD1ToD5);
        Append(code, BranchHighWord);
        var heightRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(heightRangeBranchExtensionOffset);
        Append(code, MoveWordD2ToD6);
        Append(code, ShiftRightWordD6Count3);
        if (byteWidth > 1)
        {
            // Compare the last touched byte without moving the destination
            // cursor off its byte-aligned start address.
            Append(code, MoveWordD6ToD3);
            Append(code, AddImmediateWordD3, 1);
            Append(code, CompareWordD3ToD4);
        }
        else
            Append(code, CompareWordD6ToD4);
        Append(code, BranchLowerOrSameWord);
        var xByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xByteBranchExtensionOffset);

        // Only y=0 is admitted, so the plane pointer needs no row addition.
        // Keep a conservative high-address guard for the final x-byte add.
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        // The final byte range is validated after the x/row arithmetic
        // below. This first probe merely admits the pointer value itself.
        Append(code, 0xFFFF);
        Append(code, BranchHighWord);
        var planeRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeRangeBranchExtensionOffset);

        // A source byte of FF is the only template content admitted by this
        // first native slice.  Read it before rebinding A0 to the destination.
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, BranchNotEqualWord);
        var sourceFirstByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceFirstByteBranchExtensionOffset);
        for (var sourceByteIndex = 1; sourceByteIndex < byteWidth; sourceByteIndex++)
        {
            Append(code, MoveByteA0DisplacementToD0);
            Append(code, checked((ushort)sourceByteIndex));
            Append(code, CompareImmediateWordD0);
            Append(code, 0x00FF);
            Append(code, BranchNotEqualWord);
            var sourceByteBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(sourceByteBranchExtensionOffset);
        }

        // The plane pointer is already in D4 from the guarded read above.
        // Re-read BytesPerRow into D1 only after the final source byte probe;
        // every branch that can decline still has the incoming D0 preserved
        // in D7.  The final-row offset is checked before the first write.
        Append(code, MoveQuickZeroD1);
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD5ToD0); // retain SizeY for the loop
        Append(code, SubQuickOneWordD0);
        Append(code, MultiplyUnsignedWordD1ToD0); // stride * (SizeY - 1)
        Append(code, ExtendLongD6);
        Append(code, AddLongD6ToD4); // row-zero x-byte
        Append(code, BranchCarryWord);
        var xAddressWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xAddressWrapBranchExtensionOffset);
        if (byteWidth > 1)
        {
            Append(code, CompareImmediateLongD4);
            Append(code, 0xFFFF);
            Append(code, checked((ushort)(0x10000 - byteWidth)));
            Append(code, BranchHighWord);
            var xAddressByteRangeBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(xAddressByteRangeBranchExtensionOffset);
        }
        Append(code, MoveAddressD4ToA0); // preserve row-zero destination
        Append(code, AddLongD0ToD4); // final row address
        Append(code, BranchCarryWord);
        var finalAddressWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(finalAddressWrapBranchExtensionOffset);
        if (byteWidth > 1)
        {
            Append(code, CompareImmediateLongD4);
            Append(code, 0xFFFF);
            Append(code, checked((ushort)(0x10000 - byteWidth)));
            Append(code, BranchHighWord);
            var finalAddressByteRangeBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(finalAddressByteRangeBranchExtensionOffset);
        }

        // All possible decline points are complete.  Rebind the volatile
        // registers for the native row loop without affecting fallback D0.
        Append(code, MoveQuickZeroD7);
        Append(code, MoveWordD1ToD7); // zero-extended BytesPerRow stride
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD5ToD6); // SizeY rows
        Append(code, MoveByteA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, BitTestImmediateD5);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var clearByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickMinusOneD0);
        Append(code, BranchAlwaysWord);
        var patternByteReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var clearByteOffset = code.Count;
        Append(code, MoveQuickZeroD0);

        var patternByteReadyOffset = code.Count;
        var rowLoopOffset = code.Count;
        Append(code, byteWidth switch
        {
            1 => MoveByteD0ToA0,
            2 => MoveWordD0ToA0,
            _ => MoveLongD0ToA0
        });
        if (byteWidth >= 8)
        {
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, 4);
            if (byteWidth >= 16)
            {
                Append(code, MoveLongD0ToA0Displacement);
                Append(code, 8);
                Append(code, MoveLongD0ToA0Displacement);
                Append(code, 12);
            }
        }
        Append(code, AddLongD7ToA0);
        Append(code, DecrementBranchD6);
        var rowLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, clearByteBranchExtensionOffset, clearByteOffset);
        PatchBranch(code, patternByteReadyBranchExtensionOffset, patternByteReadyOffset);
        PatchBranch(code, rowLoopBranchExtensionOffset, rowLoopOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendBltClear(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(8);

        // Claim only the scalar, zero/fill-word forms.  V36 row geometry
        // remains on the portable/provider path, while this compact body
        // keeps the classic void-vector D0/fallback shape.
        Append(code, MoveLongD0ToD7); // preserve the incoming byte count
        Append(code, MoveLongD1ToD6); // only scalar zero/fill flags are admitted
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var zeroCountBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 0xFFFF);
        Append(code, BranchHighWord);
        var countRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(countRangeBranchExtensionOffset);

        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var oneByteCountBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BitTestImmediateD7);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddCountBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BranchAlwaysWord);
        var evenCountSkipOneByteCheckExtensionOffset = code.Count;
        Append(code, 0);

        var oddCountEntryOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var oddCountFlagsJoinExtensionOffset = code.Count;
        Append(code, 0);

        // A single-byte native slice shares the validated zero/fill pattern
        // selection below.  The final byte is taken from the high byte of the
        // big-endian fill word, matching the prefix of an ordinary word walk.
        var oneByteCheckOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var oneByteFlagsJoinExtensionOffset = code.Count;
        Append(code, 0);

        var flagsEntryOffset = code.Count;
        PatchBranch(code, oneByteCountBranchExtensionOffset, oneByteCheckOffset);
        PatchBranch(code, oddCountBranchExtensionOffset, oddCountEntryOffset);
        PatchBranch(code, evenCountSkipOneByteCheckExtensionOffset, flagsEntryOffset);
        PatchBranch(code, oddCountFlagsJoinExtensionOffset, flagsEntryOffset);
        PatchBranch(code, oneByteFlagsJoinExtensionOffset, flagsEntryOffset);

        // Only bit 2 is meaningful in this scalar native slice.  The upper
        // flag word is admitted when fill-word mode is selected below.
        Append(code, MoveLongD6ToD1);
        Append(code, AndImmediateWordD1);
        Append(code, 0xFFFB);
        Append(code, TestWordD1);
        Append(code, BranchNotEqualWord);
        var flagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(flagsBranchExtensionOffset);

        Append(code, BitTestImmediateD6);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var zeroFillDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD6ToD0);
        Append(code, SwapD0);
        Append(code, MoveLongD0ToD4);
        Append(code, BranchAlwaysWord);
        var fillWordJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var zeroFillOffset = code.Count;
        Append(code, MoveLongD6ToD1);
        Append(code, SwapD1);
        Append(code, TestWordD1);
        Append(code, BranchNotEqualWord);
        var strayFillWordBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(strayFillWordBranchExtensionOffset);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToD4);

        var fillWordReadyOffset = code.Count;

        // A1 is a word-aligned guest address. Check the entire requested
        // scalar span rather than rejecting the whole top 64 KiB. The exact
        // final-byte endpoint is valid even though base + byteCount wraps to
        // zero in 32-bit arithmetic.
        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullBufferBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullBufferBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBufferBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddBufferBranchExtensionOffset);
        Append(code, MoveLongD7ToD5);
        Append(code, AddLongD0ToD5);
        Append(code, BranchCarryWord);
        var bufferEndCarryBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var bufferEndCheckedBranchExtensionOffset = code.Count;
        Append(code, 0);
        var bufferEndCarryOffset = code.Count;
        Append(code, TestLongD5);
        Append(code, BranchNotEqualWord);
        var wrappingBufferBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappingBufferBranchExtensionOffset);
        var bufferEndCheckedOffset = code.Count;

        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var oneByteWriteBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BitTestImmediateD7);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddWriteBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongD7ToD5);
        Append(code, ShiftRightWordD5);
        Append(code, SubQuickOneWordD5);
        var clearLoopOffset = code.Count;
        Append(code, MoveWordD0ToA1PostIncrement);
        Append(code, DecrementBranchD5);
        var clearLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BranchAlwaysWord);
        var normalSuccessSkipBranchExtensionOffset = code.Count;
        Append(code, 0);

        var oddWriteOffset = code.Count;
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongD7ToD5);
        Append(code, SubQuickOneWordD5);
        Append(code, ShiftRightWordD5);
        Append(code, SubQuickOneWordD5);
        var oddWordLoopOffset = code.Count;
        Append(code, MoveWordD0ToA1PostIncrement);
        Append(code, DecrementBranchD5);
        var oddWordLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD4ToD0);
        for (var index = 0; index < 8; index++)
            Append(code, ShiftRightLongD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0);
        Append(code, 0x00FF);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, 0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var oneByteWriteOffset = code.Count;
        Append(code, MoveLongD4ToD0);
        for (var index = 0; index < 8; index++)
            Append(code, ShiftRightLongD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0);
        Append(code, 0x00FF);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, 0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var successOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, zeroCountBranchExtensionOffset, successOffset);
        PatchBranch(code, zeroFillDispatchBranchExtensionOffset, zeroFillOffset);
        PatchBranch(code, fillWordJoinBranchExtensionOffset, fillWordReadyOffset);
        PatchBranch(code, bufferEndCarryBranchExtensionOffset, bufferEndCarryOffset);
        PatchBranch(code, bufferEndCheckedBranchExtensionOffset, bufferEndCheckedOffset);
        PatchBranch(code, oneByteWriteBranchExtensionOffset, oneByteWriteOffset);
        PatchBranch(code, oddWriteBranchExtensionOffset, oddWriteOffset);
        PatchBranch(code, oddWordLoopBranchExtensionOffset, oddWordLoopOffset);
        PatchBranch(code, clearLoopBranchExtensionOffset, clearLoopOffset);
        PatchBranch(code, normalSuccessSkipBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendSetRast(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(20);

        // SetRast is an unconditional standard-planar initialization: it
        // ignores DrawMode, applies the RastPort write mask to the declared
        // depth, and fills every byte of each selected plane with the
        // requested pen bit.  The native overlay validates the complete
        // selected-plane envelope before dispatch; this body repeats the
        // structural guards and performs a pointer-only preflight so a late
        // missing selected plane cannot partially mutate an earlier plane.
        // Keep the incoming pen intact on every decline.  The provider can
        // then interpret layered/private-colour forms without seeing native
        // scratch state in D0.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var layerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layerBranchExtensionOffset);
        Append(code, MoveQuickZeroD1);
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, BitTestImmediateD1);
        Append(code, 14); // RPF_NO_PENS
        Append(code, BranchNotEqualWord);
        var noPensBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(noPensBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var bitmapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD2);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var bitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapRangeBranchExtensionOffset);

        Append(code, MoveAddressD2ToA0);
        Append(code, MoveQuickZeroD1);
        Append(code, MoveByteA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var bitmapFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapFlagsBranchExtensionOffset);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, TestLongD3);
        Append(code, BranchEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);

        Append(code, CompareImmediateByteD3);
        Append(code, 0x0008);
        Append(code, BranchHighWord);
        var depthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthRangeBranchExtensionOffset);

        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rowBytesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesBranchExtensionOffset);
        Append(code, TestWordD4);
        Append(code, BranchMinusWord);
        var rowBytesSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesSignBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rowBytesOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesOddBranchExtensionOffset);

        Append(code, MoveQuickZeroD2);
        Append(code, MoveWordA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);
        Append(code, TestWordD2);
        Append(code, BranchMinusWord);
        var rowsSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsSignBranchExtensionOffset);

        // The positive word dimensions have a bounded non-wrapping product.
        // Retain it for selected-plane endpoint preflight before publication.
        Append(code, MoveLongD2ToD5);
        Append(code, MultiplyUnsignedWordD4ToD5);

        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var zeroMaskBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Retain the bitmap address for both the pointer preflight and the
        // subsequent fill pass.  A2 is the current plane-link cursor.
        Append(code, MoveLongA0ToA3);
        Append(code, MoveAddressA0ToA2);
        Append(code, AddQuickEightLongA2);
        Append(code, MoveQuickZeroD7);
        Append(code, SubQuickOneWordD3);

        var preflightLoopOffset = code.Count;
        Append(code, BitTestDynamicD7ToD6);
        Append(code, BranchEqualWord);
        var preflightSkipBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA2IndirectToA0);
        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var planePointerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planePointerBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planePointerOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planePointerOddBranchExtensionOffset);
        Append(code, AddLongD5ToD1);
        Append(code, BranchCarryWord);
        var planeEndpointCarryBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var planeEndpointCheckedBranchExtensionOffset = code.Count;
        Append(code, 0);
        var planeEndpointCarryOffset = code.Count;
        // An exclusive endpoint of zero is the valid plane span ending at
        // $FFFF_FFFF. Every other carry is a true address wrap.
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var planeEndpointBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeEndpointBranchExtensionOffset);

        var preflightSkipOffset = code.Count;
        Append(code, AddQuickFourLongA2);
        Append(code, AddQuickOneLongD7);
        Append(code, DecrementBranchD3);
        var preflightLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Rewind to the first plane and re-read the depth for the publication
        // pass; the preflight consumed D3 and advanced A2.
        Append(code, MoveLongA3ToA0);
        Append(code, MoveAddressA0ToA2);
        Append(code, AddQuickEightLongA2);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA3DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, MoveQuickZeroD7);
        Append(code, SubQuickOneWordD3);

        var fillPlaneLoopOffset = code.Count;
        Append(code, BitTestDynamicD7ToD6);
        Append(code, BranchEqualWord);
        var fillPlaneSkipBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA2IndirectToA0);
        Append(code, BitTestDynamicD7ToD0);
        Append(code, SetNotEqualByteD1);
        Append(code, MoveLongD2ToD5);
        Append(code, MultiplyUnsignedWordD4ToD5);

        var fillByteLoopOffset = code.Count;
        Append(code, MoveByteD1ToA0PostIncrement);
        Append(code, SubQuickOneLongD5);
        Append(code, BranchNotEqualWord);
        var fillByteBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fillPlaneSkipOffset = code.Count;
        Append(code, AddQuickFourLongA2);
        Append(code, AddQuickOneLongD7);
        Append(code, DecrementBranchD3);
        var fillPlaneBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, preflightSkipBranchExtensionOffset, preflightSkipOffset);
        PatchBranch(code, planeEndpointCarryBranchExtensionOffset, planeEndpointCarryOffset);
        PatchBranch(code, planeEndpointCheckedBranchExtensionOffset, preflightSkipOffset);
        PatchBranch(code, preflightLoopBranchExtensionOffset, preflightLoopOffset);
        PatchBranch(code, fillPlaneSkipBranchExtensionOffset, fillPlaneSkipOffset);
        PatchBranch(code, fillByteBranchExtensionOffset, fillByteLoopOffset);
        PatchBranch(code, fillPlaneBranchExtensionOffset, fillPlaneLoopOffset);
        PatchBranch(code, zeroMaskBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);

        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendRectFill(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(16);

        // This body claims the ordinary one-plane JAM1/JAM2 rectangle.  The
        // register adapter preflights the complete clipped destination span;
        // the body additionally rejects negative/inverted WORD geometry so a
        // future raw-ROM caller cannot turn an unsupported rectangle into a
        // host-specific address walk.  Other draw modes, depths, masks, and
        // provider/layer surfaces remain on the shared fallback.
        Append(code, TestWordD0);
        Append(code, BranchMinusWord);
        var xMinSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMinSignBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchMinusWord);
        var yMinSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMinSignBranchExtensionOffset);
        Append(code, TestWordD2);
        Append(code, BranchMinusWord);
        var xMaxSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMaxSignBranchExtensionOffset);
        Append(code, TestWordD3);
        Append(code, BranchMinusWord);
        var yMaxSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMaxSignBranchExtensionOffset);

        Append(code, CompareWordD0ToD2);
        Append(code, BranchCarryWord);
        var xOrderBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xOrderBranchExtensionOffset);
        Append(code, CompareWordD1ToD3);
        Append(code, BranchCarryWord);
        var yOrderBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yOrderBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var bitmapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapBranchExtensionOffset);
        Append(code, MoveAddressD4ToA0);

        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, SubQuickOneWordD3);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);

        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rowBytesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var planeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeBranchExtensionOffset);
        Append(code, MoveAddressD5ToA3);

        Append(code, MoveQuickZeroD5);
        Append(code, MoveByteA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        // For a NULL area pattern, ordinary JAM2 has the same foreground
        // source as JAM1.  Clear the JAM2 bit while rejecting every richer
        // mode (COMPLEMENT/INVERSVID); the writer below still consumes only
        // FgPen and therefore preserves the classic one-plane fill.
        Append(code, AndImmediateWordD5);
        Append(code, 0xFFFE);
        Append(code, TestLongD5);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);

        Append(code, MoveQuickZeroD5);
        Append(code, MoveByteA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BitTestImmediateD5);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);

        Append(code, MoveQuickZeroD5);
        Append(code, MoveByteA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, AndImmediateWordD5);
        Append(code, 0x0001);

        // Save xMin in A4.  D1 remains the signed yMin until the initial row
        // displacement is calculated; D2 remains xMax for the inner loop.
        Append(code, MoveWordD0ToD7);
        Append(code, ExtendLongD7);
        Append(code, MoveAddressD7ToA4);
        Append(code, MultiplySignedWordD4ToD1);
        Append(code, MoveWordD0ToD7);
        Append(code, ShiftRightWordD7Count3);
        Append(code, ExtendLongD7);
        Append(code, AddLongD7ToD1);
        Append(code, MoveAddressA3ToA5);
        Append(code, AddLongD1ToA5);

        Append(code, SubWordD1ToD3);
        Append(code, AddQuickOneWordD3);
        Append(code, SubQuickOneWordD3);

        var rowLoopOffset = code.Count;
        Append(code, MoveLongA4ToD0);
        Append(code, MoveAddressA5ToA0);

        var pixelLoopOffset = code.Count;
        Append(code, MoveLongD0ToD6);
        Append(code, AndImmediateWordD6);
        Append(code, 0x0007);
        Append(code, ExclusiveOrImmediateWordD6);
        Append(code, 0x0007);
        Append(code, MoveWordD0ToD7);
        Append(code, ShiftRightWordD7Count3);
        Append(code, ExtendLongD7);
        Append(code, MoveAddressA0ToA2);
        Append(code, AddLongD7ToA2);

        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var clearPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitSetDynamicD6AtA2);
        Append(code, BranchAlwaysWord);
        var afterPixelBranchExtensionOffset = code.Count;
        Append(code, 0);

        var clearPixelOffset = code.Count;
        Append(code, BitClearDynamicD6AtA2);

        var afterPixelOffset = code.Count;
        Append(code, AddQuickOneWordD0);
        Append(code, CompareWordD2ToD0);
        Append(code, BranchLowerOrSameWord);
        var pixelLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, AddLongD4ToA5);
        Append(code, DecrementBranchD3);
        var rowLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        PatchBranch(code, clearPixelBranchExtensionOffset, clearPixelOffset);
        PatchBranch(code, afterPixelBranchExtensionOffset, afterPixelOffset);
        PatchBranch(code, pixelLoopBranchExtensionOffset, pixelLoopOffset);
        PatchBranch(code, rowLoopBranchExtensionOffset, rowLoopOffset);

        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    private static int AppendRectFillMultiPlane(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(28);

        // This companion body deliberately claims one small, but useful,
        // multi-plane form: an ordered span of one or more aligned
        // one-through-sixteen-byte rows on a standard planar depth-2..8 bitmap,
        // with JAM1 and a depth-sized write mask. Keeping the form exact
        // gives the resident path bounded row/depth loops without pretending
        // to implement clipping, patterns, minterms, or provider-owned
        // surfaces here.
        // Keep the complete incoming D0 on the guest stack while D7 becomes
        // the plane-index cursor used by masked preflight/publication.
        Append(code, MoveLongD0ToPreDecrementA7);

        Append(code, TestWordD0);
        Append(code, BranchMinusWord);
        var xMinSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMinSignBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchMinusWord);
        var yMinSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMinSignBranchExtensionOffset);
        Append(code, TestWordD2);
        Append(code, BranchMinusWord);
        var xMaxSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMaxSignBranchExtensionOffset);
        Append(code, TestWordD3);
        Append(code, BranchMinusWord);
        var yMaxSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMaxSignBranchExtensionOffset);

        // xMin must be byte aligned and xMax must complete exactly one through
        // sixteen bytes. A6 carries the accepted byte-count minus one (0..15)
        // across the preflight and publication passes.
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD0ToD6);
        Append(code, AndImmediateWordD6);
        Append(code, 0x0007);
        Append(code, TestWordD6);
        Append(code, BranchNotEqualWord);
        var xAlignmentBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xAlignmentBranchExtensionOffset);
        Append(code, MoveWordD2ToD6);
        Append(code, SubWordD0ToD6);
        Append(code, CompareImmediateWordD6);
        Append(code, 127);
        Append(code, BranchEqualWord);
        var widthOneHundredTwentyEightByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 7);
        Append(code, BranchEqualWord);
        var widthOneByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 15);
        Append(code, BranchEqualWord);
        var widthTwoByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 23);
        Append(code, BranchEqualWord);
        var widthThreeByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 31);
        Append(code, BranchEqualWord);
        var widthFourByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 39);
        Append(code, BranchEqualWord);
        var widthFiveByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 47);
        Append(code, BranchEqualWord);
        var widthSixByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 55);
        Append(code, BranchEqualWord);
        var widthSevenByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 63);
        Append(code, BranchNotEqualWord);
        var widthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthBranchExtensionOffset);

        // Each accepted form carries its byte-count marker through the same
        // nested row/plane loops; larger forms are laid out first so every
        // exact-width branch lands on the matching marker and then converges
        // on one common continuation.
        var widthEightByteSetupOffset = code.Count;
        Append(code, MoveQuickSevenD6);
        Append(code, MoveAddressD6ToA6);
        Append(code, BranchAlwaysWord);
        var widthEightByteAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthSevenByteSetupOffset = code.Count;
        Append(code, MoveQuickSixD6);
        Append(code, MoveAddressD6ToA6);
        Append(code, BranchAlwaysWord);
        var widthSevenByteAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthSixByteSetupOffset = code.Count;
        Append(code, MoveQuickFiveD6);
        Append(code, MoveAddressD6ToA6);
        Append(code, BranchAlwaysWord);
        var widthSixByteAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthFiveByteSetupOffset = code.Count;
        Append(code, MoveQuickFourD6);
        Append(code, MoveAddressD6ToA6);
        Append(code, BranchAlwaysWord);
        var widthFiveByteAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthFourByteSetupOffset = code.Count;
        Append(code, MoveQuickThreeD6);
        Append(code, MoveAddressD6ToA6);
        Append(code, BranchAlwaysWord);
        var widthFourByteAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthThreeByteSetupOffset = code.Count;
        Append(code, MoveQuickTwoD6);
        Append(code, MoveAddressD6ToA6);
        Append(code, BranchAlwaysWord);
        var widthThreeByteAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthTwoByteSetupOffset = code.Count;
        Append(code, MoveQuickOneD6);
        Append(code, MoveAddressD6ToA6);
        Append(code, BranchAlwaysWord);
        var widthTwoByteAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthOneByteSetupOffset = code.Count;
        Append(code, MoveQuickZeroD6);
        Append(code, MoveAddressD6ToA6);
        Append(code, BranchAlwaysWord);
        var widthOneByteAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthOneHundredTwentyEightByteSetupOffset = code.Count;
        // MOVE.W preserves the upper half of D6, so clear it first before
        // publishing the sixteen-byte marker used by the aligned 128-pixel
        // row arm.  This setup is placed after the ordinary fall-through
        // chain, so the legacy one-through-eight-byte forms still enter the
        // eight-byte marker when the 128-pixel compare is not equal.
        Append(code, MoveQuickZeroD6);
        Append(code, MoveImmediateWordD6);
        Append(code, 15);
        Append(code, MoveAddressD6ToA6);
        Append(code, BranchAlwaysWord);
        var widthOneHundredTwentyEightByteAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthAcceptedOffset = code.Count;
        PatchBranch(code, widthOneHundredTwentyEightByteBranchExtensionOffset, widthOneHundredTwentyEightByteSetupOffset);
        PatchBranch(code, widthFourByteBranchExtensionOffset, widthFourByteSetupOffset);
        PatchBranch(code, widthFiveByteBranchExtensionOffset, widthFiveByteSetupOffset);
        PatchBranch(code, widthSixByteBranchExtensionOffset, widthSixByteSetupOffset);
        PatchBranch(code, widthSevenByteBranchExtensionOffset, widthSevenByteSetupOffset);
        PatchBranch(code, widthFourByteAcceptedBranchExtensionOffset, widthAcceptedOffset);
        PatchBranch(code, widthThreeByteAcceptedBranchExtensionOffset, widthAcceptedOffset);
        PatchBranch(code, widthTwoByteAcceptedBranchExtensionOffset, widthAcceptedOffset);
        PatchBranch(code, widthOneByteAcceptedBranchExtensionOffset, widthAcceptedOffset);
        PatchBranch(code, widthEightByteAcceptedBranchExtensionOffset, widthAcceptedOffset);
        PatchBranch(code, widthSevenByteAcceptedBranchExtensionOffset, widthAcceptedOffset);
        PatchBranch(code, widthSixByteAcceptedBranchExtensionOffset, widthAcceptedOffset);
        PatchBranch(code, widthFiveByteAcceptedBranchExtensionOffset, widthAcceptedOffset);
        PatchBranch(code, widthOneByteBranchExtensionOffset, widthOneByteSetupOffset);
        PatchBranch(code, widthTwoByteBranchExtensionOffset, widthTwoByteSetupOffset);
        PatchBranch(code, widthThreeByteBranchExtensionOffset, widthThreeByteSetupOffset);
        PatchBranch(code, widthOneHundredTwentyEightByteAcceptedBranchExtensionOffset, widthAcceptedOffset);

        // D2 is no longer needed as xMax after width admission. Preserve the
        // requested yMin while D1 is reused for the public bitmap row count.
        Append(code, MoveWordD1ToD5);
        Append(code, CompareWordD5ToD3);
        Append(code, BranchCarryWord);
        var yOrderBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yOrderBranchExtensionOffset);

        // Preserve the bitmap pointer in A4 while D4 is reused for the row
        // stride.  A1 is the public RastPort pointer and is never changed.
        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var bitmapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, MoveAddressD4ToA4);
        Append(code, MoveAddressD4ToA0);

        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);

        // The signed-WORD admission above and the public row-count check below
        // provide the complete nonnegative y envelope.  The final-byte carry
        // preflight still rejects any wrapped plane address before mutation.
        Append(code, CompareWordD3ToD1);
        Append(code, BranchLowerOrSameWord);
        var rowsRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsRangeBranchExtensionOffset);

        // Preserve the inclusive DBRA distance before D3 is reused for depth.
        // DBRA executes distance+1 rows, so yMax-yMin is the exact value.
        Append(code, MoveWordD3ToD2);
        Append(code, SubWordD5ToD2);

        // Keep yMin outside the later marker comparison and plane preflight.
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD5ToD6);
        Append(code, MoveAddressD6ToA5);

        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD3);
        Append(code, 2);
        Append(code, BranchCarryWord);
        var depthLowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthLowBranchExtensionOffset);
        Append(code, CompareImmediateByteD3);
        Append(code, 8);
        Append(code, BranchHighWord);
        var depthHighBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthHighBranchExtensionOffset);

        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var rowBytesZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesZeroBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rowBytesOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesOddBranchExtensionOffset);

        // The byte containing xMin plus the accepted byte-count marker must
        // remain inside the declared row.
        Append(code, MoveWordD0ToD6);
        Append(code, ShiftRightWordD6Count3);
        Append(code, MoveWordD6ToD5); // retain x-byte before marker addition
        Append(code, MoveLongA6ToD1);
        Append(code, AddWordD1ToD6);
        Append(code, CompareWordD6ToD4);
        Append(code, BranchLowerOrSameWord);
        var xByteRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xByteRangeBranchExtensionOffset);
        // Restore yMin after the marker comparison; D5 now carries the
        // accepted x-byte offset for publication.
        Append(code, MoveLongA5ToD1);
        // Only the ordinary JAM1 planar form is claimed here.  Byte loads
        // leave the upper register bits unchanged on 68k, so clear D4 before
        // each byte-sized state read.
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        // A zero write mask is a successful no-op once the same geometry,
        // bitmap, depth, stride, and ordinary-JAM1 admission has succeeded.
        // Keep the branch outside the plane preflight: no plane is selected,
        // so a valid no-op must not read or publish any plane byte.
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var zeroMaskBranchExtensionOffset = code.Count;
        Append(code, 0);
        // The mask byte occupied D4 during admission. Restore the declared
        // planar row stride before the publication loop reuses it for each
        // subsequent row.
        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveByteA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, AndImmediateLongD0);
        Append(code, 0x0000);
        Append(code, 0x00FF);

        // Read-only preflight of every declared plane.  Keep the plane-array
        // cursor in A2 and a restart copy in A3 so a missing later plane can
        // never leave an earlier plane byte published.
        // BitMap.Planes is an inline eight-LONG array, not a pointer to an
        // external table.  Start at the first inline element and preflight
        // each declared plane link below.
        Append(code, MoveAddressA0ToA2);
        Append(code, AddQuickEightLongA2);
        Append(code, MoveAddressA2ToA3);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, SubQuickOneWordD3);
        Append(code, MoveQuickZeroD7);

        var preflightLoopOffset = code.Count;
        Append(code, MoveLongA2IndirectToA0);
        // Only selected planes need a readable/even link and final-address
        // carry preflight. Unselected planes remain untouched by the mask.
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BitTestDynamicD7ToD0);
        Append(code, BranchEqualWord);
        var preflightSkipPlaneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        // Check the final byte of this plane's selected span before any plane
        // can publish. The bounded yMax/stride product plus x-byte and the
        // width marker must not carry through the guest address limit.
        Append(code, MoveLongA5ToD6);
        Append(code, AddLongD2ToD6);
        Append(code, MultiplyUnsignedWordD4ToD6);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD5ToD0);
        Append(code, AddLongD0ToD6);
        Append(code, MoveLongA6ToD0);
        Append(code, AddLongD0ToD6);
        Append(code, AddLongD6ToD1);
        Append(code, BranchCarryWord);
        var planeAddressCarryBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeAddressCarryBranchExtensionOffset);
        var preflightNextPlaneOffset = code.Count;
        Append(code, AddQuickFourLongA2);
        Append(code, AddQuickOneLongD7);
        Append(code, DecrementBranchD3);
        var preflightLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        // The preflight used D0 as arithmetic scratch; reload the selected
        // APen before the publication pass.
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, AndImmediateLongD0);
        Append(code, 0x0000);
        Append(code, 0x00FF);

        // Publication pass. Plane index D7 selects both the write-mask bit
        // and the APen bit; D6 becomes the complete byte value for each row
        // in the selected y span.
        Append(code, MoveAddressA3ToA2);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, SubQuickOneWordD3);
        // D1 is the mutable DBRA row counter. Preserve yMin in A4 after the
        // depth read so every selected plane starts at the same row origin.
        Append(code, MoveLongA5ToD6);
        Append(code, MoveAddressD6ToA4);
        Append(code, MoveQuickZeroD7);

        var writePlaneLoopOffset = code.Count;
        Append(code, MoveLongA2IndirectToA0);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BitTestDynamicD7ToD6);
        Append(code, BranchEqualWord);
        var publicationSkipPlaneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressA0ToA5);
        // Start at plane0 + yMin*BytesPerRow + xMin/8. A4 retains yMin;
        // D5 carries the accepted x-byte offset.
        Append(code, MoveQuickZeroD6);
        Append(code, MoveLongA4ToD6);
        Append(code, MultiplyUnsignedWordD4ToD6);
        Append(code, AddLongD6ToA5);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD5ToD6);
        Append(code, AddLongD6ToA5);
        Append(code, BitTestDynamicD7ToD0);
        Append(code, BranchEqualWord);
        var clearBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickMinusOneD6);
        Append(code, BranchAlwaysWord);
        var writeNextBranchExtensionOffset = code.Count;
        Append(code, 0);
        var clearBranchOffset = code.Count;
        Append(code, MoveQuickZeroD6);
        var writeNextOffset = code.Count;
        // A6 carries byte-count minus one, so a nested DBRA loop publishes
        // one through sixteen legal byte stores per row. D1 is the outer row
        // counter; D2 retains the immutable row count for each plane and D0
        // is scratch for the inner byte counter.
        Append(code, MoveWordD2ToD1);
        var rowLoopOffset = code.Count;
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA6ToD0);
        var byteLoopOffset = code.Count;
        Append(code, MoveByteD6ToA0PostIncrement);
        Append(code, DecrementBranchD0);
        var byteLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, AddLongD4ToA5);
        Append(code, DecrementBranchD1);
        var rowLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        var afterRowLoopOffset = code.Count;
        Append(code, AddQuickFourLongA2);
        Append(code, AddQuickOneLongD7);
        Append(code, DecrementBranchD3);
        var writePlaneLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, preflightLoopBranchExtensionOffset, preflightLoopOffset);
        PatchBranch(code, preflightSkipPlaneBranchExtensionOffset, preflightNextPlaneOffset);
        PatchBranch(code, clearBranchExtensionOffset, clearBranchOffset);
        PatchBranch(code, writeNextBranchExtensionOffset, writeNextOffset);
        PatchBranch(code, byteLoopBranchExtensionOffset, byteLoopOffset);
        PatchBranch(code, rowLoopBranchExtensionOffset, rowLoopOffset);
        PatchBranch(code, writePlaneLoopBranchExtensionOffset, writePlaneLoopOffset);
        PatchBranch(code, publicationSkipPlaneBranchExtensionOffset, afterRowLoopOffset);
        PatchBranch(code, zeroMaskBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        // The body is emitted before the dispatch wrapper; all branches above
        // are therefore short and remain relocatable inside the native HUNK.
        return offset;
    }

    private static int AppendRectFillDispatch(
        List<byte> code,
        int fallbackEntryOffset,
        int onePlaneEntryOffset,
        int multiPlaneEntryOffset)
    {
        var offset = code.Count;

        // Preserve the original full D0 while choosing the depth-specialized
        // body.  The two target bodies perform their own complete admission;
        // this wrapper only avoids sending depth-2..8 calls through the
        // one-plane implementation.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        // The dispatch reads fields across the complete public RastPort
        // envelope below. Do not let a wrapped header alias low guest memory
        // before either depth-specialized body gets a chance to decline it.
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C);
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        // BitMap.Planes is part of the standard 40-byte public header, so
        // admission must cover the whole header rather than only its depth
        // byte. This keeps wrapped guest structures on the shared fallback.
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var bitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveAddressD0ToA0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD0);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var onePlaneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD0);
        Append(code, 2);
        Append(code, BranchCarryWord);
        var depthLowBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD0);
        Append(code, 8);
        Append(code, BranchHighWord);
        var depthHighBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var multiPlaneJumpExtensionOffset = code.Count;
        Append(code, 0);

        var onePlaneDispatchOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var onePlaneJumpExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, rastPortNullBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, rastPortOddBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, rastPortRangeBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, bitmapNullBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, bitmapOddBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, bitmapRangeBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, onePlaneBranchExtensionOffset, onePlaneDispatchOffset);
        PatchBranch(code, depthLowBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, depthHighBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, multiPlaneJumpExtensionOffset, multiPlaneEntryOffset);
        PatchBranch(code, onePlaneJumpExtensionOffset, onePlaneEntryOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    private static int AppendDraw(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(24);

        // This body deliberately claims only the smallest useful native Draw
        // envelope: a fresh horizontal (forward or reverse) or vertical
        // (forward or reverse) line on a one-plane standard bitmap.  The
        // implicit source is one; all-ones patterns and non-inverse JAM1
        // patterns (including COMPLEMENT|JAM1) are sampled natively.  JAM2
        // and inverse-video patterned source selection still use the richer
        // portable/provider path, as do Bresenham slopes, connected
        // endpoints, and every layered/non-planar surface.
        Append(code, TestWordD0);
        Append(code, BranchMinusWord);
        var targetXSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(targetXSignBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchMinusWord);
        var targetYSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(targetYSignBranchExtensionOffset);

        Append(code, MoveQuickZeroD2);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentX));
        Append(code, TestWordD2);
        Append(code, BranchMinusWord);
        var currentXSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(currentXSignBranchExtensionOffset);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveWordA1DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentY));
        Append(code, TestWordD3);
        Append(code, BranchMinusWord);
        var currentYSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(currentYSignBranchExtensionOffset);

        // Horizontal lines take the first path.  If Y differs, the second
        // path accepts a positive or reverse vertical line.  D5 holds the major
        // distance and D7 is an orientation marker until the shared address
        // setup has completed: 0 is forward horizontal, 1 is vertical, and
        // 2 is reverse horizontal, and 3 is reverse vertical.
        Append(code, CompareWordD3ToD1);
        Append(code, BranchNotEqualWord);
        var notHorizontalBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareWordD2ToD0);
        Append(code, BranchCarryWord);
        var horizontalOrderBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveWordD0ToD5);
        Append(code, SubWordD2ToD5);
        Append(code, MoveQuickZeroD7);
        Append(code, BranchAlwaysWord);
        var commonSetupBranchExtensionOffset = code.Count;
        Append(code, 0);

        var reverseHorizontalGeometryOffset = code.Count;
        Append(code, MoveWordD2ToD5);
        Append(code, SubWordD0ToD5);
        Append(code, MoveQuickTwoD7);
        Append(code, BranchAlwaysWord);
        var reverseCommonSetupBranchExtensionOffset = code.Count;
        Append(code, 0);

        var verticalGeometryOffset = code.Count;
        Append(code, CompareWordD2ToD0);
        Append(code, BranchNotEqualWord);
        var verticalXOrderBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(verticalXOrderBranchExtensionOffset);
        Append(code, CompareWordD3ToD1);
        Append(code, BranchCarryWord);
        var verticalOrderBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveWordD1ToD5);
        Append(code, SubWordD3ToD5);
        Append(code, MoveQuickOneD7);

        Append(code, BranchAlwaysWord);
        var verticalCommonSetupBranchExtensionOffset = code.Count;
        Append(code, 0);

        var reverseVerticalGeometryOffset = code.Count;
        Append(code, MoveWordD3ToD5);
        Append(code, SubWordD1ToD5);
        Append(code, MoveQuickThreeD7);
        Append(code, BranchAlwaysWord);
        var reverseVerticalCommonSetupBranchExtensionOffset = code.Count;
        Append(code, 0);

        var commonSetupOffset = code.Count;
        // D0 carries the target X at entry, but patterned loops use it as a
        // temporary pattern word.  A5 is otherwise unused by Draw and keeps
        // the original target available for final cursor publication.
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var bitmapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapBranchExtensionOffset);
        Append(code, MoveAddressD4ToA0);

        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);

        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rowBytesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var planeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeBranchExtensionOffset);
        Append(code, MoveAddressD6ToA3);

        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        // Admit modes 0/1/2/3/4/5.  Modes 6/7 combine COMPLEMENT with
        // INVERSVID and remain on the portable fallback until the richer
        // source/pen interaction is implemented natively.
        Append(code, BitTestImmediateD4);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var drawModeValidationBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD4);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        var drawModeValidationOffset = code.Count;
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var firstDotBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(firstDotBranchExtensionOffset);
        // ONE_DOT/SING suppresses repeated samples on a horizontal raster;
        // the native fast path owns complete fresh-line traversal, so leave
        // this row-suppression mode to the portable Bresenham implementation.
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, BitTestImmediateD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var oneDotBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oneDotBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePattern));
        Append(code, CompareImmediateWordD4);
        Append(code, 0xFFFF);
        Append(code, BranchEqualWord);
        var patternEqualBranchExtensionOffset = code.Count;
        Append(code, 0);
        // Non-all-ones patterns are claimed only for non-inverse JAM1.  The
        // native loop can skip clear pattern cells, while JAM2 and INVERSVID
        // still require the richer portable/provider source selection.
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var patternJam2BranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(patternJam2BranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var patternInverseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(patternInverseBranchExtensionOffset);
        var patternAcceptedOffset = code.Count;

        // Sample the current line-pattern bit for the native non-inverse
        // JAM1 envelope.  D2 retains the initial major distance and D5 the
        // remaining distance, so their difference matches the portable
        // phase formula (linePatternCount-majorStep)&15.
        // D7 carries the selected pen for ordinary JAM1; A2 is otherwise
        // scratch in Draw and preserves it across the pattern calculation.
        (int PatternBranchExtensionOffset,
            int ClearRestoreOffset,
            int SetContinueBranchExtensionOffset,
            int ClearContinueBranchExtensionOffset) AppendPatternGate()
        {
            Append(code, MoveWordD7ToA2);
            Append(code, MoveWordD3ToD7);
            Append(code, MoveWordD2ToD3);
            Append(code, SubWordD5ToD3);
            Append(code, MoveQuickZeroD0);
            Append(code, MoveWordA1DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.RastPortLinePattern));
            Append(code, MoveQuickZeroD4);
            Append(code, MoveByteA1DisplacementToD4);
            Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
            Append(code, SubWordD3ToD4);
            Append(code, AndImmediateWordD4);
            Append(code, 0x000F);
            Append(code, BitTestDynamicD4ToD0);
            Append(code, BranchEqualWord);
            var patternBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveWordD7ToD3);
            Append(code, MoveWordA2ToD7);
            Append(code, MoveWordA0DisplacementToD4);
            Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
            Append(code, BranchAlwaysWord);
            var setContinueBranchExtensionOffset = code.Count;
            Append(code, 0);

            var clearRestoreOffset = code.Count;
            Append(code, MoveWordD7ToD3);
            Append(code, MoveWordA2ToD7);
            Append(code, MoveWordA0DisplacementToD4);
            Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
            Append(code, BranchAlwaysWord);
            var clearContinueBranchExtensionOffset = code.Count;
            Append(code, 0);
            return (
                patternBranchExtensionOffset,
                clearRestoreOffset,
                setContinueBranchExtensionOffset,
                clearContinueBranchExtensionOffset);
        }

        // A4 is the current planar byte.  D4 is the row stride, D6 the
        // Amiga MSB-first bit number, and D7 remains the orientation marker.
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveAddressA3ToA4);
        Append(code, MultiplyUnsignedWordD4ToD3);
        Append(code, AddLongD3ToA4);
        Append(code, MoveWordD2ToD6);
        Append(code, ShiftRightWordD6Count3);
        Append(code, ExtendLongD6);
        Append(code, AddLongD6ToA4);
        Append(code, MoveWordD2ToD6);
        Append(code, AndImmediateWordD6);
        Append(code, 7);
        Append(code, ExclusiveOrImmediateWordD6);
        Append(code, 7);
        // D2 is no longer needed for address setup; retain the initial major
        // distance so every patterned loop iteration can derive its phase.
        Append(code, MoveWordD5ToD2);
        Append(code, CompareImmediateWordD7);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var reverseDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD7);
        Append(code, 3);
        Append(code, BranchEqualWord);
        var reverseVerticalDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, TestLongD7);
        Append(code, BranchNotEqualWord);
        var verticalLoopDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BranchAlwaysWord);
        var horizontalDirectionFallthroughBranchExtensionOffset = code.Count;
        Append(code, 0);

        var reverseVerticalDirectionOffset = code.Count;
        Append(code, MoveQuickOneD3);
        Append(code, BranchAlwaysWord);
        var reverseVerticalPenDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);

        var horizontalDirectionOffset = code.Count;
        Append(code, MoveQuickZeroD3);
        Append(code, BranchAlwaysWord);
        var horizontalPenDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);

        var reverseDirectionOffset = code.Count;
        Append(code, MoveQuickOneD3);
        var penDispatchOffset = code.Count;

        // Select the pen for source-one samples.  Non-inverse COMPLEMENT
        // dispatches to a BCHG loop; inverse JAM1 skips the raster loop but
        // still reaches the common cursor/phase publication.
        Append(code, MoveByteA1DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, BitTestImmediateD7);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var horizontalComplementBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteA1DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, BitTestImmediateD7);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var horizontalForegroundBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD7);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var horizontalInverseNoOpBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD7);
        Append(code, MoveByteA1DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, AndImmediateWordD7);
        Append(code, 1);
        Append(code, BranchAlwaysWord);
        var horizontalBackgroundLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        var horizontalForegroundPathOffset = code.Count;
        Append(code, MoveQuickZeroD7);
        Append(code, MoveByteA1DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, AndImmediateWordD7);
        Append(code, 1);
        Append(code, BranchAlwaysWord);
        var horizontalForegroundLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var horizontalLoopSelectorOffset = code.Count;
        Append(code, TestLongD3);
        Append(code, BranchNotEqualWord);
        var horizontalReverseLoopDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var horizontalForwardLoopDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);

        var horizontalPatternGateOffset = code.Count;
        var horizontalPatternGateBranches = AppendPatternGate();
        var horizontalLoopOffset = code.Count;
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var horizontalClearBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitSetDynamicD6AtA4);
        Append(code, BranchAlwaysWord);
        var horizontalAfterPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        var horizontalClearOffset = code.Count;
        Append(code, BitClearDynamicD6AtA4);
        var horizontalAfterPixelOffset = code.Count;
        Append(code, SubQuickOneWordD6);
        Append(code, BranchMinusWord);
        var horizontalWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, DecrementBranchD5);
        var horizontalLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var horizontalSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);

        var horizontalWrapOffset = code.Count;
        Append(code, MoveQuickSevenD6);
        Append(code, AddQuickOneLongA4);
        Append(code, DecrementBranchD5);
        var horizontalWrapLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var horizontalWrapSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);

        var horizontalReversePatternGateOffset = code.Count;
        var horizontalReversePatternGateBranches = AppendPatternGate();
        var horizontalReverseLoopOffset = code.Count;
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var horizontalReverseClearBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitSetDynamicD6AtA4);
