    private static int AppendDrawDiagonalOne(
        List<byte> code,
        int drawFallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(28);

        // Claim only the exact fresh one-step diagonal form.  D0/D1 are the
        // classic WORD target coordinates; preserving their full incoming
        // values lets every richer slope, reverse line, or malformed state
        // continue through the existing Draw body unchanged.
        Append(code, MoveLongD0ToD6); // target X for Draw fallback
        Append(code, MoveLongD1ToD7); // target Y for Draw fallback
        Append(code, CompareImmediateWordD0);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var targetXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(targetXBranchExtensionOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var targetYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(targetYBranchExtensionOffset);

        // Guard the complete public RastPort envelope before consuming its
        // cursor, bitmap, or line state.  A malformed form is still handled
        // by the existing Draw body, which owns its own native/provider
        // boundary.
        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);

        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentX));
        Append(code, CompareImmediateWordD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var currentXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(currentXBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentY));
        Append(code, CompareImmediateWordD3);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var currentYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(currentYBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var layerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layerBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var bitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapRangeBranchExtensionOffset);
        Append(code, MoveAddressD4ToA0);

        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD5);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var rowBytesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD4);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // both row bytes must be addressable
        Append(code, BranchHighWord);
        var planeRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeRangeBranchExtensionOffset);
        Append(code, MoveAddressD4ToA3);
        Append(code, MoveAddressA3ToA4);
        Append(code, AddLongD5ToA4);

        // Strict source/state envelope: JAM1, selected plane zero, fresh dot,
        // no ONE_DOT suppression, and an all-ones line pattern.  The native
        // body intentionally leaves all richer modes and phase forms to Draw.
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var firstDotBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(firstDotBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var oneDotBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oneDotBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePattern));
        Append(code, CompareImmediateWordD4);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var patternBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(patternBranchExtensionOffset);

        // All guards have passed, so D6/D7 may now become pixel scratch.  The
        // two samples lie in the first byte of rows zero and one; APen bit zero
        // selects whether both MSB-first bits are set or cleared.
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, MoveQuickSevenD6);
        Append(code, MoveAddressA3ToA0);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var clearPixelsBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitSetDynamicD6AtA0);
        Append(code, MoveQuickSixD6);
        Append(code, MoveAddressA4ToA0);
        Append(code, BitSetDynamicD6AtA0);
        Append(code, BranchAlwaysWord);
        var afterPixelsBranchExtensionOffset = code.Count;
        Append(code, 0);

        var clearPixelsOffset = code.Count;
        Append(code, MoveAddressA3ToA0);
        Append(code, BitClearDynamicD6AtA0);
        Append(code, MoveQuickSixD6);
        Append(code, MoveAddressA4ToA0);
        Append(code, BitClearDynamicD6AtA0);

        var successOffset = code.Count;
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, AndImmediateWordD4);
        Append(code, 0xFFFE);
        Append(code, MoveWordD4ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, SubQuickOneWordD4);
        Append(code, AndImmediateWordD4);
        Append(code, 0x000F);
        Append(code, MoveByteD4ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveImmediateWordD0);
        Append(code, 1);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentX));
        Append(code, MoveImmediateWordD1);
        Append(code, 1);
        Append(code, MoveWordD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentY));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD7ToD1);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, clearPixelsBranchExtensionOffset, clearPixelsOffset);
        PatchBranch(code, afterPixelsBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, drawFallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    /// <summary>
    /// Builds the exact visible prefix of the origin-rooted shallow Bresenham
    /// line used by a bounded native Draw body.  The guest Bitmap has no
    /// separate width field: its visible row width is <c>BytesPerRow * 8</c>.
    /// Samples beyond that envelope must not wrap into a following row, but
    /// they still contribute to the caller-supplied line phase and endpoint.
    /// </summary>
    private static int ReserveBranchRelay(
        NativeGraphicsBranchIslandAllocator branchAllocator,
        string name,
        int targetOffset)
    {
        var relayOffset = branchAllocator.ReserveAtFragmentBoundary(
            name,
            out var relayExtensionOffset);
        branchAllocator.Link(relayExtensionOffset, targetOffset);
        return relayOffset;
    }

    private static int AppendDrawDiagonalShallow(
        List<byte> code,
        int drawFallbackEntryOffset,
        ushort targetX,
        ushort targetY,
        ushort requiredRows,
        ushort[] sampleRowOffsets,
        byte[] sampleBits,
        byte patternAdvance,
        byte[]? sampleByteOffsets = null,
        ushort requiredBytesPerRow = 2,
        bool targetFromD0 = false,
        Action? appendFragmentBoundary = null)
    {
        if (sampleRowOffsets.Length != sampleBits.Length || sampleRowOffsets.Length < 3)
            throw new ArgumentException("A native shallow Draw arm needs at least three paired samples.");
        if (sampleByteOffsets is not null && sampleByteOffsets.Length != sampleRowOffsets.Length)
            throw new ArgumentException($"A native shallow Draw arm needs one byte offset per sample (target {targetX},{targetY}: rows={sampleRowOffsets.Length}, bits={sampleBits.Length}, bytes={sampleByteOffsets.Length}).");

        var offset = code.Count;
        var fallbackBranches = new List<int>(28);

        // This is a deliberately bounded shallow-slope Draw form on a
        // one-plane standard bitmap with a caller-selected two-, four-, or
        // six-byte row stride. The caller supplies the target and inclusive Bresenham
        // sample addresses; richer slopes and connected/provider ownership
        // remain on the existing Draw body.
        Append(code, MoveLongD0ToD6);
        Append(code, MoveLongD1ToD7);
        if (!targetFromD0)
        {
            Append(code, CompareImmediateWordD0);
            Append(code, targetX);
            Append(code, BranchNotEqualWord);
            var targetXBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(targetXBranchExtensionOffset);
        }
        Append(code, CompareImmediateWordD1);
        Append(code, targetY);
        Append(code, BranchNotEqualWord);
        var targetYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(targetYBranchExtensionOffset);

        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);

        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentX));
        Append(code, CompareImmediateWordD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var currentXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(currentXBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentY));
        Append(code, CompareImmediateWordD3);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var currentYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(currentYBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var layerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layerBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var bitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapRangeBranchExtensionOffset);
        Append(code, MoveAddressD4ToA0);

        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD5);
        Append(code, requiredBytesPerRow);
        Append(code, BranchNotEqualWord);
        var rowBytesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD4);
        Append(code, requiredRows);
        Append(code, BranchNotEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        var maxAddressOffset = 0;
        for (var sample = 0; sample < sampleRowOffsets.Length; sample++)
        {
            var byteOffset = sampleByteOffsets is null ? 0 : sampleByteOffsets[sample];
            if (byteOffset > 31)
                throw new ArgumentOutOfRangeException(nameof(sampleByteOffsets));
            maxAddressOffset = Math.Max(maxAddressOffset, sampleRowOffsets[sample] + byteOffset);
        }

        var planeRangeLimit = maxAddressOffset switch
        {
            0 => (ushort)0xFFFF,
            1 => (ushort)0xFFFE,
            2 => (ushort)0xFFFC,
            3 => (ushort)0xFFFC,
            4 => (ushort)0xFFFB,
            5 => (ushort)0xFFFA,
            6 => (ushort)0xFFFA,
            7 => (ushort)0xFFF8,
            8 => (ushort)0xFFF8,
            9 => (ushort)0xFFF6,
            10 => (ushort)0xFFF6,
            11 => (ushort)0xFFF4,
            12 => (ushort)0xFFF4,
            13 => (ushort)0xFFF2,
            14 => (ushort)0xFFF2,
            15 => (ushort)0xFFF0,
            16 => (ushort)0xFFEF,
            17 => (ushort)0xFFEE,
            18 => (ushort)0xFFEC,
            19 => (ushort)0xFFEC,
            20 => (ushort)0xFFEB,
            21 => (ushort)0xFFEA,
            22 => (ushort)0xFFE9,
            23 => (ushort)0xFFE8,
            24 => (ushort)0xFFE7,
            25 => (ushort)0xFFE6,
            26 => (ushort)0xFFE5,
            27 => (ushort)0xFFE4,
            28 => (ushort)0xFFE3,
            29 => (ushort)0xFFE2,
            30 => (ushort)0xFFE1,
            31 => (ushort)0xFFE0,
            32 => (ushort)0xFFDF,
            33 => (ushort)0xFFDE,
            _ => throw new ArgumentOutOfRangeException(nameof(sampleRowOffsets))
        };
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, planeRangeLimit);
        Append(code, BranchHighWord);
        var planeRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeRangeBranchExtensionOffset);
        Append(code, MoveAddressD4ToA3);

        // Strict source/state envelope: ordinary JAM1, plane zero selected,
        // fresh line, no ONE_DOT suppression, and an all-ones line pattern.
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var firstDotBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(firstDotBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var oneDotBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oneDotBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePattern));
        Append(code, CompareImmediateWordD4);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var patternBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(patternBranchExtensionOffset);

        // A large exact-raster body may need a relay island after all of its
        // fallible guards but before the emitted pixel walks. The optional
        // hook keeps that island inside the generated fragment; ordinary
        // bounded bodies retain their existing byte stream unchanged.
        appendFragmentBoundary?.Invoke();

        // Guards are complete; D6/D7 may now become pixel scratch.  The
        // target values remain in the fallback restore registers until here.
        ushort MoveQuickForBit(byte bit) => bit switch
        {
            0 => MoveQuickZeroD6,
            1 => MoveQuickOneD6,
            2 => MoveQuickTwoD6,
            3 => MoveQuickThreeD6,
            4 => MoveQuickFourD6,
            5 => MoveQuickFiveD6,
            6 => MoveQuickSixD6,
            7 => MoveQuickSevenD6,
            _ => throw new ArgumentOutOfRangeException(nameof(bit))
        };

        void AppendPixelAddress(ushort rowOffset, byte byteOffset)
        {
            var addressOffset = rowOffset + byteOffset;
            if (addressOffset == 0)
            {
                Append(code, MoveAddressA3ToA0);
                return;
            }

            // The compact ADDQ walk is ideal for the established small
            // storage envelopes.  Once the visible address reaches byte 32,
            // use A0's already-established ADDA.L immediate form so the
            // 68000 path has one exact address addition for the final
            // 17-byte-row samples.
            if (addressOffset >= 32)
            {
                Append(code, MoveAddressA3ToA0);
                Append(code, AddImmediateLongToA0);
                Append(code, 0);
                Append(code, checked((ushort)addressOffset));
                return;
            }
            Append(code, MoveAddressA3ToA4);
            while (addressOffset >= 8)
            {
                Append(code, AddQuickEightLongA4);
                addressOffset -= 8;
            }
            if (addressOffset == 6)
                Append(code, AddQuickSixLongA4);
            else if (addressOffset == 7)
            {
                Append(code, AddQuickSixLongA4);
                Append(code, AddQuickOneLongA4);
            }
            else if (addressOffset == 4)
                Append(code, AddQuickFourLongA4);
            else if (addressOffset == 5)
            {
                Append(code, AddQuickFourLongA4);
                Append(code, AddQuickOneLongA4);
            }
            else if (addressOffset == 2)
                Append(code, AddQuickTwoLongA4);
            else if (addressOffset == 3)
            {
                Append(code, AddQuickTwoLongA4);
                Append(code, AddQuickOneLongA4);
            }
            else if (addressOffset == 1)
                Append(code, AddQuickOneLongA4);
            else if (addressOffset != 0)
                throw new ArgumentOutOfRangeException(nameof(rowOffset));
            Append(code, MoveAddressA4ToA0);
        }

        byte ByteOffsetAt(int sample) => sampleByteOffsets is null ? (byte)0 : sampleByteOffsets[sample];

        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, AndImmediateWordD4);
        Append(code, 1);
        AppendPixelAddress(sampleRowOffsets[0], ByteOffsetAt(0));
        Append(code, MoveQuickForBit(sampleBits[0]));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var clearPixelsBranchExtensionOffset = code.Count;
        Append(code, 0);
        for (var sample = 0; sample < sampleRowOffsets.Length; sample++)
        {
            if (sample != 0)
                AppendPixelAddress(sampleRowOffsets[sample], ByteOffsetAt(sample));
            Append(code, MoveQuickForBit(sampleBits[sample]));
            Append(code, BitSetDynamicD6AtA0);
        }
        Append(code, BranchAlwaysWord);
        var afterPixelsBranchExtensionOffset = code.Count;
        Append(code, 0);

        var clearPixelsOffset = code.Count;
        for (var sample = 0; sample < sampleRowOffsets.Length; sample++)
        {
            AppendPixelAddress(sampleRowOffsets[sample], ByteOffsetAt(sample));
            Append(code, MoveQuickForBit(sampleBits[sample]));
            Append(code, BitClearDynamicD6AtA0);
        }

        var successOffset = code.Count;
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, AndImmediateWordD4);
        Append(code, 0xFFFE);
        Append(code, MoveWordD4ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        if (targetFromD0)
        {
            Append(code, SubWordD0ToD4);
        }
        else
        {
            Append(code, SubImmediateWordD4);
            Append(code, patternAdvance);
        }
        Append(code, AndImmediateWordD4);
        Append(code, 0x000F);
        Append(code, MoveByteD4ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        if (!targetFromD0)
        {
            Append(code, MoveImmediateWordD0);
            Append(code, targetX);
        }
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentX));
        Append(code, MoveImmediateWordD1);
        Append(code, targetY);
        Append(code, MoveWordD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentY));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD7ToD1);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, clearPixelsBranchExtensionOffset, clearPixelsOffset);
        PatchBranch(code, afterPixelsBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, drawFallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    /// <summary>
    /// Runtime form of the established origin-rooted shallow <c>(x,1)</c>
    /// Draw envelope. The visible raster is clipped to the admitted planar
    /// row, but the target and line phase remain the full caller values.
    /// </summary>
    private static int AppendDrawRuntimeShallowOne(
        List<byte> code,
        int fallbackEntryOffset,
        ushort minimumTargetX,
        ushort maximumTargetX,
        ushort bytesPerRow)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(minimumTargetX, (ushort)2);
        ArgumentOutOfRangeException.ThrowIfLessThan(maximumTargetX, minimumTargetX);
        ArgumentOutOfRangeException.ThrowIfGreaterThan(maximumTargetX, (ushort)255);
        ArgumentOutOfRangeException.ThrowIfLessThan(bytesPerRow, (ushort)1);

        var offset = code.Count;
        var fallbackBranches = new List<int>(32);
        var lastVisibleX = checked((ushort)(bytesPerRow * 8 - 1));
        var planeRangeLimit = checked((ushort)(ushort.MaxValue - (bytesPerRow * 2 - 1)));

        // Preserve the complete ABI inputs until the last fallible guard.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongD1ToD6);
        Append(code, TestWordD0);
        Append(code, BranchMinusWord);
        var targetXSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(targetXSignBranchExtensionOffset);
        Append(code, CompareImmediateWordD0);
        Append(code, minimumTargetX);
        Append(code, BranchCarryWord);
        var targetXLowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(targetXLowBranchExtensionOffset);
        Append(code, CompareImmediateWordD0);
        Append(code, maximumTargetX);
        Append(code, BranchHighWord);
        var targetXHighBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(targetXHighBranchExtensionOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var targetYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(targetYBranchExtensionOffset);

        // Match the established exact-arm admission: an origin cursor, an
        // unlayered standard one-plane bitmap, and both complete plane rows
        // addressable before the first store.
        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentX));
        Append(code, CompareImmediateWordD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var currentXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(currentXBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentY));
        Append(code, CompareImmediateWordD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var currentYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(currentYBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var layerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layerBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var bitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapRangeBranchExtensionOffset);
        Append(code, MoveAddressD4ToA0);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD5);
        Append(code, bytesPerRow);
        Append(code, BranchNotEqualWord);
        var rowBytesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD4);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, planeRangeLimit); // final byte of plane row one
        Append(code, BranchHighWord);
        var planeRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeRangeBranchExtensionOffset);
        Append(code, MoveAddressD4ToA3);

        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        // The generated arms use only FgPen's low bit. Retain that exact
        // JAM1 source selection in D2 for the two runtime walks.
        Append(code, MoveQuickZeroD2);
        Append(code, MoveByteA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, AndImmediateWordD2);
        Append(code, 1);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var firstDotBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(firstDotBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var oneDotBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oneDotBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePattern));
        Append(code, CompareImmediateWordD4);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var patternBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(patternBranchExtensionOffset);

        // The portable Bresenham walk raises y after the ceil(targetX / 2)
        // first-row samples. Draw that visible run, then the visible suffix
        // of row one; samples beyond the visible row only advance
        // endpoint/phase.
        Append(code, MoveWordD0ToD4);
        Append(code, AddQuickOneWordD4);
        Append(code, ShiftRightWordD4Count1); // first-row sample count
        // Clamp the visible row-zero prefix without changing D0's full
        // endpoint: later code recomputes the un-clipped row-one start.
        Append(code, CompareImmediateWordD4);
        Append(code, checked((ushort)(lastVisibleX + 1)));
        Append(code, BranchHighWord);
        var clippedFirstCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var firstCountReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var clippedFirstCountOffset = code.Count;
        Append(code, MoveImmediateWordD0);
        Append(code, checked((ushort)(lastVisibleX + 1)));
        Append(code, MoveWordD0ToD4);
        Append(code, MoveWordD7ToD0);
        var firstCountReadyOffset = code.Count;
        Append(code, SubQuickOneWordD4); // DBRA counter
        Append(code, MoveAddressA3ToA4);
        Append(code, MoveQuickSevenD5);
        var firstLoopOffset = code.Count;
        Append(code, TestLongD2);
        Append(code, BranchNotEqualWord);
        var firstSetPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitClearDynamicD5AtA4);
        Append(code, BranchAlwaysWord);
        var firstPenContinueBranchExtensionOffset = code.Count;
        Append(code, 0);
        var firstSetPenOffset = code.Count;
        Append(code, BitSetDynamicD5AtA4);
        var firstPenContinueOffset = code.Count;
        Append(code, SubQuickOneWordD5);
        Append(code, BranchMinusWord);
        var firstWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, DecrementBranchD4);
        var firstLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var firstDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        var firstWrapOffset = code.Count;
        Append(code, MoveQuickSevenD5);
        Append(code, AddQuickOneLongA4);
        Append(code, DecrementBranchD4);
        var firstWrapLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        var firstDoneOffset = code.Count;

        Append(code, MoveWordD0ToD4);
        Append(code, AddQuickOneWordD4);
        Append(code, ShiftRightWordD4Count1); // second-row start X
        // An empty clipped suffix must bypass DBRA entirely: subtracting one
        // from its zero iteration count would otherwise wrap to 65,536.
        Append(code, CompareImmediateWordD4);
        Append(code, lastVisibleX);
        Append(code, BranchHighWord);
        var noVisibleSecondRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, lastVisibleX);
        Append(code, BranchHighWord);
        var clippedSecondCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveWordD0ToD3);
        Append(code, SubWordD4ToD3);
        Append(code, AddQuickOneWordD3);
        Append(code, BranchAlwaysWord);
        var secondCountReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var clippedSecondCountOffset = code.Count;
        Append(code, MoveImmediateWordD1);
        Append(code, checked((ushort)(lastVisibleX + 1)));
        Append(code, MoveWordD1ToD3);
        Append(code, SubWordD4ToD3);
        var secondCountReadyOffset = code.Count;
        Append(code, SubQuickOneWordD3); // DBRA counter
        Append(code, MoveAddressA3ToA4);
        Append(code, MoveWordA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, ExtendLongD5);
        Append(code, AddLongD5ToA4);
        Append(code, MoveWordD4ToD5);
        Append(code, ShiftRightWordD5Count3);
        Append(code, ExtendLongD5);
        Append(code, AddLongD5ToA4);
        Append(code, MoveWordD4ToD5);
        Append(code, AndImmediateWordD5);
        Append(code, 7);
        Append(code, ExclusiveOrImmediateWordD5);
        Append(code, 7);
        var secondLoopOffset = code.Count;
        Append(code, TestLongD2);
        Append(code, BranchNotEqualWord);
        var secondSetPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitClearDynamicD5AtA4);
        Append(code, BranchAlwaysWord);
        var secondPenContinueBranchExtensionOffset = code.Count;
        Append(code, 0);
        var secondSetPenOffset = code.Count;
        Append(code, BitSetDynamicD5AtA4);
        var secondPenContinueOffset = code.Count;
        Append(code, SubQuickOneWordD5);
        Append(code, BranchMinusWord);
        var secondWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, DecrementBranchD3);
        var secondLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var secondDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        var secondWrapOffset = code.Count;
        Append(code, MoveQuickSevenD5);
        Append(code, AddQuickOneLongA4);
        Append(code, DecrementBranchD3);
        var secondWrapLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        var successOffset = code.Count;

        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, AndImmediateWordD4);
        Append(code, 0xFFFE);
        Append(code, MoveWordD4ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, MoveQuickFifteenD0);
        Append(code, SubWordD7ToD0);
        Append(code, AndImmediateWordD0);
        Append(code, 0x000F);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveWordD7ToD0);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentX));
        Append(code, MoveQuickOneD1);
        Append(code, MoveWordD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentY));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongD6ToD1);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, firstSetPenBranchExtensionOffset, firstSetPenOffset);
        PatchBranch(code, firstPenContinueBranchExtensionOffset, firstPenContinueOffset);
        PatchBranch(code, firstWrapBranchExtensionOffset, firstWrapOffset);
        PatchBranch(code, firstLoopBranchExtensionOffset, firstLoopOffset);
        PatchBranch(code, firstDoneBranchExtensionOffset, firstDoneOffset);
        PatchBranch(code, firstWrapLoopBranchExtensionOffset, firstLoopOffset);
        PatchBranch(code, clippedFirstCountBranchExtensionOffset, clippedFirstCountOffset);
        PatchBranch(code, firstCountReadyBranchExtensionOffset, firstCountReadyOffset);
        PatchBranch(code, clippedSecondCountBranchExtensionOffset, clippedSecondCountOffset);
        PatchBranch(code, secondCountReadyBranchExtensionOffset, secondCountReadyOffset);
        PatchBranch(code, secondSetPenBranchExtensionOffset, secondSetPenOffset);
        PatchBranch(code, secondPenContinueBranchExtensionOffset, secondPenContinueOffset);
        PatchBranch(code, secondWrapBranchExtensionOffset, secondWrapOffset);
        PatchBranch(code, secondLoopBranchExtensionOffset, secondLoopOffset);
        PatchBranch(code, secondDoneBranchExtensionOffset, successOffset);
        PatchBranch(code, secondWrapLoopBranchExtensionOffset, secondLoopOffset);
        PatchBranch(code, noVisibleSecondRowBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

