        PatchBranch(code, thirtyFourthTargetYFallbackBranchExtensionOffset, thirtyFifthCheckOffset);
        PatchBranch(code, thirtyFourthShallowJumpExtensionOffset, diagonalTwoHundredEightEntryOffset);
        PatchBranch(code, thirtyFifthTargetXFallbackBranchExtensionOffset, thirtySixthCheckOffset);
        PatchBranch(code, thirtyFifthTargetYFallbackBranchExtensionOffset, thirtySixthCheckOffset);
        PatchBranch(code, thirtyFifthShallowJumpExtensionOffset, diagonalTwoHundredNineEntryOffset);
        PatchBranch(code, thirtySixthTargetXFallbackBranchExtensionOffset, thirtySeventhCheckOffset);
        PatchBranch(code, thirtySixthTargetYFallbackBranchExtensionOffset, thirtySeventhCheckOffset);
        PatchBranch(code, thirtySixthShallowJumpExtensionOffset, diagonalTwoHundredTenEntryOffset);
        PatchBranch(code, thirtySeventhTargetXFallbackBranchExtensionOffset, thirtyEighthCheckOffset);
        PatchBranch(code, thirtySeventhTargetYFallbackBranchExtensionOffset, thirtyEighthCheckOffset);
        PatchBranch(code, thirtySeventhShallowJumpExtensionOffset, diagonalTwoHundredElevenEntryOffset);
        PatchBranch(code, thirtyEighthTargetXFallbackBranchExtensionOffset, existingDispatchOffsetInExtension);
        PatchBranch(code, thirtyEighthTargetYFallbackBranchExtensionOffset, existingDispatchOffsetInExtension);
        PatchBranch(code, thirtyEighthShallowJumpExtensionOffset, diagonalTwoHundredTwelveEntryOffset);
        PatchBranch(code, existingDispatchJumpExtensionOffset, existingDispatchOffset);
