    }

    /// <summary>
    /// Appends a small terminal selector for one shallow-line endpoint. Its
    /// fall-through stays on the preceding selector, keeping each 68000 word
    /// branch local as the appended body grows with the Bitmap storage boundary.
    /// </summary>
    private static int AppendDrawTerminalShallowDispatch(
        List<byte> code,
        int existingDispatchOffset,
        ushort targetX,
        ushort targetY,
        int targetOffset)
    {
        var offset = code.Count;
        Append(code, CompareImmediateWordD0);
        Append(code, targetX);
        Append(code, BranchEqualWord);
        var firstTargetMatchBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        var targetYCheckOffset = code.Count;
        Append(code, CompareImmediateWordD1);
        Append(code, targetY);
        Append(code, BranchNotEqualWord);
        var targetYFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var targetJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, firstTargetMatchBranchExtensionOffset, targetYCheckOffset);
        PatchBranch(code, targetYFallbackBranchExtensionOffset, fallbackOffset);
        PatchBranch(code, targetJumpExtensionOffset, targetOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, existingDispatchOffset);
        return offset;
    }

    private static int AppendPolyDraw(
        List<byte> code,
        int fallbackEntryOffset,
        int drawBranchTargetOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(20);

        // PolyDraw consumes the low UWORD count.  This first native slice
        // claims the empty stream and exactly one connected segment; longer
        // streams remain on the portable/provider path until a native
        // connected-loop body can preserve the complete transaction.
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateWordD0);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var onePointBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, TestWordD0);
        Append(code, BranchEqualWord);
        var emptyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var tooManyBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tooManyBranchExtensionOffset);

        var onePointOffset = code.Count;

        // The point-table envelope is checked before any RastPort state is
        // consumed.  The host admission gate validates readable guest spans;
        // the body additionally rejects null/odd point bases so a malformed
        // native entry remains available to the shared fallback.
        Append(code, MoveLongA0ToD2);
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var nullPointsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullPointsBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddPointsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddPointsBranchExtensionOffset);

        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 0);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, 2);
        Append(code, TestWordD0);
        Append(code, BranchMinusWord);
        var targetXSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(targetXSignBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchMinusWord);
