        PatchBranch(code, diagonalOneHundredSeventyFiveAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredSeventySixAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredSeventySevenAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredSeventyEightAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredSeventyNineAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredEightyAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredEightyOneAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredEightyTwoAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredEightyThreeAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredEightyFourAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredEightyFiveAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredEightySixAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredEightySevenAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredEightyEightAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredEightyNineAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredNinetyAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredNinetyOneAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredNinetyTwoAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredNinetyThreeAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredNinetyFourAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredNinetyFiveAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredNinetySixAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredNinetySevenAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredNinetyEightAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalOneHundredNinetyNineAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredOneAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredTwoAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredThreeAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredFourAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredFiveAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredSixAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredSevenAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredEightAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredNineAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredTenAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredElevenAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredTwelveAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredThirteenAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredFourteenAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredFifteenAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredSixteenAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredSeventeenAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredEighteenAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredNineteenAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredTwentyAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredTwentyOneAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredTwentyTwoAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredTwentyThreeAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalTwoHundredTwentyFourAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageAcceptedOffset);
        PatchBranch(code, diagonalFiftyStorageBytesBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, diagonalFiftyStorageSixByteAcceptedBranchExtensionOffset, diagonalFiftyStorageRowsProbeOffset);
        PatchBranch(code, diagonalFiftyStorageSevenByteAcceptedBranchExtensionOffset, diagonalFiftyStorageRowsProbeOffset);
        PatchBranch(code, diagonalFiftyStorageRowsBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, diagonalFiftyStorageGeometryBranchExtensionOffset, geometryAcceptedOffset);
        PatchBranch(code, diagonalOneHundredFortyFiveStorageBytesBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, diagonalOneHundredFortyFiveStorageSevenByteAcceptedBranchExtensionOffset, diagonalOneHundredFortyFiveStorageRowsProbeOffset);
        PatchBranch(code, diagonalOneHundredFortyFiveStorageRowsBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, diagonalOneHundredFortyFiveStorageGeometryBranchExtensionOffset, geometryAcceptedOffset);
        PatchBranch(code, diagonalOneHundredSixtyOneStorageBytesBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, diagonalOneHundredSixtyOneStorageRowsBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, diagonalOneHundredSixtyOneStorageGeometryBranchExtensionOffset, geometryAcceptedOffset);
        PatchBranch(code, diagonalOneHundredSixtyOneStorageNineByteCheckOffset, geometryAcceptedOffset);
        PatchBranch(code, diagonalOneHundredSixtyOneStorageTenByteCheckOffset, geometryAcceptedOffset);
        PatchBranch(code, diagonalOneHundredSixtyOneStorageTenByteAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageRowsProbeOffset);
        PatchBranch(code, diagonalOneHundredSixtyOneStorageElevenByteAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageRowsProbeOffset);
        PatchBranch(code, diagonalOneHundredSixtyOneStorageThirteenByteAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageRowsProbeOffset);
        PatchBranch(code, diagonalOneHundredSixtyOneStorageFourteenByteAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageRowsProbeOffset);
        PatchBranch(code, diagonalOneHundredSixtyOneStorageFifteenByteAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageRowsProbeOffset);
        PatchBranch(code, diagonalOneHundredSixtyOneStorageSixteenByteAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageRowsProbeOffset);
        PatchBranch(code, diagonalOneHundredSixtyOneStorageSeventeenByteAcceptedBranchExtensionOffset, diagonalOneHundredSixtyOneStorageRowsProbeOffset);
        PatchBranch(code, diagonalOneFiveAcceptedBranchExtensionOffset, geometryAcceptedOffset);
        PatchBranch(code, diagonalOneSixAcceptedBranchExtensionOffset, geometryAcceptedOffset);
        PatchBranch(code, diagonalOneSevenAcceptedBranchExtensionOffset, geometryAcceptedOffset);
        PatchBranch(code, diagonalAcceptedBranchExtensionOffset, geometryAcceptedOffset);
        PatchBranch(code, drawBranchExtensionOffset, drawBranchTargetOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendClearEol(
        List<byte> code,
        int fallbackEntryOffset,
        bool requireSingleRowScreen = false)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(24);

        // This native slice owns only the cached one-row form: a NULL guest
        // Font, TxHeight=1, TxBaseline=0, one standard plane, base JAM1 or
        // JAM2 with BPen 0/1, and a selected low mask bit.  It clears or
        // fills from CurrentX to the end of the current row and publishes the
        // native line-pattern reset.  Font-derived heights, complement or
        // inverse modes, and richer planes remain on the portable/provider
        // transaction.  ClearScreen has a separate origin/full-raster arm;
        // this body remains the compatibility tail for its one-row and
        // partial/non-origin forms.
        Append(code, MoveLongD0ToD6);
        // This tail is reached directly by ClearScreen as well as after the
        // multi-plane ClearEOL selector declines depth one. Keep a wrapped
        // RastPort from aliasing the low guest range on either route.
        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C);
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFont));
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var fontBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontBranchExtensionOffset);

        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextHeight));
        Append(code, CompareImmediateWordD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var heightBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(heightBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextBaseline));
        Append(code, TestWordD4);
        Append(code, BranchNotEqualWord);
        var baselineBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(baselineBranchExtensionOffset);

        Append(code, MoveWordA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentX));
        Append(code, TestWordD0);
        Append(code, BranchMinusWord);
        var xSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xSignBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentY));
        Append(code, TestWordD3);
        Append(code, BranchMinusWord);
        var ySignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ySignBranchExtensionOffset);

        // Base JAM1 clears to zero.  Base JAM2 is admitted only for BPen 0
        // or 1; the D1 mode marker survives the geometry preflight so the
        // final loop can select bit-clear versus bit-set without changing
        // the captured D0 fallback value in D6.
        Append(code, MoveQuickZeroD1);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var jam1ModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var jam2ZeroPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var bPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bPenBranchExtensionOffset);
        Append(code, MoveQuickOneD1);
        var jam2ValidationEndOffset = code.Count;
        PatchBranch(code, jam1ModeBranchExtensionOffset, jam2ValidationEndOffset);
        PatchBranch(code, jam2ZeroPenBranchExtensionOffset, jam2ValidationEndOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var bitmapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var bitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapRangeBranchExtensionOffset);
        Append(code, MoveAddressD4ToA0);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD2);
        Append(code, BranchEqualWord);
        var rowBytesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRowBytesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRowBytesBranchExtensionOffset);
        Append(code, CompareImmediateWordD2);
        Append(code, 0x0FFF);
        Append(code, BranchHighWord);
        var rowBytesLimitBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesLimitBranchExtensionOffset);

        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);

        if (requireSingleRowScreen)
        {
            Append(code, CompareImmediateWordD4);
            Append(code, 1);
            Append(code, BranchNotEqualWord);
            var strictRowsBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(strictRowsBranchExtensionOffset);
            // D3 still carries the nonnegative CurrentY loaded above.
            Append(code, TestWordD3);
            Append(code, BranchNotEqualWord);
            var yOriginBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(yOriginBranchExtensionOffset);
        }

        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var planesTableBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planesTableBranchExtensionOffset);
        Append(code, MoveAddressD4ToA3);
        Append(code, MoveLongA3ToD5);
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var planeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeBranchExtensionOffset);
        Append(code, MoveAddressD5ToA4);

        // A4 becomes the start of the selected bitmap row.  D3 is the
        // nonnegative CurrentY and D2 the bounded row stride.
        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordD2ToD4);
        Append(code, MultiplyUnsignedWordD4ToD3);
        Append(code, AddLongD3ToA4);

        // D5 = BytesPerRow * 8, D7 = CurrentX, and D4 becomes the number of
        // pixels remaining in the row.  Equality is the successful empty
        // right-edge form; a wrapped/negative remainder remains fallback.
        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordD2ToD5);
        Append(code, ShiftLeftLongD5);
        Append(code, ShiftLeftLongD5);
        Append(code, ShiftLeftLongD5);
        Append(code, MoveWordD0ToD7);
        Append(code, MoveLongD5ToD4);
        Append(code, SubWordD0ToD4);
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var emptyRemainingBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchMinusWord);
        var remainderSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(remainderSignBranchExtensionOffset);

        Append(code, ShiftRightWordD0Count3);
        Append(code, ExtendLongD0);
        Append(code, AddLongD0ToA4);
        Append(code, MoveWordD7ToD6);
        Append(code, AndImmediateWordD6);
        Append(code, 7);
        Append(code, ExclusiveOrImmediateWordD6);
        Append(code, 7);

        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var clearModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var setLoopJumpExtensionOffset = code.Count;
        Append(code, 0);

        var clearLoopOffset = code.Count;
        Append(code, BitClearDynamicD6AtA4);
        Append(code, SubQuickOneLongD4);
        Append(code, BranchEqualWord);
        var clearSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, SubQuickOneWordD6);
        Append(code, BranchMinusWord);
        var nextByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var clearLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var nextByteOffset = code.Count;
        Append(code, MoveQuickSevenD6);
        Append(code, AddQuickOneLongA4);
        Append(code, BranchAlwaysWord);
        var nextByteLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var setLoopOffset = code.Count;
        Append(code, BitSetDynamicD6AtA4);
        Append(code, SubQuickOneLongD4);
        Append(code, BranchEqualWord);
        var setSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, SubQuickOneWordD6);
        Append(code, BranchMinusWord);
        var setNextByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var setLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var setNextByteOffset = code.Count;
        Append(code, MoveQuickSevenD6);
        Append(code, AddQuickOneLongA4);
        Append(code, BranchAlwaysWord);
        var setNextByteLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var emptySuccessOffset = code.Count;
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD6ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, emptyRemainingBranchExtensionOffset, emptySuccessOffset);
        PatchBranch(code, clearSuccessBranchExtensionOffset, emptySuccessOffset);
        PatchBranch(code, nextByteBranchExtensionOffset, nextByteOffset);
        PatchBranch(code, clearModeBranchExtensionOffset, clearLoopOffset);
        PatchBranch(code, clearLoopBranchExtensionOffset, clearLoopOffset);
        PatchBranch(code, nextByteLoopBranchExtensionOffset, clearLoopOffset);
        PatchBranch(code, setLoopJumpExtensionOffset, setLoopOffset);
        PatchBranch(code, setSuccessBranchExtensionOffset, emptySuccessOffset);
        PatchBranch(code, setNextByteBranchExtensionOffset, setNextByteOffset);
        PatchBranch(code, setLoopBranchExtensionOffset, setLoopOffset);
        PatchBranch(code, setNextByteLoopBranchExtensionOffset, setLoopOffset);
        PatchBranch(code, rastPortNullBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, rastPortOddBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, rastPortRangeBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendClearScreenMultiPlane(
        List<byte> code,
        int oneRowEntryOffset,
        bool requireSingleRow = false)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(28);

        // Claim the small, deterministic multi-plane origin form first.  The
        // full-raster wrapper reaches this body only after its one-plane arm
        // declines depth > 1; this arm then provides the same transactional
        // admission for standard planar depth 2..8 screens.  Every selected
        // plane is preflighted before the first byte is published.
        Append(code, MoveLongD0ToPreDecrementA7);

        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C);
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFont));
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var fontBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextHeight));
        Append(code, CompareImmediateWordD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var heightBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(heightBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextBaseline));
        Append(code, TestWordD4);
        Append(code, BranchNotEqualWord);
        var baselineBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(baselineBranchExtensionOffset);

        // This first multi-plane slice is deliberately origin-only.  The
        // one-plane bit-tail body remains responsible for arbitrary cursors.
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentX));
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var currentXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(currentXBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentY));
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var currentYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(currentYBranchExtensionOffset);

        // Base JAM1 writes zero.  Base JAM2 is admitted for BPen 0/1; the
        // marker in D1 is regenerated after preflight because D1 is scratch
        // during the address-span checks.
        Append(code, MoveQuickZeroD1);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD0);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var drawModeDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD0);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveQuickZeroD1);
        Append(code, MoveByteA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD1);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var bPenZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD1);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var bPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bPenBranchExtensionOffset);
        Append(code, MoveQuickOneD1);
        var drawModeDoneOffset = code.Count;
        PatchBranch(code, drawModeDoneBranchExtensionOffset, drawModeDoneOffset);
        PatchBranch(code, bPenZeroBranchExtensionOffset, drawModeDoneOffset);

        Append(code, MoveQuickZeroD2);
        Append(code, MoveByteA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));

        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var bitmapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var bitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapRangeBranchExtensionOffset);
        Append(code, MoveAddressD4ToA4);
        Append(code, MoveAddressD4ToA0);

        // Standard planar only: reject displayable/interleaved/provider-owned
        // flags before looking at any plane link.
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var flagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(flagsBranchExtensionOffset);

        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD0);
        Append(code, 2);
        Append(code, BranchCarryWord);
        var depthLowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthLowBranchExtensionOffset);
        Append(code, CompareImmediateByteD0);
        Append(code, 8);
        Append(code, BranchHighWord);
        var depthHighBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthHighBranchExtensionOffset);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveByteA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, SubQuickOneWordD5);

        // Keep the bounded resident form exact: the declared row stride must
        // equal the full byte span that is cleared on every row.
        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var strideZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(strideZeroBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var strideOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(strideOddBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 0x0FFF);
        Append(code, BranchHighWord);
        var strideLimitBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(strideLimitBranchExtensionOffset);

        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareWordD6ToD4);
        Append(code, BranchNotEqualWord);
        var rowWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowWidthBranchExtensionOffset);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestWordD6);
        Append(code, BranchEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);
        if (requireSingleRow)
        {
            Append(code, CompareImmediateWordD6);
            Append(code, 1);
            Append(code, BranchNotEqualWord);
            var singleRowBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(singleRowBranchExtensionOffset);
        }

        // A zero mask is a validated no-op.  It must not read the plane table.
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var zeroMaskBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Read-only preflight of every selected plane.  The product is the
        // one-past row envelope (stride * rows), so a carry rejects any plane
        // whose declared raster would wrap the 32-bit guest address space.
        Append(code, MoveAddressA0ToA2);
        Append(code, MoveAddressA2ToA3);
        Append(code, AddQuickFourLongA3);
        Append(code, AddQuickFourLongA3);
        Append(code, MoveQuickZeroD7);
        var preflightLoopOffset = code.Count;
        Append(code, MoveLongA3IndirectToD3);
        Append(code, MoveLongD2ToD0);
        Append(code, BitTestDynamicD7ToD0);
        Append(code, BranchEqualWord);
        var preflightSkipPlaneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, TestLongD3);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD3);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, MultiplyUnsignedWordD4ToD6);
        Append(code, MoveLongD3ToD0);
        Append(code, AddLongD6ToD0);
        Append(code, BranchCarryWord);
        var planeAddressCarryBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeAddressCarryBranchExtensionOffset);

        var preflightNextPlaneOffset = code.Count;
        Append(code, AddQuickFourLongA3);
        Append(code, AddQuickOneLongD7);
        Append(code, DecrementBranchD5);
        var preflightLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Regenerate the JAM source byte after preflight and restart the
        // inline plane table for the publication pass.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveByteA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, SubQuickOneWordD5);
        Append(code, MoveQuickZeroD1);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD0);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var publicationJam1BranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD1);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var publicationBPenZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickMinusOneD1);
        var publicationSourceReadyOffset = code.Count;
        PatchBranch(code, publicationJam1BranchExtensionOffset, publicationSourceReadyOffset);
        PatchBranch(code, publicationBPenZeroBranchExtensionOffset, publicationSourceReadyOffset);
        Append(code, MoveAddressA0ToA2);
        Append(code, MoveAddressA2ToA3);
        Append(code, AddQuickFourLongA3);
        Append(code, AddQuickFourLongA3);
        Append(code, MoveQuickZeroD7);

        var writePlaneLoopOffset = code.Count;
        Append(code, MoveLongD2ToD0);
        Append(code, BitTestDynamicD7ToD0);
        Append(code, BranchEqualWord);
        var publicationSkipPlaneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA3IndirectToD3);
        Append(code, MoveAddressD3ToA0);
        Append(code, MoveAddressA0ToA5);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, MoveAddressA5ToA0);

        var rowLoopOffset = code.Count;
        Append(code, MoveWordD4ToD6);
        var byteLoopOffset = code.Count;
        Append(code, MoveByteD1ToA0PostIncrement);
        Append(code, SubQuickOneWordD6);
        Append(code, BranchNotEqualWord);
        var byteLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, SubQuickOneWordD3);
        Append(code, BranchNotEqualWord);
        var rowLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var afterRowLoopOffset = code.Count;
        Append(code, MoveQuickZeroD2);
        Append(code, MoveByteA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, AddQuickFourLongA3);
        Append(code, AddQuickOneLongD7);
        Append(code, DecrementBranchD5);
        var writePlaneLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, preflightSkipPlaneBranchExtensionOffset, preflightNextPlaneOffset);
        PatchBranch(code, preflightLoopBranchExtensionOffset, preflightLoopOffset);
        PatchBranch(code, publicationSkipPlaneBranchExtensionOffset, afterRowLoopOffset);
        PatchBranch(code, byteLoopBranchExtensionOffset, byteLoopOffset);
        PatchBranch(code, rowLoopBranchExtensionOffset, rowLoopOffset);
        PatchBranch(code, writePlaneLoopBranchExtensionOffset, writePlaneLoopOffset);
        PatchBranch(code, zeroMaskBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, oneRowEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendClearScreenFullRaster(
        List<byte> code,
        int oneRowEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(24);

        // Keep this admission deliberately small: a standard screen has a
        // NULL guest font, one-pixel cached text geometry, a single planar
        // byte stream, and a nonnegative cursor inside the raster. The
        // resident arm clears/fills the current-row bit tail and every later
        // row; the companion origin multi-plane arm, layered/provider, and
        // richer-mode forms retain their separate ownership paths.
        Append(code, MoveLongD0ToD6);
        // ClearScreen enters here directly rather than through the ClearEOL
        // selector. Validate the entire public descriptor before cached text
        // fields can wrap into a low-memory alias.
        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C);
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFont));
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var fontBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontBranchExtensionOffset);

        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextHeight));
        Append(code, CompareImmediateWordD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var heightBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(heightBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextBaseline));
        Append(code, TestWordD4);
        Append(code, BranchNotEqualWord);
        var baselineBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(baselineBranchExtensionOffset);

        Append(code, MoveWordA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentX));
        Append(code, TestWordD0);
        Append(code, BranchMinusWord);
        var xSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xSignBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentY));
        Append(code, TestWordD3);
        Append(code, BranchMinusWord);
        var ySignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ySignBranchExtensionOffset);
        Append(code, MoveWordD3ToD7);

        // Base JAM1 clears to zero.  Base JAM2 is admitted only for BPen 0
        // or 1, preserving the same conservative pen contract as ClearEOL.
        Append(code, MoveQuickZeroD1);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var jam1ModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var jam2ZeroPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var bPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bPenBranchExtensionOffset);
        Append(code, MoveQuickOneD1);
        var jam2ValidationEndOffset = code.Count;
        PatchBranch(code, jam1ModeBranchExtensionOffset, jam2ValidationEndOffset);
        PatchBranch(code, jam2ZeroPenBranchExtensionOffset, jam2ValidationEndOffset);

        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var bitmapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var bitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapRangeBranchExtensionOffset);
        Append(code, MoveAddressD4ToA0);

        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD3);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);

        Append(code, MoveWordA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD2);
        Append(code, BranchEqualWord);
        var rowBytesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRowBytesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRowBytesBranchExtensionOffset);
        Append(code, CompareImmediateWordD2);
        Append(code, 0x0FFF);
        Append(code, BranchHighWord);
        var rowBytesLimitBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowBytesLimitBranchExtensionOffset);

        // A byte-aligned CurrentX may name the empty tail immediately after
        // the last byte, but it must not start beyond the raster.  Keep this
        // check in the resident admission arm so the pointer arithmetic below
        // never walks past the current row before falling back.
        Append(code, MoveWordD0ToD5);
        Append(code, ShiftRightWordD5Count3);
        Append(code, MoveWordD2ToD4);
        Append(code, SubWordD5ToD4);
        Append(code, TestWordD4);
        Append(code, BranchMinusWord);
        var currentXRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(currentXRangeBranchExtensionOffset);

        Append(code, MoveWordA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD3);
        Append(code, 1);
        Append(code, BranchLowerOrSameWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);

        // CurrentY is retained in D7.  Reject a row at or below the bitmap
        // end before following the plane table; the resident body then starts
        // its byte walk at plane0 + CurrentY*BytesPerRow.
        Append(code, MoveWordD7ToD5);
        Append(code, CompareWordD5ToD3);
        Append(code, BranchLowerOrSameWord);
        var currentRowRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(currentRowRangeBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var planesTableBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planesTableBranchExtensionOffset);
        Append(code, MoveAddressD4ToA3);
        Append(code, MoveLongA3ToD5);
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var planeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeBranchExtensionOffset);
        Append(code, MoveAddressD5ToA4);

        Append(code, MoveWordD7ToD5);
        Append(code, MoveWordD2ToD4);
        Append(code, MultiplyUnsignedWordD4ToD5);
        Append(code, AddLongD5ToA4);
        Append(code, MoveWordD0ToD5);
        Append(code, ShiftRightWordD5Count3);
        Append(code, ExtendLongD5);
        Append(code, AddLongD5ToA4);
        Append(code, MoveAddressA4ToA0);

        // SNE converts the JAM2 pen marker in D1 to the complete bit source:
        // zero selects clear and 0xFF selects fill.
        Append(code, TestLongD1);
        Append(code, SetNotEqualByteD1);

        // D4 is the number of pixels remaining in the first row.  D6 is the
        // MSB-first bit index within the current byte; all admission branches
        // have already passed, so the saved caller D0 no longer needs D6.
        Append(code, MoveWordD2ToD4);
        Append(code, ShiftLeftLongD4);
        Append(code, ShiftLeftLongD4);
        Append(code, ShiftLeftLongD4);
        Append(code, SubWordD0ToD4);
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var firstRowEmptyBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveWordD0ToD6);
        Append(code, AndImmediateWordD6);
        Append(code, 7);
        Append(code, ExclusiveOrImmediateWordD6);
        Append(code, 7);

        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var clearBitModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var setBitModeBranchExtensionOffset = code.Count;
        Append(code, 0);

        var clearBitLoopOffset = code.Count;
        Append(code, BitClearDynamicD6AtA0);
        Append(code, SubQuickOneWordD4);
        Append(code, BranchEqualWord);
        var clearBitRowDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, SubQuickOneWordD6);
        Append(code, BranchMinusWord);
        var clearBitNextByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var clearBitLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var clearBitNextByteOffset = code.Count;
        Append(code, MoveQuickSevenD6);
        Append(code, AddQuickOneLongA0);
        Append(code, BranchAlwaysWord);
        var clearBitNextByteLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var setBitLoopOffset = code.Count;
        Append(code, BitSetDynamicD6AtA0);
        Append(code, SubQuickOneWordD4);
        Append(code, BranchEqualWord);
        var setBitRowDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, SubQuickOneWordD6);
        Append(code, BranchMinusWord);
        var setBitNextByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var setBitLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var setBitNextByteOffset = code.Count;
        Append(code, MoveQuickSevenD6);
        Append(code, AddQuickOneLongA0);
        Append(code, BranchAlwaysWord);
        var setBitNextByteLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        // The nonempty first-row walk leaves A0 on its final byte. Advance to
        // the next row; the empty-tail path already points at that row.
        var firstRowDoneOffset = code.Count;
        Append(code, AddQuickOneLongA0);
        var firstRowEmptyDoneOffset = code.Count;
        Append(code, SubQuickOneWordD3);
        Append(code, BranchEqualWord);
        var firstRowCompleteBranchExtensionOffset = code.Count;
        Append(code, 0);

        var rowLoopOffset = code.Count;
        Append(code, MoveWordD2ToD4);
        var rowByteLoopOffset = code.Count;
        Append(code, MoveByteD1ToA0PostIncrement);
        Append(code, SubQuickOneWordD4);
        Append(code, BranchNotEqualWord);
        var rowByteLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, SubQuickOneWordD3);
        Append(code, BranchNotEqualWord);
        var rowLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD6ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, firstRowEmptyBranchExtensionOffset, firstRowEmptyDoneOffset);
        PatchBranch(code, clearBitModeBranchExtensionOffset, clearBitLoopOffset);
        PatchBranch(code, setBitModeBranchExtensionOffset, setBitLoopOffset);
        PatchBranch(code, clearBitRowDoneBranchExtensionOffset, firstRowDoneOffset);
        PatchBranch(code, clearBitNextByteBranchExtensionOffset, clearBitNextByteOffset);
        PatchBranch(code, clearBitLoopBranchExtensionOffset, clearBitLoopOffset);
        PatchBranch(code, clearBitNextByteLoopBranchExtensionOffset, clearBitLoopOffset);
        PatchBranch(code, setBitRowDoneBranchExtensionOffset, firstRowDoneOffset);
        PatchBranch(code, setBitNextByteBranchExtensionOffset, setBitNextByteOffset);
        PatchBranch(code, setBitLoopBranchExtensionOffset, setBitLoopOffset);
        PatchBranch(code, setBitNextByteLoopBranchExtensionOffset, setBitLoopOffset);
        PatchBranch(code, firstRowCompleteBranchExtensionOffset, successOffset);
        PatchBranch(code, rowByteLoopBranchExtensionOffset, rowByteLoopOffset);
        PatchBranch(code, rowLoopBranchExtensionOffset, rowLoopOffset);
        PatchBranch(code, rastPortNullBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, rastPortOddBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, rastPortRangeBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, oneRowEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static void AppendJsrPcRelative(List<byte> code, int targetOffset)
    {
        Append(code, JumpToSubroutinePcDisplacement);
        var extensionOffset = code.Count;
        Append(code, 0);
        // Copper68k's PC-relative control decoder uses the extension-word
        // address as the displacement base (the same convention exercised by
        // the 68000 JSR d16(PC) tests), not the post-extension PC.
        var displacement = checked(targetOffset - extensionOffset);
        if (displacement < short.MinValue || displacement > short.MaxValue)
        {
            throw new InvalidOperationException(
                $"Native graphics JSR is out of range (extension {extensionOffset}, target {targetOffset}, displacement {displacement}).");
        }

        code[extensionOffset] = (byte)((ushort)displacement >> 8);
        code[extensionOffset + 1] = (byte)displacement;
    }

    private static void AppendJsrA6Displacement(List<byte> code, short displacement)
    {
        Append(code, JumpToSubroutineA6Displacement);
        Append(code, unchecked((ushort)displacement));
    }

    /// <summary>
    /// Adapts native release arguments (A0=allocation, D0=byte count)
    /// to Exec FreeMem's A1/D0 ABI without losing the caller's live A1.
    /// </summary>
    private static void AppendExecFreeMemFromA0PreservingA1(List<byte> code)
    {
        Append(code, MoveLongA1ToPreDecrementA7);
        Append(code, MoveAddressA0ToA1);
        AppendJsrA6Displacement(code, ExecFreeMemDisplacement);
        Append(code, MoveAddressA7PostIncrementToA1);
    }

    /// <summary>
    /// Adapts native release staging (D0=allocation, D1=byte count) to
    /// Exec FreeMem's A1/D0 ABI while retaining the caller's live A1.
    /// </summary>
    private static void AppendExecFreeMemFromD0D1PreservingA1(List<byte> code)
    {
        Append(code, MoveLongA1ToPreDecrementA7);
        Append(code, MoveAddressD0ToA1);
        Append(code, MoveLongD1ToD0);
        AppendJsrA6Displacement(code, ExecFreeMemDisplacement);
        Append(code, MoveAddressA7PostIncrementToA1);
    }

    /// <summary>
    /// Emits the first native in-place two-viewport copper merge.  This is a
    /// deliberately small Kickstart-compatible form: two visible terminal
    /// ViewPorts, two caller-owned 12-entry CopLists, distinct canonical raw
    /// streams, and a first stream with capacity for the composed 24-entry
    /// result.  The first stream is the destination, the second stream is
    /// copied after a generated WAIT separator, and the first CopList count
    /// is published only after the complete preflight succeeds.  Every
    /// malformed/unsupported shape restores D0/A1 and falls through to the
    /// read-only pre-merged alias owner.
    /// </summary>
    private static int AppendMrgCopPreallocatedTwoVisibleMerge(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(96);

        void Decline(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void ValidatePointer(
            ushort testOpcode,
            ushort bitTestOpcode,
            ushort compareOpcode,
            uint maximumAddress)
        {
            Append(code, testOpcode);
            Decline(BranchEqualWord);
            Append(code, bitTestOpcode);
            Append(code, 0);
            Decline();
            Append(code, compareOpcode);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            Decline(BranchHighWord);
        }

        // MrgCop receives View in A1 and returns its status in D0. Preserve
        // both the caller result and the original A1 for the alias fallback.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveAddressA1ToA5);
        Append(code, MoveLongA1ToD6);
        ValidatePointer(
            TestLongD6,
            BitTestImmediateD6,
            CompareImmediateLongD6,
            0xFFFF_FFEEu); // ViewSize

        // Exactly two visible terminal ViewPorts, with no alternate copper
        // providers.  Hidden/extended/linked shapes stay on their owner.
        Append(code, MoveLongA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        ValidatePointer(
            TestLongD5,
            BitTestImmediateD5,
            CompareImmediateLongD5,
            0xFFFF_FFD8u); // ViewPortSize
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Decline();
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        ValidatePointer(
            TestLongD4,
            BitTestImmediateD4,
            CompareImmediateLongD4,
            0xFFFF_FFD8u);

        Append(code, MoveAddressD4ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Decline();
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD0);
        Decline();

        // Both RasInfo records are complete, unlinked envelopes.  Their
        // bitmap payload remains provider-owned and is never dereferenced.
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        ValidatePointer(
        TestLongD0,
            BitTestImmediateD0,
            CompareImmediateLongD0,
            0xFFFF_FFF4u);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveAddressD4ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        ValidatePointer(
            TestLongD0,
            BitTestImmediateD0,
            CompareImmediateLongD0,
            0xFFFF_FFF4u);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
        Append(code, TestLongD0);
        Decline();

        // Keep the two CopList addresses in D3/D2 for the commit.  Their
        // public envelope is checked before either raw stream is touched.
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(
            TestLongD3,
            BitTestImmediateD3,
            CompareImmediateLongD3,
            0xFFFF_FFCAu); // CopListSize
        Append(code, MoveAddressD4ToA0);
        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(
            TestLongD2,
            BitTestImmediateD2,
            CompareImmediateLongD2,
            0xFFFF_FFCAu);

        // CopList shape: each list points back to its ViewPort, is terminal,
        // and exposes the exact twelve-entry preallocated source form.  The
        // first list must have room for the twelve copied instructions and
        // two-word terminator (24 entries total).
        Append(code, MoveAddressD3ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
        Append(code, MoveLongD5ToD6);
        Append(code, CompareLongD6ToD0);
        Decline();
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListNext));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 12);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 23);
        Decline(BranchLowerOrSameWord);

        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
        Append(code, MoveLongD4ToD6);
        Append(code, CompareLongD6ToD0);
        Decline();
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListNext));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 12);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 11);
        Decline(BranchLowerOrSameWord);

        // Distinct, non-overlapping, even raw streams.  The destination is
        // the first stream and is bounded for the 96-byte merged result.
        Append(code, MoveAddressD3ToA0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(
            TestLongD1,
            BitTestImmediateD1,
            CompareImmediateLongD1,
            0xFFFF_FFA0u); // first + 96 bytes
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        Append(code, MoveLongD0ToD2); // source raw; second CopList no longer needed
        ValidatePointer(
            TestLongD2,
            BitTestImmediateD2,
            CompareImmediateLongD2,
            0xFFFF_FFD0u); // source + 48 bytes
        Append(code, CompareLongD0ToD1);
        Decline(BranchEqualWord);
        Append(code, MoveLongD1ToD6);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 96);
        Append(code, AddLongD0ToD6);
        Append(code, CompareLongD6ToD2);
        // CMP.L D6,D2 computes source-end minus destination-end.  Decline
        // when the source begins at or before the destination's 96-byte
        // extent; a strictly higher source address is the non-overlap form.
        Decline(BranchLowerOrSameWord);

        // Both source streams must be the canonical twelve-entry raw form:
        // 22 words of instructions followed by $FFFF/$FFFE.
        Append(code, MoveAddressD1ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 44);
        Append(code, CompareImmediateWordD0);
        Append(code, 0xFFFF);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 46);
        Append(code, CompareImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Decline();
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 44);
        Append(code, CompareImmediateWordD0);
        Append(code, 0xFFFF);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 46);
        Append(code, CompareImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Decline();

        // LOF/SHF wrappers must already point at the destination and have
        // capacity for the composed 24-entry stream.  Their nodes remain
        // untouched by the merge.
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewLoFCprList));
        ValidatePointer(
            TestLongD0,
            BitTestImmediateD0,
            CompareImmediateLongD0,
            0xFFFF_FFF4u);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CprListStart));
        Append(code, CompareLongD0ToD1);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 23);
        Decline(BranchLowerOrSameWord);

        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewShFCprList));
        ValidatePointer(
            TestLongD0,
            BitTestImmediateD0,
            CompareImmediateLongD0,
            0xFFFF_FFF4u);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CprListStart));
        Append(code, CompareLongD0ToD1);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 23);
        Decline(BranchLowerOrSameWord);

        // Commit: replace the first terminator with the host-equivalent WAIT,
        // copy the second 22-word body, append the final terminator, and only
        // then publish Count=24. The mutation is therefore all-or-nothing
        // with respect to every preflight failure above.
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 2); // DIWSTRT word; preserve its vertical byte
        Append(code, AndImmediateWordD0);
        Append(code, 0xFF00);
        Append(code, MoveAddressD1ToA2);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 44);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 46);

        Append(code, MoveAddressD2ToA1);
        Append(code, MoveAddressD1ToA2);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 48);
        Append(code, AddLongD0ToA2);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        // DBRA repeats while the decremented low word remains nonnegative;
        // an initial value of 21 therefore copies exactly 22 words.
        Append(code, 21);
        Append(code, MoveLongD0ToD5);
        var copyLoopOffset = code.Count;
        Append(code, MoveWordA1PostIncrementToD4);
        Append(code, MoveWordD4ToA2);
        Append(code, AddQuickTwoLongA2);
        Append(code, DecrementBranchD5);
        var copyLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, copyLoopBranchExtensionOffset, copyLoopOffset);

        Append(code, MoveImmediateWordD0);
        Append(code, 0xFFFF);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);
        Append(code, MoveAddressD3ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, 24);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveAddressA5ToA1);
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Emits the seven-visible composition of the bounded in-place merge. It
    /// preflights the two final sources and the 84-entry destination, then
    /// invokes the guarded five-node prefix through a private success
    /// handshake before appending streams six and seven.
    /// </summary>
    private static int AppendMrgCopPreallocatedSevenVisibleMerge(
        List<byte> code,
        int sixVisibleMergeOffset,
        int fiveVisibleMergeOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(128);

        void Decline(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void ValidatePointer(
            ushort testOpcode,
            ushort bitTestOpcode,
            ushort compareOpcode,
            uint maximumAddress)
        {
            Append(code, testOpcode);
            Decline(BranchEqualWord);
            Append(code, bitTestOpcode);
            Append(code, 0);
            Decline();
            Append(code, compareOpcode);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            Decline(BranchHighWord);
        }

        void ValidateFinalSource(
            ushort viewPortAddressOpcode,
            ushort viewPortBacklinkOpcode,
            ushort rawRetainOpcode)
        {
            Append(code, viewPortAddressOpcode);
            foreach (var linkOffset in new[]
            {
                GraphicsLayouts.ViewPortSprIns,
                GraphicsLayouts.ViewPortClrIns,
                GraphicsLayouts.ViewPortUCopIns
            })
            {
                Append(code, MoveLongA0DisplacementToD0);
                Append(code, checked((ushort)linkOffset));
                Append(code, TestLongD0);
                Decline();
            }
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
            ValidatePointer(TestLongD0, BitTestImmediateD0,
                CompareImmediateLongD0, 0xFFFF_FFF4u);
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
            Append(code, TestLongD0);
            Decline();

            Append(code, viewPortAddressOpcode);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
            ValidatePointer(TestLongD0, BitTestImmediateD0,
                CompareImmediateLongD0, 0xFFFF_FFCAu);
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
            Append(code, viewPortBacklinkOpcode);
            Append(code, CompareLongD6ToD0);
            Decline();
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListNext));
            Append(code, TestLongD0);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 12);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 11);
            Decline(BranchLowerOrSameWord);
            Append(code, rawRetainOpcode);
            Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
            ValidatePointer(rawRetainOpcode == MoveLongA0DisplacementToD4
                    ? TestLongD4
                    : TestLongD2,
                rawRetainOpcode == MoveLongA0DisplacementToD4
                    ? BitTestImmediateD4
                    : BitTestImmediateD2,
                rawRetainOpcode == MoveLongA0DisplacementToD4
                    ? CompareImmediateLongD4
                    : CompareImmediateLongD2,
                0xFFFF_FFD0u);
            foreach (var wordOffset in new[] { (ushort)44, (ushort)46 })
            {
                Append(code, rawRetainOpcode == MoveLongA0DisplacementToD4
                    ? MoveAddressD4ToA0
                    : MoveAddressD2ToA0);
                Append(code, MoveWordA0DisplacementToD0);
                Append(code, wordOffset);
                Append(code, CompareImmediateWordD0);
                Append(code, wordOffset == 44
                    ? GraphicsLayouts.CopperEndWait
                    : GraphicsLayouts.CopperEndMask);
                Decline();
            }
        }

        // Preserve the public ABI while the private composition reserves
        // every source and destination envelope before its first write.
        Append(code, MoveLongA6ToPreDecrementA7);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA1ToPreDecrementA7);
        Append(code, MoveLongA1ToD6);
        ValidatePointer(TestLongD6, BitTestImmediateD6,
            CompareImmediateLongD6, 0xFFFF_FFEEu);

        // Retain the seven fixed-cardinality ViewPorts. The established
        // five-node prefix validates nodes one through five in full; this arm
        // owns the additional sixth/seventh public envelopes.
        Append(code, MoveLongA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        ValidatePointer(TestLongD5, BitTestImmediateD5,
            CompareImmediateLongD5, 0xFFFF_FFD8u);
        foreach (var step in new[]
        {
            (MoveAddressD5ToA0, MoveLongA0DisplacementToD4,
                TestLongD4, BitTestImmediateD4, CompareImmediateLongD4),
            (MoveAddressD4ToA0, MoveLongA0DisplacementToD3,
                TestLongD3, BitTestImmediateD3, CompareImmediateLongD3),
            (MoveAddressD3ToA0, MoveLongA0DisplacementToD2,
                TestLongD2, BitTestImmediateD2, CompareImmediateLongD2),
            (MoveAddressD2ToA0, MoveLongA0DisplacementToD1,
                TestLongD1, BitTestImmediateD1, CompareImmediateLongD1),
            (MoveAddressD1ToA0, MoveLongA0DisplacementToD7,
                TestLongD7, BitTestImmediateD7, CompareImmediateLongD7),
            (MoveAddressD7ToA0, MoveLongA0DisplacementToD0,
                TestLongD0, BitTestImmediateD0, CompareImmediateLongD0)
        })
        {
            Append(code, step.Item1);
            Append(code, step.Item2);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
            ValidatePointer(step.Item3, step.Item4, step.Item5, 0xFFFF_FFD8u);
        }
        Append(code, MoveAddressD0ToA3); // seventh ViewPort

        // The sixth must be visible and lead exactly to the retained seventh.
        // A private eight-node caller may carry one already-preflighted trailing
        // node through A4; public seven-node calls still require a terminal
        // seventh ViewPort.
        Append(code, MoveAddressD7ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Decline();
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, MoveLongA3ToD6);
        Append(code, CompareLongD6ToD0);
        Decline();

        Append(code, MoveAddressA3ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Decline();
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var terminalSeventhBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA4ToD0);
        Append(code, CompareImmediateLongD0);
        Append(code, (ushort)(MrgCopSevenAllowTrailingEightMagic >> 16));
        Append(code, unchecked((ushort)MrgCopSevenAllowTrailingEightMagic));
        Decline();
        PatchBranch(code, terminalSeventhBranchExtensionOffset, code.Count);

        ValidateFinalSource(MoveAddressD7ToA0, MoveLongD7ToD6,
            MoveLongA0DisplacementToD4); // sixth raw source
        ValidateFinalSource(MoveAddressA3ToA0, MoveLongA3ToD6,
            MoveLongA0DisplacementToD2); // seventh raw source

        // The first stream/wrappers must have room for the final 84-entry
        // result. The five-prefix checks its own smaller envelope too.
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(TestLongD0, BitTestImmediateD0,
            CompareImmediateLongD0, 0xFFFF_FFCAu);
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 83);
        Decline(BranchLowerOrSameWord);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(TestLongD6, BitTestImmediateD6,
            CompareImmediateLongD6, 0xFFFF_FEB0u);
        foreach (var cprOffset in new[]
        {
            GraphicsLayouts.ViewLoFCprList,
            GraphicsLayouts.ViewShFCprList
        })
        {
            Append(code, MoveLongA1DisplacementToD0);
            Append(code, checked((ushort)cprOffset));
            ValidatePointer(TestLongD0, BitTestImmediateD0,
                CompareImmediateLongD0, 0xFFFF_FFF4u);
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CprListStart));
            Append(code, CompareLongD6ToD0);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 83);
            Decline(BranchLowerOrSameWord);
        }

        // The two final raw sources must follow both the enlarged destination
        // and each other before the five-node prefix commits anything.
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongImmediateD6);
        Append(code, 0);
        Append(code, 336);
        Append(code, AddLongD6ToD0);
        Append(code, CompareLongD0ToD4);
        Decline(BranchLowerOrSameWord);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongImmediateD6);
        Append(code, 0);
        Append(code, 48);
        Append(code, AddLongD6ToD0);
        Append(code, CompareLongD0ToD2);
        Decline(BranchLowerOrSameWord);

        // Keep both final ViewPort/raw pairs across the private prefix call.
        Append(code, MoveLongD7ToPreDecrementA7);
        Append(code, MoveLongD4ToPreDecrementA7);
        Append(code, MoveLongA3ToPreDecrementA7);
        Append(code, MoveLongD2ToPreDecrementA7);
        Append(code, MoveLongA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, MoveAddressD4ToA0);
        Append(code, MoveLongA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, MoveAddressD3ToA0);
        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, MoveLongImmediateD6);
        Append(code, (ushort)(MrgCopFiveAllowTrailingSixMagic >> 16));
        Append(code, unchecked((ushort)MrgCopFiveAllowTrailingSixMagic));
        Append(code, MoveAddressD6ToA4);
        Append(code, MoveLongImmediateD6);
        Append(code, (ushort)(MrgCopPrivatePrefixA6Magic >> 16));
        Append(code, unchecked((ushort)MrgCopPrivatePrefixA6Magic));
        Append(code, MoveAddressD6ToA6);
        Append(code, MoveQuickZeroD0);
        AppendJsrPcRelative(code, fiveVisibleMergeOffset);
        Append(code, CompareImmediateLongD7);
        Append(code, (ushort)(MrgCopFiveSuccessMagic >> 16));
        Append(code, unchecked((ushort)MrgCopFiveSuccessMagic));
        Append(code, BranchEqualWord);
        var prefixSucceededBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var prefixFailedBranchExtensionOffset = code.Count;
        Append(code, 0);
        var prefixSucceededOffset = code.Count;
        PatchBranch(code, prefixSucceededBranchExtensionOffset, prefixSucceededOffset);

        Append(code, MoveLongA7PostIncrementToD2); // seventh raw
        Append(code, MoveLongA7PostIncrementToD6); // seventh ViewPort
        Append(code, MoveAddressD6ToA3);
        Append(code, MoveLongA7PostIncrementToD4); // sixth raw
        Append(code, MoveLongA7PostIncrementToD7); // sixth ViewPort
        Append(code, MoveLongA7PostIncrementToD6); // original A1
        Append(code, MoveAddressD6ToA1);
        Append(code, MoveLongA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        Append(code, MoveAddressD5ToA5);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        Append(code, MoveAddressD6ToA2);
        Append(code, MoveLongImmediateD5);
        Append(code, 0);
        Append(code, 236);
        Append(code, AddLongD5ToA2);

        // Append sixth source after the prefix terminator.
        Append(code, MoveAddressD4ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 2);
        Append(code, AndImmediateWordD0);
        Append(code, 0xFF00);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);
        Append(code, MoveAddressD4ToA1);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 4);
        Append(code, AddLongD0ToA2);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 21);
        Append(code, MoveLongD0ToD5);
        var sixthCopyLoopOffset = code.Count;
        Append(code, MoveWordA1PostIncrementToD4);
        Append(code, MoveWordD4ToA2);
        Append(code, AddQuickTwoLongA2);
        Append(code, DecrementBranchD5);
        var sixthCopyBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, sixthCopyBranchExtensionOffset, sixthCopyLoopOffset);

        // Replace that provisional terminator with the seventh separator,
        // append the final source, and publish Count=84 last.
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 2);
        Append(code, AndImmediateWordD0);
        Append(code, 0xFF00);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);
        Append(code, MoveAddressD2ToA1);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 4);
        Append(code, AddLongD0ToA2);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 21);
        Append(code, MoveLongD0ToD5);
        var seventhCopyLoopOffset = code.Count;
        Append(code, MoveWordA1PostIncrementToD4);
        Append(code, MoveWordD4ToA2);
        Append(code, AddQuickTwoLongA2);
        Append(code, DecrementBranchD5);
        var seventhCopyBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, seventhCopyBranchExtensionOffset, seventhCopyLoopOffset);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndWait);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, 84);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, MoveLongA7PostIncrementToD6); // original D0 discard
        Append(code, MoveLongA7PostIncrementToD6); // original A6
        Append(code, CompareImmediateLongD6);
        Append(code, (ushort)(MrgCopPrivatePrefixA6Magic >> 16));
        Append(code, unchecked((ushort)MrgCopPrivatePrefixA6Magic));
        Append(code, BranchNotEqualWord);
        var publicSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongImmediateD7);
        Append(code, (ushort)(MrgCopFiveSuccessMagic >> 16));
        Append(code, unchecked((ushort)MrgCopFiveSuccessMagic));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, publicSuccessBranchExtensionOffset, code.Count);
        Append(code, MoveAddressD6ToA6);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var prefixFailedOffset = code.Count;
        PatchBranch(code, prefixFailedBranchExtensionOffset, prefixFailedOffset);
        Append(code, MoveLongA7PostIncrementToD2);
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, BranchAlwaysWord);
        var prefixFailedRestoreBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        PatchBranch(code, prefixFailedRestoreBranchExtensionOffset, fallbackRestoreOffset);
        Append(code, MoveLongA7PostIncrementToD6); // original A1
        Append(code, MoveAddressD6ToA1);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveAddressD6ToA6);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveAddressD4ToA4);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, sixVisibleMergeOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Emits the eight-visible composition of the bounded in-place merge. The
    /// eighth source is fully preflighted before the private seven-node prefix
    /// can alter its destination; the public count is published last.
    /// </summary>
    private static int AppendMrgCopPreallocatedEightVisibleMerge(
        List<byte> code,
        int sevenVisibleMergeOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(96);

        void Decline(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void ValidatePointer(
            ushort testOpcode,
            ushort bitTestOpcode,
            ushort compareOpcode,
            uint maximumAddress)
        {
            Append(code, testOpcode);
            Decline(BranchEqualWord);
            Append(code, bitTestOpcode);
            Append(code, 0);
            Decline();
            Append(code, compareOpcode);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
