            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
            Append(code, TestLongD0);
            Decline();

            Append(code, MoveAddressA2ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
            ValidatePointer(TestLongD0, BitTestImmediateD0,
                CompareImmediateLongD0, 0xFFFF_FFCAu);
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
            Append(code, MoveLongA2ToD6);
            Append(code, CompareLongD6ToD0);
            Decline();
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListNext));
            Append(code, TestLongD0);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 12);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 11);
            Decline(BranchLowerOrSameWord);
            Append(code, MoveLongA0DisplacementToD4);
            Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
            ValidatePointer(TestLongD4, BitTestImmediateD4,
                CompareImmediateLongD4, 0xFFFF_FFD0u);
            foreach (var wordOffset in new[] { (ushort)44, (ushort)46 })
            {
                Append(code, MoveAddressD4ToA0);
                Append(code, MoveWordA0DisplacementToD0);
                Append(code, wordOffset);
                Append(code, CompareImmediateWordD0);
                Append(code, wordOffset == 44
                    ? GraphicsLayouts.CopperEndWait
                    : GraphicsLayouts.CopperEndMask);
                Decline();
            }
        }

        Append(code, MoveLongA6ToPreDecrementA7);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA1ToPreDecrementA7);
        Append(code, MoveLongA1ToD6);
        ValidatePointer(TestLongD6, BitTestImmediateD6,
            CompareImmediateLongD6, 0xFFFF_FFEEu);

        // Retain the eighth ViewPort before handing the first seven to their
        // existing atomic prefix. The seven-node body will revalidate every
        // predecessor and admits the trailing marker only for this call.
        Append(code, MoveLongA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        ValidatePointer(TestLongD5, BitTestImmediateD5,
            CompareImmediateLongD5, 0xFFFF_FFD8u);
        foreach (var step in new[]
        {
            (MoveAddressD5ToA0, MoveLongA0DisplacementToD4,
                TestLongD4, BitTestImmediateD4, CompareImmediateLongD4),
            (MoveAddressD4ToA0, MoveLongA0DisplacementToD3,
                TestLongD3, BitTestImmediateD3, CompareImmediateLongD3),
            (MoveAddressD3ToA0, MoveLongA0DisplacementToD2,
                TestLongD2, BitTestImmediateD2, CompareImmediateLongD2),
            (MoveAddressD2ToA0, MoveLongA0DisplacementToD1,
                TestLongD1, BitTestImmediateD1, CompareImmediateLongD1),
            (MoveAddressD1ToA0, MoveLongA0DisplacementToD7,
                TestLongD7, BitTestImmediateD7, CompareImmediateLongD7),
            (MoveAddressD7ToA0, MoveLongA0DisplacementToD0,
                TestLongD0, BitTestImmediateD0, CompareImmediateLongD0)
