            Append(code, MoveLongA4ToD0);
            PointerD0(0xFFFF_FFD8u);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
            Append(code, CompareImmediateWordD0);
            Append(code, 0);
            Fail();
            Append(code, MoveQuickZeroD0);
            Append(code, MoveByteA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
            Append(code, TestLongD0);
            Fail();
            foreach (var link in new[]
            {
                GraphicsLayouts.ViewPortSprIns,
                GraphicsLayouts.ViewPortClrIns,
                GraphicsLayouts.ViewPortUCopIns
            })
            {
                Append(code, MoveLongA0DisplacementToD0);
                Append(code, checked((ushort)link));
                Append(code, TestLongD0);
                Fail();
            }

            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
            PointerD0(0xFFFF_FFF4u);
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
            Append(code, TestLongD0);
            Fail();

            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
            PointerD0(0xFFFF_FFCAu);
            Append(code, MoveAddressD0ToA5);
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
            Append(code, MoveLongA4ToD1);
            Append(code, CompareLongD1ToD0);
            Fail();
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListNext));
            Append(code, TestLongD0);
            Fail();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 12);
            Fail();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 11);
            Fail(BranchLowerOrSameWord);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
            PointerD0(0xFFFF_FFD0u);
            Append(code, MoveLongD0ToD2);
            Append(code, MoveAddressD2ToA0);
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, 44);
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.CopperEndWait);
            Fail();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, 46);
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.CopperEndMask);
            Fail();
        }

        // Preserve the public ABI state. The generic body retains A1 as the
        // View root, A2 as the first raw stream, A3 as the first CopList, and
        // D7 as the validated node count across its three passes.
        Append(code, MoveLongA6ToPreDecrementA7);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA1ToPreDecrementA7);
        Append(code, MoveLongA1ToD0);
        PointerD0(0xFFFF_FFEEu);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        PointerD0(0xFFFF_FFD8u);
        Append(code, MoveAddressD0ToA4);

        // Floyd's tortoise/hare check catches a repeated ViewPort pointer
        // before the counting pass. It is intentionally bounded as a second
        // line of defence for corrupt long chains; NULL is the sole terminal
        // spelling admitted by this native owner.
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveQuickThirtyOneD5);
        Append(code, MoveLongD5ToD6);
        var acyclicBranches = new List<int>(2);
        var cycleCheckOffset = code.Count;
        foreach (var _ in new[] { 0, 1 })
        {
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
            Append(code, TestLongD0);
            Append(code, BranchEqualWord);
            var acyclicBranch = code.Count;
            Append(code, 0);
            acyclicBranches.Add(acyclicBranch);
            PointerD0(0xFFFF_FFD8u);
            Append(code, MoveAddressD0ToA5);
        }
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        PointerD0(0xFFFF_FFD8u);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongA5ToD1);
        Append(code, CompareLongD0ToD1);
        Fail(BranchEqualWord);
        Append(code, DecrementBranchD6);
        var cycleCheckLoop = code.Count;
        Append(code, 0);
        PatchBranch(code, cycleCheckLoop, cycleCheckOffset);
        Append(code, BranchAlwaysWord);
        var cycleCheckLimitFail = code.Count;
        Append(code, 0);
        var cycleCheckComplete = code.Count;
        foreach (var acyclicBranch in acyclicBranches)
            PatchBranch(code, acyclicBranch, cycleCheckComplete);
        // A nonterminal chain past the bounded detection budget is provider-
        // owned, just like a detected repeated pointer.
        fallbackBranches.Add(cycleCheckLimitFail);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveQuickZeroD7);
        Append(code, MoveQuickThirtyOneD5);
        Append(code, MoveLongD5ToD6); // DBRA allows at most 32 nodes.

        var firstPassOffset = code.Count;
        CurrentNodeEnvelope();
        Append(code, TestLongD7);
        Append(code, BranchNotEqualWord);
        var notFirstBranch = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD2ToA2);
        Append(code, MoveAddressA5ToA3);
        PatchBranch(code, notFirstBranch, code.Count);
        Append(code, AddQuickOneLongD7);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var firstPassComplete = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD0ToA4);
        Append(code, DecrementBranchD6);
        var firstPassLoop = code.Count;
        Append(code, 0);
        PatchBranch(code, firstPassLoop, firstPassOffset);
        // The only way DBRA reaches here is a nonterminal 33rd node.
        Append(code, BranchAlwaysWord);
        var firstPassLimitFail = code.Count;
        Append(code, 0);
        PatchBranch(code, firstPassComplete, code.Count);
        // Calculate the destination end (base + 48 * count) with overflow
        // detection, then require Count >= 12 * count - 1 on the first list.
        Append(code, MoveLongD7ToD0);
        Append(code, ShiftLeftLongD0); Append(code, ShiftLeftLongD0);
        Append(code, ShiftLeftLongD0); Append(code, ShiftLeftLongD0);
        Append(code, MoveLongD0ToD1);
        Append(code, AddLongD0ToD1); Append(code, AddLongD0ToD1);
        Append(code, MoveLongA2ToD4);
        Append(code, AddLongD1ToD4);
        Fail(BranchCarryWord);
        Append(code, MoveLongD7ToD0);
        Append(code, AddLongD7ToD0); Append(code, AddLongD7ToD0);
        Append(code, ShiftLeftLongD0); Append(code, ShiftLeftLongD0);
        Append(code, SubQuickOneLongD0);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareWordD0ToD1);
        Fail(BranchCarryWord);
        Append(code, MoveLongD0ToD5); // retain final Count requirement for CPR checks

        // The View CPR wrappers must name the same first raw stream and carry
        // the final capacity before any individual source can be overwritten.
        foreach (var cpr in new[] { GraphicsLayouts.ViewLoFCprList, GraphicsLayouts.ViewShFCprList })
        {
            Append(code, MoveLongA1DisplacementToD0);
            Append(code, checked((ushort)cpr));
            PointerD0(0xFFFF_FFF4u);
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CprListStart));
            Append(code, MoveLongA2ToD1);
            Append(code, CompareLongD1ToD0);
            Fail();
            Append(code, MoveWordA0DisplacementToD1);
            Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
            Append(code, CompareWordD5ToD1);
            Fail(BranchCarryWord);
        }

        // Pass two replays the chain read-only and rejects any raw source in
        // the final destination envelope. This makes the later in-place copy
        // safe even though it rewinds to the View head rather than buffering.
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveQuickThirtyOneD5);
        Append(code, MoveLongD5ToD6);
        Append(code, MoveQuickZeroD5); // first stream is the destination itself
        var separationPassOffset = code.Count;
        CurrentNodeEnvelope();
        Append(code, TestLongD5);
        Append(code, BranchNotEqualWord);
        var compareNonFirstSource = code.Count;
        Append(code, 0);
        Append(code, AddQuickOneLongD5);
        Append(code, BranchAlwaysWord);
        var separationCheckComplete = code.Count;
        Append(code, 0);
        PatchBranch(code, compareNonFirstSource, code.Count);
        Append(code, MoveLongD2ToD0);
        Append(code, CompareLongD4ToD0);
        Fail(BranchLowerOrSameWord);
        PatchBranch(code, separationCheckComplete, code.Count);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var separationPassComplete = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD0ToA4);
        Append(code, DecrementBranchD6);
        var separationPassLoop = code.Count;
        Append(code, 0);
        PatchBranch(code, separationPassLoop, separationPassOffset);
        Append(code, BranchAlwaysWord);
        var separationPassLimitFail = code.Count;
        Append(code, 0);
        PatchBranch(code, separationPassComplete, code.Count);

        // Pass three is the sole writer. Its sources and all destination
        // bounds are exactly those proven by the preceding passes.
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, MoveAddressD0ToA4);
        // The first source already occupies the destination. Its terminal
        // pair is at byte 44, which is where the first appended separator
        // must replace it; only ViewPorts two through N are copied here.
        Append(code, MoveLongImmediateD0);
        Append(code, 0); Append(code, 44);
        Append(code, AddLongD0ToA2);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, MoveAddressD0ToA4);
        var compositionPassOffset = code.Count;
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        Append(code, MoveAddressD0ToA1);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 2);
        Append(code, AndImmediateWordD0);
        Append(code, 0xFF00);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);
        Append(code, MoveLongImmediateD0);
        Append(code, 0); Append(code, 4);
        Append(code, AddLongD0ToA2);
        Append(code, MoveLongImmediateD5);
        Append(code, 0); Append(code, 21);
        var copyBodyOffset = code.Count;
        Append(code, MoveWordA1PostIncrementToD0);
        Append(code, MoveWordD0ToA2);
        Append(code, AddQuickTwoLongA2);
        Append(code, DecrementBranchD5);
        var copyBodyLoop = code.Count;
        Append(code, 0);
        PatchBranch(code, copyBodyLoop, copyBodyOffset);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var compositionComplete = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD0ToA4);
        Append(code, BranchAlwaysWord);
        var compositionLoop = code.Count;
        Append(code, 0);
        PatchBranch(code, compositionLoop, compositionPassOffset);
        PatchBranch(code, compositionComplete, code.Count);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndWait);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);
        Append(code, MoveLongD7ToD0);
        Append(code, AddLongD7ToD0); Append(code, AddLongD7ToD0);
        Append(code, ShiftLeftLongD0); Append(code, ShiftLeftLongD0);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, MoveLongA7PostIncrementToD6); // original A1 discard
        Append(code, MoveLongA7PostIncrementToD6); // original D0 discard
        Append(code, MoveLongA7PostIncrementToD6); // original A6
        Append(code, MoveAddressD6ToA6);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackOffset = code.Count;
        PatchBranch(code, firstPassLimitFail, fallbackOffset);
        PatchBranch(code, separationPassLimitFail, fallbackOffset);
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveAddressD6ToA1);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveAddressD6ToA6);
        Append(code, BranchAlwaysWord);
        var fallbackJump = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJump, fallbackEntryOffset);
        foreach (var extensionOffset in fallbackBranches)
            PatchBranch(code, extensionOffset, fallbackOffset);
        return offset;
    }

    /// <summary>
    /// Emits the six-visible composition of the bounded in-place merge.  It
    /// preflights the sixth source and the enlarged destination, asks the
    /// existing five-visible body to commit its independently guarded prefix,
    /// then appends the already validated final separator/body.  No guest byte
    /// is changed until every six-specific envelope has passed.
    /// </summary>
    private static int AppendMrgCopPreallocatedSixVisibleMerge(
        List<byte> code,
        int fiveVisibleMergeOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(96);

        void Decline(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void ValidatePointer(
            ushort testOpcode,
            ushort bitTestOpcode,
            ushort compareOpcode,
            uint maximumAddress)
        {
            Append(code, testOpcode);
            Decline(BranchEqualWord);
            Append(code, bitTestOpcode);
            Append(code, 0);
            Decline();
            Append(code, compareOpcode);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            Decline(BranchHighWord);
        }

        void ValidateVisibleViewPort(ushort addressOpcode, bool terminal,
            ushort nextRegister = 0, ushort nextTest = 0,
            ushort nextBitTest = 0, ushort nextCompare = 0)
        {
            Append(code, addressOpcode);
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
            Append(code, CompareImmediateWordD0);
            Append(code, 0);
            Decline();
            Append(code, MoveQuickZeroD0);
            Append(code, MoveByteA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
            Append(code, TestLongD0);
            Decline();
            if (terminal)
            {
                Append(code, MoveLongA0DisplacementToD0);
                Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
                Append(code, TestLongD0);
                Decline();
            }
            else
            {
                Append(code, nextRegister);
                Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
                ValidatePointer(nextTest, nextBitTest, nextCompare, 0xFFFF_FFD8u);
            }
        }

        // The wrapper keeps the public vector's A6 intact and restores D0 on
        // every preflight decline.  The five-visible prefix itself preserves
        // A6 across its private call.
        Append(code, MoveLongA6ToPreDecrementA7);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA1ToPreDecrementA7);
        Append(code, MoveLongA1ToD6);
        ValidatePointer(TestLongD6, BitTestImmediateD6, CompareImmediateLongD6, 0xFFFF_FFEEu);

        // Retain the six fixed-cardinality ViewPort nodes. D7 carries the
        // sixth only until its complete public envelope has been inspected.
        Append(code, MoveLongA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        ValidatePointer(TestLongD5, BitTestImmediateD5, CompareImmediateLongD5, 0xFFFF_FFD8u);
        ValidateVisibleViewPort(MoveAddressD5ToA0, false,
            MoveLongA0DisplacementToD4, TestLongD4, BitTestImmediateD4, CompareImmediateLongD4);
        ValidateVisibleViewPort(MoveAddressD4ToA0, false,
            MoveLongA0DisplacementToD3, TestLongD3, BitTestImmediateD3, CompareImmediateLongD3);
        ValidateVisibleViewPort(MoveAddressD3ToA0, false,
            MoveLongA0DisplacementToD2, TestLongD2, BitTestImmediateD2, CompareImmediateLongD2);
        ValidateVisibleViewPort(MoveAddressD2ToA0, false,
            MoveLongA0DisplacementToD1, TestLongD1, BitTestImmediateD1, CompareImmediateLongD1);
        ValidateVisibleViewPort(MoveAddressD1ToA0, false,
            MoveLongA0DisplacementToD7, TestLongD7, BitTestImmediateD7, CompareImmediateLongD7);
        ValidateVisibleViewPort(MoveAddressD7ToA0, true);

        // The sixth node must be a terminal standard planar source just like
        // the five nodes owned by the established prefix body.
        Append(code, MoveAddressD7ToA0);
        foreach (var linkOffset in new[]
        {
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        })
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)linkOffset));
            Append(code, TestLongD0);
            Decline();
        }
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        ValidatePointer(TestLongD0, BitTestImmediateD0, CompareImmediateLongD0, 0xFFFF_FFF4u);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
        Append(code, TestLongD0);
        Decline();

        // Validate the sixth CopList/source stream and retain its raw base in
        // D4. The five-visible body validates its own complete prefix before
        // it writes the first sixty destination entries.
        Append(code, MoveAddressD7ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(TestLongD0, BitTestImmediateD0, CompareImmediateLongD0, 0xFFFF_FFCAu);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
        Append(code, MoveLongD7ToD6);
        Append(code, CompareLongD6ToD0);
        Decline();
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListNext));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 12);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 11);
        Decline(BranchLowerOrSameWord);
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(TestLongD4, BitTestImmediateD4, CompareImmediateLongD4, 0xFFFF_FFD0u);
        foreach (var wordOffset in new[] { (ushort)44, (ushort)46 })
        {
            Append(code, MoveAddressD4ToA0);
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, wordOffset);
            Append(code, CompareImmediateWordD0);
            Append(code, wordOffset == 44
                ? GraphicsLayouts.CopperEndWait
                : GraphicsLayouts.CopperEndMask);
            Decline();
        }

        // The first CopList/raw stream and both CPR wrappers must already
        // have room for the 72-entry result. This is stricter than the
        // five-visible prefix requirement, so no post-prefix store can fail.
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(TestLongD0, BitTestImmediateD0, CompareImmediateLongD0, 0xFFFF_FFCAu);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 71);
        Decline(BranchLowerOrSameWord);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(TestLongD6, BitTestImmediateD6, CompareImmediateLongD6, 0xFFFF_FEE0u);

        foreach (var cprOffset in new[]
        {
            GraphicsLayouts.ViewLoFCprList,
            GraphicsLayouts.ViewShFCprList
        })
        {
            Append(code, MoveLongA1DisplacementToD0);
            Append(code, checked((ushort)cprOffset));
            ValidatePointer(TestLongD0, BitTestImmediateD0, CompareImmediateLongD0, 0xFFFF_FFF4u);
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CprListStart));
            Append(code, CompareLongD6ToD0);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 71);
            Decline(BranchLowerOrSameWord);
        }

        // The prefix body proves sources two through five are strictly
        // ordered. Requiring the sixth source after the enlarged destination
        // and fifth source makes the final copy disjoint before any commit.
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongImmediateD6);
        Append(code, 0);
        Append(code, 288);
        Append(code, AddLongD6ToD0);
        Append(code, CompareLongD0ToD4);
        Decline(BranchLowerOrSameWord);
        Append(code, MoveAddressD1ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(TestLongD0, BitTestImmediateD0, CompareImmediateLongD0, 0xFFFF_FFCAu);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(TestLongD2, BitTestImmediateD2, CompareImmediateLongD2, 0xFFFF_FFD0u);
        Append(code, MoveLongImmediateD6);
        Append(code, 0);
        Append(code, 48);
        Append(code, AddLongD6ToD2);
        Append(code, CompareLongD2ToD4);
        Decline(BranchLowerOrSameWord);

        // The existing five-node code has all of its own guarded validation;
        // A4's private marker merely allows the validated sixth link to stay
        // attached while it commits the first sixty entries.
        Append(code, MoveLongD1ToPreDecrementA7); // fifth ViewPort
        Append(code, MoveLongD7ToPreDecrementA7); // sixth ViewPort
        Append(code, MoveLongD4ToPreDecrementA7); // sixth raw source
        // The six-specific preflight reused D4/D2 as raw scratch. Rebuild
        // the exact five-node register shape expected by the established
        // prefix before its private call.
        Append(code, MoveLongA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, MoveAddressD4ToA0);
        Append(code, MoveLongA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, MoveAddressD3ToA0);
        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, MoveLongImmediateD6);
        Append(code, (ushort)(MrgCopFiveAllowTrailingSixMagic >> 16));
        Append(code, unchecked((ushort)MrgCopFiveAllowTrailingSixMagic));
        Append(code, MoveAddressD6ToA4);
        AppendJsrPcRelative(code, fiveVisibleMergeOffset);

        // The prefix succeeded: recover the final source/node state, append
        // the fifth separator plus the sixth 22-word body, then publish
        // Count=72 last.
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveLongA7PostIncrementToD1);
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveAddressD6ToA1);
        Append(code, MoveAddressD1ToA0);
        Append(code, MoveLongD7ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));

        Append(code, MoveLongA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        Append(code, MoveAddressD5ToA5);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        Append(code, MoveAddressD4ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 2);
        Append(code, AndImmediateWordD0);
        Append(code, 0xFF00);
        Append(code, MoveAddressD6ToA2);
        Append(code, MoveLongImmediateD5);
        Append(code, 0);
        Append(code, 236);
        Append(code, AddLongD5ToA2);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);

        Append(code, MoveAddressD4ToA1);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 4);
        Append(code, AddLongD0ToA2);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 21);
        Append(code, MoveLongD0ToD5);
        var copyLoopOffset = code.Count;
        Append(code, MoveWordA1PostIncrementToD4);
        Append(code, MoveWordD4ToA2);
        Append(code, AddQuickTwoLongA2);
        Append(code, DecrementBranchD5);
        var copyBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, copyBranchExtensionOffset, copyLoopOffset);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndWait);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, 72);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, MoveLongA7PostIncrementToD6); // original D0 discard
        Append(code, MoveLongA7PostIncrementToD6); // original A6
        Append(code, MoveAddressD6ToA6);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD6); // original A1
        Append(code, MoveAddressD6ToA1);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveAddressD6ToA6);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveAddressD4ToA4);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fiveVisibleMergeOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Emits the next bounded native merge form: five visible terminal
    /// ViewPorts with canonical twelve-entry streams.  A6 is retained on the
    /// stack because it is the library base in the normal vector ABI; after
    /// preflight it temporarily carries the fifth CopList/raw source.  The
    /// first raw stream has room for the four generated separators and the
    /// existing four-visible body remains the fallback for richer/provider
    /// shapes.
    /// </summary>
    private static int AppendMrgCopPreallocatedFiveVisibleMerge(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(192);

        void Decline(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void ValidatePointer(
            ushort testOpcode,
            ushort bitTestOpcode,
            ushort compareOpcode,
            uint maximumAddress)
        {
            Append(code, testOpcode);
            Decline(BranchEqualWord);
            Append(code, bitTestOpcode);
            Append(code, 0);
            Decline();
            Append(code, compareOpcode);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            Decline(BranchHighWord);
        }

        // Preserve the caller's GfxBase in A6 while this private arm uses it
        // as a fifth descriptor/source register.
        Append(code, MoveLongA6ToPreDecrementA7);
        Append(code, MoveLongD0ToD7);
        Append(code, MoveAddressA1ToA5);
        Append(code, MoveLongA1ToD6);
        ValidatePointer(TestLongD6, BitTestImmediateD6, CompareImmediateLongD6, 0xFFFF_FFEEu);

        // Five visible terminal ViewPorts; D5..D1 retain the node addresses.
        Append(code, MoveLongA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        ValidatePointer(TestLongD5, BitTestImmediateD5, CompareImmediateLongD5, 0xFFFF_FFD8u);
        foreach (var step in new[]
        {
            (MoveAddressD5ToA0, MoveLongA0DisplacementToD4, TestLongD4, BitTestImmediateD4, CompareImmediateLongD4),
            (MoveAddressD4ToA0, MoveLongA0DisplacementToD3, TestLongD3, BitTestImmediateD3, CompareImmediateLongD3),
            (MoveAddressD3ToA0, MoveLongA0DisplacementToD2, TestLongD2, BitTestImmediateD2, CompareImmediateLongD2),
            (MoveAddressD2ToA0, MoveLongA0DisplacementToD1, TestLongD1, BitTestImmediateD1, CompareImmediateLongD1)
        })
        {
            Append(code, step.Item1);
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
            Append(code, CompareImmediateWordD0);
            Append(code, 0);
            Decline();
            Append(code, MoveQuickZeroD0);
            Append(code, MoveByteA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
            Append(code, TestLongD0);
            Decline();
            Append(code, step.Item2);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
            ValidatePointer(step.Item3, step.Item4, step.Item5, 0xFFFF_FFD8u);
        }

        Append(code, MoveAddressD1ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Decline();
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var terminalViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA4ToD0);
        Append(code, CompareImmediateLongD0);
        Append(code, (ushort)(MrgCopFiveAllowTrailingSixMagic >> 16));
        Append(code, unchecked((ushort)MrgCopFiveAllowTrailingSixMagic));
        Decline();
        PatchBranch(code, terminalViewPortBranchExtensionOffset, code.Count);

        foreach (var vpRegister in new[]
        {
            MoveAddressD5ToA0,
            MoveAddressD4ToA0,
            MoveAddressD3ToA0,
            MoveAddressD2ToA0,
            MoveAddressD1ToA0
        })
        {
            Append(code, vpRegister);
            foreach (var linkOffset in new[]
            {
                GraphicsLayouts.ViewPortSprIns,
                GraphicsLayouts.ViewPortClrIns,
                GraphicsLayouts.ViewPortUCopIns
            })
            {
                Append(code, MoveLongA0DisplacementToD0);
                Append(code, checked((ushort)linkOffset));
                Append(code, TestLongD0);
                Decline();
            }
        }

        foreach (var vpRegister in new[]
        {
            MoveAddressD5ToA0,
            MoveAddressD4ToA0,
            MoveAddressD3ToA0,
            MoveAddressD2ToA0,
            MoveAddressD1ToA0
        })
        {
            Append(code, vpRegister);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
            ValidatePointer(TestLongD0, BitTestImmediateD0, CompareImmediateLongD0, 0xFFFF_FFF4u);
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
            Append(code, TestLongD0);
            Decline();
        }

        // Retain five CopList descriptors in A4/A3/A2/A1/A6. A0 is scratch;
        // D5..D1 remain the matching ViewPort backlink registers.
        foreach (var load in new[]
        {
            (MoveAddressD5ToA0, MoveAddressD0ToA4),
            (MoveAddressD4ToA0, MoveAddressD0ToA3),
            (MoveAddressD3ToA0, MoveAddressD0ToA2),
            (MoveAddressD2ToA0, MoveAddressD0ToA1),
            (MoveAddressD1ToA0, MoveAddressD0ToA6)
        })
        {
            Append(code, load.Item1);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
            ValidatePointer(TestLongD0, BitTestImmediateD0, CompareImmediateLongD0, 0xFFFF_FFCAu);
            Append(code, load.Item2);
        }

        foreach (var descriptor in new[]
        {
            (MoveAddressA4ToA0, MoveLongD5ToD6, 59),
            (MoveAddressA3ToA0, MoveLongD4ToD6, 11),
            (MoveAddressA2ToA0, MoveLongD3ToD6, 11),
            (MoveAddressA1ToA0, MoveLongD2ToD6, 11),
            (MoveAddressA6ToA0, MoveLongD1ToD6, 11)
        })
        {
            Append(code, descriptor.Item1);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
            Append(code, descriptor.Item2);
            Append(code, CompareLongD6ToD0);
            Decline();
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListNext));
            Append(code, TestLongD0);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 12);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
            Append(code, CompareImmediateWordD0);
            Append(code, (ushort)descriptor.Item3);
            Decline(BranchLowerOrSameWord);
        }

        // Raw destination plus four ordered sources.  The fifth source lives
        // in A6 after descriptor validation; the original A6 is restored at
        // both the success and fallback tails below.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(TestLongD6, BitTestImmediateD6, CompareImmediateLongD6, 0xFFFF_FF0Eu);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(TestLongD2, BitTestImmediateD2, CompareImmediateLongD2, 0xFFFF_FFD0u);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(TestLongD1, BitTestImmediateD1, CompareImmediateLongD1, 0xFFFF_FFD0u);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveLongA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(TestLongD3, BitTestImmediateD3, CompareImmediateLongD3, 0xFFFF_FFD0u);
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(TestLongD0, BitTestImmediateD0, CompareImmediateLongD0, 0xFFFF_FFD0u);
        Append(code, MoveAddressD0ToA6);

        foreach (var compare in new[] { CompareLongD6ToD2, CompareLongD6ToD1, CompareLongD6ToD3, CompareLongD6ToD0 })
        {
            Append(code, compare);
            Decline(BranchEqualWord);
        }
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 240);
        Append(code, AddLongD0ToD6);
        foreach (var compare in new[] { CompareLongD6ToD2, CompareLongD6ToD1, CompareLongD6ToD3 })
        {
            Append(code, compare);
            Decline(BranchLowerOrSameWord);
        }
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongA0ToD0);
        Append(code, CompareLongD6ToD0);
        Decline(BranchLowerOrSameWord);

        Append(code, MoveLongD2ToD4);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 48);
        Append(code, AddLongD0ToD4);
        foreach (var compare in new[] { CompareLongD4ToD1, CompareLongD4ToD3 })
        {
            Append(code, compare);
            Decline(BranchLowerOrSameWord);
        }
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongA0ToD0);
        Append(code, CompareLongD4ToD0);
        Decline(BranchLowerOrSameWord);

        Append(code, MoveLongD1ToD5);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 48);
        Append(code, AddLongD0ToD5);
        Append(code, CompareLongD5ToD3);
        Decline(BranchLowerOrSameWord);
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongA0ToD0);
        Append(code, CompareLongD5ToD0);
        Decline(BranchLowerOrSameWord);

        Append(code, MoveLongD3ToD4);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 48);
        Append(code, AddLongD0ToD4);
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongA0ToD0);
        Append(code, CompareLongD4ToD0);
        Decline(BranchLowerOrSameWord);

        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));

        foreach (var rawRegister in new[]
        {
            MoveAddressD6ToA0,
            MoveAddressD2ToA0,
            MoveAddressD1ToA0,
            MoveAddressD3ToA0
        })
        {
            Append(code, rawRegister);
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, 44);
            Append(code, CompareImmediateWordD0);
            Append(code, 0xFFFF);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, 46);
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.CopperEndMask);
            Decline();
        }
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 44);
        Append(code, CompareImmediateWordD0);
        Append(code, 0xFFFF);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 46);
        Append(code, CompareImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Decline();

        foreach (var cprOffset in new[] { GraphicsLayouts.ViewLoFCprList, GraphicsLayouts.ViewShFCprList })
        {
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)cprOffset));
            ValidatePointer(TestLongD0, BitTestImmediateD0, CompareImmediateLongD0, 0xFFFF_FFF4u);
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CprListStart));
            Append(code, CompareLongD6ToD0);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 59);
            Decline(BranchLowerOrSameWord);
        }

        // Commit four separators and four source bodies, then publish the
        // sixty-entry count only after the final terminator is present.
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 2);
        Append(code, AndImmediateWordD0);
        Append(code, 0xFF00);
        Append(code, MoveAddressD6ToA2);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 44);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 46);

        void AppendCopy(ushort sourceAddress, int destinationOffset, ref int loopOffset, ref int branchExtensionOffset)
        {
            Append(code, sourceAddress);
            Append(code, MoveLongImmediateD0);
            Append(code, 0);
            Append(code, (ushort)destinationOffset);
            Append(code, AddLongD0ToA2);
            Append(code, MoveLongImmediateD0);
            Append(code, 0);
            Append(code, 21);
            Append(code, MoveLongD0ToD5);
            loopOffset = code.Count;
            Append(code, MoveWordA1PostIncrementToD4);
            Append(code, MoveWordD4ToA2);
            Append(code, AddQuickTwoLongA2);
            Append(code, DecrementBranchD5);
            branchExtensionOffset = code.Count;
            Append(code, 0);
            PatchBranch(code, branchExtensionOffset, loopOffset);
        }

        var secondCopyLoopOffset = 0;
        var secondCopyBranchExtensionOffset = 0;
        Append(code, MoveAddressD6ToA2);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 48);
        Append(code, AddLongD0ToA2);
        AppendCopy(MoveAddressD2ToA1, 0, ref secondCopyLoopOffset, ref secondCopyBranchExtensionOffset);
        Append(code, MoveAddressD1ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 2);
        Append(code, AndImmediateWordD0);
        Append(code, 0xFF00);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);
        var thirdCopyLoopOffset = 0;
        var thirdCopyBranchExtensionOffset = 0;
        AppendCopy(MoveAddressD1ToA1, 4, ref thirdCopyLoopOffset, ref thirdCopyBranchExtensionOffset);
        Append(code, MoveAddressD3ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 2);
        Append(code, AndImmediateWordD0);
        Append(code, 0xFF00);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);
        var fourthCopyLoopOffset = 0;
        var fourthCopyBranchExtensionOffset = 0;
        AppendCopy(MoveAddressD3ToA1, 4, ref fourthCopyLoopOffset, ref fourthCopyBranchExtensionOffset);
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 2);
        Append(code, AndImmediateWordD0);
        Append(code, 0xFF00);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);
        var fifthCopyLoopOffset = 0;
        var fifthCopyBranchExtensionOffset = 0;
        AppendCopy(MoveAddressA6ToA1, 4, ref fifthCopyLoopOffset, ref fifthCopyBranchExtensionOffset);

        Append(code, MoveImmediateWordD0);
        Append(code, 0xFFFF);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, 60);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveAddressD6ToA6);
        Append(code, MoveLongImmediateD7);
        Append(code, (ushort)(MrgCopFiveSuccessMagic >> 16));
        Append(code, unchecked((ushort)MrgCopFiveSuccessMagic));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveAddressA5ToA1);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveAddressD6ToA6);
        Append(code, MoveLongA6ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, (ushort)(MrgCopPrivatePrefixA6Magic >> 16));
        Append(code, unchecked((ushort)MrgCopPrivatePrefixA6Magic));
        Append(code, BranchNotEqualWord);
        var publicFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD7);
        Append(code, ReturnFromSubroutine);
        var publicFallbackOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, publicFallbackBranchExtensionOffset, publicFallbackOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Emits the next bounded native merge form: four visible terminal
    /// ViewPorts with canonical twelve-entry streams.  This is intentionally
    /// a strict, preallocated in-place unit: the first raw stream has room
    /// for the three generated separators, all four source streams are
    /// distinct and ordered, and the existing three-visible body remains the
    /// fallback for every richer/provider-owned shape.
    /// </summary>
    private static int AppendMrgCopPreallocatedFourVisibleMerge(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(160);

        void Decline(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void ValidatePointer(
            ushort testOpcode,
            ushort bitTestOpcode,
            ushort compareOpcode,
            uint maximumAddress)
        {
            Append(code, testOpcode);
            Decline(BranchEqualWord);
            Append(code, bitTestOpcode);
            Append(code, 0);
            Decline();
            Append(code, compareOpcode);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            Decline(BranchHighWord);
        }

        Append(code, MoveLongD0ToD7);
        Append(code, MoveAddressA1ToA5);
        Append(code, MoveLongA1ToD6);
        ValidatePointer(TestLongD6, BitTestImmediateD6, CompareImmediateLongD6, 0xFFFF_FFEEu);

        // Four visible, terminal ViewPorts.  Keep the four node addresses in
        // D5..D2 until all public links and alternate providers are checked.
        Append(code, MoveLongA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        ValidatePointer(TestLongD5, BitTestImmediateD5, CompareImmediateLongD5, 0xFFFF_FFD8u);
        foreach (var node in new[]
        {
            (MoveAddressD5ToA0, MoveLongA0DisplacementToD4),
            (MoveAddressD4ToA0, MoveLongA0DisplacementToD3),
            (MoveAddressD3ToA0, MoveLongA0DisplacementToD2)
        })
        {
            Append(code, node.Item1);
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
            Append(code, CompareImmediateWordD0);
            Append(code, 0);
            Decline();
            Append(code, MoveQuickZeroD0);
            Append(code, MoveByteA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
            Append(code, TestLongD0);
            Decline();
            Append(code, node.Item2);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
            ValidatePointer(
                node.Item2 == MoveLongA0DisplacementToD4 ? TestLongD4 :
                node.Item2 == MoveLongA0DisplacementToD3 ? TestLongD3 : TestLongD2,
                node.Item2 == MoveLongA0DisplacementToD4 ? BitTestImmediateD4 :
                node.Item2 == MoveLongA0DisplacementToD3 ? BitTestImmediateD3 : BitTestImmediateD2,
                node.Item2 == MoveLongA0DisplacementToD4 ? CompareImmediateLongD4 :
                node.Item2 == MoveLongA0DisplacementToD3 ? CompareImmediateLongD3 : CompareImmediateLongD2,
                0xFFFF_FFD8u);
        }

        Append(code, MoveAddressD2ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Decline();
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD0);
        Decline();

        foreach (var vpRegister in new[] { MoveAddressD5ToA0, MoveAddressD4ToA0, MoveAddressD3ToA0, MoveAddressD2ToA0 })
        {
            Append(code, vpRegister);
            foreach (var linkOffset in new[]
            {
                GraphicsLayouts.ViewPortSprIns,
                GraphicsLayouts.ViewPortClrIns,
                GraphicsLayouts.ViewPortUCopIns
            })
            {
                Append(code, MoveLongA0DisplacementToD0);
                Append(code, checked((ushort)linkOffset));
                Append(code, TestLongD0);
                Decline();
            }
        }

        foreach (var vpRegister in new[] { MoveAddressD5ToA0, MoveAddressD4ToA0, MoveAddressD3ToA0, MoveAddressD2ToA0 })
        {
            Append(code, vpRegister);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
            ValidatePointer(TestLongD0, BitTestImmediateD0, CompareImmediateLongD0, 0xFFFF_FFF4u);
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
            Append(code, TestLongD0);
            Decline();
        }

        // Keep CopList descriptors in A4/A3/A2/A1 while A0 is the read
        // scratch.  The viewport pointers remain in D5..D2 for backlinks.
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(TestLongD0, BitTestImmediateD0, CompareImmediateLongD0, 0xFFFF_FFCAu);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveAddressD4ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(TestLongD0, BitTestImmediateD0, CompareImmediateLongD0, 0xFFFF_FFCAu);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveAddressD3ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(TestLongD0, BitTestImmediateD0, CompareImmediateLongD0, 0xFFFF_FFCAu);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(TestLongD0, BitTestImmediateD0, CompareImmediateLongD0, 0xFFFF_FFCAu);
        Append(code, MoveAddressD0ToA1);

        foreach (var descriptor in new[]
        {
            (MoveAddressA4ToA0, MoveLongD5ToD6, 47),
            (MoveAddressA3ToA0, MoveLongD4ToD6, 11),
            (MoveAddressA2ToA0, MoveLongD3ToD6, 11),
            (MoveAddressA1ToA0, MoveLongD2ToD6, 11)
        })
        {
            Append(code, descriptor.Item1);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
            Append(code, descriptor.Item2);
            Append(code, CompareLongD6ToD0);
            Decline();
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListNext));
            Append(code, TestLongD0);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 12);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
            Append(code, CompareImmediateWordD0);
            Append(code, (ushort)descriptor.Item3);
            Decline(BranchLowerOrSameWord);
        }

        // Raw destination and three source spans.  The bounded native unit
        // requires the source spans to be ordered after the destination and
        // after one another, which makes every copy source stable in-place.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(TestLongD6, BitTestImmediateD6, CompareImmediateLongD6, 0xFFFF_FF10u);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(TestLongD2, BitTestImmediateD2, CompareImmediateLongD2, 0xFFFF_FFD0u);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(TestLongD1, BitTestImmediateD1, CompareImmediateLongD1, 0xFFFF_FFD0u);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveLongA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(TestLongD3, BitTestImmediateD3, CompareImmediateLongD3, 0xFFFF_FFD0u);
        Append(code, CompareLongD6ToD2);
        Decline(BranchEqualWord);
        Append(code, CompareLongD6ToD1);
        Decline(BranchEqualWord);
        Append(code, CompareLongD6ToD3);
        Decline(BranchEqualWord);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 192);
        Append(code, AddLongD0ToD6);
        Append(code, CompareLongD6ToD2);
        Decline(BranchLowerOrSameWord);
        Append(code, CompareLongD6ToD1);
        Decline(BranchLowerOrSameWord);
        Append(code, CompareLongD6ToD3);
        Decline(BranchLowerOrSameWord);
        Append(code, MoveLongD2ToD4);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 48);
        Append(code, AddLongD0ToD4);
        Append(code, CompareLongD4ToD1);
        Decline(BranchLowerOrSameWord);
        Append(code, CompareLongD4ToD3);
        Decline(BranchLowerOrSameWord);
        Append(code, MoveLongD1ToD5);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 48);
        Append(code, AddLongD0ToD5);
        Append(code, CompareLongD5ToD3);
        Decline(BranchLowerOrSameWord);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));

        foreach (var rawRegister in new[] { MoveAddressD6ToA0, MoveAddressD2ToA0, MoveAddressD1ToA0, MoveAddressD3ToA0 })
        {
            Append(code, rawRegister);
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, 44);
            Append(code, CompareImmediateWordD0);
            Append(code, 0xFFFF);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, 46);
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.CopperEndMask);
            Decline();
        }

        foreach (var cprOffset in new[] { GraphicsLayouts.ViewLoFCprList, GraphicsLayouts.ViewShFCprList })
        {
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)cprOffset));
            ValidatePointer(TestLongD0, BitTestImmediateD0, CompareImmediateLongD0, 0xFFFF_FFF4u);
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CprListStart));
            Append(code, CompareLongD6ToD0);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 47);
            Decline(BranchLowerOrSameWord);
        }

        // Commit three separators and three 22-word bodies.  A2 advances
        // monotonically through the destination, so Count=48 is published
        // only after the final terminator has been written.
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 2);
        Append(code, AndImmediateWordD0);
        Append(code, 0xFF00);
        Append(code, MoveAddressD6ToA2);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 44);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 46);

        Append(code, MoveAddressD2ToA1);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 48);
        Append(code, AddLongD0ToA2);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 21);
        Append(code, MoveLongD0ToD5);
        var secondCopyLoopOffset = code.Count;
        Append(code, MoveWordA1PostIncrementToD4);
        Append(code, MoveWordD4ToA2);
        Append(code, AddQuickTwoLongA2);
        Append(code, DecrementBranchD5);
        var secondCopyBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, secondCopyBranchExtensionOffset, secondCopyLoopOffset);

        Append(code, MoveAddressD1ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 2);
        Append(code, AndImmediateWordD0);
        Append(code, 0xFF00);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);

        Append(code, MoveAddressD1ToA1);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 4);
        Append(code, AddLongD0ToA2);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 21);
        Append(code, MoveLongD0ToD5);
        var thirdCopyLoopOffset = code.Count;
        Append(code, MoveWordA1PostIncrementToD4);
        Append(code, MoveWordD4ToA2);
        Append(code, AddQuickTwoLongA2);
        Append(code, DecrementBranchD5);
        var thirdCopyBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, thirdCopyBranchExtensionOffset, thirdCopyLoopOffset);

        Append(code, MoveAddressD3ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 2);
        Append(code, AndImmediateWordD0);
        Append(code, 0xFF00);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);

        Append(code, MoveAddressD3ToA1);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 4);
        Append(code, AddLongD0ToA2);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 21);
        Append(code, MoveLongD0ToD5);
        var fourthCopyLoopOffset = code.Count;
        Append(code, MoveWordA1PostIncrementToD4);
        Append(code, MoveWordD4ToA2);
        Append(code, AddQuickTwoLongA2);
        Append(code, DecrementBranchD5);
        var fourthCopyBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fourthCopyBranchExtensionOffset, fourthCopyLoopOffset);

        Append(code, MoveImmediateWordD0);
        Append(code, 0xFFFF);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, 48);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveAddressA5ToA1);
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Emits the next bounded native merge form: three visible terminal
    /// ViewPorts, each carrying the canonical twelve-entry standard-planar
    /// stream.  The first raw stream is expanded in place to hold all three
    /// bodies (two WAIT separators plus the final terminator); the first
    /// CopList and both CPR wrappers publish a 36-entry capacity/count.  This
    /// deliberately conservative shape keeps arbitrary/provider-owned chains
    /// on the two-visible/compatibility owners while extending the future
    /// native-ROM path one complete merge unit at a time.
    /// </summary>
    private static int AppendMrgCopPreallocatedThreeVisibleMerge(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(128);

        void Decline(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void ValidatePointer(
            ushort testOpcode,
            ushort bitTestOpcode,
            ushort compareOpcode,
            uint maximumAddress)
        {
            Append(code, testOpcode);
            Decline(BranchEqualWord);
            Append(code, bitTestOpcode);
            Append(code, 0);
            Decline();
            Append(code, compareOpcode);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            Decline(BranchHighWord);
        }

        // D7 preserves the caller's result on every decline. A5 retains the
        // original View so the alias/compatibility tail receives A1 intact.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveAddressA1ToA5);
        Append(code, MoveLongA1ToD6);
        ValidatePointer(
            TestLongD6,
            BitTestImmediateD6,
            CompareImmediateLongD6,
            0xFFFF_FFEEu); // ViewSize

        // Three visible terminal ViewPorts, no alternate providers, and no
        // extended-mode handoff. D5/D4/D3 retain the node addresses.
        Append(code, MoveLongA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        ValidatePointer(
            TestLongD5,
            BitTestImmediateD5,
            CompareImmediateLongD5,
            0xFFFF_FFD8u);
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Decline();
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        ValidatePointer(
            TestLongD4,
            BitTestImmediateD4,
            CompareImmediateLongD4,
            0xFFFF_FFD8u);

        Append(code, MoveAddressD4ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Decline();
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveLongA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        ValidatePointer(
            TestLongD3,
            BitTestImmediateD3,
            CompareImmediateLongD3,
            0xFFFF_FFD8u);

        Append(code, MoveAddressD3ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Decline();
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD0);
        Decline();

        foreach (var linkOffset in new[]
        {
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        })
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)linkOffset));
            Append(code, TestLongD0);
            Decline();
        }
        Append(code, MoveAddressD5ToA0);
        foreach (var linkOffset in new[]
        {
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        })
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)linkOffset));
            Append(code, TestLongD0);
            Decline();
        }
        Append(code, MoveAddressD4ToA0);
        foreach (var linkOffset in new[]
        {
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        })
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)linkOffset));
            Append(code, TestLongD0);
            Decline();
        }

        // Each RasInfo is a complete unlinked envelope. The bitmap itself is
        // provider-owned and is intentionally not dereferenced here.
        foreach (var (moveAddress, testOpcode, bitTestOpcode, compareOpcode) in new[]
        {
            (MoveAddressD5ToA0, TestLongD0, BitTestImmediateD0, CompareImmediateLongD0),
            (MoveAddressD4ToA0, TestLongD0, BitTestImmediateD0, CompareImmediateLongD0),
            (MoveAddressD3ToA0, TestLongD0, BitTestImmediateD0, CompareImmediateLongD0)
        })
        {
            Append(code, moveAddress);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
            ValidatePointer(testOpcode, bitTestOpcode, compareOpcode, 0xFFFF_FFF4u);
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
            Append(code, TestLongD0);
            Decline();
        }

        // Load and preserve all three CopList pointers. A4 keeps the first
        // descriptor while D6/D2/D1 are later repurposed as raw pointers.
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(
            TestLongD6,
            BitTestImmediateD6,
            CompareImmediateLongD6,
            0xFFFF_FFCAu);
        Append(code, MoveAddressD6ToA4);

        Append(code, MoveAddressD4ToA0);
        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(
            TestLongD2,
            BitTestImmediateD2,
            CompareImmediateLongD2,
            0xFFFF_FFCAu);

        Append(code, MoveAddressD3ToA0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(
            TestLongD1,
            BitTestImmediateD1,
            CompareImmediateLongD1,
            0xFFFF_FFCAu);

        // CopList shape and capacity. The first descriptor holds the merged
        // 36-entry publication; each source remains exactly twelve entries.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
        Append(code, MoveLongD5ToD6);
        Append(code, CompareLongD6ToD0);
        Decline();
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListNext));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 12);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 35);
        Decline(BranchLowerOrSameWord);

        foreach (var (copRegister, viewRegister, copTest, copBit, copCompare) in new[]
        {
            (MoveAddressD2ToA0, MoveLongD4ToD6, TestLongD2, BitTestImmediateD2, CompareImmediateLongD2),
            (MoveAddressD1ToA0, MoveLongD3ToD6, TestLongD1, BitTestImmediateD1, CompareImmediateLongD1)
        })
        {
            Append(code, copRegister);
            // The CopList pointer is already retained in D2/D1. The tuple's
            // second opcode documents which ViewPort backlink is expected;
            // the actual load below uses D6 as the compare scratch.
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
            Append(code, viewRegister);
            Append(code, CompareLongD6ToD0);
            Decline();
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListNext));
            Append(code, TestLongD0);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 12);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 11);
            Decline(BranchLowerOrSameWord);
        }

        // Raw pointers: first is a 144-byte destination; second and third
        // are 48-byte source spans. Require strict non-overlap so every
        // source remains readable for the two copy loops.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(
            TestLongD6,
            BitTestImmediateD6,
            CompareImmediateLongD6,
            0xFFFF_FF70u);
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(
            TestLongD2,
            BitTestImmediateD2,
            CompareImmediateLongD2,
            0xFFFF_FFD0u);
        Append(code, MoveAddressD1ToA0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(
            TestLongD1,
            BitTestImmediateD1,
            CompareImmediateLongD1,
            0xFFFF_FFD0u);
        Append(code, CompareLongD6ToD2);
        Decline(BranchEqualWord);
        Append(code, CompareLongD6ToD1);
        Decline(BranchEqualWord);
        Append(code, MoveLongD2ToD6);
        Append(code, CompareLongD6ToD1);
        Decline(BranchEqualWord);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));

        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 144);
        Append(code, AddLongD0ToD6);
        Append(code, CompareLongD6ToD2);
        Decline(BranchLowerOrSameWord);
        Append(code, CompareLongD6ToD1);
        Decline(BranchLowerOrSameWord);
        Append(code, MoveLongD2ToD4);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 48);
        Append(code, AddLongD0ToD4);
        Append(code, CompareLongD4ToD1);
        Decline(BranchLowerOrSameWord);

        // D6 now holds destination+144 from the overlap checks. Restore the
        // original destination before canonical-word validation and commit.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));

        // Canonical source terminators at +44/+46 for all three streams.
        foreach (var rawRegister in new[]
        {
            MoveAddressD6ToA0,
            MoveAddressD2ToA0,
            MoveAddressD1ToA0
        })
        {
            Append(code, rawRegister);
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, 44);
            Append(code, CompareImmediateWordD0);
            Append(code, 0xFFFF);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, 46);
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.CopperEndMask);
            Decline();
        }

        // LOF/SHF CPR wrappers already point at the destination and have
        // capacity for 36 entries. Neither wrapper is rewritten here.
        foreach (var viewCprOffset in new[]
        {
            GraphicsLayouts.ViewLoFCprList,
            GraphicsLayouts.ViewShFCprList
        })
        {
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)viewCprOffset));
            ValidatePointer(
                TestLongD0,
                BitTestImmediateD0,
                CompareImmediateLongD0,
                0xFFFF_FFF4u);
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CprListStart));
            Append(code, CompareLongD6ToD0);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 35);
            Decline(BranchLowerOrSameWord);
        }

        // Commit the two separators, copy each 22-word source body, append
        // the final terminator, and publish the first Count only at the end.
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 2);
        Append(code, AndImmediateWordD0);
        Append(code, 0xFF00);
        Append(code, MoveAddressD6ToA2);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 44);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 46);

        Append(code, MoveAddressD2ToA1);
        Append(code, MoveAddressD6ToA2);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 48);
        Append(code, AddLongD0ToA2);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 21);
        Append(code, MoveLongD0ToD5);
        var secondCopyLoopOffset = code.Count;
        Append(code, MoveWordA1PostIncrementToD4);
        Append(code, MoveWordD4ToA2);
        Append(code, AddQuickTwoLongA2);
        Append(code, DecrementBranchD5);
        var secondCopyBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, secondCopyBranchExtensionOffset, secondCopyLoopOffset);

        Append(code, MoveAddressD1ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 2);
        Append(code, AndImmediateWordD0);
        Append(code, 0xFF00);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);

        Append(code, MoveAddressD1ToA1);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 4);
        Append(code, AddLongD0ToA2);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 21);
        Append(code, MoveLongD0ToD5);
        var thirdCopyLoopOffset = code.Count;
        Append(code, MoveWordA1PostIncrementToD4);
        Append(code, MoveWordD4ToA2);
        Append(code, AddQuickTwoLongA2);
        Append(code, DecrementBranchD5);
        var thirdCopyBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, thirdCopyBranchExtensionOffset, thirdCopyLoopOffset);

        Append(code, MoveImmediateWordD0);
        Append(code, 0xFFFF);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, 2);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, 36);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveAddressA5ToA1);
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        return offset;
    }

    private static int AppendSetOutlinePen(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(3);
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x0800); // D4, reversed predecrement mask.

        // SetOutlinePen takes A0 and returns the previous AOlPen in D0, publishing
        // the new pen and setting AREAOUTLINE in the Flags word. Its complete
        // public transaction reaches the Flags WORD, so admit that aligned,
        // non-wrapping RastPort envelope before the first read or write.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // RastPortFlags (0x20) + WORD envelope
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);

        // Preserve the full caller value in D1 before narrowing the byte
        // field. D0 carries the resident old-outline-pen result.
        Append(code, MoveLongD0ToD1);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortOutlinePen));
        Append(code, MoveByteD1ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortOutlinePen));
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, OrImmediateWordD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAreaOutline));
        Append(code, MoveWordD1ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x0010); // Restore public D4 after discarding the saved argument.
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x0010); // Restore D4 without changing the full decline argument.
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendSetMaxPen(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(4);

        // SetMaxPen takes A0; zero is field-free. For a nonzero ULONG, round the
        // requested range up to a contiguous low-bit mask: D1 starts at one,
        // while D2 is shifted until no higher input bit remains.
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var nonZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var nonZeroOffset = code.Count;
        PatchBranch(code, nonZeroBranchExtensionOffset, nonZeroOffset);
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x2800); // D2/D4, reversed predecrement mask; zero never enters this frame.
        // Every nonzero decline restores the original full-width request
        // before taking the portable fallback, including a value that cannot
        // fit the public one-byte mask representation.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, byte.MaxValue);
        Append(code, BranchHighWord);
        var maxPenRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maxPenRangeBranchExtensionOffset);
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        var maxAddress = uint.MaxValue - (uint)GraphicsLayouts.RastPortMask;
        Append(code, checked((ushort)(maxAddress >> 16)));
        Append(code, checked((ushort)(maxAddress & ushort.MaxValue)));
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);
        Append(code, MoveQuickOneD1);
        Append(code, MoveLongD0ToD2);
        Append(code, ShiftRightLongD2);
        Append(code, (ushort)(BranchEqualShort | 0x0008));
        Append(code, ShiftLeftLongD1);
        Append(code, OrImmediateByteD1);
        Append(code, 0x0001);
        Append(code, (ushort)(BranchAlwaysShort | 0x00F4)); // loop to LSR.L D2
        Append(code, MoveByteD1ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x0014); // Restore D2/D4 after discarding the saved nonzero argument.
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x0014); // Preserve the full decline argument and its prior CCR.
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Emits a read-only visible singleton MrgCop admission in front of the
    /// empty/hidden compatibility body.  This is deliberately limited to the
    /// caller-owned preallocated resource shape produced by the native
    /// MakeVPort slice: one visible ViewPort, one RasInfo, one DspIns CopList,
    /// and matching LOF/SHF CPR wrappers over one raw stream.  No copper bytes,
    /// links, counters, or display state are written here; resource allocation
    /// and multi-viewport merge remain explicit owners.
    /// </summary>
    private static int AppendMrgCopPreallocatedTwoVisibleAlias(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(64);

        void Decline(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void ValidateRequired(
            ushort testOpcode,
            ushort bitTestOpcode,
            ushort compareOpcode,
            uint maximumAddress)
        {
            Append(code, testOpcode);
            Decline(BranchEqualWord);
            Append(code, bitTestOpcode);
            Append(code, 0);
            Decline();
            Append(code, compareOpcode);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            Decline(BranchHighWord);
        }

        void RejectOverlap(
            ushort firstToD0,
            ushort secondToD1,
            uint firstSize,
            uint secondSize)
        {
            Append(code, firstToD0);
            Append(code, AddImmediateLongD0);
            Append(code, (ushort)(firstSize >> 16));
            Append(code, (ushort)firstSize);
            Decline(BranchCarryWord);
            Append(code, secondToD1);
            Append(code, AddImmediateLongD1);
            Append(code, (ushort)(secondSize >> 16));
            Append(code, (ushort)secondSize);
            Decline(BranchCarryWord);

            // FirstEnd <= SecondBase is disjoint.  Otherwise reload the
            // first base and prove SecondEnd <= FirstBase; only the
            // remaining interval is an overlap.
            Append(code, CompareLongD1ToD0);
            Append(code, BranchLowerOrSameWord);
            var firstBeforeSecondBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, firstToD0);
            Append(code, CompareLongD0ToD1);
            Append(code, BranchLowerOrSameWord);
            var secondBeforeFirstBranchExtensionOffset = code.Count;
            Append(code, 0);
            Decline(BranchAlwaysWord);

            var disjointOffset = code.Count;
            PatchBranch(
                code,
                firstBeforeSecondBranchExtensionOffset,
                disjointOffset);
            PatchBranch(
                code,
                secondBeforeFirstBranchExtensionOffset,
                disjointOffset);
        }

        // MrgCop receives View in A1 and reports its status in D0. Preserve
        // D0 on every decline; the alias form is strictly read-only.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA1ToD6);
        ValidateRequired(
            TestLongD6,
            BitTestImmediateD6,
            CompareImmediateLongD6,
            0xFFFF_FFEEu); // ViewSize

        // Require exactly two visible, terminal ViewPorts. A longer or
        // hidden/provider-shaped chain stays on the normal merge owner.
        Append(code, MoveLongA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        ValidateRequired(
            TestLongD5,
            BitTestImmediateD5,
            CompareImmediateLongD5,
            0xFFFF_FFD8u); // ViewPortRasInfo at +0x24 envelope
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Decline();
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        ValidateRequired(
            TestLongD4,
            BitTestImmediateD4,
            CompareImmediateLongD4,
            0xFFFF_FFD8u); // ViewPortRasInfo at +0x24 envelope

        // Both visible nodes are native public envelopes.  A direct call to
        // this multi-viewport body must enforce the same root/viewport
        // separation as the common MrgCop entry, including the second node.
        RejectOverlap(
            MoveLongD5ToD0,
            MoveLongD6ToD1,
            (uint)GraphicsLayouts.ViewPortSize,
            (uint)GraphicsLayouts.ViewSize);
        RejectOverlap(
            MoveLongD4ToD0,
            MoveLongD6ToD1,
            (uint)GraphicsLayouts.ViewPortSize,
            (uint)GraphicsLayouts.ViewSize);
        RejectOverlap(
            MoveLongD5ToD0,
            MoveLongD4ToD1,
            (uint)GraphicsLayouts.ViewPortSize,
            (uint)GraphicsLayouts.ViewPortSize);

        Append(code, MoveAddressD4ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Decline();
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD0);
        Decline(BranchNotEqualWord);

        // Both visible nodes must expose bounded RasInfo/DspIns envelopes;
        // linked RasInfo is outside this pre-merged no-op form.
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        ValidateRequired(
            TestLongD0,
            BitTestImmediateD0,
            CompareImmediateLongD0,
            0xFFFF_FFF4u); // RasInfoSize
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
        Append(code, TestLongD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidateRequired(
            TestLongD3,
            BitTestImmediateD3,
            CompareImmediateLongD3,
            0xFFFF_FFCAu); // CopListSize

        Append(code, MoveAddressD4ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        ValidateRequired(
            TestLongD0,
            BitTestImmediateD0,
            CompareImmediateLongD0,
            0xFFFF_FFF4u);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
        Append(code, TestLongD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveAddressD4ToA0);
        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidateRequired(
            TestLongD2,
            BitTestImmediateD2,
            CompareImmediateLongD2,
            0xFFFF_FFCAu);

        // The two CopLists must point back to their respective ViewPorts and
        // agree on one shared raw stream. Each list is the exact pre-merged
        // 12-entry form emitted by native MakeVPort.
        Append(code, MoveAddressD3ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
        Append(code, MoveLongD5ToD6);
        Append(code, CompareLongD6ToD0);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 12);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 12);
        Decline();
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListNext));
        Append(code, TestLongD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidateRequired(
            TestLongD0,
            BitTestImmediateD0,
            CompareImmediateLongD0,
            0xFFFF_FFFCu);
        Append(code, MoveLongD0ToD1);
        foreach (var fieldOffset in new[]
        {
            GraphicsLayouts.CopListCopLStart,
            GraphicsLayouts.CopListCopSStart
        })
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)fieldOffset));
            Append(code, CompareLongD0ToD1);
            Decline();
        }

        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
        Append(code, MoveLongD4ToD6);
        Append(code, CompareLongD6ToD0);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 12);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 12);
        Decline();
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListNext));
        Append(code, TestLongD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidateRequired(
            TestLongD0,
            BitTestImmediateD0,
            CompareImmediateLongD0,
            0xFFFF_FFFCu);
        Append(code, CompareLongD0ToD1);
        Decline();
        foreach (var fieldOffset in new[]
        {
            GraphicsLayouts.CopListCopLStart,
            GraphicsLayouts.CopListCopSStart
        })
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)fieldOffset));
            Append(code, CompareLongD0ToD1);
            Decline();
        }

        // View LOF/SHF wrappers must both start at the same shared stream and
        // expose the native twelve-entry capacity. No wrapper or raw bytes
        // are modified by this admission.
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewLoFCprList));
        ValidateRequired(
            TestLongD0,
            BitTestImmediateD0,
            CompareImmediateLongD0,
            0xFFFF_FFF4u);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CprListStart));
        Append(code, CompareLongD0ToD1);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 12);
        Decline();

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewShFCprList));
        ValidateRequired(
            TestLongD0,
            BitTestImmediateD0,
            CompareImmediateLongD0,
            0xFFFF_FFF4u);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CprListStart));
        Append(code, CompareLongD0ToD1);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 12);
        Decline();

        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        return offset;
    }

    private static int AppendMrgCopPreallocatedVisible(
        List<byte> code,
        int multiViewportOffset,
        int emptyOrHiddenOffset)
    {
        var offset = code.Count;
        var hiddenBranches = new List<int>(24);

        void BranchToEmptyOrHidden(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            hiddenBranches.Add(extensionOffset);
        }

        void ValidatePointer(
            ushort testOpcode,
            ushort bitTestOpcode,
            ushort compareOpcode,
            uint maximumAddress)
        {
            Append(code, testOpcode);
            BranchToEmptyOrHidden(BranchEqualWord);
            Append(code, bitTestOpcode);
            Append(code, 0);
            BranchToEmptyOrHidden(BranchNotEqualWord);
            Append(code, compareOpcode);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            BranchToEmptyOrHidden(BranchHighWord);
        }

        // MrgCop's View argument is A1 and D0 is the status/result register.
        // Preserve the original D0 while this admission uses the data
        // registers as pointer scratch; the compatibility body owns all
        // malformed/hidden/empty forms through the normal fallback contract.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA1ToD6);
        ValidatePointer(
            TestLongD6,
            BitTestImmediateD6,
            CompareImmediateLongD6,
            0xFFFF_FFEEu); // ViewSize

        // View.ViewPort == NULL is the classic empty-view no-op.  Hidden
        // ViewPorts are admitted by the existing bounded read-only body.
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, TestLongD0);
        BranchToEmptyOrHidden(BranchEqualWord);

        // MrgCop's native visible arm owns the root View and its public
        // ViewPort envelope. Reject wrapping or partial overlap before the
        // viewport base is reused for deeper admission; the empty/hidden
        // compatibility owner retains the original D0 on this decline.
        Append(code, MoveLongD0ToD1);
        Append(code, AddImmediateLongD1);
        Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.ViewPortSize);
        BranchToEmptyOrHidden(BranchCarryWord);
        Append(code, CompareLongD6ToD0); // ViewPort base - View base
        Append(code, BranchLowerOrSameWord);
        var viewportBeforeViewDisjointBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveLongD6ToD3);
        Append(code, AddImmediateLongD3);
        Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.ViewSize);
        BranchToEmptyOrHidden(BranchCarryWord);
        Append(code, CompareLongD0ToD3); // View end - ViewPort base
        Append(code, BranchLowerOrSameWord);
        var viewBeforeViewportDisjointBranchExtensionOffset = code.Count;
        Append(code, 0);
        BranchToEmptyOrHidden(BranchAlwaysWord);

        var viewportBeforeViewOffset = code.Count;
        PatchBranch(
            code,
            viewportBeforeViewDisjointBranchExtensionOffset,
            viewportBeforeViewOffset);
        Append(code, CompareLongD6ToD1); // ViewPort end - View base
        Append(code, BranchLowerOrSameWord);
        var viewportBeforeViewDisjointBranchExtensionOffset2 = code.Count;
        Append(code, 0);
        BranchToEmptyOrHidden(BranchAlwaysWord);

        var viewViewPortDisjointOffset = code.Count;
        PatchBranch(
            code,
            viewBeforeViewportDisjointBranchExtensionOffset,
            viewViewPortDisjointOffset);
        PatchBranch(
            code,
            viewportBeforeViewDisjointBranchExtensionOffset2,
            viewViewPortDisjointOffset);

        Append(code, MoveLongD0ToD6); // retain the ViewPort base
        ValidatePointer(
            TestLongD6,
            BitTestImmediateD6,
            CompareImmediateLongD6,
            0xFFFF_FFD8u); // ViewPortRasInfo at +0x24 envelope

        Append(code, MoveAddressD6ToA0);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        // A set hidden bit belongs to the bounded hidden chain body.
        BranchToEmptyOrHidden(BranchNotEqualWord);

        // The native admission is a single visible ViewPort.  A linked
        // visible chain belongs to the complete multi-viewport owner; retain
        // the caller's original D0 before handing it off.
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var singletonViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var multiViewportDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, multiViewportDispatchBranchExtensionOffset, multiViewportOffset);
        PatchBranch(code, singletonViewPortBranchExtensionOffset, code.Count);

        // vp_RasInfo and vp_DspIns must both be caller-owned, bounded
        // envelopes.  Keep the values in D3/D2 for the final signature.
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, MoveLongD0ToD3);
        ValidatePointer(
            TestLongD3,
            BitTestImmediateD3,
            CompareImmediateLongD3,
            0xFFFF_FFF4u); // RasInfoSize

        // RasInfo is a public envelope in the native singleton form, not an
        // opaque provider handle.  Keep it disjoint from both the root View
        // and the selected ViewPort before any later copper/resource reads.
        // D2 is still scratch here; the CopList base is loaded only after
        // this transaction has passed.
        Append(code, MoveLongD3ToD0);
        Append(code, AddImmediateLongD0);
        Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RasInfoSize);
        BranchToEmptyOrHidden(BranchCarryWord);
        Append(code, MoveLongA1ToD1); // root View base
        Append(code, MoveLongD1ToD2);
        Append(code, AddImmediateLongD2);
        Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.ViewSize); // root View end
        Append(code, CompareLongD1ToD0); // RasInfo end - View base
        Append(code, BranchLowerOrSameWord);
        var rasInfoBeforeViewDisjointBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD3ToD1); // RasInfo base
        Append(code, CompareLongD1ToD2); // View end - RasInfo base
        Append(code, BranchLowerOrSameWord);
        var viewBeforeRasInfoDisjointBranchExtensionOffset = code.Count;
        Append(code, 0);
        BranchToEmptyOrHidden(BranchAlwaysWord);

        var rasInfoBeforeViewOffset = code.Count;
        PatchBranch(
            code,
            rasInfoBeforeViewDisjointBranchExtensionOffset,
            rasInfoBeforeViewOffset);
        Append(code, CompareLongD6ToD0); // RasInfo end - ViewPort base
        Append(code, BranchLowerOrSameWord);
        var rasInfoBeforeViewPortDisjointBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD3ToD0); // RasInfo base
        Append(code, MoveLongD6ToD1);
        Append(code, AddImmediateLongD1);
        Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.ViewPortSize); // ViewPort end
        Append(code, CompareLongD0ToD1); // ViewPort end - RasInfo base
        Append(code, BranchLowerOrSameWord);
        var viewPortBeforeRasInfoDisjointBranchExtensionOffset = code.Count;
        Append(code, 0);
        BranchToEmptyOrHidden(BranchAlwaysWord);

        var rasInfoViewDisjointOffset = code.Count;
        PatchBranch(
            code,
            viewBeforeRasInfoDisjointBranchExtensionOffset,
            rasInfoBeforeViewOffset);
        PatchBranch(
            code,
            rasInfoBeforeViewPortDisjointBranchExtensionOffset,
            rasInfoViewDisjointOffset);
        PatchBranch(
            code,
            viewPortBeforeRasInfoDisjointBranchExtensionOffset,
            rasInfoViewDisjointOffset);

        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(
            TestLongD2,
            BitTestImmediateD2,
            CompareImmediateLongD2,
            0xFFFF_FFCAu); // CopListSize

        // The View's LOF/SHF wrappers are required and must be bounded CPR
        // envelopes. Their exact starts are checked against the CopList raw
        // stream below, so a split-field or provider-shaped resource declines.
        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewLoFCprList));
        ValidatePointer(
            TestLongD4,
            BitTestImmediateD4,
            CompareImmediateLongD4,
            0xFFFF_FFF4u); // CprListSize
        // There is no dedicated A1->D5 displacement opcode in the compact
        // emitter; load through D0 and retain it in D5.
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewShFCprList));
        Append(code, MoveLongD0ToD5);
        ValidatePointer(
            TestLongD5,
            BitTestImmediateD5,
            CompareImmediateLongD5,
            0xFFFF_FFF4u); // CprListSize

        // CopList.ViewPort must name this exact ViewPort. CopList.CopPtr,
        // CopLStart, and CopSStart must share one bounded raw stream.
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
        Append(code, CompareLongD6ToD0);
        BranchToEmptyOrHidden(BranchNotEqualWord);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        Append(code, MoveLongD0ToD1);
        ValidatePointer(
            TestLongD1,
            BitTestImmediateD1,
            CompareImmediateLongD1,
            0xFFFF_FFFCu); // four-byte raw terminator envelope
        foreach (var fieldOffset in new[]
        {
            GraphicsLayouts.CopListCopLStart,
            GraphicsLayouts.CopListCopSStart
        })
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)fieldOffset));
            Append(code, CompareLongD0ToD1);
            BranchToEmptyOrHidden(BranchNotEqualWord);
        }

        // Both CPR wrappers must use the same raw stream, have capacity, and
        // agree with the CopList's pointer. Their public links are read only.
        Append(code, MoveAddressD4ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CprListStart));
        Append(code, CompareLongD0ToD1);
        BranchToEmptyOrHidden(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        Append(code, TestWordD0);
        BranchToEmptyOrHidden(BranchEqualWord);

        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CprListStart));
        Append(code, CompareLongD0ToD1);
        BranchToEmptyOrHidden(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        Append(code, TestWordD0);
        BranchToEmptyOrHidden(BranchEqualWord);

        // A valid preallocated singleton is already assembled by MakeVPort;
        // MrgCop therefore reports MCOP_OK without claiming any allocation or
        // touching the guest stream.
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        // Every decline branch reaches the compatibility body with the
        // original D0 restored.  The body itself then owns the final
        // malformed/hidden decision and its direct RTS/fallback return.
        var hiddenDispatchOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var hiddenDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, hiddenDispatchBranchExtensionOffset, emptyOrHiddenOffset);
        foreach (var branchExtensionOffset in hiddenBranches)
            PatchBranch(code, branchExtensionOffset, hiddenDispatchOffset);
        return offset;
    }

    private static int AppendMrgCopEmptyOrHiddenView(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(18);

        // MCOP_OK for a valid View with no ViewPort is a read-only lifecycle
        // no-op.  A bounded, one- through eight-node hidden ViewPort chain whose
        // final Next link is NULL is the other read-only resident form: the
        // merge loop consumes only Modes/Next and reports MCOP_NOP without
        // touching copper links. Any visible, longer, malformed, or
        // provider-owned form remains on the portable/provider owner.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddViewBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFEE); // ViewSize (0x12) envelope
        Append(code, BranchHighWord);
        var wrappedViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedViewBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var emptyViewBranchExtensionOffset = code.Count;
        Append(code, 0);

        // The hidden form reads only the public ViewPort mode/next pair.  The
        // mode word occupies +0x20..+0x21, so the base must not exceed
        // FFFF:FFDE before
        // A0 is rebound and either field is read.
        Append(code, MoveAddressD0ToA0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddViewPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var wrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedViewPortBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var visibleViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleViewPortBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var hiddenChainSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Admit the second hidden successor. This keeps the native body
        // read-only while matching the portable bounded hidden-chain rule.
        Append(code, MoveLongD1ToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var secondOddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondOddViewPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var secondWrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondWrappedViewPortBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var secondVisibleViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleViewPortBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var thirdHiddenViewPortDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A third hidden node is admitted only as a bounded terminal node.
        // Its public mode/next pair is the complete native read envelope;
        // visible, odd, wrapped, or linked forms retain the provider owner.
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var thirdOddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(thirdOddViewPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var thirdWrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(thirdWrappedViewPortBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var thirdVisibleViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(thirdVisibleViewPortBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var fourthHiddenViewPortDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A fourth hidden node is admitted only as a bounded terminal node.
        // Keep the same mode/next-only read envelope; any visible, malformed,
        // or linked fourth node remains on the provider owner.
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fourthOddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthOddViewPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var fourthWrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthWrappedViewPortBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var fourthVisibleViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleViewPortBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var fifthHiddenViewPortEntryBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A fifth hidden node is admitted as another bounded link. Its public
        // mode/next pair is the complete native read envelope; visible or
        // malformed forms remain on the provider owner. Sixth through eighth
        // nodes below extend the same bounded terminal-chain rule.
        var fifthHiddenViewPortOffset = code.Count;
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fifthOddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fifthOddViewPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var fifthWrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fifthWrappedViewPortBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var fifthVisibleViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fifthVisibleViewPortBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var sixthHiddenViewPortEntryBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var fifthHiddenViewChainDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A sixth hidden node is admitted as another bounded link. Its public
        // mode/next pair is the complete native read envelope; visible or
        // malformed forms remain on the provider owner. A seventh node below
        // is the next bounded link.
        var sixthHiddenViewPortOffset = code.Count;
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var sixthOddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sixthOddViewPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var sixthWrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sixthWrappedViewPortBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var sixthVisibleViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sixthVisibleViewPortBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var sixthHiddenViewChainDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var seventhHiddenViewPortEntryBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A seventh hidden node is admitted as another bounded link. Keep the
        // read envelope mode/next-only and defer an eighth successor to the
        // terminal block below.
        var seventhHiddenViewPortOffset = code.Count;
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var seventhOddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(seventhOddViewPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var seventhWrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(seventhWrappedViewPortBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var seventhVisibleViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(seventhVisibleViewPortBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var seventhHiddenViewChainDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var eighthHiddenViewPortEntryBranchExtensionOffset = code.Count;
        Append(code, 0);

        // The eighth hidden node remains a bounded link. A ninth terminal
        // hidden node is admitted below so MrgCop and LoadView consume the
        // same assembling-view chain envelope.
        var eighthHiddenViewPortOffset = code.Count;
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var eighthOddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(eighthOddViewPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var eighthWrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(eighthWrappedViewPortBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var eighthVisibleViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(eighthVisibleViewPortBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var eighthLinkedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);

        // The ninth hidden node is terminal for this resident chain slice.
        // Any visible, malformed, or linked form remains provider-owned.
        var ninthHiddenViewPortOffset = code.Count;
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var ninthOddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ninthOddViewPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var ninthWrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ninthWrappedViewPortBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var ninthVisibleViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ninthVisibleViewPortBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var ninthLinkedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ninthLinkedViewPortBranchExtensionOffset);

        var hiddenChainSuccessOffset = code.Count;
        Append(code, MoveQuickTwoD0);
        Append(code, ReturnFromSubroutine);

        var emptyViewSuccessOffset = code.Count;

        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, ReturnFromSubroutine);

        PatchBranch(code, emptyViewBranchExtensionOffset, emptyViewSuccessOffset);
        PatchBranch(code, hiddenChainSuccessBranchExtensionOffset, hiddenChainSuccessOffset);
        PatchBranch(code, thirdHiddenViewPortDoneBranchExtensionOffset, hiddenChainSuccessOffset);
        PatchBranch(code, fourthHiddenViewPortDoneBranchExtensionOffset, hiddenChainSuccessOffset);
        PatchBranch(code, fifthHiddenViewPortEntryBranchExtensionOffset, fifthHiddenViewPortOffset);
        PatchBranch(code, sixthHiddenViewPortEntryBranchExtensionOffset, sixthHiddenViewPortOffset);
        PatchBranch(code, seventhHiddenViewPortEntryBranchExtensionOffset, seventhHiddenViewPortOffset);
        PatchBranch(code, eighthHiddenViewPortEntryBranchExtensionOffset, eighthHiddenViewPortOffset);
        PatchBranch(code, eighthLinkedViewPortBranchExtensionOffset, ninthHiddenViewPortOffset);
        PatchBranch(code, fifthHiddenViewChainDoneBranchExtensionOffset, hiddenChainSuccessOffset);
        PatchBranch(code, sixthHiddenViewChainDoneBranchExtensionOffset, hiddenChainSuccessOffset);
        PatchBranch(code, seventhHiddenViewChainDoneBranchExtensionOffset, hiddenChainSuccessOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    /// <summary>
    /// Allocates a standard public ColorMap and both 16-bit palette tables in
    /// one Exec-owned, CLEARed envelope.  The public pointer remains at the
    /// classic ColorMap layout; a private prefix records the marker and exact
    /// allocation span for the paired native FreeColorMap arm.
    /// </summary>
    private static int AppendGetColorMapNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(8);

        // Public vectors and AUTOINIT entries expose this same body. Save
        // its callee-saved scratch before any success or decline path.
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x0702); // MOVEM.L D5-D7/A6,-(A7), reversed save mask

        // D0 is a LONG in the ABI but the public count is a UWORD.  Zero is
        // the documented allocation-free failure form; values above 65535
        // decline to the ownership-aware portable path.
        Append(code, MoveLongD0ToD7);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var zeroEntriesBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0000);
        Append(code, 0xFFFF);
        Append(code, BranchHighWord);
        var wideEntriesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wideEntriesBranchExtensionOffset);

        // Total = private prefix + public ColorMap + two UWORD tables.
        // The count is bounded to UWORD, so the two shifts cannot overflow.
        Append(code, MoveLongD0ToD5); // retained public count
        Append(code, MoveLongD0ToD6);
        Append(code, ShiftLeftLongD6);
        Append(code, ShiftLeftLongD6);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.NativeColorMapBaseSize));
        Append(code, AddLongD1ToD6);

        // Resolve ExecBase only at the native ownership boundary.  PUBLIC |
        // CLEAR matches the portable ColorMap allocator's zeroed envelopes.
        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0001); // PUBLIC | CLEAR
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var allocationFailureBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Require both word alignment and a representable complete envelope.
        // Release a violating allocation before writing any ownership bytes.
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Check the inclusive last byte; base + size itself may legitimately
        // wrap to zero for an allocation ending exactly at $FFFFFFFF.
        // D1 is already volatile; do not add D4 to this body's scratch set.
        Append(code, MoveLongD6ToD1);
        Append(code, SubQuickOneLongD1);
        Append(code, AddLongD0ToD1);
        Append(code, BranchCarryWord);
        var wrappedAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var skipInvalidAllocationCleanupBranchExtensionOffset = code.Count;
        Append(code, 0);

        var invalidAllocationCleanupOffset = code.Count;
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongD6ToD0);
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, BranchAlwaysWord);
        var invalidAllocationJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveAddressD0ToA0); // private allocation base
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.NativeColorMapMarker);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 0);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, 4); // exact envelope span
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0); // A0 = public ColorMap

        Append(code, MoveImmediateWordD0);
        Append(code, 0x0002); // V39 ColorMap type
        Append(code, MoveByteD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapType));
        Append(code, MoveLongD5ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapCount));

        // ColorTable = map + ColorMapSize; LowColorBits follows the table.
        Append(code, MoveLongA0ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapSize));
        Append(code, AddLongD1ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapColorTable));
        Append(code, MoveLongD5ToD1);
        Append(code, ShiftLeftLongD1);
        Append(code, AddLongD1ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapLowColorBits));
        Append(code, MoveLongA0ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40E0); // MOVEM.L (A7)+,D5-D7/A6
        Append(code, ReturnFromSubroutine);

        var allocationFailureOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var allocationFailureJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var zeroSuccessOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40E0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        // Recover the original argument before restoring the caller's D7.
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40E0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, zeroEntriesBranchExtensionOffset, zeroSuccessOffset);
        PatchBranch(code, wideEntriesBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, allocationFailureBranchExtensionOffset, allocationFailureOffset);
        PatchBranch(code, oddAllocationBranchExtensionOffset, invalidAllocationCleanupOffset);
        PatchBranch(code, wrappedAllocationBranchExtensionOffset, invalidAllocationCleanupOffset);
        PatchBranch(code, skipInvalidAllocationCleanupBranchExtensionOffset, successOffset);
        PatchBranch(code, invalidAllocationJoinBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, allocationFailureJoinBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    /// <summary>
    /// Publishes the resident GfxBase ChipRevBits0 byte for the native
    /// SetChipRev contract.  The field is the chipset capability source in a
    /// native ROM image; requested bits are masked by the currently available
    /// capabilities and accumulated in the public byte.  Invalid or missing
    /// GfxBase envelopes preserve D0 and remain on the provider boundary.
    /// </summary>
    private static int AppendSetChipRevNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(4);

        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA6ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullBaseBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddBaseBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFF14); // GfxBase + 0xEC must not wrap
        Append(code, BranchHighWord);
        var wrappedBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedBaseBranchExtensionOffset);

        // D6 = capabilities currently published by the resident byte; D5
        // retains the accumulated result while D7 keeps the caller request.
        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA6DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
        Append(code, MoveQuickZeroD5);
        Append(code, MoveByteA6DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));

        Append(code, CompareImmediateLongD7);
        Append(code, 0xFFFF);
        Append(code, 0xFFFF);
        Append(code, BranchEqualWord);
        var setBestBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD7ToD0);
        Append(code, AndLongD0ToD6);

        var publishOffset = code.Count;
        Append(code, OrLongD6ToD5);
        Append(code, MoveByteD5ToA6Displacement);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
        Append(code, MoveLongD5ToD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, setBestBranchExtensionOffset, publishOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    /// <summary>
    /// Claims the empty display-list form of CalcIVG.  Kickstart returns zero
    /// when a validated viewport has no generated display instructions; a
    /// non-empty list still belongs to the copper/display owner because its
    /// result depends on the merged stream and monitor timing.
    /// </summary>
    private static int AppendCalcIvgEmptyNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(8);

        // Preserve the caller result on every decline.  The native contract
        // consumes both the View and ViewPort envelopes, but it does not need
        // RasInfo, bitmap, or display geometry for the empty-list result.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullViewBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddViewBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFB); // View.ViewPort is the only View field read
        Append(code, BranchHighWord);
        var wrappedViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedViewBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));

        Append(code, MoveLongA1ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullViewPortBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddViewPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // vp_DspIns spans offsets +0x08..+0x0B
        Append(code, BranchHighWord);
        var wrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedViewPortBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullDisplayListBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddDisplayListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddDisplayListBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFCA); // CopListSize (0x36) envelope
        Append(code, BranchHighWord);
        var wrappedDisplayListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedDisplayListBranchExtensionOffset);

        // A preallocated blank CopList is still an empty display list for
        // CalcIVG.  Require its public ViewPort backlink and a positive
        // capacity before claiming the timing-neutral zero result; a
        // populated, zero-capacity, or foreign list remains provider-owned.
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
        Append(code, CompareLongD6ToD1);
        Append(code, BranchNotEqualWord);
        var displayListViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(displayListViewPortBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, TestWordD1);
        Append(code, BranchNotEqualWord);
        var populatedDisplayListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(populatedDisplayListBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var zeroCapacityDisplayListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(zeroCapacityDisplayListBranchExtensionOffset);

        var successOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, nullDisplayListBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    /// <summary>
    /// Claims the assembling single-RasInfo ScrollVPort form whose display
    /// list is either NULL or a complete, empty preallocated CopList.  There
    /// is no copper stream to rebuild in either state, so the resident
    /// operation is a successful void no-op.  Populated lists, made viewports,
    /// and multi-node chains remain with the display owner.
    /// </summary>
    private static int AppendScrollVPortEmptyNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(12);

        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD6);
        Append(code, MoveLongD6ToD5); // retain the ViewPort base
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullViewPortBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddViewPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // complete public ViewPort envelope
        Append(code, BranchHighWord);
        var wrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedViewPortBranchExtensionOffset);

        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var extendedModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(extendedModesBranchExtensionOffset);

        // A generated display list requires the copper/display rebuild path.
        // A complete blank CopList, however, still has no stream to rebuild.
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullDisplayListBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddDisplayListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddDisplayListBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFCA); // CopListSize (0x36) envelope
        Append(code, BranchHighWord);
        var wrappedDisplayListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedDisplayListBranchExtensionOffset);

        Append(code, MoveAddressD6ToA0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
        Append(code, CompareLongD5ToD1);
        Append(code, BranchNotEqualWord);
        var displayListViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(displayListViewPortBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, TestWordD1);
        Append(code, BranchNotEqualWord);
        var populatedDisplayListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(populatedDisplayListBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var zeroCapacityDisplayListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(zeroCapacityDisplayListBranchExtensionOffset);
        Append(code, MoveAddressD5ToA0);

        // Admit exactly one bounded RasInfo node.  The offsets are read to
        // mirror the resident refresh field set, but are not rewritten for
        // the empty-list no-op.
        var rasInfoValidationOffset = code.Count;
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullRasInfoBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRasInfoBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // complete RasInfo envelope
        Append(code, BranchHighWord);
        var wrappedRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedRasInfoBranchExtensionOffset);
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var linkedRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(linkedRasInfoBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoRxOffset));
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoRyOffset));

        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, nullDisplayListBranchExtensionOffset, rasInfoValidationOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendDisplayModeQuery(
        List<byte> code,
        int fallbackEntryOffset,
        bool availabilityQuery)
    {
        var offset = code.Count;
        var modeBranches = new List<(uint ModeId, int ExtensionOffset)>(48);
        var capabilityAdmissionBranches = new List<int>(3);

        // Keep the native display database query read-free.  The canonical
        // OCS/ECS ModeIDs are immediate values, so a native 68k ROM can
        // answer FindDisplayInfo and ModeNotAvailable without dereferencing
        // the host/private database sidecar.  Foreign monitor families and
        // future provider-owned records still decline through the original
        // vector, preserving the CyberGraphX/provider boundary.
        // D1 is public volatile scratch and survives every immediate compare.
        // It can therefore retain the original ModeID for both the optional
        // SuperHires classification and foreign owner handoff without
        // borrowing callee-saved D7.
        Append(code, MoveLongD0ToD1);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFF);
        Append(code, BranchEqualWord);
        var invalidIdBranchExtensionOffset = code.Count;
        Append(code, 0);

        var modeKeys = new ushort[]
        {
            GraphicsModeIds.LoresKey,
            GraphicsModeIds.HiresKey,
            GraphicsModeIds.SuperHiresKey,
            GraphicsModeIds.HamKey,
            GraphicsModeIds.LoresLaceKey,
            GraphicsModeIds.HiresLaceKey,
            GraphicsModeIds.SuperHiresLaceKey,
            GraphicsModeIds.HamLaceKey,
            GraphicsModeIds.LoresDualPlayfieldKey,
            GraphicsModeIds.HiresDualPlayfieldKey,
            GraphicsModeIds.SuperHiresDualPlayfieldKey,
            GraphicsModeIds.LoresDualPlayfieldLaceKey,
            GraphicsModeIds.HiresDualPlayfieldLaceKey,
            GraphicsModeIds.SuperHiresDualPlayfieldLaceKey,
            GraphicsModeIds.LoresDualPlayfieldTwoKey,
            GraphicsModeIds.HiresDualPlayfieldTwoKey,
            GraphicsModeIds.SuperHiresDualPlayfieldTwoKey,
            GraphicsModeIds.LoresDualPlayfieldTwoLaceKey,
            GraphicsModeIds.HiresDualPlayfieldTwoLaceKey,
            GraphicsModeIds.SuperHiresDualPlayfieldTwoLaceKey,
            GraphicsModeIds.ExtraHalfBriteKey,
            GraphicsModeIds.ExtraHalfBriteLaceKey
        };

        // ModeID zero is the valid default-monitor lores record, but its
        // private DisplayInfo handle must remain nonzero so it cannot alias
        // NULL.  The remaining canonical records use the public ModeID as
        // their compatibility handle.
        var modeIds = new List<uint>(1 + (modeKeys.Length * 3))
        {
            GraphicsModeIds.DefaultMonitor
        };
        foreach (var monitor in new[]
        {
            GraphicsModeIds.NtscMonitor,
            GraphicsModeIds.PalMonitor
        })
        {
            foreach (var key in modeKeys)
                modeIds.Add(monitor | key);
        }

        foreach (var modeId in modeIds)
        {
            Append(code, CompareImmediateLongD0);
            Append(code, (ushort)(modeId >> 16));
            Append(code, (ushort)modeId);
            Append(code, BranchEqualWord);
            var branchExtensionOffset = code.Count;
            Append(code, 0);
            modeBranches.Add((modeId, branchExtensionOffset));
        }

        // A mode that matched none of the canonical records must skip the
        // result blocks below and take the shared provider/native fallback.
        Append(code, BranchAlwaysWord);
        var unsupportedSkipResultsExtensionOffset = code.Count;
        Append(code, 0);

        var invalidResultOffset = code.Count;
        Append(code, availabilityQuery ? MoveQuickTwoD0 : MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var defaultHandleResultOffset = code.Count;
        Append(code, MoveLongImmediateD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE); // GraphicsDisplayDatabase.DefaultModeHandle
        Append(code, ReturnFromSubroutine);

        var recognizedResultOffset = code.Count;
        if (availabilityQuery)
        {
            // SuperHires records remain enumerable on OCS, but they are not
            // executable until both ECS components are published in GfxBase.
            // Preserve the read-free FindDisplayInfo path; only the
            // availability vector needs this resident capability check.
            Append(code, MoveLongD1ToD0);
            Append(code, AndImmediateWordD0);
            Append(code, GraphicsModeIds.SuperHiresMode);
            Append(code, TestWordD0);
            Append(code, BranchEqualWord);
            var ordinaryAvailabilityBranchExtensionOffset = code.Count;
            Append(code, 0);

            // Only the SuperHires availability path consumes GfxBase.  Admit
            // exactly its one-byte ChipRevBits0 field before the read: a
            // native library base is non-NULL and even, and adding the public
            // 0xEC field offset must not wrap the 32-bit address space.  D1
            // retains the original ModeID for the shared owner handoff.
            Append(code, MoveLongA6ToD0);
            Append(code, TestLongD0);
            Append(code, BranchEqualWord);
            var nullCapabilityBaseBranchExtensionOffset = code.Count;
            Append(code, 0);
            capabilityAdmissionBranches.Add(nullCapabilityBaseBranchExtensionOffset);
            Append(code, BitTestImmediateD0);
            Append(code, 0);
            Append(code, BranchNotEqualWord);
            var oddCapabilityBaseBranchExtensionOffset = code.Count;
            Append(code, 0);
            capabilityAdmissionBranches.Add(oddCapabilityBaseBranchExtensionOffset);
            var maximumCapabilityBase =
                uint.MaxValue - (uint)GraphicsLayouts.GfxBaseChipRevBits0;
            Append(code, CompareImmediateLongD0);
            Append(code, (ushort)(maximumCapabilityBase >> 16));
            Append(code, (ushort)maximumCapabilityBase);
            Append(code, BranchHighWord);
            var wrappedCapabilityBaseBranchExtensionOffset = code.Count;
            Append(code, 0);
            capabilityAdmissionBranches.Add(wrappedCapabilityBaseBranchExtensionOffset);
            Append(code, MoveByteA6DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
            Append(code, BitTestImmediateD0);
            Append(code, 0); // GraphicsChipRevision.HrAgnus
            Append(code, BranchEqualWord);
            var unavailableEcsAgnusBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BitTestImmediateD0);
            Append(code, 1); // GraphicsChipRevision.HrDenise
            Append(code, BranchEqualWord);
            var unavailableEcsDeniseBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveQuickZeroD0);
            Append(code, ReturnFromSubroutine);

            var unavailableResultOffset = code.Count;
            PatchBranch(code, unavailableEcsAgnusBranchExtensionOffset,
                unavailableResultOffset);
            PatchBranch(code, unavailableEcsDeniseBranchExtensionOffset,
                unavailableResultOffset);
            Append(code, MoveQuickOneD0); // DI_AVAIL_NOCHIPS
            Append(code, ReturnFromSubroutine);

            var ordinaryAvailabilityResultOffset = code.Count;
            PatchBranch(code, ordinaryAvailabilityBranchExtensionOffset,
                ordinaryAvailabilityResultOffset);
            Append(code, MoveQuickZeroD0);
        }
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD1ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, invalidIdBranchExtensionOffset, invalidResultOffset);
        PatchBranch(
            code,
            unsupportedSkipResultsExtensionOffset,
            fallbackRestoreOffset);
        foreach (var branchExtensionOffset in capabilityAdmissionBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        foreach (var (modeId, branchExtensionOffset) in modeBranches)
        {
            var target = modeId == GraphicsModeIds.DefaultMonitor
                ? defaultHandleResultOffset
                : recognizedResultOffset;
            PatchBranch(code, branchExtensionOffset, target);
        }

        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendBestModeIdDefault(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;

        // BestModeIDA has a deliberately small native admission surface.  A
        // NULL tag list and a complete single TAG_DONE item are the classic
        // default query; the portable database resolves that request to the
        // default-monitor Hires mode (0x00008000) on its resident PAL
        // profile.  Any non-empty list remains on the portable/provider
        // matcher, which owns the full scoring, TAG_MORE/TAG_SKIP, viewport,
        // and CyberGraphX boundaries.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullTagsBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddTagsBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A TagItem is eight bytes; FFFFFFF8 is the last valid aligned start.
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8);
        Append(code, BranchHighWord);
        var wrappedTagsBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveLongA0DisplacementToD2);
        Append(code, 0);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var nonTerminalTagBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Read the complete TagItem envelope even though TAG_DONE ignores
        // ti_Data.  This preserves the native bus-error boundary for a
        // caller whose final four bytes are not readable.
        Append(code, MoveLongA0DisplacementToD3);
        Append(code, 4);

        var successOffset = code.Count;
        Append(code, MoveLongImmediateD0);
        Append(code, 0x0000);
        Append(code, 0x8000);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, nullTagsBranchExtensionOffset, successOffset);
        PatchBranch(code, oddTagsBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, wrappedTagsBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, nonTerminalTagBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    private static int AppendBestModeIdStandardTags(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(48);

        void Decline(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void ExpectTag(uint tag, ushort valueMove, ushort displacement)
        {
            Append(code, MoveLongA1DisplacementToD0);
            Append(code, displacement);
            Append(code, CompareImmediateLongD0);
            Append(code, (ushort)(tag >> 16));
            Append(code, (ushort)tag);
            Decline();
            Append(code, valueMove);
            Append(code, checked((ushort)(displacement + 4)));
        }

        // The native arm owns the complete, fixed six-tag standard request:
        // nominal width/height, desired width/height, minimum depth, and
        // monitor ID, terminated by TAG_DONE.  Full scoring, TAG_MORE/
        // TAG_SKIP, BIDTAG_ViewPort/BIDTAG_SourceID, and provider/RTG forms
        // remain on the portable matcher.  D7 preserves the caller's D0 for
        // every decline just as the other native query bodies do.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullTagsBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Decline();
        // Seven complete TagItems (six fields plus TAG_DONE) must fit without
        // wrapping, and the final ti_Data long is read below as a boundary
        // check even though TAG_DONE ignores it.
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFC8);
        Append(code, BranchHighWord);
        var highPointerBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressA0ToA1);

        // Preserve the classic empty-list default while still reading the
        // complete final TagItem envelope.
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var emptyTagListBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 4);

        ExpectTag(GraphicsDisplayDatabase.BidTagNominalWidth,
            MoveLongA1DisplacementToD1,
            0);
        ExpectTag(GraphicsDisplayDatabase.BidTagNominalHeight,
            MoveLongA1DisplacementToD2,
            8);
        ExpectTag(GraphicsDisplayDatabase.BidTagDesiredWidth,
            MoveLongA1DisplacementToD3,
            16);
        ExpectTag(GraphicsDisplayDatabase.BidTagDesiredHeight,
            MoveLongA1DisplacementToD4,
            24);
        ExpectTag(GraphicsDisplayDatabase.BidTagDepth,
            MoveLongA1DisplacementToD5,
            32);
        ExpectTag(GraphicsDisplayDatabase.BidTagMonitorId,
            MoveLongA1DisplacementToD6,
            40);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 48);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 0);
        Decline();
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 52); // complete final TAG_DONE envelope

        // All six values are long guest fields.  The native mode table only
        // admits the documented standard dimensions and one-to-eight-plane
        // depth range; desired dimensions must also be recognized, but this
        // exact unit does not claim the portable scorer's closest-match policy.
        Append(code, TestLongD1);
        Decline(BranchEqualWord);
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 320);
        Append(code, BranchEqualWord);
        var nominalLoresBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 640);
        Append(code, BranchEqualWord);
        var nominalHiresBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 1280);
        Append(code, BranchEqualWord);
        var nominalSuperHiresBranchExtensionOffset = code.Count;
        Append(code, 0);
        Decline();

        var nominalLoresOffset = code.Count;
        PatchBranch(code, nominalLoresBranchExtensionOffset, nominalLoresOffset);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var widthAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var nominalHiresOffset = code.Count;
        PatchBranch(code, nominalHiresBranchExtensionOffset, nominalHiresOffset);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0x8000);
        Append(code, BranchAlwaysWord);
        var hiresWidthAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var nominalSuperHiresOffset = code.Count;
        PatchBranch(code, nominalSuperHiresBranchExtensionOffset, nominalSuperHiresOffset);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0x8020);
        var widthAcceptedOffset = code.Count;
        PatchBranch(code, widthAcceptedBranchExtensionOffset, widthAcceptedOffset);
        PatchBranch(code, hiresWidthAcceptedBranchExtensionOffset, widthAcceptedOffset);

        Append(code, TestLongD3);
        Decline(BranchEqualWord);
        Append(code, CompareImmediateLongD3);
        Append(code, 0);
        Append(code, 320);
        Append(code, BranchEqualWord);
        var desiredLoresBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD3);
        Append(code, 0);
        Append(code, 640);
        Append(code, BranchEqualWord);
        var desiredHiresBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD3);
        Append(code, 0);
        Append(code, 1280);
        Decline();
        var desiredWidthAcceptedOffset = code.Count;
        PatchBranch(code, desiredLoresBranchExtensionOffset, desiredWidthAcceptedOffset);
        PatchBranch(code, desiredHiresBranchExtensionOffset, desiredWidthAcceptedOffset);

        Append(code, TestLongD2);
        Decline(BranchEqualWord);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 256);
        Append(code, BranchEqualWord);
        var nominalPalProgressiveBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 200);
        Append(code, BranchEqualWord);
        var nominalNtscProgressiveBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 512);
        Append(code, BranchEqualWord);
        var nominalPalInterlaceBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 400);
        Decline();

        Append(code, TestLongD4);
        Decline(BranchEqualWord);
        Append(code, CompareImmediateLongD4);
        Append(code, 0);
        Append(code, 256);
        Append(code, BranchEqualWord);
        var desiredPalProgressiveBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0);
        Append(code, 200);
        Append(code, BranchEqualWord);
        var desiredNtscProgressiveBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0);
        Append(code, 512);
        Append(code, BranchEqualWord);
        var desiredPalInterlaceBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0);
        Append(code, 400);
        Decline();

        Append(code, TestLongD5);
        Decline(BranchEqualWord);
        Append(code, CompareImmediateLongD5);
        Append(code, 0);
        Append(code, 8);
        Decline(BranchHighWord);

        // Monitor zero denotes the resident default PAL family.  Only the
        // three documented monitor parts are native-owned here.
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var defaultMonitorAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD6);
        Append(code, 0x0002);
        Append(code, 0x1000);
        Append(code, BranchEqualWord);
        var palMonitorAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD6);
        Append(code, 0x0001);
        Append(code, 0x1000);
        Decline();
        var monitorAcceptedOffset = code.Count;
        PatchBranch(code, defaultMonitorAcceptedBranchExtensionOffset, monitorAcceptedOffset);
        PatchBranch(code, palMonitorAcceptedBranchExtensionOffset, monitorAcceptedOffset);

        var heightAcceptedOffset = code.Count;
        PatchBranch(code, nominalPalProgressiveBranchExtensionOffset, heightAcceptedOffset);
        PatchBranch(code, nominalNtscProgressiveBranchExtensionOffset, heightAcceptedOffset);
        PatchBranch(code, nominalPalInterlaceBranchExtensionOffset, heightAcceptedOffset);
        PatchBranch(code, desiredPalProgressiveBranchExtensionOffset, heightAcceptedOffset);
        PatchBranch(code, desiredNtscProgressiveBranchExtensionOffset, heightAcceptedOffset);
        PatchBranch(code, desiredPalInterlaceBranchExtensionOffset, heightAcceptedOffset);

        // Re-read nominal height after the range checks.  D2 still contains
        // the field, while D1 remains the selected mode key from the width
        // ladder below.
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 256);
        Append(code, BranchEqualWord);
        var palProgressiveHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 200);
        Append(code, BranchEqualWord);
        var ntscProgressiveHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 512);
        Append(code, BranchEqualWord);
        var palInterlaceHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        // The remaining recognized height is 400.
        Append(code, OrImmediateWordD1);
        Append(code, 4);
        var ntscInterlaceHeightOffset = code.Count;
        Append(code, CompareImmediateLongD6);
        Append(code, 0x0001);
        Append(code, 0x1000);
        Decline(BranchNotEqualWord);
        Append(code, BranchAlwaysWord);
        var modeKeyReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var palInterlaceHeightOffset = code.Count;
        PatchBranch(code, palInterlaceHeightBranchExtensionOffset, palInterlaceHeightOffset);
        Append(code, OrImmediateWordD1);
        Append(code, 4);
        Append(code, CompareImmediateLongD6);
        Append(code, 0x0001);
        Append(code, 0x1000);
        Decline(BranchEqualWord);
        Append(code, BranchAlwaysWord);
        var palInterlaceReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var ntscProgressiveHeightOffset = code.Count;
        PatchBranch(code, ntscProgressiveHeightBranchExtensionOffset, ntscProgressiveHeightOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0x0001);
        Append(code, 0x1000);
        Decline(BranchNotEqualWord);
        Append(code, BranchAlwaysWord);
        var ntscProgressiveReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var palProgressiveHeightOffset = code.Count;
        PatchBranch(code, palProgressiveHeightBranchExtensionOffset, palProgressiveHeightOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0x0001);
        Append(code, 0x1000);
        Decline(BranchEqualWord);
        Append(code, BranchAlwaysWord);
        var palProgressiveReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var modeKeyReadyOffset = code.Count;
        PatchBranch(code, modeKeyReadyBranchExtensionOffset, modeKeyReadyOffset);
        PatchBranch(code, palInterlaceReadyBranchExtensionOffset, modeKeyReadyOffset);
        PatchBranch(code, ntscProgressiveReadyBranchExtensionOffset, modeKeyReadyOffset);
        PatchBranch(code, palProgressiveReadyBranchExtensionOffset, modeKeyReadyOffset);

        // A standard 1280-pixel record is SuperHires and therefore needs the
        // complete ECS display pair.  On OCS leave the request to the prior
        // owner rather than publishing an executable mode ID.
        Append(code, MoveLongD1ToD0);
        Append(code, AndImmediateWordD0);
        Append(code, GraphicsModeIds.SuperHiresMode);
        Append(code, TestWordD0);
        Append(code, BranchEqualWord);
        var ordinaryCapabilityBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
        Append(code, BitTestImmediateD0);
        Append(code, 0); // GraphicsChipRevision.HrAgnus
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD0);
        Append(code, 1); // GraphicsChipRevision.HrDenise
        Decline(BranchEqualWord);
        PatchBranch(code, ordinaryCapabilityBranchExtensionOffset, code.Count);

        Append(code, MoveLongD6ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var defaultResultBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0002);
        Append(code, 0x1000);
        Append(code, BranchEqualWord);
        var palResultBranchExtensionOffset = code.Count;
        Append(code, 0);
        // The preceding monitor ladder leaves only NTSC here.
        Append(code, AddImmediateLongD1);
        Append(code, 0x0001);
        Append(code, 0x1000);
        Append(code, MoveLongD1ToD0);
        Append(code, ReturnFromSubroutine);

        var palResultOffset = code.Count;
        PatchBranch(code, palResultBranchExtensionOffset, palResultOffset);
        Append(code, AddImmediateLongD1);
        Append(code, 0x0002);
        Append(code, 0x1000);
        Append(code, MoveLongD1ToD0);
        Append(code, ReturnFromSubroutine);

        var emptyResultOffset = code.Count;
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, 0x8000);
        Append(code, ReturnFromSubroutine);

        var defaultResultOffset = code.Count;
        PatchBranch(code, defaultResultBranchExtensionOffset, defaultResultOffset);
        Append(code, MoveLongD1ToD0);
        Append(code, ReturnFromSubroutine);

        // The final aligned address FFFFFFF8 is a documented empty-list
        // boundary case.  No other wrapped address is admitted.
        var highPointerCheckOffset = code.Count;
        PatchBranch(code, highPointerBranchExtensionOffset, highPointerCheckOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8);
        Append(code, BranchNotEqualWord);
        var highPointerNonBoundaryBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressA0ToA1);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 0);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var highPointerNonEmptyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 4);
        Append(code, BranchAlwaysWord);
        var highPointerEmptyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, nullTagsBranchExtensionOffset, emptyResultOffset);
        PatchBranch(code, emptyTagListBranchExtensionOffset, emptyResultOffset);
        PatchBranch(code, highPointerNonBoundaryBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, highPointerNonEmptyBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, highPointerEmptyBranchExtensionOffset, emptyResultOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendBestModeIdStandardComponentTags(
        List<byte> code,
        int standardEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(64);
        var limitSuccessBranches = new List<int>(3);

        void Decline(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void ExpectTag(uint tag, ushort valueMove, ushort displacement)
        {
            Append(code, MoveLongA1DisplacementToD0);
            Append(code, displacement);
            Append(code, CompareImmediateLongD0);
            Append(code, (ushort)(tag >> 16));
            Append(code, (ushort)tag);
            Decline();
            Append(code, valueMove);
            Append(code, checked((ushort)(displacement + 4)));
        }

        // This arm owns the fixed standard geometry request when the caller
        // also supplies all three RGB component minima.  The plain six-field
        // request remains owned by AppendBestModeIdStandardTags below; this
        // exact shape therefore cannot steal scoring, arbitrary tag chains,
        // viewport/source forms, or provider/RTG requests.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullTagsBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Decline();
        // Ten complete TagItems (nine fields plus TAG_DONE) are read by the
        // native body.  FFFFFFB0 is the final aligned start that keeps the
        // terminal ti_Data long inside the 32-bit guest address envelope.
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFB0);
        Decline(BranchHighWord);
        Append(code, MoveAddressA0ToA1);

        ExpectTag(GraphicsDisplayDatabase.BidTagNominalWidth,
            MoveLongA1DisplacementToD1,
            0);
        ExpectTag(GraphicsDisplayDatabase.BidTagNominalHeight,
            MoveLongA1DisplacementToD2,
            8);
        ExpectTag(GraphicsDisplayDatabase.BidTagDesiredWidth,
            MoveLongA1DisplacementToD3,
            16);
        ExpectTag(GraphicsDisplayDatabase.BidTagDesiredHeight,
            MoveLongA1DisplacementToD4,
            24);
        ExpectTag(GraphicsDisplayDatabase.BidTagDepth,
            MoveLongA1DisplacementToD5,
            32);
        ExpectTag(GraphicsDisplayDatabase.BidTagMonitorId,
            MoveLongA1DisplacementToD6,
            40);
        ExpectTag(GraphicsDisplayDatabase.BidTagRedBits,
            MoveLongA1DisplacementToD0,
            48);
        ExpectTag(GraphicsDisplayDatabase.BidTagBlueBits,
            MoveLongA1DisplacementToD0,
            56);
        ExpectTag(GraphicsDisplayDatabase.BidTagGreenBits,
            MoveLongA1DisplacementToD0,
            64);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 72);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 0);
        Decline();
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 76); // complete terminal TagItem envelope

        // Geometry and depth are deliberately the same canonical set as the
        // fixed standard arm.  The source values are retained in D1..D6 until
        // the RGB/depth limits are checked below.
        Append(code, TestLongD1);
        Decline(BranchEqualWord);
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 320);
        Append(code, BranchEqualWord);
        var loresWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 640);
        Append(code, BranchEqualWord);
        var hiresWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 1280);
        Append(code, BranchEqualWord);
        var superHiresWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Decline();

        var loresWidthOffset = code.Count;
        PatchBranch(code, loresWidthBranchExtensionOffset, loresWidthOffset);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var widthReadyFromLoresExtensionOffset = code.Count;
        Append(code, 0);

        var hiresWidthOffset = code.Count;
        PatchBranch(code, hiresWidthBranchExtensionOffset, hiresWidthOffset);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0x8000);
        Append(code, BranchAlwaysWord);
        var widthReadyFromHiresExtensionOffset = code.Count;
        Append(code, 0);

        var superHiresWidthOffset = code.Count;
        PatchBranch(code, superHiresWidthBranchExtensionOffset, superHiresWidthOffset);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0x8020);
        var widthReadyOffset = code.Count;
        PatchBranch(code, widthReadyFromLoresExtensionOffset, widthReadyOffset);
        PatchBranch(code, widthReadyFromHiresExtensionOffset, widthReadyOffset);

        Append(code, TestLongD3);
        Decline(BranchEqualWord);
        Append(code, CompareImmediateLongD3);
        Append(code, 0);
        Append(code, 320);
        Append(code, BranchEqualWord);
        var desiredLoresBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD3);
        Append(code, 0);
        Append(code, 640);
        Append(code, BranchEqualWord);
        var desiredHiresBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD3);
        Append(code, 0);
        Append(code, 1280);
        Decline();
        var desiredWidthAcceptedOffset = code.Count;
        PatchBranch(code, desiredLoresBranchExtensionOffset, desiredWidthAcceptedOffset);
        PatchBranch(code, desiredHiresBranchExtensionOffset, desiredWidthAcceptedOffset);

        Append(code, TestLongD2);
        Decline(BranchEqualWord);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 256);
        Append(code, BranchEqualWord);
        var nominalPalProgressiveBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 200);
        Append(code, BranchEqualWord);
        var nominalNtscProgressiveBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 512);
        Append(code, BranchEqualWord);
        var nominalPalInterlaceBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 400);
        Decline();

        Append(code, TestLongD4);
        Decline(BranchEqualWord);
        Append(code, CompareImmediateLongD4);
        Append(code, 0);
        Append(code, 256);
        Append(code, BranchEqualWord);
        var desiredPalProgressiveBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0);
        Append(code, 200);
        Append(code, BranchEqualWord);
        var desiredNtscProgressiveBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0);
        Append(code, 512);
        Append(code, BranchEqualWord);
        var desiredPalInterlaceBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0);
        Append(code, 400);
        Decline();

        Append(code, TestLongD5);
        Decline(BranchEqualWord);
        Append(code, CompareImmediateLongD5);
        Append(code, 0);
        Append(code, 8);
        Decline(BranchHighWord);

        // Monitor zero denotes the resident default PAL family.  Explicit
        // PAL and NTSC are the only other native monitor parts.
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var defaultMonitorAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD6);
        Append(code, 0x0002);
        Append(code, 0x1000);
        Append(code, BranchEqualWord);
        var palMonitorAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD6);
        Append(code, 0x0001);
        Append(code, 0x1000);
        Decline();
        var monitorAcceptedOffset = code.Count;
        PatchBranch(code, defaultMonitorAcceptedBranchExtensionOffset, monitorAcceptedOffset);
        PatchBranch(code, palMonitorAcceptedBranchExtensionOffset, monitorAcceptedOffset);

        var heightAcceptedOffset = code.Count;
        PatchBranch(code, nominalPalProgressiveBranchExtensionOffset, heightAcceptedOffset);
        PatchBranch(code, nominalNtscProgressiveBranchExtensionOffset, heightAcceptedOffset);
        PatchBranch(code, nominalPalInterlaceBranchExtensionOffset, heightAcceptedOffset);
        PatchBranch(code, desiredPalProgressiveBranchExtensionOffset, heightAcceptedOffset);
        PatchBranch(code, desiredNtscProgressiveBranchExtensionOffset, heightAcceptedOffset);
        PatchBranch(code, desiredPalInterlaceBranchExtensionOffset, heightAcceptedOffset);

        // Re-read the nominal height to select progressive/interlace and then
        // apply the monitor-family compatibility rule of the standard arm.
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 256);
        Append(code, BranchEqualWord);
        var palProgressiveHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 200);
        Append(code, BranchEqualWord);
        var ntscProgressiveHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 512);
        Append(code, BranchEqualWord);
        var palInterlaceHeightBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, OrImmediateWordD1);
        Append(code, 4);
        var ntscInterlaceHeightOffset = code.Count;
        Append(code, CompareImmediateLongD6);
        Append(code, 0x0001);
        Append(code, 0x1000);
        Decline(BranchNotEqualWord);
        Append(code, BranchAlwaysWord);
        var modeKeyReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var palInterlaceHeightOffset = code.Count;
        PatchBranch(code, palInterlaceHeightBranchExtensionOffset, palInterlaceHeightOffset);
        Append(code, OrImmediateWordD1);
        Append(code, 4);
        Append(code, CompareImmediateLongD6);
        Append(code, 0x0001);
        Append(code, 0x1000);
        Decline(BranchEqualWord);
        Append(code, BranchAlwaysWord);
        var palInterlaceReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var ntscProgressiveHeightOffset = code.Count;
        PatchBranch(code, ntscProgressiveHeightBranchExtensionOffset, ntscProgressiveHeightOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0x0001);
        Append(code, 0x1000);
        Decline(BranchNotEqualWord);
        Append(code, BranchAlwaysWord);
        var ntscProgressiveReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var palProgressiveHeightOffset = code.Count;
        PatchBranch(code, palProgressiveHeightBranchExtensionOffset, palProgressiveHeightOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0x0001);
        Append(code, 0x1000);
        Decline(BranchEqualWord);
        Append(code, BranchAlwaysWord);
        var palProgressiveReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var modeKeyReadyOffset = code.Count;
        PatchBranch(code, modeKeyReadyBranchExtensionOffset, modeKeyReadyOffset);
        PatchBranch(code, palInterlaceReadyBranchExtensionOffset, modeKeyReadyOffset);
        PatchBranch(code, ntscProgressiveReadyBranchExtensionOffset, modeKeyReadyOffset);
        PatchBranch(code, palProgressiveReadyBranchExtensionOffset, modeKeyReadyOffset);

        // SuperHires is the only standard width whose native record has a
        // reduced depth/component ceiling.  The interlace bit already resides
        // in D1, so the two exact keys select the corresponding RGB allowance.
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 0x8020);
        Append(code, BranchEqualWord);
        var progressiveSuperLimitBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 0x8024);
        Append(code, BranchEqualWord);
        var interlaceSuperLimitBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var ordinaryLimitBranchExtensionOffset = code.Count;
        Append(code, 0);

        void AppendLimits(
            uint depthMaximum,
            uint componentMaximum,
            bool requiresEcs = false)
        {
            var limitOffset = code.Count;
            if (requiresEcs)
            {
                Append(code, MoveByteA6DisplacementToD0);
                Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
                Append(code, BitTestImmediateD0);
                Append(code, 0); // GraphicsChipRevision.HrAgnus
                Decline(BranchEqualWord);
                Append(code, BitTestImmediateD0);
                Append(code, 1); // GraphicsChipRevision.HrDenise
                Decline(BranchEqualWord);
            }
            Append(code, CompareImmediateLongD5);
            Append(code, (ushort)(depthMaximum >> 16));
            Append(code, (ushort)depthMaximum);
            Decline(BranchHighWord);
            foreach (var displacement in new ushort[] { 52, 60, 68 })
            {
                Append(code, MoveLongA1DisplacementToD0);
                Append(code, displacement);
                Append(code, CompareImmediateLongD0);
                Append(code, (ushort)(componentMaximum >> 16));
                Append(code, (ushort)componentMaximum);
                Decline(BranchHighWord);
            }

            Append(code, BranchAlwaysWord);
            var successExtensionOffset = code.Count;
            Append(code, 0);
            limitSuccessBranches.Add(successExtensionOffset);
            return;
        }

        PatchBranch(code, progressiveSuperLimitBranchExtensionOffset, code.Count);
        AppendLimits(2, 2, requiresEcs: true);
        PatchBranch(code, interlaceSuperLimitBranchExtensionOffset, code.Count);
        AppendLimits(2, 4, requiresEcs: true);
        PatchBranch(code, ordinaryLimitBranchExtensionOffset, code.Count);
        // Lisa's eight-plane/RGB8 palette path requires both AA components.
        // Keep an incomplete public capability declaration in the legacy
        // six-plane/RGB4 envelope, consistent with GetDisplayInfoData.
        Append(code, MoveByteA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
        Append(code, BitTestImmediateD0);
        Append(code, 2); // GraphicsChipRevision.AaAlice
        Append(code, BranchEqualWord);
        var ordinaryLegacyAliceBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 3); // GraphicsChipRevision.AaLisa
        Append(code, BranchEqualWord);
        var ordinaryLegacyLisaBranchExtensionOffset = code.Count;
        Append(code, 0);
        AppendLimits(8, 8);
        var ordinaryLegacyLimitOffset = code.Count;
        PatchBranch(code, ordinaryLegacyAliceBranchExtensionOffset,
            ordinaryLegacyLimitOffset);
        PatchBranch(code, ordinaryLegacyLisaBranchExtensionOffset,
            ordinaryLegacyLimitOffset);
        AppendLimits(6, 4);

        var resultOffset = code.Count;
        foreach (var successExtensionOffset in limitSuccessBranches)
            PatchBranch(code, successExtensionOffset, resultOffset);

        Append(code, MoveLongD6ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var defaultResultBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0002);
        Append(code, 0x1000);
        Append(code, BranchEqualWord);
        var palResultBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, AddImmediateLongD1);
        Append(code, 0x0001);
        Append(code, 0x1000);
        Append(code, MoveLongD1ToD0);
        Append(code, ReturnFromSubroutine);

        var palResultOffset = code.Count;
        PatchBranch(code, palResultBranchExtensionOffset, palResultOffset);
        Append(code, AddImmediateLongD1);
        Append(code, 0x0002);
        Append(code, 0x1000);
        Append(code, MoveLongD1ToD0);
        Append(code, ReturnFromSubroutine);

        var defaultResultOffset = code.Count;
        PatchBranch(code, defaultResultBranchExtensionOffset, defaultResultOffset);
        Append(code, MoveLongD1ToD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, nullTagsBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, standardEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        return offset;
    }

    private static int AppendBestModeIdViewportTags(
        List<byte> code,
        int standardEntryOffset)
    {
        var offset = code.Count;
        var standardBranches = new List<int>(20);

        void DeclineToStandard(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            standardBranches.Add(extensionOffset);
        }

        void ExpectTag(uint tag, ushort valueMove, ushort displacement)
        {
            Append(code, MoveLongA1DisplacementToD0);
            Append(code, displacement);
            Append(code, CompareImmediateLongD0);
            Append(code, (ushort)(tag >> 16));
            Append(code, (ushort)tag);
            DeclineToStandard();
            Append(code, valueMove);
            Append(code, checked((ushort)(displacement + 4)));
        }

        // This arm claims a fixed viewport-source spelling: ViewPort pointer,
        // explicit depth, explicit monitor, and TAG_DONE.  It validates the
        // guest ViewPort envelope and canonical standard mode key, then lets
        // the portable matcher retain full viewport/source/provider policy.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        DeclineToStandard(BranchEqualWord);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        DeclineToStandard();
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFE0); // four complete TagItems
        DeclineToStandard(BranchHighWord);
        Append(code, MoveAddressA0ToA1);

        ExpectTag(GraphicsDisplayDatabase.BidTagViewPort,
            MoveLongA1DisplacementToD1, 0);
        ExpectTag(GraphicsDisplayDatabase.BidTagDepth,
            MoveLongA1DisplacementToD6, 8);
        ExpectTag(GraphicsDisplayDatabase.BidTagMonitorId,
            MoveLongA1DisplacementToD5, 16);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 24);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 0);
        DeclineToStandard();
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 28); // complete TAG_DONE envelope

        // Validate the referenced ViewPort and reject extended modes.  A2 is
        // retained so A0 still denotes the caller's tag list on a decline.
        Append(code, TestLongD1);
        DeclineToStandard(BranchEqualWord);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        DeclineToStandard();
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // complete ViewPort envelope
        DeclineToStandard(BranchHighWord);
        Append(code, MoveAddressD1ToA2);
        Append(code, MoveByteA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestByteD4);
        DeclineToStandard(BranchNotEqualWord);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));

        Append(code, TestLongD6);
        DeclineToStandard(BranchEqualWord);
        Append(code, CompareImmediateLongD6);
        Append(code, 0);
        Append(code, 8);
        DeclineToStandard(BranchHighWord);

        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var defaultMonitorAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD5);
        Append(code, 0x0002);
        Append(code, 0x1000);
        Append(code, BranchEqualWord);
        var palMonitorAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD5);
        Append(code, 0x0001);
        Append(code, 0x1000);
        DeclineToStandard();
        var monitorAcceptedOffset = code.Count;
        PatchBranch(code, defaultMonitorAcceptedBranchExtensionOffset, monitorAcceptedOffset);
        PatchBranch(code, palMonitorAcceptedBranchExtensionOffset, monitorAcceptedOffset);

        Append(code, MoveWordA2DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDWidth));
        Append(code, CompareImmediateWordD2);
        Append(code, 320);
        Append(code, BranchEqualWord);
        var loresWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 640);
        Append(code, BranchEqualWord);
        var hiresWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 1280);
        Append(code, BranchEqualWord);
        var superHiresWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        DeclineToStandard();

        var loresWidthOffset = code.Count;
        PatchBranch(code, loresWidthBranchExtensionOffset, loresWidthOffset);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var widthAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        var hiresWidthOffset = code.Count;
        PatchBranch(code, hiresWidthBranchExtensionOffset, hiresWidthOffset);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0x8000);
        Append(code, BranchAlwaysWord);
        var hiresWidthAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        var superHiresWidthOffset = code.Count;
        PatchBranch(code, superHiresWidthBranchExtensionOffset, superHiresWidthOffset);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0x8020);
        var widthAcceptedOffset = code.Count;
        PatchBranch(code, widthAcceptedBranchExtensionOffset, widthAcceptedOffset);
        PatchBranch(code, hiresWidthAcceptedBranchExtensionOffset, widthAcceptedOffset);

        Append(code, MoveWordA2DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDHeight));
        Append(code, CompareImmediateWordD3);
        Append(code, 256);
        Append(code, BranchEqualWord);
        var palProgressiveBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD3);
        Append(code, 200);
        Append(code, BranchEqualWord);
        var ntscProgressiveBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD3);
        Append(code, 512);
        Append(code, BranchEqualWord);
        var palInterlaceBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD3);
        Append(code, 400);
        Append(code, BranchEqualWord);
        var ntscInterlaceBranchExtensionOffset = code.Count;
        Append(code, 0);
        DeclineToStandard();

        var heightAcceptedOffset = code.Count;
        PatchBranch(code, palProgressiveBranchExtensionOffset, heightAcceptedOffset);
        PatchBranch(code, ntscProgressiveBranchExtensionOffset, heightAcceptedOffset);
        PatchBranch(code, palInterlaceBranchExtensionOffset, heightAcceptedOffset);
        PatchBranch(code, ntscInterlaceBranchExtensionOffset, heightAcceptedOffset);

        Append(code, CompareImmediateWordD3);
        Append(code, 256);
        Append(code, BranchEqualWord);
        var palProgressiveModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD3);
        Append(code, 200);
        Append(code, BranchEqualWord);
        var ntscProgressiveModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD3);
        Append(code, 512);
        Append(code, BranchEqualWord);
        var palInterlaceModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        // The remaining recognized height is 400.
        Append(code, OrImmediateWordD1);
        Append(code, 4);
        Append(code, CompareImmediateLongD5);
        Append(code, 0x0001);
        Append(code, 0x1000);
        DeclineToStandard(BranchNotEqualWord);
        Append(code, BranchAlwaysWord);
        var modeReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var palInterlaceModeOffset = code.Count;
        PatchBranch(code, palInterlaceModeBranchExtensionOffset, palInterlaceModeOffset);
        Append(code, OrImmediateWordD1);
        Append(code, 4);
        Append(code, CompareImmediateLongD5);
        Append(code, 0x0001);
        Append(code, 0x1000);
        DeclineToStandard(BranchEqualWord);
        Append(code, BranchAlwaysWord);
        var palInterlaceReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var ntscProgressiveModeOffset = code.Count;
        PatchBranch(code, ntscProgressiveModeBranchExtensionOffset, ntscProgressiveModeOffset);
        Append(code, CompareImmediateLongD5);
        Append(code, 0x0001);
        Append(code, 0x1000);
        DeclineToStandard(BranchNotEqualWord);
        Append(code, BranchAlwaysWord);
        var ntscProgressiveReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var palProgressiveModeOffset = code.Count;
        PatchBranch(code, palProgressiveModeBranchExtensionOffset, palProgressiveModeOffset);
        Append(code, CompareImmediateLongD5);
        Append(code, 0x0001);
        Append(code, 0x1000);
        DeclineToStandard(BranchEqualWord);
        Append(code, BranchAlwaysWord);
        var palProgressiveReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var modeReadyOffset = code.Count;
        PatchBranch(code, modeReadyBranchExtensionOffset, modeReadyOffset);
        PatchBranch(code, palInterlaceReadyBranchExtensionOffset, modeReadyOffset);
        PatchBranch(code, ntscProgressiveReadyBranchExtensionOffset, modeReadyOffset);
        PatchBranch(code, palProgressiveReadyBranchExtensionOffset, modeReadyOffset);

        Append(code, MoveWordD4ToD3);
        Append(code, CompareWordD1ToD3);
        DeclineToStandard();

        // The matched 1280-pixel ViewPort key is executable only when both
        // ECS display components are present at the resident GfxBase.
        Append(code, MoveLongD1ToD0);
        Append(code, AndImmediateWordD0);
        Append(code, GraphicsModeIds.SuperHiresMode);
        Append(code, TestWordD0);
        Append(code, BranchEqualWord);
        var ordinaryCapabilityBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
        Append(code, BitTestImmediateD0);
        Append(code, 0); // GraphicsChipRevision.HrAgnus
        DeclineToStandard(BranchEqualWord);
        Append(code, BitTestImmediateD0);
        Append(code, 1); // GraphicsChipRevision.HrDenise
        DeclineToStandard(BranchEqualWord);
        PatchBranch(code, ordinaryCapabilityBranchExtensionOffset, code.Count);

        Append(code, MoveLongD5ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var defaultResultBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0002);
        Append(code, 0x1000);
        Append(code, BranchEqualWord);
        var palResultBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, AddImmediateLongD1);
        Append(code, 0x0001);
        Append(code, 0x1000);
        Append(code, MoveLongD1ToD0);
        Append(code, ReturnFromSubroutine);

        var palResultOffset = code.Count;
        PatchBranch(code, palResultBranchExtensionOffset, palResultOffset);
        Append(code, AddImmediateLongD1);
        Append(code, 0x0002);
        Append(code, 0x1000);
        Append(code, MoveLongD1ToD0);
        Append(code, ReturnFromSubroutine);

        var defaultResultOffset = code.Count;
        PatchBranch(code, defaultResultBranchExtensionOffset, defaultResultOffset);
        Append(code, MoveLongD1ToD0);
        Append(code, ReturnFromSubroutine);

        var standardJumpOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var standardJumpBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, standardJumpBranchExtensionOffset, standardEntryOffset);
        foreach (var branchExtensionOffset in standardBranches)
            PatchBranch(code, branchExtensionOffset, standardJumpOffset);

        return offset;
    }

    private static int AppendBestModeIdSourceTags(
        List<byte> code,
        int viewportEntryOffset)
    {
        var offset = code.Count;
        var viewportBranches = new List<int>(24);

        void DeclineToViewport(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            viewportBranches.Add(extensionOffset);
        }

        void ExpectTag(uint tag, ushort valueMove, ushort displacement)
        {
            Append(code, MoveLongA1DisplacementToD0);
            Append(code, displacement);
            Append(code, CompareImmediateLongD0);
            Append(code, (ushort)(tag >> 16));
            Append(code, (ushort)tag);
            DeclineToViewport();
            Append(code, valueMove);
            Append(code, checked((ushort)(displacement + 4)));
        }

        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        DeclineToViewport(BranchEqualWord);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        DeclineToViewport();
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFE0); // four complete TagItems
        DeclineToViewport(BranchHighWord);
        Append(code, MoveAddressA0ToA1);

        ExpectTag(GraphicsDisplayDatabase.BidTagSourceId,
            MoveLongA1DisplacementToD1, 0);
        ExpectTag(GraphicsDisplayDatabase.BidTagDepth,
            MoveLongA1DisplacementToD5, 8);
        ExpectTag(GraphicsDisplayDatabase.BidTagMonitorId,
            MoveLongA1DisplacementToD2, 16);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 24);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 0);
        DeclineToViewport();
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 28); // complete TAG_DONE envelope

        Append(code, TestLongD5);
        DeclineToViewport(BranchEqualWord);
        Append(code, CompareImmediateLongD5);
        Append(code, 0);
        Append(code, 8);
        DeclineToViewport(BranchHighWord);

        // Validate the explicit monitor family before comparing it to the
        // source ModeID's monitor part.
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var defaultMonitorBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD2);
        Append(code, 0x0002);
        Append(code, 0x1000);
        Append(code, BranchEqualWord);
        var palMonitorBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD2);
        Append(code, 0x0001);
        Append(code, 0x1000);
        DeclineToViewport();
        var monitorAcceptedOffset = code.Count;
        PatchBranch(code, defaultMonitorBranchExtensionOffset, monitorAcceptedOffset);
        PatchBranch(code, palMonitorBranchExtensionOffset, monitorAcceptedOffset);

        Append(code, MoveLongD1ToD3);
        Append(code, AndImmediateLongD3);
        Append(code, 0xFFFF);
        Append(code, 0x1000); // monitor part mask, excluding mode-key bits
        Append(code, MoveLongD3ToD6);
        Append(code, CompareLongD6ToD2);
        DeclineToViewport();

        // The monitor family occupies bits 12..31, including the low-word
        // 0x1000 marker. Keep D1 intact for the successful return, but
        // compare a monitor-stripped copy when admitting the native key.
        Append(code, MoveLongD1ToD4);
        Append(code, AndImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0xEFFF);

        var sourceKeys = new ushort[]
        {
            GraphicsModeIds.LoresKey,
            GraphicsModeIds.HiresKey,
            GraphicsModeIds.SuperHiresKey,
            GraphicsModeIds.LoresLaceKey,
            GraphicsModeIds.HiresLaceKey,
            GraphicsModeIds.SuperHiresLaceKey,
            GraphicsModeIds.HamKey,
            GraphicsModeIds.HamLaceKey,
            GraphicsModeIds.ExtraHalfBriteKey,
            GraphicsModeIds.ExtraHalfBriteLaceKey,
            GraphicsModeIds.LoresDualPlayfieldKey,
            GraphicsModeIds.HiresDualPlayfieldKey,
            GraphicsModeIds.SuperHiresDualPlayfieldKey,
            GraphicsModeIds.LoresDualPlayfieldLaceKey,
            GraphicsModeIds.HiresDualPlayfieldLaceKey,
            GraphicsModeIds.SuperHiresDualPlayfieldLaceKey,
            GraphicsModeIds.LoresDualPlayfieldTwoKey,
            GraphicsModeIds.HiresDualPlayfieldTwoKey,
            GraphicsModeIds.SuperHiresDualPlayfieldTwoKey,
            GraphicsModeIds.LoresDualPlayfieldTwoLaceKey,
            GraphicsModeIds.HiresDualPlayfieldTwoLaceKey,
            GraphicsModeIds.SuperHiresDualPlayfieldTwoLaceKey
        };

        var sourceAcceptedBranches = new List<int>(sourceKeys.Length);
        foreach (var key in sourceKeys)
        {
            Append(code, CompareImmediateWordD4);
            Append(code, key);
            Append(code, BranchEqualWord);
            sourceAcceptedBranches.Add(code.Count);
            Append(code, 0);
        }
        DeclineToViewport();
        var sourceAcceptedOffset = code.Count;
        foreach (var branchExtensionOffset in sourceAcceptedBranches)
            PatchBranch(code, branchExtensionOffset, sourceAcceptedOffset);

        // Keep SuperHires records discoverable, but do not claim them as a
        // runnable source on OCS.  The chained owner receives the original
        // D0, matching the other native capability declines.
        Append(code, MoveLongD4ToD0);
        Append(code, AndImmediateWordD0);
        Append(code, GraphicsModeIds.SuperHiresMode);
        Append(code, TestWordD0);
        Append(code, BranchEqualWord);
        var ordinaryCapabilityBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
        Append(code, BitTestImmediateD0);
        Append(code, 0); // GraphicsChipRevision.HrAgnus
        DeclineToViewport(BranchEqualWord);
        Append(code, BitTestImmediateD0);
        Append(code, 1); // GraphicsChipRevision.HrDenise
        DeclineToViewport(BranchEqualWord);
        PatchBranch(code, ordinaryCapabilityBranchExtensionOffset, code.Count);

        // The source ID already contains the validated monitor part and key;
        // return it unchanged so feature records retain their exact identity.
        Append(code, MoveLongD1ToD0);
        Append(code, ReturnFromSubroutine);

        var viewportJumpOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var viewportJumpBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, viewportJumpBranchExtensionOffset, viewportEntryOffset);
        foreach (var branchExtensionOffset in viewportBranches)
            PatchBranch(code, branchExtensionOffset, viewportJumpOffset);

        return offset;
    }

    private static int AppendBestModeIdSourceFeatureTags(
        List<byte> code,
        int sourceEntryOffset)
    {
        var offset = code.Count;
        var sourceBranches = new List<int>(20);

        void Decline(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            sourceBranches.Add(extensionOffset);
        }

        void ExpectTag(uint tag, ushort valueMove, ushort displacement)
        {
            Append(code, MoveLongA1DisplacementToD0);
            Append(code, displacement);
            Append(code, CompareImmediateLongD0);
            Append(code, (ushort)(tag >> 16));
            Append(code, (ushort)tag);
            Decline();
            Append(code, valueMove);
            Append(code, checked((ushort)(displacement + 4)));
        }

        // This arm owns one exact source/property spelling.  The source ID
        // remains authoritative for geometry and monitor selection; the two
        // DIPF masks are applied to the source record's native properties.
        // Full scoring, arbitrary tag order/chains, viewport precedence,
        // component constraints, providers, and CyberGraphX remain on the
        // existing source/viewport/standard owners.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Decline();
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFE0); // four complete TagItems
        Decline(BranchHighWord);
        Append(code, MoveAddressA0ToA1);

        ExpectTag(GraphicsDisplayDatabase.BidTagSourceId,
            MoveLongA1DisplacementToD1, 0);
        ExpectTag(GraphicsDisplayDatabase.BidTagDipfMustHave,
            MoveLongA1DisplacementToD5, 8);
        ExpectTag(GraphicsDisplayDatabase.BidTagDipfMustNotHave,
            MoveLongA1DisplacementToD6, 16);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 24);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 0);
        Decline();
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 28); // complete terminal envelope

        // Validate the source monitor family before deriving properties.
        Append(code, MoveLongD1ToD3);
        Append(code, AndImmediateLongD3);
        Append(code, 0xFFFF);
        Append(code, 0x1000);
        Append(code, TestLongD3);
        Append(code, BranchEqualWord);
        var defaultMonitorBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD3);
        Append(code, 0x0002);
        Append(code, 0x1000);
        Append(code, BranchEqualWord);
        var palMonitorBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD3);
        Append(code, 0x0001);
        Append(code, 0x1000);
        Decline();
        var monitorAcceptedOffset = code.Count;
        PatchBranch(code, defaultMonitorBranchExtensionOffset, monitorAcceptedOffset);
        PatchBranch(code, palMonitorBranchExtensionOffset, monitorAcceptedOffset);

        Append(code, MoveLongD1ToD4);
        Append(code, AndImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0xEFFF); // strip monitor bits, retain the native key

        static uint PropertiesForKey(ushort key)
        {
            var properties = GraphicsDisplayDatabase.DipfIsSprites |
                             GraphicsDisplayDatabase.DipfIsSpritesAttached |
                             GraphicsDisplayDatabase.DipfIsWb |
                             GraphicsDisplayDatabase.DipfIsDbuffer;
            if ((key & GraphicsModeIds.SuperHiresMode) != 0)
            {
                properties &= ~GraphicsDisplayDatabase.DipfIsSpritesAttached;
                properties |= GraphicsDisplayDatabase.DipfIsEcs;
            }
            if ((key & GraphicsModeIds.InterlaceMode) != 0)
                properties |= GraphicsDisplayDatabase.DipfIsLace;
            if ((key & GraphicsModeIds.DualPlayfieldMode) != 0)
                properties |= GraphicsDisplayDatabase.DipfIsDualPf;
            if ((key & GraphicsModeIds.PlayfieldBitAssignment) != 0)
                properties |= GraphicsDisplayDatabase.DipfIsPf2Pri;
            if ((key & GraphicsModeIds.HamMode) != 0)
                properties |= GraphicsDisplayDatabase.DipfIsHam;
            if ((key & GraphicsModeIds.ExtraHalfBriteMode) != 0)
                properties |= GraphicsDisplayDatabase.DipfIsExtraHalfBrite;
            return properties;
        }

        var sourceProperties = new (ushort Key, uint Properties)[]
        {
            (GraphicsModeIds.LoresKey, PropertiesForKey(GraphicsModeIds.LoresKey)),
            (GraphicsModeIds.HiresKey, PropertiesForKey(GraphicsModeIds.HiresKey)),
            (GraphicsModeIds.SuperHiresKey, PropertiesForKey(GraphicsModeIds.SuperHiresKey)),
            (GraphicsModeIds.LoresLaceKey, PropertiesForKey(GraphicsModeIds.LoresLaceKey)),
            (GraphicsModeIds.HiresLaceKey, PropertiesForKey(GraphicsModeIds.HiresLaceKey)),
            (GraphicsModeIds.SuperHiresLaceKey, PropertiesForKey(GraphicsModeIds.SuperHiresLaceKey)),
            (GraphicsModeIds.HamKey, PropertiesForKey(GraphicsModeIds.HamKey)),
            (GraphicsModeIds.HamLaceKey, PropertiesForKey(GraphicsModeIds.HamLaceKey)),
            (GraphicsModeIds.ExtraHalfBriteKey, PropertiesForKey(GraphicsModeIds.ExtraHalfBriteKey)),
            (GraphicsModeIds.ExtraHalfBriteLaceKey, PropertiesForKey(GraphicsModeIds.ExtraHalfBriteLaceKey)),
            (GraphicsModeIds.LoresDualPlayfieldKey, PropertiesForKey(GraphicsModeIds.LoresDualPlayfieldKey)),
            (GraphicsModeIds.HiresDualPlayfieldKey, PropertiesForKey(GraphicsModeIds.HiresDualPlayfieldKey)),
            (GraphicsModeIds.SuperHiresDualPlayfieldKey, PropertiesForKey(GraphicsModeIds.SuperHiresDualPlayfieldKey)),
            (GraphicsModeIds.LoresDualPlayfieldLaceKey, PropertiesForKey(GraphicsModeIds.LoresDualPlayfieldLaceKey)),
            (GraphicsModeIds.HiresDualPlayfieldLaceKey, PropertiesForKey(GraphicsModeIds.HiresDualPlayfieldLaceKey)),
            (GraphicsModeIds.SuperHiresDualPlayfieldLaceKey, PropertiesForKey(GraphicsModeIds.SuperHiresDualPlayfieldLaceKey)),
            (GraphicsModeIds.LoresDualPlayfieldTwoKey, PropertiesForKey(GraphicsModeIds.LoresDualPlayfieldTwoKey)),
            (GraphicsModeIds.HiresDualPlayfieldTwoKey, PropertiesForKey(GraphicsModeIds.HiresDualPlayfieldTwoKey)),
            (GraphicsModeIds.SuperHiresDualPlayfieldTwoKey, PropertiesForKey(GraphicsModeIds.SuperHiresDualPlayfieldTwoKey)),
            (GraphicsModeIds.LoresDualPlayfieldTwoLaceKey, PropertiesForKey(GraphicsModeIds.LoresDualPlayfieldTwoLaceKey)),
            (GraphicsModeIds.HiresDualPlayfieldTwoLaceKey, PropertiesForKey(GraphicsModeIds.HiresDualPlayfieldTwoLaceKey)),
            (GraphicsModeIds.SuperHiresDualPlayfieldTwoLaceKey, PropertiesForKey(GraphicsModeIds.SuperHiresDualPlayfieldTwoLaceKey))
        };

        var propertyBranches = new List<(int ExtensionOffset, uint Properties)>(sourceProperties.Length);
        foreach (var (key, properties) in sourceProperties)
        {
            Append(code, CompareImmediateWordD4);
            Append(code, key);
            Append(code, BranchEqualWord);
            propertyBranches.Add((code.Count, properties));
            Append(code, 0);
        }
        Decline();

        var propertyJoinBranches = new List<int>(propertyBranches.Count);
        foreach (var (extensionOffset, properties) in propertyBranches)
        {
            PatchBranch(code, extensionOffset, code.Count);
            Append(code, MoveLongImmediateD2);
            Append(code, (ushort)(properties >> 16));
            Append(code, (ushort)properties);
            Append(code, BranchAlwaysWord);
            propertyJoinBranches.Add(code.Count);
            Append(code, 0);
        }
        var propertyReadyOffset = code.Count;
        foreach (var branchExtensionOffset in propertyJoinBranches)
            PatchBranch(code, branchExtensionOffset, propertyReadyOffset);

        // Source-property requests may describe an ECS SuperHires record.
        // Admit that record only after both ECS display bits are published.
        Append(code, MoveLongD4ToD0);
        Append(code, AndImmediateWordD0);
        Append(code, GraphicsModeIds.SuperHiresMode);
        Append(code, TestWordD0);
        Append(code, BranchEqualWord);
        var ordinaryCapabilityBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
        Append(code, BitTestImmediateD0);
        Append(code, 0); // GraphicsChipRevision.HrAgnus
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD0);
        Append(code, 1); // GraphicsChipRevision.HrDenise
        Decline(BranchEqualWord);
        PatchBranch(code, ordinaryCapabilityBranchExtensionOffset, code.Count);

        // Native default-monitor records use the resident PAL profile, so
        // the zero monitor part receives the same DIPF_IS_PAL bit as PAL.
        Append(code, TestLongD3);
        Append(code, BranchEqualWord);
        var defaultPalBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD3);
        Append(code, 0x0002);
        Append(code, 0x1000);
        Append(code, BranchEqualWord);
        var palPropertyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var noPalPropertyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var palPropertyOffset = code.Count;
        PatchBranch(code, defaultPalBranchExtensionOffset, palPropertyOffset);
        PatchBranch(code, palPropertyBranchExtensionOffset, palPropertyOffset);
        Append(code, OrImmediateLongD2);
        Append(code, 0);
        Append(code, 0x0020);
        var noPalPropertyOffset = code.Count;
        PatchBranch(code, noPalPropertyBranchExtensionOffset, noPalPropertyOffset);

        // Require all requested properties and reject every forbidden one.
        // The intersection checks leave D2 (the derived record properties)
        // intact for the successful return.
        Append(code, MoveLongD2ToD4);
        Append(code, AndLongD5ToD4);
        Append(code, CompareLongD5ToD4);
        Decline();
        Append(code, MoveLongD2ToD4);
        Append(code, AndLongD6ToD4);
        Append(code, TestLongD4);
        Decline();

        Append(code, MoveLongD1ToD0);
        Append(code, ReturnFromSubroutine);

        var sourceJumpOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var sourceJumpBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, sourceJumpBranchExtensionOffset, sourceEntryOffset);
        foreach (var branchExtensionOffset in sourceBranches)
            PatchBranch(code, branchExtensionOffset, sourceJumpOffset);

        return offset;
    }

    private static int AppendBestModeIdSourceComponentTags(
        List<byte> code,
        int sourceFeatureEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(24);

        void Decline(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void ExpectTag(uint tag, ushort valueMove, ushort displacement)
        {
            Append(code, MoveLongA1DisplacementToD0);
            Append(code, displacement);
            Append(code, CompareImmediateLongD0);
            Append(code, (ushort)(tag >> 16));
            Append(code, (ushort)tag);
            Decline();
            Append(code, valueMove);
            Append(code, checked((ushort)(displacement + 4)));
        }

        // This exact seven-tag arm covers SourceID requests that also state
        // depth and RGB component precision.  It is intentionally separate
        // from source/property matching so a caller can use either contract
        // without widening arbitrary tag-order or closest-match ownership.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Decline();
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFC8); // seven complete TagItems
        Decline(BranchHighWord);
        Append(code, MoveAddressA0ToA1);

        ExpectTag(GraphicsDisplayDatabase.BidTagSourceId,
            MoveLongA1DisplacementToD1, 0);
        ExpectTag(GraphicsDisplayDatabase.BidTagDepth,
            MoveLongA1DisplacementToD2, 8);
        ExpectTag(GraphicsDisplayDatabase.BidTagMonitorId,
            MoveLongA1DisplacementToD3, 16);
        ExpectTag(GraphicsDisplayDatabase.BidTagRedBits,
            MoveLongA1DisplacementToD4, 24);
        ExpectTag(GraphicsDisplayDatabase.BidTagBlueBits,
            MoveLongA1DisplacementToD5, 32);
        ExpectTag(GraphicsDisplayDatabase.BidTagGreenBits,
            MoveLongA1DisplacementToD6, 40);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 48);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 0);
        Decline();
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 52); // complete terminal envelope

        // The explicit monitor must be a supported family and must agree
        // with the monitor part of the full SourceID.  The $1000 low-word
        // marker is the monitor bit; mode-key bits such as HIRES are not.
        Append(code, MoveLongD1ToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0x1000);
        Append(code, CompareLongD0ToD3);
        Decline();
        Append(code, TestLongD3);
        Append(code, BranchEqualWord);
        var defaultMonitorBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD3);
        Append(code, 0x0002);
        Append(code, 0x1000);
        Append(code, BranchEqualWord);
        var palMonitorBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD3);
        Append(code, 0x0001);
        Append(code, 0x1000);
        Decline();
        var monitorAcceptedOffset = code.Count;
        PatchBranch(code, defaultMonitorBranchExtensionOffset, monitorAcceptedOffset);
        PatchBranch(code, palMonitorBranchExtensionOffset, monitorAcceptedOffset);

        // Retain only the native key bits for the family/depth/precision
        // ladder.  Every accepted branch returns D1 unchanged below.
        Append(code, MoveLongD1ToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0x0000);
        Append(code, 0xEFFF);

        var sourceKeys = new (ushort Key, byte Group)[]
        {
            (GraphicsModeIds.LoresKey, 0),
            (GraphicsModeIds.HiresKey, 0),
            (GraphicsModeIds.SuperHiresKey, 1),
            (GraphicsModeIds.LoresLaceKey, 0),
            (GraphicsModeIds.HiresLaceKey, 0),
            (GraphicsModeIds.SuperHiresLaceKey, 2),
            (GraphicsModeIds.HamKey, 0),
            (GraphicsModeIds.HamLaceKey, 0),
            (GraphicsModeIds.ExtraHalfBriteKey, 0),
            (GraphicsModeIds.ExtraHalfBriteLaceKey, 0),
            (GraphicsModeIds.LoresDualPlayfieldKey, 0),
            (GraphicsModeIds.HiresDualPlayfieldKey, 0),
            (GraphicsModeIds.SuperHiresDualPlayfieldKey, 1),
            (GraphicsModeIds.LoresDualPlayfieldLaceKey, 0),
            (GraphicsModeIds.HiresDualPlayfieldLaceKey, 0),
            (GraphicsModeIds.SuperHiresDualPlayfieldLaceKey, 2),
            (GraphicsModeIds.LoresDualPlayfieldTwoKey, 0),
            (GraphicsModeIds.HiresDualPlayfieldTwoKey, 0),
            (GraphicsModeIds.SuperHiresDualPlayfieldTwoKey, 1),
            (GraphicsModeIds.LoresDualPlayfieldTwoLaceKey, 0),
            (GraphicsModeIds.HiresDualPlayfieldTwoLaceKey, 0),
            (GraphicsModeIds.SuperHiresDualPlayfieldTwoLaceKey, 2)
        };

        var progressiveSuperBranches = new List<int>(3);
        var interlaceSuperBranches = new List<int>(3);
        var ordinaryBranches = new List<int>(16);
        foreach (var (key, group) in sourceKeys)
        {
            Append(code, CompareImmediateWordD0);
            Append(code, key);
            Append(code, BranchEqualWord);
            var extensionOffset = code.Count;
            Append(code, 0);
            (group switch
            {
                1 => progressiveSuperBranches,
                2 => interlaceSuperBranches,
                _ => ordinaryBranches
            }).Add(extensionOffset);
        }
        Decline();

        void AppendLimits(
            List<int> branches,
            uint depthMaximum,
            uint componentMaximum,
            bool requiresEcs = false)
        {
            var groupOffset = code.Count;
            foreach (var branchExtensionOffset in branches)
                PatchBranch(code, branchExtensionOffset, groupOffset);

            if (requiresEcs)
            {
                Append(code, MoveByteA6DisplacementToD0);
                Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
                Append(code, BitTestImmediateD0);
                Append(code, 0); // GraphicsChipRevision.HrAgnus
                Decline(BranchEqualWord);
                Append(code, BitTestImmediateD0);
                Append(code, 1); // GraphicsChipRevision.HrDenise
                Decline(BranchEqualWord);
            }
            Append(code, CompareImmediateLongD2);
            Append(code, (ushort)(depthMaximum >> 16));
            Append(code, (ushort)depthMaximum);
            Decline(BranchHighWord);
            foreach (var register in new[] { CompareImmediateLongD4, CompareImmediateLongD5, CompareImmediateLongD6 })
            {
                Append(code, register);
                Append(code, (ushort)(componentMaximum >> 16));
                Append(code, (ushort)componentMaximum);
                Decline(BranchHighWord);
            }

            Append(code, MoveLongD1ToD0);
            Append(code, ReturnFromSubroutine);
        }

        AppendLimits(progressiveSuperBranches, 2, 2, requiresEcs: true);
        AppendLimits(interlaceSuperBranches, 2, 4, requiresEcs: true);
        // SourceID requests can carry their precise palette requirement, so
        // the ordinary branch consults the resident graphics capability just
        // like the fixed standard RGB-component form.  SuperHires remains an
        // ECS record and retains its separate limits above.
        var ordinaryCapabilityOffset = code.Count;
        foreach (var branchExtensionOffset in ordinaryBranches)
            PatchBranch(code, branchExtensionOffset, ordinaryCapabilityOffset);
        Append(code, MoveByteA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
        Append(code, BitTestImmediateD0);
        Append(code, 2); // GraphicsChipRevision.AaAlice
        Append(code, BranchEqualWord);
        var ordinaryLegacyAliceBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 3); // GraphicsChipRevision.AaLisa
        Append(code, BranchEqualWord);
        var ordinaryLegacyLisaBranchExtensionOffset = code.Count;
        Append(code, 0);
        AppendLimits([], 8, 8);
        var ordinaryLegacyLimitOffset = code.Count;
        PatchBranch(code, ordinaryLegacyAliceBranchExtensionOffset,
            ordinaryLegacyLimitOffset);
        PatchBranch(code, ordinaryLegacyLisaBranchExtensionOffset,
            ordinaryLegacyLimitOffset);
        AppendLimits([], 6, 4);

        var sourceJumpOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var sourceJumpBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, sourceJumpBranchExtensionOffset, sourceFeatureEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, sourceJumpOffset);

        return offset;
    }

    private static int AppendCoerceModeStandard(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(32);

        void Decline(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void ValidatePointer(ushort registerMove, ushort registerBitTest)
        {
            Append(code, registerMove);
            Append(code, TestLongD0);
            Decline(BranchEqualWord);
            Append(code, registerBitTest);
            Append(code, 0);
            Decline();
            Append(code, CompareImmediateLongD0);
            Append(code, 0xFFFF);
            Append(code, 0xFFD8); // ViewPort/RasInfo/BitMap 0x28-byte envelope
            Decline(BranchHighWord);
        }

        // CoerceMode(A0=ViewPort, D0=monitor, D1=flags) is a mode-selection
        // query, so retain the input monitor ID for every decline.  This
        // This native arm owns complete standard PAL 320x256 lores and
        // 640x256 hires viewports plus their explicit NTSC 320x200/640x200
        // counterparts. DEFAULT_MONITOR_ID (the resident PAL profile), PAL,
        // and NTSC are accepted; extended modes, feature keys, and every
        // other geometry remain on the portable/provider owner.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongD0ToD4); // retain the selected monitor family

        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var defaultMonitorBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0002);
        Append(code, 0x1000); // GraphicsModeIds.PalMonitor
        Append(code, BranchEqualWord);
        var palMonitorBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0001);
        Append(code, 0x1000); // GraphicsModeIds.NtscMonitor
        Decline();
        var monitorAcceptedOffset = code.Count;
        PatchBranch(code, defaultMonitorBranchExtensionOffset, monitorAcceptedOffset);
        PatchBranch(code, palMonitorBranchExtensionOffset, monitorAcceptedOffset);

        // Only the documented low flag bits are meaningful here.  The
        // progressive records ignore AVOID_FLICKER; the interlace branches
        // below explicitly decline it before publication.
        Append(code, AndImmediateLongD1);
        Append(code, 0x0000);
        Append(code, 0x0007); // retain documented PRESERVE/FLICKER/MCOMPAT bits

        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Decline();
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // complete ViewPort envelope
        Decline(BranchHighWord);

        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, CompareImmediateByteD0);
        Append(code, 0);
        Decline();
        Append(code, MoveQuickZeroD5); // zero = lores, one = Hires, two = SuperHires
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDWidth));
        Append(code, CompareImmediateWordD0);
        Append(code, 320);
        Append(code, BranchEqualWord);
        var loresWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 640);
        Append(code, BranchEqualWord);
        var hiresWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 1280);
        Decline();
        Append(code, MoveQuickTwoD0);
        Append(code, MoveLongD0ToD5);
        Append(code, BranchAlwaysWord);
        var widthAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var loresWidthOffset = code.Count;
        PatchBranch(code, loresWidthBranchExtensionOffset, loresWidthOffset);
        Append(code, MoveQuickZeroD5);
        Append(code, BranchAlwaysWord);
        var loresWidthAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var hiresWidthOffset = code.Count;
        PatchBranch(code, hiresWidthBranchExtensionOffset, hiresWidthOffset);
        Append(code, MoveQuickOneD5);
        var widthAcceptedOffset = code.Count;
        PatchBranch(code, widthAcceptedBranchExtensionOffset, widthAcceptedOffset);
        PatchBranch(code, loresWidthAcceptedBranchExtensionOffset, widthAcceptedOffset);
        // D2 is the interlace marker used by the result ladder below.  The
        // native arm admits only the complete standard progressive and
        // interlaced lores/hires envelopes: PAL 320x256/640x256 and
        // 320x512/640x512, plus their NTSC 200/400-line counterparts.
        Append(code, MoveQuickZeroD2);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDHeight));
        Append(code, CompareImmediateWordD0);
        Append(code, 256);
        Append(code, BranchEqualWord);
        var palProgressiveHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 200);
        Append(code, BranchEqualWord);
        var ntscProgressiveHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 512);
        Append(code, BranchEqualWord);
        var palInterlaceHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 400);
        Decline();
        Append(code, MoveLongD4ToD0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0001);
        Append(code, 0x1000); // 400-line geometry requires NTSC
        Decline();
        Append(code, MoveQuickOneD2);
        Append(code, BitTestImmediateD1);
        Append(code, 1); // AVOID_FLICKER declines interlace records
        Decline(BranchNotEqualWord);
        Append(code, BranchAlwaysWord);
        var heightAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var palInterlaceHeightOffset = code.Count;
        PatchBranch(code, palInterlaceHeightBranchExtensionOffset, palInterlaceHeightOffset);
        Append(code, MoveLongD4ToD0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0001);
        Append(code, 0x1000); // 512-line geometry rejects NTSC
        Append(code, BranchEqualWord);
        var palInterlaceNtscBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(palInterlaceNtscBranchExtensionOffset);
        Append(code, MoveQuickOneD2);
        Append(code, BitTestImmediateD1);
        Append(code, 1); // AVOID_FLICKER declines interlace records
        Decline(BranchNotEqualWord);
        Append(code, BranchAlwaysWord);
        var palInterlaceAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var ntscProgressiveHeightOffset = code.Count;
        PatchBranch(code, ntscProgressiveHeightBranchExtensionOffset, ntscProgressiveHeightOffset);
        Append(code, MoveLongD4ToD0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0001);
        Append(code, 0x1000); // 200-line geometry requires NTSC
        Decline();
        Append(code, BranchAlwaysWord);
        var ntscProgressiveAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var palProgressiveHeightOffset = code.Count;
        PatchBranch(code, palProgressiveHeightBranchExtensionOffset, palProgressiveHeightOffset);
        Append(code, MoveLongD4ToD0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0001);
        Append(code, 0x1000); // 256-line geometry rejects NTSC
        Append(code, BranchEqualWord);
        var palProgressiveNtscBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(palProgressiveNtscBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var palProgressiveAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var modeHeightAcceptedOffset = code.Count;
        PatchBranch(code, heightAcceptedBranchExtensionOffset, modeHeightAcceptedOffset);
        PatchBranch(code, palInterlaceAcceptedBranchExtensionOffset, modeHeightAcceptedOffset);
        PatchBranch(code, ntscProgressiveAcceptedBranchExtensionOffset, modeHeightAcceptedOffset);
        PatchBranch(code, palProgressiveAcceptedBranchExtensionOffset, modeHeightAcceptedOffset);

        // Validate native keys independently of the requested geometry.
        // The associated record supplies features; geometry supplies resolution.
        void ValidateCoerceKey()
        {
            var accepted = new List<int>();
            foreach (var key in new ushort[] {
                0, 4, 0x80, 0x84, 0x400, 0x404, 0x440, 0x444,
                0x800, 0x804, 0x8000, 0x8004, 0x8020, 0x8024,
                0x8400, 0x8404, 0x8440, 0x8444,
                0x8420, 0x8424, 0x8460, 0x8464 })
            {
                Append(code, CompareImmediateWordD0);
                Append(code, key);
                Append(code, BranchEqualWord);
                accepted.Add(code.Count);
                Append(code, 0);
            }
            Decline(BranchAlwaysWord);
            foreach (var branch in accepted)
                PatchBranch(code, branch, code.Count);
        }
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        ValidateCoerceKey();
        Append(code, MoveQuickZeroD3);
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var loresGeometryBranch = code.Count;
        Append(code, 0);
        Append(code, 0x0043); // ORI.W #HIRES,D3
        Append(code, 0x8000);
        Append(code, CompareImmediateWordD5);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var hiresGeometryBranch = code.Count;
        Append(code, 0);
        Append(code, 0x0043); // ORI.W #SUPERHIRES,D3
        Append(code, 0x20);
        PatchBranch(code, loresGeometryBranch, code.Count);
        PatchBranch(code, hiresGeometryBranch, code.Count);
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var progressiveGeometryBranch = code.Count;
        Append(code, 0);
        Append(code, 0x0043); // ORI.W #LACE,D3
        Append(code, 4);
        PatchBranch(code, progressiveGeometryBranch, code.Count);

        // Feature semantics come from an associated display record, not the
        // Modes word of an assembling viewport. Keep foreign/override forms
        // on their existing owner until that broader association arm is added.
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortColorMap));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var absentAssociationBranch = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD0ToA3);
        ValidatePointer(MoveLongA3ToD0, BitTestImmediateD0);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapModeId));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapNormalDisplayInfo));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var emptyAssociationBranch = code.Count;
        Append(code, 0);
        Append(code, MoveLongD0ToD6);
        Append(code, AndImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0x1000);
        var associationMonitorBranches = new List<int>();
        foreach (var family in new uint[] { 0, 0x11000, 0x21000 })
        {
            Append(code, CompareImmediateLongD0);
            Append(code, (ushort)(family >> 16));
            Append(code, (ushort)family);
            Append(code, BranchEqualWord);
            associationMonitorBranches.Add(code.Count);
            Append(code, 0);
        }
        Decline(BranchAlwaysWord);
        foreach (var branch in associationMonitorBranches)
            PatchBranch(code, branch, code.Count);
        Append(code, MoveLongD6ToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0);
        Append(code, 0xEFFF);
        ValidateCoerceKey();
        // An associated record supplies nominal geometry as well as features.
        // Destination depth filtering below may still lower the resolution.
        Append(code, MoveLongD0ToD3);
        Append(code, MoveQuickZeroD5);
        Append(code, BitTestImmediateD0);
        Append(code, 15);
        Append(code, BranchEqualWord);
        var sourceLoresGeometryBranch = code.Count;
        Append(code, 0);
        Append(code, MoveQuickOneD5);
        Append(code, BitTestImmediateD0);
        Append(code, 5);
        Append(code, BranchEqualWord);
        var sourceHiresGeometryBranch = code.Count;
        Append(code, 0);
        Append(code, MoveQuickTwoD0);
        Append(code, MoveLongD0ToD5);
        PatchBranch(code, sourceLoresGeometryBranch, code.Count);
        PatchBranch(code, sourceHiresGeometryBranch, code.Count);
        Append(code, BranchAlwaysWord);
        var associationAcceptedBranch = code.Count;
        Append(code, 0);
        PatchBranch(code, absentAssociationBranch, code.Count);
        PatchBranch(code, emptyAssociationBranch, code.Count);
        Append(code, AndImmediateLongD3);
        Append(code, 0);
        Append(code, 0xF33F); // remove HAM/EHB/dual/priority features.
        PatchBranch(code, associationAcceptedBranch, code.Count);

        // A 1280-pixel result is SuperHires.  Reject it on OCS before the
        // bitmap/depth checks so the fallback can apply its own ownership
        // policy with the original monitor ID intact.
        Append(code, CompareImmediateWordD5);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var ordinaryCapabilityBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
        Append(code, BitTestImmediateD0);
        Append(code, 0); // GraphicsChipRevision.HrAgnus
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD0);
        Append(code, 1); // GraphicsChipRevision.HrDenise
        Decline(BranchEqualWord);
        PatchBranch(code, ordinaryCapabilityBranchExtensionOffset, code.Count);

        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, MoveAddressD0ToA1);
        ValidatePointer(
            MoveLongA1ToD0,
            BitTestImmediateD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
        Append(code, TestLongD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoBitMap));
        Append(code, MoveAddressD0ToA2);
        ValidatePointer(
            MoveLongA2ToD0,
            BitTestImmediateD0);

        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var standardFlagBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD6);
        Append(code, 0x08); // BMF_STANDARD
        Decline();
        var flagsAcceptedOffset = code.Count;
        PatchBranch(code, standardFlagBranchExtensionOffset, flagsAcceptedOffset);

        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, TestLongD6);
        Decline(BranchEqualWord);
        Append(code, CompareImmediateByteD6);
        Append(code, 8);
        Decline(BranchHighWord);

        // Validate source depth even without PRESERVE_COLORS. Ordinary
        // six-plane lores must return INVALID, not be reinterpreted as HAM.
        var invalidDepthBranches = new List<int>();
        void LimitSourceDepth(ushort maximum)
        {
            Append(code, CompareImmediateByteD6);
            Append(code, maximum);
            Append(code, BranchHighWord);
            invalidDepthBranches.Add(code.Count);
            Append(code, 0);
        }
        Append(code, CompareImmediateWordD5);
        Append(code, 2); // SuperHires width marker
        Append(code, BranchNotEqualWord);
        var standardPreserveDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        LimitSourceDepth(2);
        Append(code, BranchAlwaysWord);
        var superPreserveDepthAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var standardPreserveDepthOffset = code.Count;
        PatchBranch(code, standardPreserveDepthBranchExtensionOffset, standardPreserveDepthOffset);
        Append(code, CompareImmediateByteD6);
        Append(code, 8);
        Decline(BranchHighWord);
        Append(code, MoveByteA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
        Append(code, BitTestImmediateD0);
        Append(code, 2); // GraphicsChipRevision.AaAlice
        Append(code, BranchNotEqualWord);
        var agaAliceBranchExtensionOffset = code.Count;
        Append(code, 0);

        var legacyPreserveDepthOffset = code.Count;
        LimitSourceDepth(6);
        Append(code, CompareImmediateWordD5);
        Append(code, 1); // Hires, including dual playfields, supports four.
        Append(code, BranchNotEqualWord);
        var loresDepthBranch = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD6);
        Append(code, 4);
        Append(code, 0x6300); // BLS.W: hires destination supports this depth.
        var hiresDepthAcceptedBranch = code.Count;
        Append(code, 0);
        // A deeper hires request may fit lores with the same source features.
        Append(code, AndImmediateLongD3);
        Append(code, 0);
        Append(code, 0x7FFF);
        Append(code, MoveQuickZeroD5);
        PatchBranch(code, loresDepthBranch, code.Count);
        Append(code, MoveLongD3ToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0);
        Append(code, 0x0C80); // HAM, dual playfield, or EHB: six planes.
        Append(code, BranchNotEqualWord);
        var featureDepthAcceptedBranch = code.Count;
        Append(code, 0);
        LimitSourceDepth(5);
        Append(code, BranchAlwaysWord);
        var legacyPreserveDepthAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var agaAliceOffset = code.Count;
        PatchBranch(code, agaAliceBranchExtensionOffset, agaAliceOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 3); // GraphicsChipRevision.AaLisa
        Append(code, BranchEqualWord);
        var partialAgaPreserveDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var agaPreserveDepthAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        PatchBranch(code, hiresDepthAcceptedBranch, successOffset);
        PatchBranch(code, featureDepthAcceptedBranch, successOffset);
        PatchBranch(code, superPreserveDepthAcceptedBranchExtensionOffset, successOffset);
        PatchBranch(code, legacyPreserveDepthAcceptedBranchExtensionOffset, successOffset);
        PatchBranch(code, agaPreserveDepthAcceptedBranchExtensionOffset, successOffset);
        PatchBranch(code, partialAgaPreserveDepthBranchExtensionOffset,
            legacyPreserveDepthOffset);

        // D3 carries the accepted canonical key.  Start each result from the
        // concrete PAL/NTSC high word, copy the key into the low word, then
        // restore the monitor-part base bit which is shared by all records.
        // This keeps HAM/EHB and interlace result IDs in the same compact
        // guest-relative body as the standard lores/Hires records.
        Append(code, MoveLongD4ToD0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0001);
        Append(code, 0x1000); // GraphicsModeIds.NtscMonitor
        Append(code, BranchEqualWord);
        var ntscResultBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongImmediateD0);
        Append(code, 0x0002); // PAL/default high word
        Append(code, 0x1000); // PAL monitor-part base
        Append(code, MoveWordD3ToD0);
        Append(code, OrImmediateWordD0);
        Append(code, 0x1000);
        Append(code, ReturnFromSubroutine);

        var ntscResultOffset = code.Count;
        PatchBranch(code, ntscResultBranchExtensionOffset, ntscResultOffset);
        Append(code, MoveLongImmediateD0);
        Append(code, 0x0001); // NTSC high word
        Append(code, 0x1000); // NTSC monitor-part base
        Append(code, MoveWordD3ToD0);
        Append(code, OrImmediateWordD0);
        Append(code, 0x1000);
        Append(code, ReturnFromSubroutine);

        var invalidDepthOffset = code.Count;
        Append(code, 0x70FF); // MOVEQ #-1,D0: recognized invalid source.
        Append(code, ReturnFromSubroutine);
        foreach (var branch in invalidDepthBranches)
            PatchBranch(code, branch, invalidDepthOffset);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendNextDisplayInfoCanonical(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;

        // NextDisplayInfo walks the public NativeModes order: default-monitor
        // standard modes, default feature modes, then the same two groups for
        // PAL and NTSC.  Keep that ordering in the native body so callers can
        // enumerate the database without entering the host/provider path.
        var modeIds = new List<uint>(66);
        var standardKeys = new ushort[]
        {
            GraphicsModeIds.LoresKey,
            GraphicsModeIds.HiresKey,
            GraphicsModeIds.SuperHiresKey,
            GraphicsModeIds.LoresLaceKey,
            GraphicsModeIds.HiresLaceKey,
            GraphicsModeIds.SuperHiresLaceKey
        };
        var featureKeys = new ushort[]
        {
            GraphicsModeIds.HamKey,
            GraphicsModeIds.HamLaceKey,
            GraphicsModeIds.ExtraHalfBriteKey,
            GraphicsModeIds.ExtraHalfBriteLaceKey,
            GraphicsModeIds.LoresDualPlayfieldKey,
            GraphicsModeIds.HiresDualPlayfieldKey,
            GraphicsModeIds.SuperHiresDualPlayfieldKey,
            GraphicsModeIds.LoresDualPlayfieldLaceKey,
            GraphicsModeIds.HiresDualPlayfieldLaceKey,
            GraphicsModeIds.SuperHiresDualPlayfieldLaceKey,
            GraphicsModeIds.LoresDualPlayfieldTwoKey,
            GraphicsModeIds.HiresDualPlayfieldTwoKey,
            GraphicsModeIds.SuperHiresDualPlayfieldTwoKey,
            GraphicsModeIds.LoresDualPlayfieldTwoLaceKey,
            GraphicsModeIds.HiresDualPlayfieldTwoLaceKey,
            GraphicsModeIds.SuperHiresDualPlayfieldTwoLaceKey
        };

        void AddMonitorStandardModes(uint monitor)
        {
            foreach (var key in standardKeys)
                modeIds.Add(monitor | key);
        }

        void AddMonitorFeatureModes(uint monitor)
        {
            foreach (var key in featureKeys)
                modeIds.Add(monitor | key);
        }

        AddMonitorStandardModes(GraphicsModeIds.DefaultMonitor);
        AddMonitorFeatureModes(GraphicsModeIds.DefaultMonitor);
        AddMonitorStandardModes(GraphicsModeIds.PalMonitor);
        AddMonitorStandardModes(GraphicsModeIds.NtscMonitor);
        AddMonitorFeatureModes(GraphicsModeIds.PalMonitor);
        AddMonitorFeatureModes(GraphicsModeIds.NtscMonitor);

        void AppendResult(uint result)
        {
            if (result == GraphicsModeIds.Invalid)
            {
                Append(code, MoveQuickMinusOneD0);
            }
            else if (result == GraphicsModeIds.DefaultMonitor)
            {
                Append(code, MoveQuickZeroD0);
            }
            else
            {
                Append(code, MoveLongImmediateD0);
                Append(code, (ushort)(result >> 16));
                Append(code, (ushort)result);
            }

            Append(code, ReturnFromSubroutine);
        }

        // D1 is public volatile scratch.  Keep the original cursor there so
        // every canonical result and the foreign owner handoff preserve the
        // complete D2-D7/A2-A6 callee-save set without a stack frame.
        Append(code, MoveLongD0ToD1);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var invalidResultSkipBranchExtensionOffset = code.Count;
        Append(code, 0);
        AppendResult(GraphicsModeIds.DefaultMonitor);
        PatchBranch(code, invalidResultSkipBranchExtensionOffset, code.Count);

        // FindDisplayInfo uses a private nonzero handle for the valid zero
        // mode.  Accept that handle as a courtesy and map it to the second
        // public key, matching GraphicsDisplayDatabase.NextDisplayInfo.
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE);
        Append(code, BranchNotEqualWord);
        var defaultHandleResultSkipBranchExtensionOffset = code.Count;
        Append(code, 0);
        AppendResult(modeIds[1]);
        PatchBranch(code, defaultHandleResultSkipBranchExtensionOffset, code.Count);

        for (var index = 0; index < modeIds.Count; index++)
        {
            var modeId = modeIds[index];
            Append(code, CompareImmediateLongD0);
            Append(code, (ushort)(modeId >> 16));
            Append(code, (ushort)modeId);
            Append(code, BranchNotEqualWord);
            var resultSkipBranchExtensionOffset = code.Count;
            Append(code, 0);
            var result = index + 1 < modeIds.Count
                ? modeIds[index + 1]
                : GraphicsModeIds.Invalid;
            AppendResult(result);
            PatchBranch(code, resultSkipBranchExtensionOffset, code.Count);
        }

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD1ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendDisplayInfoDataCanonical(
        List<byte> code,
        int fallbackEntryOffset,
        bool defaultMonitorNtsc,
        bool enableNativeMonitorMutation = false)
    {
        var offset = code.Count;
        var defaultMonitor = defaultMonitorNtsc ? GraphicsModeIds.NtscMonitor : GraphicsModeIds.PalMonitor;
        var stagedFallbackBranches = new List<int>(14);
        var modeIds = GetCanonicalDisplayModeIds();

        // Match the portable database's universal no-record query before tag,
        // size, destination, or capability admission.  A non-null handle stays
        // authoritative even when D2 is INVALID_ID, so both failed comparisons
        // continue at the untouched ordinary entry without borrowing scratch.
        Append(code, CompareAddressImmediateLongA0); // CMPA.L #0,A0
        Append(code, 0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var nonNullHandleToOrdinaryQueryExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD2);
        Append(code, 0xFFFF);
        Append(code, 0xFFFF); // GraphicsModeIds.Invalid
        Append(code, BranchNotEqualWord);
        var nonInvalidModeToOrdinaryQueryExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var nonSentinelQueryOffset = code.Count;
        PatchBranch(code, nonNullHandleToOrdinaryQueryExtensionOffset, nonSentinelQueryOffset);
        PatchBranch(code, nonInvalidModeToOrdinaryQueryExtensionOffset, nonSentinelQueryOffset);

        AppendRegisteredMonitorInfo(code, fallbackEntryOffset, enableNativeMonitorMutation,
            defaultMonitorNtsc);

        // The portable owner resolves DTAG_VEC and foreign/provider modes
        // before treating A1=NULL or D0=0 as an ordinary no-write query. Keep
        // that precedence in a small entry lane so every other call retains
        // the existing publication path. CMPA is required on a 68000 because
        // address registers have no TST encoding.
        Append(code, CompareAddressImmediateLongA1); // CMPA.L #0,A1
        Append(code, 0);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var nullDestinationToEmptyQueryExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var nonemptyToOrdinaryQueryExtensionOffset = code.Count;
        Append(code, 0);

        var emptyQueryOffset = code.Count;
        PatchBranch(code, nullDestinationToEmptyQueryExtensionOffset, emptyQueryOffset);

        // DTAG_VEC is always left to a resident monitor/provider after the
        // completed NULL-handle/INVALID_ID sentinel above. It must retain the
        // original D0 and must not acquire a destination or GfxBase access.
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x4000); // GraphicsDisplayDatabase.DtagVec
        Append(code, BranchEqualWord);
        var emptyVectorToProviderExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveLongD0ToPreDecrementA7); // preserve original size
        var emptyModeResolutionOffset = code.Count;

        // Resolve the public handle before the fallback ModeID. The private
        // default handle maps to the public default-monitor mode just as it
        // does in the ordinary record path.
        Append(code, MoveLongA0ToD0);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var emptyNonNullHandleBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD2ToD0);
        Append(code, BranchAlwaysWord);
        var emptyNullHandleToSelectedModeExtensionOffset = code.Count;
        Append(code, 0);

        var emptyNonNullHandleOffset = code.Count;
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE); // GraphicsDisplayDatabase.DefaultModeHandle
        Append(code, BranchNotEqualWord);
        var emptyPublicHandleToSelectedModeExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD0);

        var emptySelectedModeOffset = code.Count;
        PatchBranch(
            code,
            emptyNonNullHandleBranchExtensionOffset,
            emptyNonNullHandleOffset);
        PatchBranch(
            code,
            emptyNullHandleToSelectedModeExtensionOffset,
            emptySelectedModeOffset);
        PatchBranch(
            code,
            emptyPublicHandleToSelectedModeExtensionOffset,
            emptySelectedModeOffset);

        var ownedEmptyQueryBranches = new List<int>(modeIds.Count);
        foreach (var modeId in modeIds)
        {
            Append(code, CompareImmediateLongD0);
            Append(code, (ushort)(modeId >> 16));
            Append(code, (ushort)modeId);
            Append(code, BranchEqualWord);
            ownedEmptyQueryBranches.Add(code.Count);
            Append(code, 0);
        }

        // A foreign mode keeps its provider opportunity and its original D0.
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var emptyForeignModeToProviderExtensionOffset = code.Count;
        Append(code, 0);

        var ownedEmptyQueryOffset = code.Count;
        foreach (var branchExtensionOffset in ownedEmptyQueryBranches)
            PatchBranch(code, branchExtensionOffset, ownedEmptyQueryOffset);
        Append(code, AddQuickFourLongA7); // discard original size
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        // Link provider declines through an explicit BRA.W. The distant shared
        // fallback is an RTS, so the branch linker emits an adjacent,
        // relocatable RTS clone while preserving provider-terminal provenance.
        var emptyProviderOffset = code.Count;
        PatchBranch(code, emptyVectorToProviderExtensionOffset, emptyProviderOffset);
        PatchBranch(code, emptyForeignModeToProviderExtensionOffset, emptyProviderOffset);
        Append(code, BranchAlwaysWord);
        var emptyProviderFallbackExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, emptyProviderFallbackExtensionOffset, fallbackEntryOffset);

        var ordinaryQueryOffset = code.Count;
        PatchBranch(code, nonemptyToOrdinaryQueryExtensionOffset, ordinaryQueryOffset);

        // DTAG_VEC is provider-owned for nonempty calls too. Resolve it before
        // staging D0 so the proven provider terminal retains the public value
        // without another unwind path.
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x4000); // GraphicsDisplayDatabase.DtagVec
        Append(code, BranchEqualWord);
        var nonemptyVectorToProviderExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, nonemptyVectorToProviderExtensionOffset, emptyProviderOffset);

        // This native slice owns the complete DtagDisp, DtagDims, DtagName, and
        // resident-default DtagMntr records for the canonical OCS/ECS database.
        // It additionally owns every one- through fifty-five-byte DtagName
        // prefix and every one- through fifty-five-byte DtagDisp prefix, plus
        // every DIMS scalar/complete-Rectangle prefix, and every one- through
        // sixteen-byte MNTR QueryHeader prefix and the resident-default
        // MonitorSpec pointer prefixes through byte twenty. Other
        // partial chunks remain on the portable or monitor/
        // provider path until their own transactional publication units are
        // implemented.
        Append(code, MoveLongD0ToPreDecrementA7); // stage requested byte count
        Append(code, BranchAlwaysWord);
        var skipLocalFallbackExtensionOffset = code.Count;
        Append(code, 0);
        var stagedLocalFallbackOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, skipLocalFallbackExtensionOffset, code.Count);

        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x0000); // GraphicsDisplayDatabase.DtagDisp
        Append(code, BranchEqualWord);
        var displayTagBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x3000); // GraphicsDisplayDatabase.DtagName
        Append(code, BranchEqualWord);
        var nameTagBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x2000); // GraphicsDisplayDatabase.DtagMntr
        Append(code, BranchEqualWord);
        var monitorTagBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x1000); // GraphicsDisplayDatabase.DtagDims
        Append(code, BranchNotEqualWord);
        var unsupportedTagToModeResolutionExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(
            code,
            unsupportedTagToModeResolutionExtensionOffset,
            emptyModeResolutionOffset);
        // Only complete Rectangle fields follow the byte-granular scalar
        // prefix. Admit the actual transfer, not the unused requested tail;
        // preserve the original count on the staged stack for every decline.
        AppendDimensionsTransferCount(code, 0);
        Append(code, BranchAlwaysWord);
        var dimensionsSizeToDestinationExtensionOffset = code.Count;
        Append(code, 0);

        var monitorSizeCheckOffset = code.Count;
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 0x0018); // QueryHeader, default MonitorSpec pointer and ViewPosition
        Append(code, BranchLowerOrSameWord);
        var monitorPrefixToDestinationExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 0x0058); // full MNTR payload excludes the SDK terminators
        Append(code, BranchCarryWord);
        stagedFallbackBranches.Add(code.Count);
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var monitorSizeToDestinationExtensionOffset = code.Count;
        Append(code, 0);

        var displaySizeCheckOffset = code.Count;
        // DISP's public transfer ends at48 bytes. Preserve the original size
        // on the staged stack for provider declines; admit only the capped
        // byte span, including odd destinations handled by the byte publisher.
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 0x0030);
        Append(code, BranchLowerOrSameWord);
        var displayHeaderToDestinationExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, (ushort)(MoveQuickZeroD0 | 48));
        Append(code, BranchAlwaysWord);
        var displayCappedToDestinationExtensionOffset = code.Count;
        Append(code, 0);

        var nameSizeCheckOffset = code.Count;
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 0x0037);
        Append(code, BranchLowerOrSameWord);
        var nameHeaderToDestinationExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var fullNameToDestinationExtensionOffset = code.Count;
        Append(code, 0);

        // DISP, DIMS and MNTR QueryHeaders use byte stores after the universal
        // null-destination lane. DIMS counts include only complete Rectangles,
        // but rectangle-bearing odd destinations remain unowned: the original
        // ROM probes did not establish a returning transfer for those calls.
        // The existing odd scalar-prefix policy remains separate.
        // Preserve D1 across the inclusive end-address
        // carry proof so both the admitted and local-decline exits retain the
        // exact public tag without borrowing a public data/address register.
        var displayHeaderDestinationOffset = code.Count;
        PatchBranch(code, displayCappedToDestinationExtensionOffset, displayHeaderDestinationOffset);
        PatchBranch(
            code,
            monitorPrefixToDestinationExtensionOffset,
            displayHeaderDestinationOffset);
        PatchBranch(
            code,
            dimensionsSizeToDestinationExtensionOffset,
            displayHeaderDestinationOffset);
        PatchBranch(
            code,
            displayHeaderToDestinationExtensionOffset,
            displayHeaderDestinationOffset);
        Append(code, MoveLongD1ToPreDecrementA7);
        // Borrow only the already-saved public tag for the new alignment
        // decline. No destination or capability byte has been accessed, and
        // the common unwind restores both D1 and the original requested D0.
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x1000);
        Append(code, BranchNotEqualWord);
        var nonDimensionsToByteSpanExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 34); // actual count: requests27..33 still transfer26
        Append(code, BranchCarryWord);
        var dimensionsScalarToByteSpanExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1ToD1);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddDimensionsToLocalDeclineExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, nonDimensionsToByteSpanExtensionOffset, code.Count);
        PatchBranch(code, dimensionsScalarToByteSpanExtensionOffset, code.Count);
        Append(code, MoveLongD0ToD1);
        Append(code, SubQuickOneLongD1);
        Append(code, MoveLongA1ToD0);
        Append(code, AddLongD1ToD0);
        Append(code, BranchCarryWord);
        var displayHeaderOverflowExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA7PostIncrementToD1);
        Append(code, BranchAlwaysWord);
        var displayHeaderToAdmittedExtensionOffset = code.Count;
        Append(code, 0);

        var displayHeaderOverflowOffset = code.Count;
        PatchBranch(
            code,
            oddDimensionsToLocalDeclineExtensionOffset,
            displayHeaderOverflowOffset);
        PatchBranch(
            code,
            displayHeaderOverflowExtensionOffset,
            displayHeaderOverflowOffset);
        Append(code, MoveLongA7PostIncrementToD1);
        Append(code, BranchAlwaysWord);
        var displayHeaderOverflowToFallbackExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(
            code,
            displayHeaderOverflowToFallbackExtensionOffset,
            stagedLocalFallbackOffset);

        // Partial DtagName records are byte-granular. Prove the inclusive end
        // address in volatile D0/D1, restore the public tag on both exits, and
        // leave the requested count staged for mode ownership and return.
        var nameHeaderDestinationOffset = code.Count;
        PatchBranch(
            code,
            nameHeaderToDestinationExtensionOffset,
            nameHeaderDestinationOffset);
        Append(code, MoveLongD0ToD1);
        Append(code, SubQuickOneLongD1);
        Append(code, MoveLongA1ToD0);
        Append(code, AddLongD1ToD0);
        Append(code, BranchCarryWord);
        var nameHeaderOverflowExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x8000);
        Append(code, 0x3000); // GraphicsDisplayDatabase.DtagName
        Append(code, BranchAlwaysWord);
        var nameHeaderToAdmittedExtensionOffset = code.Count;
        Append(code, 0);

        var nameHeaderOverflowOffset = code.Count;
        PatchBranch(code, nameHeaderOverflowExtensionOffset, nameHeaderOverflowOffset);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x8000);
        Append(code, 0x3000); // GraphicsDisplayDatabase.DtagName
        Append(code, BranchAlwaysWord);
        var nameHeaderOverflowToFallbackExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(
            code,
            nameHeaderOverflowToFallbackExtensionOffset,
            stagedLocalFallbackOffset);

        var destinationValidationOffset = code.Count;
        PatchBranch(code, displayTagBranchExtensionOffset, displaySizeCheckOffset);
        PatchBranch(code, nameTagBranchExtensionOffset, nameSizeCheckOffset);
        PatchBranch(code, monitorTagBranchExtensionOffset, monitorSizeCheckOffset);
        PatchBranch(code, monitorSizeToDestinationExtensionOffset, destinationValidationOffset);
        PatchBranch(code, fullNameToDestinationExtensionOffset, destinationValidationOffset);

        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        stagedFallbackBranches.Add(code.Count);
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0x0000);
        Append(code, BranchNotEqualWord);
        stagedFallbackBranches.Add(code.Count);
        Append(code, 0);

        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x2000); // GraphicsDisplayDatabase.DtagMntr
        Append(code, BranchEqualWord);
        var monitorSpanBranchExtensionOffset = code.Count;
        Append(code, 0);

        // DtagDisp and DtagName both publish exactly 0x38 bytes.
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFC8);
        Append(code, BranchHighWord);
        stagedFallbackBranches.Add(code.Count);
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var displaySpanToAdmittedExtensionOffset = code.Count;
        Append(code, 0);

        var monitorSpanOffset = code.Count;
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFA8); // last valid start for an inclusive88-byte span
        Append(code, BranchHighWord);
        stagedFallbackBranches.Add(code.Count);
        Append(code, 0);

        var destinationAdmittedOffset = code.Count;
        PatchBranch(code, monitorSpanBranchExtensionOffset, monitorSpanOffset);
        PatchBranch(code, displaySpanToAdmittedExtensionOffset, destinationAdmittedOffset);
        PatchBranch(code, displayHeaderToAdmittedExtensionOffset, destinationAdmittedOffset);
        PatchBranch(code, nameHeaderToAdmittedExtensionOffset, destinationAdmittedOffset);

        // A non-null DisplayInfo handle is authoritative in the public ABI.
        // Resolve it in volatile D0 without changing the fallback ModeID in D2.
        // A null handle selects D2; the private default handle selects public
        // mode zero.  Keep the requested size staged until canonical membership
        // and the resident-default-only monitor rule are both known.
        Append(code, MoveLongA0ToD0);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var nonNullHandleBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD2ToD0);
        Append(code, BranchAlwaysWord);
        var nullHandleToSelectedModeExtensionOffset = code.Count;
        Append(code, 0);

        var nonNullHandleOffset = code.Count;
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE);
        Append(code, BranchNotEqualWord);
        var publicHandleToSelectedModeExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD0);

        var selectedModeOffset = code.Count;
        PatchBranch(code, nonNullHandleBranchExtensionOffset, nonNullHandleOffset);
        PatchBranch(code, nullHandleToSelectedModeExtensionOffset, selectedModeOffset);
        PatchBranch(code, publicHandleToSelectedModeExtensionOffset, selectedModeOffset);

        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x2000); // GraphicsDisplayDatabase.DtagMntr
        Append(code, BranchNotEqualWord);
        var nonMonitorTagBranchExtensionOffset = code.Count;
        Append(code, 0);
        // A MonitorInfo header contains no resident MonitorSpec pointer.
        // Resolve membership/provider ownership without reading defaultMonitor.
        Append(code, CompareImmediateLongA7Indirect);
        Append(code, 0);
        Append(code, 0x0010);
        Append(code, BranchLowerOrSameWord);
        var monitorHeaderToMembershipExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        stagedFallbackBranches.Add(code.Count);
        Append(code, 0);

        // Only the resident-default DTAG_MNTR form reaches this point.  Admit
        // the complete GfxBase.defaultMonitor LONG and a non-null resident
        // pointer before the requested size enters D7.  A0 is volatile in the
        // public ABI and retains the exact pointer for the later record arm,
        // avoiding a second A6 read after admission.
        Append(code, MoveLongA6ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        stagedFallbackBranches.Add(code.Count);
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        stagedFallbackBranches.Add(code.Count);
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFE6E); // uint.MaxValue - (GfxBaseDefaultMonitor + 3)
        Append(code, BranchHighWord);
        stagedFallbackBranches.Add(code.Count);
        Append(code, 0);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseDefaultMonitor));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        stagedFallbackBranches.Add(code.Count);
        Append(code, 0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveQuickZeroD0); // restore selected default ModeID

        var capabilityTagOffset = code.Count;
        PatchBranch(code, nonMonitorTagBranchExtensionOffset, capabilityTagOffset);
        PatchBranch(code, monitorHeaderToMembershipExtensionOffset, capabilityTagOffset);

        // Prove canonical membership for every supported tag before entering
        // the public frame. Foreign/provider-owned modes still traverse the
        // existing unframed dispatch and fallback path, preserving their exact
        // owner provenance without acquiring an A6 dependency.
        var capabilityMembershipBranchExtensionOffsets = new List<int>(modeIds.Count);
        foreach (var modeId in modeIds)
        {
            Append(code, CompareImmediateLongD0);
            Append(code, (ushort)(modeId >> 16));
            Append(code, (ushort)modeId);
            Append(code, BranchEqualWord);
            capabilityMembershipBranchExtensionOffsets.Add(code.Count);
            Append(code, 0);
        }

        Append(code, BranchAlwaysWord);
        var foreignModeToModeDispatchExtensionOffset = code.Count;
        Append(code, 0);

        // This failure path owns two stacked longs: the selected mode saved
        // below and the original requested byte count staged on entry.
        var capabilityFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // discard selected mode
        Append(code, MoveLongA7PostIncrementToD0); // restore requested size
        Append(code, ReturnFromSubroutine);

        var canonicalAdmissionOffset = code.Count;
        foreach (var branchExtensionOffset in capabilityMembershipBranchExtensionOffsets)
            PatchBranch(code, branchExtensionOffset, canonicalAdmissionOffset);

        // Every admitted header-only query is independent of capabilities.
        // This is after ownership resolution: foreign modes still tail-chain.
        // DIMS17 is also read-free (the invariant high depth byte). All larger
        // DIMS transfers retain capability guards. MNTR17..20 has already
        // acquired its resident pointer; MNTR21..87 remains unowned.
        // Only read our staged count here.
        Append(code, CompareImmediateLongA7Indirect);
        Append(code, 0);
        Append(code, 0x0010);
        Append(code, BranchLowerOrSameWord);
        var queryHeaderReadFreeToFrameExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x1000);
        Append(code, BranchNotEqualWord);
        var nonDimsDepthToCapabilitySplit = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongA7Indirect);
        Append(code, 0);
        Append(code, 17); // invariant-zero high MaxDepth byte needs no A6 read
        Append(code, BranchEqualWord);
        var dimsHighDepthReadFreeToFrame = code.Count;
        Append(code, 0);
        PatchBranch(code, nonDimsDepthToCapabilitySplit, code.Count);

        // DTAG_DISP calls through byte 17 are A6-read-free because offset 0x10
        // is the invariant-zero high byte of NotAvailable. Exact sizes 18 and
        // 19 are also read-free for ordinary modes, while SuperHires alone
        // needs the low NotAvailable byte derived from ChipRevBits0. Every
        // exact size-20 through size-55 request needs that same byte for the low
        // half of the Properties prefix, so these sizes continue into the
        // capability guard even
        // for ordinary modes. Keep these tests after canonical membership so
        // foreign modes retain provider provenance. Full DISP records continue
        // into the same guard. DTAG_NAME and the already-admitted
        // resident-default DTAG_MNTR form remain read-free through the tag-bit
        // split below.
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x0000); // GraphicsDisplayDatabase.DtagDisp
        Append(code, BranchNotEqualWord);
        var nonDisplayTagToCapabilitySplitExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongA7Indirect);
        Append(code, 0);
        Append(code, 0x0011); // staged requested byte count
        Append(code, BranchLowerOrSameWord);
        var displayReadFreeToFrameExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongA7Indirect);
        Append(code, 0);
        Append(code, 0x0013); // through invariant high Properties byte
        Append(code, BranchHighWord);
        var laterDisplayToCapabilitySplitExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 5); // GraphicsModeIds.SuperHiresMode
        Append(code, BranchEqualWord);
        var ordinaryDisplayShortToFrameExtensionOffset = code.Count;
        Append(code, 0);

        var capabilityTagSplitOffset = code.Count;
        PatchBranch(
            code,
            nonDisplayTagToCapabilitySplitExtensionOffset,
            capabilityTagSplitOffset);
        PatchBranch(
            code,
            laterDisplayToCapabilitySplitExtensionOffset,
            capabilityTagSplitOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchNotEqualWord);
        var readFreeTagToFrameExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveLongD0ToPreDecrementA7); // preserve selected mode
        Append(code, MoveLongA6ToD0);
        var capabilityFailureBranchExtensionOffsets = new List<int>(3);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        capabilityFailureBranchExtensionOffsets.Add(code.Count);
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        capabilityFailureBranchExtensionOffsets.Add(code.Count);
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFF13); // uint.MaxValue - GraphicsLayouts.GfxBaseChipRevBits0
        Append(code, BranchHighWord);
        capabilityFailureBranchExtensionOffsets.Add(code.Count);
        Append(code, 0);
        Append(code, MoveLongA7PostIncrementToD0); // restore selected mode

        var publicFrameOffset = code.Count;
        PatchBranch(code, dimsHighDepthReadFreeToFrame, publicFrameOffset);
        PatchBranch(code, queryHeaderReadFreeToFrameExtensionOffset, publicFrameOffset);
        PatchBranch(code, displayReadFreeToFrameExtensionOffset, publicFrameOffset);
        PatchBranch(
            code,
            ordinaryDisplayShortToFrameExtensionOffset,
            publicFrameOffset);
        PatchBranch(code, readFreeTagToFrameExtensionOffset, publicFrameOffset);
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x3F3E); // MOVEM.L D2-D7/A2-A6,-(A7), reversed save mask
        Append(code, MoveLongA7DisplacementToD7);
        Append(code, 0x002C); // requested byte count below the 44-byte frame

        // The original requested count remains below the frame for every
        // decline. Owned DISP and DIMS publishers consume their actual
        // transfer counts independently of that public fallback value.
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x0000);
        Append(code, BranchNotEqualWord);
        var nonDisplayToTransferReadyExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 48);
        Append(code, BranchLowerOrSameWord);
        var shortDisplayToTransferReadyExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, (ushort)(MoveQuickZeroD7 | 48));
        PatchBranch(code, nonDisplayToTransferReadyExtensionOffset, code.Count);
        PatchBranch(code, shortDisplayToTransferReadyExtensionOffset, code.Count);

        // Recompute the actual DIMS transfer after the original requested
        // count enters D7. Clamp before arithmetic, exactly as in the earlier
        // destination proof, without changing the selected ModeID in D0.
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x1000);
        Append(code, BranchNotEqualWord);
        var nonDimensionsToTransferReadyExtensionOffset = code.Count;
        Append(code, 0);
        AppendDimensionsTransferCount(code, 7);
        PatchBranch(code, nonDimensionsToTransferReadyExtensionOffset, code.Count);

        // DtagDisp sizes 18 through 55 own the complete big-endian NotAvailable
        // UWORD, the four Properties bytes, both Resolution.X bytes, and the
        // complete Resolution.Y, PixelSpeed, SpriteCount, PaletteRange, and
        // SpriteResolution point, pad bytes, component precision and reserved tail.
        // Route these requested sizes to a dedicated arm before any Name table
        // work.
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 0x0012);
        Append(code, BranchCarryWord);
        var displayPrefixBelowPayloadToHeaderSplitExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 0x0037);
        Append(code, BranchHighWord);
        var displayPrefixAbovePayloadToHeaderSplitExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x0000); // GraphicsDisplayDatabase.DtagDisp
        Append(code, BranchEqualWord);
        var displayShortToPayloadExtensionOffset = code.Count;
        Append(code, 0);

        var queryHeaderSizeSplitOffset = code.Count;
        PatchBranch(
            code,
            displayPrefixBelowPayloadToHeaderSplitExtensionOffset,
            queryHeaderSizeSplitOffset);
        PatchBranch(
            code,
            displayPrefixAbovePayloadToHeaderSplitExtensionOffset,
            queryHeaderSizeSplitOffset);

        // The resident-default MNTR pointer prefixes are byte-granular even
        // at odd destinations. Their exact span and the complete defaultMonitor
        // LONG were proved before the public frame, and A0 retains that single
        // field read. ViewPosition uses the owned runtime Point when explicitly
        // enabled, otherwise the captured boot Point.
        // Keep these requests away from both the DIMS scalar
        // capability read and the NAME payload table. Header-only queries and
        // full MNTR records keep their existing publishers and admission rules.
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x2000);
        Append(code, BranchNotEqualWord);
        var nonMonitorPrefixToSharedHeaderExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 0x0010);
        Append(code, BranchLowerOrSameWord);
        var monitorHeaderToSharedHeaderExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 0x0018);
        Append(code, BranchHighWord);
        var monitorFullToSharedHeaderExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveLongD0ToD2); // retain selected default ModeID
        var bootViewPosition = GraphicsMonitorViewPosition.BootDefault.WordPair;
        Append(code, MoveLongImmediateD0);
        Append(code, (ushort)(bootViewPosition >> 16));
        Append(code, (ushort)bootViewPosition);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 20);
        Append(code, BranchLowerOrSameWord);
        var monitorPointerOnlyToScratch = code.Count;
        Append(code, 0);
        AppendOwnedMonitorPoint(code, defaultMonitorNtsc);
        PatchBranch(code, monitorPointerOnlyToScratch, code.Count);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA0ToPreDecrementA7); // exact resident pointer, no dereference
        Append(code, (ushort)(MoveQuickZeroD0 | 9)); // MNTR Length
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveQuickThreeD0);
        Append(code, MoveLongD0ToPreDecrementA7);
        AppendQueryHeaderIdentity(code, defaultMonitorNtsc);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7); // selected StructID
        Append(code, MoveAddressA7ToA2);
        Append(code, MoveAddressA1ToA3);
        Append(code, 0x2807); // MOVE.L D7,D4: retain exact requested count across DBRA
        Append(code, SubQuickOneWordD7);
        var monitorPointerPrefixCopyLoopOffset = code.Count;
        Append(code, MoveByteA2PostIncrementToD0);
        Append(code, MoveByteD0ToA3PostIncrement);
        Append(code, DecrementBranchD7);
        var monitorPointerPrefixCopyLoopExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(
            code,
            monitorPointerPrefixCopyLoopExtensionOffset,
            monitorPointerPrefixCopyLoopOffset);
        Append(code, LoadEffectiveAddressA7Displacement);
        Append(code, 0x0018); // discard header, pointer and Point; total stack use76 bytes
        Append(code, MoveLongD4ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6
        Append(code, AddQuickFourLongA7); // discard staged request, preserve CCR
        Append(code, ReturnFromSubroutine);

        var sharedQueryHeaderOffset = code.Count;
        PatchBranch(code, nonMonitorPrefixToSharedHeaderExtensionOffset, sharedQueryHeaderOffset);
        PatchBranch(code, monitorHeaderToSharedHeaderExtensionOffset, sharedQueryHeaderOffset);
        PatchBranch(code, monitorFullToSharedHeaderExtensionOffset, sharedQueryHeaderOffset);

        // Every canonical mode shares the same sixteen-byte QueryHeader shape.
        // The membership pass leaves the resolved ModeID in D0 and D1 retains
        // the selected StructID, so one tag-aware byte-copy arm can publish an
        // exact NAME, DISP, DIMS or MNTR header without duplicating it 66 times
        // or changing the caller's A1.
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x1000);
        Append(code, BranchNotEqualWord);
        var nonDimsToHeaderSize = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 26);
        Append(code, BranchLowerOrSameWord);
        var dimsDepthToHeader = code.Count;
        Append(code, 0);
        PatchBranch(code, nonDimsToHeaderSize, code.Count);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 0x0010);
        Append(code, BranchHighWord);
        var largerNameToPayloadExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, dimsDepthToHeader, code.Count);
        Append(code, MoveLongD0ToD2); // retain resolved ModeID inside public frame
        // Build the scalar tail in reverse stack order. These are raster
        // allocation limits captured from the ROM, not nominal rectangles.
        Append(code, MoveLongImmediateD0);
        Append(code, 0x03F0); // MaxRasterWidth1008
        Append(code, 0x0400); // MaxRasterHeight1024
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, 0x3F3C); // MOVE.W #1,-(A7): MinRasterHeight
        Append(code, 1);
        Append(code, (ushort)(MoveQuickZeroD3 | 16));
        Append(code, BitTestImmediateD2);
        Append(code, 15);
        Append(code, (ushort)(BranchEqualShort | 2));
        Append(code, (ushort)(MoveQuickZeroD3 | 32));
        Append(code, BitTestImmediateD2);
        Append(code, 5);
        Append(code, (ushort)(BranchEqualShort | 2));
        Append(code, (ushort)(MoveQuickZeroD3 | 64));
        Append(code, 0x3F03); // MOVE.W D3,-(A7): MinRasterWidth
        Append(code, MoveQuickZeroD3);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 18);
        Append(code, BranchCarryWord);
        var noDepthWordToHeaderScratch = code.Count;
        Append(code, 0);
        // Only DIMS18..33 reaches this publisher with an eighteenth byte. Its
        // capability address was proved before entering the public frame.
        Append(code, (ushort)(MoveQuickZeroD3 | 5));
        Append(code, MoveLongD2ToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0);
        Append(code, 0x0C80);
        Append(code, (ushort)(BranchEqualShort | 2));
        Append(code, (ushort)(MoveQuickZeroD3 | 6));
        Append(code, BitTestImmediateD2);
        Append(code, 15);
        Append(code, (ushort)(BranchEqualShort | 2));
        Append(code, (ushort)(MoveQuickZeroD3 | 4));
        Append(code, BitTestImmediateD2);
        Append(code, 5);
        Append(code, (ushort)(BranchEqualShort | 2));
        Append(code, (ushort)(MoveQuickZeroD3 | 2));
        Append(code, MoveByteA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
        Append(code, AndImmediateLongD0);
        Append(code, 0);
        Append(code, 0x0C);
        Append(code, CompareImmediateByteD0);
        Append(code, 0x0C);
        Append(code, (ushort)(BranchNotEqualShort | 2));
        Append(code, (ushort)(MoveQuickZeroD3 | 8));
        PatchBranch(code, noDepthWordToHeaderScratch, code.Count);
        Append(code, 0x3F03); // MOVE.W D3,-(A7): depth after the QueryHeader
        Append(code, MoveQuickFiveD0);
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x0000); // verified DISP Length=4; NAME policy stays separate
        Append(code, (ushort)(BranchNotEqualShort | 0x0002));
        Append(code, (ushort)(MoveQuickZeroD0 | 4));
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x1000); // verified DIMS Length=8
        Append(code, (ushort)(BranchNotEqualShort | 0x0002));
        Append(code, (ushort)(MoveQuickZeroD0 | 8));
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x2000); // verified MNTR Length=9
        Append(code, (ushort)(BranchNotEqualShort | 0x0002));
        Append(code, (ushort)(MoveQuickZeroD0 | 9));
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveQuickThreeD0);
        Append(code, MoveLongD0ToPreDecrementA7);
        AppendQueryHeaderIdentity(code, defaultMonitorNtsc);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7); // selected StructID
        Append(code, MoveAddressA7ToA2);
        Append(code, MoveAddressA1ToA3);
        Append(code, 0x2807); // MOVE.L D7,D4: retain actual count across DBRA
        Append(code, SubQuickOneWordD7);
        var nameHeaderCopyLoopOffset = code.Count;
        Append(code, MoveByteA2PostIncrementToD0);
        Append(code, MoveByteD0ToA3PostIncrement);
        Append(code, DecrementBranchD7);
        var nameHeaderCopyLoopExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, nameHeaderCopyLoopExtensionOffset, nameHeaderCopyLoopOffset);
        Append(code, LoadEffectiveAddressA7Displacement);
        Append(code, 0x001A); // discard QueryHeader plus the five scalar words
        Append(code, MoveLongD4ToD0); // return actual bytes, not an incomplete Rectangle tail
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6
        Append(code, AddQuickFourLongA7); // discard staged requested size, preserve CCR
        Append(code, ReturnFromSubroutine);

        var displayShortPayloadOffset = code.Count;
        PatchBranch(
            code,
            displayShortToPayloadExtensionOffset,
            displayShortPayloadOffset);

        // NotAvailable defaults to zero and the second Properties byte defaults
        // to DIPF_IS_DBUFFER. Ordinary N=18/19 modes take those defaults without
        // touching A6. SuperHires N=18/19 and every N=20 through N=55 mode reach
        // this arm only after the exact one-byte A6 envelope was admitted. Read
        // that byte once and reuse it for both SuperHires availability and the
        // N=20 through N=55 DIPF_IS_AA flag when both AA components are resident.
        Append(code, MoveQuickZeroD5);
        Append(code, (ushort)(MoveQuickZeroD4 | 16)); // DIPF_IS_DBUFFER byte
        // The third Properties byte is capability-invariant: every mode has
        // DIPF_IS_WB, ordinary modes also have DIPF_IS_SPRITES_ATT, EHB adds
        // DIPF_IS_EXTRAHALFBRITE, and SuperHires replaces SPRITES_ATT with the
        // low-byte DIPF_IS_ECS flag. Canonical EHB and SuperHires never overlap.
        Append(code, (ushort)(MoveQuickZeroD3 | 1));
        Append(code, BitTestImmediateD0);
        Append(code, 5); // GraphicsModeIds.SuperHiresMode
        Append(code, BranchNotEqualWord);
        var superHiresDisplayPropertiesReadyExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, (ushort)(MoveQuickZeroD3 | 0x21));
        Append(code, BitTestImmediateD0);
        Append(code, 7); // GraphicsModeIds.ExtraHalfBriteMode
        Append(code, BranchEqualWord);
        var ordinaryDisplayPropertiesReadyExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, (ushort)(MoveQuickZeroD3 | 0x31));

        var displayPropertiesReadyOffset = code.Count;
        PatchBranch(
            code,
            superHiresDisplayPropertiesReadyExtensionOffset,
            displayPropertiesReadyOffset);
        PatchBranch(
            code,
            ordinaryDisplayPropertiesReadyExtensionOffset,
            displayPropertiesReadyOffset);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 0x0013);
        Append(code, BranchHighWord);
        var displayLaterToCapabilityReadExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 5); // GraphicsModeIds.SuperHiresMode
        Append(code, BranchEqualWord);
        var ordinaryDisplayAvailabilityReadyExtensionOffset = code.Count;
        Append(code, 0);

        var displayShortCapabilityReadOffset = code.Count;
        PatchBranch(
            code,
            displayLaterToCapabilityReadExtensionOffset,
            displayShortCapabilityReadOffset);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA6DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
        Append(code, BitTestImmediateD0);
        Append(code, 5); // GraphicsModeIds.SuperHiresMode
        Append(code, BranchEqualWord);
        var ordinaryDisplayLaterToPropertiesExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickOneD5); // DI_AVAIL_NO_CHIPS
        Append(code, BitTestImmediateD6);
        Append(code, 0); // GraphicsChipRevision.HrAgnus
        Append(code, BranchEqualWord);
        var missingEcsAgnusToPropertiesExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD6);
        Append(code, 1); // GraphicsChipRevision.HrDenise
        Append(code, BranchEqualWord);
        var missingEcsDeniseToPropertiesExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD5);

        var displayShortPropertiesOffset = code.Count;
        PatchBranch(
            code,
            ordinaryDisplayLaterToPropertiesExtensionOffset,
            displayShortPropertiesOffset);
        PatchBranch(
            code,
            missingEcsAgnusToPropertiesExtensionOffset,
            displayShortPropertiesOffset);
        PatchBranch(
            code,
            missingEcsDeniseToPropertiesExtensionOffset,
            displayShortPropertiesOffset);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 0x0014);
        Append(code, BranchCarryWord);
        var earlierDisplayAvailabilityReadyExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD6);
        Append(code, 2); // GraphicsChipRevision.AaAlice
        Append(code, BranchEqualWord);
        var missingAaAliceAvailabilityReadyExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD6);
        Append(code, 3); // GraphicsChipRevision.AaLisa
        Append(code, BranchEqualWord);
        var missingAaLisaAvailabilityReadyExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, (ushort)(MoveQuickZeroD4 | 17)); // add DIPF_IS_AA

        var displayAvailabilityReadyOffset = code.Count;
        PatchBranch(
            code,
            ordinaryDisplayAvailabilityReadyExtensionOffset,
            displayAvailabilityReadyOffset);
        PatchBranch(
            code,
            earlierDisplayAvailabilityReadyExtensionOffset,
            displayAvailabilityReadyOffset);
        PatchBranch(
            code,
            missingAaAliceAvailabilityReadyExtensionOffset,
            displayAvailabilityReadyOffset);
        PatchBranch(
            code,
            missingAaLisaAvailabilityReadyExtensionOffset,
            displayAvailabilityReadyOffset);

        // Build the tag-aware header on its existing aligned scratch, then use
        // byte stores for NotAvailable so odd guest destinations remain valid.
        Append(code, MoveLongD0ToD2); // retain resolved ModeID inside public frame
        Append(code, (ushort)(MoveQuickZeroD0 | 4)); // DISP Length
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveQuickThreeD0);
        Append(code, MoveLongD0ToPreDecrementA7);
        AppendQueryHeaderIdentity(code, defaultMonitorNtsc);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7); // selected StructID
        Append(code, MoveAddressA7ToA2);
        Append(code, MoveAddressA1ToA3);
        Append(code, (ushort)(MoveQuickZeroD6 | 15));

        var displayShortHeaderCopyLoopOffset = code.Count;
        Append(code, MoveByteA2PostIncrementToD0);
        Append(code, MoveByteD0ToA3PostIncrement);
        Append(code, DecrementBranchD6);
        var displayShortHeaderCopyLoopExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(
            code,
            displayShortHeaderCopyLoopExtensionOffset,
            displayShortHeaderCopyLoopOffset);
        Append(code, LoadEffectiveAddressA7Displacement);
        Append(code, 0x0010); // discard the sixteen-byte QueryHeader scratch
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteD0ToA3PostIncrement); // NotAvailable high byte
        Append(code, MoveByteD5ToA1Displacement);
        Append(code, 0x0011); // NotAvailable low byte
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 0x0012);
        Append(code, BranchEqualWord);
        var displayEighteenToResultExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, 0x0012); // invariant high Properties byte at N=19
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 0x0013);
        Append(code, BranchEqualWord);
        var displayNineteenToResultExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteD4ToA1Displacement);
        Append(code, 0x0013); // DIPF_IS_DBUFFER plus optional DIPF_IS_AA
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 0x0014);
        Append(code, BranchEqualWord);
        var displayTwentyToResultExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteD3ToA1Displacement);
        Append(code, 0x0014); // WB plus SPRITES_ATT/EHB, or SuperHires WB alone
        // N=21 through N=55 are the only sizes still live here. Subtracting
        // 21 sends N=21 to the common result and leaves one through twenty in D7
        // for the N=22 through N=55 shared byte-21 path. Every possible
        // byte-20 value has low bits 01; six ADDX byte shifts therefore discard
        // its remaining flags, retain the invariant SPRITES bit at bit 6, and
        // inject the PAL, SuperHires, HAM, PF2, dual-playfield, and lace ModeID
        // bits in their exact big-endian byte-21 positions. The preceding shift
        // in each lane supplies X, so this needs no table or conditional branch.
        Append(code, SubtractImmediateByteD7);
        Append(code, 0x0015);
        Append(code, BranchEqualWord);
        var displayTwentyOneToResultExtensionOffset = code.Count;
        Append(code, 0);
        // Keep D0's known zero for the stores introduced at N=23/25/27/29/33/35;
        // D5 is dead after NotAvailable has been published and is an equivalent
        // scratch lane for the byte-21 synthesis.
        Append(code, MoveLongD2ToD5);
        Append(code, SwapD5);
        // PAL boot: default/PAL iff !monitor bit0. NTSC boot: PAL iff
        // monitor bit1. Both sequences preserve the original low ModeID word
        // in D5's upper half and leave the same byte-sized scratch footprint.
        Append(code, defaultMonitorNtsc ? ShiftRightByteD5 : NotByteD5);
        Append(code, ShiftRightByteD5);
        Append(code, AddExtendByteD3ToD3);
        Append(code, ShiftRightLongD2Count6); // X = SuperHires bit 5
        Append(code, AddExtendByteD3ToD3);
        Append(code, ShiftRightLongD2Count6); // X = HAM bit 11
        Append(code, AddExtendByteD3ToD3);
        Append(code, SwapD5);
        Append(code, MoveWordD5ToD6); // recover the original low ModeID word
        Append(code, ShiftRightLongD5Count7); // X = PF2 bit 6
        Append(code, AddExtendByteD3ToD3);
        Append(code, ShiftRightLongD5Count4); // X = dual-playfield bit 10
        Append(code, AddExtendByteD3ToD3);
        Append(code, ShiftRightWordD6Count3); // X = lace bit 2; preserve D4 AA marker
        Append(code, AddExtendByteD3ToD3);
        Append(code, MoveByteD3ToA1Displacement);
        Append(code, 0x0015); // SPRITES, monitor family, and ModeID feature flags
        // D7 is one through thirty-four for N=22 through N=55. The first decrement
        // returns N=22; the preserved zero in D0 then publishes Resolution.X
        // high for every larger prefix, and the second decrement returns N=23.
        // N=24 through N=55 reach the classifier with D7=1 through 32 while scratch
        // D6 carries the Resolution.X value. ROR.B exposes SuperHires
        // then Hires through C while preserving X; the two ADD.B operations
        // cannot carry. The next decrement returns N=24, while N=25 through
        // N=55 publish the invariant-
        // zero high Resolution.Y byte. One more decrement returns N=25;
        // N=26 through N=55 then write the invariant-one low byte directly
        // without consuming D0 or D7. A fifth decrement returns N=26;
        // N=27 through N=55 use the preserved zero for PixelSpeed's high byte.
        // The sixth decrement returns N=27, while N=28 through N=55 multiply the
        // preserved 1/2/4 classifier by 35 to publish PixelSpeed's low byte.
        // The seventh decrement returns N=28; N=29 through N=55 write
        // SpriteCount's invariant-zero high byte. The eighth decrement returns
        // N=29; N=30 through N=55 write SpriteCount's invariant-eight low byte.
        // The ninth decrement returns N=30. N=31 through N=55 normalize D4's AA bit
        // to 00/FF, then use the rotated D3 SuperHires/lace bits to add 0x10
        // for every non-AA mode except progressive SuperHires. Both seven-bit
        // shifts finish with X=0. The tenth decrement returns N=31 through a
        // centered BRA.W bridge. N=32 through N=55 rotate 00/10/FF to 00/40/FF, leave AA's
        // FF unchanged, and toggle the two non-AA values with EORI.B #$40 to
        // publish PaletteRange's low byte as 40/00/FF. The eleventh decrement
        // returns N=32; N=33 through N=55 then use D0's retained zero for
        // SpriteResolution.X's invariant high byte. The twelfth decrement returns
        // N=33. N=34 through N=55 seed framed D6 with two; D3's negative SuperHires
        // marker skips a safe doubling to select two rather than four without
        // consuming D7. The thirteenth decrement returns N=34; N=35 through N=55 use
        // D0's retained zero for SpriteResolution.Y's high byte. The fourteenth
        // decrement returns N=35; N=36 through N=55 write the invariant-one low
        // byte directly. The fifteenth decrement returns N=36; N=37 through N=55 write
        // the first internally-used pad byte from D0's retained zero. The
        // sixteenth decrement returns N=37, then N=38 through N=55 write the second
        // pad byte. The seventeenth decrement returns N=38 through BEQ.W;
        // N=39 through N=55 write the third pad byte. The eighteenth decrement
        // returns N=39 through BEQ.W, then N=40 through N=55 write the fourth pad byte.
        // The nineteenth decrement returns N=40; N=41 through N=55 select RedBits in D6.
        // The twentieth/twenty-first decrements return N=41/N=42; larger prefixes
        // reuse D6 for GreenBits/BlueBits, respectively, without new memory reads.
        // All partial-prefix returns retain X=0.
        // The centered result bridge keeps the new N=36 branch at -120 in this
        // fixed 272-byte tail; the N=37 branch reaches exactly -128.
        // The N=38 return uses a patched word branch directly to the result,
        // keeping further extensions independent of the short-branch limit.
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchEqualShort | 0x0038)); // N=22 -> bridge
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, 0x0016);
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchEqualShort | 0x0030)); // N=23 -> bridge
        Append(code, MoveQuickOneD6);
        Append(code, RotateRightByteD3Count5); // C = SuperHires bit
        Append(code, (ushort)(BranchCarryShort | 0x0008)); // value 1 -> store
        Append(code, AddByteD6ToD6); // value 2
        Append(code, RotateRightByteD2Count4); // C = original ModeID Hires bit
        Append(code, (ushort)(BranchCarryShort | 0x0002)); // value 2 -> store
        Append(code, AddByteD6ToD6); // value 4 (lores)
        Append(code, MoveByteD6ToA1Displacement);
        Append(code, 0x0017);
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchEqualShort | 0x001A)); // N=24 -> bridge
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, 0x0018);
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchEqualShort | 0x0012)); // N=25 -> bridge
        Append(code, MoveByteImmediateToA1Displacement);
        Append(code, 0x0001);
        Append(code, 0x0019);
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchEqualShort | 0x0008)); // N=26 -> bridge
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, 0x001A);
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchNotEqualShort | 0x0004)); // N>27 skips bridge
        Append(code, BranchAlwaysWord); // N=27 -> common result
        var displayShortResultBridgeExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MultiplyUnsignedWordImmediateToD6);
        Append(code, 0x0023); // 35 colour clocks per SuperHires pixel
        Append(code, MoveByteD6ToA1Displacement);
        Append(code, 0x001B);
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchEqualShort | 0x00F0)); // N=28 -> bridge
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, 0x001C); // invariant high SpriteCount byte traversed by N=29 through N=55
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchEqualShort | 0x00E8)); // N=29 -> bridge
        Append(code, MoveByteImmediateToA1Displacement);
        Append(code, 0x0008);
        Append(code, 0x001D); // invariant low SpriteCount byte introduced at N=30, traversed through N=55
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchEqualShort | 0x00DE)); // N=30 -> bridge
        Append(code, ShiftLeftByteD4Count7); // 0x10/0x11 -> 0x00/0x80, X=0
        Append(code, ShiftRightArithmeticByteD4Count7); // 0x00/0x80 -> 0x00/0xFF, X=0
        Append(code, BitTestImmediateD3);
        Append(code, 0x0007); // rotated Properties SuperHires bit
        Append(code, (ushort)(BranchEqualShort | 0x0006)); // non-SuperHires -> add 0x10
        Append(code, BitTestImmediateD3);
        Append(code, 0x0003); // rotated Properties lace bit
        Append(code, (ushort)(BranchEqualShort | 0x0004)); // progressive SuperHires -> store
        Append(code, OrImmediateByteD4);
        Append(code, 0x0010);
        Append(code, MoveByteD4ToA1Displacement);
        Append(code, 0x001E);
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchEqualShort | 0x00C2)); // N=31 -> bridge
        Append(code, RotateLeftByteD4Count2); // 00/10/FF -> 00/40/FF
        Append(code, (ushort)(BranchMinusShort | 0x0004)); // AA keeps FF
        Append(code, ExclusiveOrImmediateByteD4);
        Append(code, 0x0040); // non-AA: 00/40 -> 40/00
        Append(code, MoveByteD4ToA1Displacement);
        Append(code, 0x001F);
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchEqualShort | 0x00B2)); // N=32 -> bridge
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, 0x0020); // invariant high SpriteResolution byte at N=33
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchEqualShort | 0x00AA)); // N=33 -> bridge
        Append(code, MoveQuickTwoD6);
        Append(code, TestByteD3); // N = rotated Properties SuperHires bit
        Append(code, (ushort)(BranchMinusShort | 0x0002)); // SuperHires skips first double
        Append(code, AddByteD6ToD6); // ordinary modes select four
        Append(code, MoveByteD6ToA1Displacement); // SuperHires retains two
        Append(code, 0x0021);
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchEqualShort | 0x009A)); // N=34 -> bridge
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, 0x0022); // invariant high SpriteResolution.Y byte at N=35
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchEqualShort | 0x0092)); // N=35 -> bridge
        Append(code, MoveByteImmediateToA1Displacement);
        Append(code, 0x0001);
        Append(code, 0x0023); // invariant low SpriteResolution.Y byte at N=36
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchEqualShort | 0x0088)); // N=36 -> bridge
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, 0x0024); // invariant first internally-used pad byte at N=37
        Append(code, SubQuickOneWordD7);
        Append(code, (ushort)(BranchEqualShort | 0x0080)); // N=37 -> bridge, -128
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, 0x0025); // invariant second internally-used pad byte at N=38
        Append(code, SubQuickOneWordD7);
        Append(code, BranchEqualWord); // N=38 -> result beyond short-branch reach
        var displayThirtyEightToResultExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, 0x0026); // invariant third internally-used pad byte at N=39
        Append(code, SubQuickOneWordD7);
        Append(code, BranchEqualWord); // N=39 -> shared result
        var displayThirtyNineToResultExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, 0x0027); // invariant fourth internally-used pad byte at N=40

        Append(code, SubQuickOneWordD7);
        Append(code, BranchEqualWord); // N=40 -> shared result
        var displayFortyToResultExtensionOffset = code.Count;
        Append(code, 0);
        // D4 retains PaletteRange's low byte: FF for AA, 40 for non-AA
        // progressive SuperHires, otherwise 00. Select RedBits without another
        // capability/output read. Framed D6 remains available to N42/N43.
        // SUBQ above leaves X=0; MOVEQ, TST, branches and MOVE preserve it.
        Append(code, MoveQuickFourD6);
        Append(code, TestByteD4);
        Append(code, (ushort)(BranchMinusShort | 0x0006)); // FF -> eight
        Append(code, (ushort)(BranchEqualShort | 0x0006)); // 00 -> store four
        Append(code, MoveQuickTwoD6); // 40 -> two
        Append(code, (ushort)(BranchAlwaysShort | 0x0002)); // -> store two
        Append(code, MoveQuickEightD6);
        Append(code, MoveByteD6ToA1Displacement);
        Append(code, 0x0028); // mode/profile-dependent RedBits at N=41

        Append(code, SubQuickOneWordD7);
        Append(code, BranchEqualWord); // N=41 -> shared result
        var displayFortyOneToResultExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteD6ToA1Displacement);
        Append(code, 0x0029); // GreenBits reuses retained component precision at N=42

        Append(code, SubQuickOneWordD7);
        Append(code, BranchEqualWord); // N=42 -> shared result
        var displayFortyTwoToResultExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteD6ToA1Displacement);
        Append(code, 0x002A); // BlueBits reuses retained component precision at N=43

        // N=43 still has D7=1; larger admitted prefixes have D7=N-42.
        // The guard leaves N-43 zero bytes to publish, bounded to 1..12.
        // A3 and D7 are framed scratch. Byte stores allow odd destinations;
        // the complete span was validated before the first header write.
        Append(code, SubQuickOneWordD7);
        Append(code, BranchEqualWord); // N=43 -> shared result without a tail write
        var displayFortyThreeToResultExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, LoadEffectiveAddressA1DisplacementToA3);
        Append(code, 0x002B);
        Append(code, MoveByteD0ToA3PostIncrement); // retained zero, no destination read
        Append(code, SubQuickOneWordD7); // final 1 -> 0 is non-borrowing: X=0
        Append(code, (ushort)(BranchNotEqualShort | 0x00FA)); // -6 -> zero store

        var displayShortResultOffset = code.Count;
        PatchBranch(code, displayFortyThreeToResultExtensionOffset, displayShortResultOffset);
        PatchBranch(code, displayFortyTwoToResultExtensionOffset, displayShortResultOffset);
        PatchBranch(code, displayFortyOneToResultExtensionOffset, displayShortResultOffset);
        PatchBranch(code, displayFortyToResultExtensionOffset, displayShortResultOffset);
        PatchBranch(code, displayThirtyNineToResultExtensionOffset, displayShortResultOffset);
        PatchBranch(code, displayThirtyEightToResultExtensionOffset, displayShortResultOffset);
        PatchBranch(
            code,
            displayShortResultBridgeExtensionOffset,
            displayShortResultOffset);
        PatchBranch(
            code,
            displayEighteenToResultExtensionOffset,
            displayShortResultOffset);
        PatchBranch(
            code,
            displayNineteenToResultExtensionOffset,
            displayShortResultOffset);
        PatchBranch(
            code,
            displayTwentyToResultExtensionOffset,
            displayShortResultOffset);
        PatchBranch(
            code,
            displayTwentyOneToResultExtensionOffset,
            displayShortResultOffset);
        Append(code, MoveLongA7DisplacementToD0);
        Append(code, 0x002C); // return requested size below the public frame
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 48);
        Append(code, BranchLowerOrSameWord);
        var displayCountReadyExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, (ushort)(MoveQuickZeroD0 | 48));
        PatchBranch(code, displayCountReadyExtensionOffset, code.Count);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6
        Append(code, AddQuickFourLongA7); // discard staged requested size, preserve CCR
        Append(code, ReturnFromSubroutine);

        // Keep the mode-specific Name[32] plus eight reserved bytes as a
        // relocation-free PC-relative table. QueryHeader-only and eighteen-
        // through fifty-five-byte DisplayInfo calls return before these bytes,
        // while every larger call branches across them.
        // A fixed 44-byte row avoids 66 distant payload branches and preserves
        // the existing 68-byte maximum active stack depth.
        var nameTailTableOffset = code.Count;
        foreach (var modeId in modeIds)
        {
            Append(code, (ushort)(modeId >> 16));
            Append(code, (ushort)modeId);

            var nameTail = new byte[40];
            var name = BuildNativeDisplayName(modeId, defaultMonitorNtsc);
            var nameLength = Math.Min(31, name.Length);
            for (var index = 0; index < nameLength; index++)
                nameTail[index] = (byte)name[index];
            for (var index = 0; index < nameTail.Length; index += 2)
            {
                Append(
                    code,
                    (ushort)((nameTail[index] << 8) | nameTail[index + 1]));
            }
        }

        var namePayloadEntryOffset = code.Count;
        PatchBranch(
            code,
            largerNameToPayloadExtensionOffset,
            namePayloadEntryOffset);

        // Partial DIMS records reuse the verified per-mode serializer below,
        // including counts34/42/50 that would otherwise enter the NAME tail
        // table. Only NAME and the DISP17 seam own that partial-payload arm.
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x1000);
        Append(code, BranchEqualWord);
        var dimensionsPayloadToModeDispatchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 0x0037);
        Append(code, BranchHighWord);
        var fullRecordToModeDispatchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveLongD0ToD2); // retain resolved ModeID inside public frame
        Append(code, LoadEffectiveAddressPcDisplacementToA2);
        var nameTailTableExtensionOffset = code.Count;
        var nameTailTableDisplacement = checked(
            nameTailTableOffset - nameTailTableExtensionOffset);
        if (nameTailTableDisplacement < short.MinValue ||
            nameTailTableDisplacement > short.MaxValue)
        {
            throw new InvalidOperationException(
                $"Native graphics name table is out of PC-relative range (extension {nameTailTableExtensionOffset}, table {nameTailTableOffset}, displacement {nameTailTableDisplacement}).");
        }
        Append(code, unchecked((ushort)nameTailTableDisplacement));
        Append(code, (ushort)(MoveQuickZeroD6 | 65)); // sixty-six fixed-stride rows

        var nameTailSearchLoopOffset = code.Count;
        Append(code, CompareLongA2IndirectToD2);
        Append(code, BranchEqualWord);
        var nameTailFoundExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, LoadEffectiveAddressA2Displacement);
        Append(code, 0x002C); // next 44-byte mode/tail row
        Append(code, DecrementBranchD6);
        var nameTailSearchLoopExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(
            code,
            nameTailSearchLoopExtensionOffset,
            nameTailSearchLoopOffset);

        // Membership and this table share one mode list, so exhaustion is an
        // internal consistency guard. Preserve the public frame and destination
        // transactionally even if construction is ever changed inconsistently.
        Append(code, MoveLongA7DisplacementToD0);
        Append(code, 0x002C); // restore requested size below the public frame
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6
        Append(code, AddQuickFourLongA7); // discard staged requested size, preserve CCR
        Append(code, ReturnFromSubroutine);

        var nameTailFoundOffset = code.Count;
        PatchBranch(code, nameTailFoundExtensionOffset, nameTailFoundOffset);
        Append(code, LoadEffectiveAddressA2Displacement);
        Append(code, 0x0004); // skip the row's ModeID
        Append(code, MoveAddressA2ToA4); // retain tail while A2 addresses scratch

        // Construct the tag-selected QueryHeader on an aligned stack, then
        // byte-copy it so odd guest destinations remain valid. A3 is a private
        // cursor; the caller's public A1 is restored from the frame unchanged.
        Append(code, MoveQuickFiveD0);
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x0000); // DISP17 also uses this prefix-copy arm
        Append(code, (ushort)(BranchNotEqualShort | 0x0002));
        Append(code, (ushort)(MoveQuickZeroD0 | 4));
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveQuickThreeD0);
        Append(code, MoveLongD0ToPreDecrementA7);
        AppendQueryHeaderIdentity(code, defaultMonitorNtsc);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7); // selected StructID
        Append(code, MoveAddressA7ToA2);
        Append(code, MoveAddressA1ToA3);
        Append(code, (ushort)(MoveQuickZeroD6 | 15));

        var namePayloadHeaderCopyLoopOffset = code.Count;
        Append(code, MoveByteA2PostIncrementToD0);
        Append(code, MoveByteD0ToA3PostIncrement);
        Append(code, DecrementBranchD6);
        var namePayloadHeaderCopyLoopExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(
            code,
            namePayloadHeaderCopyLoopExtensionOffset,
            namePayloadHeaderCopyLoopOffset);
        Append(code, LoadEffectiveAddressA7Displacement);
        Append(code, 0x0010); // discard the sixteen-byte QueryHeader scratch

        // Copy N-17 table bytes after the header, then force byte N-1 to zero.
        // This reproduces the portable clipped NameInfo contract for sizes
        // 17..55 and publishes the invariant DISP byte at N=17 without touching
        // byte N. The zero remainder branches before any name-tail read.
        Append(code, MoveAddressA4ToA2);
        Append(code, MoveWordD7ToD6);
        Append(code, (ushort)(MoveQuickZeroD5 | 17));
        Append(code, SubWordD5ToD6);
        Append(code, BranchEqualWord);
        var namePayloadForceNulExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, SubQuickOneWordD6);

        var namePayloadTailCopyLoopOffset = code.Count;
        Append(code, MoveByteA2PostIncrementToD0);
        Append(code, MoveByteD0ToA3PostIncrement);
        Append(code, DecrementBranchD6);
        var namePayloadTailCopyLoopExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(
            code,
            namePayloadTailCopyLoopExtensionOffset,
            namePayloadTailCopyLoopOffset);

        var namePayloadForceNulOffset = code.Count;
        PatchBranch(
            code,
            namePayloadForceNulExtensionOffset,
            namePayloadForceNulOffset);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteD0ToA3PostIncrement);
        Append(code, MoveLongA7DisplacementToD0);
        Append(code, 0x002C); // return requested size below the public frame
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6
        Append(code, AddQuickFourLongA7); // discard staged requested size, preserve CCR
        Append(code, ReturnFromSubroutine);

        var modeDispatchOffset = code.Count;
        PatchBranch(code, fullRecordToModeDispatchExtensionOffset, modeDispatchOffset);
        PatchBranch(code, dimensionsPayloadToModeDispatchExtensionOffset, modeDispatchOffset);
        PatchBranch(code, foreignModeToModeDispatchExtensionOffset, modeDispatchOffset);
        foreach (var branchExtensionOffset in capabilityFailureBranchExtensionOffsets)
            PatchBranch(code, branchExtensionOffset, capabilityFailureOffset);

        foreach (var modeId in modeIds)
        {
            Append(code, CompareImmediateLongD0);
            Append(code, (ushort)(modeId >> 16));
            Append(code, (ushort)modeId);
            Append(code, BranchNotEqualWord);
            var modeSkipExtensionOffset = code.Count;
            Append(code, 0);
            var displayRecord = BuildNativeDisplayInfoRecord(modeId, defaultMonitorNtsc);
            var dimensionsRecord = BuildNativeDisplayDimensionsRecord(modeId, defaultMonitorNtsc);
            var headerModeId = (modeId & 0xFFFF1000u) == 0
                ? modeId | defaultMonitor : modeId;
            var name = BuildNativeDisplayName(modeId, defaultMonitorNtsc);
            var recordReturnBranchExtensionOffsets = new List<int>(3);

            Append(code, CompareImmediateLongD1);
            Append(code, 0x8000);
            Append(code, 0x2000); // GraphicsDisplayDatabase.DtagMntr
            Append(code, BranchEqualWord);
            var monitorBranchExtensionOffset = code.Count;
            Append(code, 0);

            Append(code, CompareImmediateLongD1);
            Append(code, 0x8000);
            Append(code, 0x1000); // GraphicsDisplayDatabase.DtagDims
            Append(code, BranchEqualWord);
            var dimensionsBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateLongD1);
            Append(code, 0x8000);
            Append(code, 0x3000); // GraphicsDisplayDatabase.DtagName
            Append(code, BranchEqualWord);
            var nameBranchExtensionOffset = code.Count;
            Append(code, 0);

            AppendMoveLongToA1(code, 0x00, GraphicsDisplayDatabase.DtagDisp);
            AppendMoveLongToA1(code, 0x04, headerModeId);
            AppendMoveLongToA1(code, 0x08, 3);
            AppendMoveLongToA1(code, 0x0C, 4);
            AppendMoveWordToA1(code, 0x10, displayRecord.ModeNotAvailable);
            AppendEcsDisplayInfoAvailability(code, modeId);
            AppendMoveLongToA1(code, 0x12, displayRecord.Properties);
            AppendMoveWordToA1(code, 0x16, displayRecord.HorizontalTicksPerPixel);
            AppendMoveWordToA1(code, 0x18, 1);
            AppendMoveWordToA1(code, 0x1A, displayRecord.PixelSpeed);
            AppendMoveWordToA1(code, 0x1C, displayRecord.SpriteCount);
            AppendMoveWordToA1(code, 0x1E, displayRecord.PaletteRange);
            AppendMoveWordToA1(code, 0x20, displayRecord.SpriteResolution);
            AppendMoveWordToA1(code, 0x22, 1);
            // Clear the padding/reserved tail before publishing the three
            // component-bit bytes at 0x28..0x2A.  Callers may recycle a
            // buffer, so leaving stale bytes in the QueryHeader payload is
            // observable and is not Kickstart-compatible.
            foreach (var clearOffset in new[] { 0x24, 0x28, 0x2C, 0x30, 0x34 })
                AppendMoveLongToA1(code, clearOffset, 0);
            AppendMoveByteToA1(code, 0x28, displayRecord.ComponentBits);
            AppendMoveByteToA1(code, 0x29, displayRecord.ComponentBits);
            AppendMoveByteToA1(code, 0x2A, displayRecord.ComponentBits);
            AppendAgaDisplayInfoOverrides(code, displayRecord.Properties);

            Append(code, MoveLongImmediateD0);
            Append(code, 0);
            Append(code, 0x0038);
            Append(code, BranchAlwaysWord);
            recordReturnBranchExtensionOffsets.Add(code.Count);
            Append(code, 0);

            var nameOffset = code.Count;
            PatchBranch(code, nameBranchExtensionOffset, nameOffset);
            AppendMoveLongToA1(code, 0x00, GraphicsDisplayDatabase.DtagName);
            AppendMoveLongToA1(code, 0x04, modeId);
            AppendMoveLongToA1(code, 0x08, 3);
            AppendMoveLongToA1(code, 0x0C, 5);
            for (var clearOffset = 0x10; clearOffset <= 0x34; clearOffset += 4)
                AppendMoveLongToA1(code, clearOffset, 0);
            AppendNativeDisplayName(code, name);
            Append(code, MoveLongImmediateD0);
            Append(code, 0);
            Append(code, 0x0038);
            Append(code, BranchAlwaysWord);
            recordReturnBranchExtensionOffsets.Add(code.Count);
            Append(code, 0);

            var dimensionsOffset = code.Count;
            PatchBranch(code, dimensionsBranchExtensionOffset, dimensionsOffset);
            // The verified serializer uses aligned WORD/LONG stores. Keep
            // those stores private, then publish only the admitted bytes to
            // the original destination. The native call's
            // maximum frame is118 bytes: return4 + staged count4 + MOVEM44
            // + this even-sized66-byte scratch; no extra pointer is stacked.
            Append(code, MoveAddressA1ToA3);
            Append(code, LoadEffectiveAddressA7Displacement);
            Append(code, unchecked((ushort)-66));
            Append(code, 0x224F); // MOVEA.L A7,A1: aligned scratch destination
            AppendMoveLongToA1(code, 0x00, GraphicsDisplayDatabase.DtagDims);
            AppendMoveLongToA1(code, 0x04, headerModeId);
            AppendMoveLongToA1(code, 0x08, 3);
            AppendMoveLongToA1(code, 0x0C, 8);
            foreach (var clearOffset in new[]
            {
                0x10, 0x14, 0x18, 0x1C, 0x20, 0x24, 0x28, 0x2C, 0x30,
                0x34, 0x38, 0x3C
            })
            {
                AppendMoveLongToA1(code, clearOffset, 0);
            }

            AppendMoveWordToA1(code, 0x10, dimensionsRecord.Depth);
            AppendAgaDimensionsOverrides(code);
            // Min/MaxRaster fields are allocation limits, not the rectangles
            // below. Match the independently captured OCS/ECS ROM scalars.
            AppendMoveWordToA1(code, 0x12, (modeId & GraphicsModeIds.SuperHiresMode) != 0
                ? (ushort)64 : (modeId & GraphicsModeIds.HiresMode) != 0 ? (ushort)32 : (ushort)16);
            AppendMoveWordToA1(code, 0x14, 1);
            AppendMoveWordToA1(code, 0x16, 1008);
            AppendMoveWordToA1(code, 0x18, 1024);
            AppendDimensionsRectangle(code, 0x1A, dimensionsRecord.Width, dimensionsRecord.Height);
            AppendNativeOverscanRectangle(code, 0x22, modeId, defaultMonitorNtsc, video: false);
            AppendNativeOverscanRectangle(code, 0x2A, modeId, defaultMonitorNtsc, video: true);
            AppendDimensionsRectangle(code, 0x32, dimensionsRecord.Width, dimensionsRecord.Height);
            AppendDimensionsRectangle(code, 0x3A, dimensionsRecord.Width, dimensionsRecord.Height);

            Append(code, MoveAddressA7ToA2);
            Append(code, MoveAddressA3ToA1); // restore exact public destination before copying
            Append(code, 0x2807); // MOVE.L D7,D4: actual transfer count survives DBRA
            Append(code, SubQuickOneWordD7);
            var dimensionsCopyLoopOffset = code.Count;
            Append(code, MoveByteA2PostIncrementToD0);
            Append(code, MoveByteD0ToA3PostIncrement);
            Append(code, DecrementBranchD7);
            var dimensionsCopyLoopExtensionOffset = code.Count;
            Append(code, 0);
            PatchBranch(code, dimensionsCopyLoopExtensionOffset, dimensionsCopyLoopOffset);
            Append(code, LoadEffectiveAddressA7Displacement);
            Append(code, 66); // restore the existing public MOVEM frame
            Append(code, MoveLongD4ToD0);
            Append(code, BranchAlwaysWord);
            recordReturnBranchExtensionOffsets.Add(code.Count);
            Append(code, 0);

            if (modeId == GraphicsModeIds.DefaultMonitor)
            {
                var monitorOffset = code.Count;
                PatchBranch(code, monitorBranchExtensionOffset, monitorOffset);

                AppendOwnedMonitorPoint(code, defaultMonitorNtsc, includeOriginal: true);
                Append(code, 0x2C00); // MOVE.L D0,D6: retain Point before overlapping writes

                // The exact resident pointer was retained in volatile A0 by
                // the pre-D7 DefaultMonitor admission above.
                Append(code, MoveLongA0ToA1Displacement);
                Append(code, 0x0010);

                // Emit the same ROM-qualified family bytes as the host image.
                // Dynamic pointer/Points remain snapshotted guest values; this
                // does not broaden the existing default-only payload admission.
                var monitorImage = GraphicsMonitorInfoImage.Create(!defaultMonitorNtsc, 0,
                    GraphicsMonitorViewPosition.BootDefault, GraphicsMonitorViewPosition.BootDefault);
                for (var fieldOffset = 0; fieldOffset < GraphicsMonitorInfoImage.TransferSize; fieldOffset += 4)
                {
                    if (fieldOffset is 0x10 or 0x14 or 0x50) continue;
                    var value = ((uint)monitorImage[fieldOffset] << 24) |
                        ((uint)monitorImage[fieldOffset + 1] << 16) |
                        ((uint)monitorImage[fieldOffset + 2] << 8) | monitorImage[fieldOffset + 3];
                    AppendMoveLongToA1(code, fieldOffset, value);
                }

                Append(code, 0x2006); // MOVE.L D6,D0
                Append(code, 0x4840); // SWAP D0: X, then Y, preserving WORD write order
                Append(code, 0x3340); // MOVE.W D0,ViewPosition.X(A1)
                Append(code, 0x0014);
                Append(code, 0x3346); // MOVE.W D6,ViewPosition.Y(A1)
                Append(code, 0x0016);
                Append(code, 0x2005); // MOVE.L D5,D0: retained original Point
                Append(code, 0x4840); // SWAP D0
                Append(code, 0x3340); // MOVE.W D0,DefaultViewPosition.X(A1)
                Append(code, 0x0050);
                Append(code, 0x3345); // MOVE.W D5,DefaultViewPosition.Y(A1)
                Append(code, 0x0052);
                Append(code, MoveLongImmediateD0);
                Append(code, 0);
                Append(code, 0x0058);
            }
            else
            {
                var unsupportedMonitorOffset = code.Count;
                PatchBranch(code, monitorBranchExtensionOffset, unsupportedMonitorOffset);
                Append(code, MoveLongD7ToD0);
            }

            var recordReturnOffset = code.Count;
            foreach (var branchExtensionOffset in recordReturnBranchExtensionOffsets)
                PatchBranch(code, branchExtensionOffset, recordReturnOffset);
            Append(code, MoveMultipleLongA7PostIncrementToRegisters);
            Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6
            Append(code, AddQuickFourLongA7); // discard staged requested size, preserve CCR
            Append(code, ReturnFromSubroutine);

            // Keep the mode-dispatch branch local.  Each complete DtagDisp /
            // DtagDims result block is larger than a 16-bit Bcc reach when
            // all 66 canonical records are emitted as one distant table.
            // The inline skip mirrors Kickstart's compact lookup shape and
            // keeps every 68000 conditional branch within its signed-word
            // range.
            PatchBranch(code, modeSkipExtensionOffset, code.Count);
        }

        Append(code, BranchAlwaysWord);
        var unsupportedModeExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        foreach (var branchExtensionOffset in stagedFallbackBranches)
            PatchBranch(code, branchExtensionOffset, stagedLocalFallbackOffset);
        PatchBranch(code, unsupportedModeExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);

        return offset;

        static void AppendDimensionsTransferCount(List<byte> target, int dataRegister)
        {
            // Dn = requested <=26 ? requested :
            //      26 + ((min(requested,66) -26) & ~7).
            // Only Dn and CCR change, so this is usable both before ownership
            // resolution in D0 and inside the saved public frame in D7.
            Append(target, (ushort)(CompareImmediateLongD0 | dataRegister));
            Append(target, 0);
            Append(target, 26);
            Append(target, BranchLowerOrSameWord);
            var scalarCompleteExtensionOffset = target.Count;
            Append(target, 0);
            Append(target, (ushort)(CompareImmediateLongD0 | dataRegister));
            Append(target, 0);
            Append(target, 66);
            Append(target, BranchLowerOrSameWord);
            var boundedRectanglesExtensionOffset = target.Count;
            Append(target, 0);
            Append(target, (ushort)(MoveQuickZeroD0 | (dataRegister << 9) | 66));
            PatchBranch(target, boundedRectanglesExtensionOffset, target.Count);
            Append(target, (ushort)(SubImmediateLongD0 | dataRegister));
            Append(target, 0);
            Append(target, 26);
            Append(target, (ushort)(AndImmediateLongD0 | dataRegister));
            Append(target, 0xFFFF);
            Append(target, 0xFFF8);
            Append(target, (ushort)(0x0680 | dataRegister)); // ADDI.L #26,Dn
            Append(target, 0);
            Append(target, 26);
            PatchBranch(target, scalarCompleteExtensionOffset, target.Count);
        }

        static void AppendMoveLongToA1(List<byte> target, int displacement, uint value)
        {
            Append(target, MoveLongImmediateD0);
            Append(target, (ushort)(value >> 16));
            Append(target, (ushort)value);
            Append(target, MoveLongD0ToA1Displacement);
            Append(target, checked((ushort)displacement));
        }

        static void AppendMoveWordToA1(List<byte> target, int displacement, ushort value)
        {
            Append(target, MoveImmediateWordD0);
            Append(target, value);
            Append(target, MoveWordD0ToA1Displacement);
            Append(target, checked((ushort)displacement));
        }

        static void AppendMoveByteToA1(List<byte> target, int displacement, byte value)
        {
            Append(target, MoveImmediateWordD0);
            Append(target, value);
            Append(target, MoveByteD0ToA1Displacement);
            Append(target, checked((ushort)displacement));
        }

        static void AppendAgaDisplayInfoOverrides(
            List<byte> target,
            uint baseProperties)
        {
            // ChipRevBits0 is the native GfxBase capability publication.
            // Both AA bits must be present before an AGA display record can
            // advertise Lisa's eight-plane/RGB8 capability; a partial Alice
            // or Lisa configuration remains on the conservative OCS/ECS
            // record established above.
            Append(target, MoveQuickZeroD6);
            Append(target, MoveByteA6DisplacementToD6);
            Append(target, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
            Append(target, BitTestImmediateD6);
            Append(target, 2); // GraphicsChipRevision.AaAlice
            Append(target, BranchEqualWord);
            var noAgaAliceBranchExtensionOffset = target.Count;
            Append(target, 0);
            Append(target, BitTestImmediateD6);
            Append(target, 3); // GraphicsChipRevision.AaLisa
            Append(target, BranchEqualWord);
            var noAgaLisaBranchExtensionOffset = target.Count;
            Append(target, 0);

            AppendMoveLongToA1(
                target,
                0x12,
                baseProperties | GraphicsDisplayDatabase.DipfIsAa);
            AppendMoveWordToA1(target, 0x1E, ushort.MaxValue);
            AppendMoveByteToA1(target, 0x28, 8);
            AppendMoveByteToA1(target, 0x29, 8);
            AppendMoveByteToA1(target, 0x2A, 8);

            var noAgaOffset = target.Count;
            PatchBranch(target, noAgaAliceBranchExtensionOffset, noAgaOffset);
            PatchBranch(target, noAgaLisaBranchExtensionOffset, noAgaOffset);
        }

        static void AppendEcsDisplayInfoAvailability(
            List<byte> target,
            uint modeId)
        {
            if (((ushort)modeId & GraphicsModeIds.SuperHiresMode) == 0)
                return;

            // SuperHires remains a canonical, enumerable DisplayInfo record
            // on OCS, but its DtagDisp availability must report no chips until
            // both ECS capability bits are resident in GfxBase.ChipRevBits0.
            // This mirrors ModeNotAvailable without suppressing enumeration.
            Append(target, MoveQuickZeroD6);
            Append(target, MoveByteA6DisplacementToD6);
            Append(target, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
            Append(target, BitTestImmediateD6);
            Append(target, 0); // GraphicsChipRevision.HrAgnus
            Append(target, BranchEqualWord);
            var missingEcsAgnusBranchExtensionOffset = target.Count;
            Append(target, 0);
            Append(target, BitTestImmediateD6);
            Append(target, 1); // GraphicsChipRevision.HrDenise
            Append(target, BranchNotEqualWord);
            var ecsAvailableBranchExtensionOffset = target.Count;
            Append(target, 0);

            var unavailableOffset = target.Count;
            AppendMoveWordToA1(
                target,
                0x10,
                (ushort)GraphicsDisplayDatabase.DiAvailNoChips);

            var completeOffset = target.Count;
            PatchBranch(
                target,
                missingEcsAgnusBranchExtensionOffset,
                unavailableOffset);
            PatchBranch(
                target,
                ecsAvailableBranchExtensionOffset,
                completeOffset);
        }

        static void AppendAgaDimensionsOverrides(List<byte> target)
        {
            Append(target, MoveQuickZeroD6);
            Append(target, MoveByteA6DisplacementToD6);
            Append(target, checked((ushort)GraphicsLayouts.GfxBaseChipRevBits0));
            Append(target, BitTestImmediateD6);
            Append(target, 2); // GraphicsChipRevision.AaAlice
            Append(target, BranchEqualWord);
            var noAgaAliceBranchExtensionOffset = target.Count;
            Append(target, 0);
            Append(target, BitTestImmediateD6);
            Append(target, 3); // GraphicsChipRevision.AaLisa
            Append(target, BranchEqualWord);
            var noAgaLisaBranchExtensionOffset = target.Count;
            Append(target, 0);

            AppendMoveWordToA1(target, 0x10, 8);

            var noAgaOffset = target.Count;
            PatchBranch(target, noAgaAliceBranchExtensionOffset, noAgaOffset);
            PatchBranch(target, noAgaLisaBranchExtensionOffset, noAgaOffset);
        }

        static void AppendDimensionsRectangle(
            List<byte> target,
            int displacement,
            ushort width,
            ushort height)
        {
            AppendMoveWordToA1(target, displacement, 0);
            AppendMoveWordToA1(target, displacement + 2, 0);
            AppendMoveWordToA1(target, displacement + 4, (ushort)(width - 1));
            AppendMoveWordToA1(target, displacement + 6, (ushort)(height - 1));
        }

        static void AppendNativeOverscanRectangle(
            List<byte> target, int displacement, uint modeId, bool defaultMonitorNtsc, bool video)
        {
            // Original 3.1 records have signed origins and distinct Max/Video
            // rectangles. Superhires has the same 1440-pixel extent for both.
            var monitor = modeId & 0xFFFF1000u;
            var pal = monitor == GraphicsModeIds.PalMonitor ||
                (monitor == GraphicsModeIds.DefaultMonitor && !defaultMonitorNtsc);
            var superHires = (modeId & GraphicsModeIds.SuperHiresMode) != 0;
            var hires = (modeId & GraphicsModeIds.HiresMode) != 0;
            var scaleX = superHires ? 4 : hires ? 2 : 1;
            var scaleY = (modeId & GraphicsModeIds.InterlaceMode) != 0 ? 2 : 1;
            var right = superHires ? 1295 : hires ? (video ? 663 : 651) : (video ? 331 : 325);
            AppendMoveWordToA1(target, displacement, unchecked((ushort)(-36 * scaleX)));
            AppendMoveWordToA1(target, displacement + 2, unchecked((ushort)((pal ? -15 : -23) * scaleY)));
            AppendMoveWordToA1(target, displacement + 4, (ushort)right);
            AppendMoveWordToA1(target, displacement + 6, (ushort)((pal ? 268 : 218) * scaleY - 1));
        }

        static void AppendNativeDisplayName(List<byte> target, string name)
        {
            var length = Math.Min(31, name.Length);
            for (var offset = 0; offset < length; offset += 4)
            {
                uint value = 0;
                for (var byteIndex = 0; byteIndex < 4; byteIndex++)
                {
                    var sourceIndex = offset + byteIndex;
                    value <<= 8;
                    if (sourceIndex < length)
                        value |= (byte)name[sourceIndex];
                }

                AppendMoveLongToA1(target, 0x10 + offset, value);
            }
        }
    }

    private static List<uint> GetCanonicalDisplayModeIds()
    {
        var modeIds = new List<uint>(66);
        var keys = new ushort[]
        {
            GraphicsModeIds.LoresKey,
            GraphicsModeIds.HiresKey,
            GraphicsModeIds.SuperHiresKey,
            GraphicsModeIds.HamKey,
            GraphicsModeIds.LoresLaceKey,
            GraphicsModeIds.HiresLaceKey,
            GraphicsModeIds.SuperHiresLaceKey,
            GraphicsModeIds.HamLaceKey,
            GraphicsModeIds.LoresDualPlayfieldKey,
            GraphicsModeIds.HiresDualPlayfieldKey,
            GraphicsModeIds.SuperHiresDualPlayfieldKey,
            GraphicsModeIds.LoresDualPlayfieldLaceKey,
            GraphicsModeIds.HiresDualPlayfieldLaceKey,
            GraphicsModeIds.SuperHiresDualPlayfieldLaceKey,
            GraphicsModeIds.LoresDualPlayfieldTwoKey,
            GraphicsModeIds.HiresDualPlayfieldTwoKey,
            GraphicsModeIds.SuperHiresDualPlayfieldTwoKey,
            GraphicsModeIds.LoresDualPlayfieldTwoLaceKey,
            GraphicsModeIds.HiresDualPlayfieldTwoLaceKey,
            GraphicsModeIds.SuperHiresDualPlayfieldTwoLaceKey,
            GraphicsModeIds.ExtraHalfBriteKey,
            GraphicsModeIds.ExtraHalfBriteLaceKey
        };

        foreach (var monitor in new[]
        {
            GraphicsModeIds.DefaultMonitor,
            GraphicsModeIds.PalMonitor,
            GraphicsModeIds.NtscMonitor
        })
        {
            foreach (var key in keys)
                modeIds.Add(monitor | key);
        }

        return modeIds;
    }

    // D2 retains the admitted mode for subsequent payload calculations. Only
    // D0 is scratch here, and no guest profile reads are introduced. The image
    // constructor supplies the initialized database profile; mutable DisplayFlags
    // do not remap ROM aliases. Standalone ROM initialization remains separate.
    private static void AppendQueryHeaderIdentity(List<byte> code, bool defaultMonitorNtsc)
    {
        Append(code, MoveLongD2ToD0);
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x3000); // NAME policy is not inferred from absent ROM data
        Append(code, BranchEqualWord);
        var nameDone = code.Count;
        Append(code, 0);
        Append(code, AndImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0x1000);
        Append(code, BranchNotEqualWord);
        var explicitMonitor = code.Count;
        Append(code, 0);
        Append(code, MoveLongImmediateD0);
        Append(code, defaultMonitorNtsc ? (ushort)0x0001 : (ushort)0x0002);
        Append(code, 0x1000); // initialized default owner
        PatchBranch(code, explicitMonitor, code.Count);
        Append(code, CompareImmediateLongD1);
        Append(code, 0x8000);
        Append(code, 0x2000);
        Append(code, BranchEqualWord);
        var monitorDone = code.Count;
        Append(code, 0);
        Append(code, 0x8082); // OR.L D2,D0: DISP/DIMS retain their resolution key
        PatchBranch(code, nameDone, code.Count);
        PatchBranch(code, monitorDone, code.Count);
    }

    private static NativeDisplayInfoRecord BuildNativeDisplayInfoRecord(uint modeId, bool defaultMonitorNtsc)
    {
        var modeKey = (ushort)modeId;
        var isDefault = (modeId & 0xFFFF1000u) == GraphicsModeIds.DefaultMonitor;
        var isPal = (isDefault && !defaultMonitorNtsc) ||
                    (modeId & 0xFFFF_1000u) == GraphicsModeIds.PalMonitor;
        var isLace = (modeKey & GraphicsModeIds.InterlaceMode) != 0;
        var isSuperHires = (modeKey & GraphicsModeIds.SuperHiresMode) != 0;

        var properties = GraphicsDisplayDatabase.DipfIsSprites |
                         GraphicsDisplayDatabase.DipfIsSpritesAttached |
                         GraphicsDisplayDatabase.DipfIsWb |
                         GraphicsDisplayDatabase.DipfIsDbuffer;
        if (isSuperHires)
        {
            properties &= ~GraphicsDisplayDatabase.DipfIsSpritesAttached;
            properties |= GraphicsDisplayDatabase.DipfIsEcs;
        }

        if (isLace)
            properties |= GraphicsDisplayDatabase.DipfIsLace;
        if ((modeKey & GraphicsModeIds.DualPlayfieldMode) != 0)
            properties |= GraphicsDisplayDatabase.DipfIsDualPf;
        if ((modeKey & GraphicsModeIds.PlayfieldBitAssignment) != 0)
            properties |= GraphicsDisplayDatabase.DipfIsPf2Pri;
        if ((modeKey & GraphicsModeIds.HamMode) != 0)
            properties |= GraphicsDisplayDatabase.DipfIsHam;
        if ((modeKey & GraphicsModeIds.ExtraHalfBriteMode) != 0)
            properties |= GraphicsDisplayDatabase.DipfIsExtraHalfBrite;
        if (isPal)
            properties |= GraphicsDisplayDatabase.DipfIsPal;

        var horizontalTicksPerPixel = isSuperHires
            ? (ushort)1
            : (modeKey & GraphicsModeIds.HiresMode) != 0
                ? (ushort)2
                : (ushort)4;
        var pixelSpeed = horizontalTicksPerPixel switch
        {
            1 => (ushort)35,
            2 => (ushort)70,
            _ => (ushort)140
        };
        var componentBits = isSuperHires && !isLace ? (byte)2 : (byte)4;
        var paletteRange = (ushort)(1 << (componentBits * 3));

        return new NativeDisplayInfoRecord(
            modeNotAvailable: 0,
            properties: properties,
            horizontalTicksPerPixel: horizontalTicksPerPixel,
            pixelSpeed: pixelSpeed,
            spriteCount: 8,
            paletteRange: paletteRange,
            spriteResolution: isSuperHires ? (ushort)2 : (ushort)4,
            componentBits: componentBits);
    }

    private static NativeDisplayDimensionsRecord BuildNativeDisplayDimensionsRecord(uint modeId, bool defaultMonitorNtsc)
    {
        var modeKey = (ushort)modeId;
        var isDefault = (modeId & 0xFFFF1000u) == GraphicsModeIds.DefaultMonitor;
        var isPal = (isDefault && !defaultMonitorNtsc) ||
                    (modeId & 0xFFFF_1000u) == GraphicsModeIds.PalMonitor;
        var isLace = (modeKey & GraphicsModeIds.InterlaceMode) != 0;
        var isHires = (modeKey & GraphicsModeIds.HiresMode) != 0;
        var isSuperHires = (modeKey & GraphicsModeIds.SuperHiresMode) != 0;
        var height = isLace
            ? isPal ? (ushort)512 : (ushort)400
            : isPal ? (ushort)256 : (ushort)200;
        var maxHeight = (ushort)((isPal ? 283 : 241) * (isLace ? 2 : 1));
        var width = isSuperHires
            ? (ushort)1280
            : isHires ? (ushort)640 : (ushort)320;
        var maxWidth = isSuperHires
            ? (ushort)1448
            : isHires ? (ushort)724 : (ushort)362;

        return new NativeDisplayDimensionsRecord(
            depth: isSuperHires ? (ushort)2 : isHires ? (ushort)4 :
                (modeKey & (GraphicsModeIds.HamKey | GraphicsModeIds.ExtraHalfBriteKey |
                            GraphicsModeIds.LoresDualPlayfieldKey)) != 0 ? (ushort)6 : (ushort)5,
            width: width,
            height: height,
            maxWidth: maxWidth,
            maxHeight: maxHeight);
    }

    private static string BuildNativeDisplayName(uint modeId, bool defaultMonitorNtsc)
    {
        var modeKey = (ushort)(modeId & 0x0000_EFFFu);
        var monitorName = (modeId & 0xFFFF1000u) == GraphicsModeIds.DefaultMonitor
            ? defaultMonitorNtsc ? "NTSC" : "Default"
            : (modeId & 0xFFFF_1000u) == GraphicsModeIds.PalMonitor
                ? "PAL"
                : "NTSC";
        var suffix = modeKey switch
        {
            GraphicsModeIds.LoresKey => "lores",
            GraphicsModeIds.HiresKey => "hires",
            GraphicsModeIds.SuperHiresKey => "superhires",
            GraphicsModeIds.LoresLaceKey => "lores interlace",
            GraphicsModeIds.HiresLaceKey => "hires interlace",
            GraphicsModeIds.SuperHiresLaceKey => "superhires interlace",
            GraphicsModeIds.HamKey => "HAM",
            GraphicsModeIds.HamLaceKey => "HAM interlace",
            GraphicsModeIds.ExtraHalfBriteKey => "extra-halfbrite",
            GraphicsModeIds.ExtraHalfBriteLaceKey => "extra-halfbrite interlace",
            GraphicsModeIds.LoresDualPlayfieldKey => "dual-playfield",
            GraphicsModeIds.HiresDualPlayfieldKey => "hires dual-playfield",
            GraphicsModeIds.SuperHiresDualPlayfieldKey => "superhires dual-playfield",
            GraphicsModeIds.LoresDualPlayfieldLaceKey => "dual-playfield interlace",
            GraphicsModeIds.HiresDualPlayfieldLaceKey => "hires dual-playfield interlace",
            GraphicsModeIds.SuperHiresDualPlayfieldLaceKey => "superhires dual-playfield interlace",
            GraphicsModeIds.LoresDualPlayfieldTwoKey => "dual-playfield 2",
            GraphicsModeIds.HiresDualPlayfieldTwoKey => "hires dual-playfield 2",
            GraphicsModeIds.SuperHiresDualPlayfieldTwoKey => "superhires dual-playfield 2",
            GraphicsModeIds.LoresDualPlayfieldTwoLaceKey => "dual-playfield 2 interlace",
            GraphicsModeIds.HiresDualPlayfieldTwoLaceKey => "hires dual-playfield 2 interlace",
            GraphicsModeIds.SuperHiresDualPlayfieldTwoLaceKey => "superhires dual-playfield 2 interlace",
            _ => "unknown"
        };

        return $"{monitorName} {suffix}";
    }

    private readonly struct NativeDisplayInfoRecord
    {
        internal NativeDisplayInfoRecord(
            ushort modeNotAvailable,
            uint properties,
            ushort horizontalTicksPerPixel,
            ushort pixelSpeed,
            ushort spriteCount,
            ushort paletteRange,
            ushort spriteResolution,
            byte componentBits)
        {
            ModeNotAvailable = modeNotAvailable;
            Properties = properties;
            HorizontalTicksPerPixel = horizontalTicksPerPixel;
            PixelSpeed = pixelSpeed;
            SpriteCount = spriteCount;
            PaletteRange = paletteRange;
            SpriteResolution = spriteResolution;
            ComponentBits = componentBits;
        }

        internal ushort ModeNotAvailable { get; }
        internal uint Properties { get; }
        internal ushort HorizontalTicksPerPixel { get; }
        internal ushort PixelSpeed { get; }
        internal ushort SpriteCount { get; }
        internal ushort PaletteRange { get; }
        internal ushort SpriteResolution { get; }
        internal byte ComponentBits { get; }
    }

    private readonly struct NativeDisplayDimensionsRecord
    {
        internal NativeDisplayDimensionsRecord(
            ushort depth,
            ushort width,
            ushort height,
            ushort maxWidth,
            ushort maxHeight)
        {
            Depth = depth;
            Width = width;
            Height = height;
            MaxWidth = maxWidth;
            MaxHeight = maxHeight;
        }

        internal ushort Depth { get; }
        internal ushort Width { get; }
        internal ushort Height { get; }
        internal ushort MaxWidth { get; }
        internal ushort MaxHeight { get; }
    }

    /// <summary>
    /// Emits a strict post-<c>MrgCop</c> teardown form for three through thirteen
    /// visible ViewPorts.  Each admitted form has a <c>12 * N</c> entry
    /// destination stream in its first CopList and <c>N - 1</c> retained,
    /// distinct twelve-entry source streams.  All guest envelopes are
    /// validated before any public link is cleared.
    /// </summary>
    private static int AppendFreeVPortCopListsMergedVisible(
        List<byte> code,
        int viewPortCount,
        int fallbackEntryOffset)
    {
        if (viewPortCount is < 3 or > 13)
            throw new ArgumentOutOfRangeException(nameof(viewPortCount));

        var offset = code.Count;
        var fallbackBranches = new List<int>(viewPortCount * 48);
        var destinationEntryCount = checked((ushort)(viewPortCount * 12));
        var destinationTerminatorOffset = checked((ushort)(viewPortCount * 48 - 4));
        var destinationMaximumAddress = unchecked(
            uint.MaxValue - (uint)(viewPortCount * 48 - 1));

        void Decline(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void ValidatePointer(
            ushort testOpcode,
            ushort bitTestOpcode,
            ushort compareOpcode,
            uint maximumAddress)
        {
            Append(code, testOpcode);
            Decline(BranchEqualWord);
            Append(code, bitTestOpcode);
            Append(code, 0);
            Decline();
            Append(code, compareOpcode);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            Decline(BranchHighWord);
        }

        // Preserve the void-vector D0 result and the first ViewPort for both
        // an all-or-nothing commit and an unchanged fallback frame.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveAddressA0ToA5);
        Append(code, MoveLongA0ToD6);
        ValidatePointer(
            TestLongD6,
            BitTestImmediateD6,
            CompareImmediateLongD6,
            0xFFFF_FFD8u); // ViewPortSize

        for (var index = 0; index < viewPortCount; index++)
        {
            // A4 retains the current node while A0 visits its RasInfo,
            // CopList, and raw Copper stream envelopes.
            Append(code, MoveAddressA0ToA4);
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
            Append(code, CompareImmediateWordD0);
            Append(code, 0);
            Decline();
            Append(code, MoveQuickZeroD0);
            Append(code, MoveByteA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
            Append(code, TestLongD0);
            Decline();

            foreach (var linkOffset in new[]
            {
                GraphicsLayouts.ViewPortSprIns,
                GraphicsLayouts.ViewPortClrIns,
                GraphicsLayouts.ViewPortUCopIns
            })
            {
                Append(code, MoveLongA0DisplacementToD0);
                Append(code, checked((ushort)linkOffset));
                Append(code, TestLongD0);
                Decline();
            }

            // MrgCop only owns the terminal single-RasInfo shape.  Keeping
            // the same preflight here prevents a native retire from claiming
            // a richer/provider-owned ViewPort chain.
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
            ValidatePointer(
                TestLongD0,
                BitTestImmediateD0,
                CompareImmediateLongD0,
                0xFFFF_FFF4u); // RasInfoSize
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
            Append(code, TestLongD0);
            Decline();
            Append(code, MoveAddressA4ToA0);

            Append(code, MoveLongA0DisplacementToD5);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
            ValidatePointer(
                TestLongD5,
                BitTestImmediateD5,
                CompareImmediateLongD5,
                0xFFFF_FFCAu); // CopListSize
            Append(code, MoveAddressD5ToA0);

            // CopList must remain bound to this ViewPort, with no descriptor
            // chain.  D6 is scratch after the raw head is retained in D4.
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongA0ToD6);
            Append(code, MoveAddressD5ToA0);
            Append(code, CompareLongD6ToD0);
            Decline();
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListNext));
            Append(code, TestLongD0);
            Decline();

            Append(code, MoveLongA0DisplacementToD4);
            Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
            ValidatePointer(
                TestLongD4,
                BitTestImmediateD4,
                CompareImmediateLongD4,
                index == 0 ? destinationMaximumAddress : 0xFFFF_FFD0u);
            foreach (var fieldOffset in new[]
            {
                GraphicsLayouts.CopListCopLStart,
                GraphicsLayouts.CopListCopSStart
            })
            {
                Append(code, MoveLongA0DisplacementToD0);
                Append(code, checked((ushort)fieldOffset));
                Append(code, MoveLongD4ToD6);
                Append(code, CompareLongD6ToD0);
                Decline();
            }

            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListCount));
            Append(code, CompareImmediateWordD0);
            Append(code, index == 0 ? destinationEntryCount : (ushort)12);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
            Append(code, CompareImmediateWordD0);
            Append(code, index == 0
                ? checked((ushort)(destinationEntryCount - 1))
                : (ushort)11);
            Decline(BranchLowerOrSameWord);

            // Validate the canonical raw-stream terminator after the merged
            // destination or retained source body.  The body bytes themselves
            // are caller-owned and intentionally never rewritten here.
            Append(code, MoveAddressD4ToA0);
            var terminatorOffset = index == 0 ? destinationTerminatorOffset : (ushort)44;
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, terminatorOffset);
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.CopperEndWait);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)(terminatorOffset + 2)));
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.CopperEndMask);
            Decline();

            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
            if (index + 1 == viewPortCount)
            {
                Append(code, TestLongD0);
                Decline();
            }
            else
            {
                ValidatePointer(
                    TestLongD0,
                    BitTestImmediateD0,
                    CompareImmediateLongD0,
                    0xFFFF_FFD8u);
                Append(code, MoveAddressD0ToA0);
            }
        }

        // Commit after the complete fixed-cardinality chain has passed.
        Append(code, MoveQuickZeroD0);
        Append(code, MoveAddressA5ToA0);
        for (var index = 0; index < viewPortCount; index++)
        {
            foreach (var linkOffset in new[]
            {
                GraphicsLayouts.ViewPortDspIns,
                GraphicsLayouts.ViewPortSprIns,
                GraphicsLayouts.ViewPortClrIns,
                GraphicsLayouts.ViewPortUCopIns
            })
            {
                Append(code, MoveLongD0ToA0Displacement);
                Append(code, checked((ushort)linkOffset));
            }

            if (index + 1 < viewPortCount)
            {
                Append(code, MoveLongA0DisplacementToD6);
                Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
                Append(code, MoveAddressD6ToA0);
            }
        }
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Emits the bounded native teardown walker for canonical post-<c>MrgCop</c>
    /// chains beyond the retained fixed compatibility units.  It performs a
    /// complete read-only preflight before clearing any public link, so an
    /// unrecognised provider chain remains entirely owned by the fallback.
    /// </summary>
    private static int AppendFreeVPortCopListsGenericVisible(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(192);

        void Fail(ushort opcode = BranchNotEqualWord)
        {
            Append(code, opcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void PointerD0(uint maximumAddress)
        {
            Append(code, TestLongD0);
            Fail(BranchEqualWord);
            Append(code, BitTestImmediateD0);
            Append(code, 0);
            Fail();
            Append(code, CompareImmediateLongD0);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            Fail(BranchHighWord);
        }

        void CurrentNodeEnvelope()
        {
            // A4 is the current ViewPort, A5 its CopList and D4 its raw
            // Copper stream. D6 is the validated node count and is never
            // repurposed while this read-only pass is active.
            Append(code, MoveLongA4ToD0);
            PointerD0(0xFFFF_FFD8u);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
            Append(code, CompareImmediateWordD0);
            Append(code, 0);
            Fail();
            Append(code, MoveQuickZeroD0);
            Append(code, MoveByteA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
            Append(code, TestLongD0);
            Fail();
            foreach (var link in new[]
            {
                GraphicsLayouts.ViewPortSprIns,
                GraphicsLayouts.ViewPortClrIns,
                GraphicsLayouts.ViewPortUCopIns
            })
            {
                Append(code, MoveLongA0DisplacementToD0);
                Append(code, checked((ushort)link));
                Append(code, TestLongD0);
                Fail();
            }

            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
            PointerD0(0xFFFF_FFF4u);
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
            Append(code, TestLongD0);
            Fail();

            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
            PointerD0(0xFFFF_FFCAu);
            Append(code, MoveAddressD0ToA5);
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
            Append(code, MoveLongA4ToD1);
            Append(code, CompareLongD1ToD0);
            Fail();
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListNext));
            Append(code, TestLongD0);
            Fail();
            Append(code, MoveLongA0DisplacementToD4);
            Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
            Append(code, MoveLongD4ToD0);
            PointerD0(0xFFFF_FFD0u);
            foreach (var field in new[]
            {
                GraphicsLayouts.CopListCopLStart,
                GraphicsLayouts.CopListCopSStart
            })
            {
                Append(code, MoveLongA0DisplacementToD0);
                Append(code, checked((ushort)field));
                Append(code, MoveLongD4ToD1);
                Append(code, CompareLongD1ToD0);
                Fail();
            }

            // Source lists remain fixed twelve-entry programs. The first
            // list is the merged destination and gets its cardinality and
            // final terminator checked only after the chain has been counted.
            Append(code, TestLongD6);
            Append(code, BranchEqualWord);
            var firstNodeBranch = code.Count;
            Append(code, 0);
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 12);
            Fail();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
            Append(code, CompareImmediateWordD0);
            Append(code, 11);
            Fail(BranchLowerOrSameWord);
            Append(code, MoveAddressD4ToA0);
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, 44);
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.CopperEndWait);
            Fail();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, 46);
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.CopperEndMask);
            Fail();
            Append(code, BranchAlwaysWord);
            var nodeCompleteBranch = code.Count;
            Append(code, 0);

            PatchBranch(code, firstNodeBranch, code.Count);
            Append(code, MoveAddressA5ToA3);
            Append(code, MoveLongD4ToD2);
            Append(code, MoveAddressD2ToA2);
            PatchBranch(code, nodeCompleteBranch, code.Count);
        }

        // Preserve exactly the state the fallback must observe. The native
        // unit otherwise follows graphics.library's void-vector convention.
        Append(code, MoveLongA6ToPreDecrementA7);
        Append(code, MoveLongD0ToD7);
        Append(code, MoveAddressA0ToA6);
        Append(code, MoveLongA0ToD0);
        PointerD0(0xFFFF_FFD8u);
        Append(code, MoveAddressA6ToA4);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveQuickThirtyOneD5);
        Append(code, MoveLongD5ToD1); // DBRA admits no more than 32 nodes.

        var preflightLoopOffset = code.Count;
        CurrentNodeEnvelope();
        Append(code, AddQuickOneLongD6);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var preflightCompleteBranch = code.Count;
        Append(code, 0);
        PointerD0(0xFFFF_FFD8u);
        Append(code, MoveAddressD0ToA4);
        Append(code, DecrementBranchD1);
        var preflightLoopBranch = code.Count;
        Append(code, 0);
        PatchBranch(code, preflightLoopBranch, preflightLoopOffset);
        Append(code, BranchAlwaysWord);
        var preflightLimitFail = code.Count;
        Append(code, 0);
        fallbackBranches.Add(preflightLimitFail);

        PatchBranch(code, preflightCompleteBranch, code.Count);
        // First CopList: Count == 12 * N, MaxCount >= Count - 1, and its
        // terminator lies at byte 48 * N - 4. The pointer bound established
        // above makes the dynamic address arithmetic safe for N <= 32.
        Append(code, MoveLongD6ToD0);
        Append(code, AddLongD6ToD0);
        Append(code, AddLongD6ToD0);
        Append(code, ShiftLeftLongD0);
        Append(code, ShiftLeftLongD0);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, CompareWordD0ToD1);
        Fail();
        Append(code, SubQuickOneLongD0);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareWordD0ToD1);
        Fail(BranchCarryWord);
        Append(code, ShiftLeftLongD0);
        Append(code, ShiftLeftLongD0);
        Append(code, MoveAddressA2ToA0);
        Append(code, AddLongD0ToA0);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, GraphicsLayouts.CopperEndWait);
        Fail();
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, 2);
        Append(code, CompareImmediateWordD1);
        Append(code, GraphicsLayouts.CopperEndMask);
        Fail();

        // Commit is deliberately a second traversal. Every location it
        // writes was accepted above; Next is fetched before link clearing so
        // the traversal itself cannot lose a public node.
        Append(code, MoveQuickZeroD0);
        Append(code, MoveAddressA6ToA0);
        var commitLoopOffset = code.Count;
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        foreach (var link in new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        })
        {
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, checked((ushort)link));
        }
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var commitCompleteBranch = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD1ToA0);
        Append(code, BranchAlwaysWord);
        var commitLoopBranch = code.Count;
        Append(code, 0);
        PatchBranch(code, commitLoopBranch, commitLoopOffset);
        PatchBranch(code, commitCompleteBranch, code.Count);
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveAddressD6ToA6);
        Append(code, ReturnFromSubroutine);

        var fallbackOffset = code.Count;
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveAddressD6ToA6);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtension = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtension, fallbackEntryOffset);
        foreach (var extensionOffset in fallbackBranches)
            PatchBranch(code, extensionOffset, fallbackOffset);
        return offset;
    }

    private static int AppendFreeVPortCopListsTwoVisiblePreMerged(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(56);

        void Decline(ushort branchOpcode = BranchNotEqualWord)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void ValidatePointer(
            ushort testOpcode,
            ushort bitTestOpcode,
            ushort compareOpcode,
            uint maximumAddress)
        {
            Append(code, testOpcode);
            Decline(BranchEqualWord);
            Append(code, bitTestOpcode);
            Append(code, 0);
            Decline();
            Append(code, compareOpcode);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            Decline(BranchHighWord);
        }

        // FreeVPortCopLists receives the first ViewPort in A0. Retain both
        // node addresses in address registers so the teardown stores can be
        // performed only after every public envelope has passed preflight.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveAddressA0ToA5); // first ViewPort
        Append(code, MoveLongA0ToPreDecrementA7);
        Append(code, MoveLongA7PostIncrementToD6);
        ValidatePointer(
            TestLongD6,
            BitTestImmediateD6,
            CompareImmediateLongD6,
            0xFFFF_FFD8u); // ViewPortSize
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Decline();
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD0);
        Decline();
        foreach (var linkOffset in new[]
        {
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        })
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)linkOffset));
            Append(code, TestLongD0);
            Decline();
        }

        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        ValidatePointer(
            TestLongD5,
            BitTestImmediateD5,
            CompareImmediateLongD5,
            0xFFFF_FFD8u);

        // The second node is visible, terminal, and has no alternate copper
        // links. Keep it in A4 while A0 walks its CopList envelope.
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveAddressA0ToA4);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Decline();
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD0);
        Decline();
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD0);
        Decline();
        foreach (var linkOffset in new[]
        {
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        })
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)linkOffset));
            Append(code, TestLongD0);
            Decline();
        }

        // Validate the native MrgCop two-viewport result.  MrgCop publishes
        // a 24-entry destination in the first caller-owned stream while the
        // second descriptor retains its original, distinct 12-entry source.
        // Teardown is allocation-free and leaves all descriptor/raw bytes
        // untouched; only the four public ViewPort links are retired.
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(
            TestLongD4,
            BitTestImmediateD4,
            CompareImmediateLongD4,
            0xFFFF_FFCAu); // CopListSize
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        ValidatePointer(
            TestLongD3,
            BitTestImmediateD3,
            CompareImmediateLongD3,
            0xFFFF_FFCAu);

        Append(code, MoveAddressD4ToA0);
        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        ValidatePointer(
            TestLongD2,
            BitTestImmediateD2,
            CompareImmediateLongD2,
            0xFFFF_FFFCu); // raw stream
        foreach (var fieldOffset in new[]
        {
            GraphicsLayouts.CopListCopLStart,
            GraphicsLayouts.CopListCopSStart
        })
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)fieldOffset));
            Append(code, MoveLongD2ToD6);
            Append(code, CompareLongD6ToD0);
            Decline();
        }
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 24);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 23);
        Decline(BranchLowerOrSameWord);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListNext));
        Append(code, TestLongD0);
        Decline();

        Append(code, MoveAddressD3ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        Append(code, MoveLongD0ToD5);
        ValidatePointer(
            TestLongD5,
            BitTestImmediateD5,
            CompareImmediateLongD5,
            0xFFFF_FFD0u); // twelve-entry source stream
        foreach (var fieldOffset in new[]
        {
            GraphicsLayouts.CopListCopLStart,
            GraphicsLayouts.CopListCopSStart
        })
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)fieldOffset));
            Append(code, MoveLongD5ToD6);
            Append(code, CompareLongD6ToD0);
            Decline();
        }
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 12);
        Decline();
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD0);
        Append(code, 11);
        Decline(BranchLowerOrSameWord);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListNext));
        Append(code, TestLongD0);
        Decline();

        // The merged destination terminates after 24 entries; the retained
        // source still terminates after its canonical twelve-entry body.
        foreach (var (rawRegister, terminatorOffset) in new[]
        {
            (MoveAddressD2ToA0, (ushort)92),
            (MoveAddressD5ToA0, (ushort)44)
        })
        {
            Append(code, rawRegister);
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, terminatorOffset);
            Append(code, CompareImmediateWordD0);
            Append(code, 0xFFFF);
            Decline();
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)(terminatorOffset + 2)));
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.CopperEndMask);
            Decline();
        }

        // Commit only after the complete two-node signature has passed.
        Append(code, MoveQuickZeroD0);
        foreach (var linkOffset in new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        })
        {
            Append(code, MoveLongD0ToA5Displacement);
            Append(code, checked((ushort)linkOffset));
        }
        Append(code, MoveAddressA4ToA0);
        foreach (var linkOffset in new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        })
        {
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, checked((ushort)linkOffset));
        }
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        return offset;
    }

    private static int AppendFreeVPortCopListsEmpty(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(32);

        // FreeVPortCopLists is a void vector.  Empty links remain the
        // smallest native no-op.  The preallocated MakeVPort unit adds one
        // deliberately narrow teardown form: a nonzero DspIns CopList with
        // zero alternate links, matching ViewPort/raw pointers, zero count,
        // positive capacity, and the canonical copper terminator.  This is a
        // guest-layout transaction only; provider/allocator-owned lists keep
        // the existing fallback owner.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddViewPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFE8); // links through ViewPort+0x17
        Append(code, BranchHighWord);
        var wrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedViewPortBranchExtensionOffset);

        // The three alternate links must be empty in the preallocated blank
        // form.  Reading them before the DspIns pointer also keeps an
        // arbitrary provider pointer from being dereferenced accidentally.
        var alternateLinkOffsets = new[]
        {
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };
        foreach (var linkOffset in alternateLinkOffsets)
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)linkOffset));
            Append(code, TestLongD0);
            Append(code, BranchNotEqualWord);
            var linkBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(linkBranchExtensionOffset);
        }

        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var emptySuccessBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A nonzero DspIns is only examined after a nonzero RasInfo marker,
        // which keeps malformed/provider pointers on the shared owner.
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var missingRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(missingRasInfoBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRasInfoBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // RasInfoSize envelope
        Append(code, BranchHighWord);
        var wrappedRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedRasInfoBranchExtensionOffset);

        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddCopListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddCopListBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFCA); // CopListSize envelope
        Append(code, BranchHighWord);
        var wrappedCopListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedCopListBranchExtensionOffset);
        Append(code, MoveAddressD0ToA2);

        // The CopList must still name this ViewPort and one shared raw
        // stream through all three public start pointers.
        Append(code, MoveLongD4ToD2);
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
        Append(code, CompareLongD2ToD4);
        Append(code, BranchNotEqualWord);
        var foreignCopListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(foreignCopListBranchExtensionOffset);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullRawBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullRawBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRawBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRawBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // four-byte raw terminator envelope
        Append(code, BranchHighWord);
        var wrappedRawBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedRawBranchExtensionOffset);

        foreach (var fieldOffset in new[]
        {
            GraphicsLayouts.CopListCopLStart,
            GraphicsLayouts.CopListCopSStart
        })
        {
            Append(code, MoveLongA2DisplacementToD1);
            Append(code, checked((ushort)fieldOffset));
            Append(code, CompareLongD6ToD1);
            Append(code, BranchNotEqualWord);
            var splitRawBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(splitRawBranchExtensionOffset);
        }

        Append(code, MoveWordA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, CompareImmediateWordD1);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var blankCountBranchExtensionOffset = code.Count;
        Append(code, 0);

        // The native MakeVPort construction slice emits nine caller-owned
        // forms: twelve-instruction 16x1, 320x200/PAL 320x256,
        // PAL/NTSC 320x512/400 lores interlace, 640x200/PAL 640x256, and
        // PAL/NTSC 640x512/400 hires interlace standard-planar programs.
        // FreeVPortCopLists may retire any form only after the
        // complete program signature, bitmap envelope, and encoded plane
        // pointer have passed.  This keeps populated/provider copper lists
        // on the ownership-aware fallback and never frees or clears their
        // storage here.
        Append(code, CompareImmediateWordD1);
        Append(code, 12);
        Append(code, BranchNotEqualWord);
        var nonGeneratedCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nonGeneratedCountBranchExtensionOffset);

        Append(code, MoveWordA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD1);
        Append(code, 11);
        Append(code, BranchLowerOrSameWord);
        var generatedCapacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedCapacityBranchExtensionOffset);

        Append(code, MoveAddressD6ToA2);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD0); // twelve words occupy a 48-byte raw span
        Append(code, BranchHighWord);
        var generatedRawRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedRawRangeBranchExtensionOffset);

        var generatedCopperChecks = new[]
        {
            (Offset: 0, Value: (ushort)0x008E),
            (Offset: 2, Value: (ushort)0x2C81),
            (Offset: 4, Value: (ushort)0x0090),
            (Offset: 8, Value: (ushort)0x0092),
            (Offset: 12, Value: (ushort)0x0094),
            (Offset: 16, Value: (ushort)0x0108),
            (Offset: 18, Value: (ushort)0x0000),
            (Offset: 20, Value: (ushort)0x010A),
            (Offset: 22, Value: (ushort)0x0000),
            (Offset: 24, Value: (ushort)0x0100),
            (Offset: 28, Value: (ushort)0x0102),
            (Offset: 30, Value: (ushort)0x0000),
            (Offset: 32, Value: (ushort)0x0104),
            (Offset: 34, Value: (ushort)0x0000),
            (Offset: 36, Value: (ushort)0x00E0),
            (Offset: 40, Value: (ushort)0x00E2),
            (Offset: 44, Value: GraphicsLayouts.CopperEndWait),
            (Offset: 46, Value: GraphicsLayouts.CopperEndMask)
        };
        foreach (var (fieldOffset, value) in generatedCopperChecks)
        {
            Append(code, MoveWordA2DisplacementToD1);
            Append(code, checked((ushort)fieldOffset));
            Append(code, CompareImmediateWordD1);
            Append(code, value);
            Append(code, BranchNotEqualWord);
            var generatedCopperBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(generatedCopperBranchExtensionOffset);
        }

        void AppendGeneratedWordEither(
            ushort fieldOffset,
            ushort smallValue,
            ushort wideValue)
        {
            Append(code, MoveWordA2DisplacementToD1);
            Append(code, fieldOffset);
            Append(code, CompareImmediateWordD1);
            Append(code, smallValue);
            Append(code, BranchEqualWord);
            var smallValueBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD1);
            Append(code, wideValue);
            Append(code, BranchNotEqualWord);
            var invalidValueBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(invalidValueBranchExtensionOffset);
            PatchBranch(code, smallValueBranchExtensionOffset, code.Count);
        }

        void AppendGeneratedWordSeven(
            ushort fieldOffset,
            ushort smallValue,
            ushort wide200Value,
            ushort wide256Value,
            ushort hires200Value,
            ushort hires256Value,
            ushort lace512Value,
            ushort hiresLace512Value)
        {
            Append(code, MoveWordA2DisplacementToD1);
            Append(code, fieldOffset);
            Append(code, CompareImmediateWordD1);
            Append(code, smallValue);
            Append(code, BranchEqualWord);
            var smallValueBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD1);
            Append(code, wide200Value);
            Append(code, BranchEqualWord);
            var wide200ValueBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD1);
            Append(code, wide256Value);
            Append(code, BranchEqualWord);
            var wide256ValueBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD1);
            Append(code, hires200Value);
            Append(code, BranchEqualWord);
            var hires200ValueBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD1);
            Append(code, hires256Value);
            Append(code, BranchEqualWord);
            var hires256ValueBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD1);
            Append(code, lace512Value);
            Append(code, BranchEqualWord);
            var lace512ValueBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD1);
            Append(code, hiresLace512Value);
            Append(code, BranchNotEqualWord);
            var invalidValueBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(invalidValueBranchExtensionOffset);
            PatchBranch(code, smallValueBranchExtensionOffset, code.Count);
            PatchBranch(code, wide200ValueBranchExtensionOffset, code.Count);
            PatchBranch(code, wide256ValueBranchExtensionOffset, code.Count);
            PatchBranch(code, hires200ValueBranchExtensionOffset, code.Count);
            PatchBranch(code, hires256ValueBranchExtensionOffset, code.Count);
            PatchBranch(code, lace512ValueBranchExtensionOffset, code.Count);
        }

        AppendGeneratedWordEither(6, 0x2D00, 0xF4C1);
        AppendGeneratedWordSeven(10, 0x0038, 0x0038, 0x0038, 0x003C, 0x003C, 0x0038, 0x003C);
        AppendGeneratedWordSeven(14, 0x0038, 0x00D0, 0x00D0, 0x00D4, 0x00D4, 0x00D0, 0x00D4);
        AppendGeneratedWordSeven(26, 0x1000, 0x1000, 0x1000, 0x9000, 0x9000, 0x1004, 0x9004);

        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var generatedStandardModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, GraphicsModeIds.InterlaceMode);
        Append(code, BranchEqualWord);
        var generatedInvalidModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, (ushort)(GraphicsModeIds.HiresMode | GraphicsModeIds.InterlaceMode));
        Append(code, BranchEqualWord);
        var generatedHiresInterlaceModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var generatedHiresInterlaceInvalidModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedHiresInterlaceInvalidModesBranchExtensionOffset);
        var generatedInterlaceModesCheckJoinOffset = code.Count;
        PatchBranch(code, generatedInvalidModesBranchExtensionOffset, generatedInterlaceModesCheckJoinOffset);
        PatchBranch(code, generatedHiresInterlaceModesBranchExtensionOffset, generatedInterlaceModesCheckJoinOffset);
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, 26);
        Append(code, CompareImmediateWordD1);
        Append(code, 0x1004);
        Append(code, BranchEqualWord);
        var generatedInterlaceProgramBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 0x9004);
        Append(code, BranchNotEqualWord);
        var generatedInterlaceProgramFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedInterlaceProgramFallbackBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var generatedModesJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, generatedInterlaceProgramBranchExtensionOffset, generatedModesJoinBranchExtensionOffset - 2);
        var generatedStandardModesCheckOffset = code.Count;
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, 26);
        Append(code, CompareImmediateWordD1);
        Append(code, 0x1004);
        Append(code, BranchEqualWord);
        var generatedStandardLaceProgramBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedStandardLaceProgramBranchExtensionOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 0x9004);
        Append(code, BranchEqualWord);
        var generatedStandardHiresLaceProgramBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedStandardHiresLaceProgramBranchExtensionOffset);
        var generatedModesJoinOffset = code.Count;
        PatchBranch(code, generatedStandardModesBranchExtensionOffset, generatedStandardModesCheckOffset);
        PatchBranch(code, generatedModesJoinBranchExtensionOffset, generatedModesJoinOffset);

        // Verify that the raw BPL pointer words name the single standard
        // bitmap plane.  The bitmap is reached through the already validated
        // RasInfo link; no plane bytes are read or modified.
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var generatedRasInfoNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedRasInfoNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var generatedRasInfoOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedRasInfoOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4);
        Append(code, BranchHighWord);
        var generatedRasInfoRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedRasInfoRangeBranchExtensionOffset);
        Append(code, MoveAddressD1ToA3);
        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoBitMap));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var generatedBitMapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedBitMapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var generatedBitMapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedBitMapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var generatedBitMapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedBitMapRangeBranchExtensionOffset);
        Append(code, MoveAddressD1ToA3);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD4);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var generatedStrideSmallBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 40);
        Append(code, BranchEqualWord);
        var generatedStrideWideBranchExtensionOffset = code.Count;
        Append(code, 0);
        // PAL 320x256 uses the same 40-byte row stride as the bounded
        // 320x200 form; keep a distinct branch so the geometry/row check
        // below remains an exact signature rather than a width-only claim.
        Append(code, CompareImmediateWordD4);
        Append(code, 40);
        Append(code, BranchEqualWord);
        var generatedStridePalWideBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 80);
        Append(code, BranchNotEqualWord);
        var generatedStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 80);
        Append(code, BranchEqualWord);
        var generatedStrideHiresPalBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedStrideBranchExtensionOffset);
        PatchBranch(code, generatedStrideSmallBranchExtensionOffset, code.Count);
        PatchBranch(code, generatedStrideWideBranchExtensionOffset, code.Count);
        PatchBranch(code, generatedStridePalWideBranchExtensionOffset, code.Count);
        PatchBranch(code, generatedStrideHiresPalBranchExtensionOffset, code.Count);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD4);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var generatedRowsTinyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var generatedRowsSmallBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 200);
        Append(code, BranchEqualWord);
        var generatedRowsWideBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 256);
        Append(code, BranchEqualWord);
        var generatedRowsPalWideBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 512);
        Append(code, BranchEqualWord);
        var generatedRowsPalLoresLaceBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 400);
        Append(code, BranchEqualWord);
        var generatedRowsNtscLoresLaceBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var generatedRowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedRowsBranchExtensionOffset);
        var generatedRowsJoinOffset = code.Count;
        PatchBranch(code, generatedRowsTinyBranchExtensionOffset, generatedRowsJoinOffset);
        PatchBranch(code, generatedRowsSmallBranchExtensionOffset, generatedRowsJoinOffset);
        PatchBranch(code, generatedRowsWideBranchExtensionOffset, generatedRowsJoinOffset);
        PatchBranch(code, generatedRowsPalWideBranchExtensionOffset, generatedRowsJoinOffset);
        PatchBranch(code, generatedRowsPalLoresLaceBranchExtensionOffset, generatedRowsJoinOffset);
        PatchBranch(code, generatedRowsNtscLoresLaceBranchExtensionOffset, generatedRowsJoinOffset);
        Append(code, MoveByteA3DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD1);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var generatedDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedDepthBranchExtensionOffset);
        Append(code, MoveByteA3DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, AndImmediateWordD1);
        Append(code, 0x0006);
        Append(code, TestWordD1);
        Append(code, BranchNotEqualWord);
        var generatedFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedFlagsBranchExtensionOffset);
        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, MoveLongD1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var generatedPlaneNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedPlaneNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var generatedPlaneOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedPlaneOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var generatedPlaneRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedPlaneRangeBranchExtensionOffset);

        Append(code, SwapD4);
        Append(code, MoveWordD4ToD6);
        Append(code, SwapD4);
        Append(code, MoveWordD4ToD5);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, 38);
        Append(code, CompareWordD6ToD4);
        Append(code, BranchNotEqualWord);
        var generatedPlaneHighBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedPlaneHighBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, 42);
        Append(code, CompareWordD5ToD4);
        Append(code, BranchNotEqualWord);
        var generatedPlaneLowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(generatedPlaneLowBranchExtensionOffset);

        Append(code, BranchAlwaysWord);
        var generatedSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);

        var blankCountValidationOffset = code.Count;
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, TestWordD1);
        Append(code, BranchNotEqualWord);
        var populatedCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(populatedCountBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var emptyCapacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(emptyCapacityBranchExtensionOffset);

        // The constructor's raw stream is part of the admission signature.
        Append(code, MoveAddressD6ToA2);
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, GraphicsLayouts.CopperEndWait);
        Append(code, BranchNotEqualWord);
        var invalidRawWaitBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(invalidRawWaitBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, 2);
        Append(code, CompareImmediateWordD1);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, BranchNotEqualWord);
        var invalidRawMaskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(invalidRawMaskBranchExtensionOffset);

        var emptySuccessOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        foreach (var linkOffset in new[]
        {
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        })
        {
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, checked((ushort)linkOffset));
        }
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, nullViewPortBranchExtensionOffset, emptySuccessOffset);
        PatchBranch(code, emptySuccessBranchExtensionOffset, emptySuccessOffset);
        PatchBranch(code, blankCountBranchExtensionOffset, blankCountValidationOffset);
        PatchBranch(code, generatedSuccessBranchExtensionOffset, emptySuccessOffset);

        return offset;
    }

    private static int AppendFreeCprListEmpty(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(5);

        // FreeCprList walks a NULL head and a bounded, completely zeroed
        // cprlist as successful empty forms. Any linked, populated, or
        // provider-owned resource remains on the ownership-aware fallback so
        // this body never releases storage it cannot prove belongs to it.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullListBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddListBranchExtensionOffset);

        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // cprlist + 0x0B must remain addressable
        Append(code, BranchHighWord);
        var wrappedListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedListBranchExtensionOffset);

        var longOffsets = new[]
        {
            GraphicsLayouts.CprListNext,
            GraphicsLayouts.CprListStart
        };
        foreach (var fieldOffset in longOffsets)
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)fieldOffset));
            Append(code, TestLongD0);
            Append(code, BranchNotEqualWord);
            var fieldBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(fieldBranchExtensionOffset);
        }

        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        Append(code, TestWordD0);
        Append(code, BranchNotEqualWord);
        var maxCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maxCountBranchExtensionOffset);

        var emptySuccessOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, nullListBranchExtensionOffset, emptySuccessOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    /// <summary>
    /// Frees the contiguous native ColorMap envelope after proving its private
    /// marker, exact span, count, and table pointers.  NULL is the documented
    /// successful no-op; foreign or malformed maps preserve D0 and decline to
    /// the ownership-aware fallback path.
    /// </summary>
    private static int AppendFreeColorMapNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(14);

        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x1F02); // MOVEM.L D3-D7/A6,-(A7), reversed save mask

        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddMapBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.NativeColorMapPrivatePrefixSize));
        Append(code, BranchCarryWord);
        var shortMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(shortMapBranchExtensionOffset);

        // Prove the complete public header before reading its ownership or
        // count fields, even when all table-pointer equalities are forged.
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, checked((ushort)(0x10000 - GraphicsLayouts.ColorMapSize)));
        Append(code, BranchHighWord);
        var wrappedHeaderBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedHeaderBranchExtensionOffset);

        // D5 = private allocation base; A0 remains the public map for the
        // public-field checks below.
        Append(code, MoveLongD0ToD5);
        Append(code, SubQuickFourLongD5);
        Append(code, SubQuickFourLongD5);
        Append(code, SubQuickFourLongD5);
        Append(code, MoveAddressD5ToA1);
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, GraphicsLayouts.NativeColorMapMarker);
        Append(code, BranchNotEqualWord);
        var markerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(markerBranchExtensionOffset);

        // The stored envelope size must equal 0x40 + (count * 4).  This
        // rejects a forged marker even before any Exec FreeMem call occurs.
        Append(code, MoveQuickZeroD3);
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapCount));
        Append(code, TestLongD3);
        Append(code, BranchEqualWord);
        var zeroCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(zeroCountBranchExtensionOffset);
        Append(code, MoveLongD3ToD0);
        Append(code, ShiftLeftLongD0);
        Append(code, ShiftLeftLongD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.NativeColorMapBaseSize));
        Append(code, AddLongD1ToD0);
        Append(code, MoveLongA1DisplacementToD6);
        Append(code, 4);
        Append(code, CompareLongD6ToD0);
        Append(code, BranchNotEqualWord);
        var spanBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(spanBranchExtensionOffset);

        // Matching sizes/pointers alone do not prove that the palette tail
        // fits. Check its inclusive last byte before table reads or FreeMem.
        Append(code, MoveLongD6ToD4);
        Append(code, SubQuickOneLongD4);
        Append(code, AddLongD5ToD4);
        Append(code, BranchCarryWord);
        var wrappedEnvelopeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedEnvelopeBranchExtensionOffset);

        // ColorTable must be map + ColorMapSize and LowColorBits must follow
        // its count-sized UWORD span.  Both checks are guest-address checks,
        // so an odd or unrelated table cannot be released by this arm.
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapColorTable));
        Append(code, MoveLongA0ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapSize));
        Append(code, AddLongD1ToD0);
        Append(code, CompareLongD4ToD0);
        Append(code, BranchNotEqualWord);
        var colorTableBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(colorTableBranchExtensionOffset);
        Append(code, MoveLongD3ToD1);
        Append(code, ShiftLeftLongD1);
        Append(code, AddLongD1ToD0);
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapLowColorBits));
        Append(code, CompareLongD4ToD0);
        Append(code, BranchNotEqualWord);
        var lowTableBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowTableBranchExtensionOffset);

        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveAddressD1ToA6);
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, 4);
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40F8); // MOVEM.L (A7)+,D3-D7/A6
        Append(code, ReturnFromSubroutine);

        var nullSuccessOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40F8);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        // D0's decline value lives in working D7 until this point.
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40F8);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, nullMapBranchExtensionOffset, nullSuccessOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendAllocRasterNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(8);

        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x3F02); // MOVEM.L D2-D7/A6,-(A7), reversed save mask

        // Preserve the caller's D0 across every decline and allocator
        // failure.  The public width/height arguments are UWORDs; zero the
        // temporary registers before copying their low words so stale high
        // halves cannot leak into the byte-count arithmetic.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveQuickZeroD2);
        Append(code, MoveWordD0ToD2);
        Append(code, TestWordD2);
        Append(code, BranchEqualWord);
        var zeroWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(zeroWidthBranchExtensionOffset);

        Append(code, MoveQuickZeroD3);
        Append(code, MoveWordD1ToD3);
        Append(code, TestWordD3);
        Append(code, BranchEqualWord);
        var zeroHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(zeroHeightBranchExtensionOffset);

        // Round the normalized UWORD width in LONG arithmetic. Widths
        // 65521..65535 carry into bit 16 when adding 15, so both the add
        // and the four 68000-compatible shifts must retain that bit.
        Append(code, MoveLongD2ToD6);
        Append(code, AddImmediateLongD6);
        Append(code, 0);
        Append(code, 0x000F);
        Append(code, ShiftRightLongD6);
        Append(code, ShiftRightLongD6);
        Append(code, ShiftRightLongD6);
        Append(code, ShiftRightLongD6);
        Append(code, ShiftLeftLongD6);
        Append(code, MoveQuickZeroD4);
        Append(code, AddLongD6ToD4);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordD1ToD5);
        Append(code, MultiplyUnsignedWordD4ToD5);

        // Ten-byte private header: marker (word), width (word), height
        // (word), and the complete AllocMem span (long).  The public raster
        // pointer is returned immediately after this header.
        Append(code, AddQuickOneLongD5);
        Append(code, AddQuickOneLongD5);
        Append(code, AddQuickOneLongD5);
        Append(code, AddQuickOneLongD5);
        Append(code, AddQuickOneLongD5);
        Append(code, AddQuickOneLongD5);
        Append(code, AddQuickOneLongD5);
        Append(code, AddQuickOneLongD5);
        Append(code, AddQuickOneLongD5);
        Append(code, AddQuickOneLongD5);

        // SysBase lives at absolute address four.  Exec AllocMem is called
        // with PUBLIC | CHIP | CLEAR, matching the portable chip allocator
        // and the classic raster contract.
        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0003);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var allocationFailureBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A provisional allocation must be word-aligned and its complete
        // inclusive envelope must fit before any ownership fields are
        // published. Keep D0/base and D5/size intact for exact rollback.
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD5ToD4);
        Append(code, SubQuickOneLongD4);
        Append(code, AddLongD0ToD4);
        Append(code, BranchCarryWord);
        var wrappingAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var skipAllocationCleanupBranchExtensionOffset = code.Count;
        Append(code, 0);

        var allocationCleanupOffset = code.Count;
        Append(code, MoveLongD5ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, BranchAlwaysWord);
        var allocationCleanupJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, NativeRasterMarker);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 0);
        Append(code, MoveWordD2ToA0Displacement);
        Append(code, 2);
        Append(code, MoveWordD3ToA0Displacement);
        Append(code, 4);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, 6);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickTwoLongA0);
        Append(code, MoveLongA0ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40FC); // MOVEM.L (A7)+,D2-D7/A6
        Append(code, ReturnFromSubroutine);

        var allocationFailureOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var allocationFailureJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40FC);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, allocationFailureBranchExtensionOffset, allocationFailureOffset);
        PatchBranch(code, oddAllocationBranchExtensionOffset, allocationCleanupOffset);
        PatchBranch(code, wrappingAllocationBranchExtensionOffset, allocationCleanupOffset);
        PatchBranch(code, skipAllocationCleanupBranchExtensionOffset, successOffset);
        PatchBranch(code, allocationCleanupJoinBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, allocationFailureJoinBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    /// <summary>
    /// Allocates and clears one public Region envelope through Exec.  The
    /// native path reserves a private marker longword immediately before the
    /// public structure so DisposeRegion can prove ownership without a host
    /// side registry.  The returned pointer and all public fields retain the
    /// Kickstart Region layout.  Native AndRectRegion may subsequently claim
    /// canonical marker-owned chains; allocating and provider-owned boolean
    /// forms remain on their portable/provider boundary.
    /// </summary>
    private static int AppendNewRegionNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(8);

        // Preserve the caller's D0 on every decline.  NewRegion has no
        // arguments, but a native overlay must leave the captured register
        // frame untouched when its Exec boundary is unavailable.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.NativeRegionAllocationSize));
        Append(code, MoveLongD0ToD5);

        // SysBase lives at absolute address four.  Exec AllocMem is called
        // with PUBLIC | CLEAR, matching the portable NewRegion contract.
        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0001); // PUBLIC | CLEAR
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var allocationFailureBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Exec promises word alignment.  A violating provider is cleaned up
        // and made available to the fallback owner instead of publishing an
        // odd public Region pointer.
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var skipOddAllocationCleanupBranchExtensionOffset = code.Count;
        Append(code, 0);

        var oddAllocationCleanupOffset = code.Count;
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0000);
        Append(code, 0x0001); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, BranchAlwaysWord);
        var oddAllocationJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.NativeRegionMarker);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 0);
        Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0);
        Append(code, MoveLongA0ToD0);
        Append(code, ReturnFromSubroutine);

        var allocationFailureOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var allocationFailureJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, allocationFailureBranchExtensionOffset, allocationFailureOffset);
        PatchBranch(code, oddAllocationBranchExtensionOffset, oddAllocationCleanupOffset);
        PatchBranch(code, skipOddAllocationCleanupBranchExtensionOffset, successOffset);
        PatchBranch(code, oddAllocationJoinBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, allocationFailureJoinBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    /// <summary>
    /// Tears down a Region allocated by AppendNewRegionNative.  The public
    /// RegionRectangle chain is walked and each node is released through the
    /// same Exec boundary before the private-prefix allocation is released.
    /// A missing/foreign/odd marker declines with the original D0 intact so a
    /// provider or older graphics owner can retain the call.
    /// </summary>
    private static int AppendDisposeRegionNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(8);

        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullRegionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullRegionBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRegionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRegionBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 4);
        Append(code, BranchCarryWord);
        var shortRegionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(shortRegionBranchExtensionOffset);

        // D5 retains the original public pointer minus the private prefix;
        // A1 points at that private allocation base for the marker check.
        Append(code, MoveLongD0ToD5);
        Append(code, SubQuickFourLongD5);
        Append(code, MoveAddressD5ToA1);
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, GraphicsLayouts.NativeRegionMarker);
        Append(code, BranchNotEqualWord);
        var markerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(markerBranchExtensionOffset);

        // Keep the public Region pointer in A2 while D0 walks the linked
        // RegionRectangle nodes.  A bounded DBRA guard prevents a malformed
        // chain from turning teardown into an unbounded native loop.
        Append(code, MoveAddressA1ToA0);
        Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0);
        Append(code, MoveAddressA0ToA2);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, MoveLongImmediateD6);
        Append(code, 0);
        Append(code, 0x0FFF);

        // Resolve ExecBase only after the ownership marker has been proven;
        // a foreign Region therefore never observes an Exec call.
        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveAddressD1ToA6);

        var freeNodeLoopOffset = code.Count;
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var noMoreNodesBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleSize));
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0000);
        Append(code, 0x0001); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongD4ToD0);
        Append(code, DecrementBranchD6);
        var nodeLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var freeRegionOffset = code.Count;
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.NativeRegionAllocationSize));
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0000);
        Append(code, 0x0001); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, noMoreNodesBranchExtensionOffset, freeRegionOffset);
        PatchBranch(code, nodeLoopBranchExtensionOffset, freeNodeLoopOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    /// <summary>
    /// Clears a native Region in place.  It shares the private-prefix marker
    /// and bounded RegionRectangle teardown with DisposeRegion, but retains
    /// the public Region allocation for subsequent boolean operations.
    /// </summary>
    private static int AppendClearRegionNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(8);

        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullRegionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullRegionBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRegionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRegionBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 4);
        Append(code, BranchCarryWord);
        var shortRegionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(shortRegionBranchExtensionOffset);

        Append(code, MoveLongD0ToD5);
        Append(code, SubQuickFourLongD5);
        Append(code, MoveAddressD5ToA1);
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, GraphicsLayouts.NativeRegionMarker);
        Append(code, BranchNotEqualWord);
        var markerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(markerBranchExtensionOffset);

        Append(code, MoveAddressA0ToA2);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, MoveLongImmediateD6);
        Append(code, 0);
        Append(code, 0x0FFF);

        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveAddressD1ToA6);

        var freeNodeLoopOffset = code.Count;
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var noMoreNodesBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleSize));
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0000);
        Append(code, 0x0001); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongD4ToD0);
        Append(code, DecrementBranchD6);
        var nodeLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var publishEmptyOffset = code.Count;
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RegionBounds));
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)(GraphicsLayouts.RegionBounds + 4)));
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, noMoreNodesBranchExtensionOffset, publishEmptyOffset);
        PatchBranch(code, nodeLoopBranchExtensionOffset, freeNodeLoopOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    /// <summary>
    /// Unions a Rectangle into a native-owned Region. Canonical one-node
    /// sources support containment, coalescing, and selected two/three-node
    /// replacement transactions; other shapes retain the portable builder.
    /// </summary>
    private static int AppendOrRectRegionEmptyNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(20);
        var expansionBranches = new List<int>(4);
        var disjointBranches = new List<int>(4);
        var lShapeBranches = new List<int>(8);
        var mirroredLShapeBranches = new List<int>(6);
        var lowerLeftLShapeBranches = new List<int>(6);
        var lowerRightLShapeBranches = new List<int>(6);
        var crossingBarBranches = new List<int>(4);
        var verticalBarBranches = new List<int>(4);
        var leftTBarBranches = new List<int>(4);
        var rightTBarBranches = new List<int>(4);
        var topTBarBranches = new List<int>(5);
        var bottomTBarBranches = new List<int>(5);
        var oldTopTStemBranches = new List<int>(5);
        var oldBottomTStemBranches = new List<int>(5);
        var oldLeftTStemBranches = new List<int>(4);
        var oldRightTStemBranches = new List<int>(4);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitFreeNode(ushort moveNodeToA0)
        {
            Append(code, moveNodeToA0);
            Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
            AppendExecFreeMemFromA0PreservingA1(code);
        }

        void EmitWriteRelativeBounds()
        {
            // D0..D3 are the new absolute Region bounds and D4..D7 are one
            // absolute result rectangle. Each caller proves the source
            // offsets or complete envelope before allocating any node.
            Append(code, SubWordD0ToD4);
            Append(code, MoveWordD4ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, SubWordD1ToD5);
            Append(code, MoveWordD5ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, SubWordD0ToD6);
            Append(code, MoveWordD6ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, SubWordD1ToD7);
            Append(code, MoveWordD7ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        }

        void EmitFirstNodeLinks()
        {
            Append(code, MoveAddressA3ToA0);
            Append(code, MoveLongA4ToD6);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveAddressA5ToA0);
            Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
            Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
            Append(code, MoveLongA0ToD6);
            Append(code, MoveAddressA3ToA0);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        }

        void EmitSecondNodeLinks()
        {
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveQuickZeroD6);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveLongA3ToD6);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        }

        void EmitLShapeNodeLinks()
        {
            // A3, A4 and A2 are the already validated first, second and
            // third replacement nodes.  Link the complete list before the
            // Region header makes it reachable.
            Append(code, MoveAddressA3ToA0);
            Append(code, MoveLongA4ToD6);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveAddressA5ToA0);
            Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
            Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
            Append(code, MoveLongA0ToD6);
            Append(code, MoveAddressA3ToA0);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);

            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongA2ToD6);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveLongA3ToD6);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);

            Append(code, MoveAddressA2ToA0);
            Append(code, MoveQuickZeroD6);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveLongA4ToD6);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        }

        void EmitLShapeFirstBounds()
        {
            // [header.minX, header.minY .. header.maxX, input.minY - 1]
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveWordA1DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveQuickZeroD4); Append(code, MoveQuickZeroD5);
            Append(code, SubWordD0ToD6);
            Append(code, SubWordD1ToD7); Append(code, SubQuickOneWordD7);
            Append(code, MoveAddressA3ToA0);
            Append(code, MoveWordD4ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordD5ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD7ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        }

        void EmitLShapeSecondBounds()
        {
            // [header.minX, input.minY .. input.maxX, header.maxY]
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA0DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveQuickZeroD4);
            Append(code, SubWordD1ToD5);
            Append(code, SubWordD0ToD6);
            Append(code, SubWordD1ToD7);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveWordD4ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordD5ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD7ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        }

        void EmitLShapeThirdBounds()
        {
            // [input.minX, header.maxY + 1 .. input.maxX, input.maxY]
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveWordA1DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, SubWordD0ToD4);
            Append(code, SubWordD1ToD5); Append(code, AddQuickOneWordD5);
            Append(code, SubWordD0ToD6);
            Append(code, SubWordD1ToD7);
            Append(code, MoveAddressA2ToA0);
            Append(code, MoveWordD4ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordD5ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD7ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        }

        void EmitMirroredLShapeFirstBounds()
        {
            // [header.minX, header.minY .. header.maxX, input.minY - 1]
            // relative to the mirrored union's input.minX/header.minY origin.
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA1DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveQuickZeroD5);
            Append(code, SubWordD4ToD0);
            Append(code, SubWordD4ToD6);
            Append(code, SubWordD1ToD7); Append(code, SubQuickOneWordD7);
            Append(code, MoveAddressA3ToA0);
            Append(code, MoveWordD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordD5ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD7ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        }

        void EmitMirroredLShapeSecondBounds()
        {
            // [input.minX, input.minY .. header.maxX, header.maxY]
            // relative to the mirrored union's input.minX/header.minY origin.
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveWordA0DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveQuickZeroD0);
            Append(code, SubWordD1ToD5);
            Append(code, SubWordD4ToD6);
            Append(code, SubWordD1ToD7);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveWordD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordD5ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD7ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        }

        void EmitMirroredLShapeThirdBounds()
        {
            // [input.minX, header.maxY + 1 .. input.maxX, input.maxY]
            // relative to the mirrored union's input.minX/header.minY origin.
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, MoveQuickZeroD7);
            Append(code, SubWordD1ToD5); Append(code, AddQuickOneWordD5);
            Append(code, SubWordD4ToD0);
            Append(code, SubWordD1ToD6);
            Append(code, MoveAddressA2ToA0);
            Append(code, MoveWordD7ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordD5ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD0ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        }

        void EmitLowerLeftLShapeFirstBounds()
        {
            // [input.minX, input.minY .. input.maxX, header.minY - 1]
            // relative to the lower-left union's header.minX/input.minY origin.
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveQuickZeroD5);
            Append(code, SubWordD0ToD4);
            Append(code, SubWordD0ToD6);
            Append(code, MoveWordA0DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, SubWordD0ToD7); Append(code, SubQuickOneWordD7);
            Append(code, MoveAddressA3ToA0);
            Append(code, MoveWordD4ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordD5ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD7ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
