        void EmitInputSpanningYEnvelope()
        {
            // D0..D3 are old bounds and D4..D7 input bounds. The admitted
            // input strictly spans both old Y edges; connected X intervals
            // form either the vertical crossing bar or an old horizontal T
            // stem. Keep the union envelope in D0..D3 without source swaps.
            Append(code, CompareWordD4ToD0); Append(code, BranchLessOrEqualWord);
            var keepMinX = code.Count; Append(code, 0);
            Append(code, MoveWordD4ToD0);
            PatchBranch(code, keepMinX, code.Count);
            Append(code, CompareWordD6ToD2); Append(code, BranchGreaterOrEqualWord);
            var keepMaxX = code.Count; Append(code, 0);
            Append(code, MoveWordD6ToD2);
            PatchBranch(code, keepMaxX, code.Count);
            Append(code, MoveWordD5ToD1);
            Append(code, MoveWordD7ToD3);
        }

        void EmitInputSpanningYBounds()
        {
            // The allocation frame saves source identities, not geometry.
            // Reconstruct exactly the envelope checked before AllocMem.
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            EmitLoadInputToD4ThroughD7();
            EmitInputSpanningYEnvelope();

            // Top: complete input X span, ending just before the old stem.
            EmitLoadInputToD4ThroughD7();
            Append(code, MoveWordA0DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, SubQuickOneWordD7);
            Append(code, MoveAddressA3ToA0);
            EmitWriteRelativeBounds();

            // Middle: the connected union X span throughout the old Y span.
            Append(code, MoveAddressA5ToA0);
            EmitLoadHeaderToD4ThroughD7();
            Append(code, MoveWordD0ToD4);
            Append(code, MoveWordD2ToD6);
            Append(code, MoveAddressA4ToA0);
            EmitWriteRelativeBounds();

            // Bottom: complete input X span after the old stem. Strict Y
            // containment proves both absolute endpoint adjustments safe;
            // every relative word stays inside the preflighted envelope.
            EmitLoadInputToD4ThroughD7();
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, AddQuickOneWordD5);
            Append(code, MoveAddressA2ToA0);
            EmitWriteRelativeBounds();
        }

        void EmitLoadHeaderToD4ThroughD7()
        {
            Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveWordA0DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        }

        void EmitLoadInputToD4ThroughD7()
        {
            Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveWordA1DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        }

        // A decline may occur after D7 receives rectangle.maxY, so retain the
        // captured portable frame on the stack rather than in a scratch
        // register. Every direct return below consumes this word too.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA0ToD0);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
        Decline(BranchHighWord);
        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF8);
        Decline(BranchHighWord);

        Append(code, MoveLongA0ToD0);
        Append(code, SubQuickFourLongD0);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveWordA3DisplacementToD0); Append(code, 0);
        Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var nonEmptyBranchExtensionOffset = code.Count; Append(code, 0);

        // D4/D5/D6/D7 retain input minX/minY/maxX/maxY across Exec.
        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD6); Decline(BranchLessThanWord);
        Append(code, CompareWordD5ToD7); Decline(BranchLessThanWord);

        Append(code, MoveWordD6ToD0); Append(code, SubWordD4ToD0);
        Decline(BranchOverflowWord);
        Append(code, MoveWordD7ToD0); Append(code, SubWordD5ToD0);
        Decline(BranchOverflowWord);
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 1); Append(code, 1);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        // The success continuation follows the inline FALSE cleanup, so a
        // nonzero AllocMem result must branch over that cleanup.
        Append(code, TestLongD0); Append(code, BranchNotEqualWord);
        var allocationSucceededExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0); Append(code, ReturnFromSubroutine); // allocation failure returns FALSE

        var allocationSucceededOffset = code.Count;
        PatchBranch(code, allocationSucceededExtensionOffset, allocationSucceededOffset);
        // An Exec provider must return a public, word-aligned allocation.
        // Do not hand a bad result to the portable path: release it first so
        // the fallback can allocate and own its own replacement node.
        Append(code, BitTestImmediateD0); Append(code, 0);
        Append(code, BranchEqualWord);
        var evenAllocationBranchExtensionOffset = code.Count; Append(code, 0);
        var badAllocationCleanupOffset = code.Count;
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0); Append(code, ReturnFromSubroutine);

        var evenAllocationOffset = code.Count;
        PatchBranch(code, evenAllocationBranchExtensionOffset, evenAllocationOffset);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchLowerOrSameWord);
        var addressableAllocationBranchExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var badHighAllocationBranchExtensionOffset = code.Count; Append(code, 0);
        var addressableAllocationOffset = code.Count;
        PatchBranch(code, addressableAllocationBranchExtensionOffset, addressableAllocationOffset);
        Append(code, MoveAddressD0ToA2);

        // Initialize the node before making it visible from Region.Rectangle.
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA2Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressA0ToA3); Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToA2Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToA2Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD0ToA2Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD6ToD0); Append(code, SubWordD4ToD0);
        Append(code, MoveWordD0ToA2Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD7ToD0); Append(code, SubWordD5ToD0);
        Append(code, MoveWordD0ToA2Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

        Append(code, MoveWordD4ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordD5ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
