        Append(code, MoveWordD2ToD6); Append(code, SubWordD4ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordD5ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
        Append(code, SubQuickOneWordD6);
        Append(code, MoveWordD5ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
