        var firstAllocationBadExtensionOffset = code.Count; Append(code, 0);
        var firstAllocationEvenOffset = code.Count;
        PatchBranch(code, firstAllocationEvenExtensionOffset, firstAllocationEvenOffset);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchLowerOrSameWord);
        var firstAllocationAddressableExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var firstAllocationHighExtensionOffset = code.Count; Append(code, 0);
        var firstAllocationAddressableOffset = code.Count;
        PatchBranch(code, firstAllocationAddressableExtensionOffset, firstAllocationAddressableOffset);

        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0); Append(code, BranchNotEqualWord);
        var secondAllocationSucceededExtensionOffset = code.Count; Append(code, 0);
        var secondAllocationFailedOffset = code.Count;
        EmitFreeNode(MoveAddressA3ToA0);
        for (var index = 0; index < 5; index++)
            Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0); Append(code, ReturnFromSubroutine);

        var secondAllocationSucceededOffset = code.Count;
        PatchBranch(code, secondAllocationSucceededExtensionOffset, secondAllocationSucceededOffset);
        Append(code, MoveAddressD0ToA4);
        Append(code, BitTestImmediateD0); Append(code, 0);
        Append(code, BranchEqualWord);
        var secondAllocationEvenExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var secondAllocationBadExtensionOffset = code.Count; Append(code, 0);
        var secondAllocationEvenOffset = code.Count;
        PatchBranch(code, secondAllocationEvenExtensionOffset, secondAllocationEvenOffset);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchLowerOrSameWord);
        var secondAllocationAddressableExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var secondAllocationHighExtensionOffset = code.Count; Append(code, 0);
        var secondAllocationAddressableOffset = code.Count;
        PatchBranch(code, secondAllocationAddressableExtensionOffset, secondAllocationAddressableOffset);

        // Restore the input pointer and bounds once both allocations are
        // known usable. A3 and A4 are first and second list nodes, not source
        // identities; their contents are selected by canonical sort order.
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);
        Append(code, MoveLongA7PostIncrementToD3);
        Append(code, MoveLongA7PostIncrementToD2);
        Append(code, MoveLongA7PostIncrementToD1);
        Append(code, MoveLongA7PostIncrementToD0);

        // Shared-Y-edge geometry is selected before sorting the two sources:
        // its first canonical band can be wider than either whole source.
        // D4/D5 are scratch; preserve the checked D0..D3 envelope and recheck
        // X connectivity so a genuine gap still uses the disjoint writer.
        var ordinaryTwoNodeWriterBranches = new List<int>(4);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD5ToD4); Append(code, BranchGreaterOrEqualWord);
        var sharedYHeaderGeometryOverlapsExtensionOffset = code.Count; Append(code, 0);
        Append(code, AddQuickOneWordD4);
        Append(code, CompareWordD5ToD4); Append(code, BranchNotEqualWord);
        ordinaryTwoNodeWriterBranches.Add(code.Count); Append(code, 0);
        PatchBranch(code, sharedYHeaderGeometryOverlapsExtensionOffset, code.Count);
        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD5ToD4); Append(code, BranchGreaterOrEqualWord);
        var sharedYInputGeometryOverlapsExtensionOffset = code.Count; Append(code, 0);
        Append(code, AddQuickOneWordD4);
        Append(code, CompareWordD5ToD4); Append(code, BranchNotEqualWord);
        ordinaryTwoNodeWriterBranches.Add(code.Count); Append(code, 0);
        PatchBranch(code, sharedYInputGeometryOverlapsExtensionOffset, code.Count);

        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, CompareWordD5ToD4); Append(code, BranchNotEqualWord);
        var trySharedMaximumYGeometryExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD5ToD4); Append(code, BranchLessThanWord);
        var sharedMinimumHeaderEndsFirstExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchGreaterThanWord);
        var sharedMinimumInputEndsFirstExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        ordinaryTwoNodeWriterBranches.Add(code.Count); Append(code, 0);

        PatchBranch(code, trySharedMaximumYGeometryExtensionOffset, code.Count);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD5ToD4); Append(code, BranchNotEqualWord);
        ordinaryTwoNodeWriterBranches.Add(code.Count); Append(code, 0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, CompareWordD5ToD4); Append(code, BranchLessThanWord);
        var sharedMaximumHeaderStartsFirstExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchGreaterThanWord);
        var sharedMaximumInputStartsFirstExtensionOffset = code.Count; Append(code, 0);

        foreach (var branch in ordinaryTwoNodeWriterBranches)
            PatchBranch(code, branch, code.Count);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, CompareWordD5ToD4); Append(code, BranchLessThanWord);
        var headerFirstYExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD5ToD4); Append(code, BranchGreaterThanWord);
        var inputFirstYExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD5ToD4); Append(code, BranchLessThanWord);
        var headerFirstXExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var inputFirstXExtensionOffset = code.Count; Append(code, 0);

        var inputFirstOffset = code.Count;
        // Shared-Y-edge sources have already selected a geometry body.
        // The remaining transaction admits disjoint sources or a vertical T.
        // Input-first order, contained X, and overlapping Y identify top T;
        // clip its first node to the exposed stem before the old rectangle.
        // D0..D3 remain the preflighted result envelope throughout dispatch.
        var oldBottomTStemWriterBranches = new List<int>(3);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD5); Append(code, BranchLessThanWord);
        oldBottomTStemWriterBranches.Add(code.Count); Append(code, 0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD5ToD4); Append(code, BranchGreaterThanWord);
        oldBottomTStemWriterBranches.Add(code.Count); Append(code, 0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, CompareWordD5ToD4); Append(code, BranchLessThanWord);
        oldBottomTStemWriterBranches.Add(code.Count); Append(code, 0);

        PatchBranch(code, sharedMaximumInputStartsFirstExtensionOffset, code.Count);
        EmitFirstNodeLinks();
        EmitLoadInputToD4ThroughD7();
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveWordA0DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, SubQuickOneWordD7);
        Append(code, MoveAddressA3ToA0);
        EmitWriteRelativeBounds();
        EmitSecondNodeLinks();
        Append(code, MoveAddressA5ToA0);
        EmitLoadHeaderToD4ThroughD7();
        // A vertical T's bar already has this X span. A shared-Y-edge
        // union instead widens the same band to the checked union envelope.
        Append(code, MoveWordD0ToD4); Append(code, MoveWordD2ToD6);
        Append(code, MoveAddressA4ToA0);
        EmitWriteRelativeBounds();
        Append(code, BranchAlwaysWord);
        var publishTopTBarExtensionOffset = code.Count; Append(code, 0);

        foreach (var branchExtensionOffset in oldBottomTStemWriterBranches)
            PatchBranch(code, branchExtensionOffset, code.Count);
        // Input-first order with the opposite X containment identifies the
        // old bottom stem. Check Y overlap again so adjacency and real gaps
        // retain the original disjoint geometry rather than clipping it.
        var disjointInputFirstBranches = new List<int>(3);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD5); Append(code, BranchLessThanWord);
        disjointInputFirstBranches.Add(code.Count); Append(code, 0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD5ToD4); Append(code, BranchLessThanWord);
        disjointInputFirstBranches.Add(code.Count); Append(code, 0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, CompareWordD5ToD4); Append(code, BranchGreaterThanWord);
        disjointInputFirstBranches.Add(code.Count); Append(code, 0);

        PatchBranch(code, sharedMinimumInputEndsFirstExtensionOffset, code.Count);
        EmitFirstNodeLinks();
        EmitLoadInputToD4ThroughD7();
        Append(code, MoveWordD0ToD4); Append(code, MoveWordD2ToD6);
        Append(code, MoveAddressA3ToA0);
        EmitWriteRelativeBounds();
        EmitSecondNodeLinks();
        Append(code, MoveAddressA5ToA0);
        EmitLoadHeaderToD4ThroughD7();
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        // input.maxY < header.maxY proves +1 is an absolute signed word;
        // the clipped endpoint is also inside the checked source envelope.
        Append(code, AddQuickOneWordD5);
        Append(code, MoveAddressA4ToA0);
        EmitWriteRelativeBounds();
        Append(code, BranchAlwaysWord);
        var publishOldBottomTStemExtensionOffset = code.Count; Append(code, 0);

        foreach (var branchExtensionOffset in disjointInputFirstBranches)
            PatchBranch(code, branchExtensionOffset, code.Count);
        EmitFirstNodeLinks();
        EmitLoadInputToD4ThroughD7();
        Append(code, MoveAddressA3ToA0);
        EmitWriteRelativeBounds();
        EmitSecondNodeLinks();
        Append(code, MoveAddressA5ToA0);
        EmitLoadHeaderToD4ThroughD7();
        Append(code, MoveAddressA4ToA0);
        EmitWriteRelativeBounds();
        Append(code, BranchAlwaysWord);
        var publishDisjointExtensionOffset = code.Count; Append(code, 0);

        var headerFirstOffset = code.Count;
        // Header-first order with a contained X span and overlapping Y
        // identifies the bottom T. Disjoint input must retain its original
        // MinY so neither adjacency nor a real gap is accidentally filled.
        var oldTopTStemWriterBranches = new List<int>(3);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, CompareWordD4ToD5); Append(code, BranchGreaterThanWord);
        oldTopTStemWriterBranches.Add(code.Count); Append(code, 0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD5ToD4); Append(code, BranchGreaterThanWord);
        oldTopTStemWriterBranches.Add(code.Count); Append(code, 0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, CompareWordD5ToD4); Append(code, BranchLessThanWord);
        oldTopTStemWriterBranches.Add(code.Count); Append(code, 0);

        PatchBranch(code, sharedMinimumHeaderEndsFirstExtensionOffset, code.Count);
        EmitFirstNodeLinks();
        Append(code, MoveAddressA5ToA0);
        EmitLoadHeaderToD4ThroughD7();
        Append(code, MoveWordD0ToD4); Append(code, MoveWordD2ToD6);
        Append(code, MoveAddressA3ToA0);
        EmitWriteRelativeBounds();
        EmitSecondNodeLinks();
        EmitLoadInputToD4ThroughD7();
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        // Admission proves header.maxY < input.maxY, so +1 cannot wrap.
        Append(code, AddQuickOneWordD5);
        Append(code, MoveAddressA4ToA0);
        EmitWriteRelativeBounds();
        Append(code, BranchAlwaysWord);
        var publishBottomTBarExtensionOffset = code.Count; Append(code, 0);

        foreach (var branchExtensionOffset in oldTopTStemWriterBranches)
            PatchBranch(code, branchExtensionOffset, code.Count);
        // With the input's wider X span, header-first order identifies the
        // old top stem. A disjoint source must keep its untrimmed endpoint.
        var disjointHeaderFirstBranches = new List<int>(3);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, CompareWordD4ToD5); Append(code, BranchGreaterThanWord);
        disjointHeaderFirstBranches.Add(code.Count); Append(code, 0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD5ToD4); Append(code, BranchLessThanWord);
        disjointHeaderFirstBranches.Add(code.Count); Append(code, 0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, CompareWordD5ToD4); Append(code, BranchGreaterThanWord);
        disjointHeaderFirstBranches.Add(code.Count); Append(code, 0);

        PatchBranch(code, sharedMaximumHeaderStartsFirstExtensionOffset, code.Count);
        EmitFirstNodeLinks();
        Append(code, MoveAddressA5ToA0);
        EmitLoadHeaderToD4ThroughD7();
        Append(code, MoveWordA1DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        // header.minY < input.minY proves -1 cannot wrap, and this endpoint
        // remains between the already preflighted old Y endpoints.
        Append(code, SubQuickOneWordD7);
        Append(code, MoveAddressA3ToA0);
        EmitWriteRelativeBounds();
        EmitSecondNodeLinks();
        EmitLoadInputToD4ThroughD7();
        Append(code, MoveWordD0ToD4); Append(code, MoveWordD2ToD6);
        Append(code, MoveAddressA4ToA0);
        EmitWriteRelativeBounds();
        Append(code, BranchAlwaysWord);
        var publishOldTopTStemExtensionOffset = code.Count; Append(code, 0);

        foreach (var branchExtensionOffset in disjointHeaderFirstBranches)
            PatchBranch(code, branchExtensionOffset, code.Count);
        EmitFirstNodeLinks();
        Append(code, MoveAddressA5ToA0);
        EmitLoadHeaderToD4ThroughD7();
        Append(code, MoveAddressA3ToA0);
        EmitWriteRelativeBounds();
        EmitSecondNodeLinks();
        EmitLoadInputToD4ThroughD7();
        Append(code, MoveAddressA4ToA0);
        EmitWriteRelativeBounds();

        var publishDisjointOffset = code.Count;
        PatchBranch(code, publishDisjointExtensionOffset, publishDisjointOffset);
        PatchBranch(code, publishTopTBarExtensionOffset, publishDisjointOffset);
        PatchBranch(code, publishBottomTBarExtensionOffset, publishDisjointOffset);
        PatchBranch(code, publishOldBottomTStemExtensionOffset, publishDisjointOffset);
        PatchBranch(code, publishOldTopTStemExtensionOffset, publishDisjointOffset);
        // Both nodes are fully initialized and linked before the Region
        // header points at the replacement list. Only after that publication
        // can the obsolete canonical node be released.
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveWordD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordD1ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordD2ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordD3ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveLongA3ToD6);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        EmitFreeNode(MoveAddressA2ToA0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var firstAllocationBadOffset = code.Count;
        PatchBranch(code, firstAllocationBadExtensionOffset, firstAllocationBadOffset);
        PatchBranch(code, firstAllocationHighExtensionOffset, firstAllocationBadOffset);
        EmitFreeNode(MoveAddressA3ToA0);
        for (var index = 0; index < 5; index++)
            Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0); Append(code, ReturnFromSubroutine);

        var secondAllocationBadOffset = code.Count;
        PatchBranch(code, secondAllocationBadExtensionOffset, secondAllocationBadOffset);
        PatchBranch(code, secondAllocationHighExtensionOffset, secondAllocationBadOffset);
        EmitFreeNode(MoveAddressA4ToA0);
        EmitFreeNode(MoveAddressA3ToA0);
        for (var index = 0; index < 5; index++)
            Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, nonEmptyBranchExtensionOffset, nonEmptyOffset);
        foreach (var branchExtensionOffset in expansionBranches)
            PatchBranch(code, branchExtensionOffset, expansionOffset);
        PatchBranch(code, nonHorizontalCoalesceYMinExtensionOffset, verticalCoalesceOffset);
        PatchBranch(code, nonHorizontalCoalesceYMaxExtensionOffset, verticalCoalesceOffset);
        PatchBranch(code, nonHorizontalCoalesceLeftExtensionOffset, verticalCoalesceOffset);
        PatchBranch(code, nonHorizontalCoalesceRightExtensionOffset, verticalCoalesceOffset);
        PatchBranch(code, nonVerticalCoalesceXMinExtensionOffset, containingInputOffset);
        PatchBranch(code, nonVerticalCoalesceXMaxExtensionOffset, containingInputOffset);
        PatchBranch(code, nonVerticalCoalesceTopExtensionOffset, containingInputOffset);
        PatchBranch(code, nonVerticalCoalesceBottomExtensionOffset, containingInputOffset);
        foreach (var branchExtensionOffset in lShapeBranches)
            PatchBranch(code, branchExtensionOffset, mirroredLShapeSelectorOffset);
        foreach (var branchExtensionOffset in mirroredLShapeBranches)
            PatchBranch(code, branchExtensionOffset, lowerLeftLShapeSelectorOffset);
        foreach (var branchExtensionOffset in lowerLeftLShapeBranches)
            PatchBranch(code, branchExtensionOffset, lowerRightLShapeSelectorOffset);
        foreach (var branchExtensionOffset in lowerRightLShapeBranches)
            PatchBranch(code, branchExtensionOffset, crossingBarSelectorOffset);
        foreach (var branchExtensionOffset in crossingBarBranches)
            PatchBranch(code, branchExtensionOffset, verticalBarSelectorOffset);
        foreach (var branchExtensionOffset in verticalBarBranches)
            PatchBranch(code, branchExtensionOffset, leftTBarSelectorOffset);
        foreach (var branchExtensionOffset in leftTBarBranches)
            PatchBranch(code, branchExtensionOffset, rightTBarSelectorOffset);
        foreach (var branchExtensionOffset in rightTBarBranches)
            PatchBranch(code, branchExtensionOffset, topTBarSelectorOffset);
        foreach (var branchExtensionOffset in topTBarBranches)
            PatchBranch(code, branchExtensionOffset, bottomTBarSelectorOffset);
        foreach (var branchExtensionOffset in bottomTBarBranches)
            PatchBranch(code, branchExtensionOffset, oldTopTStemSelectorOffset);
        foreach (var branchExtensionOffset in oldTopTStemBranches)
            PatchBranch(code, branchExtensionOffset, oldBottomTStemSelectorOffset);
        foreach (var branchExtensionOffset in oldBottomTStemBranches)
            PatchBranch(code, branchExtensionOffset, oldLeftTStemSelectorOffset);
        foreach (var branchExtensionOffset in oldLeftTStemBranches)
            PatchBranch(code, branchExtensionOffset, oldRightTStemSelectorOffset);
        foreach (var branchExtensionOffset in oldRightTStemBranches)
            PatchBranch(code, branchExtensionOffset, sharedYBandSelectorOffset);
        PatchBranch(code, oldRightTStemGapFallbackExtensionOffset, genericPartialOverlapOffset);
        foreach (var branchExtensionOffset in disjointBranches)
            PatchBranch(code, branchExtensionOffset, twoNodeListGrowthOffset);
        PatchBranch(code, headerFirstYExtensionOffset, headerFirstOffset);
        PatchBranch(code, inputFirstYExtensionOffset, inputFirstOffset);
        PatchBranch(code, headerFirstXExtensionOffset, headerFirstOffset);
        PatchBranch(code, inputFirstXExtensionOffset, inputFirstOffset);
        PatchBranch(code, badHighAllocationBranchExtensionOffset, badAllocationCleanupOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Clears a canonical four-node destination for an empty native source
    /// Region. The continuation is read-only until the complete topology and
    /// relative envelope proof succeeds; then all four public nodes are
    /// stacked, freed tail-to-head, and the destination header is published
    /// empty. Every decline restores the caller's saved D0 frame.
    /// </summary>
    private static int AppendAndRegionRegionFourNodeEmptySourceNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(48);
        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitRelativeBoundsValidation(ushort moveNodeToA2)
        {
            if (moveNodeToA2 != 0)
                Append(code, moveNodeToA2);
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA1DisplacementToD6);
            Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA1DisplacementToD6);
            Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        // Entry state: A2/A3/A4 are nodes one/two/three and D0 is node four.
        Append(code, BitTestImmediateD0); Append(code, 0);
        Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA6ToD7); // preserve the first node for ordering
        Append(code, MoveAddressA5ToA6); // A6 now retains node four

        // The fourth node is terminal and points back to the third.
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA4ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        // The third successor and all predecessor links must agree.
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, MoveLongA6ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA1ToA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, MoveLongA5ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        // Prove the public envelope and all four relative rectangles.
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitRelativeBoundsValidation(0);
        EmitRelativeBoundsValidation(MoveAddressA3ToA2);
        EmitRelativeBoundsValidation(MoveAddressA4ToA2);
        EmitRelativeBoundsValidation(MoveAddressA6ToA2);

        // Relative validation leaves A2 at node four; restore node one from D7
        // before proving the strict vertical gaps.
        Append(code, MoveAddressD7ToA2);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA3DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA4DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);
        Append(code, MoveWordA4DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA6DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);

        // Resolve Exec, stack all nodes below the saved caller D0, and free
        // the chain tail-to-head before publishing the empty destination.
        Append(code, MoveAddressA6ToA5); // preserve node four across Exec lookup
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA2ToPreDecrementA7);
        Append(code, MoveLongA3ToPreDecrementA7);
        Append(code, MoveLongA4ToPreDecrementA7);
        Append(code, MoveLongA5ToPreDecrementA7);

        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);

        Append(code, MoveAddressA1ToA0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionBounds);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionBounds + 4));
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Clears a canonical three-node destination when the native source Region
    /// is empty.  The complete chain is admitted before resolving Exec or
    /// retiring any public node; all three node pointers are stacked so a
    /// FreeMem gateway cannot expose a partially published result.  Any
    /// malformed link, envelope, relative bound, or missing Exec base restores
    /// the caller's D0 frame and enters the established portable fallback.
    /// </summary>
    private static int AppendAndRegionRegionThreeNodeEmptySourceNative(
        List<byte> code,
        int fallbackEntryOffset,
        List<int>? fourNodeDestinationBranches = null)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(40);
        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitRelativeBoundsValidation(ushort moveNodeToA2)
        {
            if (moveNodeToA2 != 0)
                Append(code, moveNodeToA2);
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA1DisplacementToD6);
            Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA1DisplacementToD6);
            Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        // The caller has already admitted A2/A3 and D0 is the third node.
        Append(code, MoveAddressA2ToA6);
        Append(code, BitTestImmediateD0); Append(code, 0);
        Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveAddressD0ToA4);

        // The third node terminates the chain and points back to the second.
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0);
        if (fourNodeDestinationBranches is not null)
        {
            Append(code, BranchNotEqualWord);
            fourNodeDestinationBranches.Add(code.Count);
            Append(code, 0);
        }
        else
        {
            Decline(BranchNotEqualWord);
        }
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        // Validate the first sentinel and the second predecessor before any
        // relative rectangle read.
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA1ToA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, MoveLongA5ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        // Prove the public envelope and every relative node rectangle.
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitRelativeBoundsValidation(0);
        EmitRelativeBoundsValidation(MoveAddressA3ToA2);
        EmitRelativeBoundsValidation(MoveAddressA4ToA2);

        // Relative validation leaves A2 at the third node; restore the first
        // node retained in A6 before proving strict vertical ordering.
        Append(code, MoveAddressA6ToA2);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA3DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA4DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);

        // Resolve Exec only after the complete read-only admission. Stack all
        // public nodes below the saved caller D0, then free tail-to-head.
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA2ToPreDecrementA7);
        Append(code, MoveLongA3ToPreDecrementA7);
        Append(code, MoveLongA4ToPreDecrementA7);

        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);

        Append(code, MoveAddressA1ToA0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionBounds);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionBounds + 4));
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Clears a rectangle from a marker-owned Region. Empty and canonical
    /// one-node sources support no-op, retained-node, and bounded replacement
    /// transactions; other forms retain the portable Boolean builder.
    /// </summary>
    private static int AppendClearRectRegionEmptyNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(11);
        var fullContainmentFallbackBranches = new List<int>(4);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        // Preserve the portable D0 frame for every decline.  Unlike
        // AndRectRegion this Boolean vector returns TRUE on a native no-op.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA0ToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
        Decline(BranchHighWord);
        Append(code, MoveLongA1ToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF8);
        Decline(BranchHighWord);

        Append(code, MoveLongA0ToD0); Append(code, SubQuickFourLongD0);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
        Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Append(code, BranchNotEqualWord);
        var nonEmptyBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Match ModifyWithRectangle's input-read boundary even though an
        // empty Region is unchanged for both ordinary and evil rectangles.
        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var nonEmptyOffset = code.Count;
        // A canonical one-node Region has a complete, no-allocation answer
        // when the clear Rectangle is wholly outside its absolute bounds.
        // Intersecting subtraction would need replacement-list publication,
        // so it deliberately retains the portable Boolean path below.
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA2ToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA0ToA3); Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordA2DisplacementToD6);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);

        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        // ClearRectRegion treats an evil rectangle as a successful no-op.
        Append(code, CompareWordD4ToD6); Append(code, BranchLessThanWord);
        var evilRectangleExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD5ToD7); Append(code, BranchLessThanWord);
        var evilRectangleYExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD6ToD0); Append(code, BranchGreaterThanWord);
        var noIntersectionExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD2ToD4); Append(code, BranchGreaterThanWord);
        var noIntersectionRightExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD7ToD1); Append(code, BranchGreaterThanWord);
        var noIntersectionBelowExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD3ToD5); Append(code, BranchGreaterThanWord);
        var noIntersectionAboveExtensionOffset = code.Count; Append(code, 0);
        // A clear Rectangle that wholly contains the sole canonical node has
        // an empty result. Other intersections continue through the bounded
        // strip, split, corner, and interior-hole selectors below.
        Append(code, CompareWordD4ToD0); Append(code, BranchLessThanWord);
        var rightStripCandidateExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD5ToD1); Append(code, BranchLessThanWord);
        var bottomStripCandidateExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD6ToD2); Append(code, BranchGreaterThanWord);
        var leftStripExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD7ToD3); Append(code, BranchGreaterThanWord);
        var topStripExtensionOffset = code.Count; Append(code, 0);
        var fullContainmentOffset = code.Count;
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveAddressA0ToA5);
        // Match the portable builder's empty sentinel and publish the null
        // head before calling Exec. The old node must not remain reachable
        // from a public Region while its allocation is being retired.
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionBounds);
        Append(code, MoveQuickMinusOneD1);
        Append(code, MoveLongD1ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionBounds + 4));
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        // Clearing the full width from an interior top edge through the
        // bottom edge leaves one canonical rectangle. D5 is strictly above
        // D1 on this route, so D5-1 is a valid new maximum Y.
        var bottomStripCandidateOffset = code.Count;
        PatchBranch(code, bottomStripCandidateExtensionOffset, bottomStripCandidateOffset);
        Append(code, CompareWordD6ToD2); Append(code, BranchGreaterThanWord);
