        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        // An upper interior clear leaves two upper side bands followed by a
        // lower full-width band. Keep clear.maxX in D5 once minY is no longer
        // needed so D6 remains available for link and bound scratch.
        var interiorUpperGeometryOffset = code.Count;
        PatchBranch(code, interiorUpperGeometryExtensionOffset, interiorUpperGeometryOffset);
        Append(code, MoveWordD6ToD5);

        // First node: [header.minX .. clear.minX-1, header.minY .. clear.maxY].
        Append(code, MoveAddressA3ToA0); Append(code, MoveLongA4ToD6);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressA5ToA0); Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0); Append(code, MoveLongA0ToD6);
        Append(code, MoveAddressA3ToA0); Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveQuickZeroD6); Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds); Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD4ToD6); Append(code, SubWordD0ToD6); Append(code, SubQuickOneWordD6); Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD7ToD6); Append(code, SubWordD1ToD6); Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

        // Second node: [clear.maxX+1 .. header.maxX, header.minY .. clear.maxY].
        Append(code, MoveAddressA4ToA0); Append(code, MoveLongA1ToD6); Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext); Append(code, MoveLongA3ToD6); Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveWordD5ToD6); Append(code, AddQuickOneWordD6); Append(code, SubWordD0ToD6); Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveQuickZeroD6); Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD7ToD6); Append(code, SubWordD1ToD6); Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

        // Third node: [header.minX .. header.maxX, clear.maxY+1 .. header.maxY].
        Append(code, MoveAddressA1ToA0); Append(code, MoveQuickZeroD6); Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext); Append(code, MoveLongA4ToD6); Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveQuickZeroD6); Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD7ToD6); Append(code, AddQuickOneWordD6); Append(code, SubWordD1ToD6); Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveAddressA5ToA0); Append(code, MoveLongA3ToD6); Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle); Append(code, MoveAddressA2ToA0); Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize); Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); AppendExecFreeMemFromA0PreservingA1(code); Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        // A lower interior clear that reaches the Region bottom retains the
        // upper full-width band followed by lower-left and lower-right bands.
        // The common allocator above has already kept A3/A4/A1 private and
        // restored every geometry word before this topology is initialized.
        var interiorBottomGeometryOffset = code.Count;
        PatchBranch(code, interiorBottomGeometryExtensionOffset, interiorBottomGeometryOffset);
        // clear.maxY is irrelevant once bottom coverage is admitted; retain
        // clear.maxX there while D6 is reused for link/bounds scratch.
        Append(code, MoveWordD6ToD7);

        // First node: [header.minX .. header.maxX, header.minY .. clear.minY - 1].
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA4ToD6);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressA5ToA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, MoveLongA0ToD6);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD5ToD6); Append(code, SubWordD1ToD6); Append(code, SubQuickOneWordD6);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

        // Second node: [header.minX .. clear.minX - 1, clear.minY .. header.maxY].
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA1ToD6);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveLongA3ToD6);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD5ToD6); Append(code, SubWordD1ToD6);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD4ToD6); Append(code, SubWordD0ToD6); Append(code, SubQuickOneWordD6);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

        // Third node: [clear.maxX + 1 .. header.maxX, clear.minY .. header.maxY].
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveLongA4ToD6);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveWordD7ToD6); Append(code, AddQuickOneWordD6); Append(code, SubWordD0ToD6);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD5ToD6); Append(code, SubWordD1ToD6);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA3ToD6);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var interiorHoleFirstAllocationBadOffset = code.Count;
        PatchBranch(code, interiorHoleFirstAllocationBadExtensionOffset, interiorHoleFirstAllocationBadOffset);
        PatchBranch(code, interiorHoleFirstAllocationHighExtensionOffset, interiorHoleFirstAllocationBadOffset);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        for (var index = 0; index < 8; index++)
            Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0); Append(code, ReturnFromSubroutine);

        var interiorHoleSecondAllocationBadOffset = code.Count;
        PatchBranch(code, interiorHoleSecondAllocationBadExtensionOffset, interiorHoleSecondAllocationBadOffset);
        PatchBranch(code, interiorHoleSecondAllocationHighExtensionOffset, interiorHoleSecondAllocationBadOffset);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        for (var index = 0; index < 8; index++)
            Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0); Append(code, ReturnFromSubroutine);

        var interiorHoleThirdAllocationBadOffset = code.Count;
        PatchBranch(code, interiorHoleThirdAllocationBadExtensionOffset, interiorHoleThirdAllocationBadOffset);
        PatchBranch(code, interiorHoleThirdAllocationHighExtensionOffset, interiorHoleThirdAllocationBadOffset);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        for (var index = 0; index < 8; index++)
            Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0); Append(code, ReturnFromSubroutine);

        var verticalSplitSecondAllocationBadOffset = code.Count;
        PatchBranch(code, verticalSplitSecondAllocationBadExtensionOffset, verticalSplitSecondAllocationBadOffset);
        PatchBranch(code, verticalSplitSecondAllocationHighExtensionOffset, verticalSplitSecondAllocationBadOffset);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        for (var index = 0; index < 8; index++)
            Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0); Append(code, ReturnFromSubroutine);

        // Clearing the full width from the top edge through an interior
        // bottom edge leaves one canonical rectangle. D7 is strictly below
        // D3 on this route, so D7+1 is a valid new minimum Y.
        var topStripOffset = code.Count;
        PatchBranch(code, topStripExtensionOffset, topStripOffset);
        Append(code, MoveWordD7ToD6); Append(code, AddQuickOneWordD6);
        Append(code, MoveWordD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordD2ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordD3ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD6ToA2Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordD3ToD6); Append(code, SubWordD0ToD6);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        // Clearing from the left edge through an interior right edge leaves
        // one canonical rectangle only when the clear also reaches the
        // bottom edge. A shorter clear is an upper-left corner cut and must
        // retain the portable replacement-list path until its two-band
        // publisher is emitted.
        var leftStripOffset = code.Count;
        PatchBranch(code, leftStripExtensionOffset, leftStripOffset);
        Append(code, CompareWordD7ToD3); Append(code, BranchGreaterThanWord);
        var upperLeftCornerFallbackExtensionOffset = code.Count; Append(code, 0);
        // This branch is emitted after the shared vertical transaction, so
        // patch it directly to that established entry point.  The selected
        // geometry is decided after its two provisional allocations.
        PatchBranch(code, upperLeftCornerFallbackExtensionOffset, verticalSplitOffset);
        Append(code, AddQuickOneWordD6);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordD1ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordD2ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordD3ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD6ToA2Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        // A real partial intersection must preserve the caller frame for the
        // portable subtraction/replacement-list transaction.
        Append(code, BranchAlwaysWord);
        var intersectionFallbackExtensionOffset = code.Count; Append(code, 0);

        var noIntersectionOffset = code.Count;
        PatchBranch(code, evilRectangleExtensionOffset, noIntersectionOffset);
        PatchBranch(code, evilRectangleYExtensionOffset, noIntersectionOffset);
        PatchBranch(code, noIntersectionExtensionOffset, noIntersectionOffset);
        PatchBranch(code, noIntersectionRightExtensionOffset, noIntersectionOffset);
        PatchBranch(code, noIntersectionBelowExtensionOffset, noIntersectionOffset);
        PatchBranch(code, noIntersectionAboveExtensionOffset, noIntersectionOffset);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, nonEmptyBranchExtensionOffset, nonEmptyOffset);
        PatchBranch(code, intersectionFallbackExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, horizontalSplitFallbackExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, verticalSplitFallbackExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, lowerLeftCornerFallbackExtensionOffset, interiorHoleTransactionOffset);
        PatchBranch(code, interiorHoleExecFallbackExtensionOffset, fallbackRestoreOffset);
        foreach (var branch in fullContainmentFallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Uses the empty-region XOR identity.  A valid Rectangle has the same
    /// result as OrRectRegion; an evil Rectangle is the documented successful
    /// no-op and never enters the allocation-bearing OR body.
    /// </summary>
    private static int AppendXorRectRegionEmptyNative(
        List<byte> code,
        int fallbackEntryOffset,
        int orRectRegionEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(11);
        var identicalRectangleFallbackBranches = new List<int>(4);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA0ToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
        Decline(BranchHighWord);
        Append(code, MoveLongA1ToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF8);
        Decline(BranchHighWord);

        Append(code, MoveLongA0ToD0); Append(code, SubQuickFourLongD0);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
        Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Append(code, BranchNotEqualWord);
        var nonEmptyBranchExtensionOffset = code.Count; Append(code, 0);

        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD6); Append(code, BranchLessThanWord);
        var evilRectangleExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD5ToD7); Append(code, BranchLessThanWord);
        var evilRectangleYExtensionOffset = code.Count; Append(code, 0);

        // Restore the portable D0 frame before tail-entering the OR body,
        // which captures it again for its own fallback and allocation paths.
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var orRectRegionExtensionOffset = code.Count; Append(code, 0);

        var nonEmptyOffset = code.Count;
        // For a canonical one-node Region, XOR with a disjoint Rectangle is
        // exactly OR.  Verify that narrow identity before tail-entering the
        // established transactional OR publisher; any overlap remains with
        // the portable XOR Boolean builder.
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA2ToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA0ToA3); Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordA2DisplacementToD6);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD6); Append(code, BranchLessThanWord);
        var nonEmptyEvilRectangleExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD5ToD7); Append(code, BranchLessThanWord);
        var nonEmptyEvilRectangleYExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD6ToD0); Append(code, BranchGreaterThanWord);
        var disjointXExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD2ToD4); Append(code, BranchGreaterThanWord);
        var disjointRightExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD7ToD1); Append(code, BranchGreaterThanWord);
        var disjointYExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD3ToD5); Append(code, BranchGreaterThanWord);
        var disjointAboveExtensionOffset = code.Count; Append(code, 0);

        // Equal canonical rectangles XOR to an empty Region. This is the only
        // overlapping one-node form with a one-step lifecycle result; every
        // other overlap retains the portable subtraction builder.
        Append(code, CompareWordD0ToD4); Append(code, BranchNotEqualWord);
        identicalRectangleFallbackBranches.Add(code.Count); Append(code, 0);
        Append(code, CompareWordD1ToD5); Append(code, BranchNotEqualWord);
        identicalRectangleFallbackBranches.Add(code.Count); Append(code, 0);
        Append(code, CompareWordD2ToD6); Append(code, BranchNotEqualWord);
        identicalRectangleFallbackBranches.Add(code.Count); Append(code, 0);
        Append(code, CompareWordD3ToD7); Append(code, BranchNotEqualWord);
        identicalRectangleFallbackBranches.Add(code.Count); Append(code, 0);
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveAddressA0ToA5);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionBounds);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionBounds + 4));
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        Append(code, BranchAlwaysWord);
        var nonEmptyFallbackExtensionOffset = code.Count; Append(code, 0);

        var nonEmptyOrOffset = code.Count;
        PatchBranch(code, disjointXExtensionOffset, nonEmptyOrOffset);
        PatchBranch(code, disjointRightExtensionOffset, nonEmptyOrOffset);
        PatchBranch(code, disjointYExtensionOffset, nonEmptyOrOffset);
        PatchBranch(code, disjointAboveExtensionOffset, nonEmptyOrOffset);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var nonEmptyOrRectRegionExtensionOffset = code.Count; Append(code, 0);

        var nonEmptyEvilOffset = code.Count;
        PatchBranch(code, nonEmptyEvilRectangleExtensionOffset, nonEmptyEvilOffset);
        PatchBranch(code, nonEmptyEvilRectangleYExtensionOffset, nonEmptyEvilOffset);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var evilRectangleOffset = code.Count;
        PatchBranch(code, evilRectangleExtensionOffset, evilRectangleOffset);
        PatchBranch(code, evilRectangleYExtensionOffset, evilRectangleOffset);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, orRectRegionExtensionOffset, orRectRegionEntryOffset);
        PatchBranch(code, nonEmptyOrRectRegionExtensionOffset, orRectRegionEntryOffset);
        PatchBranch(code, nonEmptyBranchExtensionOffset, nonEmptyOffset);
        PatchBranch(code, nonEmptyFallbackExtensionOffset, fallbackRestoreOffset);
        foreach (var branch in identicalRectangleFallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Intersects two empty marker-owned Regions. The public result is already
    /// empty, but both source and destination headers are admitted before the
    /// Boolean success is claimed.
    /// </summary>
    private static int AppendAndRegionRegionBothEmptyNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(12);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitEmptyOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        EmitEmptyOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        EmitEmptyOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Admits a canonical two-node native source Region against either an
    /// empty destination, a canonical one-node destination contained by one
    /// source node, a destination containing exactly one source node, or a
    /// single-node partial intersection disjoint from the other source node.
    /// The first two forms are read-only; the latter forms rewrite the
    /// existing node without allocation. All other shapes remain on the
    /// portable builder.
    /// </summary>
    private static int AppendAndRegionRegionTwoNodeSourceEmptyNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(42);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitRelativeEnvelopeValidation(ushort nodeMinXToD4, ushort nodeMinYToD4,
            ushort nodeMaxXToD5, ushort nodeMaxYToD5)
        {
            Append(code, nodeMinXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, nodeMaxXToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, nodeMinYToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, nodeMaxYToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        void EmitDestinationContainedByNode(
            ushort nodeMinXToD4,
            ushort nodeMaxXToD4,
            ushort nodeMinYToD4,
            ushort nodeMaxYToD4,
            List<int> missBranches,
            List<int> successBranches)
        {
            void Miss(ushort branchOpcode)
            {
                Append(code, branchOpcode);
                missBranches.Add(code.Count);
                Append(code, 0);
            }

            // Compare destination coordinates relative to the source header
            // against one source node's relative bounds.  This avoids adding
            // the signed header origin to a node word in-place.
            Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, SubWordD0ToD1); Miss(BranchOverflowWord);
            Append(code, nodeMinXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, CompareWordD4ToD1); Miss(BranchLessThanWord);

            Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, SubWordD0ToD1); Miss(BranchOverflowWord);
            Append(code, nodeMaxXToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD1); Miss(BranchGreaterThanWord);

            Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, SubWordD0ToD1); Miss(BranchOverflowWord);
            Append(code, nodeMinYToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD1); Miss(BranchLessThanWord);

            Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, SubWordD0ToD1); Miss(BranchOverflowWord);
            Append(code, nodeMaxYToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD1); Miss(BranchGreaterThanWord);

            Append(code, BranchAlwaysWord);
            successBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitDestinationContainsNodeAndDisjointOther(
            ushort nodeAddressToA4,
            ushort otherMinXToD4,
            ushort otherMaxXToD4,
            ushort otherMinYToD4,
            ushort otherMaxYToD4,
            List<int> missBranches,
            List<int> successBranches)
        {
            void Miss(ushort branchOpcode)
            {
                Append(code, branchOpcode);
                missBranches.Add(code.Count);
                Append(code, 0);
            }

            // Work in the source Region's relative coordinate space. The
            // candidate node must be contained by the destination, and the
            // destination must be disjoint from the other source node so the
            // intersection remains a single public Rectangle.
            Append(code, nodeAddressToA4);
            Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, SubWordD4ToD0); Miss(BranchOverflowWord);
            Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, SubWordD4ToD1); Miss(BranchOverflowWord);
            Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, SubWordD4ToD2); Miss(BranchOverflowWord);
            Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, SubWordD4ToD3); Miss(BranchOverflowWord);

            Append(code, MoveWordA4DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA4DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA4DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordD6ToD7);
            Append(code, CompareWordD4ToD0); Miss(BranchGreaterThanWord);
            Append(code, CompareWordD5ToD1); Miss(BranchGreaterThanWord);
            Append(code, CompareWordD6ToD2); Miss(BranchLessThanWord);
            Append(code, CompareWordD7ToD3); Miss(BranchLessThanWord);

            var disjointSuccessBranches = new List<int>(4);
            Append(code, otherMinXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, CompareWordD4ToD2); Append(code, BranchLessThanWord);
            disjointSuccessBranches.Add(code.Count); Append(code, 0);
            Append(code, otherMaxXToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD0ToD4); Append(code, BranchLessThanWord);
            disjointSuccessBranches.Add(code.Count); Append(code, 0);
            Append(code, otherMinYToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD3); Append(code, BranchLessThanWord);
            disjointSuccessBranches.Add(code.Count); Append(code, 0);
            Append(code, otherMaxYToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD1ToD4); Append(code, BranchLessThanWord);
            disjointSuccessBranches.Add(code.Count); Append(code, 0);

            Append(code, BranchAlwaysWord);
            missBranches.Add(code.Count);
            Append(code, 0);
            var disjointSuccessOffset = code.Count;
            foreach (var branch in disjointSuccessBranches)
                PatchBranch(code, branch, disjointSuccessOffset);
            Append(code, BranchAlwaysWord);
            successBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitDestinationIntersectionWithNodeAndDisjointOther(
            ushort nodeAddressToA4,
            ushort otherMinXToD4,
            ushort otherMaxXToD4,
            ushort otherMinYToD4,
            ushort otherMaxYToD4,
            List<int> missBranches,
            List<int> successBranches)
        {
            void Miss(ushort branchOpcode)
            {
                Append(code, branchOpcode);
                missBranches.Add(code.Count);
                Append(code, 0);
            }

            // Translate the destination to the source Region's relative
            // coordinate space.  If a signed translation cannot be
            // represented, the portable builder remains authoritative.
            Append(code, nodeAddressToA4);
            Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, SubWordD4ToD0); Miss(BranchOverflowWord);
            Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, SubWordD4ToD1); Miss(BranchOverflowWord);
            Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, SubWordD4ToD2); Miss(BranchOverflowWord);
            Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, SubWordD4ToD3); Miss(BranchOverflowWord);

            Append(code, MoveWordA4DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA4DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA4DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordD6ToD7);
            Append(code, MoveWordA4DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));

            // Inclusive overlap with the candidate node is required.
            Append(code, CompareWordD4ToD2); Miss(BranchLessThanWord);
            Append(code, CompareWordD0ToD6); Miss(BranchLessThanWord);
            Append(code, CompareWordD5ToD3); Miss(BranchLessThanWord);
            Append(code, CompareWordD1ToD7); Miss(BranchLessThanWord);

            // The destination may not touch the other source node, otherwise
            // the result would require a replacement list rather than one
            // destination node.
            var disjointSuccessBranches = new List<int>(4);
            Append(code, otherMinXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, CompareWordD4ToD2); Append(code, BranchLessThanWord);
            disjointSuccessBranches.Add(code.Count); Append(code, 0);
            Append(code, otherMaxXToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD0ToD4); Append(code, BranchLessThanWord);
            disjointSuccessBranches.Add(code.Count); Append(code, 0);
            Append(code, otherMinYToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD3); Append(code, BranchLessThanWord);
            disjointSuccessBranches.Add(code.Count); Append(code, 0);
            Append(code, otherMaxYToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD1ToD4); Append(code, BranchLessThanWord);
            disjointSuccessBranches.Add(code.Count); Append(code, 0);
            Append(code, BranchAlwaysWord);
            missBranches.Add(code.Count);
            Append(code, 0);
            var disjointSuccessOffset = code.Count;
            foreach (var branch in disjointSuccessBranches)
                PatchBranch(code, branch, disjointSuccessOffset);

            // Reload the candidate bounds after the other-node probes, then
            // select max(minima) and min(maxima) for the inclusive result.
            Append(code, MoveWordA4DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA4DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA4DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordD6ToD7);
            Append(code, MoveWordA4DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));

            Append(code, CompareWordD4ToD0); Append(code, BranchLessThanWord);
            var minimumXSetExtensionOffset = code.Count; Append(code, 0);
            Append(code, BranchAlwaysWord);
            var minimumXReadyExtensionOffset = code.Count; Append(code, 0);
            var minimumXSetOffset = code.Count;
            Append(code, MoveWordD4ToD0);
            var minimumXReadyOffset = code.Count;
            PatchBranch(code, minimumXSetExtensionOffset, minimumXSetOffset);
            PatchBranch(code, minimumXReadyExtensionOffset, minimumXReadyOffset);
            Append(code, CompareWordD5ToD1); Append(code, BranchLessThanWord);
            var minimumYSetExtensionOffset = code.Count; Append(code, 0);
            Append(code, BranchAlwaysWord);
            var minimumYReadyExtensionOffset = code.Count; Append(code, 0);
            var minimumYSetOffset = code.Count;
            Append(code, MoveWordD5ToD1);
            var minimumYReadyOffset = code.Count;
            PatchBranch(code, minimumYSetExtensionOffset, minimumYSetOffset);
            PatchBranch(code, minimumYReadyExtensionOffset, minimumYReadyOffset);
            Append(code, CompareWordD6ToD2); Append(code, BranchGreaterThanWord);
            var maximumXSetExtensionOffset = code.Count; Append(code, 0);
            Append(code, BranchAlwaysWord);
            var maximumXReadyExtensionOffset = code.Count; Append(code, 0);
            var maximumXSetOffset = code.Count;
            Append(code, MoveWordD6ToD2);
            var maximumXReadyOffset = code.Count;
            PatchBranch(code, maximumXSetExtensionOffset, maximumXSetOffset);
            PatchBranch(code, maximumXReadyExtensionOffset, maximumXReadyOffset);
            Append(code, CompareWordD7ToD3); Append(code, BranchGreaterThanWord);
            var maximumYSetExtensionOffset = code.Count; Append(code, 0);
            Append(code, BranchAlwaysWord);
            var maximumYReadyExtensionOffset = code.Count; Append(code, 0);
            var maximumYSetOffset = code.Count;
            Append(code, MoveWordD7ToD3);
            var maximumYReadyOffset = code.Count;
            PatchBranch(code, maximumYSetExtensionOffset, maximumYSetOffset);
            PatchBranch(code, maximumYReadyExtensionOffset, maximumYReadyOffset);
            Append(code, CompareWordD0ToD2); Miss(BranchLessThanWord);
            Append(code, CompareWordD1ToD3); Miss(BranchLessThanWord);
            Append(code, BranchAlwaysWord);
            successBranches.Add(code.Count);
            Append(code, 0);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveQuickZeroD7);
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var nonEmptyDestinationExtensionOffset = code.Count;
        Append(code, 0);

        // Empty destinations retain the no-allocation identity.  A nonempty
        // destination is admitted as exactly one canonical node so the later
        // source-node containment check can prove an unchanged AND result.
        Append(code, BranchAlwaysWord);
        var emptyDestinationSkipExtensionOffset = code.Count;
        Append(code, 0);
        var nonEmptyDestinationOffset = code.Count;
        Append(code, MoveAddressD0ToA4);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA4DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD6); Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA1ToA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, MoveLongA5ToD0); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        Append(code, MoveWordA4DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordA4DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
        Append(code, TestWordD4); Decline(BranchLessThanWord);
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
        Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        Append(code, MoveWordA4DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordA4DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
        Append(code, TestWordD4); Decline(BranchLessThanWord);
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
        Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        Append(code, MoveQuickOneD7);

        var destinationValidationDoneOffset = code.Count;
        PatchBranch(code, nonEmptyDestinationExtensionOffset, nonEmptyDestinationOffset);
        PatchBranch(code, emptyDestinationSkipExtensionOffset, destinationValidationDoneOffset);
        // Preserve the destination node while A4 is reused for source-node
        // admission and the two source-node containment probes.
        Append(code, MoveLongA4ToD0);
        Append(code, MoveAddressD0ToA5);

        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA2);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);

        // The Region header supplies the absolute envelope used to validate
        // every relative node rectangle below.
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);

        // First node: backlink to the public Region sentinel and a non-null
        // successor, which becomes A3 for the second-node checks.
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA0ToA4);
        Append(code, AddQuickFourLongA4); Append(code, AddQuickFourLongA4);
        Append(code, MoveLongA4ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA3);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        EmitRelativeEnvelopeValidation(
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD5,
            MoveWordA2DisplacementToD5);

        // The second node must terminate the canonical two-node chain and
        // point back to the first node stored in the Region sentinel.
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA2ToA4);
        Append(code, MoveLongA4ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        EmitRelativeEnvelopeValidation(
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD5,
            MoveWordA3DisplacementToD5);

        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var emptyDestinationSuccessExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);

        var firstNodeContainedMissBranches = new List<int>(8);
        var secondNodeContainedMissBranches = new List<int>(8);
        var firstNodeContainsMissBranches = new List<int>(8);
        var firstNodeIntersectionMissBranches = new List<int>(8);
        var secondNodeContainsMissBranches = new List<int>(8);
        var secondNodeIntersectionMissBranches = new List<int>(8);
        var containsSuccessBranches = new List<int>(4);
        var intersectionSuccessBranches = new List<int>(4);
        var containmentSuccessBranches = new List<int>(2);
        EmitDestinationContainedByNode(
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            firstNodeContainedMissBranches,
            containmentSuccessBranches);
        var secondNodeContainmentOffset = code.Count;
        foreach (var branch in firstNodeContainedMissBranches)
            PatchBranch(code, branch, secondNodeContainmentOffset);
        EmitDestinationContainedByNode(
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD4,
            secondNodeContainedMissBranches,
            containmentSuccessBranches);

        var firstNodeContainsOffset = code.Count;
        foreach (var branch in secondNodeContainedMissBranches)
            PatchBranch(code, branch, firstNodeContainsOffset);
        EmitDestinationContainsNodeAndDisjointOther(
            MoveAddressA2ToA4,
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD4,
            firstNodeContainsMissBranches,
            containsSuccessBranches);

        var firstNodeIntersectionOffset = code.Count;
        foreach (var branch in firstNodeContainsMissBranches)
            PatchBranch(code, branch, firstNodeIntersectionOffset);
        EmitDestinationIntersectionWithNodeAndDisjointOther(
            MoveAddressA2ToA4,
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD4,
            firstNodeIntersectionMissBranches,
            intersectionSuccessBranches);

        var secondNodeContainsOffset = code.Count;
        foreach (var branch in firstNodeIntersectionMissBranches)
            PatchBranch(code, branch, secondNodeContainsOffset);
        EmitDestinationContainsNodeAndDisjointOther(
            MoveAddressA3ToA4,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            secondNodeContainsMissBranches,
            containsSuccessBranches);

        var secondNodeIntersectionOffset = code.Count;
        foreach (var branch in secondNodeContainsMissBranches)
            PatchBranch(code, branch, secondNodeIntersectionOffset);
        EmitDestinationIntersectionWithNodeAndDisjointOther(
            MoveAddressA3ToA4,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            fallbackBranches,
            intersectionSuccessBranches);

        var containmentSuccessOffset = code.Count;
        foreach (var branch in containmentSuccessBranches)
            PatchBranch(code, branch, containmentSuccessOffset);
        PatchBranch(code, emptyDestinationSuccessExtensionOffset, containmentSuccessOffset);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var containsRewriteOffset = code.Count;
        foreach (var branch in containsSuccessBranches)
            PatchBranch(code, branch, containsRewriteOffset);
        // Snapshot the candidate source-node relative bounds before A2 is
        // repurposed for the destination node writes.
        Append(code, MoveWordA4DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordA4DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordA4DisplacementToD6);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordA4DisplacementToD6);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordD6ToD7);
        Append(code, MoveWordA4DisplacementToD6);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, AddWordD4ToD0);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordD5ToD4);
        Append(code, AddWordD4ToD1);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordD6ToD4);
        Append(code, AddWordD4ToD2);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordD7ToD6);
        Append(code, MoveWordD6ToD4);
        Append(code, AddWordD4ToD3);
        Append(code, MoveWordD0ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordD1ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordD2ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordD3ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveAddressA5ToA2);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD6ToA2Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordA4DisplacementToD6);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordA4DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, SubWordD4ToD6);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD7ToD6);
        Append(code, SubWordD5ToD6);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var intersectionRewriteOffset = code.Count;
        foreach (var branch in intersectionSuccessBranches)
            PatchBranch(code, branch, intersectionRewriteOffset);
        // D0..D3 contain the selected intersection relative to the source
        // header; A5 retains the admitted destination node.
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, AddWordD4ToD0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, AddWordD4ToD1);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, AddWordD4ToD2);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, AddWordD4ToD3);
        Append(code, MoveWordD0ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordD1ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordD2ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordD3ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveAddressA5ToA2);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD6ToA2Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Intersects a canonical one-node native Region with an empty native
    /// destination. The result is already empty, so successful admission is
    /// read-only and must not allocate or publish a replacement list.
    /// </summary>
    private static int AppendAndRegionRegionDestinationEmptyNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(18);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        // A1 is the destination: it must be the already-empty owned Region.
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);

        // A0 is admitted as exactly one canonical source node. This avoids
        // claiming malformed source ownership merely because the destination
        // happens to be empty.
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Append(code, BranchNotEqualWord);
        var nonEmptySourceExtensionOffset = code.Count; Append(code, 0);
        // Empty source and empty destination is the original no-allocation
        // identity, retained by this broader AND entrypoint.
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var nonEmptySourceOffset = code.Count;
        Append(code, MoveAddressD0ToA2);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);

        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA0ToA3); Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordA2DisplacementToD6);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, nonEmptySourceExtensionOffset, nonEmptySourceOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Transfers a canonical two-node native source Region into an empty
    /// native destination for OR/XOR. The source chain is admitted completely
    /// before Exec is resolved; two fresh public nodes are allocated and
    /// initialized privately, then the destination header and head are
    /// published atomically. Allocation and address-class failures free any
    /// provisional nodes and return FALSE without changing either Region.
    /// </summary>
    private static int AppendOrXorRegionRegionTwoNodeSourceEmptyNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(48);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitAddressAdmission(ushort moveAddressToD0, ushort displacement)
        {
            Append(code, moveAddressToD0); Append(code, displacement);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        void EmitRelativeBoundsValidation(
            ushort nodeMinXToD4,
            ushort nodeMinYToD4,
            ushort nodeMaxXToD5,
            ushort nodeMaxYToD5)
        {
            Append(code, nodeMinXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, nodeMaxXToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, nodeMinYToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, nodeMaxYToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        void EmitRestoreFailure()
        {
            // Saved frame: destination, source header, source first, source
            // second, then the caller's original D0.
            for (var index = 0; index < 5; index++)
                Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickZeroD0);
            Append(code, ReturnFromSubroutine);
        }

        void EmitFreeAndRestoreFailure(
            ushort moveAllocationToA0,
            ushort moveFirstAllocationToA0,
            bool freeFirst)
        {
            Append(code, moveAllocationToA0);
            Append(code, MoveLongImmediateD0); Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
            AppendExecFreeMemFromA0PreservingA1(code);
            if (freeFirst)
            {
                Append(code, moveFirstAllocationToA0);
                Append(code, MoveLongImmediateD0); Append(code, 0);
                Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
                Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
                AppendExecFreeMemFromA0PreservingA1(code);
            }
            EmitRestoreFailure();
        }

        // Preserve the caller's seed while every admission check remains
        // non-mutating. The source header and both source nodes are copied to
        // address registers before destination admission reuses A2.
        Append(code, MoveLongD0ToPreDecrementA7);
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA2);
        EmitAddressAdmission(
            MoveLongA0DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA0ToA3);
        Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA2DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitRelativeBoundsValidation(
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD5,
            MoveWordA2DisplacementToD5);
        EmitRelativeBoundsValidation(
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD5,
            MoveWordA3DisplacementToD5);

        Append(code, MoveAddressA0ToA4); // source header
        Append(code, MoveLongA2ToD0); Append(code, MoveAddressD0ToA5); // source first
        Append(code, MoveLongA3ToD0); Append(code, MoveAddressD0ToA6); // source second

        // Destination is an owned Region with an empty public list. Its
        // existing envelope is replaced by the source envelope only after
        // both replacement nodes have been initialized.
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);

        // Keep all guest pointers below the caller's seed before resolving
        // Exec.  The Exec-missing path therefore has a dedicated frame
        // restore before it rejoins the portable fallback.
        Append(code, MoveLongA1ToPreDecrementA7);
        Append(code, MoveLongA4ToPreDecrementA7);
        Append(code, MoveLongA5ToPreDecrementA7);
        Append(code, MoveLongA6ToPreDecrementA7);

        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var execMissingRestoreExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveAddressD0ToA6);

        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var firstAllocationSucceededExtensionOffset = code.Count; Append(code, 0);
        EmitRestoreFailure();

        var firstAllocationSucceededOffset = code.Count;
        PatchBranch(code, firstAllocationSucceededExtensionOffset, firstAllocationSucceededOffset);
        Append(code, BitTestImmediateD0); Append(code, 0);
        Append(code, BranchEqualWord);
        var firstAllocationEvenExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var firstAllocationBadExtensionOffset = code.Count; Append(code, 0);
        var firstAllocationEvenOffset = code.Count;
        PatchBranch(code, firstAllocationEvenExtensionOffset, firstAllocationEvenOffset);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchHighWord);
        var firstAllocationAddressableExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var firstAllocationHighExtensionOffset = code.Count; Append(code, 0);
        var firstAllocationAddressableOffset = code.Count;
        Append(code, MoveLongD0ToD6);

        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var secondAllocationSucceededExtensionOffset = code.Count; Append(code, 0);
        EmitFreeAndRestoreFailure(
            MoveAddressD6ToA0,
            MoveAddressD6ToA0,
            freeFirst: false);

        var secondAllocationSucceededOffset = code.Count;
        PatchBranch(code, secondAllocationSucceededExtensionOffset, secondAllocationSucceededOffset);
        Append(code, BitTestImmediateD0); Append(code, 0);
        Append(code, BranchEqualWord);
        var secondAllocationEvenExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var secondAllocationBadExtensionOffset = code.Count; Append(code, 0);
        var secondAllocationEvenOffset = code.Count;
        PatchBranch(code, secondAllocationEvenExtensionOffset, secondAllocationEvenOffset);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchHighWord);
        var secondAllocationAddressableExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var secondAllocationHighExtensionOffset = code.Count; Append(code, 0);
        var secondAllocationAddressableOffset = code.Count;
        Append(code, MoveLongD0ToD7);
        Append(code, BranchAlwaysWord);
        var secondAllocationSuccessExtensionOffset = code.Count; Append(code, 0);

        var secondAllocationBadOffset = code.Count;
        PatchBranch(code, secondAllocationBadExtensionOffset, secondAllocationBadOffset);
        PatchBranch(code, secondAllocationHighExtensionOffset, secondAllocationAddressableOffset);
        EmitFreeAndRestoreFailure(
            MoveAddressD0ToA0,
            MoveAddressD6ToA0,
            freeFirst: true);

        var firstAllocationBadOffset = code.Count;
        PatchBranch(code, firstAllocationBadExtensionOffset, firstAllocationBadOffset);
        PatchBranch(code, firstAllocationAddressableExtensionOffset, firstAllocationBadOffset);
        PatchBranch(code, firstAllocationHighExtensionOffset, firstAllocationAddressableOffset);
        PatchBranch(code, secondAllocationAddressableExtensionOffset, secondAllocationBadOffset);
        PatchBranch(code, secondAllocationHighExtensionOffset, secondAllocationAddressableOffset);
        EmitFreeAndRestoreFailure(
            MoveAddressD0ToA0,
            MoveAddressD6ToA0,
            freeFirst: false);

        var secondAllocationSuccessOffset = code.Count;
        PatchBranch(code, secondAllocationSuccessExtensionOffset, secondAllocationSuccessOffset);

        // Restore the saved pointers while D6/D7 retain the two allocations.
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);
        Append(code, MoveLongA7PostIncrementToD0); // discard caller seed

        void CopyBounds(ushort sourceRegisterMove, ushort destinationRegisterMove)
        {
            foreach (var displacement in new[] { 0, 2, 4, 6 })
            {
                Append(code, sourceRegisterMove);
                Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
                Append(code, destinationRegisterMove);
                Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
            }
        }

        Append(code, MoveAddressD6ToA0);
        CopyBounds(MoveWordA5DisplacementToD4, MoveWordD4ToA0Displacement);
        Append(code, MoveAddressD7ToA0);
        CopyBounds(MoveWordA6DisplacementToD0, MoveWordD0ToA0Displacement);

        // Publish source envelope and the private two-node chain only after
        // both allocations and all writes have completed.
        Append(code, MoveWordA4DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordD0ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA4DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordD1ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA4DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordD2ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA4DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordD3ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);

        Append(code, MoveAddressA1ToA0);
        Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0);
        Append(code, MoveLongA0ToD0);
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongD7ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD7ToA0);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        var execMissingRestoreOffset = code.Count;
        for (var index = 0; index < 5; index++)
            Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var execMissingFallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, execMissingRestoreExtensionOffset, execMissingRestoreOffset);
        PatchBranch(code, execMissingFallbackJumpExtensionOffset, fallbackEntryOffset);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Transfers a canonical four-node native source Region into an empty
    /// native destination for OR/XOR. The complete source topology and
    /// relative rectangles are admitted before Exec is resolved. Four fresh
    /// public nodes are allocated and initialized privately, then the
    /// destination envelope and chain are published atomically. Every
    /// allocation/address-class failure rolls back provisional nodes and
    /// leaves both Regions available to the existing operation-specific path.
    /// </summary>
    private static int AppendOrXorRegionRegionFourNodeSourceEmptyNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(88);
        var firstAllocationFailureBranches = new List<int>(6);
        var secondAllocationFailureBranches = new List<int>(6);
        var thirdAllocationFailureBranches = new List<int>(6);
        var fourthAllocationFailureBranches = new List<int>(6);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitAddressAdmission(ushort moveAddressToD0, ushort displacement)
        {
            Append(code, moveAddressToD0); Append(code, displacement);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        void EmitRestoreFailure()
        {
            // Saved frame: destination, source header, source first through
            // fourth, then the caller's original D0.
            for (var index = 0; index < 7; index++)
                Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickZeroD0);
            Append(code, ReturnFromSubroutine);
        }

        void EmitFree(uint register, bool enabled)
        {
            if (!enabled)
                return;
            Append(code, register switch
            {
                4 => MoveAddressD4ToA0,
                5 => MoveAddressD5ToA0,
                6 => MoveAddressD6ToA0,
                _ => throw new ArgumentOutOfRangeException(nameof(register))
            });
            Append(code, MoveLongImmediateD0); Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
            AppendExecFreeMemFromA0PreservingA1(code);
        }

        void EmitFreeAndRestoreFailure(bool freeThird, bool freeSecond, bool freeFirst)
        {
            EmitFree(6, freeThird);
            EmitFree(5, freeSecond);
            EmitFree(4, freeFirst);
            EmitRestoreFailure();
        }

        void EmitAllocationAddressValidation(List<int> failureBranches, ushort moveToRegister)
        {
            Append(code, BitTestImmediateD0); Append(code, 0);
            Append(code, BranchEqualWord);
            var evenExtensionOffset = code.Count; Append(code, 0);
            Append(code, BranchAlwaysWord);
            var oddExtensionOffset = code.Count; Append(code, 0);
            var evenOffset = code.Count;
            PatchBranch(code, evenExtensionOffset, evenOffset);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Append(code, BranchHighWord);
            failureBranches.Add(code.Count); Append(code, 0);
            failureBranches.Add(oddExtensionOffset);
            Append(code, moveToRegister);
        }

        // Preserve the caller's seed while the complete four-node source is
        // admitted. A2/A3/A4/A5 retain source nodes and A0 retains the header.
        Append(code, MoveLongD0ToPreDecrementA7);
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA2);
        EmitAddressAdmission(MoveLongA0DisplacementToD0, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA0ToA6);
        for (var index = 0; index < 8; index++)
            Append(code, AddQuickOneLongA6);
        Append(code, MoveLongA6ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(MoveLongA2DisplacementToD0, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(MoveLongA3DisplacementToD0, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(MoveLongA4DisplacementToD0, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);

        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA4ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);

        void ValidateNode(
            ushort minXToD4,
            ushort maxXToD5,
            ushort minYToD4,
            ushort maxYToD5)
        {
            Append(code, minXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, maxXToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
            Append(code, minYToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, maxYToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        ValidateNode(
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD5,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD5);
        ValidateNode(
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD5,
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD5);
        ValidateNode(
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD5,
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD5);
        ValidateNode(
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD5,
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD5);

        void RequireGap(ushort upperNode, ushort lowerNode)
        {
            Append(code, upperNode);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, lowerNode);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);
        }

        RequireGap(MoveWordA2DisplacementToD4, MoveWordA3DisplacementToD5);
        RequireGap(MoveWordA3DisplacementToD4, MoveWordA4DisplacementToD5);
        RequireGap(MoveWordA4DisplacementToD4, MoveWordA5DisplacementToD5);

        // Destination admission reuses A2; retain the source first node in
        // A6 while A3/A4/A5 and the source header in A0 remain available.
        Append(code, MoveAddressA2ToA6);
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);

        Append(code, MoveLongA1ToPreDecrementA7);
        Append(code, MoveLongA0ToPreDecrementA7);
        Append(code, MoveLongA6ToPreDecrementA7);
        Append(code, MoveLongA3ToPreDecrementA7);
        Append(code, MoveLongA4ToPreDecrementA7);
        Append(code, MoveLongA5ToPreDecrementA7);

        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var execMissingExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveAddressD0ToA6);

        void EmitAlloc(List<int> failures, ushort destinationRegister)
        {
            Append(code, MoveLongImmediateD0); Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
            Append(code, TestLongD0);
            Append(code, BranchEqualWord);
            failures.Add(code.Count); Append(code, 0);
            EmitAllocationAddressValidation(failures, destinationRegister);
        }

        EmitAlloc(firstAllocationFailureBranches, MoveLongD0ToD4);
        EmitAlloc(secondAllocationFailureBranches, MoveLongD0ToD5);
        EmitAlloc(thirdAllocationFailureBranches, MoveLongD0ToD6);
        EmitAlloc(fourthAllocationFailureBranches, MoveLongD0ToD7);

        // Restore guest pointers while D4..D7 retain the private allocations.
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);
        Append(code, MoveLongA7PostIncrementToD0);

        void CopyBounds(ushort sourceNodeMove)
        {
            foreach (var displacement in new[] { 0, 2, 4, 6 })
            {
                Append(code, sourceNodeMove); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
                Append(code, MoveWordD0ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
            }
        }

        Append(code, MoveAddressD4ToA0); CopyBounds(MoveWordA2DisplacementToD0);
        Append(code, MoveAddressD5ToA0); CopyBounds(MoveWordA3DisplacementToD0);
        Append(code, MoveAddressD6ToA0); CopyBounds(MoveWordA4DisplacementToD0);
        Append(code, MoveAddressD7ToA0); CopyBounds(MoveWordA5DisplacementToD0);

        foreach (var displacement in new[] { 0, 2, 4, 6 })
        {
            Append(code, MoveWordA6DisplacementToD0);
            Append(code, (ushort)(GraphicsLayouts.RectangleMinX + displacement));
            Append(code, MoveWordD0ToA1Displacement);
            Append(code, (ushort)(GraphicsLayouts.RectangleMinX + displacement));
        }

        Append(code, MoveAddressA1ToA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, MoveLongA0ToD0);
        Append(code, MoveAddressD4ToA0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongD5ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongD4ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveLongD5ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongD7ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD7ToA0);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveLongD4ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var execMissingRestoreOffset = code.Count;
        for (var index = 0; index < 7; index++)
            Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var execMissingFallbackExtensionOffset = code.Count; Append(code, 0);

        var fourthAllocationFailureOffset = code.Count;
        EmitFreeAndRestoreFailure(freeThird: true, freeSecond: true, freeFirst: true);
        var thirdAllocationFailureOffset = code.Count;
        EmitFreeAndRestoreFailure(freeThird: false, freeSecond: true, freeFirst: true);
        var secondAllocationFailureOffset = code.Count;
        EmitFreeAndRestoreFailure(freeThird: false, freeSecond: false, freeFirst: true);
        var firstAllocationFailureOffset = code.Count;
        EmitRestoreFailure();

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);

        PatchBranch(code, execMissingExtensionOffset, execMissingRestoreOffset);
        PatchBranch(code, execMissingFallbackExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in firstAllocationFailureBranches)
            PatchBranch(code, branch, firstAllocationFailureOffset);
        foreach (var branch in secondAllocationFailureBranches)
            PatchBranch(code, branch, secondAllocationFailureOffset);
        foreach (var branch in thirdAllocationFailureBranches)
            PatchBranch(code, branch, thirdAllocationFailureOffset);
        foreach (var branch in fourthAllocationFailureBranches)
            PatchBranch(code, branch, fourthAllocationFailureOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Transfers a canonical three-node native source Region into an empty
    /// native destination for OR/XOR. The complete source topology and
    /// relative rectangles are admitted before Exec is resolved. Three fresh
    /// public nodes are allocated and initialized privately, then the
    /// destination envelope and chain are published atomically. Every
    /// allocation/address-class failure rolls back provisional nodes and
    /// leaves both Regions available to the existing operation-specific path.
    /// </summary>
    private static int AppendOrXorRegionRegionThreeNodeSourceEmptyNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(72);
        var firstAllocationFailureBranches = new List<int>(6);
        var secondAllocationFailureBranches = new List<int>(6);
        var thirdAllocationFailureBranches = new List<int>(6);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitAddressAdmission(ushort moveAddressToD0, ushort displacement)
        {
            Append(code, moveAddressToD0); Append(code, displacement);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        void EmitRelativeBoundsValidation(
            ushort nodeMinXToD4,
            ushort nodeMinYToD4,
            ushort nodeMaxXToD5,
            ushort nodeMaxYToD5)
        {
            Append(code, nodeMinXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, nodeMaxXToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, nodeMinYToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, nodeMaxYToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        void EmitRestoreFailure()
        {
            // Saved frame: destination, source header, source first, source
            // second, source third, then the caller's original D0.
            for (var index = 0; index < 6; index++)
                Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickZeroD0);
            Append(code, ReturnFromSubroutine);
        }

        void EmitFreeAndRestoreFailure(bool freeSecond, bool freeFirst)
        {
            if (freeSecond)
            {
                Append(code, MoveAddressD6ToA0);
                Append(code, MoveLongImmediateD0); Append(code, 0);
                Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
                Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
                AppendExecFreeMemFromA0PreservingA1(code);
            }

            if (freeFirst)
            {
                Append(code, MoveAddressD5ToA0);
                Append(code, MoveLongImmediateD0); Append(code, 0);
                Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
                Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
                AppendExecFreeMemFromA0PreservingA1(code);
            }

            EmitRestoreFailure();
        }

        void EmitAllocationAddressValidation(List<int> failureBranches, ushort moveToRegister)
        {
            Append(code, BitTestImmediateD0); Append(code, 0);
            Append(code, BranchEqualWord);
            var evenExtensionOffset = code.Count; Append(code, 0);
            Append(code, BranchAlwaysWord);
            var oddExtensionOffset = code.Count; Append(code, 0);
            var evenOffset = code.Count;
            PatchBranch(code, evenExtensionOffset, evenOffset);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Append(code, BranchHighWord);
            failureBranches.Add(code.Count); Append(code, 0);
            failureBranches.Add(oddExtensionOffset);
            Append(code, moveToRegister);
        }

        // Preserve the caller's seed while the complete three-node source is
        // admitted. A2/A3/A4 retain the source nodes; A5 retains its header.
        Append(code, MoveLongD0ToPreDecrementA7);
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA2);
        EmitAddressAdmission(
            MoveLongA0DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA0ToA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, MoveLongA5ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveAddressA0ToA5);

        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA2DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA3);

        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA3DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);

        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitRelativeBoundsValidation(
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD5,
            MoveWordA2DisplacementToD5);
        EmitRelativeBoundsValidation(
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD5,
            MoveWordA3DisplacementToD5);
        EmitRelativeBoundsValidation(
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD5,
            MoveWordA4DisplacementToD5);

        // Canonical Region lists are vertically ordered; touching or
        // overlapping source nodes stay on the portable boolean builder.
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA3DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA4DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);

        // The destination must be marker-owned and empty. Its envelope is
        // replaced only after all three new nodes have been initialized. The
        // marker admission reuses A2, so retain the source head in A6 first.
        Append(code, MoveAddressA2ToA6);
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);

        Append(code, MoveLongA1ToPreDecrementA7);
        Append(code, MoveLongA5ToPreDecrementA7);
        Append(code, MoveLongA6ToPreDecrementA7);
        Append(code, MoveLongA3ToPreDecrementA7);
        Append(code, MoveLongA4ToPreDecrementA7);

        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var execMissingExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveAddressD0ToA6);

        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        firstAllocationFailureBranches.Add(code.Count); Append(code, 0);
        EmitAllocationAddressValidation(firstAllocationFailureBranches, MoveLongD0ToD5);

        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        secondAllocationFailureBranches.Add(code.Count); Append(code, 0);
        EmitAllocationAddressValidation(secondAllocationFailureBranches, MoveLongD0ToD6);

        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        thirdAllocationFailureBranches.Add(code.Count); Append(code, 0);
        EmitAllocationAddressValidation(thirdAllocationFailureBranches, MoveLongD0ToD7);

        // Restore guest pointers while D5/D6/D7 retain the three private
        // allocations. The caller's seed is discarded only after success.
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);
        Append(code, MoveLongA7PostIncrementToD0);

        void CopyBounds(ushort sourceRegisterMove, ushort destinationRegisterMove)
        {
            foreach (var displacement in new[] { 0, 2, 4, 6 })
            {
                Append(code, sourceRegisterMove);
                Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
                Append(code, destinationRegisterMove);
                Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
            }
        }

        Append(code, MoveAddressD5ToA0);
        CopyBounds(MoveWordA2DisplacementToD4, MoveWordD4ToA0Displacement);
        Append(code, MoveAddressD6ToA0);
        CopyBounds(MoveWordA3DisplacementToD4, MoveWordD4ToA0Displacement);
        Append(code, MoveAddressD7ToA0);
        CopyBounds(MoveWordA4DisplacementToD4, MoveWordD4ToA0Displacement);

        // Publish the source envelope and the fully linked private chain only
        // after all allocations and writes have completed.
        foreach (var displacement in new[] { 0, 2, 4, 6 })
        {
            Append(code, MoveWordA5DisplacementToD0);
            Append(code, (ushort)(GraphicsLayouts.RectangleMinX + displacement));
            Append(code, MoveWordD0ToA1Displacement);
            Append(code, (ushort)(GraphicsLayouts.RectangleMinX + displacement));
        }

        Append(code, MoveAddressA1ToA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, MoveLongA0ToD0);
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveLongD5ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongD7ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD7ToA0);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveLongD5ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var execMissingRestoreOffset = code.Count;
        for (var index = 0; index < 6; index++)
            Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var execMissingFallbackExtensionOffset = code.Count; Append(code, 0);

        var thirdAllocationFailureOffset = code.Count;
        EmitFreeAndRestoreFailure(freeSecond: true, freeFirst: true);
        var secondAllocationFailureOffset = code.Count;
        EmitFreeAndRestoreFailure(freeSecond: false, freeFirst: true);
        var firstAllocationFailureOffset = code.Count;
        EmitRestoreFailure();

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);

        PatchBranch(code, execMissingExtensionOffset, execMissingRestoreOffset);
        PatchBranch(code, execMissingFallbackExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in firstAllocationFailureBranches)
            PatchBranch(code, branch, firstAllocationFailureOffset);
        foreach (var branch in secondAllocationFailureBranches)
            PatchBranch(code, branch, secondAllocationFailureOffset);
        foreach (var branch in thirdAllocationFailureBranches)
            PatchBranch(code, branch, thirdAllocationFailureOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Admits the bounded read-only OR identity where a canonical one-node
    /// source is contained by the second node of a canonical two-node
    /// destination and is strictly disjoint from the first node. Complete
    /// ownership, link, envelope, and relative-bounds admission precedes
    /// success; no allocation or public mutation occurs. Every other shape
    /// restores D0 and continues through the operation-specific fallback.
    /// </summary>
    private static int AppendOrRegionRegionOneNodeTwoNodeContainedBySecondNative(
        List<byte> code,
        int fallbackEntryOffset,
        List<int>? boundsNormalizationCallExtensions = null) =>
        AppendOrRegionRegionOneNodeTwoNodeContainedNative(
            code,
            fallbackEntryOffset,
            containedBySecond: true,
            boundsNormalizationCallExtensions: boundsNormalizationCallExtensions);

    /// <summary>
    /// Admits the symmetric bounded read-only OR identity where the source is
    /// contained by the first destination node and is strictly disjoint from
    /// the second destination node. The complete ownership/link/envelope
    /// proof is shared with the second-node form; only the two rectangle roles
    /// in the final geometric proof are swapped.
    /// </summary>
    private static int AppendOrRegionRegionOneNodeTwoNodeContainedByFirstNative(
        List<byte> code,
        int fallbackEntryOffset,
        List<int>? boundsNormalizationCallExtensions = null) =>
        AppendOrRegionRegionOneNodeTwoNodeContainedNative(
            code,
            fallbackEntryOffset,
            containedBySecond: false,
            boundsNormalizationCallExtensions: boundsNormalizationCallExtensions);

    private static int AppendOrRegionRegionOneNodeTwoNodeContainedNative(
        List<byte> code,
        int fallbackEntryOffset,
        bool containedBySecond,
        List<int>? boundsNormalizationCallExtensions = null)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(64);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitAddressAdmission(ushort moveAddressToD0, ushort displacement)
        {
            Append(code, moveAddressToD0); Append(code, displacement);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        void EmitRelativeBoundsValidation(
            ushort nodeMinXToD4,
            ushort nodeMinYToD4,
            ushort nodeMaxXToD5,
            ushort nodeMaxYToD5)
        {
            Append(code, nodeMinXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, nodeMaxXToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, nodeMinYToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, nodeMaxYToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);

        // Source: exactly one canonical native node.
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA0DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA0ToA3);
        Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitRelativeBoundsValidation(
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD5,
            MoveWordA5DisplacementToD5);

        // Destination: exactly two canonical native nodes.
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA1DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA1ToA2);
        Append(code, AddQuickFourLongA2); Append(code, AddQuickFourLongA2);
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA4DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA4ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitRelativeBoundsValidation(
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD5,
            MoveWordA4DisplacementToD5);
        EmitRelativeBoundsValidation(
            MoveWordA6DisplacementToD4,
            MoveWordA6DisplacementToD4,
            MoveWordA6DisplacementToD5,
            MoveWordA6DisplacementToD5);

        // The public envelopes must match before relative containment is
        // compared directly.
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, CompareWordD5ToD1); Decline(BranchNotEqualWord);
        Append(code, CompareWordD6ToD2); Decline(BranchNotEqualWord);
        Append(code, CompareWordD7ToD3); Decline(BranchNotEqualWord);

        var containedNodeToD0 = containedBySecond
            ? MoveWordA6DisplacementToD0
            : MoveWordA4DisplacementToD0;
        var containedNodeToD6 = containedBySecond
            ? MoveWordA6DisplacementToD6
            : MoveWordA4DisplacementToD6;
        var disjointNodeToD4 = containedBySecond
            ? MoveWordA4DisplacementToD4
            : MoveWordA6DisplacementToD4;
        var disjointNodeToD0 = containedBySecond
            ? MoveWordA4DisplacementToD0
            : MoveWordA6DisplacementToD0;

        // Source rectangle is contained by the selected destination
        // rectangle. Signed subtraction keeps the admission safe at the word
        // boundary.
        Append(code, containedNodeToD0); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordA5DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
        Append(code, TestWordD6); Decline(BranchLessThanWord);
        Append(code, containedNodeToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordA5DisplacementToD6); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
        Append(code, TestWordD6); Decline(BranchLessThanWord);
        Append(code, MoveWordA5DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, containedNodeToD6); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
        Append(code, TestWordD6); Decline(BranchLessThanWord);
        Append(code, MoveWordA5DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, containedNodeToD6); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
        Append(code, TestWordD6); Decline(BranchLessThanWord);

        // The source must be strictly disjoint from the other destination
        // node. Any one of the four positive gaps proves no inclusive touch.
        var disjointSuccessBranches = new List<int>(4);
        void EmitGap(
            ushort leftBoundMove,
            ushort leftBoundDisplacement,
            ushort rightBoundMove,
            ushort rightBoundDisplacement)
        {
            Append(code, leftBoundMove); Append(code, leftBoundDisplacement);
            Append(code, rightBoundMove); Append(code, rightBoundDisplacement);
            Append(code, CompareWordD4ToD0);
            Append(code, BranchGreaterThanWord);
            disjointSuccessBranches.Add(code.Count); Append(code, 0);
        }

        EmitGap(
            MoveWordA5DisplacementToD4,
            (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX),
            disjointNodeToD0,
            (ushort)GraphicsLayouts.RegionRectangleBounds);
        EmitGap(
            disjointNodeToD4,
            (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX),
            MoveWordA5DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangleBounds);
        EmitGap(
            MoveWordA5DisplacementToD4,
            (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY),
            disjointNodeToD0,
            (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        EmitGap(
            disjointNodeToD4,
            (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY),
            MoveWordA5DisplacementToD0,
            (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, BranchAlwaysWord);
        var disjointFallbackOffset = code.Count; Append(code, 0);
        var disjointSuccessOffset = code.Count;
        foreach (var branch in disjointSuccessBranches)
            PatchBranch(code, branch, disjointSuccessOffset);

        if (boundsNormalizationCallExtensions is not null)
        {
            Append(code, BranchSubroutineWord);
            boundsNormalizationCallExtensions.Add(code.Count);
            Append(code, 0);
        }
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, disjointFallbackOffset, fallbackRestoreOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Admits the bounded read-only OR identity where corresponding nodes of
    /// canonical two-node source and destination Regions are nested under a
    /// matching public envelope. The destination is already the complete
    /// union, so no allocation or public mutation is needed. Every other
    /// shape restores D0/A0 and delegates to the normal OR path. The optional
    /// modes select containment by the first or second destination node.
    /// </summary>
    private static int AppendOrRegionRegionTwoNodeSourceContainedByTwoNodeNative(
        List<byte> code,
        int fallbackEntryOffset,
        bool sourceNodesContainedByFirstDestinationNode = false,
        bool sourceNodesContainedBySecondDestinationNode = false,
        List<int>? boundsNormalizationCallExtensions = null)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(72);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitAddressAdmission(ushort moveAddressToD0, ushort displacement)
        {
            Append(code, moveAddressToD0); Append(code, displacement);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        void EmitRelativeBoundsValidation(
            ushort nodeMinXToD4,
            ushort nodeMinYToD4,
            ushort nodeMaxXToD5,
            ushort nodeMaxYToD5)
        {
            Append(code, nodeMinXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, nodeMaxXToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, nodeMinYToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, nodeMaxYToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        void EmitContainedPair(ushort sourceNodeToA2, ushort destinationNodeToA2)
        {
            Append(code, sourceNodeToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA2DisplacementToD1); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA2DisplacementToD2); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA2DisplacementToD3); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

            Append(code, destinationNodeToA2);
            Append(code, MoveWordA2DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, CompareWordD4ToD0); Decline(BranchLessThanWord);
            Append(code, MoveWordA2DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD1); Decline(BranchLessThanWord);
            Append(code, MoveWordA2DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD2); Decline(BranchGreaterThanWord);
            Append(code, MoveWordA2DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD3); Decline(BranchGreaterThanWord);
        }

        // Preserve the source public pointer before either admission reuses
        // A0/A2. D0 remains the only stack value needed by the fallback.
        Append(code, MoveLongA0ToD7);
        Append(code, MoveLongD0ToPreDecrementA7);

        // Source: exactly two canonical native nodes.
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA0DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA0ToA3);
        Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA2DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitRelativeBoundsValidation(
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD5,
            MoveWordA2DisplacementToD5);
        EmitRelativeBoundsValidation(
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD5,
            MoveWordA5DisplacementToD5);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA5DisplacementToD0);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD0); Decline(BranchLessOrEqualWord);

        // Keep the source first node in A6 while the destination admission
        // reuses A2/A3; the source second node remains in A5.
        Append(code, MoveAddressA2ToA6);

        // Destination: exactly two canonical native nodes.
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA1DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA1ToA3);
        Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA4DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA4ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        // The public envelopes must match. Reload the source envelope from
        // D7, compare against destination A1, then use destination A0 for
        // the relative-bounds checks below.
        Append(code, MoveAddressD7ToA0);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, CompareWordD4ToD1); Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, CompareWordD4ToD2); Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD3); Decline(BranchNotEqualWord);

        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitRelativeBoundsValidation(
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD5,
            MoveWordA4DisplacementToD5);
        EmitRelativeBoundsValidation(
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD5,
            MoveWordA3DisplacementToD5);
        Append(code, MoveWordA4DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA3DisplacementToD0);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD0); Decline(BranchLessOrEqualWord);

        if (sourceNodesContainedByFirstDestinationNode)
        {
            EmitContainedPair(MoveAddressA6ToA2, MoveAddressA4ToA2);
            EmitContainedPair(MoveAddressA5ToA2, MoveAddressA4ToA2);
        }
        else if (sourceNodesContainedBySecondDestinationNode)
        {
            EmitContainedPair(MoveAddressA6ToA2, MoveAddressA3ToA2);
            EmitContainedPair(MoveAddressA5ToA2, MoveAddressA3ToA2);
        }
        else
        {
            EmitContainedPair(MoveAddressA6ToA2, MoveAddressA4ToA2);
            EmitContainedPair(MoveAddressA5ToA2, MoveAddressA3ToA2);
        }

        Append(code, MoveAddressD7ToA0);
        Append(code, MoveLongA7PostIncrementToD0);
        if (boundsNormalizationCallExtensions is null)
        {
            Append(code, MoveQuickOneD0);
            Append(code, ReturnFromSubroutine);
        }
        else
        {
            Append(code, BranchAlwaysWord);
            boundsNormalizationCallExtensions.Add(code.Count);
            Append(code, 0);
        }

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Admits the bounded read-only OR identity where a canonical two-node
    /// source is contained by a canonical one-node destination under the same
    /// public envelope. The destination is already the complete union, so no
    /// allocation or public mutation is needed. All ownership, link,
    /// envelope, relative-bounds, ordering, and containment checks precede
    /// success; every other shape restores D0 and delegates to the normal OR
    /// path.
    /// </summary>
    private static int AppendOrRegionRegionTwoNodeSourceContainedByOneNodeNative(
        List<byte> code,
        int fallbackEntryOffset,
        List<int>? boundsNormalizationCallExtensions = null)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(72);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitAddressAdmission(ushort moveAddressToD0, ushort displacement)
        {
            Append(code, moveAddressToD0); Append(code, displacement);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        void EmitRelativeBoundsValidation(
            ushort nodeMinXToD4,
            ushort nodeMinYToD4,
            ushort nodeMaxXToD5,
            ushort nodeMaxYToD5)
        {
            Append(code, nodeMinXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, nodeMaxXToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, nodeMinYToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, nodeMaxYToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        void EmitContainedNode(ushort nodeToA2)
        {
            Append(code, nodeToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA2DisplacementToD1); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA2DisplacementToD2); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA2DisplacementToD3); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

            // Source min >= destination min and destination max >= source max.
            Append(code, MoveWordA4DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, CompareWordD6ToD0); Decline(BranchLessThanWord);
            Append(code, MoveWordA4DisplacementToD6); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD6ToD1); Decline(BranchLessThanWord);
            Append(code, MoveWordA4DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, SubWordD2ToD0); Decline(BranchOverflowWord);
            Append(code, TestWordD0); Decline(BranchLessThanWord);
            Append(code, MoveWordA4DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, SubWordD3ToD0); Decline(BranchOverflowWord);
            Append(code, TestWordD0); Decline(BranchLessThanWord);
        }

        // Keep the original source header available for the portable fallback
        // after destination admission has reused A0 for its own envelope.
        Append(code, MoveLongA0ToD7);
        Append(code, MoveLongD0ToPreDecrementA7);

        // Source: exactly two canonical native nodes.
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA0DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA2DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA0ToA3);
        Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitRelativeBoundsValidation(
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD5,
            MoveWordA2DisplacementToD5);
        EmitRelativeBoundsValidation(
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD5,
            MoveWordA5DisplacementToD5);
        // Require the canonical source order to be a strict vertical pair.
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA5DisplacementToD0);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD0); Decline(BranchLessOrEqualWord);
        Append(code, MoveAddressA2ToA6);

        // Destination: exactly one canonical native node.
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA1DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA1ToA3);
        Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveAddressA1ToA0);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitRelativeBoundsValidation(
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD5,
            MoveWordA4DisplacementToD5);

        // Matching public envelopes let the relative containment proof avoid
        // signed cross-origin arithmetic.
        Append(code, MoveAddressD7ToA0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, CompareWordD5ToD1); Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, CompareWordD6ToD2); Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD3); Decline(BranchNotEqualWord);

        EmitContainedNode(MoveAddressA6ToA2);
        EmitContainedNode(MoveAddressA5ToA2);

        Append(code, MoveLongA7PostIncrementToD0);
        if (boundsNormalizationCallExtensions is null)
        {
            Append(code, MoveQuickOneD0);
            Append(code, ReturnFromSubroutine);
        }
        else
        {
            Append(code, BranchAlwaysWord);
            boundsNormalizationCallExtensions.Add(code.Count);
            Append(code, 0);
        }

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Publishes the bounded two-node disjoint OR/XOR replacement form. The
    /// admitted shape uses identical public envelopes, with both source nodes
    /// vertically preceding both destination nodes by default. The optional
    /// one-node destination mode admits the complementary source-above-
    /// destination form; the optional reverse mode admits the destination-
    /// before-source order for the two-node destination. Two fresh public
    /// nodes copy the source rectangles and are linked on the appropriate side
    /// of the existing destination chain; allocation and address-class
    /// failures roll back privately before publication.
    /// </summary>
    private static int AppendOrXorRegionRegionTwoNodeDisjointNative(
        List<byte> code,
        int fallbackEntryOffset,
        bool sourceNodesBelowDestination = false,
        bool destinationOneNode = false)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(12);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitRestoreFailure()
        {
            // The transaction frame contains old-destination-second,
            // source-second, source-first, old-destination-first,
            // destination header, then the caller's original D0.
            for (var index = 0; index < 6; index++)
                Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickZeroD0);
            Append(code, ReturnFromSubroutine);
        }

        void EmitFreeAndRestoreFailure(
            ushort moveAllocationToA0,
            ushort moveFirstAllocationToA0,
            bool freeFirst)
        {
            Append(code, moveAllocationToA0);
            Append(code, MoveLongImmediateD0); Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
            AppendExecFreeMemFromA0PreservingA1(code);
            if (freeFirst)
            {
                Append(code, moveFirstAllocationToA0);
                Append(code, MoveLongImmediateD0); Append(code, 0);
                Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
                Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
                AppendExecFreeMemFromA0PreservingA1(code);
            }
            EmitRestoreFailure();
        }

        // Keep the caller's seed until either the private transaction or the
        // portable fallback has completed.
        Append(code, MoveLongD0ToPreDecrementA7);

        // This arm is reserved for a two-node source.  The public dispatch
        // ladder also visits it for one-node/two-node operands, so reject that
        // topology before interpreting a null successor as an address.  The
        // canonical predecessor/successor checks below still validate the
        // complete shape before any allocation or publication.
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);

        // Reload the admitted headers and require the same absolute envelope
        // so relative source bounds can be copied without coordinate
        // translation.
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, CompareWordD5ToD1); Decline(BranchNotEqualWord);
        Append(code, CompareWordD6ToD2); Decline(BranchNotEqualWord);
        Append(code, CompareWordD7ToD3); Decline(BranchNotEqualWord);

        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA4);
        if (destinationOneNode)
        {
            Append(code, MoveLongA4DisplacementToD0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, TestLongD0);
            Decline(BranchNotEqualWord);
        }
        else
        {
            Append(code, MoveLongA4DisplacementToD6);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveAddressD6ToA6);
        }

        // Require canonical vertical ordering and a strict gap between the
        // source and destination chains. Touching rectangles are inclusive
        // overlap and therefore remain on the portable XOR/OR path.
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA3DisplacementToD0);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD0); Decline(BranchLessOrEqualWord);
        if (sourceNodesBelowDestination && destinationOneNode)
        {
            Append(code, MoveWordA4DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA2DisplacementToD0);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD0); Decline(BranchLessOrEqualWord);
        }
        else if (sourceNodesBelowDestination)
        {
            Append(code, MoveWordA4DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA6DisplacementToD0);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD0); Decline(BranchLessOrEqualWord);
            Append(code, MoveWordA6DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);
        }
        else if (destinationOneNode)
        {
            Append(code, MoveWordA3DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);
        }
        else
        {
            Append(code, MoveWordA4DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA6DisplacementToD0);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD0); Decline(BranchLessOrEqualWord);
            Append(code, MoveWordA3DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);
        }

        // Preserve the old destination tail before A6 is reused for ExecBase
        // during the private allocation transaction.  The one-node form has
        // no tail; its saved A6 slot is intentionally left as the caller's
        // value so the common rollback frame stays the same size.
        if (sourceNodesBelowDestination)
            Append(code, MoveAddressA6ToA5);

        // Resolve Exec before opening the private allocation transaction.
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0);
        Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA6);

        // Save all guest identities below the original D0. A1 remains live as
        // the FreeMem-preservation register during both allocation failures;
        // the old second destination node is retained for reverse publication.
        Append(code, MoveLongA1ToPreDecrementA7);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0ToPreDecrementA7);
        Append(code, MoveLongA2ToPreDecrementA7);
        Append(code, MoveLongA3ToPreDecrementA7);
        Append(code, sourceNodesBelowDestination
            ? MoveLongA5ToPreDecrementA7
            : MoveLongA6ToPreDecrementA7);

        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var firstAllocationSucceededExtensionOffset = code.Count;
        Append(code, 0);
        EmitRestoreFailure();

        var firstAllocationSucceededOffset = code.Count;
        PatchBranch(code, firstAllocationSucceededExtensionOffset, firstAllocationSucceededOffset);
        Append(code, BitTestImmediateD0); Append(code, 0);
        Append(code, BranchEqualWord);
        var firstAllocationEvenExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var firstAllocationBadExtensionOffset = code.Count; Append(code, 0);
        var firstAllocationEvenOffset = code.Count;
        PatchBranch(code, firstAllocationEvenExtensionOffset, firstAllocationEvenOffset);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchHighWord);
        var firstAllocationAddressableExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var firstAllocationHighExtensionOffset = code.Count; Append(code, 0);
        var firstAllocationAddressableOffset = code.Count;
        // The high-address branch declines; the fall-through relay admits
        // the ordinary low/even allocation address.
        Append(code, MoveLongD0ToD6);

        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var secondAllocationSucceededExtensionOffset = code.Count;
        Append(code, 0);
        EmitFreeAndRestoreFailure(
            MoveAddressD6ToA0,
            MoveAddressD6ToA0,
            freeFirst: false);

        var secondAllocationSucceededOffset = code.Count;
        PatchBranch(code, secondAllocationSucceededExtensionOffset, secondAllocationSucceededOffset);
        Append(code, BitTestImmediateD0); Append(code, 0);
        Append(code, BranchEqualWord);
        var secondAllocationEvenExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var secondAllocationBadExtensionOffset = code.Count; Append(code, 0);
        var secondAllocationEvenOffset = code.Count;
        PatchBranch(code, secondAllocationEvenExtensionOffset, secondAllocationEvenOffset);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchHighWord);
        var secondAllocationAddressableExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var secondAllocationHighExtensionOffset = code.Count; Append(code, 0);
        var secondAllocationAddressableOffset = code.Count;
        Append(code, MoveLongD0ToD7);
        Append(code, BranchAlwaysWord);
        var secondAllocationSuccessExtensionOffset = code.Count; Append(code, 0);

        var secondAllocationBadOffset = code.Count;
        PatchBranch(code, secondAllocationBadExtensionOffset, secondAllocationBadOffset);
        PatchBranch(code, secondAllocationHighExtensionOffset, secondAllocationAddressableOffset);
        EmitFreeAndRestoreFailure(
            MoveAddressD0ToA0,
            MoveAddressD6ToA0,
            freeFirst: true);

        var firstAllocationBadOffset = code.Count;
        PatchBranch(code, firstAllocationBadExtensionOffset, firstAllocationBadOffset);
        PatchBranch(code, firstAllocationAddressableExtensionOffset, firstAllocationBadOffset);
        PatchBranch(code, firstAllocationHighExtensionOffset, firstAllocationAddressableOffset);
        PatchBranch(code, secondAllocationAddressableExtensionOffset, secondAllocationBadOffset);
        PatchBranch(code, secondAllocationHighExtensionOffset, secondAllocationAddressableOffset);
        EmitFreeAndRestoreFailure(
            MoveAddressD0ToA0,
            MoveAddressD6ToA0,
            freeFirst: false);

        var secondAllocationSuccessOffset = code.Count;
        PatchBranch(code, secondAllocationSuccessExtensionOffset, secondAllocationSuccessOffset);

        // D6/D7 retain the two new allocations. Restore the saved guest
        // pointers while the original D0 remains at the bottom of the frame.
        // A5 receives the old second destination node for reverse publication.
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveLongD0ToD4);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);

        void CopyBounds(ushort sourceRegisterMove, ushort destinationRegisterMove)
        {
            foreach (var displacement in new[] { 0, 2, 4, 6 })
            {
                Append(code, sourceRegisterMove); Append(code,
                    (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
                Append(code, destinationRegisterMove); Append(code,
                    (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
            }
        }

        // D6 is the first new node and D7 is the second; use their address
        // forms as temporary A6/A0 destinations for the word copies.
        Append(code, MoveAddressD6ToA6);
        CopyBounds(MoveWordA2DisplacementToD0, MoveWordD0ToA6Displacement);
        Append(code, MoveAddressD7ToA0);
        CopyBounds(MoveWordA3DisplacementToD0, MoveWordD0ToA0Displacement);

        if (sourceNodesBelowDestination)
        {
            // D6=new1, D7=new2, A4=old destination first.  A5 is the old
            // second node for the two-node destination form; a one-node
            // destination appends directly after A4.
            if (destinationOneNode)
            {
                Append(code, MoveAddressA4ToA0);
                Append(code, MoveLongD6ToD0);
                Append(code, MoveLongD0ToA0Displacement);
                Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
                Append(code, MoveAddressD6ToA0);
                Append(code, MoveLongA4ToD0);
                Append(code, MoveLongD0ToA0Displacement);
                Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
                Append(code, MoveAddressD6ToA0);
                Append(code, MoveLongD7ToA0Displacement);
                Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
                Append(code, MoveAddressD7ToA0);
                Append(code, MoveLongD6ToA0Displacement);
                Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
                Append(code, MoveAddressD7ToA0);
                Append(code, MoveQuickZeroD0);
                Append(code, MoveLongD0ToA0Displacement);
                Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            }
            else
            {
                // Keep the existing destination head and append the source
                // pair after its second node.
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveLongD6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveAddressD6ToA0);
            Append(code, MoveLongA5ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveAddressD6ToA0);
            Append(code, MoveLongD7ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveAddressD7ToA0);
            Append(code, MoveLongD6ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveAddressD7ToA0);
            Append(code, MoveQuickZeroD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            }
        }
        else
        {
            // Re-establish the private four-node chain, then publish only its
            // new head. Existing destination nodes remain owned and need no
            // retirement. D6=new1, D7=new2, A4=old destination first, A1=destination.
            Append(code, MoveLongA4DisplacementToD4);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveLongA1DisplacementToD0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangle);
            Append(code, MoveAddressD6ToA0);
            Append(code, MoveLongD4ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveAddressD6ToA0);
            Append(code, MoveLongD7ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveAddressD7ToA0);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveAddressD7ToA0);
            Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongD7ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveAddressA1ToA0);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        }
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Publishes the bounded one-source-node/two-destination-node disjoint
    /// OR/XOR form. The public envelopes must match and the three canonical
    /// rectangles must be separated by strict vertical gaps. One fresh public
    /// node is allocated privately, copied from the source node, and prepended
    /// to the existing two-node destination chain by default. The optional
    /// reverse mode appends it after that chain; all admission failures restore
    /// D0 and continue through the operation-specific canonical entry, while
    /// allocation/address failures free privately without changing the list.
    /// </summary>
    private static int AppendOrXorRegionRegionOneNodeTwoNodeDisjointNative(
        List<byte> code,
        int fallbackEntryOffset,
        bool sourceNodeBelowDestination = false,
        bool sourceNodeBetweenDestinationNodes = false)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(48);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitRestoreFailure()
        {
            // The private frame contains source, destination header, old
            // destination first, old destination second, then the caller's
            // original D0.
            for (var index = 0; index < 4; index++)
                Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickZeroD0);
            Append(code, ReturnFromSubroutine);
        }

        void EmitFreeAndRestoreFailure()
        {
            // A1 remains the destination header until the saved frame is
            // restored, so the normal FreeMem adapter can preserve it.
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongImmediateD0); Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
            AppendExecFreeMemFromA0PreservingA1(code);
            EmitRestoreFailure();
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitAddressAdmission(ushort moveAddressToD0, ushort displacement)
        {
            Append(code, moveAddressToD0); Append(code, displacement);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        void EmitRelativeBoundsValidation(
            ushort nodeMinXToD4,
            ushort nodeMinYToD4,
            ushort nodeMaxXToD5,
            ushort nodeMaxYToD5)
        {
            Append(code, nodeMinXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, nodeMaxXToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, nodeMinYToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, nodeMaxYToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);

        // Source: exactly one canonical native node.
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA0DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA0ToA3);
        Append(code, AddQuickFourLongA3);
        Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        // Keep the source node in A5 while the destination admission reuses
        // A2 for its predecessor calculations.  No stack frame is opened
        // until every shape check has passed, so every decline still owns
        // only the caller's saved D0.
        Append(code, MoveAddressA2ToA6);
        Append(code, MoveAddressA6ToA5);

        // Destination: exactly two canonical native nodes.
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA1DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA1ToA2);
        Append(code, AddQuickFourLongA2);
        Append(code, AddQuickFourLongA2);
        Append(code, MoveLongA2ToD6);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA4DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA4ToD6);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        // The two public envelopes must be identical.
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, CompareWordD5ToD1); Decline(BranchNotEqualWord);
        Append(code, CompareWordD6ToD2); Decline(BranchNotEqualWord);
        Append(code, CompareWordD7ToD3); Decline(BranchNotEqualWord);
        Append(code, CompareWordD4ToD6); Decline(BranchLessThanWord);
        Append(code, CompareWordD5ToD7); Decline(BranchLessThanWord);

        // Reload the source public envelope before validating each relative
        // rectangle; the helper intentionally keeps all writes private.
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        EmitRelativeBoundsValidation(
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD5,
            MoveWordA5DisplacementToD5);
        EmitRelativeBoundsValidation(
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD5,
            MoveWordA4DisplacementToD5);
        EmitRelativeBoundsValidation(
            MoveWordA6DisplacementToD4,
            MoveWordA6DisplacementToD4,
            MoveWordA6DisplacementToD5,
            MoveWordA6DisplacementToD5);

        // Strict vertical gaps make the three rectangles pairwise disjoint,
        // so OR and XOR have the same replacement list.
        if (sourceNodeBetweenDestinationNodes)
        {
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA5DisplacementToD0);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD5ToD0); Decline(BranchLessOrEqualWord);
            Append(code, MoveWordA5DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA6DisplacementToD0);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD5ToD0); Decline(BranchLessOrEqualWord);
        }
        else if (sourceNodeBelowDestination)
        {
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA6DisplacementToD0);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD5ToD0); Decline(BranchLessOrEqualWord);
            Append(code, MoveWordA6DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA5DisplacementToD0);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD5ToD0); Decline(BranchLessOrEqualWord);
        }
        else
        {
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA4DisplacementToD0);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD5ToD0); Decline(BranchLessOrEqualWord);
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA6DisplacementToD0);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD5ToD0); Decline(BranchLessOrEqualWord);
        }

        // Preserve the second node while ExecBase is resolved, then open the
        // private frame used by allocation rollback.
        Append(code, MoveLongA6ToD7);
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA5ToPreDecrementA7);
        Append(code, MoveLongA1ToPreDecrementA7);
        Append(code, MoveLongA4ToPreDecrementA7);
        Append(code, MoveLongD7ToPreDecrementA7);

        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var allocationSucceededExtensionOffset = code.Count; Append(code, 0);
        EmitRestoreFailure();

        var allocationSucceededOffset = code.Count;
        PatchBranch(code, allocationSucceededExtensionOffset, allocationSucceededOffset);
        Append(code, BitTestImmediateD0); Append(code, 0);
        Append(code, BranchEqualWord);
        var allocationEvenExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var allocationBadExtensionOffset = code.Count; Append(code, 0);
        var allocationEvenOffset = code.Count;
        PatchBranch(code, allocationEvenExtensionOffset, allocationEvenOffset);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchHighWord);
        var allocationAddressableExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var allocationHighExtensionOffset = code.Count; Append(code, 0);
        var allocationAddressableOffset = code.Count;
        Append(code, MoveLongD0ToD6);

        // Restore source, destination, first node, and second node while the
        // original D0 remains at the bottom of the transaction frame.
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA2);

        // Copy the source-relative bounds into the fresh public node.
        Append(code, MoveAddressD6ToA0);
        foreach (var displacement in new[] { 0, 2, 4, 6 })
        {
            Append(code, MoveWordA2DisplacementToD0);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
        }

        if (sourceNodeBetweenDestinationNodes)
        {
            // Insert between the existing nodes; the destination head and
            // both public Region headers remain unchanged.
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongD6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);

            Append(code, MoveAddressD6ToA0);
            Append(code, MoveLongA4ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);

            Append(code, MoveAddressA6ToA0);
            Append(code, MoveLongD6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);

            Append(code, MoveAddressD6ToA0);
            Append(code, MoveLongA6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        }
        else if (sourceNodeBelowDestination)
        {
            // Append the new source node after the existing second node and
            // leave the destination head unchanged.
            Append(code, MoveAddressA6ToA0);
            Append(code, MoveLongD6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveAddressD6ToA0);
            Append(code, MoveLongA6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveAddressD6ToA0);
            Append(code, MoveQuickZeroD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        }
        else
        {
            // Prepend the fresh node, preserving the old first->second chain.
            Append(code, MoveAddressA1ToA3);
            Append(code, AddQuickFourLongA3);
            Append(code, AddQuickFourLongA3);
            Append(code, MoveLongA3ToD0);
            Append(code, MoveAddressD6ToA0);
            Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveAddressD6ToA0);
            Append(code, MoveLongA4ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveAddressA1ToA0);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        }
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var allocationBadOffset = code.Count;
        PatchBranch(code, allocationBadExtensionOffset, allocationBadOffset);
        PatchBranch(code, allocationAddressableExtensionOffset, allocationBadOffset);
        PatchBranch(code, allocationHighExtensionOffset, allocationAddressableOffset);
        EmitFreeAndRestoreFailure();

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Collapses a canonical one-node OR source that strictly contains both
    /// nodes of a canonical two-node destination. The caller has already
    /// proved ownership, links, matching public envelopes, and strict
    /// containment for both destination nodes; this continuation allocates
    /// one replacement node privately, publishes it, then retires both old
    /// nodes. The source remains untouched and every allocation/Exec failure
    /// restores the caller frame without public mutation.
    /// </summary>
    private static int AppendOrRegionRegionOneNodeTwoNodeSourceContainsBothNative(
        List<byte> code,
        int fallbackEntryOffset,
        List<int>? boundsNormalizationCallExtensions = null)
    {
        var offset = code.Count;

        void EmitRestoreFailure()
        {
            // The caller's original D0 is below source, destination, old
            // first, and old second pointers.
            for (var index = 0; index < 5; index++)
                Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickZeroD0);
            Append(code, ReturnFromSubroutine);
        }

        void EmitFreeAndRestoreFailure()
        {
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongImmediateD0); Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
            AppendExecFreeMemFromA0PreservingA1(code);
            EmitRestoreFailure();
        }

        // Entry contract from the contained/two-node admission: A0 is the
        // source Region, A1 the destination Region, A5 the source node, A4
        // the old destination first node, A6 the old second node, and the
        // caller's original D0 is already on the stack.
        Append(code, MoveLongA6ToD7);
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var execMissingRestoreExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveAddressD0ToA6);

        Append(code, MoveLongA5ToPreDecrementA7);
        Append(code, MoveLongA1ToPreDecrementA7);
        Append(code, MoveLongA4ToPreDecrementA7);
        Append(code, MoveLongD7ToPreDecrementA7);

        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var allocationSucceededExtensionOffset = code.Count; Append(code, 0);
        EmitRestoreFailure();

        var allocationSucceededOffset = code.Count;
        PatchBranch(code, allocationSucceededExtensionOffset, allocationSucceededOffset);
        Append(code, BitTestImmediateD0); Append(code, 0);
        Append(code, BranchEqualWord);
        var allocationEvenExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var allocationBadExtensionOffset = code.Count; Append(code, 0);
        var allocationEvenOffset = code.Count;
        PatchBranch(code, allocationEvenExtensionOffset, allocationEvenOffset);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchHighWord);
        var allocationAddressableExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var allocationHighExtensionOffset = code.Count; Append(code, 0);
        var allocationAddressableOffset = code.Count;
        Append(code, MoveLongD0ToD6);

        // Restore public pointers; A6 remains ExecBase for the two retirements.
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA2);

        // Copy the source-relative rectangle into the fresh replacement node.
        Append(code, MoveAddressD6ToA0);
        foreach (var displacement in new[] { 0, 2, 4, 6 })
        {
            Append(code, MoveWordA2DisplacementToD0);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
        }

        // Initialize the complete one-node chain before publishing its head.
        Append(code, MoveAddressA1ToA3);
        Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD0);
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);

        // Retire both old public nodes only after the replacement is visible.
        Append(code, MoveAddressD7ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0);
        if (boundsNormalizationCallExtensions is not null)
        {
            Append(code, BranchSubroutineWord);
            boundsNormalizationCallExtensions.Add(code.Count);
            Append(code, 0);
        }
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var allocationBadOffset = code.Count;
        PatchBranch(code, allocationBadExtensionOffset, allocationBadOffset);
        PatchBranch(code, allocationAddressableExtensionOffset, allocationBadOffset);
        PatchBranch(code, allocationHighExtensionOffset, allocationAddressableOffset);
        EmitFreeAndRestoreFailure();

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, execMissingRestoreExtensionOffset, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Publishes the bounded overlapping OR form where a canonical one-node
    /// source strictly contains the first node of a canonical two-node
    /// destination and the second destination node is vertically below the
    /// source. The result is the source rectangle followed by the existing
    /// second node, so one fresh public node replaces the contained first
    /// node. The source remains untouched; every allocation/address/Exec
    /// failure rolls back before the old first node is retired.
    /// </summary>
    private static int AppendOrRegionRegionOneNodeTwoNodeContainedNative(
        List<byte> code,
        int fallbackEntryOffset,
        int sourceContainsBothEntryOffset = -1,
        List<int>? boundsNormalizationCallExtensions = null)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(56);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitRestoreFailure()
        {
            // The private frame contains source, destination header, old
            // first node, old second node, then the caller's original D0.
            for (var index = 0; index < 4; index++)
                Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickZeroD0);
            Append(code, ReturnFromSubroutine);
        }

        void EmitFreeAndRestoreFailure()
        {
            Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongImmediateD0); Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
            AppendExecFreeMemFromA0PreservingA1(code);
            EmitRestoreFailure();
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitAddressAdmission(ushort moveAddressToD0, ushort displacement)
        {
            Append(code, moveAddressToD0); Append(code, displacement);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        void EmitRelativeBoundsValidation(
            ushort nodeMinXToD4,
            ushort nodeMinYToD4,
            ushort nodeMaxXToD5,
            ushort nodeMaxYToD5)
        {
            Append(code, nodeMinXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, nodeMaxXToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, nodeMinYToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, nodeMaxYToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);

        // Source: exactly one canonical native node.
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA0DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA0ToA3);
        Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        // Keep the source node in A5 while the destination admission reuses
        // A2 for predecessor calculations. No transaction frame is opened
        // until the complete shape proof has passed.
        Append(code, MoveAddressA2ToA6);
        Append(code, MoveAddressA6ToA5);

        // Destination: exactly two canonical native nodes.
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA1DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA1ToA2);
        Append(code, AddQuickFourLongA2); Append(code, AddQuickFourLongA2);
        Append(code, MoveLongA2ToD6);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA4DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA4ToD6);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        // The public envelopes must match and each relative node rectangle
        // must be valid inside that common envelope.
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, CompareWordD5ToD1); Decline(BranchNotEqualWord);
        Append(code, CompareWordD6ToD2); Decline(BranchNotEqualWord);
        Append(code, CompareWordD7ToD3); Decline(BranchNotEqualWord);
        Append(code, CompareWordD4ToD6); Decline(BranchLessThanWord);
        Append(code, CompareWordD5ToD7); Decline(BranchLessThanWord);

        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        EmitRelativeBoundsValidation(
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD5,
            MoveWordA2DisplacementToD5);
        EmitRelativeBoundsValidation(
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD5,
            MoveWordA4DisplacementToD5);
        EmitRelativeBoundsValidation(
            MoveWordA6DisplacementToD4,
            MoveWordA6DisplacementToD4,
            MoveWordA6DisplacementToD5,
            MoveWordA6DisplacementToD5);

        // Strict containment is the admitted overlap form: the source is
        // wider and taller than the first destination node. The second node
        // remains below the source, so the result is source followed by that
        // already-owned node.
        Append(code, MoveAddressA5ToA2);
        Append(code, MoveWordA2DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordA2DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordA2DisplacementToD7); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA4DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordA4DisplacementToD1); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordA4DisplacementToD2); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordA4DisplacementToD3); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD4ToD0); Decline(BranchLessOrEqualWord);
        Append(code, CompareWordD5ToD1); Decline(BranchLessOrEqualWord);
        Append(code, CompareWordD6ToD2); Decline(BranchGreaterOrEqualWord);
        Append(code, CompareWordD7ToD3); Decline(BranchGreaterOrEqualWord);

        // A source that strictly contains both destination nodes collapses
        // the OR result to one rectangle. Try that topology before the
        // existing source-plus-lower-node form; every miss continues through
        // the established second-below proof.
        if (sourceContainsBothEntryOffset >= 0)
        {
            var sourceContainsBothMissBranches = new List<int>(4);

            void SourceContainsBothMiss(ushort branchOpcode)
            {
                Append(code, branchOpcode);
                sourceContainsBothMissBranches.Add(code.Count);
                Append(code, 0);
            }

            Append(code, MoveWordA5DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA5DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA5DisplacementToD6); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA5DisplacementToD7); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA6DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA6DisplacementToD1); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA6DisplacementToD2); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA6DisplacementToD3); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD0); SourceContainsBothMiss(BranchLessOrEqualWord);
            Append(code, CompareWordD5ToD1); SourceContainsBothMiss(BranchLessOrEqualWord);
            Append(code, CompareWordD6ToD2); SourceContainsBothMiss(BranchGreaterOrEqualWord);
            Append(code, CompareWordD7ToD3); SourceContainsBothMiss(BranchGreaterOrEqualWord);
            Append(code, BranchAlwaysWord);
            var sourceContainsBothExtensionOffset = code.Count; Append(code, 0);

            var secondBelowOffset = code.Count;
            foreach (var branch in sourceContainsBothMissBranches)
                PatchBranch(code, branch, secondBelowOffset);
            PatchBranch(code, sourceContainsBothExtensionOffset, sourceContainsBothEntryOffset);
        }

        // The second destination node must remain below the source. This
        // also proves that its existing predecessor can be replaced by the
        // new source node without reordering any other public node.
        Append(code, MoveWordA5DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA6DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD0); Decline(BranchLessOrEqualWord);

        // Resolve Exec before opening the private transaction frame. A5
        // retains source and D7 retains the existing second node.
        Append(code, MoveLongA6ToD7);
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA5ToPreDecrementA7);
        Append(code, MoveLongA1ToPreDecrementA7);
        Append(code, MoveLongA4ToPreDecrementA7);
        Append(code, MoveLongD7ToPreDecrementA7);

        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var allocationSucceededExtensionOffset = code.Count; Append(code, 0);
        EmitRestoreFailure();

        var allocationSucceededOffset = code.Count;
        PatchBranch(code, allocationSucceededExtensionOffset, allocationSucceededOffset);
        Append(code, BitTestImmediateD0); Append(code, 0);
        Append(code, BranchEqualWord);
        var allocationEvenExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var allocationBadExtensionOffset = code.Count; Append(code, 0);
        var allocationEvenOffset = code.Count;
        PatchBranch(code, allocationEvenExtensionOffset, allocationEvenOffset);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchHighWord);
        var allocationAddressableExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var allocationHighExtensionOffset = code.Count; Append(code, 0);
        var allocationAddressableOffset = code.Count;
        Append(code, MoveLongD0ToD6);

        // Restore the public pointers but leave A6 as ExecBase for retirement.
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA2);

        // Copy the source-relative rectangle into the fresh replacement node.
        Append(code, MoveAddressD6ToA0);
        foreach (var displacement in new[] { 0, 2, 4, 6 })
        {
            Append(code, MoveWordA2DisplacementToD0);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
        }

        // Link new source -> existing second, publish the head, then retire
        // the contained old first node. No public pointer is changed before
        // the fresh node is fully initialized.
        Append(code, MoveAddressA1ToA3);
        Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD0);
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveLongD7ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD7ToA0);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);

        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0);
        if (boundsNormalizationCallExtensions is not null)
        {
            Append(code, BranchSubroutineWord);
            boundsNormalizationCallExtensions.Add(code.Count);
            Append(code, 0);
        }
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var allocationBadOffset = code.Count;
        PatchBranch(code, allocationBadExtensionOffset, allocationBadOffset);
        PatchBranch(code, allocationAddressableExtensionOffset, allocationBadOffset);
        PatchBranch(code, allocationHighExtensionOffset, allocationAddressableOffset);
        EmitFreeAndRestoreFailure();

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Keeps the short empty-list identities ahead of the increasingly large
    /// canonical OR topology ladder. The public entry still validates every
    /// malformed/foreign Region through the established ladder; this relay
    /// only classifies marker-owned native Regions whose head pointer is
    /// already null. D0 is restored before entering any destination body.
    /// </summary>
    private static int AppendOrRegionRegionEmptyDispatchNative(
        List<byte> code,
        int fallbackEntryOffset,
        int nonEmptyEntryOffset,
        int sourceEmptyEntryOffset,
        int destinationOneNodeEmptyEntryOffset,
        int destinationTwoNodeEmptyEntryOffset,
        int destinationThreeNodeEmptyEntryOffset,
        int destinationFourNodeEmptyEntryOffset)
    {
        var offset = code.Count;
        // Keep the dispatcher-to-nonempty return within 68000 Bcc.W reach as
        // the native Region body grows. Entry skips the nearby return relay;
        // the far main-path branch can reach the relay, which hops back to
        // the nonempty implementation just ahead of this dispatcher.
        Append(code, (ushort)(BranchAlwaysShort | 0x0008)); // Skip the two four-byte return relays.
        var nonEmptyReturnRelayOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var nonEmptyReturnRelayExtensionOffset = code.Count; Append(code, 0);
        // Keep the source-empty relay at the dispatcher front. Its target is
        // near the signed-word reach limit as later native Region bodies grow.
        var sourceEmptyReturnRelayOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var sourceEmptyReturnRelayExtensionOffset = code.Count; Append(code, 0);
        var nonEmptyBranches = new List<int>(12);
        var sourceEmptyBranches = new List<int>(1);
        var destinationEmptyBranches = new List<int>(1);
        var malformedBranches = new List<int>(1);

        void Route(ushort opcode, List<int> branches)
        {
            Append(code, opcode);
            branches.Add(code.Count);
            Append(code, 0);
        }

        void AdmitOwnedRegion(ushort moveRegionToD0, List<int> emptyBranches)
        {
            Append(code, moveRegionToD0);
            Append(code, TestLongD0);
            Route(BranchEqualWord, emptyBranches);
            Append(code, BitTestImmediateD0);
            Append(code, 0);
            Route(BranchNotEqualWord, nonEmptyBranches);
            Append(code, CompareImmediateLongD0);
            Append(code, 0xFFFF);
            Append(code, 0xFFF4);
            Route(BranchHighWord, nonEmptyBranches);
            Append(code, SubQuickFourLongD0);
            Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0);
            Append(code, 0);
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.NativeRegionMarker);
            Route(BranchNotEqualWord, nonEmptyBranches);
        }

        // Preserve the caller's seed while the relay classifies both public
        // Region envelopes. No target body observes the relay's scratch D0.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0);
        Route(BranchEqualWord, sourceEmptyBranches);
        AdmitOwnedRegion(MoveLongA0ToD0, nonEmptyBranches);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0);
        Route(BranchEqualWord, nonEmptyBranches);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0);
        Route(BranchEqualWord, destinationEmptyBranches);
        AdmitOwnedRegion(MoveLongA1ToD0, nonEmptyBranches);

        // A second return relay near the dispatcher tail keeps the main
        // nonempty return branch inside signed 68000 Bcc.W reach as this
        // classifier grows. Ordinary classification skips over the relay.
        Append(code, BranchAlwaysWord);
        var nonEmptyReturnRelaySkipExtensionOffset = code.Count; Append(code, 0);
        var destinationOneNodeReturnRelayOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var destinationOneNodeReturnRelayExtensionOffset = code.Count; Append(code, 0);
        var destinationTwoNodeReturnRelayOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var destinationTwoNodeReturnRelayExtensionOffset = code.Count; Append(code, 0);
        var destinationThreeNodeReturnRelayOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var destinationThreeNodeReturnRelayExtensionOffset = code.Count; Append(code, 0);
        var destinationFourNodeReturnRelayOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var destinationFourNodeReturnRelayExtensionOffset = code.Count; Append(code, 0);
        var nonEmptyReturnRelayTailOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var nonEmptyReturnRelayTailExtensionOffset = code.Count; Append(code, 0);
        var dispatcherAfterReturnRelayOffset = code.Count;
        PatchBranch(code, nonEmptyReturnRelaySkipExtensionOffset, dispatcherAfterReturnRelayOffset);
        PatchBranch(code, sourceEmptyReturnRelayExtensionOffset, sourceEmptyEntryOffset);
        PatchBranch(code, destinationOneNodeReturnRelayExtensionOffset, destinationOneNodeEmptyEntryOffset);
        PatchBranch(code, destinationTwoNodeReturnRelayExtensionOffset, destinationTwoNodeEmptyEntryOffset);
        PatchBranch(code, destinationThreeNodeReturnRelayExtensionOffset, destinationThreeNodeEmptyEntryOffset);
        PatchBranch(code, destinationFourNodeReturnRelayExtensionOffset, destinationFourNodeEmptyEntryOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var nonEmptyDestinationExtensionOffset = code.Count;
        Append(code, 0);

        // The destination-empty source ladder is selected by the terminal
        // link count so the common one-node transfer does not walk the
        // larger three/four-node proof bodies before returning.
        var destinationEmptyLadderOffset = code.Count;
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var oneNodeExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var twoNodeExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var threeNodeExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        malformedBranches.Add(code.Count);
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var fourNodeExtensionOffset = code.Count;
        Append(code, 0);

        var invalidRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var invalidJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, invalidJumpExtensionOffset, fallbackEntryOffset);

        var mainRestoreOffset = code.Count;
        PatchBranch(code, nonEmptyDestinationExtensionOffset, mainRestoreOffset);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var mainJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, mainJumpExtensionOffset, nonEmptyReturnRelayTailOffset);
        PatchBranch(code, nonEmptyReturnRelayTailExtensionOffset, nonEmptyReturnRelayOffset);
        PatchBranch(code, nonEmptyReturnRelayExtensionOffset, nonEmptyEntryOffset);

        var sourceEmptyRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var sourceEmptyJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, sourceEmptyJumpExtensionOffset, sourceEmptyReturnRelayOffset);

        var destinationOneNodeRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var destinationOneNodeJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, destinationOneNodeJumpExtensionOffset, destinationOneNodeReturnRelayOffset);

        var destinationTwoNodeRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var destinationTwoNodeJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, destinationTwoNodeJumpExtensionOffset, destinationTwoNodeReturnRelayOffset);

        var destinationThreeNodeRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var destinationThreeNodeJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, destinationThreeNodeJumpExtensionOffset, destinationThreeNodeReturnRelayOffset);

        var destinationFourNodeRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var destinationFourNodeJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, destinationFourNodeJumpExtensionOffset, destinationFourNodeReturnRelayOffset);

        PatchBranch(code, oneNodeExtensionOffset, destinationOneNodeRestoreOffset);
        PatchBranch(code, twoNodeExtensionOffset, destinationTwoNodeRestoreOffset);
        PatchBranch(code, threeNodeExtensionOffset, destinationThreeNodeRestoreOffset);
        PatchBranch(code, fourNodeExtensionOffset, destinationFourNodeRestoreOffset);

        foreach (var branch in nonEmptyBranches)
            PatchBranch(code, branch, invalidRestoreOffset);
        foreach (var branch in malformedBranches)
            PatchBranch(code, branch, invalidRestoreOffset);
        foreach (var branch in sourceEmptyBranches)
            PatchBranch(code, branch, sourceEmptyRestoreOffset);
        foreach (var branch in destinationEmptyBranches)
            PatchBranch(code, branch, destinationEmptyLadderOffset);
        return offset;
    }

    /// <summary>
    /// Adds the XOR-only empty-source identity in front of the operation
    /// ladder.  The existing XOR ladder already owns every nonempty-source
    /// case; this short relay only reads the source head, restores the caller
    /// seed, and selects the local read-only canonical empty-source proof.
    /// </summary>
    private static int AppendOrXorRegionRegionEmptySourceOnlyDispatchNative(
        List<byte> code,
        int nonEmptyEntryOffset,
        int emptySourceEntryOffset,
        int emptyDestinationEntryOffset)
    {
        var offset = code.Count;
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var nonEmptyExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var emptyExtensionOffset = code.Count;
        Append(code, 0);
        var nonEmptySourceOffset = code.Count;
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var nonEmptySourceExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var execPresentExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, ReturnFromSubroutine);
        var execPresentOffset = code.Count;
        PatchBranch(code, execPresentExtensionOffset, execPresentOffset);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var emptyDestinationExtensionOffset = code.Count;
        Append(code, 0);
        var nonEmptyRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var nonEmptyJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, emptyExtensionOffset, emptySourceEntryOffset);
        PatchBranch(code, nonEmptyExtensionOffset, nonEmptySourceOffset);
        PatchBranch(code, nonEmptySourceExtensionOffset, nonEmptyRestoreOffset);
        PatchBranch(code, emptyDestinationExtensionOffset, emptyDestinationEntryOffset);
        PatchBranch(code, nonEmptyJumpExtensionOffset, nonEmptyEntryOffset);
        return offset;
    }

    /// <summary>
    /// Publishes the bounded coalesced OR form where a canonical one-node
    /// source and the first node of a canonical two-node destination overlap
    /// horizontally and have identical Y spans. The union remains one
    /// rectangle, so the first destination node can be widened in place while
    /// the second node remains below it. All malformed, envelope-mismatched,
    /// or topology-changing forms delegate without public mutation.
    /// </summary>
    private static int AppendOrRegionRegionOneNodeTwoNodeCoalescedNative(
        List<byte> code,
        int fallbackEntryOffset,
        bool coalesceSecondNode = false,
        int? emptyFallbackEntryOffset = null,
        List<int>? boundsNormalizationCallExtensions = null)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(64);
        var emptyFallbackBranches = new List<int>(4);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void DeclineEmpty(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            emptyFallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitAddressAdmission(ushort moveAddressToD0, ushort displacement)
        {
            Append(code, moveAddressToD0); Append(code, displacement);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        void EmitRelativeBoundsValidation(
            ushort nodeMinXToD4,
            ushort nodeMinYToD4,
            ushort nodeMaxXToD5,
            ushort nodeMaxYToD5)
        {
            Append(code, nodeMinXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, nodeMaxXToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, nodeMinYToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, nodeMaxYToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveAddressA0ToA3);

        if (emptyFallbackEntryOffset.HasValue)
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangle);
            Append(code, TestLongD0); DeclineEmpty(BranchEqualWord);
            Append(code, MoveLongA1DisplacementToD0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangle);
            Append(code, TestLongD0); DeclineEmpty(BranchEqualWord);
        }

        // Source: exactly one canonical node.
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        EmitAddressAdmission(
            MoveLongA0DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA0ToA2);
        Append(code, AddQuickFourLongA2); Append(code, AddQuickFourLongA2);
        Append(code, MoveLongA2ToD6);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitRelativeBoundsValidation(
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD5,
            MoveWordA5DisplacementToD5);

        // Destination: exactly two canonical nodes.
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        EmitAddressAdmission(
            MoveLongA1DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA1ToA2);
        Append(code, AddQuickFourLongA2); Append(code, AddQuickFourLongA2);
        Append(code, MoveLongA2ToD6);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        EmitAddressAdmission(
            MoveLongA4DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA4ToD6);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        // Validate the destination public envelope and both relative nodes.
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitRelativeBoundsValidation(
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD5,
            MoveWordA4DisplacementToD5);
        EmitRelativeBoundsValidation(
            MoveWordA6DisplacementToD4,
            MoveWordA6DisplacementToD4,
            MoveWordA6DisplacementToD5,
            MoveWordA6DisplacementToD5);

        // The established arm coalesces the first destination node. The
        // mirrored bounded arm below may instead target the second node while
        // leaving the first node and both links untouched.
        var targetWordToD4 = coalesceSecondNode
            ? MoveWordA6DisplacementToD4
            : MoveWordA4DisplacementToD4;
        var targetWordToD5 = coalesceSecondNode
            ? MoveWordA6DisplacementToD5
            : MoveWordA4DisplacementToD5;
        var targetAddressToA0 = coalesceSecondNode
            ? MoveAddressA6ToA0
            : MoveAddressA4ToA0;
        var verticalTargetAddressToA0 = coalesceSecondNode
            ? MoveAddressA6ToA0
            : MoveAddressA4ToA0;

        // Public envelopes must match. The two node spans must share Y and
        // the second node must remain strictly below the coalesced first.
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, CompareWordD5ToD1); Decline(BranchNotEqualWord);
        Append(code, CompareWordD6ToD2); Decline(BranchNotEqualWord);
        Append(code, CompareWordD7ToD3); Decline(BranchNotEqualWord);

        // Equal X spans form the vertical coalescing mirror. Dispatch it
        // before the horizontal equal-Y checks below; non-equal X spans keep
        // the existing horizontal-overlap path.
        Append(code, MoveWordA5DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, targetWordToD5); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, CompareWordD4ToD5); Append(code, BranchNotEqualWord);
        var verticalDispatchFirstExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveWordA5DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, targetWordToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD4ToD5); Append(code, BranchNotEqualWord);
        var verticalDispatchSecondExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var verticalBodyExtensionOffset = code.Count; Append(code, 0);
        var horizontalBodyOffset = code.Count;
        PatchBranch(code, verticalDispatchFirstExtensionOffset, horizontalBodyOffset);
        PatchBranch(code, verticalDispatchSecondExtensionOffset, horizontalBodyOffset);

        Append(code, MoveWordA5DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, targetWordToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchNotEqualWord);
        Append(code, MoveWordA5DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, targetWordToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD4ToD5); Decline(BranchNotEqualWord);
        Append(code, MoveWordA4DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA6DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);

        // The source and first destination rectangles overlap in X. This is
        // deliberately overlap-only; touching/gapped and topology-changing
        // forms remain on the established portable/native dispatch.
        Append(code, MoveWordA5DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, targetWordToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
        Append(code, targetWordToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordA5DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);

        // Compute the union X span without changing any public byte until all
        // structural and geometry checks above have completed.
        Append(code, MoveWordA5DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD4ToD6);
        Append(code, targetWordToD5); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, CompareWordD4ToD5);
        Append(code, BranchGreaterThanWord);
        var unionMinExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveWordD5ToD6);
        var unionMinReadyOffset = code.Count;
        PatchBranch(code, unionMinExtensionOffset, unionMinReadyOffset);

        Append(code, MoveWordA5DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD4ToD7);
        Append(code, targetWordToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD4ToD5);
        Append(code, BranchLessThanWord);
        var unionMaxExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveWordD5ToD7);
        var unionMaxReadyOffset = code.Count;
        PatchBranch(code, unionMaxExtensionOffset, unionMaxReadyOffset);

        Append(code, targetAddressToA0);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD7ToA0Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0);
        if (boundsNormalizationCallExtensions is not null)
        {
            Append(code, BranchSubroutineWord);
            boundsNormalizationCallExtensions.Add(code.Count);
            Append(code, 0);
        }
        Append(code, ReturnFromSubroutine);

        var verticalBodyOffset = code.Count;
        PatchBranch(code, verticalBodyExtensionOffset, verticalBodyOffset);

        // Vertical coalescing: equal X spans, inclusive Y overlap, and a
        // second destination node strictly below the union. The success
        // epilogue canonicalizes the public envelope from the resulting chain.
        Append(code, MoveWordA5DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, targetWordToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
        Append(code, targetWordToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordA5DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);

        Append(code, MoveWordA5DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, targetWordToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordD4ToD6);
        Append(code, CompareWordD4ToD5);
        Append(code, BranchGreaterThanWord);
        var verticalUnionMaxFirstExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveWordD5ToD6);
        var verticalUnionMaxFirstReadyOffset = code.Count;
        PatchBranch(code, verticalUnionMaxFirstExtensionOffset, verticalUnionMaxFirstReadyOffset);
        if (coalesceSecondNode)
        {
            // The target is the lower second node, so the existing first
            // node must end strictly before the union begins. Preserve the
            // union maximum while computing the minimum below.
            Append(code, MoveWordD6ToD7);
        }
        else
        {
            Append(code, MoveWordA6DisplacementToD7); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD6ToD7); Decline(BranchLessOrEqualWord);
        }

        Append(code, MoveWordA5DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, targetWordToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD4ToD6);
        Append(code, CompareWordD4ToD5);
        Append(code, BranchGreaterThanWord);
        var verticalUnionMinExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveWordD5ToD6);
        var verticalUnionMinReadyOffset = code.Count;
        PatchBranch(code, verticalUnionMinExtensionOffset, verticalUnionMinReadyOffset);
        if (coalesceSecondNode)
        {
            Append(code, MoveWordA4DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD6); Decline(BranchLessOrEqualWord);
        }

        Append(code, MoveWordA5DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, targetWordToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordD4ToD7);
        Append(code, CompareWordD4ToD5);
        Append(code, BranchLessThanWord);
        var verticalUnionMaxExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveWordD5ToD7);
        var verticalUnionMaxReadyOffset = code.Count;
        PatchBranch(code, verticalUnionMaxExtensionOffset, verticalUnionMaxReadyOffset);

        Append(code, verticalTargetAddressToA0);
        Append(code, MoveWordD6ToA0Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD7ToA0Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0);
        if (boundsNormalizationCallExtensions is not null)
        {
            Append(code, BranchSubroutineWord);
            boundsNormalizationCallExtensions.Add(code.Count);
            Append(code, 0);
        }
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        var emptyFallbackRestoreOffset = -1;
        var emptyFallbackJumpExtensionOffset = -1;
        if (emptyFallbackEntryOffset.HasValue)
        {
            emptyFallbackRestoreOffset = code.Count;
            Append(code, MoveAddressA3ToA0);
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, BranchAlwaysWord);
            emptyFallbackJumpExtensionOffset = code.Count; Append(code, 0);
            PatchBranch(code, emptyFallbackJumpExtensionOffset, emptyFallbackEntryOffset.Value);
        }
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        foreach (var branch in emptyFallbackBranches)
            PatchBranch(code, branch, emptyFallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Collapses the exact vertical bridge where a canonical one-node source
    /// fills the two gaps between a canonical two-node destination. The first
    /// destination node is widened in place and the old second node is freed
    /// only after the public links and bounds have been published.
    /// </summary>
    private static int AppendOrRegionRegionOneNodeTwoNodeBridgeCollapseNative(
        List<byte> code,
        int fallbackEntryOffset,
        List<int>? boundsNormalizationCallExtensions = null)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(64);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitAddressAdmission(ushort moveAddressToD0, ushort displacement)
        {
            Append(code, moveAddressToD0); Append(code, displacement);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        void EmitNodeBounds(ushort nodeToA0)
        {
            Append(code, nodeToA0);
            Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
            Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveAddressA0ToA3);
        Append(code, MoveAddressA1ToA4);

        EmitOwnedRegionAdmission(MoveLongA3ToD0);
        Append(code, MoveLongA3DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        EmitAddressAdmission(MoveLongA3DisplacementToD0, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA5DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA5DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA3ToA2); Append(code, AddQuickFourLongA2); Append(code, AddQuickFourLongA2);
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        EmitOwnedRegionAdmission(MoveLongA4ToD0);
        Append(code, MoveLongA4DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        EmitAddressAdmission(MoveLongA4DisplacementToD0, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA2DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA4ToA1); Append(code, AddQuickFourLongA1); Append(code, AddQuickFourLongA1);
        Append(code, MoveLongA1ToD6); Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        EmitAddressAdmission(MoveLongA2DisplacementToD0, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA6DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA6DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        // The two public envelopes must match exactly.
        Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA4DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA4DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, CompareWordD4ToD1); Decline(BranchNotEqualWord);
        Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA4DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, CompareWordD4ToD2); Decline(BranchNotEqualWord);
        Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordA4DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD3); Decline(BranchNotEqualWord);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);

        // Every node must span the public X envelope; Y bounds remain inside it.
        EmitNodeBounds(MoveAddressA5ToA0);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD4ToD2); Decline(BranchNotEqualWord);
        EmitNodeBounds(MoveAddressA2ToA0);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD4ToD2); Decline(BranchNotEqualWord);
        EmitNodeBounds(MoveAddressA6ToA0);
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD4ToD2); Decline(BranchNotEqualWord);

        // Strict adjacency: first.maxY + 1 == source.minY and
        // source.maxY + 1 == second.minY.
        Append(code, MoveWordA2DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, AddQuickOneWordD4);
        Append(code, MoveWordA5DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchNotEqualWord);
        Append(code, MoveWordA5DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, AddQuickOneWordD4);
        Append(code, MoveWordA6DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchNotEqualWord);

        // Resolve Exec only after the complete proof; D6 retains the node to retire.
        Append(code, MoveLongA6ToD6);
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var execMissingExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveAddressD0ToA6);

        // Publish the widened first node and terminate its public successor.
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY)));
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveWordD4ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);

        Append(code, MoveAddressD6ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveAddressA4ToA1);
        Append(code, MoveLongA7PostIncrementToD0);
        if (boundsNormalizationCallExtensions is not null)
        {
            Append(code, BranchSubroutineWord);
            boundsNormalizationCallExtensions.Add(code.Count);
            Append(code, 0);
        }
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        PatchBranch(code, execMissingExtensionOffset, code.Count);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveAddressA4ToA1);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveAddressA4ToA1);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Publishes the bounded XOR form where a full-width one-node source is
    /// strictly contained by the first node of a full-width two-node
    /// destination. Removing the source splits the first node into its upper
    /// and lower remainders; one fresh public node carries the lower remainder
    /// and the existing second node remains linked below it. The source is
    /// untouched and every allocation/address/Exec failure restores the caller
    /// frame before entering the prior XOR arm.
    /// </summary>
    private static int AppendXorRegionRegionOneNodeTwoNodeContainedByFirstNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(72);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitAddressAdmission(ushort moveAddressToD0, ushort displacement)
        {
            Append(code, moveAddressToD0); Append(code, displacement);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        void EmitNodeBoundsValidation(ushort nodeToAddress)
        {
            Append(code, nodeToAddress);
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            // Region node Y bounds are relative to RectangleMinY, not MinX.
            Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        void EmitAllocationFailure()
        {
            // The private frame contains source Region, destination Region,
            // old first node, old second node, then the caller's D0.
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA6);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA3);
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickZeroD0);
            Append(code, ReturnFromSubroutine);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveAddressA0ToA3); // source Region

        // Source: exactly one canonical native node and a valid public extent.
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA0DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA0ToA2);
        Append(code, AddQuickFourLongA2); Append(code, AddQuickFourLongA2);
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        EmitNodeBoundsValidation(MoveAddressA5ToA2);

        // Destination: exactly two canonical native nodes in first/second
        // order, with the lower node still strictly below the first.
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA1DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA1ToA2);
        Append(code, AddQuickFourLongA2); Append(code, AddQuickFourLongA2);
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(
            MoveLongA4DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA4ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        // Destination envelope is the common absolute extent for all three
        // nodes. Compare it directly with the source envelope before using
        // D0-D3 for relative-bound validation.
        Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA3DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, CompareWordD5ToD1); Decline(BranchNotEqualWord);
        Append(code, MoveWordA3DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, CompareWordD6ToD2); Decline(BranchNotEqualWord);
        Append(code, MoveWordA3DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD7ToD3); Decline(BranchNotEqualWord);
        EmitNodeBoundsValidation(MoveAddressA4ToA2);
        EmitNodeBoundsValidation(MoveAddressA6ToA2);

        // The intended split is full-width and strictly vertical. Requiring
        // all three nodes to span the common X envelope keeps this arm from
        // claiming horizontal or non-rectangular XOR forms.
        Append(code, MoveWordA5DisplacementToD4);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA5DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD4ToD2); Decline(BranchNotEqualWord);
        Append(code, MoveWordA4DisplacementToD4);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA4DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD4ToD2); Decline(BranchNotEqualWord);
        Append(code, MoveWordA6DisplacementToD4);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA6DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD4ToD2); Decline(BranchNotEqualWord);

        // Source lies strictly inside the first node, and the existing second
        // node remains strictly below the first. Signed word ordering is safe
        // because all rectangles were admitted as non-negative extents.
        Append(code, MoveWordA4DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordA5DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD5ToD4); Decline(BranchGreaterOrEqualWord);
        Append(code, MoveWordA5DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA4DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD5ToD4); Decline(BranchGreaterOrEqualWord);
        Append(code, MoveWordA4DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA6DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD5ToD4); Decline(BranchGreaterOrEqualWord);

        // Resolve Exec before opening the transaction frame. Preserve the old
        // second node in D7 because A6 becomes ExecBase for the gateway.
        Append(code, MoveLongA6ToD7);
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var execMissingExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA3ToPreDecrementA7);
        Append(code, MoveLongA1ToPreDecrementA7);
        Append(code, MoveLongA4ToPreDecrementA7);
        Append(code, MoveLongD7ToPreDecrementA7);

        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var allocationSucceededExtensionOffset = code.Count; Append(code, 0);
        EmitAllocationFailure();

        var allocationSucceededOffset = code.Count;
        PatchBranch(code, allocationSucceededExtensionOffset, allocationSucceededOffset);
        Append(code, BitTestImmediateD0); Append(code, 0);
        Append(code, BranchEqualWord);
        var allocationEvenExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var allocationBadExtensionOffset = code.Count; Append(code, 0);
        var allocationEvenOffset = code.Count;
        PatchBranch(code, allocationEvenExtensionOffset, allocationEvenOffset);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchHighWord);
        var allocationAddressableExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var allocationHighExtensionOffset = code.Count; Append(code, 0);
        var allocationAddressableOffset = code.Count;
        Append(code, MoveLongD0ToD6); // fresh lower remainder

        // Restore the public pointers while A6 remains ExecBase.
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA3);
        Append(code, MoveAddressD6ToA2);

        // Initialize the lower remainder completely before publishing it.
        Append(code, MoveWordA4DisplacementToD4);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD4ToA2Displacement);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordA5DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, AddQuickOneWordD4);
        Append(code, MoveWordD4ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordA4DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD4ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordA4DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordD4ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

        // Link first -> fresh lower remainder -> existing second, then trim
        // the first node's maximum Y. No public head changes are needed.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongD6ToA0Displacement);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA6ToD0);
        Append(code, MoveLongD0ToA2Displacement);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongD6ToA0Displacement);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveWordA5DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, SubQuickOneWordD4);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveWordD4ToA0Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var allocationBadOffset = code.Count;
        PatchBranch(code, allocationBadExtensionOffset, allocationBadOffset);
        PatchBranch(code, allocationAddressableExtensionOffset, allocationBadOffset);
        PatchBranch(code, allocationHighExtensionOffset, allocationAddressableOffset);
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendExecFreeMemFromA0PreservingA1(code);
        EmitAllocationFailure();

        PatchBranch(code, execMissingExtensionOffset, code.Count);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var execMissingJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, execMissingJumpExtensionOffset, fallbackEntryOffset);

        var containedSplitFallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var containedSplitFallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, containedSplitFallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, containedSplitFallbackRestoreOffset);
        return offset;
    }

    private static int AppendOrRegionRegionTightBoundsWrapperNative(
        List<byte> code,
        int rootEntryOffset)
    {
        var offset = code.Count;
        Append(code, BranchSubroutineWord);
        var rootCallExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var unsuccessfulExtensionOffset = code.Count;
        Append(code, 0);

        // Normalize only a successful result, and preserve the return value
        // plus every scratch register used by this ABI boundary pass.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA0ToPreDecrementA7);
        Append(code, MoveLongA2ToPreDecrementA7);
        foreach (var moveRegisterToStack in new[]
                 {
                     MoveLongD1ToPreDecrementA7,
                     MoveLongD2ToPreDecrementA7,
                     MoveLongD3ToPreDecrementA7,
                     MoveLongD4ToPreDecrementA7,
                     MoveLongD5ToPreDecrementA7,
                     MoveLongD6ToPreDecrementA7,
                     MoveLongD7ToPreDecrementA7
                 })
            Append(code, moveRegisterToStack);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var emptyRegionExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD0ToA2); // chain head for the rebasing pass
        Append(code, MoveAddressD0ToA0);

        void LoadFirstNodeBounds()
        {
            foreach (var pair in new[]
                     {
                         (GraphicsLayouts.RectangleMinX, MoveWordA0DisplacementToD0),
                         (GraphicsLayouts.RectangleMinY, MoveWordA0DisplacementToD1),
                         (GraphicsLayouts.RectangleMaxX, MoveWordA0DisplacementToD2),
                         (GraphicsLayouts.RectangleMaxY, MoveWordA0DisplacementToD3)
                     })
            {
                Append(code, pair.Item2);
                Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + pair.Item1)));
            }
        }

        void IncludeNodeBound(
            int rectangleOffset,
            ushort compareOpcode,
            ushort retainOpcode,
            ushort updateOpcode)
        {
            Append(code, MoveWordA0DisplacementToD4);
            Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + rectangleOffset)));
            Append(code, compareOpcode);
            Append(code, retainOpcode);
            var retainExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, updateOpcode);
            PatchBranch(code, retainExtensionOffset, code.Count);
        }

        LoadFirstNodeBounds();
        var scanNextNodeOffset = code.Count;
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var scanCompleteExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD4ToA0);
        IncludeNodeBound(
            GraphicsLayouts.RectangleMinX,
            CompareWordD4ToD0,
            BranchLessOrEqualWord,
            MoveWordD4ToD0);
        IncludeNodeBound(
            GraphicsLayouts.RectangleMinY,
            CompareWordD4ToD1,
            BranchLessOrEqualWord,
            MoveWordD4ToD1);
        IncludeNodeBound(
            GraphicsLayouts.RectangleMaxX,
            CompareWordD4ToD2,
            BranchGreaterOrEqualWord,
            MoveWordD4ToD2);
        IncludeNodeBound(
            GraphicsLayouts.RectangleMaxY,
            CompareWordD4ToD3,
            BranchGreaterOrEqualWord,
            MoveWordD4ToD3);
        Append(code, BranchAlwaysWord);
        var scanLoopExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, scanLoopExtensionOffset, scanNextNodeOffset);

        var scanCompleteOffset = code.Count;
        PatchBranch(code, scanCompleteExtensionOffset, scanCompleteOffset);

        // RegionRectangle coordinates are relative to the old origin. Store
        // the new absolute envelope and retain its relative origin deltas for
        // the second pass over the complete output chain.
        Append(code, MoveWordD0ToD6);
        Append(code, MoveWordD1ToD7);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)(GraphicsLayouts.RegionBounds + GraphicsLayouts.RectangleMinX)));
        Append(code, AddWordD4ToD0);
        Append(code, AddWordD4ToD2);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)(GraphicsLayouts.RegionBounds + GraphicsLayouts.RectangleMinX)));
        Append(code, MoveWordD2ToA1Displacement);
        Append(code, checked((ushort)(GraphicsLayouts.RegionBounds + GraphicsLayouts.RectangleMaxX)));
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)(GraphicsLayouts.RegionBounds + GraphicsLayouts.RectangleMinY)));
        Append(code, AddWordD4ToD1);
        Append(code, AddWordD4ToD3);
        Append(code, MoveWordD1ToA1Displacement);
        Append(code, checked((ushort)(GraphicsLayouts.RegionBounds + GraphicsLayouts.RectangleMinY)));
        Append(code, MoveWordD3ToA1Displacement);
        Append(code, checked((ushort)(GraphicsLayouts.RegionBounds + GraphicsLayouts.RectangleMaxY)));

        Append(code, MoveAddressA2ToA0);
        var rebaseNodeOffset = code.Count;
        foreach (var displacement in new[]
                 {
                     GraphicsLayouts.RectangleMinX,
                     GraphicsLayouts.RectangleMaxX,
                     GraphicsLayouts.RectangleMinY,
                     GraphicsLayouts.RectangleMaxY
                 })
        {
            Append(code, displacement is GraphicsLayouts.RectangleMinX or GraphicsLayouts.RectangleMaxX
                ? SubWordD6ToA0Displacement
                : SubWordD7ToA0Displacement);
            Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + displacement)));
        }
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rebaseCompleteExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD4ToA0);
        Append(code, BranchAlwaysWord);
        var rebaseLoopExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, rebaseLoopExtensionOffset, rebaseNodeOffset);

        var rebaseCompleteOffset = code.Count;
        PatchBranch(code, rebaseCompleteExtensionOffset, rebaseCompleteOffset);
        var restoreRegistersOffset = code.Count;
        PatchBranch(code, emptyRegionExtensionOffset, restoreRegistersOffset);
        foreach (var moveRegisterFromStack in new[]
                 {
                     MoveLongA7PostIncrementToD7,
                     MoveLongA7PostIncrementToD6,
                     MoveLongA7PostIncrementToD5,
                     MoveLongA7PostIncrementToD4,
                     MoveLongA7PostIncrementToD3,
                     MoveLongA7PostIncrementToD2,
                     MoveLongA7PostIncrementToD1
                 })
            Append(code, moveRegisterFromStack);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA7PostIncrementToD0); // successful result
        Append(code, ReturnFromSubroutine);

        var unsuccessfulOffset = code.Count;
        PatchBranch(code, unsuccessfulExtensionOffset, unsuccessfulOffset);
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, rootCallExtensionOffset, rootEntryOffset);
        return offset;
    }

    private static int AppendOrRegionRegionOneNodeTwoNodeGapInsertionNative(
        List<byte> code,
        int fallbackEntryOffset,
        bool allowPartialOverlap = false,
        bool normalizeFullChainBounds = false,
        List<int>? additionalBoundsNormalizationCallExtensions = null)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(64);
        var boundsNormalizationCallExtensions = new List<int>(5);
        var fullChainBoundsNormalizationCallExtensions = new List<int>(5);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitAddressAdmission(ushort moveAddressToD0, ushort displacement)
        {
            Append(code, moveAddressToD0); Append(code, displacement);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        void EmitNodeBoundsValidation(ushort nodeToAddress)
        {
            Append(code, nodeToAddress);
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        void EmitAllocationFailure()
        {
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA6);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA0);
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickZeroD0);
            Append(code, ReturnFromSubroutine);
        }

        void EmitTightenOutputRegionBounds()
        {
            // RegionRectangle coordinates are relative to Region.Bounds.
            // The output transaction can leave unused margins in the old
            // envelope, so calculate exact bounds from every published node
            // and rebase the whole chain as one transaction.
            Append(code, MoveLongD6ToD0);
            Append(code, MoveAddressD0ToA3); // preserve the upper/new node

            void LoadFirstNodeBounds()
            {
                Append(code, MoveAddressA4ToA0);
                foreach (var pair in new[]
                         {
                             (GraphicsLayouts.RectangleMinX, MoveWordD4ToD0),
                             (GraphicsLayouts.RectangleMinY, MoveWordD4ToD1),
                             (GraphicsLayouts.RectangleMaxX, MoveWordD4ToD2),
                             (GraphicsLayouts.RectangleMaxY, MoveWordD4ToD3)
                         })
                {
                    Append(code, MoveWordA0DisplacementToD4);
                    Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + pair.Item1)));
                    Append(code, pair.Item2);
                }
            }

            void IncludeNodeBounds(ushort moveNodeToA0)
            {
                Append(code, moveNodeToA0);
                foreach (var pair in new[]
                         {
                             (GraphicsLayouts.RectangleMinX, CompareWordD4ToD0,
                                 BranchLessOrEqualWord, MoveWordD4ToD0),
                             (GraphicsLayouts.RectangleMinY, CompareWordD4ToD1,
                                 BranchLessOrEqualWord, MoveWordD4ToD1),
                             (GraphicsLayouts.RectangleMaxX, CompareWordD4ToD2,
                                 BranchGreaterOrEqualWord, MoveWordD4ToD2),
                             (GraphicsLayouts.RectangleMaxY, CompareWordD4ToD3,
                                 BranchGreaterOrEqualWord, MoveWordD4ToD3)
                         })
                {
                    Append(code, MoveWordA0DisplacementToD4);
                    Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + pair.Item1)));
                    Append(code, pair.Item2);
                    Append(code, pair.Item3);
                    var retainExistingExtensionOffset = code.Count;
                    Append(code, 0);
                    Append(code, pair.Item4);
                    PatchBranch(code, retainExistingExtensionOffset, code.Count);
                }
            }

            LoadFirstNodeBounds();
            IncludeNodeBounds(MoveAddressA6ToA0);
            IncludeNodeBounds(MoveAddressA3ToA0);

            // Keep the relative origins while converting the tight result
            // envelope back to absolute Region.Bounds coordinates.
            Append(code, MoveWordD0ToD7);
            Append(code, MoveWordD1ToD6);
            Append(code, MoveWordA1DisplacementToD4);
            Append(code, checked((ushort)(GraphicsLayouts.RegionBounds + GraphicsLayouts.RectangleMinX)));
            Append(code, AddWordD4ToD0);
            Append(code, AddWordD4ToD2);
            Append(code, MoveWordD0ToA1Displacement);
            Append(code, checked((ushort)(GraphicsLayouts.RegionBounds + GraphicsLayouts.RectangleMinX)));
            Append(code, MoveWordD2ToA1Displacement);
            Append(code, checked((ushort)(GraphicsLayouts.RegionBounds + GraphicsLayouts.RectangleMaxX)));

            Append(code, MoveWordA1DisplacementToD4);
            Append(code, checked((ushort)(GraphicsLayouts.RegionBounds + GraphicsLayouts.RectangleMinY)));
            Append(code, AddWordD4ToD1);
            Append(code, AddWordD4ToD3);
            Append(code, MoveWordD1ToA1Displacement);
            Append(code, checked((ushort)(GraphicsLayouts.RegionBounds + GraphicsLayouts.RectangleMinY)));
            Append(code, MoveWordD3ToA1Displacement);
            Append(code, checked((ushort)(GraphicsLayouts.RegionBounds + GraphicsLayouts.RectangleMaxY)));

            void RebaseNodeBounds(ushort moveNodeToA0)
            {
                Append(code, moveNodeToA0);
                foreach (var displacement in new[]
                         {
                             GraphicsLayouts.RectangleMinX,
                             GraphicsLayouts.RectangleMinY,
                             GraphicsLayouts.RectangleMaxX,
                             GraphicsLayouts.RectangleMaxY
                         })
                {
                    Append(code, displacement is GraphicsLayouts.RectangleMinX or GraphicsLayouts.RectangleMaxX
                        ? SubWordD7ToA0Displacement
                        : SubWordD6ToA0Displacement);
