        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveAddressA0ToA3); // source Region

        // Source: exactly one canonical node.
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(MoveLongA0DisplacementToD0,
