        Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA0ToA2);
        Append(code, AddQuickFourLongA2); Append(code, AddQuickFourLongA2);
