        // so they reject only a source wholly above the first destination row.
        // The XOR caller retains the original strict-gap filter because
        // overlapping rectangles are not an XOR identity.
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(MoveLongA1DisplacementToD0,
