        Append(code, MoveAddressD0ToA4);
        Append(code, MoveWordA5DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds +
            (allowPartialOverlap ? GraphicsLayouts.RectangleMaxY : GraphicsLayouts.RectangleMinY)));
        Append(code, MoveWordA4DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds +
