        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA1ToA2);
        Append(code, AddQuickFourLongA2); Append(code, AddQuickFourLongA2);
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchEqualWord);
        EmitAddressAdmission(MoveLongA4DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA4ToD6); Append(code, CompareLongD6ToD0);
