        Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA3DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA3DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA3DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, CompareWordD5ToD1); Decline(BranchNotEqualWord);
        Append(code, CompareWordD6ToD2); Decline(BranchNotEqualWord);
        Append(code, CompareWordD7ToD3); Decline(BranchNotEqualWord);
