            var secondNodeOverhangTopEqualRejectBranches = new List<int>(3);
            var secondNodeOverhangContainsSecondBothEdgesBranches = new List<int>(2);
            var secondNodeOverhangTopAlignedSingleAllocationBranches = new List<int>(2);
