            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA6DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5);
            Append(code, BranchLessThanWord);
            var secondNodeOverhangBottomCandidateBranchExtensionOffset = code.Count;
            Append(code, 0);
            SkipSecondNodeOverhangVertical(BranchEqualWord);
            Append(code, MoveQuickZeroD3);
            Append(code, BranchAlwaysWord);
            var secondNodeOverhangStrictVerticalBranchExtensionOffset = code.Count;
            Append(code, 0);

            var secondNodeOverhangBottomCandidateOffset = code.Count;
            PatchBranch(
                code,
                secondNodeOverhangBottomCandidateBranchExtensionOffset,
                secondNodeOverhangBottomCandidateOffset);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA6DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5);
            SkipSecondNodeOverhangVertical(BranchLessThanWord);
            Append(code, MoveQuickOneD3);
            Append(code, BranchAlwaysWord);
            var secondNodeOverhangBottomHorizontalBranchExtensionOffset = code.Count;
            Append(code, 0);

            var secondNodeOverhangTopEqualOffset = code.Count;
