            Append(code, 0);
            Append(code, BranchAlwaysWord);
            var secondNodeTopAlignedLeftCandidateSkipBranchExtensionOffset = code.Count;
            Append(code, 0);
            var secondNodeTopAlignedRightCandidateOffset = code.Count;
            PatchBranch(
