                secondNodeTopAlignedRightCandidateBranchExtensionOffset,
                secondNodeTopAlignedRightCandidateOffset);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordA6DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5);
            RejectSecondNodeOverhangTopEqual(BranchLessThanWord);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA6DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5);
            RejectSecondNodeOverhangTopEqual(BranchGreaterOrEqualWord);
            Append(code, MoveQuickZeroD2);
            Append(code, MoveQuickThreeD3);
            Append(code, BranchAlwaysWord);
