            var secondNodeTopAlignedLeftCandidateOffset = code.Count;
            PatchBranch(
                code,
                secondNodeTopAlignedLeftCandidateSkipBranchExtensionOffset,
                secondNodeTopAlignedLeftCandidateOffset);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordA6DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
