            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, CompareWordD4ToD5);
            RejectSecondNodeOverhangTopEqual(BranchGreaterThanWord);
