            // the overlap and exposed lower rows. Canonical OR merges those
            // rows; publish one full source band after the old-width upper
            // residual by reusing the existing second node.
            Append(code, CompareImmediateWordD3); Append(code, 2);
            Append(code, BranchNotEqualWord);
            var secondNodeOverhangNotBothVerticalBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD2); Append(code, 2);
            Append(code, BranchEqualWord);
            secondNodeOverhangContainsSecondBothEdgesBranches.Add(code.Count);
            Append(code, 0);
            var secondNodeOverhangHorizontalDispatchOffset = code.Count;
            PatchBranch(
                code,
                secondNodeOverhangNotBothVerticalBranchExtensionOffset,
                secondNodeOverhangHorizontalDispatchOffset);
            Append(code, CompareImmediateWordD3); Append(code, 3);
            Append(code, BranchEqualWord);
            var secondNodeTopAlignedSingleAllocationDispatchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD3); Append(code, 1);
            Append(code, BranchNotEqualWord);
            var secondNodeOverhangNotBottomBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD2); Append(code, 2);
            Append(code, BranchNotEqualWord);
            var secondNodeOverhangNotBothXBranchExtensionOffset = code.Count;
