            Append(code, MoveAddressD7ToA0);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA6DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, AddQuickOneWordD4);
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            PatchBranch(code, secondNodeOverhangStrictResidualSkipExtensionOffset, code.Count);

            // Initialize detached-node links, then rewrite the existing
            // second node as the source-width middle band.
            Append(code, MoveAddressD6ToA0);
            Append(code, MoveLongA4ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveLongA6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);

            Append(code, MoveAddressD7ToA0);
            Append(code, MoveLongA6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveQuickZeroD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);

            Append(code, MoveAddressA6ToA0);
            Append(code, MoveLongD6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveLongD7ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, CompareImmediateWordD3); Append(code, 2);
            Append(code, BranchEqualWord);
            var secondNodeOverhangMiddleYSkipBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, TestLongD3);
            Append(code, BranchNotEqualWord);
            var secondNodeOverhangMiddleMaxYSkipBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            PatchBranch(code, secondNodeOverhangMiddleMaxYSkipBranchExtensionOffset, code.Count);
            PatchBranch(code, secondNodeOverhangMiddleYSkipBranchExtensionOffset, code.Count);

            Append(code, CompareImmediateWordD2); Append(code, 2);
            Append(code, BranchEqualWord);
            var bothOverhangBoundsBranchExtensionOffset = code.Count; Append(code, 0);
            Append(code, TestLongD2);
            Append(code, BranchNotEqualWord);
            var leftOverhangBoundsBranchExtensionOffset = code.Count; Append(code, 0);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, BranchAlwaysWord);
            var rightOverhangBoundsSkipExtensionOffset = code.Count; Append(code, 0);

            var leftOverhangBoundsOffset = code.Count;
            PatchBranch(code, leftOverhangBoundsBranchExtensionOffset, leftOverhangBoundsOffset);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, BranchAlwaysWord);
            var leftOverhangBoundsSkipExtensionOffset = code.Count; Append(code, 0);

            var bothOverhangBoundsOffset = code.Count;
            PatchBranch(code, bothOverhangBoundsBranchExtensionOffset, bothOverhangBoundsOffset);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            PatchBranch(code, rightOverhangBoundsSkipExtensionOffset, code.Count);
            PatchBranch(code, leftOverhangBoundsSkipExtensionOffset, code.Count);

            // Publish the upper band from the unchanged first node, after all
            // three rectangle bodies and the remaining links are initialized.
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongD6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            // This transaction publishes a four-node chain. Normalize only
            // after all residual, middle, and existing-node links are live;
            // the full-chain pass also rebases nodes relative to the exact
            // union envelope.
            if (normalizeFullChainBounds)
                CallTightenFullOutputRegionBounds();
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickOneD0);
            Append(code, ReturnFromSubroutine);

            var upperAllocationNullOffset = code.Count;
            PatchBranch(code, upperAllocationNullExtensionOffset, upperAllocationNullOffset);
