            var upperAllocationInvalidOffset = code.Count;
            PatchBranch(code, upperAllocationOddExtensionOffset, upperAllocationInvalidOffset);
            PatchBranch(code, upperAllocationHighExtensionOffset, upperAllocationInvalidOffset);
            EmitSecondNodeOverhangFreeD0();
            EmitSecondNodeOverhangRestoreFailure();

