            EmitSecondNodeOverhangRestoreFailure();

            var lowerAllocationInvalidOffset = code.Count;
            PatchBranch(code, lowerAllocationOddExtensionOffset, lowerAllocationInvalidOffset);
            PatchBranch(code, lowerAllocationHighExtensionOffset, lowerAllocationInvalidOffset);
            EmitSecondNodeOverhangFreeD0();
            EmitSecondNodeOverhangFreeD6();
            EmitSecondNodeOverhangRestoreFailure();

            PatchBranch(code, secondNodeOverhangSkipExtensionOffset, code.Count);

            Append(code, BranchAlwaysWord);
            var secondNodeOverhangTwoAllocationSkipSingleBranchExtensionOffset = code.Count;
            Append(code, 0);
