            Append(code, MoveLongA6ToD7);
            Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
            Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0);
            Decline(BranchEqualWord);
            Append(code, MoveAddressD0ToA6);

            Append(code, MoveLongA1ToPreDecrementA7);
            Append(code, MoveLongA4ToPreDecrementA7);
            Append(code, MoveLongD7ToPreDecrementA7);
            Append(code, MoveLongA5ToPreDecrementA7);

