            Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
            Append(code, TestLongD0);
            Append(code, BranchEqualWord);
            var bottomBothAllocationNullExtensionOffset = code.Count; Append(code, 0);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Append(code, BranchEqualWord);
            var bottomBothAllocationEvenExtensionOffset = code.Count; Append(code, 0);
            Append(code, BranchAlwaysWord);
            var bottomBothAllocationOddExtensionOffset = code.Count; Append(code, 0);

            var bottomBothAllocationEvenOffset = code.Count;
            PatchBranch(code, bottomBothAllocationEvenExtensionOffset, bottomBothAllocationEvenOffset);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Append(code, BranchHighWord);
            var bottomBothAllocationHighExtensionOffset = code.Count; Append(code, 0);
            Append(code, MoveLongD0ToD6);

            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA5);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA6);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);

