            Append(code, BranchEqualWord);
            var secondNodeTopAlignedSingleAllocationSetupBranchExtensionOffset = code.Count;
            Append(code, 0);

            Append(code, MoveAddressD6ToA0);
            foreach (var displacement in new[] { 0, 4 })
            {
