            Append(code, MoveLongA6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveQuickZeroD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);

