            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickOneD0);
            Append(code, ReturnFromSubroutine);

            var bottomBothAllocationNullOffset = code.Count;
            PatchBranch(code, bottomBothAllocationNullExtensionOffset, bottomBothAllocationNullOffset);
            EmitSecondNodeOverhangRestoreFailure();

            var bottomBothAllocationInvalidOffset = code.Count;
            PatchBranch(code, bottomBothAllocationOddExtensionOffset, bottomBothAllocationInvalidOffset);
            PatchBranch(code, bottomBothAllocationHighExtensionOffset, bottomBothAllocationInvalidOffset);
            EmitSecondNodeOverhangFreeD0();
            EmitSecondNodeOverhangRestoreFailure();

            var secondNodeTopAlignedSingleAllocationSetupOffset = code.Count;
            PatchBranch(
