            Append(code, BranchNotEqualWord);
            var secondNodeTopAlignedLeftEdgeBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveAddressA6ToA0);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, BranchAlwaysWord);
            var secondNodeTopAlignedXUpdateSkipBranchExtensionOffset = code.Count;
