            Append(code, MoveAddressA6ToA0);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            PatchBranch(code, secondNodeTopAlignedXUpdateSkipBranchExtensionOffset, code.Count);

