            Append(code, MoveLongA6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveQuickZeroD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveAddressA6ToA0);
            Append(code, MoveLongD6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);

            // The source-aligned overlap can widen either X edge while the
            // allocated lower band extends the Region downward. Tighten and
            // rebase the completed chain only after both nodes are linked.
            if (normalizeFullChainBounds)
                CallTightenFullOutputRegionBounds();
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickOneD0);
            Append(code, ReturnFromSubroutine);

            var secondNodeOverhangContainsSecondBothEdgesOffset = code.Count;
            foreach (var branch in secondNodeOverhangContainsSecondBothEdgesBranches)
                PatchBranch(code, branch, secondNodeOverhangContainsSecondBothEdgesOffset);

            // These selected paths prove strict overhang at both X edges and
            // inclusive containment of the second node on Y. The first node is
            // vertically disjoint, so widen the existing second node in place;
            // no allocation, link change, or source mutation is needed.
            Append(code, MoveAddressA6ToA0);
            foreach (var displacement in new[] { 0, 4 })
            {
                Append(code, MoveLongA5DisplacementToD4);
                Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
                Append(code, MoveLongD4ToA0Displacement);
                Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
            }

            if (normalizeFullChainBounds)
                CallTightenFullOutputRegionBounds();
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickOneD0);
            Append(code, ReturnFromSubroutine);

