        if (allowPartialOverlap)
        {
            // If the source begins below the first node, crosses the top of
            // the second node, and is X-contained by that node, only the
            // source-only band above the second node must be inserted.
            var secondNodeTopOverhangRejectBranches = new List<int>(6);
            void SkipSecondNodeTopOverhang(ushort branchOpcode)
            {
                Append(code, branchOpcode);
                secondNodeTopOverhangRejectBranches.Add(code.Count);
