            Append(code, MoveLongD0ToD6);

            Append(code, MoveLongImmediateD0); Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
