            Append(code, TestLongD0);
            Append(code, BranchEqualWord);
            var lowerAllocationNullExtensionOffset = code.Count; Append(code, 0);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Append(code, BranchEqualWord);
            var lowerAllocationEvenExtensionOffset = code.Count; Append(code, 0);
