            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Append(code, BranchHighWord);
            var lowerAllocationHighExtensionOffset = code.Count; Append(code, 0);
            Append(code, MoveLongD0ToD7);

            // Both residual allocations are valid before any old link or
