            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA5);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA6);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);

