            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5);
            SkipHorizontalTopY(BranchLessOrEqualWord);

            // Right overhang: source starts inside and ends beyond the first.
            var horizontalTopRightRejectBranches = new List<int>(3);
            void SkipHorizontalTopRight(ushort branchOpcode)
            {
