            SkipHorizontalTopBoth(BranchGreaterOrEqualWord);

            Append(code, MoveQuickOneD2);
            Append(code, MoveQuickTwoD3);
            Append(code, BranchAlwaysWord);
            horizontalOverhangBranchExtensionOffsets.Add(code.Count);
            Append(code, 0);

            // Bottom-overlap mirror: the source begins inside the first
            // destination node and continues below it, but remains above the
            // second. The lower source-X strip becomes a separate residual.
            var horizontalBottomOverhangOffset = code.Count;
            var horizontalBottomYRejectBranches = new List<int>(3);
            void SkipHorizontalBottomY(ushort branchOpcode)
            {
                Append(code, branchOpcode);
                horizontalBottomYRejectBranches.Add(code.Count);
                Append(code, 0);
            }

            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD5);
