            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5);
            SkipHorizontalBottomRight(BranchGreaterOrEqualWord);

            Append(code, MoveQuickTwoD2);
            Append(code, MoveQuickZeroD3);
            Append(code, BranchAlwaysWord);
            horizontalOverhangBranchExtensionOffsets.Add(code.Count);
            Append(code, 0);

            var horizontalBottomLeftOverhangOffset = code.Count;
            foreach (var branch in horizontalBottomRightRejectBranches)
                PatchBranch(code, branch, horizontalBottomLeftOverhangOffset);

            var horizontalBottomLeftRejectBranches = new List<int>(3);
            void SkipHorizontalBottomLeft(ushort branchOpcode)
            {
                Append(code, branchOpcode);
                horizontalBottomLeftRejectBranches.Add(code.Count);
                Append(code, 0);
            }

            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5);
            SkipHorizontalBottomLeft(BranchLessOrEqualWord);

            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, CompareWordD4ToD5);
            SkipHorizontalBottomLeft(BranchGreaterThanWord);

            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, CompareWordD4ToD5);
            SkipHorizontalBottomLeft(BranchLessOrEqualWord);

            Append(code, MoveQuickTwoD2);
            Append(code, MoveQuickOneD3);
            Append(code, BranchAlwaysWord);
            horizontalOverhangBranchExtensionOffsets.Add(code.Count);
            Append(code, 0);

            var horizontalBottomBothOverhangOffset = code.Count;
            foreach (var branch in horizontalBottomLeftRejectBranches)
                PatchBranch(code, branch, horizontalBottomBothOverhangOffset);

            var horizontalBottomBothRejectBranches = new List<int>(2);
            void SkipHorizontalBottomBoth(ushort branchOpcode)
            {
                Append(code, branchOpcode);
                horizontalBottomBothRejectBranches.Add(code.Count);
                Append(code, 0);
            }

            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, CompareWordD4ToD5);
            SkipHorizontalBottomBoth(BranchLessOrEqualWord);

            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5);
            SkipHorizontalBottomBoth(BranchGreaterOrEqualWord);

            Append(code, MoveQuickTwoD2);
            Append(code, MoveQuickTwoD3);
            Append(code, BranchAlwaysWord);
            horizontalOverhangBranchExtensionOffsets.Add(code.Count);
            Append(code, 0);

            // Combined top/bottom overlap: the source crosses both Y edges
            // of the first node and overhangs its right edge, left edge, or
            // both. Single-edge forms use the shared two-residual transaction;
            // both-edge containment is handled allocation-free below.
            var horizontalBothVerticalOverhangOffset = code.Count;
            var horizontalBothVerticalYRejectBranches = new List<int>(2);
            void SkipHorizontalBothVerticalY(ushort branchOpcode)
            {
                Append(code, branchOpcode);
                horizontalBothVerticalYRejectBranches.Add(code.Count);
                Append(code, 0);
            }

            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD5);
            SkipHorizontalBothVerticalY(BranchLessOrEqualWord);

            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5);
            SkipHorizontalBothVerticalY(BranchGreaterOrEqualWord);

            var horizontalBothVerticalRightRejectBranches = new List<int>(3);
            void SkipHorizontalBothVerticalRight(ushort branchOpcode)
            {
                Append(code, branchOpcode);
                horizontalBothVerticalRightRejectBranches.Add(code.Count);
                Append(code, 0);
            }

            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, CompareWordD4ToD5);
            SkipHorizontalBothVerticalRight(BranchGreaterOrEqualWord);

            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5);
            SkipHorizontalBothVerticalRight(BranchLessThanWord);

