            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5);
            SkipHorizontalBothVerticalRight(BranchGreaterOrEqualWord);

            Append(code, MoveQuickThreeD2);
            Append(code, MoveQuickZeroD3);
            Append(code, BranchAlwaysWord);
            horizontalOverhangBranchExtensionOffsets.Add(code.Count);
            Append(code, 0);

            var horizontalBothVerticalLeftOffset = code.Count;
            foreach (var branch in horizontalBothVerticalRightRejectBranches)
                PatchBranch(code, branch, horizontalBothVerticalLeftOffset);

            var horizontalBothVerticalLeftRejectBranches = new List<int>(3);
            void SkipHorizontalBothVerticalLeft(ushort branchOpcode)
            {
                Append(code, branchOpcode);
                horizontalBothVerticalLeftRejectBranches.Add(code.Count);
                Append(code, 0);
            }

