            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5);
            Append(code, BranchGreaterOrEqualWord);
            var horizontalBothVerticalBothRightRejectExtensionOffset = code.Count;
            Append(code, 0);

            // This geometry strictly contains the old first node. Keep its
            // established replacement-and-retirement semantics instead of
            // widening that public node in place.
            Decline(BranchAlwaysWord);

            var ordinaryPartialOverlapGeometryOffset = code.Count;
            foreach (var branch in horizontalLeftOverhangRejectBranches)
