            foreach (var branch in horizontalBothOverhangRejectBranches)
                PatchBranch(code, branch, horizontalTopOverhangOffset);
            foreach (var branch in horizontalTopYRejectBranches)
                PatchBranch(code, branch, horizontalBottomOverhangOffset);
            foreach (var branch in horizontalTopBothRejectBranches)
