            foreach (var branch in horizontalBottomYRejectBranches)
                PatchBranch(code, branch, horizontalBothVerticalOverhangOffset);
            PatchBranch(code, horizontalBothVerticalBothRejectExtensionOffset, ordinaryPartialOverlapGeometryOffset);
            PatchBranch(code, horizontalBothVerticalBothRightRejectExtensionOffset, ordinaryPartialOverlapGeometryOffset);
            foreach (var branch in horizontalBothVerticalYRejectBranches)
                PatchBranch(code, branch, ordinaryPartialOverlapGeometryOffset);
            foreach (var branch in horizontalBottomBothRejectBranches)
                PatchBranch(code, branch, ordinaryPartialOverlapGeometryOffset);

            // The common X proof ensures the source contributes only exposed
            // rows outside the first rectangle.
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
