            var bottomOverlapSuccessBranchExtensionOffset = code.Count;
            Append(code, 0);

            var topOverlapOffset = code.Count;
            PatchBranch(code, topOverlapBranchExtensionOffset, topOverlapOffset);
            // Top form: source starts above the first node and ends within its
            // Y span. Its exposed top rows are nonempty and its overlap is
            // contained by the existing node.
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD5); Decline(BranchGreaterThanWord);

            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5);
            if (allowPartialOverlap)
            {
                Append(code, BranchLessThanWord);
                bothProtrusionsBranchExtensionOffset = code.Count;
                Append(code, 0);
            }
            else
            {
                Decline(BranchLessThanWord);
            }

            Append(code, MoveWordA4DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA6DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);

            var geometrySuccessOffset = code.Count;
            PatchBranch(code, gapSuccessBranchExtensionOffset, geometrySuccessOffset);
            PatchBranch(code, bottomOverlapSuccessBranchExtensionOffset, geometrySuccessOffset);
        }

        // All structural and geometric proofs are complete. Resolve Exec and
        // stage the four pointers below the saved caller result before the
        // first public link is changed.
        Append(code, MoveLongA6ToD7);
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var execMissingExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA3ToPreDecrementA7);
        Append(code, MoveLongA1ToPreDecrementA7);
        Append(code, MoveLongA4ToPreDecrementA7);
        Append(code, MoveLongD7ToPreDecrementA7);

        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var allocationSucceededExtensionOffset = code.Count; Append(code, 0);
        EmitAllocationFailure();

        var allocationSucceededOffset = code.Count;
        PatchBranch(code, allocationSucceededExtensionOffset, allocationSucceededOffset);
        Append(code, BitTestImmediateD0); Append(code, 0);
        Append(code, BranchEqualWord);
        var allocationEvenExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var allocationBadExtensionOffset = code.Count; Append(code, 0);
        var allocationEvenOffset = code.Count;
        PatchBranch(code, allocationEvenExtensionOffset, allocationEvenOffset);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchHighWord);
        var allocationAddressableExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var allocationHighExtensionOffset = code.Count; Append(code, 0);
        var allocationAddressableOffset = code.Count;
        Append(code, MoveLongD0ToD6); // fresh node

        // Restore the public pointers; A6 remains ExecBase until after the
        // node has been initialized, so no gateway can observe a partial link.
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA0);
        Append(code, MoveAddressD6ToA2);

        // Copy the source-relative rectangle; strict gaps and bottom
        // protrusions insert it between the old nodes, while a top protrusion
        // prepends the exposed band and updates only the destination head.
        foreach (var displacement in new[] { 0, 2, 4, 6 })
        {
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
            Append(code, MoveWordD4ToA2Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
        }
        var topOutputBranchExtensionOffset = -1;
        if (allowPartialOverlap)
        {
            // A source beginning above the first node is the top-strip form.
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD5);
            Append(code, BranchGreaterThanWord);
            topOutputBranchExtensionOffset = code.Count;
            Append(code, 0);

            // Otherwise preserve the strict-gap rectangle as-is or trim an
            // overlapping bottom source to the exposed rows only.
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA4DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5);
            Append(code, BranchGreaterOrEqualWord);
            var bottomOutputBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BranchAlwaysWord);
            var skipBottomBoundsExtensionOffset = code.Count;
            Append(code, 0);

            var bottomOutputOffset = code.Count;
            PatchBranch(code, bottomOutputBranchExtensionOffset, bottomOutputOffset);
            Append(code, MoveWordA4DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, AddQuickOneWordD4);
            Append(code, MoveWordD4ToA2Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            PatchBranch(code, skipBottomBoundsExtensionOffset, code.Count);
        }
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToA2Displacement);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA6ToD0);
        Append(code, MoveLongD0ToA2Displacement);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongD6ToA0Displacement);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongD6ToA0Displacement);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);

        CallTightenOutputRegionBounds();

        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        if (allowPartialOverlap)
        {
            var topOutputOffset = code.Count;
            PatchBranch(code, topOutputBranchExtensionOffset, topOutputOffset);

            // Exposed top rows end immediately before first.minY.
            Append(code, MoveWordA4DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, SubQuickOneWordD4);
            Append(code, MoveWordD4ToA2Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

            // The new node's predecessor is the RegionRectangle head cell;
            // its successor is the old first node. Publish the new head last.
            Append(code, MoveAddressA1ToA0);
            Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
            Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
            Append(code, MoveLongA0ToD0);
            Append(code, MoveLongD0ToA2Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveLongA4ToD0);
            Append(code, MoveLongD0ToA2Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongD6ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveAddressA1ToA0);
            Append(code, MoveLongD6ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangle);

            CallTightenOutputRegionBounds();

            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickOneD0);
            Append(code, ReturnFromSubroutine);
        }

        if (allowPartialOverlap)
        {
            var bothProtrusionsOffset = code.Count;
            PatchBranch(code, bothProtrusionsBranchExtensionOffset, bothProtrusionsOffset);

            void EmitBothProtrusionsRestoreFailure()
            {
                // Private frame: destination, old first, old second, source
                // node, then the caller's original D0.
                for (var index = 0; index < 4; index++)
                    Append(code, MoveLongA7PostIncrementToD0);
                Append(code, MoveLongA7PostIncrementToD0);
                Append(code, MoveQuickZeroD0);
                Append(code, ReturnFromSubroutine);
            }

            void EmitBothProtrusionsFreeD0()
            {
                Append(code, MoveAddressD0ToA0);
                Append(code, MoveLongImmediateD0); Append(code, 0);
                Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
                Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
                AppendExecFreeMemFromA0PreservingA1(code);
            }

            void EmitBothProtrusionsFreeD6()
            {
                Append(code, MoveAddressD6ToA0);
                Append(code, MoveLongImmediateD0); Append(code, 0);
                Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
                Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
                AppendExecFreeMemFromA0PreservingA1(code);
            }

            // Resolve Exec before opening the private frame. A missing Exec
            // base returns to the existing OR fallback without changing any
            // public Region link.
            Append(code, MoveLongA6ToD7);
            Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
            Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0);
            Decline(BranchEqualWord);
            Append(code, MoveAddressD0ToA6);

            // Save public identities below the caller result. D6/D7 become
            // the fresh top/bottom rectangles after their allocations pass
            // address-class admission.
            Append(code, MoveLongA1ToPreDecrementA7);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongA0ToPreDecrementA7);
            Append(code, MoveLongD7ToPreDecrementA7);
            Append(code, MoveLongA5ToPreDecrementA7);

            Append(code, MoveLongImmediateD0); Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
            Append(code, TestLongD0);
            Append(code, BranchEqualWord);
            var firstNodeAllocationNullExtensionOffset = code.Count; Append(code, 0);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Append(code, BranchEqualWord);
            var firstNodeAllocationEvenExtensionOffset = code.Count; Append(code, 0);
            Append(code, BranchAlwaysWord);
            var firstNodeAllocationOddExtensionOffset = code.Count; Append(code, 0);

            var firstNodeAllocationEvenOffset = code.Count;
            PatchBranch(code, firstNodeAllocationEvenExtensionOffset, firstNodeAllocationEvenOffset);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Append(code, BranchHighWord);
            var firstNodeAllocationHighExtensionOffset = code.Count; Append(code, 0);
            Append(code, MoveLongD0ToD6);

            Append(code, MoveLongImmediateD0); Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
            Append(code, TestLongD0);
            Append(code, BranchEqualWord);
            var secondNodeAllocationNullExtensionOffset = code.Count; Append(code, 0);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Append(code, BranchEqualWord);
            var secondNodeAllocationEvenExtensionOffset = code.Count; Append(code, 0);
            Append(code, BranchAlwaysWord);
            var secondNodeAllocationOddExtensionOffset = code.Count; Append(code, 0);

            var secondNodeAllocationEvenOffset = code.Count;
            PatchBranch(code, secondNodeAllocationEvenExtensionOffset, secondNodeAllocationEvenOffset);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Append(code, BranchHighWord);
            var secondNodeAllocationHighExtensionOffset = code.Count; Append(code, 0);
            Append(code, MoveLongD0ToD7);

            // Both allocations are valid before restoring pointers, writing
            // either node, or changing the destination chain.
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA5);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA6);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);

            void CopyBothProtrusionBounds(ushort moveAllocationToA0)
            {
                Append(code, moveAllocationToA0);
                foreach (var displacement in new[] { 0, 2, 4, 6 })
                {
                    Append(code, MoveWordA5DisplacementToD4);
                    Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
                    Append(code, MoveWordD4ToA0Displacement);
                    Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
                }
            }

            // Top residual: source.minY through first.minY-1.
            CopyBothProtrusionBounds(MoveAddressD6ToA0);
            Append(code, MoveWordA4DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, SubQuickOneWordD4);
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

            // Bottom residual: first.maxY+1 through source.maxY.
            CopyBothProtrusionBounds(MoveAddressD7ToA0);
            Append(code, MoveWordA4DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, AddQuickOneWordD4);
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));

            // Initialize the new chain and reciprocal old-node links. The
            // public head changes last, after both residual nodes are ready.
            Append(code, MoveAddressA1ToA0);
            Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
            Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
            Append(code, MoveLongA0ToD0);
            Append(code, MoveAddressD6ToA0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveLongA4ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);

            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongD6ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveLongD7ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);

            Append(code, MoveAddressD7ToA0);
            Append(code, MoveLongA4ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveLongA6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);

            Append(code, MoveAddressA6ToA0);
            Append(code, MoveLongD7ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveAddressA1ToA0);
            Append(code, MoveLongD6ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangle);
            // The fourth (bottom residual) node is contained by the envelope
            // of the top residual and the original node pair. Preserve its
            // address across the shared three-node bounds pass, then rebase
            // only this additional node by the computed origin deltas.
            Append(code, MoveLongD7ToD0);
            Append(code, MoveAddressD0ToA2);
            CallTightenOutputRegionBounds();
            Append(code, MoveAddressA2ToA0);
            foreach (var displacement in new[]
                     {
                         GraphicsLayouts.RectangleMinX,
                         GraphicsLayouts.RectangleMaxX,
                         GraphicsLayouts.RectangleMinY,
                         GraphicsLayouts.RectangleMaxY
                     })
            {
