                    ? SubWordD7ToA0Displacement
                    : SubWordD6ToA0Displacement);
                Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + displacement)));
            }
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickOneD0);
            Append(code, ReturnFromSubroutine);

            var firstNodeAllocationNullOffset = code.Count;
            PatchBranch(code, firstNodeAllocationNullExtensionOffset, firstNodeAllocationNullOffset);
            EmitBothProtrusionsRestoreFailure();

            var firstNodeAllocationInvalidOffset = code.Count;
            PatchBranch(code, firstNodeAllocationOddExtensionOffset, firstNodeAllocationInvalidOffset);
            PatchBranch(code, firstNodeAllocationHighExtensionOffset, firstNodeAllocationInvalidOffset);
            EmitBothProtrusionsFreeD0();
            EmitBothProtrusionsRestoreFailure();

            var secondNodeAllocationNullOffset = code.Count;
            PatchBranch(code, secondNodeAllocationNullExtensionOffset, secondNodeAllocationNullOffset);
            EmitBothProtrusionsFreeD6();
            EmitBothProtrusionsRestoreFailure();

            var secondNodeAllocationInvalidOffset = code.Count;
            PatchBranch(code, secondNodeAllocationOddExtensionOffset, secondNodeAllocationInvalidOffset);
            PatchBranch(code, secondNodeAllocationHighExtensionOffset, secondNodeAllocationInvalidOffset);
            EmitBothProtrusionsFreeD0();
            EmitBothProtrusionsFreeD6();
            EmitBothProtrusionsRestoreFailure();
        }

        if (allowPartialOverlap)
        {
            var horizontalOverhangOffset = code.Count;
            foreach (var branch in horizontalOverhangBranchExtensionOffsets)
                PatchBranch(code, branch, horizontalOverhangOffset);

            // When a both-edge source shares its X span with an exposed
            // top/bottom band, canonical OR coalesces those bands. Route both
            // vertical edge modes to their one-allocation transaction.
            Append(code, CompareImmediateWordD3);
            Append(code, 2);
            Append(code, BranchNotEqualWord);
            var horizontalBothSingleNotBothExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD2);
            Append(code, 1);
            Append(code, BranchEqualWord);
            var horizontalTopBothSingleAllocationExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD2);
            Append(code, 2);
            Append(code, BranchNotEqualWord);
            var horizontalBottomBothSingleNotBottomExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BranchAlwaysWord);
            var horizontalBottomBothSingleAllocationExtensionOffset = code.Count;
            Append(code, 0);

            var horizontalTwoAllocationOffset = code.Count;
            PatchBranch(code, horizontalBothSingleNotBothExtensionOffset, horizontalTwoAllocationOffset);
            PatchBranch(code, horizontalBottomBothSingleNotBottomExtensionOffset, horizontalTwoAllocationOffset);

            void EmitHorizontalRightOverhangRestoreFailure()
            {
                // Private frame: destination, old first, old second, source
                // node, then the caller's original D0.
                for (var index = 0; index < 4; index++)
                    Append(code, MoveLongA7PostIncrementToD0);
                Append(code, MoveLongA7PostIncrementToD0);
                Append(code, MoveQuickZeroD0);
                Append(code, ReturnFromSubroutine);
            }

            void EmitHorizontalRightOverhangFreeD0()
            {
                Append(code, MoveAddressD0ToA0);
                Append(code, MoveLongImmediateD0); Append(code, 0);
                Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
                Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
                AppendExecFreeMemFromA0PreservingA1(code);
            }

            void EmitHorizontalRightOverhangFreeD6()
            {
                Append(code, MoveAddressD6ToA0);
                Append(code, MoveLongImmediateD0); Append(code, 0);
                Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
                Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
                AppendExecFreeMemFromA0PreservingA1(code);
            }

            // Resolve Exec before opening the private frame. No public Region
            // fields are touched if the allocator is unavailable.
            Append(code, MoveLongA6ToD7);
            Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
            Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0);
            Decline(BranchEqualWord);
            Append(code, MoveAddressD0ToA6);

            // Save stable identities below the caller result. D6 and D7 hold
            // the fresh upper/lower bands across the two Exec allocations.
            Append(code, MoveLongA1ToPreDecrementA7);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongA0ToPreDecrementA7);
            Append(code, MoveLongD7ToPreDecrementA7);
            Append(code, MoveLongA5ToPreDecrementA7);

            Append(code, MoveLongImmediateD0); Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
            Append(code, TestLongD0);
            Append(code, BranchEqualWord);
            var upperAllocationNullExtensionOffset = code.Count; Append(code, 0);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Append(code, BranchEqualWord);
            var upperAllocationEvenExtensionOffset = code.Count; Append(code, 0);
            Append(code, BranchAlwaysWord);
            var upperAllocationOddExtensionOffset = code.Count; Append(code, 0);

            var upperAllocationEvenOffset = code.Count;
            PatchBranch(code, upperAllocationEvenExtensionOffset, upperAllocationEvenOffset);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Append(code, BranchHighWord);
            var upperAllocationHighExtensionOffset = code.Count; Append(code, 0);
            Append(code, MoveLongD0ToD6);

            Append(code, MoveLongImmediateD0); Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
            Append(code, TestLongD0);
            Append(code, BranchEqualWord);
            var lowerAllocationNullExtensionOffset = code.Count; Append(code, 0);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Append(code, BranchEqualWord);
            var lowerAllocationEvenExtensionOffset = code.Count; Append(code, 0);
            Append(code, BranchAlwaysWord);
            var lowerAllocationOddExtensionOffset = code.Count; Append(code, 0);

            var lowerAllocationEvenOffset = code.Count;
            PatchBranch(code, lowerAllocationEvenExtensionOffset, lowerAllocationEvenOffset);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Append(code, BranchHighWord);
            var lowerAllocationHighExtensionOffset = code.Count; Append(code, 0);
            Append(code, MoveLongD0ToD7);

            // Both returned spans are even and addressable before any node or
            // public link is written.
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA5);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA6);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);

            void CopyFirstBoundsToNode(ushort moveNodeToA0)
            {
                Append(code, moveNodeToA0);
                foreach (var displacement in new[] { 0, 2, 4, 6 })
                {
                    Append(code, MoveWordA4DisplacementToD4);
                    Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
                    Append(code, MoveWordD4ToA0Displacement);
                    Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
                }
            }

            void CopySourceBoundsToNode(ushort moveNodeToA0)
            {
                Append(code, moveNodeToA0);
                foreach (var displacement in new[] { 0, 2, 4, 6 })
                {
                    Append(code, MoveWordA5DisplacementToD4);
                    Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
                    Append(code, MoveWordD4ToA0Displacement);
                    Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + displacement));
                }
            }

            // Interior and bottom-overlap sources keep the old X span in the
            // upper residual. A top-overlap source owns that band and keeps
            // its source X span instead.
            Append(code, CompareImmediateWordD2);
            Append(code, 1);
            Append(code, BranchEqualWord);
            var upperTopOverhangBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD2);
            Append(code, 3);
            Append(code, BranchEqualWord);
            var upperBothVerticalBranchExtensionOffset = code.Count;
            Append(code, 0);
            CopyFirstBoundsToNode(MoveAddressD6ToA0);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, SubQuickOneWordD4);
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, BranchAlwaysWord);
            var upperInteriorSkipExtensionOffset = code.Count;
            Append(code, 0);

            var upperTopOverhangOffset = code.Count;
            PatchBranch(code, upperTopOverhangBranchExtensionOffset, upperTopOverhangOffset);
            PatchBranch(code, upperBothVerticalBranchExtensionOffset, upperTopOverhangOffset);
            CopySourceBoundsToNode(MoveAddressD6ToA0);
            Append(code, MoveWordA4DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, SubQuickOneWordD4);
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            PatchBranch(code, upperInteriorSkipExtensionOffset, code.Count);

            Append(code, CompareImmediateWordD2);
            Append(code, 2);
            Append(code, BranchEqualWord);
            var lowerBottomOverhangBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD2);
            Append(code, 3);
            Append(code, BranchEqualWord);
            var lowerBothVerticalBranchExtensionOffset = code.Count;
            Append(code, 0);
            CopyFirstBoundsToNode(MoveAddressD7ToA0);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, AddQuickOneWordD4);
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, BranchAlwaysWord);
            var lowerBottomOverhangSkipExtensionOffset = code.Count;
            Append(code, 0);

            var lowerBottomOverhangOffset = code.Count;
            PatchBranch(code, lowerBottomOverhangBranchExtensionOffset, lowerBottomOverhangOffset);
            PatchBranch(code, lowerBothVerticalBranchExtensionOffset, lowerBottomOverhangOffset);
            CopySourceBoundsToNode(MoveAddressD7ToA0);
            Append(code, MoveWordA4DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, AddQuickOneWordD4);
            Append(code, MoveWordD4ToA0Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            PatchBranch(code, lowerBottomOverhangSkipExtensionOffset, code.Count);

            // Reuse the original first node for the widened middle band.
            Append(code, MoveAddressA4ToA2);
            Append(code, CompareImmediateWordD2);
            Append(code, 1);
            Append(code, BranchEqualWord);
            var middleTopOverhangBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD2);
            Append(code, 3);
            Append(code, BranchEqualWord);
            var middleBothVerticalMinBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD4ToA2Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, BranchAlwaysWord);
            var middleInteriorSkipExtensionOffset = code.Count;
            Append(code, 0);

            var middleTopOverhangOffset = code.Count;
            PatchBranch(code, middleTopOverhangBranchExtensionOffset, middleTopOverhangOffset);
            PatchBranch(code, middleBothVerticalMinBranchExtensionOffset, middleTopOverhangOffset);
            Append(code, MoveWordA4DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD4ToA2Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            PatchBranch(code, middleInteriorSkipExtensionOffset, code.Count);
            Append(code, CompareImmediateWordD2);
            Append(code, 2);
            Append(code, BranchEqualWord);
            var middleBottomOverhangSkipExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareImmediateWordD2);
            Append(code, 3);
            Append(code, BranchEqualWord);
            var middleBothVerticalMaxSkipExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordD4ToA2Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            PatchBranch(code, middleBottomOverhangSkipExtensionOffset, code.Count);
            PatchBranch(code, middleBothVerticalMaxSkipExtensionOffset, code.Count);
            // D3 selects the widened horizontal edge(s): zero means right,
            // one left, and two both. Exec preserves D3 across AllocMem.
            Append(code, TestLongD3);
            Append(code, BranchEqualWord);
            var widenRightBranchExtensionOffset = code.Count;
            Append(code, 0);

            Append(code, CompareImmediateWordD3);
            Append(code, 2);
            Append(code, BranchEqualWord);
            var widenBothBranchExtensionOffset = code.Count;
            Append(code, 0);

            // The default nonzero selector widens only the left edge.
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordD4ToA2Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));

            Append(code, BranchAlwaysWord);
            var widenLeftSkipExtensionOffset = code.Count;
            Append(code, 0);

            // Both-edge overhang updates both X bounds of the middle node.
            var widenBothOffset = code.Count;
            PatchBranch(code, widenBothBranchExtensionOffset, widenBothOffset);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordD4ToA2Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD4ToA2Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, BranchAlwaysWord);
            var widenBothSkipBranchExtensionOffset = code.Count;
            Append(code, 0);

            var widenRightOffset = code.Count;
            PatchBranch(code, widenRightBranchExtensionOffset, widenRightOffset);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD4ToA2Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            PatchBranch(code, widenLeftSkipExtensionOffset, code.Count);
            PatchBranch(code, widenBothSkipBranchExtensionOffset, code.Count);

            // Initialize the complete chain before publishing its new head.
            Append(code, MoveAddressA1ToA0);
            Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
            Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
            Append(code, MoveLongA0ToD0);
            Append(code, MoveAddressD6ToA0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveLongA4ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);

            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongD6ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveLongD7ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);

            Append(code, MoveAddressD7ToA0);
            Append(code, MoveLongA4ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveLongA6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);

            Append(code, MoveAddressA6ToA0);
            Append(code, MoveLongD7ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveAddressA1ToA0);
            Append(code, MoveLongD6ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangle);
            // The widened middle plus the original pair and upper band
            // determine the left/top envelope. Preserve the lower residual
            // through that shared pass, rebase it, then extend MaxY if its
            // source tail lies below the other three output rectangles.
            Append(code, MoveLongD7ToD0);
            Append(code, MoveAddressD0ToA2);
            CallTightenOutputRegionBounds();
            Append(code, MoveAddressA2ToA0);
            foreach (var displacement in new[]
                     {
                         GraphicsLayouts.RectangleMinX,
                         GraphicsLayouts.RectangleMaxX,
                         GraphicsLayouts.RectangleMinY,
                         GraphicsLayouts.RectangleMaxY
                     })
            {
                Append(code, displacement is GraphicsLayouts.RectangleMinX or GraphicsLayouts.RectangleMaxX
                    ? SubWordD7ToA0Displacement
                    : SubWordD6ToA0Displacement);
                Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + displacement)));
            }

            Append(code, MoveWordA2DisplacementToD0);
            Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds +
                GraphicsLayouts.RectangleMaxY)));
            Append(code, MoveWordA1DisplacementToD4);
            Append(code, checked((ushort)(GraphicsLayouts.RegionBounds +
                GraphicsLayouts.RectangleMinY)));
            Append(code, AddWordD4ToD0);
            Append(code, MoveWordA1DisplacementToD4);
            Append(code, checked((ushort)(GraphicsLayouts.RegionBounds +
                GraphicsLayouts.RectangleMaxY)));
            Append(code, CompareWordD0ToD4);
            Append(code, BranchGreaterOrEqualWord);
            var retainTightMaxYExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveWordD0ToA1Displacement);
            Append(code, checked((ushort)(GraphicsLayouts.RegionBounds +
                GraphicsLayouts.RectangleMaxY)));
            PatchBranch(code, retainTightMaxYExtensionOffset, code.Count);

            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickOneD0);
            Append(code, ReturnFromSubroutine);

            var upperAllocationNullOffset = code.Count;
            PatchBranch(code, upperAllocationNullExtensionOffset, upperAllocationNullOffset);
            EmitHorizontalRightOverhangRestoreFailure();

            var upperAllocationInvalidOffset = code.Count;
            PatchBranch(code, upperAllocationOddExtensionOffset, upperAllocationInvalidOffset);
            PatchBranch(code, upperAllocationHighExtensionOffset, upperAllocationInvalidOffset);
            EmitHorizontalRightOverhangFreeD0();
            EmitHorizontalRightOverhangRestoreFailure();

            var lowerAllocationNullOffset = code.Count;
            PatchBranch(code, lowerAllocationNullExtensionOffset, lowerAllocationNullOffset);
            EmitHorizontalRightOverhangFreeD6();
            EmitHorizontalRightOverhangRestoreFailure();

            var lowerAllocationInvalidOffset = code.Count;
            PatchBranch(code, lowerAllocationOddExtensionOffset, lowerAllocationInvalidOffset);
            PatchBranch(code, lowerAllocationHighExtensionOffset, lowerAllocationInvalidOffset);
            EmitHorizontalRightOverhangFreeD0();
            EmitHorizontalRightOverhangFreeD6();
            EmitHorizontalRightOverhangRestoreFailure();

            var horizontalTopBothSingleAllocationOffset = code.Count;
            PatchBranch(
                code,
                horizontalTopBothSingleAllocationExtensionOffset,
                horizontalTopBothSingleAllocationOffset);

            // Allocate and stage the coalesced source-width upper band before
            // changing either the existing first node or the public head.
            // Exec is resolved before opening the private pointer frame.
            Append(code, MoveLongA6ToD7);
            Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
            Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0);
            Decline(BranchEqualWord);
            Append(code, MoveAddressD0ToA6);

            Append(code, MoveLongA1ToPreDecrementA7);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongA0ToPreDecrementA7);
            Append(code, MoveLongD7ToPreDecrementA7);
            Append(code, MoveLongA5ToPreDecrementA7);

            Append(code, MoveLongImmediateD0); Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
            Append(code, TestLongD0);
            Append(code, BranchNotEqualWord);
            var topBothAllocationSucceededExtensionOffset = code.Count;
            Append(code, 0);
            EmitHorizontalRightOverhangRestoreFailure();

            var topBothAllocationSucceededOffset = code.Count;
            PatchBranch(code, topBothAllocationSucceededExtensionOffset, topBothAllocationSucceededOffset);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Append(code, BranchEqualWord);
            var topBothAllocationEvenExtensionOffset = code.Count; Append(code, 0);
            Append(code, BranchAlwaysWord);
            var topBothAllocationInvalidExtensionOffset = code.Count; Append(code, 0);

            var topBothAllocationEvenOffset = code.Count;
            PatchBranch(code, topBothAllocationEvenExtensionOffset, topBothAllocationEvenOffset);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Append(code, BranchHighWord);
            var topBothAllocationHighExtensionOffset = code.Count; Append(code, 0);
            Append(code, MoveLongD0ToD6);

            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA5);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA6);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);

            // The allocated source rectangle covers the coalesced top and
            // overlap bands. Reuse the old first node only for its lower
            // residual, retaining its original X span.
            CopySourceBoundsToNode(MoveAddressD6ToA0);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, AddQuickOneWordD4);
            Append(code, MoveAddressA4ToA2);
            Append(code, MoveWordD4ToA2Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));

            Append(code, MoveAddressA1ToA0);
            Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
            Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
            Append(code, MoveLongA0ToD0);
            Append(code, MoveAddressD6ToA0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveLongA4ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);

            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongD6ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveLongA6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);

            Append(code, MoveAddressA6ToA0);
            Append(code, MoveLongA4ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveAddressA1ToA0);
            Append(code, MoveLongD6ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangle);

            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickOneD0);
            Append(code, ReturnFromSubroutine);

            var horizontalBottomBothSingleAllocationOffset = code.Count;
            PatchBranch(
                code,
                horizontalBottomBothSingleAllocationExtensionOffset,
                horizontalBottomBothSingleAllocationOffset);

            // Bottom-both uses the one new source-width node after the clipped
            // old first node. Keep the same allocate/validate-before-publish
            // transaction as top-both, but preserve the existing head.
            Append(code, MoveLongA6ToD7);
            Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
            Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0);
            Decline(BranchEqualWord);
            Append(code, MoveAddressD0ToA6);

            Append(code, MoveLongA1ToPreDecrementA7);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongA0ToPreDecrementA7);
            Append(code, MoveLongD7ToPreDecrementA7);
            Append(code, MoveLongA5ToPreDecrementA7);

            Append(code, MoveLongImmediateD0); Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
            Append(code, TestLongD0);
            Append(code, BranchNotEqualWord);
            var bottomBothAllocationSucceededExtensionOffset = code.Count;
            Append(code, 0);
            EmitHorizontalRightOverhangRestoreFailure();

            var bottomBothAllocationSucceededOffset = code.Count;
            PatchBranch(code, bottomBothAllocationSucceededExtensionOffset, bottomBothAllocationSucceededOffset);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Append(code, BranchEqualWord);
            var bottomBothAllocationEvenExtensionOffset = code.Count; Append(code, 0);
            Append(code, BranchAlwaysWord);
            var bottomBothAllocationInvalidExtensionOffset = code.Count; Append(code, 0);

            var bottomBothAllocationEvenOffset = code.Count;
            PatchBranch(code, bottomBothAllocationEvenExtensionOffset, bottomBothAllocationEvenOffset);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Append(code, BranchHighWord);
            var bottomBothAllocationHighExtensionOffset = code.Count; Append(code, 0);
            Append(code, MoveLongD0ToD6);

            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA5);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA6);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA4);
            Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveAddressD0ToA1);

            CopySourceBoundsToNode(MoveAddressD6ToA0);
            Append(code, MoveWordA5DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, SubQuickOneWordD4);
            Append(code, MoveAddressA4ToA2);
            Append(code, MoveWordD4ToA2Displacement);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

            // The existing first node remains the head; splice the new lower
            // band between it and the former second node, then repair links.
            Append(code, MoveAddressD6ToA0);
            Append(code, MoveLongA4ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveLongA6ToD0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveLongD6ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveAddressA6ToA0);
            Append(code, MoveLongD6ToA0Displacement);
            Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);

            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickOneD0);
            Append(code, ReturnFromSubroutine);

            var bottomBothAllocationInvalidOffset = code.Count;
            PatchBranch(code, bottomBothAllocationInvalidExtensionOffset, bottomBothAllocationInvalidOffset);
            PatchBranch(code, bottomBothAllocationHighExtensionOffset, bottomBothAllocationInvalidOffset);
            EmitHorizontalRightOverhangFreeD0();
            EmitHorizontalRightOverhangRestoreFailure();

            var topBothAllocationInvalidOffset = code.Count;
            PatchBranch(code, topBothAllocationInvalidExtensionOffset, topBothAllocationInvalidOffset);
            PatchBranch(code, topBothAllocationHighExtensionOffset, topBothAllocationInvalidOffset);
            EmitHorizontalRightOverhangFreeD0();
            EmitHorizontalRightOverhangRestoreFailure();
        }

        var allocationBadOffset = code.Count;
        PatchBranch(code, allocationBadExtensionOffset, allocationBadOffset);
        PatchBranch(code, allocationAddressableExtensionOffset, allocationBadOffset);
        PatchBranch(code, allocationHighExtensionOffset, allocationAddressableOffset);
        // A failed address result is not published; release the block and
        // restore the private frame exactly as an allocation failure would.
        // D6 is assigned only after this validation, so D0 is still the
        // rejected odd/out-of-range Exec result that must be released.
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendExecFreeMemFromA0PreservingA1(code);
        EmitAllocationFailure();

        PatchBranch(code, execMissingExtensionOffset, code.Count);
        // Exec was absent before the private frame was opened, so only the
        // caller's saved D0 exists on the stack at this branch.
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var execMissingJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, execMissingJumpExtensionOffset, fallbackEntryOffset);

        // The fallback body must be emitted before patching the preflight
        // branches; append it last so every malformed form restores the one
        // caller word and reaches the prior Region arm.
        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);

        if (boundsNormalizationCallExtensions.Count > 0)
        {
            var boundsNormalizerOffset = code.Count;
            EmitTightenOutputRegionBounds();
            Append(code, ReturnFromSubroutine);
            foreach (var extensionOffset in boundsNormalizationCallExtensions)
                PatchBranch(code, extensionOffset, boundsNormalizerOffset);
        }

        if (fullChainBoundsNormalizationCallExtensions.Count > 0 ||
            additionalBoundsNormalizationCallExtensions is { Count: > 0 })
        {
            // Reuse the whole-chain normalizer's success guard through a
            // tiny stub: these call sites run only after publication, so the
            // stub supplies the already-earned D0==1 result.
            var successfulResultOffset = code.Count;
            Append(code, MoveQuickOneD0);
            Append(code, ReturnFromSubroutine);
            var boundsNormalizerOffset = AppendOrRegionRegionTightBoundsWrapperNative(
                code,
                successfulResultOffset);
            foreach (var extensionOffset in fullChainBoundsNormalizationCallExtensions)
                PatchBranch(code, extensionOffset, boundsNormalizerOffset);
            if (additionalBoundsNormalizationCallExtensions is not null)
            {
                foreach (var extensionOffset in additionalBoundsNormalizationCallExtensions)
                    PatchBranch(code, extensionOffset, boundsNormalizerOffset);
            }
        }

        return offset;
    }

    /// <summary>
    /// Emits a bounded equal-envelope one-node OR containment arm. A source
    /// contained by the destination is an allocation-free identity; the
    /// mirrored form widens the destination node in place from the containing
    /// source. Shared X/Y edges are admitted, and the arm validates either
    /// full-height horizontal containment or full-width vertical containment.
    /// Malformed or unsupported forms restore the caller frame and enter the
    /// established OR chain.
    /// </summary>
    private static int AppendOrRegionRegionEqualSpanContainmentNative(
        List<byte> code,
        int fallbackEntryOffset,
        bool sourceContainedByDestination,
        int? emptyFallbackEntryOffset = null,
        bool verticalContainment = false)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(64);
        var emptyFallbackBranches = new List<int>(4);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void DeclineEmpty(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            emptyFallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0);
            Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0);
            Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitNodePointerAdmission(
            ushort moveNodeToD0,
            ushort displacement)
        {
            Append(code, moveNodeToD0);
            Append(code, displacement);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0);
            Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        void EmitNodeBoundsValidation(ushort nodeMinToD4, ushort nodeMaxToD5)
        {
            Append(code, nodeMinToD4);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, nodeMaxToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, nodeMinToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, nodeMaxToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        // Keep A5 as the destination Region and use A0/A1 as the ordered
        // destination/source views used by the admission below.
        Append(code, MoveAddressA0ToA4);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveAddressA4ToA1);
        Append(code, MoveAddressA0ToA5);

        if (emptyFallbackEntryOffset.HasValue)
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangle);
            Append(code, TestLongD0); DeclineEmpty(BranchEqualWord);
            Append(code, MoveLongA1DisplacementToD0);
            Append(code, (ushort)GraphicsLayouts.RegionRectangle);
            Append(code, TestLongD0); DeclineEmpty(BranchEqualWord);
        }

        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        EmitNodePointerAdmission(
            MoveLongA0DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA0ToA4);
        Append(code, AddQuickEightLongA4);
        Append(code, MoveLongA4ToD6);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        Append(code, MoveAddressA2ToA6);
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        EmitNodePointerAdmission(
            MoveLongA1DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA1ToA4);
        Append(code, AddQuickEightLongA4);
        Append(code, MoveLongA4ToD6);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveAddressA6ToA2);

        // Both Region headers describe the same non-negative envelope.
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, CompareWordD4ToD1); Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, CompareWordD4ToD2); Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD3); Decline(BranchNotEqualWord);

        // D0..D3 remain the public envelope. Validate both relative node
        // rectangles before checking the strict containment edges.
        EmitNodeBoundsValidation(MoveWordA2DisplacementToD4, MoveWordA2DisplacementToD5);
        EmitNodeBoundsValidation(MoveWordA3DisplacementToD4, MoveWordA3DisplacementToD5);

        void EmitWidenDestination()
        {
            // Widen the destination node to the source rectangle in place.
            Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordD4ToA2Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD4ToA2Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD4ToA2Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordD4ToA2Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        }

        if (!verticalContainment)
        {
            // Both one-node forms are full-height; containment is horizontal.
            Append(code, MoveWordA2DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA2DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
            Append(code, CompareWordD5ToD6); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD5ToD6); Decline(BranchNotEqualWord);

            if (sourceContainedByDestination)
            {
                // Destination owns both public X edges; source is contained,
                // including a shared X edge.
                Append(code, MoveWordA2DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
                Append(code, TestWordD4); Decline(BranchNotEqualWord);
                Append(code, MoveWordA2DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
                Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
                Append(code, CompareWordD5ToD6); Decline(BranchNotEqualWord);
                Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
                Append(code, TestWordD4); Decline(BranchLessThanWord);
                Append(code, MoveWordA3DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
                Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
            }
            else
            {
                // Source owns both public X edges; destination is contained,
                // including a shared X edge.
                Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
                Append(code, TestWordD4); Decline(BranchNotEqualWord);
                Append(code, MoveWordA3DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
                Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
                Append(code, CompareWordD5ToD6); Decline(BranchNotEqualWord);
                Append(code, MoveWordA2DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
                Append(code, TestWordD4); Decline(BranchLessThanWord);
                Append(code, MoveWordA2DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
                Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
            }
        }
        else
        {
            // Both one-node forms are full-width; containment is vertical.
            Append(code, MoveWordA2DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA2DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
            Append(code, CompareWordD5ToD6); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD5ToD6); Decline(BranchNotEqualWord);

            if (sourceContainedByDestination)
            {
                // Destination owns both public Y edges; source is contained,
                // including a shared Y edge.
                Append(code, MoveWordA2DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
                Append(code, TestWordD4); Decline(BranchNotEqualWord);
                Append(code, MoveWordA2DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
                Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
                Append(code, CompareWordD5ToD6); Decline(BranchNotEqualWord);
                Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
                Append(code, TestWordD4); Decline(BranchLessThanWord);
                Append(code, MoveWordA3DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
                Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
            }
            else
            {
                // Source owns both public Y edges; destination is contained,
                // including a shared Y edge.
                Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
                Append(code, TestWordD4); Decline(BranchNotEqualWord);
                Append(code, MoveWordA3DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
                Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
                Append(code, CompareWordD5ToD6); Decline(BranchNotEqualWord);
                Append(code, MoveWordA2DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
                Append(code, TestWordD4); Decline(BranchLessThanWord);
                Append(code, MoveWordA2DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
                Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
            }
        }

        if (!sourceContainedByDestination)
            EmitWidenDestination();

        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveAddressA5ToA1);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressA0ToA4);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveAddressA4ToA1);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        var emptyFallbackRestoreOffset = -1;
        var emptyFallbackJumpExtensionOffset = -1;
        if (emptyFallbackEntryOffset.HasValue)
        {
            emptyFallbackRestoreOffset = code.Count;
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveAddressA0ToA4);
            Append(code, MoveAddressA1ToA0);
            Append(code, MoveAddressA4ToA1);
            Append(code, BranchAlwaysWord);
            emptyFallbackJumpExtensionOffset = code.Count; Append(code, 0);
        }
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        if (emptyFallbackEntryOffset.HasValue)
            PatchBranch(code, emptyFallbackJumpExtensionOffset, emptyFallbackEntryOffset.Value);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        foreach (var branch in emptyFallbackBranches)
            PatchBranch(code, branch, emptyFallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Emits the bounded equal-span crossing OR arm. The destination starts at
    /// the public minimum, the source reaches the public maximum, and the two
    /// full-height rectangles overlap or touch. Their union is the complete
    /// public envelope, so the existing destination node can be widened in
    /// place without resolving Exec; malformed or unsupported forms enter the
    /// established OR chain with the caller frame restored.
    /// </summary>
    private static int AppendOrRegionRegionEqualSpanOverlapNative(
        List<byte> code,
        int fallbackEntryOffset,
        bool reverseCrossing = false,
        int? emptyFallbackEntryOffset = null,
        bool verticalCrossing = false)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(64);
        var emptyFallbackBranches = new List<int>(4);

        void DeclineTo(ushort branchOpcode, List<int> branches)
        {
            Append(code, branchOpcode);
            branches.Add(code.Count);
            Append(code, 0);
        }

        void Decline(ushort branchOpcode) => DeclineTo(branchOpcode, fallbackBranches);

        void DeclineEmpty(ushort branchOpcode) =>
            DeclineTo(branchOpcode, emptyFallbackBranches);

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0);
            Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0);
            Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitNodePointerAdmission(
            ushort moveNodeToD0,
            ushort displacement,
            bool directEmptyFallback = false)
        {
            Append(code, moveNodeToD0);
            Append(code, displacement);
            Append(code, TestLongD0);
            if (directEmptyFallback && emptyFallbackEntryOffset.HasValue)
                DeclineEmpty(BranchEqualWord);
            else
                Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0);
            Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveAddressA0ToA4);
        Append(code, MoveAddressA1ToA5);

        EmitOwnedRegionAdmission(MoveLongA4ToD0);
        EmitNodePointerAdmission(
            MoveLongA4DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle,
            directEmptyFallback: emptyFallbackEntryOffset.HasValue);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveAddressA2ToA6);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveAddressA4ToA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, MoveLongA0ToD6);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        EmitOwnedRegionAdmission(MoveLongA5ToD0);
        EmitNodePointerAdmission(
            MoveLongA5DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle,
            directEmptyFallback: emptyFallbackEntryOffset.HasValue);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveAddressA5ToA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, MoveLongA0ToD6);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        // Equal public envelopes and non-negative full-height extents.
        Append(code, MoveWordA5DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA5DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA5DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA5DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        Append(code, MoveWordA4DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA4DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, CompareWordD5ToD1); Decline(BranchNotEqualWord);
        Append(code, MoveWordA4DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, CompareWordD6ToD2); Decline(BranchNotEqualWord);
        Append(code, MoveWordA4DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD7ToD3); Decline(BranchNotEqualWord);
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
        Decline(BranchOverflowWord);
        Append(code, MoveWordD3ToD7); Append(code, SubWordD1ToD7);
        Decline(BranchOverflowWord);

        // Admit either orientation of the crossing. In the normal form the
        // destination owns the public minimum and the source reaches the
        // public maximum. The mirrored form swaps those X-edge obligations;
        // both still require full-height rectangles whose intervals overlap
        // or touch.
        if (!verticalCrossing && !reverseCrossing)
        {
            Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, TestWordD5); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, TestWordD0); Decline(BranchLessThanWord);
            Append(code, CompareWordD0ToD6); Decline(BranchLessThanWord);
            Append(code, MoveWordA3DisplacementToD1); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD1ToD7); Decline(BranchNotEqualWord);
            Append(code, MoveWordA6DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA6DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, TestWordD5); Decline(BranchNotEqualWord);
            Append(code, MoveWordA6DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD0ToD6); Decline(BranchLessThanWord);
            Append(code, MoveWordA3DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, MoveWordA6DisplacementToD1); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD1ToD7); Decline(BranchNotEqualWord);
        }
        else if (!verticalCrossing)
        {
            Append(code, MoveWordA6DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA6DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, TestWordD5); Decline(BranchNotEqualWord);
            Append(code, MoveWordA6DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, TestWordD0); Decline(BranchLessThanWord);
            Append(code, CompareWordD0ToD6); Decline(BranchLessThanWord);
            Append(code, MoveWordA6DisplacementToD1); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD1ToD7); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA3DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, TestWordD5); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD0ToD6); Decline(BranchNotEqualWord);
            Append(code, MoveWordA6DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, MoveWordA3DisplacementToD1); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD1ToD7); Decline(BranchNotEqualWord);
        }
        else if (!reverseCrossing)
        {
            Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD0ToD6); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, TestWordD0); Decline(BranchLessThanWord);
            Append(code, CompareWordD0ToD7); Decline(BranchLessThanWord);
            Append(code, MoveWordA6DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA6DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD0ToD6); Decline(BranchNotEqualWord);
            Append(code, MoveWordA6DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA6DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD0ToD7); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
        }
        else
        {
            Append(code, MoveWordA6DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA6DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD0ToD6); Decline(BranchNotEqualWord);
            Append(code, MoveWordA6DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA6DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, TestWordD0); Decline(BranchLessThanWord);
            Append(code, CompareWordD0ToD7); Decline(BranchLessThanWord);
            Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD0ToD6); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA3DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD0ToD7); Decline(BranchNotEqualWord);
            Append(code, MoveWordA6DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
        }

        // The union is the complete public envelope; rewrite only the
        // destination node and leave links, source storage, and header intact.
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToA3Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD0ToA3Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD6ToD2);
        Append(code, MoveWordD2ToA3Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD7ToD3);
        Append(code, MoveWordD3ToA3Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveAddressA5ToA1);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveAddressA5ToA1);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        var emptyFallbackRestoreOffset = -1;
        var emptyFallbackJumpExtensionOffset = -1;
        if (emptyFallbackEntryOffset.HasValue)
        {
            emptyFallbackRestoreOffset = code.Count;
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveAddressA5ToA1);
            Append(code, BranchAlwaysWord);
            emptyFallbackJumpExtensionOffset = code.Count; Append(code, 0);
        }
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        if (emptyFallbackEntryOffset.HasValue)
            PatchBranch(code, emptyFallbackJumpExtensionOffset, emptyFallbackEntryOffset.Value);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        foreach (var branch in emptyFallbackBranches)
            PatchBranch(code, branch, emptyFallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Emits the bounded one-band right-edge-overlap XOR arm. Both operands
    /// are marker-owned canonical one-node Regions with matching public
    /// envelopes and full-height rectangles. The source starts inside the
    /// destination and ends at the same right edge, so the symmetric
    /// difference is the destination's left-hand remainder. It is written in
    /// place without an Exec dependency; malformed or unsupported forms enter
    /// the existing XOR chain with the caller frame restored.
    /// </summary>
    private static int AppendXorRegionRegionEqualSpanRightEdgeNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(64);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0);
            Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0);
            Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitNodePointerAdmission(ushort moveNodeToD0, ushort displacement)
        {
            Append(code, moveNodeToD0);
            Append(code, displacement);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0);
            Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveAddressA0ToA4);
        Append(code, MoveAddressA1ToA5);

        EmitOwnedRegionAdmission(MoveLongA4ToD0);
        EmitNodePointerAdmission(
            MoveLongA4DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveAddressA2ToA6);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveAddressA4ToA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, MoveLongA0ToD6);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        EmitOwnedRegionAdmission(MoveLongA5ToD0);
        EmitNodePointerAdmission(
            MoveLongA5DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveAddressA5ToA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, MoveLongA0ToD6);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        // Preserve the destination absolute envelope and require equal
        // envelopes with a non-negative width/height.
        Append(code, MoveWordA5DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA5DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA5DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA5DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        Append(code, MoveWordA4DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA4DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, CompareWordD5ToD1); Decline(BranchNotEqualWord);
        Append(code, MoveWordA4DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, CompareWordD6ToD2); Decline(BranchNotEqualWord);
        Append(code, MoveWordA4DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD7ToD3); Decline(BranchNotEqualWord);
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
        Decline(BranchOverflowWord);
        Append(code, MoveWordD3ToD7); Append(code, SubWordD1ToD7);
        Decline(BranchOverflowWord);

        // Destination is the complete envelope; source reaches the same
        // right edge but starts strictly inside it.
        Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, TestWordD4); Decline(BranchNotEqualWord);
        Append(code, MoveWordA3DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, TestWordD5); Decline(BranchNotEqualWord);
        Append(code, MoveWordA3DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD0ToD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordA3DisplacementToD1); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD1ToD7); Decline(BranchNotEqualWord);
        Append(code, MoveWordA6DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, TestWordD4); Decline(BranchLessOrEqualWord);
        Append(code, MoveWordA6DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, TestWordD5); Decline(BranchNotEqualWord);
        Append(code, MoveWordA6DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD0ToD6); Decline(BranchNotEqualWord);
        Append(code, CompareWordD0ToD4); Decline(BranchGreaterThanWord);
        Append(code, MoveWordA6DisplacementToD1); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD1ToD7); Decline(BranchNotEqualWord);

        // The surviving left band ends one word before source.minX. The
        // public header and destination node are rebased without allocation.
        Append(code, MoveWordA6DisplacementToD4); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
        Append(code, MoveWordD4ToD0);
        Append(code, SubQuickOneWordD0); Decline(BranchOverflowWord);
        Append(code, MoveWordD0ToD5);
        Append(code, MoveWordA5DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, AddWordD4ToD0); Decline(BranchOverflowWord);
        Append(code, SubQuickOneWordD0); Decline(BranchOverflowWord);
        Append(code, MoveWordD0ToD4);
        Append(code, MoveWordD4ToA5Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);

        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToA3Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD0ToA3Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD5ToD0);
        Append(code, MoveWordD0ToA3Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD7ToD1);
        Append(code, MoveWordD1ToA3Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveAddressA5ToA1);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveAddressA5ToA1);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Emits the bounded one-band edge-overlap XOR arm. Both operands are
    /// marker-owned canonical one-node Regions with matching public envelopes
    /// and full-height rectangles. The source and destination share the left
    /// edge and the source ends first, so the symmetric difference is the
    /// destination's right-hand remainder. It is written in place without an
    /// Exec dependency; malformed or unsupported forms enter the existing XOR
    /// chain with the caller frame restored.
    /// </summary>
    private static int AppendXorRegionRegionEqualSpanLeftEdgeNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(64);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0);
            Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0);
            Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0);
            Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitNodePointerAdmission(ushort moveNodeToD0, ushort displacement)
        {
            Append(code, moveNodeToD0);
            Append(code, displacement);
            Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0);
            Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        // Keep the caller's result seed and the public Region identities in
        // callee-saved address registers while admission uses A0-A3.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveAddressA0ToA4);
        Append(code, MoveAddressA1ToA5);

        EmitOwnedRegionAdmission(MoveLongA4ToD0);
        EmitNodePointerAdmission(
            MoveLongA4DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA2); // source node
        Append(code, MoveAddressA2ToA6);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveAddressA4ToA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, MoveLongA0ToD6);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        EmitOwnedRegionAdmission(MoveLongA5ToD0);
        EmitNodePointerAdmission(
            MoveLongA5DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA3); // destination node
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveAddressA5ToA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, MoveLongA0ToD6);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        // The public envelopes must match and be ordered. D0-D3 retain the
        // destination absolute envelope; D6/D7 become its signed extents.
        Append(code, MoveWordA5DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA5DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA5DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA5DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);

        Append(code, MoveWordA4DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA4DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, CompareWordD5ToD1); Decline(BranchNotEqualWord);
        Append(code, MoveWordA4DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA4DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD6ToD2); Decline(BranchNotEqualWord);
        Append(code, CompareWordD7ToD3); Decline(BranchNotEqualWord);

        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
        Decline(BranchOverflowWord);
        Append(code, MoveWordD3ToD7); Append(code, SubWordD1ToD7);
        Decline(BranchOverflowWord);

        // Both node rectangles span the complete public height and start at
        // the envelope minimum X. Their maximum X values are ordered so the
        // XOR result is one non-empty right-hand band.
        Append(code, MoveWordA3DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, TestWordD4); Decline(BranchNotEqualWord);
        Append(code, MoveWordA3DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, TestWordD5); Decline(BranchNotEqualWord);
        Append(code, MoveWordA3DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD6ToD0); Decline(BranchGreaterThanWord);
        Append(code, MoveWordA3DisplacementToD1); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD1ToD7); Decline(BranchNotEqualWord);
        Append(code, MoveWordA6DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, TestWordD4); Decline(BranchNotEqualWord);
        Append(code, MoveWordA6DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, TestWordD5); Decline(BranchNotEqualWord);
        Append(code, MoveWordA6DisplacementToD1); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordA3DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD0ToD1); Decline(BranchGreaterOrEqualWord);
        Append(code, MoveWordA6DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD0ToD7); Decline(BranchNotEqualWord);

        // New header.minX = old header.minX + source.maxX + 1. The old
        // destination maxX and Y envelope remain unchanged.
        Append(code, MoveWordA5DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA6DisplacementToD0); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, AddWordD0ToD4); Decline(BranchOverflowWord);
        Append(code, AddQuickOneWordD4); Decline(BranchOverflowWord);
        Append(code, MoveWordD4ToA5Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinX);

        // Rebase the surviving destination node against the new header.
        Append(code, MoveWordA3DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordA6DisplacementToD6); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, SubWordD6ToD5); Decline(BranchOverflowWord);
        Append(code, SubQuickOneWordD5); Decline(BranchOverflowWord);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToA3Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD0ToA3Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD5ToA3Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordA5DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordA5DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, SubWordD7ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordD6ToD0);
        Append(code, MoveWordD0ToA3Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

        Append(code, MoveAddressA5ToA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0); Append(code, AddQuickTwoLongA0);
        Append(code, MoveLongA0ToD6);
        Append(code, MoveLongD6ToA3Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveLongD6ToA3Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);

        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveAddressA5ToA1);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveAddressA5ToA1);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Emits the first topology-changing XOR Region-to-Region overlap arm.
    /// Both operands are marker-owned canonical one-node Regions with the
    /// same public envelope and full-height rectangles.  The rectangles cross
    /// in X (destination starts at the envelope minimum, source ends at the
    /// envelope maximum), so their equal-span symmetric difference is exactly
    /// two interior-free bands.  Both replacement nodes are staged before the
    /// old destination node is retired; every malformed or escaping form
    /// restores the caller frame and enters the established XOR chain.
    /// </summary>
    private static int AppendXorRegionRegionEqualSpanOverlapNative(
        List<byte> code,
        int fallbackEntryOffset,
        bool sourceContainedByDestination = false,
        bool destinationContainedBySource = false,
        bool reverseCrossing = false,
        bool verticalCrossing = false)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(64);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0);
            Append(code, TestLongD0);
            Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0);
            Append(code, MoveAddressD0ToA4);
            Append(code, MoveWordA4DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        void EmitNodeLinkAdmission()
        {
            Append(code, TestLongD0);
            Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0);
            Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Decline(BranchHighWord);
        }

        void EmitNodeBoundsValidation(
            ushort nodeMinXToD4,
            ushort nodeMinYToD4,
            ushort nodeMaxXToD5,
            ushort nodeMaxYToD5)
        {
            Append(code, nodeMinXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, nodeMaxXToD5); Append(code,
                (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, nodeMinYToD4); Append(code,
                (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, nodeMaxYToD5); Append(code,
                (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        // Keep the portable seed until the admission either succeeds or
        // explicitly restores it before entering the established fallback.
        Append(code, MoveLongD0ToPreDecrementA7);
        // The public ABI passes source in A0 and destination in A1.  The
        // transaction below is written destination-first, so swap the two
        // pointers while retaining a reversible pair for every decline path.
        Append(code, MoveAddressA0ToA4);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveAddressA4ToA1);
        Append(code, MoveAddressA0ToA5); // destination Region survives Exec calls

        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        EmitNodeLinkAdmission();
        Append(code, MoveAddressD0ToA2); // old destination node
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA0ToA4);
        Append(code, AddQuickEightLongA4);
        Append(code, MoveLongA4ToD6);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        // Preserve the destination absolute envelope in D0..D3.  The source
        // must expose the same envelope; this keeps the first unit's output
        // header stable while still exercising signed relative coordinates.
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        EmitNodeBoundsValidation(MoveWordA2DisplacementToD4, MoveWordA2DisplacementToD4,
            MoveWordA2DisplacementToD5, MoveWordA2DisplacementToD5);

        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, CompareWordD4ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, CompareWordD4ToD1); Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, CompareWordD4ToD2); Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD3); Decline(BranchNotEqualWord);

        Append(code, MoveLongA1DisplacementToD4);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD4); Decline(BranchEqualWord);
        Append(code, BitTestImmediateD4); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD4); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveAddressD4ToA3); // source node
        Append(code, MoveLongA3DisplacementToD4);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD4); Decline(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD4);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA1ToA4);
        Append(code, AddQuickEightLongA4);
        Append(code, MoveLongA4ToD6);
        Append(code, CompareLongD6ToD4); Decline(BranchNotEqualWord);
        EmitNodeBoundsValidation(MoveWordA3DisplacementToD4, MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD5, MoveWordA3DisplacementToD5);

        // Re-read the X words after validation. The normal arm handles a
        // strict crossing; the contained arm handles source strictly inside
        // the complete destination span and uses the destination's public
        // width for the right replacement band.
        if (verticalCrossing && !reverseCrossing)
        {
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordA3DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordD6ToD4);
            Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
            Append(code, CompareWordD5ToD4); Decline(BranchGreaterThanWord);
            Append(code, MoveWordD5ToD7);
            Append(code, MoveWordA3DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD5ToD6); Decline(BranchNotEqualWord);
            Append(code, CompareWordD5ToD7); Decline(BranchGreaterOrEqualWord);
            Append(code, MoveQuickZeroD4);
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveQuickZeroD5);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveQuickZeroD6);
            Append(code, MoveWordA3DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveQuickZeroD7);
            Append(code, MoveWordA3DisplacementToD7);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        }
        else if (verticalCrossing)
        {
            Append(code, MoveWordA3DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
            Append(code, CompareWordD5ToD6); Decline(BranchNotEqualWord);
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, TestWordD4); Decline(BranchLessOrEqualWord);
            Append(code, MoveWordA3DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD5ToD6); Decline(BranchLessOrEqualWord);
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, MoveQuickZeroD4);
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveQuickZeroD5);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveQuickZeroD6);
            Append(code, MoveWordA3DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveQuickZeroD7);
            Append(code, MoveWordA3DisplacementToD7);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        }
        else if (sourceContainedByDestination)
        {
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD5ToD7); // destination.maxX survives source.maxX load
            Append(code, MoveWordA3DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, CompareWordD4ToD6); Decline(BranchLessOrEqualWord);
            Append(code, MoveWordA3DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD5ToD7); Decline(BranchLessOrEqualWord);
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
            Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);
        }
        else if (destinationContainedBySource)
        {
            Append(code, MoveWordA3DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
            Append(code, CompareWordD5ToD6); Decline(BranchNotEqualWord);
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, TestWordD4); Decline(BranchLessOrEqualWord);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD5ToD6); Decline(BranchLessOrEqualWord);
        }
        else if (reverseCrossing)
        {
            Append(code, MoveWordA3DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
            Append(code, CompareWordD5ToD6); Decline(BranchNotEqualWord);
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, TestWordD4); Decline(BranchLessOrEqualWord);
            Append(code, MoveWordA3DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD5ToD6); Decline(BranchLessOrEqualWord);
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
        }
        else
        {
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA3DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordD6ToD4); // source.minX survives width computation
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
            Append(code, CompareWordD5ToD4); Decline(BranchGreaterThanWord);
            Append(code, MoveWordD5ToD7); // destination.maxX survives source.maxX load
            Append(code, MoveWordA3DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD5ToD6); Decline(BranchNotEqualWord);
            Append(code, CompareWordD5ToD7); Decline(BranchGreaterOrEqualWord);
        }

        if (verticalCrossing)
        {
            // Equal X spans cover the public width. Stage the Y edges used by
            // the top/bottom symmetric-difference bands.
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
            Append(code, CompareWordD5ToD6); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD4);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, TestWordD4); Decline(BranchNotEqualWord);
            Append(code, MoveWordA3DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD5ToD6); Decline(BranchNotEqualWord);

            Append(code, MoveQuickZeroD4);
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveQuickZeroD6);
            Append(code, MoveWordA3DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveQuickZeroD5);
            Append(code, MoveWordA3DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveQuickZeroD7);
            Append(code, MoveWordA2DisplacementToD7);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            if (!reverseCrossing)
            {
                Append(code, MoveQuickZeroD5);
                Append(code, MoveWordA2DisplacementToD5);
                Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
                Append(code, MoveQuickZeroD7);
                Append(code, MoveWordA3DisplacementToD7);
                Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            }
        }
        else
        {
        // Restore the canonical X register layout for the transaction frame.
        // D4 is the destination minimum, D6/D5 are source min/max, and D7 is
        // the destination maximum for the contained arm; the crossing arm
        // retains its original source/destination maximum ordering.
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
        Append(code, MoveWordA3DisplacementToD6);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
        if (sourceContainedByDestination)
        {
            Append(code, MoveWordA3DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA2DisplacementToD7);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        }
        else if (reverseCrossing)
        {
            Append(code, MoveWordA2DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordA3DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA2DisplacementToD7);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        }
        else if (destinationContainedBySource)
        {
            Append(code, MoveWordA2DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA3DisplacementToD7);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        }
        else
        {
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA3DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD5ToD7);
            Append(code, MoveQuickZeroD5);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
