            Append(code, MoveQuickZeroD5);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveQuickZeroD7);
            Append(code, MoveWordA3DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD5ToD7);

            // D5 was used as the source max-X staging register; restore the
            // destination max-X value that drives the right-hand band.
            Append(code, MoveQuickZeroD5);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        }
        }

        // Save the old destination node and all geometry before resolving
        // Exec. D0..D3 are the public envelope; D4..D7 are the two split-axis
        // edge pairs.
        Append(code, MoveLongA2ToPreDecrementA7);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongD2ToPreDecrementA7);
        Append(code, MoveLongD3ToPreDecrementA7);
        Append(code, MoveLongD4ToPreDecrementA7);
        Append(code, MoveLongD5ToPreDecrementA7);
        Append(code, MoveLongD6ToPreDecrementA7);
        Append(code, MoveLongD7ToPreDecrementA7);

        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var execResolvedExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var execMissingExtensionOffset = code.Count; Append(code, 0);

        var execResolvedOffset = code.Count;
        PatchBranch(code, execResolvedExtensionOffset, execResolvedOffset);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0); Append(code, BranchEqualWord);
        var firstAllocationFailedExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveAddressD0ToA3);
        Append(code, BitTestImmediateD0); Append(code, 0);
        Append(code, BranchEqualWord);
        var firstAllocationEvenExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchLowerOrSameWord);
        var firstAllocationAddressableExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var firstAllocationBadExtensionOffset = code.Count; Append(code, 0);

        var firstAllocationEvenOffset = code.Count;
        PatchBranch(code, firstAllocationEvenExtensionOffset, firstAllocationEvenOffset);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchLowerOrSameWord);
        var firstAllocationEvenAddressableExtensionOffset = code.Count; Append(code, 0);
        var firstAllocationAddressableOffset = code.Count;
        PatchBranch(code, firstAllocationAddressableExtensionOffset, firstAllocationAddressableOffset);
        PatchBranch(code, firstAllocationEvenAddressableExtensionOffset, firstAllocationAddressableOffset);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0); Append(code, BranchEqualWord);
        var secondAllocationFailedExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveAddressD0ToA4);
        Append(code, BitTestImmediateD0); Append(code, 0);
        Append(code, BranchEqualWord);
        var secondAllocationEvenExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchLowerOrSameWord);
        var secondAllocationAddressableExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var secondAllocationBadExtensionOffset = code.Count; Append(code, 0);

        var secondAllocationEvenOffset = code.Count;
        PatchBranch(code, secondAllocationEvenExtensionOffset, secondAllocationEvenOffset);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Append(code, BranchLowerOrSameWord);
        var secondAllocationEvenAddressableExtensionOffset = code.Count; Append(code, 0);
        var secondAllocationAddressableOffset = code.Count;
        PatchBranch(code, secondAllocationAddressableExtensionOffset, secondAllocationAddressableOffset);
        PatchBranch(code, secondAllocationEvenAddressableExtensionOffset, secondAllocationAddressableOffset);

        // Restore the envelope and X edges after both private allocations.
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveLongA7PostIncrementToD5);
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveLongA7PostIncrementToD3);
        Append(code, MoveLongA7PostIncrementToD2);
        Append(code, MoveLongA7PostIncrementToD1);
        Append(code, MoveLongA7PostIncrementToD0);

        if (verticalCrossing && !reverseCrossing)
        {
            // Keep the values needed for the second node while initializing
            // the top band. The first node is full width and ends above the
            // source rectangle.
            Append(code, MoveLongD5ToPreDecrementA7);
            Append(code, MoveLongD6ToPreDecrementA7);
            Append(code, MoveLongD7ToPreDecrementA7);
            Append(code, MoveWordD6ToD4); Append(code, SubQuickOneWordD4);
            Append(code, MoveWordD4ToD7);
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
            Append(code, MoveQuickZeroD4); Append(code, MoveQuickZeroD5);
            Append(code, MoveAddressA3ToA0);
            Append(code, MoveWordD4ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordD5ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD7ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveLongA7PostIncrementToD7);
            Append(code, MoveLongA7PostIncrementToD6);
            Append(code, MoveLongA7PostIncrementToD5);
            Append(code, MoveWordD5ToD6); Append(code, AddQuickOneWordD6);
            Append(code, MoveWordD2ToD4); Append(code, SubWordD0ToD4);
            Append(code, MoveQuickZeroD5);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveWordD5ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD4ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD7ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        }
        else if (verticalCrossing)
        {
            // Mirrored crossing: stage the top band before destination.minY,
            // then the bottom band after source.maxY.
            Append(code, MoveLongD5ToPreDecrementA7);
            Append(code, MoveLongD6ToPreDecrementA7);
            Append(code, MoveLongD7ToPreDecrementA7);
            Append(code, MoveWordD4ToD5); Append(code, SubQuickOneWordD5);
            Append(code, MoveWordD5ToD7);
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
            Append(code, MoveQuickZeroD4); Append(code, MoveQuickZeroD5);
            Append(code, MoveAddressA3ToA0);
            Append(code, MoveWordD4ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordD5ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD7ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveLongA7PostIncrementToD7);
            Append(code, MoveLongA7PostIncrementToD6);
            Append(code, MoveLongA7PostIncrementToD5);
            Append(code, MoveWordD5ToD6); Append(code, AddQuickOneWordD6);
            Append(code, MoveWordD2ToD4); Append(code, SubWordD0ToD4);
            Append(code, MoveQuickZeroD5);
            Append(code, MoveAddressA4ToA0);
            Append(code, MoveWordD5ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
            Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD4ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD7ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        }
        else
        {
        // Keep the values needed for the second node while initializing the
        // left band. The first node is [0..source.minX-1] x full height.
        Append(code, MoveLongD5ToPreDecrementA7);
        Append(code, MoveLongD6ToPreDecrementA7);
        Append(code, MoveLongD7ToPreDecrementA7);
        Append(code, MoveWordD6ToD4); Append(code, SubQuickOneWordD4);
        Append(code, MoveWordD4ToD6);
        Append(code, MoveWordD3ToD7); Append(code, SubWordD1ToD7);
        Append(code, MoveQuickZeroD4); Append(code, MoveQuickZeroD5);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveWordD4ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
        Append(code, MoveWordD5ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD7ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveLongA7PostIncrementToD5);
        Append(code, MoveWordD5ToD6); Append(code, AddQuickOneWordD6);
        Append(code, MoveWordD3ToD4); Append(code, SubWordD1ToD4);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinX));
        Append(code, MoveWordD5ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD7ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD4ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));

        }

        // Link both private nodes before making the destination head public.
        Append(code, MoveAddressA5ToA0);
        Append(code, AddQuickEightLongA0);
        Append(code, MoveLongA0ToD6);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA4ToD6);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA3ToD6);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA3ToD6);
        Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);

        // Publish first, then retire only the old destination node.
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressA1ToA4);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveAddressA4ToA1);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var secondAllocationFailedOffset = code.Count;
        PatchBranch(code, secondAllocationFailedExtensionOffset, secondAllocationFailedOffset);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendExecFreeMemFromA0PreservingA1(code);
        for (var index = 0; index < 8; index++)
            Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0); // saved old node
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveQuickZeroD0); Append(code, ReturnFromSubroutine);

        var secondAllocationBadOffset = code.Count;
        PatchBranch(code, secondAllocationBadExtensionOffset, secondAllocationBadOffset);
        PatchBranch(code, secondAllocationAddressableExtensionOffset, secondAllocationAddressableOffset);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendExecFreeMemFromA0PreservingA1(code);
        for (var index = 0; index < 8; index++)
            Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveQuickZeroD0); Append(code, ReturnFromSubroutine);

        var firstAllocationFailedOffset = code.Count;
        PatchBranch(code, firstAllocationFailedExtensionOffset, firstAllocationFailedOffset);
        PatchBranch(code, execMissingExtensionOffset, firstAllocationFailedOffset);
        for (var index = 0; index < 8; index++)
            Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveQuickZeroD0); Append(code, ReturnFromSubroutine);

        var firstAllocationBadOffset = code.Count;
        PatchBranch(code, firstAllocationBadExtensionOffset, firstAllocationBadOffset);
        PatchBranch(code, firstAllocationAddressableExtensionOffset, firstAllocationAddressableOffset);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1);
        AppendExecFreeMemFromA0PreservingA1(code);
        for (var index = 0; index < 8; index++)
            Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD0); Append(code, MoveQuickZeroD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveAddressA0ToA4);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveAddressA4ToA1);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    private static int AppendOrXorRegionRegionCanonicalDisjointNative(
        List<byte> code,
        int fallbackEntryOffset,
        int canonicalSourceTransferEntryOffset,
        int orRectRegionEntryOffset,
        bool requireDisjoint,
        int twoNodeIdentityEntryOffset = -1)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(39);
        var identicalRectangleFallbackBranches = new List<int>(4);
        var twoNodeIdentityDispatchExtensionOffset = -1;

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD6); Decline(BranchEqualWord);
        Append(code, MoveAddressD6ToA2);
        Append(code, BitTestImmediateD6); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD6); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD6);
        if (twoNodeIdentityEntryOffset >= 0)
        {
            Append(code, BranchNotEqualWord);
            twoNodeIdentityDispatchExtensionOffset = code.Count;
            Append(code, 0);
        }
        else
        {
            Decline(BranchNotEqualWord);
        }
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA0ToA3); Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordA2DisplacementToD6);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);

        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD4); Decline(BranchEqualWord);
        Append(code, MoveAddressD4ToA2);
        Append(code, BitTestImmediateD4); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD4); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD6); Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA1ToA3); Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD0); Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD6); Decline(BranchLessThanWord);
        Append(code, CompareWordD5ToD7); Decline(BranchLessThanWord);
        Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordA2DisplacementToD6);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordD6ToD0); Append(code, SubWordD4ToD0); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD7ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordD6ToD0); Append(code, SubWordD5ToD0); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD7ToD0); Decline(BranchNotEqualWord);

        if (!requireDisjoint)
        {
            // OrRegionRegion permits source and destination aliasing, but the
            // identity is admitted only after both one-node Regions have
            // passed normal ownership and envelope validation.
            Append(code, CompareAddressA1ToA0);
            Append(code, BranchNotEqualWord);
            var nonAliasedExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickOneD0);
            Append(code, ReturnFromSubroutine);
            var nonAliasedOffset = code.Count;
            PatchBranch(code, nonAliasedExtensionOffset, nonAliasedOffset);
        }

        var canonicalTransferExtensionOffset = -1;
        if (requireDisjoint)
        {
            // Inclusive rectangle bounds are disjoint only when one minimum
            // is strictly beyond the other's maximum. That is the exact
            // condition under which XOR is equal to OR.
            Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveWordA1DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, CompareWordD6ToD0); Append(code, BranchGreaterThanWord);
            var disjointLeftExtensionOffset = code.Count; Append(code, 0);
            Append(code, CompareWordD2ToD4); Append(code, BranchGreaterThanWord);
            var disjointRightExtensionOffset = code.Count; Append(code, 0);
            Append(code, CompareWordD7ToD1); Append(code, BranchGreaterThanWord);
            var disjointAboveExtensionOffset = code.Count; Append(code, 0);
            Append(code, CompareWordD3ToD5); Append(code, BranchGreaterThanWord);
            var disjointBelowExtensionOffset = code.Count; Append(code, 0);

            // Equal canonical source/destination rectangles XOR to an empty
            // destination. A2 still denotes the fully admitted destination
            // node, while D0..D3 and D4..D7 carry their absolute bounds.
            Append(code, CompareWordD0ToD4); Append(code, BranchNotEqualWord);
            identicalRectangleFallbackBranches.Add(code.Count); Append(code, 0);
            Append(code, CompareWordD1ToD5); Append(code, BranchNotEqualWord);
            identicalRectangleFallbackBranches.Add(code.Count); Append(code, 0);
            Append(code, CompareWordD2ToD6); Append(code, BranchNotEqualWord);
            identicalRectangleFallbackBranches.Add(code.Count); Append(code, 0);
            Append(code, CompareWordD3ToD7); Append(code, BranchNotEqualWord);
            identicalRectangleFallbackBranches.Add(code.Count); Append(code, 0);
            Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
            Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, MoveAddressD0ToA6);
            Append(code, MoveAddressA1ToA5);
            Append(code, MoveAddressA2ToA0);
            Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
            AppendExecFreeMemFromA0PreservingA1(code);
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveQuickZeroD0);
            Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionBounds);
            Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionBounds + 4));
            Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

            Append(code, BranchAlwaysWord);
            canonicalTransferExtensionOffset = code.Count; Append(code, 0);

            var disjointOffset = code.Count;
            PatchBranch(code, disjointLeftExtensionOffset, disjointOffset);
            PatchBranch(code, disjointRightExtensionOffset, disjointOffset);
            PatchBranch(code, disjointAboveExtensionOffset, disjointOffset);
            PatchBranch(code, disjointBelowExtensionOffset, disjointOffset);
        }
        Append(code, MoveAddressA0ToA3);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveAddressA3ToA1);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var orRectRegionExtensionOffset = code.Count; Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        if (canonicalTransferExtensionOffset >= 0)
            PatchBranch(code, canonicalTransferExtensionOffset, canonicalSourceTransferEntryOffset);
        PatchBranch(code, orRectRegionExtensionOffset, orRectRegionEntryOffset);
        // This preflight is only an additional disjoint arm. Every miss must
        // still visit the established source-empty/empty-destination adapter
        // before it reaches the portable Boolean fallback.
        PatchBranch(code, fallbackJumpExtensionOffset, canonicalSourceTransferEntryOffset);
        foreach (var branch in identicalRectangleFallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        if (twoNodeIdentityDispatchExtensionOffset >= 0)
        {
            var twoNodeIdentityRestoreOffset = code.Count;
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, BranchAlwaysWord);
            var twoNodeIdentityJumpExtensionOffset = code.Count;
            Append(code, 0);
            PatchBranch(code, twoNodeIdentityDispatchExtensionOffset, twoNodeIdentityRestoreOffset);
            PatchBranch(code, twoNodeIdentityJumpExtensionOffset, twoNodeIdentityEntryOffset);
        }
        return offset;
    }

    /// <summary>
    /// Transfers a canonical one-node native source into an empty native
    /// destination for OR/XOR. The source Region header is a Rectangle-sized
    /// absolute envelope, so this exact one-node case can tail-enter the
    /// transactional OrRectRegion publisher without copying guest storage.
    /// </summary>
    private static int AppendOrXorRegionRegionCanonicalSourceEmptyDestinationNative(
        List<byte> code,
        int fallbackEntryOffset,
        int emptySourceEntryOffset,
        int orRectRegionEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(18);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Append(code, BranchNotEqualWord);
        var nonEmptySourceExtensionOffset = code.Count; Append(code, 0);
        // Preserve the established empty-source OR/XOR identity.
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var emptySourceExtensionOffset = code.Count; Append(code, 0);

        var nonEmptySourceOffset = code.Count;
        Append(code, MoveAddressD0ToA2);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA0ToA3); Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordA2DisplacementToD6);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);

        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);

        // A3 retains the source while A0/A1 are rearranged to the
        // OrRectRegion ABI: A0 destination, A1 Rectangle (source header).
        Append(code, MoveAddressA0ToA3);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveAddressA3ToA1);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var orRectRegionExtensionOffset = code.Count; Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, nonEmptySourceExtensionOffset, nonEmptySourceOffset);
        PatchBranch(code, emptySourceExtensionOffset, emptySourceEntryOffset);
        PatchBranch(code, orRectRegionExtensionOffset, orRectRegionEntryOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Intersects a canonical one-node native source with a canonical two-node
    /// destination whose two nodes are both contained by the source. The
    /// destination is already the exact intersection, so the native arm is
    /// read-only and returns success without allocation, retirement, or
    /// public writes. Every malformed, escaping, or non-matching shape
    /// delegates to the existing Region boolean entry.
    /// </summary>
    private static int AppendAndRegionRegionCanonicalSourceContainsTwoNodeDestinationNative(
        List<byte> code,
        int delegateEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(64);
        void Delegate(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Delegate(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Delegate(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Delegate(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Delegate(BranchNotEqualWord);
        }

        void EmitAddressAdmission(ushort moveAddressToD0, ushort displacement)
        {
            Append(code, moveAddressToD0); Append(code, displacement);
            Append(code, TestLongD0); Delegate(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Delegate(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
            Delegate(BranchHighWord);
        }

        void EmitRelativeBoundsValidation(
            ushort nodeMinXToD4,
            ushort nodeMinYToD4,
            ushort nodeMaxXToD5,
            ushort nodeMaxYToD5)
        {
            Append(code, nodeMinXToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, nodeMaxXToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Delegate(BranchLessThanWord);
            Append(code, TestWordD4); Delegate(BranchLessThanWord);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, SubWordD0ToD6); Delegate(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Delegate(BranchLessThanWord);

            Append(code, nodeMinYToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, nodeMaxYToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Delegate(BranchLessThanWord);
            Append(code, TestWordD4); Delegate(BranchLessThanWord);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, SubWordD1ToD6); Delegate(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Delegate(BranchLessThanWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);

        // Keep the original source pointer in A3. The source must contain
        // exactly one canonical node, retained in A5 while A2 is reused for
        // allocation-marker and predecessor checks.
        Append(code, MoveAddressA0ToA3);
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        EmitAddressAdmission(
            MoveLongA0DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Delegate(BranchNotEqualWord);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA0ToA2);
        Append(code, AddQuickFourLongA2); Append(code, AddQuickFourLongA2);
        Append(code, MoveLongA2ToD6);
        Append(code, CompareLongD6ToD0); Delegate(BranchNotEqualWord);

        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Delegate(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Delegate(BranchLessThanWord);
        EmitRelativeBoundsValidation(
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD5,
            MoveWordA5DisplacementToD5);

        // Admit and fully validate the canonical two-node destination. A4
        // and A6 retain the two public nodes; A3 still retains the source
        // header used to restore A0 for both fallback and success.
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        EmitAddressAdmission(
            MoveLongA1DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA1ToA2);
        Append(code, AddQuickFourLongA2); Append(code, AddQuickFourLongA2);
        Append(code, MoveLongA2ToD6);
        Append(code, CompareLongD6ToD0); Delegate(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        EmitAddressAdmission(
            MoveLongA4DisplacementToD0,
            (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD0); Delegate(BranchNotEqualWord);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongA4ToD6);
        Append(code, CompareLongD6ToD0); Delegate(BranchNotEqualWord);

        // Validate the destination envelope and both relative rectangles with
        // A0 temporarily pointing at the destination Region.
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Delegate(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Delegate(BranchLessThanWord);
        EmitRelativeBoundsValidation(
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD4,
            MoveWordA4DisplacementToD5,
            MoveWordA4DisplacementToD5);
        EmitRelativeBoundsValidation(
            MoveWordA6DisplacementToD4,
            MoveWordA6DisplacementToD4,
            MoveWordA6DisplacementToD5,
            MoveWordA6DisplacementToD5);

        // Matching public envelopes are required before relative containment
        // is compared. Reload the source envelope into D4..D7 and leave the
        // destination envelope in D0..D3.
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD0); Delegate(BranchNotEqualWord);
        Append(code, CompareWordD5ToD1); Delegate(BranchNotEqualWord);
        Append(code, CompareWordD6ToD2); Delegate(BranchNotEqualWord);
        Append(code, CompareWordD7ToD3); Delegate(BranchNotEqualWord);

        // Source-relative bounds are retained in D4..D7. Each destination
        // node must be contained by that source rectangle. A smaller source
        // minimum or a larger source maximum declines to the existing path.
        Append(code, MoveWordA5DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordA5DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordA5DisplacementToD6); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordA5DisplacementToD7); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        void EmitContainedNode(ushort nodeToA2)
        {
            Append(code, nodeToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA2DisplacementToD1); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA2DisplacementToD2); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA2DisplacementToD3); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD0); Delegate(BranchLessThanWord);
            Append(code, CompareWordD5ToD1); Delegate(BranchLessThanWord);
            Append(code, CompareWordD6ToD2); Delegate(BranchGreaterThanWord);
            Append(code, CompareWordD7ToD3); Delegate(BranchGreaterThanWord);
        }

        EmitContainedNode(MoveAddressA4ToA2);
        EmitContainedNode(MoveAddressA6ToA2);

        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, delegateEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Intersects a canonical one-node native source with a canonical two-node
    /// destination when the inclusive intersection is confined to exactly one
    /// destination node. The selected destination node is rewritten to the
    /// single-node intersection and the other public node is retired; all
    /// other shapes delegate to the normal Region boolean entry.
    /// </summary>
    private static int AppendAndRegionRegionCanonicalSourceTwoNodeDestinationNative(
        List<byte> code,
        int delegateEntryOffset)
    {
        var offset = code.Count;
        var delegateBranches = new List<int>(64);
        void Delegate(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            delegateBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Delegate(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Delegate(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Delegate(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Delegate(BranchNotEqualWord);
        }

        void EmitNodeEnvelope(bool secondNode)
        {
            if (secondNode)
                Append(code, MoveAddressA4ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA2DisplacementToD1); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordA2DisplacementToD2); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA2DisplacementToD3); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD0ToD1); Delegate(BranchLessThanWord);
            Append(code, CompareWordD2ToD3); Delegate(BranchLessThanWord);
            Append(code, TestWordD0); Delegate(BranchLessThanWord);
            Append(code, TestWordD2); Delegate(BranchLessThanWord);
            Append(code, MoveWordD6ToD0); Append(code, SubWordD4ToD0); Delegate(BranchOverflowWord);
            Append(code, CompareWordD1ToD0); Delegate(BranchGreaterThanWord);
            Append(code, MoveWordD7ToD0); Append(code, SubWordD5ToD0); Delegate(BranchOverflowWord);
            Append(code, MoveWordD3ToD2); Append(code, CompareWordD2ToD0); Delegate(BranchGreaterThanWord);
        }

        var sourceContainedByFirstMissBranches = new List<int>(8);
        var sourceContainedBySecondMissBranches = new List<int>(8);
        var firstRewriteSuccessBranches = new List<int>(8);
        var secondRewriteSuccessBranches = new List<int>(8);
        var execMissingBranches = new List<int>(2);

        void EmitSourceIntersectionWithNode(
            ushort candidateToA2,
            bool otherIsA4,
            List<int> missBranches,
            List<int> successBranches)
        {
            void Miss(ushort branchOpcode)
            {
                Append(code, branchOpcode);
                missBranches.Add(code.Count);
                Append(code, 0);
            }

            Append(code, candidateToA2);
            Append(code, MoveLongA2ToD6);
            Append(code, MoveAddressD6ToA5);

            // The source must not touch the other destination node. Check
            // that using the original source rectangle still held in D0..D3;
            // otherwise a source spanning both nodes could be mistaken for a
            // valid single-node reduction when the first partial overlap is
            // examined.
            if (otherIsA4)
                Append(code, MoveAddressA4ToA6);
            else
            {
                Append(code, MoveLongA3ToD6);
                Append(code, MoveAddressD6ToA6);
            }
            Append(code, MoveAddressA6ToA2);
            var sourceDisjointBranches = new List<int>(4);
            void DisjointIf(ushort compareOpcode)
            {
                Append(code, compareOpcode);
                Append(code, BranchGreaterThanWord);
                sourceDisjointBranches.Add(code.Count);
                Append(code, 0);
            }
            Append(code, MoveWordA2DisplacementToD6);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, AddWordD4ToD6);
            DisjointIf(CompareWordD2ToD6);
            Append(code, MoveWordA2DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, AddWordD4ToD6);
            DisjointIf(CompareWordD6ToD0);
            Append(code, MoveWordA2DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA1DisplacementToD4);
            Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, AddWordD4ToD6);
            DisjointIf(CompareWordD3ToD6);
            Append(code, MoveWordA2DisplacementToD6);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, AddWordD4ToD6);
            DisjointIf(CompareWordD6ToD1);
            Append(code, BranchAlwaysWord);
            missBranches.Add(code.Count);
            Append(code, 0);
            var sourceDisjointOffset = code.Count;
            foreach (var branch in sourceDisjointBranches)
                PatchBranch(code, branch, sourceDisjointOffset);
            Append(code, MoveAddressA5ToA2);
            Append(code, MoveWordA1DisplacementToD4);
            Append(code, (ushort)GraphicsLayouts.RectangleMinX);

            // Convert this node's relative bounds to absolute coordinates.
            // D4/D5 still hold the destination Region's minimum X/Y. The
            // envelope admission above proves these additions cannot wrap.
            Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordD6ToD0); Append(code, AddWordD4ToD0);
            Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD6ToD2); Append(code, AddWordD4ToD2);
            Append(code, MoveWordD5ToD4);
            Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordD6ToD1); Append(code, AddWordD4ToD1);
            Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveWordD6ToD3); Append(code, AddWordD4ToD3);

            // Reload the source rectangle in D4..D7 and select the inclusive
            // intersection of the source and this candidate node.
            Append(code, MoveWordA0DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA0DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveWordA0DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);

            Append(code, CompareWordD4ToD0); Append(code, BranchGreaterThanWord);
            var sourceMinXOffset = code.Count; Append(code, 0);
            Append(code, MoveWordD4ToD0);
            var minXReadyOffset = code.Count;
            PatchBranch(code, sourceMinXOffset, minXReadyOffset);

            Append(code, CompareWordD5ToD1); Append(code, BranchGreaterThanWord);
            var sourceMinYOffset = code.Count; Append(code, 0);
            Append(code, MoveWordD5ToD1);
            var minYReadyOffset = code.Count;
            PatchBranch(code, sourceMinYOffset, minYReadyOffset);

            Append(code, CompareWordD2ToD6); Append(code, BranchGreaterThanWord);
            var sourceMaxXOffset = code.Count; Append(code, 0);
            Append(code, MoveWordD6ToD2);
            var maxXReadyOffset = code.Count;
            PatchBranch(code, sourceMaxXOffset, maxXReadyOffset);

            Append(code, CompareWordD3ToD7); Append(code, BranchGreaterThanWord);
            var sourceMaxYOffset = code.Count; Append(code, 0);
            Append(code, MoveWordD7ToD3);
            var maxYReadyOffset = code.Count;
            PatchBranch(code, sourceMaxYOffset, maxYReadyOffset);

            Append(code, CompareWordD0ToD2); Miss(BranchLessThanWord);
            Append(code, CompareWordD1ToD3); Miss(BranchLessThanWord);

            // The source reload above reused D4/D5; restore the destination
            // header minima before translating the other node for the
            // single-result admission test.
            Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);

            // The source-vs-other-node preflight above is the authoritative
            // single-node admission test, so every non-empty intersection
            // reaching this point is a rewrite candidate.
            Append(code, BranchAlwaysWord);
            successBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitRewrite(bool selectedFirst)
        {
            // D0..D3 hold the computed intersection. Save them before the
            // Exec lookup, whose D0 result is volatile, and restore them
            // after the retirement call.
            Append(code, MoveLongD3ToPreDecrementA7);
            Append(code, MoveLongD2ToPreDecrementA7);
            Append(code, MoveLongD1ToPreDecrementA7);
            Append(code, MoveLongD0ToPreDecrementA7);

            // Exec must be resolved before the destination list is retired.
            Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
            Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0);
            Append(code, BranchEqualWord);
            execMissingBranches.Add(code.Count);
            Append(code, 0);
            Append(code, MoveAddressD0ToA6);

            // Keep the computed intersection across the FreeMem call and
            // retain the selected public node in D6 (callee-saved by Exec).
            Append(code, MoveAddressA1ToA5);
            if (selectedFirst)
            {
                Append(code, MoveLongA3ToD6);
                Append(code, MoveAddressA4ToA0);
            }
            else
            {
                Append(code, MoveLongA4ToD6);
                Append(code, MoveAddressA3ToA0);
            }
            Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
            Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
            AppendExecFreeMemFromA0PreservingA1(code);

            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongA7PostIncrementToD1);
            Append(code, MoveLongA7PostIncrementToD2);
            Append(code, MoveLongA7PostIncrementToD3);
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveWordD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
            Append(code, MoveWordD1ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
            Append(code, MoveWordD2ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, MoveWordD3ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
            if (selectedFirst)
                Append(code, MoveAddressD6ToA3);
            else
                Append(code, MoveAddressD6ToA4);
            if (selectedFirst)
                Append(code, MoveAddressA3ToA0);
            else
                Append(code, MoveAddressA4ToA0);
            Append(code, MoveQuickZeroD6);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
            Append(code, MoveAddressA5ToA2);
            Append(code, AddQuickTwoLongA2); Append(code, AddQuickTwoLongA2);
            Append(code, AddQuickTwoLongA2); Append(code, AddQuickTwoLongA2);
            Append(code, MoveLongA2ToD6);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
            Append(code, MoveQuickZeroD6);
            Append(code, MoveLongD6ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
            Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
            Append(code, MoveWordD6ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD6); Delegate(BranchEqualWord);
        Append(code, MoveAddressD6ToA2);
        Append(code, BitTestImmediateD6); Append(code, 0); Delegate(BranchNotEqualWord);
        Append(code, CompareImmediateLongD6); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Delegate(BranchHighWord);
        Append(code, MoveLongA2DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD6); Delegate(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA0ToA4); Append(code, AddQuickFourLongA4); Append(code, AddQuickFourLongA4);
        Append(code, MoveLongD6ToD0); Append(code, MoveLongA4ToD6); Append(code, CompareLongD6ToD0); Delegate(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Delegate(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Delegate(BranchLessThanWord);
        Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordA2DisplacementToD7); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD6ToD7); Delegate(BranchLessThanWord);
        Append(code, TestWordD6); Delegate(BranchLessThanWord);
        Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordA2DisplacementToD7); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD6ToD7); Delegate(BranchLessThanWord);
        Append(code, TestWordD6); Delegate(BranchLessThanWord);
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Delegate(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD7ToD6); Delegate(BranchGreaterThanWord);
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Delegate(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD7ToD6); Delegate(BranchGreaterThanWord);

        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, TestLongD4); Delegate(BranchEqualWord);
        Append(code, MoveAddressD4ToA3);
        Append(code, BitTestImmediateD4); Append(code, 0); Delegate(BranchNotEqualWord);
        Append(code, CompareImmediateLongD4); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Delegate(BranchHighWord);
        Append(code, MoveLongA3DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD6); Delegate(BranchEqualWord);
        Append(code, MoveAddressD6ToA4);
        Append(code, BitTestImmediateD6); Append(code, 0); Delegate(BranchNotEqualWord);
        Append(code, CompareImmediateLongD6); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Delegate(BranchHighWord);
        Append(code, MoveLongA4DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleNext);
        Append(code, TestLongD6); Delegate(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveAddressA1ToA5); Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, MoveLongD6ToD0); Append(code, MoveLongA5ToD6); Append(code, CompareLongD6ToD0); Delegate(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectanglePrevious);
        Append(code, MoveLongD6ToD0); Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0); Delegate(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD6); Delegate(BranchLessThanWord);
        Append(code, CompareWordD5ToD7); Delegate(BranchLessThanWord);
        EmitNodeEnvelope(secondNode: false);
        EmitNodeEnvelope(secondNode: true);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);

        EmitSourceIntersectionWithNode(
            MoveAddressA3ToA2,
            otherIsA4: true,
            sourceContainedByFirstMissBranches,
            firstRewriteSuccessBranches);
        var secondCandidateOffset = code.Count;
        // The first candidate's miss path can leave D4/D5 holding the source
        // minima. Restore the destination header before translating the
        // second node into absolute coordinates.
        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        foreach (var branch in sourceContainedByFirstMissBranches)
            PatchBranch(code, branch, secondCandidateOffset);
        EmitSourceIntersectionWithNode(
            MoveAddressA4ToA2,
            otherIsA4: false,
            sourceContainedBySecondMissBranches,
            secondRewriteSuccessBranches);

        var firstRewriteOffset = code.Count;
        foreach (var branch in firstRewriteSuccessBranches)
            PatchBranch(code, branch, firstRewriteOffset);
        EmitRewrite(selectedFirst: true);
        var secondRewriteOffset = code.Count;
        foreach (var branch in secondRewriteSuccessBranches)
            PatchBranch(code, branch, secondRewriteOffset);
        EmitRewrite(selectedFirst: false);

        var delegateRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var delegateJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, delegateJumpExtensionOffset, delegateEntryOffset);
        var execMissingRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD1);
        Append(code, MoveLongA7PostIncrementToD2);
        Append(code, MoveLongA7PostIncrementToD3);
        Append(code, BranchAlwaysWord);
        var execMissingJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, execMissingJumpExtensionOffset, delegateRestoreOffset);
        foreach (var branch in execMissingBranches)
            PatchBranch(code, branch, execMissingRestoreOffset);
        foreach (var branch in sourceContainedBySecondMissBranches)
            PatchBranch(code, branch, delegateRestoreOffset);
        foreach (var branch in delegateBranches)
            PatchBranch(code, branch, delegateRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Intersects two canonical one-node native Regions when the source
    /// completely contains the destination. The destination is already the
    /// exact intersection, so native success is allocation- and write-free.
    /// </summary>
    private static int AppendAndRegionRegionCanonicalSourceContainsDestinationNative(
        List<byte> code,
        int fallbackEntryOffset,
        int emptySourceEntryOffset,
        int twoNodeSourceEmptyEntryOffset,
        int twoNodeSourceTwoNodeDestinationEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(36);
        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD6); Decline(BranchEqualWord);
        Append(code, MoveAddressD6ToA2);
        Append(code, BitTestImmediateD6); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD6); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var twoNodeDispatchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA0ToA3); Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordA2DisplacementToD6);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);

        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD4); Decline(BranchEqualWord);
        Append(code, MoveAddressD4ToA2);
        Append(code, BitTestImmediateD4); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD4); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD6); Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA1ToA3); Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD0); Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD5); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD4ToD6); Decline(BranchLessThanWord);
        Append(code, CompareWordD5ToD7); Decline(BranchLessThanWord);
        Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordA2DisplacementToD6);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordD6ToD0); Append(code, SubWordD4ToD0); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD7ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordD6ToD0); Append(code, SubWordD5ToD0); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD7ToD0); Decline(BranchNotEqualWord);

        // Source contains destination iff every destination lower edge is no
        // lower and every upper edge is no higher than the source's.
        Append(code, MoveWordA0DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA0DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA0DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA0DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD7); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD4); Append(code, BranchLessThanWord);
        var sourceDoesNotContainMinXExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD1ToD5); Append(code, BranchLessThanWord);
        var sourceDoesNotContainMinYExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD2ToD6); Append(code, BranchGreaterThanWord);
        var sourceDoesNotContainMaxXExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD3ToD7); Append(code, BranchGreaterThanWord);
        var sourceDoesNotContainMaxYExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var sourceContainedByDestinationOffset = code.Count;
        PatchBranch(code, sourceDoesNotContainMinXExtensionOffset, sourceContainedByDestinationOffset);
        PatchBranch(code, sourceDoesNotContainMinYExtensionOffset, sourceContainedByDestinationOffset);
        PatchBranch(code, sourceDoesNotContainMaxXExtensionOffset, sourceContainedByDestinationOffset);
        PatchBranch(code, sourceDoesNotContainMaxYExtensionOffset, sourceContainedByDestinationOffset);
        // The complementary identity is an in-place single-node rewrite:
        // destination contains source, so their intersection is source.
        Append(code, CompareWordD4ToD0); Append(code, BranchLessThanWord);
        var destinationDoesNotContainMinXExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD5ToD1); Append(code, BranchLessThanWord);
        var destinationDoesNotContainMinYExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD6ToD2); Append(code, BranchGreaterThanWord);
        var destinationDoesNotContainMaxXExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD7ToD3); Append(code, BranchGreaterThanWord);
        var destinationDoesNotContainMaxYExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveWordD0ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordD1ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordD2ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordD3ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var partialIntersectionOffset = code.Count;
        PatchBranch(code, destinationDoesNotContainMinXExtensionOffset, partialIntersectionOffset);
        PatchBranch(code, destinationDoesNotContainMinYExtensionOffset, partialIntersectionOffset);
        PatchBranch(code, destinationDoesNotContainMaxXExtensionOffset, partialIntersectionOffset);
        PatchBranch(code, destinationDoesNotContainMaxYExtensionOffset, partialIntersectionOffset);

        // D0/D1 begin as the source minimum and D2/D3 as its maximum;
        // D4/D5/D6/D7 retain the destination rectangle. Select max(minima)
        // and min(maxima), declining a non-overlapping intersection.
        Append(code, CompareWordD0ToD4); Append(code, BranchGreaterThanWord);
        var takeDestinationMinXExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var minimumXReadyExtensionOffset = code.Count; Append(code, 0);
        var takeDestinationMinXOffset = code.Count;
        PatchBranch(code, takeDestinationMinXExtensionOffset, takeDestinationMinXOffset);
        Append(code, MoveWordD4ToD0);
        var minimumXReadyOffset = code.Count;
        PatchBranch(code, minimumXReadyExtensionOffset, minimumXReadyOffset);
        Append(code, CompareWordD1ToD5); Append(code, BranchGreaterThanWord);
        var takeDestinationMinYExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var minimumYReadyExtensionOffset = code.Count; Append(code, 0);
        var takeDestinationMinYOffset = code.Count;
        PatchBranch(code, takeDestinationMinYExtensionOffset, takeDestinationMinYOffset);
        Append(code, MoveWordD5ToD1);
        var minimumYReadyOffset = code.Count;
        PatchBranch(code, minimumYReadyExtensionOffset, minimumYReadyOffset);
        Append(code, CompareWordD6ToD2); Append(code, BranchGreaterThanWord);
        var takeDestinationMaxXExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var maximumXReadyExtensionOffset = code.Count; Append(code, 0);
        var takeDestinationMaxXOffset = code.Count;
        PatchBranch(code, takeDestinationMaxXExtensionOffset, takeDestinationMaxXOffset);
        Append(code, MoveWordD6ToD2);
        var maximumXReadyOffset = code.Count;
        PatchBranch(code, maximumXReadyExtensionOffset, maximumXReadyOffset);
        Append(code, CompareWordD7ToD3); Append(code, BranchGreaterThanWord);
        var takeDestinationMaxYExtensionOffset = code.Count; Append(code, 0);
        Append(code, BranchAlwaysWord);
        var maximumYReadyExtensionOffset = code.Count; Append(code, 0);
        var takeDestinationMaxYOffset = code.Count;
        PatchBranch(code, takeDestinationMaxYExtensionOffset, takeDestinationMaxYOffset);
        Append(code, MoveWordD7ToD3);
        var maximumYReadyOffset = code.Count;
        PatchBranch(code, maximumYReadyExtensionOffset, maximumYReadyOffset);
        Append(code, CompareWordD0ToD2); Append(code, BranchLessThanWord);
        var disjointIntersectionXExtensionOffset = code.Count; Append(code, 0);
        Append(code, CompareWordD1ToD3); Append(code, BranchLessThanWord);
        var disjointIntersectionYExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveWordD0ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordD1ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordD2ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordD3ToA1Displacement); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6);
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        // A nonempty canonical source/destination pair whose inclusive
        // rectangle intersection is empty has an empty destination result.
        // The chain was fully admitted above, so retire its sole public node
        // only after resolving Exec, then publish the empty Region header.
        var disjointIntersectionOffset = code.Count;
        PatchBranch(code, disjointIntersectionXExtensionOffset, disjointIntersectionOffset);
        PatchBranch(code, disjointIntersectionYExtensionOffset, disjointIntersectionOffset);
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveAddressA1ToA5);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionBounds);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionBounds + 4));
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, emptySourceEntryOffset);
        var twoNodeDispatchRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var twoNodeDispatchJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, twoNodeDispatchExtensionOffset, twoNodeDispatchRestoreOffset);
        PatchBranch(code, twoNodeDispatchJumpExtensionOffset, twoNodeSourceTwoNodeDestinationEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Intersects an empty native source with a canonical one- or two-node
    /// native destination. It clears and retires every admitted destination
    /// node, then tail enters the existing destination-empty AND body for all
    /// other shapes.
    /// </summary>
    private static int AppendAndRegionRegionEmptySourceCanonicalDestinationNative(
        List<byte> code,
        int fallbackEntryOffset,
        int destinationEmptyEntryOffset,
        List<int>? threeNodeDestinationBranches = null)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(42);
        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Append(code, BranchNotEqualWord);
        var nonEmptySourceExtensionOffset = code.Count; Append(code, 0);

        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Append(code, BranchNotEqualWord);
        var nonEmptyDestinationExtensionOffset = code.Count; Append(code, 0);
        // Both Regions are empty. Restore the caller frame and use the
        // established AND body so its exact admission remains authoritative.
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var destinationEmptyAndExtensionOffset = code.Count; Append(code, 0);

        var nonEmptyDestinationOffset = code.Count;
        Append(code, MoveAddressD0ToA2);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var oneNodeDestinationExtensionOffset = code.Count; Append(code, 0);

        // A canonical two-node destination is also an empty-source identity:
        // the intersection is empty, so both public nodes can be retired in
        // one ownership-safe transaction. Validate the complete chain and
        // both relative envelopes before resolving Exec or mutating memory.
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0);
        if (threeNodeDestinationBranches is not null)
        {
            Append(code, BranchNotEqualWord);
            threeNodeDestinationBranches.Add(code.Count);
            Append(code, 0);
        }
        else
        {
            Decline(BranchNotEqualWord);
        }
        Append(code, MoveLongA3ToD0);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveAddressA2ToA4); // retain the first node across the second-node checks

        // First node must still point back to the Region header sentinel.
        Append(code, MoveAddressA1ToA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, MoveLongA5ToD6);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        // The second node terminates the chain and points back to the first.
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA2ToD6);
        Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);

        // Load the destination envelope once; both nodes must fit it.
        Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);

        void EmitTwoNodeBounds(bool secondNode)
        {
            if (secondNode)
                Append(code, MoveAddressA3ToA2);
            Append(code, MoveWordA2DisplacementToD4); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA2DisplacementToD5); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, TestWordD5); Decline(BranchLessThanWord);
            Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, MoveWordA2DisplacementToD7); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD7ToD6); Decline(BranchLessThanWord);
            Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, MoveWordA2DisplacementToD7); Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD7ToD6); Decline(BranchLessThanWord);
        }

        EmitTwoNodeBounds(secondNode: false);
        EmitTwoNodeBounds(secondNode: true);

        // Resolve Exec before either public node is retired. Keep the first
        // node on the caller stack while the second node's FreeMem call runs;
        // the helper restores the saved caller D0 frame after both frees.
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveAddressA1ToA5);
        Append(code, MoveAddressA4ToA2);
        Append(code, MoveLongA2ToPreDecrementA7);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionBounds);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionBounds + 4));
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var oneNodeDestinationOffset = code.Count;
        PatchBranch(code, oneNodeDestinationExtensionOffset, oneNodeDestinationOffset);
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA1ToA3); Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordA2DisplacementToD6);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);

        // Resolve Exec before the node is retired. A missing Exec base must
        // decline with the exact source/destination bytes untouched.
        Append(code, MoveImmediateAddressToA6); Append(code, 0); Append(code, 4);
        Append(code, MoveLongA6IndirectToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveAddressA1ToA5);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongImmediateD0); Append(code, 0); Append(code, (ushort)GraphicsLayouts.RegionRectangleSize);
        Append(code, MoveLongImmediateD1); Append(code, 0); Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionBounds);
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)(GraphicsLayouts.RegionBounds + 4));
        Append(code, MoveLongD0ToA0Displacement); Append(code, (ushort)GraphicsLayouts.RegionRectangle);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var nonEmptySourceOffset = code.Count;
        PatchBranch(code, nonEmptySourceExtensionOffset, nonEmptySourceOffset);
        // Other source shapes retain the previously emitted AND implementation.
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var nonEmptySourceAndExtensionOffset = code.Count; Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, destinationEmptyAndExtensionOffset, destinationEmptyEntryOffset);
        PatchBranch(code, nonEmptySourceAndExtensionOffset, destinationEmptyEntryOffset);
        PatchBranch(code, nonEmptyDestinationExtensionOffset, nonEmptyDestinationOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Continues the empty-source OR/XOR admission for a canonical three-node
    /// destination. The caller has already proved an owned empty source, an
    /// owned destination, and a non-null second successor; A2 is the first
    /// node, A3 is the second node, and D0 is the third-node address. This
    /// bounded arm only reads guest
    /// memory, restores the caller's saved D0 frame, and leaves the list
    /// untouched on success or decline.
    /// </summary>
    private static int AppendRegionRegionEmptySourceCanonicalThreeNodeDestinationNative(
        List<byte> code,
        int fallbackEntryOffset,
        List<int>? fourNodeDestinationBranches = null)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(32);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitRelativeBoundsValidation(ushort nodeToA2)
        {
            if (nodeToA2 != 0)
                Append(code, nodeToA2);
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA1DisplacementToD6);
            Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA1DisplacementToD6);
            Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        // The preceding body leaves the first node in A2, the second node in
        // A3, and the third-node address in D0. Admit that final node before
        // checking its terminal link.
        Append(code, MoveAddressA2ToA6);
        Append(code, BitTestImmediateD0); Append(code, 0);
        Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveAddressD0ToA4);

        // A non-terminal third node may continue into the bounded four-node
        // read-only proof.  The continuation receives D0 as the fourth-node
        // address while A4 remains the third node and A6 remains the first.
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0);
        if (fourNodeDestinationBranches is not null)
        {
            Append(code, BranchNotEqualWord);
            fourNodeDestinationBranches.Add(code.Count);
            Append(code, 0);
        }
        else
        {
            Decline(BranchNotEqualWord);
        }

        // The third node is terminal and links back to the second node.
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        // The first two back-links complete the public circular topology.
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA1ToA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, MoveLongA5ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        // Public envelope admission precedes all relative rectangle reads.
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);

        EmitRelativeBoundsValidation(0);
        EmitRelativeBoundsValidation(MoveAddressA3ToA2);
        EmitRelativeBoundsValidation(MoveAddressA4ToA2);

        // Canonical Region lists are vertically ordered with a real gap
        // between successive rectangles.  Keep the same signed comparison
        // used by the two-node identity arm.
        Append(code, MoveAddressA6ToA2);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA3DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA4DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);

        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Continues the empty-source OR/XOR admission for a canonical four-node
    /// destination.  The caller has already proved an owned empty source and
    /// destination, and has admitted the first three node addresses.  Entry
    /// state is A2 = first, A3 = second, A4 = third, A6 = first, and D0 =
    /// fourth.  This arm is deliberately read-only and falls back with the
    /// caller's original D0 restored on every failed proof.
    /// </summary>
    private static int AppendRegionRegionEmptySourceCanonicalFourNodeDestinationNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(40);
        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitRelativeBoundsValidation(ushort moveNodeToA2)
        {
            if (moveNodeToA2 != 0)
                Append(code, moveNodeToA2);
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA1DisplacementToD6);
            Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA1DisplacementToD6);
            Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        // Admit the fourth node address before dereferencing it.
        Append(code, BitTestImmediateD0); Append(code, 0);
        Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongA6ToD7);
        Append(code, MoveAddressA5ToA6);

        // The fourth node terminates the chain and points back to the third.
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);
        Append(code, MoveLongA5DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA4ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        // The third node must actually point at this fourth node.
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, MoveLongA6ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        // Validate all predecessor links, including the public sentinel.
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA1ToA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, AddQuickTwoLongA5); Append(code, AddQuickTwoLongA5);
        Append(code, MoveLongA5ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        // Public envelope admission precedes all relative rectangle reads.
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3);
        Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);

        EmitRelativeBoundsValidation(0);
        EmitRelativeBoundsValidation(MoveAddressA3ToA2);
        EmitRelativeBoundsValidation(MoveAddressA4ToA2);
        EmitRelativeBoundsValidation(MoveAddressA6ToA2);

        // Canonical lists are strictly vertically ordered with real gaps.
        Append(code, MoveAddressD7ToA2);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA3DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA4DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);
        Append(code, MoveWordA4DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA6DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);

        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// OR and XOR both leave a canonical native destination unchanged when
    /// their native source is empty. The body admits the exact identity and
    /// leaves every nonempty source with its operation-specific fallback.
    /// </summary>
    private static int AppendRegionRegionEmptySourceCanonicalDestinationNative(
        List<byte> code,
        int fallbackEntryOffset,
        int threeNodeDestinationEntryOffset = -1)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(18);
        var threeNodeDestinationBranches = new List<int>(2);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitOwnedRegionAdmission(ushort moveAddressToD0)
        {
            Append(code, moveAddressToD0); Append(code, TestLongD0); Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF4);
            Decline(BranchHighWord);
            Append(code, SubQuickFourLongD0); Append(code, MoveAddressD0ToA2);
            Append(code, MoveWordA2DisplacementToD0); Append(code, 0);
            Append(code, CompareImmediateWordD0); Append(code, GraphicsLayouts.NativeRegionMarker);
            Decline(BranchNotEqualWord);
        }

        Append(code, MoveLongD0ToPreDecrementA7);
        // A0 is the empty source. Its header alone proves the identity.
        EmitOwnedRegionAdmission(MoveLongA0ToD0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Decline(BranchNotEqualWord);

        // A1 is either an empty destination or a complete canonical native
        // chain.  The empty-source identity is read-only for both OR and
        // XOR, so a validated two-node destination can return directly.
        EmitOwnedRegionAdmission(MoveLongA1ToD0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, TestLongD0); Append(code, BranchNotEqualWord);
        var nonEmptyDestinationExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var nonEmptyDestinationOffset = code.Count;
        Append(code, MoveAddressD0ToA2);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0); Append(code, BranchNotEqualWord);
        var twoNodeDestinationExtensionOffset = code.Count; Append(code, 0);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA1ToA3); Append(code, AddQuickFourLongA3); Append(code, AddQuickFourLongA3);
        Append(code, MoveLongA3ToD6); Append(code, CompareLongD6ToD0); Decline(BranchNotEqualWord);
        Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);
        Append(code, MoveWordA2DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordA2DisplacementToD6);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, TestWordD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD2ToD6); Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);
        Append(code, MoveWordD3ToD6); Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
        Append(code, MoveWordA2DisplacementToD7);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD7ToD6); Decline(BranchNotEqualWord);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var twoNodeDestinationOffset = code.Count;
        // The first node was already admitted into A2 and D0 contains the
        // second-node address.  Keep A0 untouched so every decline can still
        // enter the shared portable fallback with the original arguments.
        Append(code, MoveAddressA2ToA4);
        Append(code, MoveAddressD0ToA3);
        Append(code, BitTestImmediateD0); Append(code, 0); Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0); Append(code, 0xFFFF); Append(code, 0xFFF0);
        Decline(BranchHighWord);
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, TestLongD0);
        if (threeNodeDestinationEntryOffset >= 0)
        {
            Append(code, BranchNotEqualWord);
            threeNodeDestinationBranches.Add(code.Count);
            Append(code, 0);
        }
        else
        {
            Decline(BranchNotEqualWord);
        }
        Append(code, MoveLongA3DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA1ToA2);
        Append(code, AddQuickFourLongA2); Append(code, AddQuickFourLongA2);
        Append(code, MoveLongA2ToD6); Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        // Validate the public envelope before proving each relative node is
        // representable inside it.  The node checks mirror the native Region
        // canonicalizer: non-negative minima, ordered endpoints, and maxima
        // no greater than the translated envelope extents.
        Append(code, MoveWordA1DisplacementToD0); Append(code, (ushort)GraphicsLayouts.RectangleMinX);
        Append(code, MoveWordA1DisplacementToD1); Append(code, (ushort)GraphicsLayouts.RectangleMinY);
        Append(code, MoveWordA1DisplacementToD2); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
        Append(code, MoveWordA1DisplacementToD3); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
        Append(code, CompareWordD0ToD2); Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3); Decline(BranchLessThanWord);

        void EmitRelativeBoundsValidation()
        {
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)GraphicsLayouts.RegionRectangleBounds);
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxX);
            Append(code, SubWordD0ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);

            Append(code, MoveWordA2DisplacementToD4);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
            Append(code, MoveWordA2DisplacementToD5);
            Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
            Append(code, CompareWordD4ToD5); Decline(BranchLessThanWord);
            Append(code, TestWordD4); Decline(BranchLessThanWord);
            Append(code, MoveWordA1DisplacementToD6); Append(code, (ushort)GraphicsLayouts.RectangleMaxY);
            Append(code, SubWordD1ToD6); Decline(BranchOverflowWord);
            Append(code, CompareWordD5ToD6); Decline(BranchLessThanWord);
        }

        Append(code, MoveAddressA4ToA2);
        EmitRelativeBoundsValidation();
        Append(code, MoveAddressA3ToA2);
        EmitRelativeBoundsValidation();
        Append(code, MoveWordA4DisplacementToD4);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY));
        Append(code, MoveWordA3DisplacementToD5);
        Append(code, (ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY));
        Append(code, CompareWordD4ToD5); Decline(BranchLessOrEqualWord);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0); Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count; Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, nonEmptyDestinationExtensionOffset, nonEmptyDestinationOffset);
        PatchBranch(code, twoNodeDestinationExtensionOffset, twoNodeDestinationOffset);
        foreach (var branch in threeNodeDestinationBranches)
            PatchBranch(code, branch, threeNodeDestinationEntryOffset);
        foreach (var branch in fallbackBranches)
            PatchBranch(code, branch, fallbackRestoreOffset);
        return offset;
    }

    /// <summary>
    /// Intersects a native-owned canonical Region with one Rectangle without
    /// allocation.  RegionRectangle bounds are relative to Region.Bounds, so
    /// this deliberately performs three bounded passes: validate and prove
    /// every source rectangle translates, calculate the result bounds and
    /// prove its relative form, then compact and publish.  No public byte is
    /// changed before both preflight passes have succeeded.
    /// </summary>
    private static int AppendAndRectRegionNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(40);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            fallbackBranches.Add(code.Count);
            Append(code, 0);
        }

        void EmitClipMinimum(ushort compareInputToOutput, ushort moveInputToOutput, ushort rectangleOffset)
        {
            Append(code, MoveWordA1DisplacementToD4);
            Append(code, rectangleOffset);
            Append(code, compareInputToOutput); // output - input
            Append(code, BranchGreaterOrEqualWord);
            var keepOutputExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, moveInputToOutput);
            PatchBranch(code, keepOutputExtensionOffset, code.Count);
        }

        void EmitClipMaximum(ushort compareInputToOutput, ushort moveInputToOutput, ushort rectangleOffset)
        {
            Append(code, MoveWordA1DisplacementToD4);
            Append(code, rectangleOffset);
            Append(code, compareInputToOutput); // output - input
            Append(code, BranchLessOrEqualWord);
            var keepOutputExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, moveInputToOutput);
            PatchBranch(code, keepOutputExtensionOffset, code.Count);
        }

        // D0..D3 receive absolute minX/minY/maxX/maxY.  D4 is scratch; the
        // first two Region.Bounds words translate all RegionRectangle fields.
        void EmitComputeClippedCurrentNode()
        {
            Append(code, MoveWordA2DisplacementToD0);
            Append(code, checked((ushort)GraphicsLayouts.RegionRectangleBounds));
            Append(code, MoveWordA0DisplacementToD4);
            Append(code, checked((ushort)GraphicsLayouts.RectangleMinX));
            Append(code, AddWordD4ToD0);
            EmitClipMinimum(
                CompareWordD4ToD0,
                MoveWordD4ToD0,
                checked((ushort)GraphicsLayouts.RectangleMinX));

            Append(code, MoveWordA2DisplacementToD1);
            Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY)));
            Append(code, MoveWordA0DisplacementToD4);
            Append(code, checked((ushort)GraphicsLayouts.RectangleMinY));
            Append(code, AddWordD4ToD1);
            EmitClipMinimum(
                CompareWordD4ToD1,
                MoveWordD4ToD1,
                checked((ushort)GraphicsLayouts.RectangleMinY));

            Append(code, MoveWordA2DisplacementToD2);
            Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX)));
            Append(code, MoveWordA0DisplacementToD4);
            Append(code, checked((ushort)GraphicsLayouts.RectangleMinX));
            Append(code, AddWordD4ToD2);
            EmitClipMaximum(
                CompareWordD4ToD2,
                MoveWordD4ToD2,
                checked((ushort)GraphicsLayouts.RectangleMaxX));

            Append(code, MoveWordA2DisplacementToD3);
            Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY)));
            Append(code, MoveWordA0DisplacementToD4);
            Append(code, checked((ushort)GraphicsLayouts.RectangleMinY));
            Append(code, AddWordD4ToD3);
            EmitClipMaximum(
                CompareWordD4ToD3,
                MoveWordD4ToD3,
                checked((ushort)GraphicsLayouts.RectangleMaxY));
        }

        void EmitUpdateMinimum(ushort compareOutputToGlobal, ushort writeOutput, ushort globalOffset)
        {
            Append(code, MoveWordA6DisplacementToD4);
            Append(code, globalOffset);
            Append(code, compareOutputToGlobal); // global - output
            Append(code, BranchGreaterOrEqualWord);
            var setExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BranchAlwaysWord);
            var doneExtensionOffset = code.Count;
            Append(code, 0);
            var setOffset = code.Count;
            Append(code, writeOutput);
            Append(code, globalOffset);
            var doneOffset = code.Count;
            PatchBranch(code, setExtensionOffset, setOffset);
            PatchBranch(code, doneExtensionOffset, doneOffset);
        }

        void EmitUpdateMaximum(ushort compareOutputToGlobal, ushort writeOutput, ushort globalOffset)
        {
            Append(code, MoveWordA6DisplacementToD4);
            Append(code, globalOffset);
            Append(code, compareOutputToGlobal); // global - output
            Append(code, BranchLessThanWord);
            var setExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BranchAlwaysWord);
            var doneExtensionOffset = code.Count;
            Append(code, 0);
            var setOffset = code.Count;
            Append(code, writeOutput);
            Append(code, globalOffset);
            var doneOffset = code.Count;
            PatchBranch(code, setExtensionOffset, setOffset);
            PatchBranch(code, doneExtensionOffset, doneOffset);
        }

        // Preserve D0 for every decline and reserve four words for the
        // calculated result bounds.  A6 is a temporary stack-frame anchor
        // until the final Exec FreeMem pass.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, LoadEffectiveAddressA7Displacement);
        Append(code, unchecked((ushort)-8));
        Append(code, MoveAddressA7ToA6);

        // A0 is Region, A1 is Rectangle.  The envelope checks are explicit
        // so neither the private marker nor a final field can wrap through
        // logical address zero on a raw 68000 resident invocation.
        Append(code, MoveLongA0ToD0);
        Append(code, TestLongD0);
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 4);
        Decline(BranchCarryWord);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // complete Region envelope
        Decline(BranchHighWord);

        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8); // complete Rectangle envelope
        Decline(BranchHighWord);

        // Native ownership is private-prefix based.  Foreign or legacy
        // Regions remain with the portable/provider dispatcher.
        Append(code, MoveLongA0ToD5);
        Append(code, SubQuickFourLongD5);
        Append(code, MoveAddressD5ToA3);
        Append(code, MoveWordA3DisplacementToD0);
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, GraphicsLayouts.NativeRegionMarker);
        Decline(BranchNotEqualWord);

        // The source rectangle must be valid.  The portable implementation
        // owns the historical evil-rectangle clear convention, so this path
        // declines before touching a Region when min exceeds max.
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMinX));
        Append(code, MoveWordA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMaxX));
        Append(code, CompareWordD4ToD5);
        Decline(BranchLessThanWord);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD4ToD5);
        Decline(BranchLessThanWord);

        // Keep the Region bounds in D0..D3 for the first translation pass.
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMinX));
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMaxY));
        Append(code, CompareWordD0ToD2);
        Decline(BranchLessThanWord);
        Append(code, CompareWordD1ToD3);
        Decline(BranchLessThanWord);

        // Verify the canonical predecessor links, each full node envelope,
        // and that relative bounds translate without signed-word overflow.
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, MoveAddressD4ToA2);
        Append(code, MoveAddressA0ToA3);
        Append(code, AddQuickFourLongA3);
        Append(code, AddQuickFourLongA3);
        Append(code, MoveLongImmediateD6);
        Append(code, 0);
        Append(code, 0x0FFF);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var sourceValidatedEmptyExtensionOffset = code.Count;
        Append(code, 0);

        var sourceValidateLoopOffset = code.Count;
        Append(code, MoveLongA2ToD4);
        Append(code, TestLongD4);
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFF0); // complete RegionRectangle envelope
        Decline(BranchHighWord);
        Append(code, MoveLongA3ToD5);
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, CompareLongD5ToD4);
        Decline(BranchNotEqualWord);

        Append(code, MoveWordA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleBounds));
        Append(code, MoveWordA2DisplacementToD5);
        Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX)));
        Append(code, CompareWordD4ToD5);
        Decline(BranchLessThanWord);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY)));
        Append(code, MoveWordA2DisplacementToD5);
        Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY)));
        Append(code, CompareWordD4ToD5);
        Decline(BranchLessThanWord);

        // All relative endpoints must remain signed words after adding the
        // source Region's origin.  This matches TryTranslateFromRegionBounds.
        foreach (var pair in new[]
                 {
                     (GraphicsLayouts.RectangleMinX, AddWordD0ToD4),
                     (GraphicsLayouts.RectangleMaxX, AddWordD0ToD4),
                     (GraphicsLayouts.RectangleMinY, AddWordD1ToD4),
                     (GraphicsLayouts.RectangleMaxY, AddWordD1ToD4)
                 })
        {
            Append(code, MoveWordA2DisplacementToD4);
            Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + pair.Item1)));
            Append(code, pair.Item2);
            Decline(BranchOverflowWord);
        }

        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, MoveAddressA2ToA3);
        Append(code, MoveAddressD4ToA2);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var sourceValidatedExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, DecrementBranchD6);
        var sourceValidateLoopExtensionOffset = code.Count;
        Append(code, 0);
        Decline(BranchAlwaysWord);
        var sourceValidatedOffset = code.Count;
        PatchBranch(code, sourceValidatedEmptyExtensionOffset, sourceValidatedOffset);
        PatchBranch(code, sourceValidatedExtensionOffset, sourceValidatedOffset);
        PatchBranch(code, sourceValidateLoopExtensionOffset, sourceValidateLoopOffset);

        // FreeMem is needed only after publication, but prove the Exec
        // boundary now so every later decline still has an untouched Region.
        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Decline(BranchEqualWord);

        // Pass two: calculate absolute result bounds and survivor count.
        Append(code, MoveAddressA7ToA6);
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, MoveAddressD4ToA2);
        Append(code, MoveAddressA2ToA3); // retains the first stale node if empty
        Append(code, MoveQuickZeroD7);
        Append(code, MoveLongImmediateD6);
        Append(code, 0);
        Append(code, 0x0FFF);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var noResultExtensionOffset = code.Count;
        Append(code, 0);

        var calculateLoopOffset = code.Count;
        EmitComputeClippedCurrentNode();
        Append(code, CompareWordD0ToD2);
        Append(code, BranchLessThanWord);
        var calculateInvalidXExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareWordD1ToD3);
        Append(code, BranchLessThanWord);
        var calculateInvalidYExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, TestLongD7);
        Append(code, BranchNotEqualWord);
        var calculateUpdateExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveWordD0ToA6Displacement);
        Append(code, 0);
        Append(code, MoveWordD1ToA6Displacement);
        Append(code, 2);
        Append(code, MoveWordD2ToA6Displacement);
        Append(code, 4);
        Append(code, MoveWordD3ToA6Displacement);
        Append(code, 6);
        Append(code, AddQuickOneLongD7);
        Append(code, BranchAlwaysWord);
        var calculateAdvanceAfterFirstExtensionOffset = code.Count;
        Append(code, 0);
        var calculateUpdateOffset = code.Count;
        EmitUpdateMinimum(CompareWordD0ToD4, MoveWordD0ToA6Displacement, 0);
        EmitUpdateMinimum(CompareWordD1ToD4, MoveWordD1ToA6Displacement, 2);
        EmitUpdateMaximum(CompareWordD2ToD4, MoveWordD2ToA6Displacement, 4);
        EmitUpdateMaximum(CompareWordD3ToD4, MoveWordD3ToA6Displacement, 6);
        Append(code, AddQuickOneLongD7);
        var calculateAdvanceOffset = code.Count;
        PatchBranch(code, calculateUpdateExtensionOffset, calculateUpdateOffset);
        PatchBranch(code, calculateInvalidXExtensionOffset, calculateAdvanceOffset);
        PatchBranch(code, calculateInvalidYExtensionOffset, calculateAdvanceOffset);
        PatchBranch(code, calculateAdvanceAfterFirstExtensionOffset, calculateAdvanceOffset);
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, MoveAddressD4ToA2);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var calculateCompleteExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, DecrementBranchD6);
        var calculateLoopExtensionOffset = code.Count;
        Append(code, 0);
        Decline(BranchAlwaysWord);
        var calculateCompleteOffset = code.Count;
        PatchBranch(code, calculateCompleteExtensionOffset, calculateCompleteOffset);
        PatchBranch(code, calculateLoopExtensionOffset, calculateLoopOffset);
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var calculatedNoResultExtensionOffset = code.Count;
        Append(code, 0);

        // A third read-only pass proves translating the absolute results to
        // the newly calculated origin remains representable as four words.
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, MoveAddressD4ToA2);
        Append(code, MoveLongImmediateD6);
        Append(code, 0);
        Append(code, 0x0FFF);
        var relativeValidateLoopOffset = code.Count;
        EmitComputeClippedCurrentNode();
        Append(code, CompareWordD0ToD2);
        Append(code, BranchLessThanWord);
        var relativeInvalidXExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareWordD1ToD3);
        Append(code, BranchLessThanWord);
        var relativeInvalidYExtensionOffset = code.Count;
        Append(code, 0);
        foreach (var pair in new[]
                 {
                     (0, SubWordD4ToD0),
                     (2, SubWordD4ToD1),
                     (0, SubWordD4ToD2),
                     (2, SubWordD4ToD3)
                 })
        {
            Append(code, MoveWordA6DisplacementToD4);
            Append(code, checked((ushort)pair.Item1));
            Append(code, pair.Item2);
            Decline(BranchOverflowWord);
        }

        var relativeAdvanceOffset = code.Count;
        PatchBranch(code, relativeInvalidXExtensionOffset, relativeAdvanceOffset);
        PatchBranch(code, relativeInvalidYExtensionOffset, relativeAdvanceOffset);
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, MoveAddressD4ToA2);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var relativeCompleteExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, DecrementBranchD6);
        var relativeLoopExtensionOffset = code.Count;
        Append(code, 0);
        Decline(BranchAlwaysWord);
        var relativeCompleteOffset = code.Count;
        PatchBranch(code, relativeCompleteExtensionOffset, relativeCompleteOffset);
        PatchBranch(code, relativeLoopExtensionOffset, relativeValidateLoopOffset);

        // Pass three is now safe to compact survivors into the original
        // prefix.  Reading both source and target successors before writing
        // preserves an interior surviving node after earlier removals.
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));
        Append(code, MoveAddressD4ToA2);
        Append(code, MoveAddressD4ToA3);
        Append(code, MoveAddressA0ToA4);
        Append(code, AddQuickFourLongA4);
        Append(code, AddQuickFourLongA4);
        Append(code, MoveLongImmediateD6);
        Append(code, 0);
        Append(code, 0x0FFF);
        var publishLoopOffset = code.Count;
        EmitComputeClippedCurrentNode();
        Append(code, CompareWordD0ToD2);
        Append(code, BranchLessThanWord);
        var publishInvalidXExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareWordD1ToD3);
        Append(code, BranchLessThanWord);
        var publishInvalidYExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, MoveLongA3DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, MoveAddressD5ToA5);
        foreach (var pair in new[]
                 {
                     (0, SubWordD5ToD0),
                     (2, SubWordD5ToD1),
                     (0, SubWordD5ToD2),
                     (2, SubWordD5ToD3)
                 })
        {
            Append(code, MoveWordA6DisplacementToD5);
            Append(code, checked((ushort)pair.Item1));
            Append(code, pair.Item2);
        }
        Append(code, MoveWordD0ToA3Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleBounds));
        Append(code, MoveWordD1ToA3Displacement);
        Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMinY)));
        Append(code, MoveWordD2ToA3Displacement);
        Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxX)));
        Append(code, MoveWordD3ToA3Displacement);
        Append(code, checked((ushort)(GraphicsLayouts.RegionRectangleBounds + GraphicsLayouts.RectangleMaxY)));
        Append(code, MoveLongA5ToD5);
        Append(code, MoveLongD5ToA3Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, MoveLongA4ToD5);
        Append(code, MoveLongD5ToA3Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectanglePrevious));
        Append(code, MoveAddressA3ToA4);
        Append(code, MoveAddressA5ToA3);
        Append(code, MoveAddressD4ToA2);
        Append(code, BranchAlwaysWord);
        var publishAdvanceAfterWriteExtensionOffset = code.Count;
        Append(code, 0);
        var publishAdvanceOffset = code.Count;
        PatchBranch(code, publishInvalidXExtensionOffset, publishAdvanceOffset);
        PatchBranch(code, publishInvalidYExtensionOffset, publishAdvanceOffset);
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, MoveAddressD4ToA2);
        var publishAfterAdvanceOffset = code.Count;
        PatchBranch(code, publishAdvanceAfterWriteExtensionOffset, publishAfterAdvanceOffset);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var publishCompleteExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, DecrementBranchD6);
        var publishLoopExtensionOffset = code.Count;
        Append(code, 0);
        Decline(BranchAlwaysWord); // all later branches were proven above.
        var publishCompleteOffset = code.Count;
        PatchBranch(code, publishCompleteExtensionOffset, publishCompleteOffset);
        PatchBranch(code, publishLoopExtensionOffset, publishLoopOffset);

        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA4Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, MoveWordA6DisplacementToD0);
        Append(code, 0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMinX));
        Append(code, MoveWordA6DisplacementToD1);
        Append(code, 2);
        Append(code, MoveWordD1ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordA6DisplacementToD2);
        Append(code, 4);
        Append(code, MoveWordD2ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMaxX));
        Append(code, MoveWordA6DisplacementToD3);
        Append(code, 6);
        Append(code, MoveWordD3ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMaxY));
        Append(code, BranchAlwaysWord);
        var publishFreeExtensionOffset = code.Count;
        Append(code, 0);

        // Empty output (including an initially empty Region) uses the same
        // all-zero public header convention as the native ClearRegion body.
        var noResultOffset = code.Count;
        PatchBranch(code, noResultExtensionOffset, noResultOffset);
        PatchBranch(code, calculatedNoResultExtensionOffset, noResultOffset);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RegionBounds));
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)(GraphicsLayouts.RegionBounds + 4)));
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangle));

        var freeSuffixOffset = code.Count;
        PatchBranch(code, publishFreeExtensionOffset, freeSuffixOffset);
        // ExecBase was proven before the calculation pass.  It is reloaded
        // only after the final public header is visible.
        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongImmediateD6);
        Append(code, 0);
        Append(code, 0x0FFF);
        var freeSuffixLoopOffset = code.Count;
        Append(code, MoveLongA3ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var freeSuffixDoneExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleNext));
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.RegionRectangleSize));
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 1); // PUBLIC
        AppendExecFreeMemFromA0PreservingA1(code);
        Append(code, MoveAddressD4ToA3);
        Append(code, DecrementBranchD6);
        var freeSuffixLoopExtensionOffset = code.Count;
        Append(code, 0);
        var freeSuffixDoneOffset = code.Count;
        PatchBranch(code, freeSuffixDoneExtensionOffset, freeSuffixDoneOffset);
        PatchBranch(code, freeSuffixLoopExtensionOffset, freeSuffixLoopOffset);
        Append(code, AddQuickEightLongA7);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, AddQuickEightLongA7);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendFreeRasterNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(12);

        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x3102); // MOVEM.L D2/D3/D7/A6,-(A7), reversed save mask

        Append(code, MoveLongD0ToD7);

        // Normalize the public UWORD dimensions before checking the private
        // envelope, retaining the caller's original D0 in D7 for decline.
        Append(code, MoveQuickZeroD2);
        Append(code, MoveWordD1ToD2);
        Append(code, TestWordD2);
        Append(code, BranchEqualWord);
        var zeroHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(zeroHeightBranchExtensionOffset);
        Append(code, MoveQuickZeroD1);
        Append(code, MoveWordD0ToD1);
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var zeroWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(zeroWidthBranchExtensionOffset);

        Append(code, MoveLongA0ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullRasterBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullRasterBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRasterBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRasterBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 10);
        // A NULL AllocMem result cannot own the header at address zero.
        Append(code, BranchLowerOrSameWord);
        var shortRasterBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(shortRasterBranchExtensionOffset);
        Append(code, SubImmediateLongD0);
        Append(code, 0);
        Append(code, 10);
        Append(code, MoveAddressD0ToA0);

        Append(code, MoveWordA0DisplacementToD3);
        Append(code, 0);
        Append(code, CompareImmediateWordD3);
        Append(code, NativeRasterMarker);
        Append(code, BranchNotEqualWord);
        var markerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(markerBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, 2);
        Append(code, CompareWordD3ToD1);
        Append(code, BranchNotEqualWord);
        var widthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, 4);
        Append(code, CompareWordD2ToD3);
        Append(code, BranchNotEqualWord);
        var heightBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(heightBranchExtensionOffset);

        // Recompute the exact envelope from normalized dimensions before
        // D1 is reused for its recorded size. MOVE.L also discards D3's
        // caller high word left intact by the preceding header reads.
        Append(code, MoveLongD1ToD3);
        Append(code, AddImmediateLongD3);
        Append(code, 0);
        Append(code, 15);
        Append(code, ShiftRightLongD3);
        Append(code, ShiftRightLongD3);
        Append(code, ShiftRightLongD3);
        Append(code, ShiftRightLongD3);
        Append(code, ShiftLeftLongD3);
        Append(code, MultiplyUnsignedWordD2ToD3);
        Append(code, AddImmediateLongD3);
        Append(code, 0);
        Append(code, 10);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, 6);
        Append(code, CompareLongD3ToD1);
        Append(code, BranchNotEqualWord);
        var spanBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(spanBranchExtensionOffset);

        // Header ownership alone cannot admit a wrapped raster payload.
        // The inclusive last-byte check deliberately accepts $FFFFFFFF.
        Append(code, MoveLongD3ToD2);
        Append(code, SubQuickOneLongD2);
        Append(code, AddLongD0ToD2);
        Append(code, BranchCarryWord);
        var wrappingRasterBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappingRasterBranchExtensionOffset);

        Append(code, MoveAddressA0ToA1);
        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA1ToD0);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x408C); // MOVEM.L (A7)+,D2/D3/D7/A6
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x408C);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static void AppendNativeBitMapReservedFields(List<byte> code, int depth)
    {
        // A0 is the validated private base. Initialize only header fields not
        // written by active geometry/plane publication; payload belongs to Exec.
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, 12); // private reserved longword
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 22); // public BitMap pad at private prefix16 + public offset6
        for (var plane = depth; plane < 8; plane++)
        {
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, checked((ushort)(16 + GraphicsLayouts.BitMapPlanes + plane * 4)));
        }
    }

    private static int AppendNativeBitMapPublicFlags(
        List<byte> code,
        byte depth)
    {
        // The public BitMap packs Flags in the high byte and Depth in the
        // low byte.  Standard planar storage is always published; retain
        // BMF_DISPLAYABLE when the caller requested it while leaving the
        // allocation's private Exec flags (PUBLIC|CHIP[|CLEAR]) unchanged.
        Append(code, MoveImmediateWordD0);
        Append(code, checked((ushort)(0x0800 | depth)));
        Append(code, BitTestImmediateD3);
        Append(code, 1); // BMF_DISPLAYABLE
        Append(code, BranchEqualWord);
        var noDisplayableBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, OrImmediateWordD0);
        Append(code, 0x0200);
        return noDisplayableBranchExtensionOffset;
    }

    private static int AppendAllocBitMapNativeEight(
        List<byte> code,
        int fourPlaneEntryOffset,
        int globalFallbackEntryOffset)
    {
        var offset = code.Count;
        Append(code, MoveMultipleLongRegistersToPreDecrementA7); // D2/D4..D7/A2/A4/A6
        Append(code, 0x2F2A);
        var chainFourBranches = new List<int>(10);
        var globalFallbackBranches = new List<int>(4);

        // Depth eight is the upper native standard-planar ladder arm.  The
        // lower depth bodies remain separate so their publication and
        // fallback contracts stay independently auditable.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveAddressA0ToA2);
        Append(code, MoveLongA0ToD4); // Friend_BitMap must be NULL
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var friendBranchExtensionOffset = code.Count;
        Append(code, 0);
        chainFourBranches.Add(friendBranchExtensionOffset);

        // ULONG inputs must fit the classic UWORD row stride and row count.
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0007);
        Append(code, 0xFFF0); // maximum word-aligned width: 65534 bytes per row
        Append(code, BranchHighWord);
        var widthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(widthRangeBranchExtensionOffset);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var zeroWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        chainFourBranches.Add(zeroWidthBranchExtensionOffset);
        Append(code, MoveLongD0ToD4);

        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 0xFFFF);
        Append(code, BranchHighWord);
        var heightRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(heightRangeBranchExtensionOffset);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var zeroHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        chainFourBranches.Add(zeroHeightBranchExtensionOffset);
        Append(code, MoveLongD1ToD5);

        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 8);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        chainFourBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveLongD4ToD2);

        Append(code, MoveLongD3ToD6);
        Append(code, AndImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // admit BMF_CLEAR and BMF_DISPLAYABLE
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var flagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        chainFourBranches.Add(flagsBranchExtensionOffset);

        // bytesPerRow = ((width + 15) >> 4) << 1; D6 becomes the aggregate
        // eight-plane span before the public envelope is added.
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 15);
        Append(code, AddLongD1ToD0);
        for (var shift = 0; shift < 4; shift++)
            Append(code, ShiftRightLongD0);
        Append(code, ShiftLeftLongD0);
        Append(code, MoveLongD0ToD4); // row bytes
        Append(code, MoveLongD5ToD6);
        Append(code, MultiplyUnsignedWordD4ToD6); // one-plane bytes
        // Bound the aggregate, including its private/public envelope.
        Append(code, CompareImmediateLongD6);
        Append(code, 0x1FFF);
        Append(code, 0xFFF8);
        Append(code, BranchHighWord);
        var aggregateOverflowBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(aggregateOverflowBranchExtensionOffset);
        Append(code, MoveLongD6ToD0);
        for (var plane = 0; plane < 7; plane++)
            Append(code, AddLongD6ToD0);
        Append(code, MoveLongD0ToD6); // eight-plane aggregate bytes
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0x38); // private header + public BitMap
        Append(code, AddLongD1ToD6);

        Append(code, BitTestImmediateD3);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var noClearFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0003); // PUBLIC | CHIP | CLEAR
        Append(code, BranchAlwaysWord);
        var flagsJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        var noClearFlagsOffset = code.Count;
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0x0003); // PUBLIC | CHIP, without CLEAR
        var flagsReadyOffset = code.Count;

        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongD6ToD0);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var allocationFailureBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(allocationFailureBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        // Check the inclusive last byte without changing the returned base.
        Append(code, MoveLongD6ToD1);
        Append(code, SubQuickOneLongD1);
        Append(code, AddLongD0ToD1);
        Append(code, BranchCarryWord);
        var wrappedAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var skipOddCleanupBranchExtensionOffset = code.Count;
        Append(code, 0);

        var oddCleanupOffset = code.Count; // shared rollback for odd or wrapping results
        Append(code, MoveLongD6ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, BranchAlwaysWord);
        var oddCleanupJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(oddCleanupJoinBranchExtensionOffset);

        var successOffset = code.Count;
        Append(code, MoveAddressD0ToA0);
        AppendNativeBitMapReservedFields(code, 8);
        Append(code, MoveImmediateWordD0);
        Append(code, NativeBitMapMarker);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 0);
        Append(code, MoveLongD2ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 2);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 4);
        Append(code, MoveImmediateWordD0);
        Append(code, 8);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 6);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, 8);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0); // public BitMap
        Append(code, MoveLongD4ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveLongD5ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        var publicFlagsBranchExtensionOffset = AppendNativeBitMapPublicFlags(
            code,
            depth: 8);
        PatchBranch(code, publicFlagsBranchExtensionOffset, code.Count);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, MoveAddressA0ToA2);
        Append(code, MoveAddressA0ToA1);
        for (var index = 0; index < 10; index++)
            Append(code, AddQuickFourLongA1); // first plane = public + 0x28
        Append(code, MoveLongA1ToD0);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, MoveAddressA1ToA4);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongD5ToD1);
        Append(code, MultiplyUnsignedWordD1ToD0);
        Append(code, MoveLongD0ToD4); // row bytes * rows
        for (var plane = 1; plane < 8; plane++)
        {
            Append(code, AddLongD4ToA4);
            Append(code, MoveLongA4ToD0);
            Append(code, MoveAddressA2ToA0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + (plane * 4))));
        }
        Append(code, MoveLongA0ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x54F4);
        Append(code, ReturnFromSubroutine);

        var fallbackToFourOffset = code.Count;
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x54F4);
        Append(code, BranchAlwaysWord);
        var fourPlaneJumpExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackGlobalRestoreOffset = code.Count;
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x54F4);
        Append(code, BranchAlwaysWord);
        var globalJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, noClearFlagsBranchExtensionOffset, noClearFlagsOffset);
        PatchBranch(code, flagsJoinBranchExtensionOffset, flagsReadyOffset);
        PatchBranch(code, oddAllocationBranchExtensionOffset, oddCleanupOffset);
        PatchBranch(code, wrappedAllocationBranchExtensionOffset, oddCleanupOffset);
        PatchBranch(code, skipOddCleanupBranchExtensionOffset, successOffset);
        PatchBranch(code, fourPlaneJumpExtensionOffset, fourPlaneEntryOffset);
        PatchBranch(code, globalJumpExtensionOffset, globalFallbackEntryOffset);
        foreach (var branchExtensionOffset in chainFourBranches)
            PatchBranch(code, branchExtensionOffset, fallbackToFourOffset);
        PatchBranch(code, oddCleanupJoinBranchExtensionOffset, fallbackGlobalRestoreOffset);
        foreach (var branchExtensionOffset in globalFallbackBranches)
        {
            if (branchExtensionOffset == oddCleanupJoinBranchExtensionOffset)
                continue;
            PatchBranch(code, branchExtensionOffset, fallbackGlobalRestoreOffset);
        }

        return offset;
    }

    private static int AppendFreeBitMapNativeEight(
        List<byte> code,
        int fourPlaneEntryOffset,
        int globalFallbackEntryOffset)
    {
        var offset = code.Count;
        Append(code, MoveMultipleLongRegistersToPreDecrementA7); // D3..D7/A2..A4/A6
        Append(code, 0x1F3A);
        var chainFourBranches = new List<int>(2);
        var globalFallbackBranches = new List<int>(12);
        var planeMismatchBranches = new List<int>(8);

        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD0);
        Append(code, MoveAddressA0ToA2);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(oddBitMapBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 16);
        Append(code, BranchCarryWord);
        var shortBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(shortBitMapBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 16);
        Append(code, BranchEqualWord);
        var zeroBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(zeroBaseBranchExtensionOffset);
        Append(code, SubImmediateLongD0);
        Append(code, 0);
        Append(code, 16);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0ToD6);
        Append(code, MoveAddressD6ToA3);
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, 6);
        Append(code, CompareImmediateWordD3);
        Append(code, 8);
        Append(code, BranchNotEqualWord);
        var nonEightDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        chainFourBranches.Add(nonEightDepthBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, 0); // matched depth does not establish native ownership
        Append(code, CompareImmediateWordD3);
        Append(code, NativeBitMapMarker);
        Append(code, BranchNotEqualWord);
        var markerBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(markerBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, 8);
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 0x38);
        Append(code, BranchCarryWord);
        var shortSpanBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(shortSpanBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddSpanBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(oddSpanBranchExtensionOffset);

        // The validated stored span must cover every public-header read.
        Append(code, MoveLongD1ToD4);
        Append(code, SubQuickOneLongD4);
        Append(code, AddLongD0ToD4);
        Append(code, BranchCarryWord);
        var wrappedEnvelopeBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(wrappedEnvelopeBranchExtensionOffset);

        Append(code, MoveAddressA2ToA1);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, MoveLongD1ToD5);
        Append(code, MultiplyUnsignedWordD4ToD5);
        Append(code, CompareImmediateLongD5);
        Append(code, 0x1FFF);
        Append(code, 0xFFF8);
        Append(code, BranchHighWord);
        var aggregateOverflowBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(aggregateOverflowBranchExtensionOffset);
        Append(code, MoveLongD5ToD6); // retain D5's plane span for topology checks
        Append(code, ShiftLeftLongD6);
        Append(code, ShiftLeftLongD6);
        Append(code, ShiftLeftLongD6);
        Append(code, AddImmediateLongD6);
        Append(code, 0);
        Append(code, 0x38);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, 8); // reload the full stored span after WORD row decoding
        Append(code, CompareLongD6ToD1);
        Append(code, BranchNotEqualWord);
        var aggregateSpanBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(aggregateSpanBranchExtensionOffset);
        Append(code, MoveAddressA1ToA4);
        for (var index = 0; index < 10; index++)
            Append(code, AddQuickFourLongA4);

        for (var plane = 0; plane < 8; plane++)
        {
            Append(code, MoveLongA1DisplacementToD6);
            Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + (plane * 4))));
            Append(code, MoveLongA4ToD0);
            Append(code, CompareLongD6ToD0);
            Append(code, BranchNotEqualWord);
            var planeMismatchBranchExtensionOffset = code.Count;
            Append(code, 0);
            planeMismatchBranches.Add(planeMismatchBranchExtensionOffset);
            if (plane < 7)
                Append(code, AddLongD5ToA4);
        }

        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, 8); // reload exact aggregate span after row decoding
        Append(code, MoveLongA0ToD0);
        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, MoveLongD0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0ToD0);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x5CF8);
        Append(code, ReturnFromSubroutine);

        var nullBitMapOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x5CF8);
        Append(code, ReturnFromSubroutine);

        var fallbackToFourOffset = code.Count;
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x5CF8);
        Append(code, BranchAlwaysWord);
        var fourPlaneJumpExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackGlobalRestoreOffset = code.Count;
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x5CF8);
        Append(code, BranchAlwaysWord);
        var globalJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, nullBitMapBranchExtensionOffset, nullBitMapOffset);
        PatchBranch(code, fourPlaneJumpExtensionOffset, fourPlaneEntryOffset);
        PatchBranch(code, globalJumpExtensionOffset, globalFallbackEntryOffset);
        foreach (var branchExtensionOffset in chainFourBranches)
            PatchBranch(code, branchExtensionOffset, fallbackToFourOffset);
        foreach (var branchExtensionOffset in globalFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackGlobalRestoreOffset);
        foreach (var branchExtensionOffset in planeMismatchBranches)
            PatchBranch(code, branchExtensionOffset, fallbackGlobalRestoreOffset);

        return offset;
    }

    private static int AppendAllocBitMapNativeFour(
        List<byte> code,
        int twoPlaneEntryOffset,
        int globalFallbackEntryOffset)
    {
        var offset = code.Count;
        Append(code, MoveMultipleLongRegistersToPreDecrementA7); // D2/D4..D7/A2/A4/A6
        Append(code, 0x2F2A);
        var chainTwoBranches = new List<int>(10);
        var globalFallbackBranches = new List<int>(4);

        // Depth four is an independent native ladder arm.  It keeps the
        // original ABI intact while handing depth one/two and all malformed
        // geometry back to the already-built lower arms.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveAddressA0ToA2);
        Append(code, MoveLongA0ToD4); // Friend_BitMap must be NULL
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var friendBranchExtensionOffset = code.Count;
        Append(code, 0);
        chainTwoBranches.Add(friendBranchExtensionOffset);

        // ULONG inputs must fit the classic UWORD row stride and row count.
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0007);
        Append(code, 0xFFF0); // maximum word-aligned width: 65534 bytes per row
        Append(code, BranchHighWord);
        var widthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(widthRangeBranchExtensionOffset);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var zeroWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        chainTwoBranches.Add(zeroWidthBranchExtensionOffset);
        Append(code, MoveLongD0ToD4);

        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 0xFFFF);
        Append(code, BranchHighWord);
        var heightRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(heightRangeBranchExtensionOffset);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var zeroHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        chainTwoBranches.Add(zeroHeightBranchExtensionOffset);
        Append(code, MoveLongD1ToD5);

        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 4);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        chainTwoBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveLongD4ToD2);

        Append(code, MoveLongD3ToD6);
        Append(code, AndImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // admit BMF_CLEAR and BMF_DISPLAYABLE
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var flagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        chainTwoBranches.Add(flagsBranchExtensionOffset);

        // bytesPerRow = ((width + 15) >> 4) << 1; D6 becomes one-plane
        // storage, then the aggregate four-plane span.
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 15);
        Append(code, AddLongD1ToD0);
        for (var shift = 0; shift < 4; shift++)
            Append(code, ShiftRightLongD0);
        Append(code, ShiftLeftLongD0);
        Append(code, MoveLongD0ToD4); // row bytes
        Append(code, MoveLongD5ToD6);
        Append(code, MultiplyUnsignedWordD4ToD6); // one-plane bytes
        // Bound the aggregate, including its private/public envelope.
        Append(code, CompareImmediateLongD6);
        Append(code, 0x3FFF);
        Append(code, 0xFFF1);
        Append(code, BranchHighWord);
        var aggregateOverflowBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(aggregateOverflowBranchExtensionOffset);
        Append(code, MoveLongD6ToD0);
        for (var plane = 0; plane < 3; plane++)
            Append(code, AddLongD6ToD0);
        Append(code, MoveLongD0ToD6); // four-plane aggregate bytes
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0x38); // private header + public BitMap
        Append(code, AddLongD1ToD6);

        Append(code, BitTestImmediateD3);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var noClearFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0003); // PUBLIC | CHIP | CLEAR
        Append(code, BranchAlwaysWord);
        var flagsJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        var noClearFlagsOffset = code.Count;
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0x0003); // PUBLIC | CHIP, without CLEAR
        var flagsReadyOffset = code.Count;

        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongD6ToD0);
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var allocationFailureBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(allocationFailureBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        // Check the inclusive last byte without changing the returned base.
        Append(code, MoveLongD6ToD1);
        Append(code, SubQuickOneLongD1);
        Append(code, AddLongD0ToD1);
        Append(code, BranchCarryWord);
        var wrappedAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var skipOddCleanupBranchExtensionOffset = code.Count;
        Append(code, 0);

        var oddCleanupOffset = code.Count; // shared rollback for odd or wrapping results
        Append(code, MoveLongD6ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, BranchAlwaysWord);
        var oddCleanupJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(oddCleanupJoinBranchExtensionOffset);

        var successOffset = code.Count;
        Append(code, MoveAddressD0ToA0);
        AppendNativeBitMapReservedFields(code, 4);
        Append(code, MoveImmediateWordD0);
        Append(code, NativeBitMapMarker);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 0);
        Append(code, MoveLongD2ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 2);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 4);
        Append(code, MoveImmediateWordD0);
        Append(code, 4);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 6);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, 8);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0); // public BitMap
        Append(code, MoveLongD4ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveLongD5ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        var publicFlagsBranchExtensionOffset = AppendNativeBitMapPublicFlags(
            code,
            depth: 4);
        PatchBranch(code, publicFlagsBranchExtensionOffset, code.Count);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, MoveAddressA0ToA2);
        Append(code, MoveAddressA0ToA1);
        for (var index = 0; index < 10; index++)
            Append(code, AddQuickFourLongA1); // first plane = public + 0x28
        Append(code, MoveLongA1ToD0);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, MoveAddressA1ToA4);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongD5ToD1);
        Append(code, MultiplyUnsignedWordD1ToD0);
        Append(code, MoveLongD0ToD4); // row bytes * rows
        for (var plane = 1; plane < 4; plane++)
        {
            Append(code, AddLongD4ToA4);
            Append(code, MoveLongA4ToD0);
            Append(code, MoveAddressA2ToA0);
            Append(code, MoveLongD0ToA0Displacement);
            Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + (plane * 4))));
        }
        Append(code, MoveLongA0ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x54F4);
        Append(code, ReturnFromSubroutine);

        var fallbackToTwoOffset = code.Count;
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x54F4);
        Append(code, BranchAlwaysWord);
        var twoPlaneJumpExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackGlobalRestoreOffset = code.Count;
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x54F4);
        Append(code, BranchAlwaysWord);
        var globalJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, noClearFlagsBranchExtensionOffset, noClearFlagsOffset);
        PatchBranch(code, flagsJoinBranchExtensionOffset, flagsReadyOffset);
        PatchBranch(code, oddAllocationBranchExtensionOffset, oddCleanupOffset);
        PatchBranch(code, wrappedAllocationBranchExtensionOffset, oddCleanupOffset);
        PatchBranch(code, skipOddCleanupBranchExtensionOffset, successOffset);
        PatchBranch(code, twoPlaneJumpExtensionOffset, twoPlaneEntryOffset);
        PatchBranch(code, globalJumpExtensionOffset, globalFallbackEntryOffset);
        foreach (var branchExtensionOffset in chainTwoBranches)
            PatchBranch(code, branchExtensionOffset, fallbackToTwoOffset);
        PatchBranch(code, oddCleanupJoinBranchExtensionOffset, fallbackGlobalRestoreOffset);
        foreach (var branchExtensionOffset in globalFallbackBranches)
        {
            if (branchExtensionOffset == oddCleanupJoinBranchExtensionOffset)
                continue;
            PatchBranch(code, branchExtensionOffset, fallbackGlobalRestoreOffset);
        }

        return offset;
    }

    private static int AppendFreeBitMapNativeFour(
        List<byte> code,
        int twoPlaneEntryOffset,
        int globalFallbackEntryOffset)
    {
        var offset = code.Count;
        Append(code, MoveMultipleLongRegistersToPreDecrementA7); // D2..D7/A2..A4/A6
        Append(code, 0x3F3A);
        var chainTwoBranches = new List<int>(2);
        var globalFallbackBranches = new List<int>(12);

        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD0);
        Append(code, MoveAddressA0ToA2);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(oddBitMapBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 16);
        Append(code, BranchCarryWord);
        var shortBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(shortBitMapBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 16);
        Append(code, BranchEqualWord);
        var zeroBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(zeroBaseBranchExtensionOffset);
        Append(code, SubImmediateLongD0);
        Append(code, 0);
        Append(code, 16);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0ToD6);
        Append(code, MoveAddressD6ToA3);
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, 6);
        Append(code, CompareImmediateWordD3);
        Append(code, 4);
        Append(code, BranchNotEqualWord);
        var nonFourDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        chainTwoBranches.Add(nonFourDepthBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, 0); // matched depth does not establish native ownership
        Append(code, CompareImmediateWordD3);
        Append(code, NativeBitMapMarker);
        Append(code, BranchNotEqualWord);
        var markerBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(markerBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, 8);
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 0x38);
        Append(code, BranchCarryWord);
        var shortSpanBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(shortSpanBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddSpanBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(oddSpanBranchExtensionOffset);

        // The validated stored span must cover every public-header read.
        Append(code, MoveLongD1ToD4);
        Append(code, SubQuickOneLongD4);
        Append(code, AddLongD0ToD4);
        Append(code, BranchCarryWord);
        var wrappedEnvelopeBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(wrappedEnvelopeBranchExtensionOffset);

        Append(code, MoveAddressA2ToA1);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, MoveLongD1ToD5);
        Append(code, MultiplyUnsignedWordD4ToD5);
        Append(code, CompareImmediateLongD5);
        Append(code, 0x3FFF);
        Append(code, 0xFFF1);
        Append(code, BranchHighWord);
        var aggregateOverflowBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(aggregateOverflowBranchExtensionOffset);
        Append(code, MoveLongD5ToD6); // retain D5's plane span for topology checks
        Append(code, ShiftLeftLongD6);
        Append(code, ShiftLeftLongD6);
        Append(code, AddImmediateLongD6);
        Append(code, 0);
        Append(code, 0x38);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, 8); // reload the full stored span after WORD row decoding
        Append(code, CompareLongD6ToD1);
        Append(code, BranchNotEqualWord);
        var aggregateSpanBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(aggregateSpanBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, MoveLongA1DisplacementToD3);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 4)));
        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 8)));
        Append(code, MoveLongA1DisplacementToD1);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 12)));

        Append(code, MoveAddressA1ToA0);
        for (var index = 0; index < 10; index++)
        {
            Append(code, AddQuickOneLongA0);
            Append(code, AddQuickOneLongA0);
            Append(code, AddQuickOneLongA0);
            Append(code, AddQuickOneLongA0);
        }
        Append(code, MoveLongA0ToD0);
        Append(code, MoveLongD2ToD6);
        Append(code, CompareLongD6ToD0);
        Append(code, BranchNotEqualWord);
        var firstPlaneMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(firstPlaneMismatchBranchExtensionOffset);

        Append(code, MoveAddressA0ToA4);
        Append(code, AddLongD5ToA4);
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD3ToD6);
        Append(code, CompareLongD6ToD0);
        Append(code, BranchNotEqualWord);
        var secondPlaneMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(secondPlaneMismatchBranchExtensionOffset);

        Append(code, AddLongD5ToA4);
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD4ToD6);
        Append(code, CompareLongD6ToD0);
        Append(code, BranchNotEqualWord);
        var thirdPlaneMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(thirdPlaneMismatchBranchExtensionOffset);

        Append(code, AddLongD5ToA4);
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD1ToD6);
        Append(code, CompareLongD6ToD0);
        Append(code, BranchNotEqualWord);
        var fourthPlaneMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(fourthPlaneMismatchBranchExtensionOffset);

        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, 8);
        Append(code, MoveLongA0ToD0);
        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, MoveLongD0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0ToD0);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x5CFC);
        Append(code, ReturnFromSubroutine);

        var nullBitMapOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x5CFC);
        Append(code, ReturnFromSubroutine);

        var fallbackToTwoOffset = code.Count;
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x5CFC);
        Append(code, BranchAlwaysWord);
        var twoPlaneJumpExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackGlobalRestoreOffset = code.Count;
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x5CFC);
        Append(code, BranchAlwaysWord);
        var globalJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, nullBitMapBranchExtensionOffset, nullBitMapOffset);
        PatchBranch(code, nonFourDepthBranchExtensionOffset, fallbackToTwoOffset);
        PatchBranch(code, twoPlaneJumpExtensionOffset, twoPlaneEntryOffset);
        PatchBranch(code, globalJumpExtensionOffset, globalFallbackEntryOffset);
        foreach (var branchExtensionOffset in chainTwoBranches)
            PatchBranch(code, branchExtensionOffset, fallbackToTwoOffset);
        foreach (var branchExtensionOffset in globalFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackGlobalRestoreOffset);

        return offset;
    }

    private static int AppendAllocBitMapNativeTwo(
        List<byte> code,
        int onePlaneEntryOffset,
        int globalFallbackEntryOffset)
    {
        var offset = code.Count;
        Append(code, MoveMultipleLongRegistersToPreDecrementA7); // D2/D4..D7/A2/A4/A6
        Append(code, 0x2F2A);
        var earlyFallbackBranches = new List<int>(10);
        var allocationFallbackBranches = new List<int>(4);

        // A depth-two standard-planar arm is kept separate from the depth-one
        // form so each native body has a fixed, auditable publication shape.
        // Unsupported friends/flags/depths chain to the already-built
        // one-plane body first; allocator and envelope failures go directly
        // to the original provider fallback and never retry allocation.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveAddressA0ToA2); // preserve Friend_BitMap for depth-one chain
        Append(code, MoveLongA0ToD4); // Friend_BitMap must be NULL
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var friendBranchExtensionOffset = code.Count;
        Append(code, 0);
        earlyFallbackBranches.Add(friendBranchExtensionOffset);

        // ULONG inputs must fit the classic UWORD row stride and row count.
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0007);
        Append(code, 0xFFF0); // maximum word-aligned width: 65534 bytes per row
        Append(code, BranchHighWord);
        var widthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        allocationFallbackBranches.Add(widthRangeBranchExtensionOffset);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var zeroWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        earlyFallbackBranches.Add(zeroWidthBranchExtensionOffset);
        Append(code, MoveLongD0ToD4); // width
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 0xFFFF);
        Append(code, BranchHighWord);
        var heightRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        allocationFallbackBranches.Add(heightRangeBranchExtensionOffset);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var zeroHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        earlyFallbackBranches.Add(zeroHeightBranchExtensionOffset);
        Append(code, MoveLongD1ToD5); // height

        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        earlyFallbackBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveLongD4ToD2); // retain width for header publication

        Append(code, MoveLongD3ToD6);
        Append(code, AndImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // admit BMF_CLEAR and BMF_DISPLAYABLE
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var flagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        earlyFallbackBranches.Add(flagsBranchExtensionOffset);

        // bytesPerRow = ((width + 15) >> 4) << 1; depth-two plane bytes are
        // doubled before the private/public envelope is added.
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 15);
        Append(code, AddLongD1ToD0);
        for (var shift = 0; shift < 4; shift++)
            Append(code, ShiftRightLongD0);
        Append(code, ShiftLeftLongD0);
        Append(code, MoveLongD0ToD4); // row bytes
        Append(code, MoveLongD5ToD6); // height
        Append(code, MultiplyUnsignedWordD4ToD6);
        // Bound the aggregate, including its private/public envelope.
        Append(code, CompareImmediateLongD6);
        Append(code, 0x7FFF);
        Append(code, 0xFFE3);
        Append(code, BranchHighWord);
        var aggregateOverflowBranchExtensionOffset = code.Count;
        Append(code, 0);
        allocationFallbackBranches.Add(aggregateOverflowBranchExtensionOffset);
        Append(code, MoveLongD6ToD0); // one-plane byte span
        Append(code, AddLongD0ToD6); // two-plane byte span
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0x38); // private header + public BitMap
        Append(code, AddLongD1ToD6);

        Append(code, BitTestImmediateD3);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var noClearFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0003); // PUBLIC | CHIP | CLEAR
        Append(code, BranchAlwaysWord);
        var flagsJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        var noClearFlagsOffset = code.Count;
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0x0003); // PUBLIC | CHIP, without CLEAR
        var flagsReadyOffset = code.Count;

        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        allocationFallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongD6ToD0); // exact aggregate span
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var allocationFailureBranchExtensionOffset = code.Count;
        Append(code, 0);
        allocationFallbackBranches.Add(allocationFailureBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        // Check the inclusive last byte without changing the returned base.
        Append(code, MoveLongD6ToD1);
        Append(code, SubQuickOneLongD1);
        Append(code, AddLongD0ToD1);
        Append(code, BranchCarryWord);
        var wrappedAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var skipOddCleanupBranchExtensionOffset = code.Count;
        Append(code, 0);

        var oddCleanupOffset = code.Count; // shared rollback for odd or wrapping results
        Append(code, MoveLongD6ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, BranchAlwaysWord);
        var oddCleanupJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        allocationFallbackBranches.Add(oddCleanupJoinBranchExtensionOffset);

        var successOffset = code.Count;
        Append(code, MoveAddressD0ToA0); // private base
        AppendNativeBitMapReservedFields(code, 2);
        Append(code, MoveImmediateWordD0);
        Append(code, NativeBitMapMarker);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 0);
        Append(code, MoveLongD2ToD0); // width
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 2);
        Append(code, MoveLongD5ToD0); // height
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 4);
        Append(code, MoveImmediateWordD0);
        Append(code, 2); // depth
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 6);
        Append(code, MoveLongD6ToD0); // exact span
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, 8);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0); // public BitMap
        Append(code, MoveLongD4ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveLongD5ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        var publicFlagsBranchExtensionOffset = AppendNativeBitMapPublicFlags(
            code,
            depth: 2);
        PatchBranch(code, publicFlagsBranchExtensionOffset, code.Count);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, MoveAddressA0ToA2); // public pointer
        Append(code, MoveAddressA0ToA1);
        for (var index = 0; index < 10; index++)
            Append(code, AddQuickFourLongA1); // first plane = public + 0x28
        Append(code, MoveLongA1ToD0);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, MoveAddressA1ToA4);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongD5ToD1);
        Append(code, MultiplyUnsignedWordD1ToD0);
        Append(code, MoveLongD0ToD4); // plane span = row bytes * rows
        Append(code, AddLongD4ToA4); // second plane = first + row span
        Append(code, MoveLongA4ToD0);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 4)));
        Append(code, MoveLongA0ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x54F4);
        Append(code, ReturnFromSubroutine);

        var fallbackToOneOffset = code.Count;
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x54F4);
        Append(code, BranchAlwaysWord);
        var onePlaneJumpExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackGlobalRestoreOffset = code.Count;
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x54F4);
        Append(code, BranchAlwaysWord);
        var globalJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, noClearFlagsBranchExtensionOffset, noClearFlagsOffset);
        PatchBranch(code, flagsJoinBranchExtensionOffset, flagsReadyOffset);
        PatchBranch(code, oddAllocationBranchExtensionOffset, oddCleanupOffset);
        PatchBranch(code, wrappedAllocationBranchExtensionOffset, oddCleanupOffset);
        PatchBranch(code, skipOddCleanupBranchExtensionOffset, successOffset);
        PatchBranch(code, onePlaneJumpExtensionOffset, onePlaneEntryOffset);
        PatchBranch(code, globalJumpExtensionOffset, globalFallbackEntryOffset);
        foreach (var branchExtensionOffset in earlyFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackToOneOffset);
        PatchBranch(code, oddCleanupJoinBranchExtensionOffset, fallbackGlobalRestoreOffset);
        foreach (var branchExtensionOffset in allocationFallbackBranches)
        {
            if (branchExtensionOffset == oddCleanupJoinBranchExtensionOffset)
                continue;
            PatchBranch(code, branchExtensionOffset, fallbackGlobalRestoreOffset);
        }

        return offset;
    }

    private static int AppendFreeBitMapNativeTwo(
        List<byte> code,
        int onePlaneEntryOffset,
        int globalFallbackEntryOffset)
    {
        var offset = code.Count;
        Append(code, MoveMultipleLongRegistersToPreDecrementA7); // D2..D7/A2..A4/A6
        Append(code, 0x3F3A);
        var earlyFallbackBranches = new List<int>(8);
        var globalFallbackBranches = new List<int>(10);

        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD0);
        Append(code, MoveAddressA0ToA2); // original public pointer
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(oddBitMapBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 16);
        Append(code, BranchCarryWord);
        var shortBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(shortBitMapBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 16);
        Append(code, BranchEqualWord);
        var zeroBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(zeroBaseBranchExtensionOffset);
        Append(code, SubImmediateLongD0);
        Append(code, 0);
        Append(code, 16);
        Append(code, MoveAddressD0ToA0); // private base
        Append(code, MoveLongA0ToD6);
        Append(code, MoveAddressD6ToA3); // preserve base for FreeMem
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, 6); // header depth
        Append(code, CompareImmediateWordD3);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var nonTwoDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        earlyFallbackBranches.Add(nonTwoDepthBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, 0); // matched depth does not establish native ownership
        Append(code, CompareImmediateWordD3);
        Append(code, NativeBitMapMarker);
        Append(code, BranchNotEqualWord);
        var markerBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(markerBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, 8); // exact aggregate span
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 0x38);
        Append(code, BranchCarryWord);
        var shortSpanBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(shortSpanBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddSpanBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(oddSpanBranchExtensionOffset);

        // The validated stored span must cover every public-header read.
        Append(code, MoveLongD1ToD4);
        Append(code, SubQuickOneLongD4);
        Append(code, AddLongD0ToD4);
        Append(code, BranchCarryWord);
        var wrappedEnvelopeBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(wrappedEnvelopeBranchExtensionOffset);

        Append(code, MoveAddressA2ToA1); // public BitMap
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, MoveLongD1ToD5);
        Append(code, MultiplyUnsignedWordD4ToD5); // row span
        Append(code, CompareImmediateLongD5);
        Append(code, 0x7FFF);
        Append(code, 0xFFE3);
        Append(code, BranchHighWord);
        var aggregateOverflowBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(aggregateOverflowBranchExtensionOffset);
        Append(code, MoveLongD5ToD6); // retain D5's plane span for topology checks
        Append(code, ShiftLeftLongD6);
        Append(code, AddImmediateLongD6);
        Append(code, 0);
        Append(code, 0x38);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, 8); // reload the full stored span after WORD row decoding
        Append(code, CompareLongD6ToD1);
        Append(code, BranchNotEqualWord);
        var aggregateSpanBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(aggregateSpanBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, MoveLongA1DisplacementToD3);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 4)));
        Append(code, MoveAddressA1ToA0);
        for (var index = 0; index < 10; index++)
        {
            Append(code, AddQuickOneLongA0);
            Append(code, AddQuickOneLongA0);
            Append(code, AddQuickOneLongA0);
            Append(code, AddQuickOneLongA0);
        } // expected plane zero
        Append(code, MoveLongA0ToD6);
        Append(code, MoveLongD2ToD0);
        Append(code, CompareLongD6ToD0);
        Append(code, BranchNotEqualWord);
        var firstPlaneMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(firstPlaneMismatchBranchExtensionOffset);
        Append(code, MoveAddressA0ToA4);
        Append(code, AddLongD5ToA4);
        Append(code, MoveLongA4ToD6);
        Append(code, MoveLongD3ToD0);
        Append(code, CompareLongD6ToD0);
        Append(code, BranchNotEqualWord);
        var secondPlaneMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(secondPlaneMismatchBranchExtensionOffset);

        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, 8); // reload exact aggregate span after row decoding
        Append(code, MoveLongA0ToD0);
        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, MoveLongD0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        globalFallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0ToD0);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x5CFC);
        Append(code, ReturnFromSubroutine);

        var nullBitMapOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x5CFC);
        Append(code, ReturnFromSubroutine);

        var fallbackToOneOffset = code.Count;
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x5CFC);
        Append(code, BranchAlwaysWord);
        var onePlaneJumpExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackGlobalRestoreOffset = code.Count;
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x5CFC);
        Append(code, BranchAlwaysWord);
        var globalJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, nullBitMapBranchExtensionOffset, nullBitMapOffset);
        PatchBranch(code, nonTwoDepthBranchExtensionOffset, fallbackToOneOffset);
        PatchBranch(code, onePlaneJumpExtensionOffset, onePlaneEntryOffset);
        PatchBranch(code, globalJumpExtensionOffset, globalFallbackEntryOffset);
        foreach (var branchExtensionOffset in earlyFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackToOneOffset);
        foreach (var branchExtensionOffset in globalFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackGlobalRestoreOffset);

        return offset;
    }

    private static int AppendAllocBitMapNativeOne(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        Append(code, MoveMultipleLongRegistersToPreDecrementA7); // D2/D4..D7/A6
        Append(code, 0x2F02);
        var fallbackBranches = new List<int>(16);

        // This first native bitmap arm deliberately claims one standard,
        // single-plane, non-friend allocation. Public ULONG dimensions must
        // fit the classic UWORD stride/rows; the host/provider boundary still
        // owns friends, interleaved requests, and CyberGraphX.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD4); // Friend_BitMap must be NULL
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var friendBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(friendBranchExtensionOffset);

        // ULONG inputs must fit the classic UWORD row stride and row count.
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0007);
        Append(code, 0xFFF0); // maximum word-aligned width: 65534 bytes per row
        Append(code, BranchHighWord);
        var widthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthRangeBranchExtensionOffset);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var zeroWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(zeroWidthBranchExtensionOffset);
        Append(code, MoveLongD0ToD4); // width

        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 0xFFFF);
        Append(code, BranchHighWord);
        var heightRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(heightRangeBranchExtensionOffset);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var zeroHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(zeroHeightBranchExtensionOffset);
        Append(code, MoveLongD1ToD5); // height

        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 1); // one plane only
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveLongD4ToD2); // retain width for publication

        // BMF_CLEAR and BMF_DISPLAYABLE are admitted as standard planar input
        // requests. STANDARD is a published result bit; INTERLEAVED/friend
        // policy stay with the portable/provider implementation.
        Append(code, MoveLongD3ToD6);
        Append(code, AndImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var flagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(flagsBranchExtensionOffset);

        // bytesPerRow = ((width + 15) >> 4) << 1; planeBytes is then
        // bytesPerRow * height and the private header/public BitMap add 0x38.
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 15);
        Append(code, AddLongD1ToD0);
        for (var shift = 0; shift < 4; shift++)
            Append(code, ShiftRightLongD0);
        Append(code, ShiftLeftLongD0);
        Append(code, MoveLongD0ToD4); // row bytes
        Append(code, MoveLongD5ToD6); // height
        Append(code, MultiplyUnsignedWordD4ToD6);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0x38); // 16-byte header + public BitMapSize
        Append(code, AddLongD1ToD6); // exact Exec span

        // Derive Exec's allocation flags while the exact span remains in D6.
        // BMF_CLEAR requests payload clearing, not a published result flag.
        Append(code, BitTestImmediateD3);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var noClearFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0003); // PUBLIC | CHIP | CLEAR
        Append(code, BranchAlwaysWord);
        var flagsJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var noClearFlagsOffset = code.Count;
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, 0x0003); // PUBLIC | CHIP, without CLEAR
        var flagsReadyOffset = code.Count;

        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongD6ToD0); // size
        // D1 already contains PUBLIC/(CHIP|CLEAR) flags.
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var allocationFailureBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        // Check the inclusive last byte without changing the returned base.
        Append(code, MoveLongD6ToD1);
        Append(code, SubQuickOneLongD1);
        Append(code, AddLongD0ToD1);
        Append(code, BranchCarryWord);
        var wrappedAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var skipOddCleanupBranchExtensionOffset = code.Count;
        Append(code, 0);

        var oddCleanupOffset = code.Count; // shared rollback for odd or wrapping results
        Append(code, MoveLongD6ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, BranchAlwaysWord);
        var oddCleanupJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveAddressD0ToA0); // private allocation base
        AppendNativeBitMapReservedFields(code, 1);
        Append(code, MoveImmediateWordD0);
        Append(code, NativeBitMapMarker);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 0);
        Append(code, MoveLongD2ToD0); // width
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 2);
        Append(code, MoveLongD5ToD0); // height
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 4);
        Append(code, MoveImmediateWordD0);
        Append(code, 1); // depth
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 6);
        Append(code, MoveLongD6ToD0); // exact span
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, 8);

        // Public BitMap starts after the private header.
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveLongD5ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        var publicFlagsBranchExtensionOffset = AppendNativeBitMapPublicFlags(
            code,
            depth: 1);
        PatchBranch(code, publicFlagsBranchExtensionOffset, code.Count);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, MoveAddressA0ToA1);
        for (var index = 0; index < 10; index++)
            Append(code, AddQuickFourLongA1); // public BitMap + 0x28
        Append(code, MoveLongA1ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, MoveLongA0ToD0); // public BitMap result
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40F4);
        Append(code, ReturnFromSubroutine);

        var allocationFailureOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var allocationFailureJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40F4);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, noClearFlagsBranchExtensionOffset, noClearFlagsOffset);
        PatchBranch(code, flagsJoinBranchExtensionOffset, flagsReadyOffset);
        PatchBranch(code, allocationFailureBranchExtensionOffset, allocationFailureOffset);
        PatchBranch(code, oddAllocationBranchExtensionOffset, oddCleanupOffset);
        PatchBranch(code, wrappedAllocationBranchExtensionOffset, oddCleanupOffset);
        PatchBranch(code, skipOddCleanupBranchExtensionOffset, successOffset);
        PatchBranch(code, oddCleanupJoinBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, allocationFailureJoinBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendFreeBitMapNativeOne(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        Append(code, MoveMultipleLongRegistersToPreDecrementA7); // D2..D4/D7/A2/A6
        Append(code, 0x3922);
        var fallbackBranches = new List<int>(12);

        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddBitMapBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 16); // private header span
        Append(code, BranchCarryWord);
        var shortBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(shortBitMapBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 16);
        Append(code, BranchEqualWord);
        var baseZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(baseZeroBranchExtensionOffset);
        Append(code, SubImmediateLongD0);
        Append(code, 0);
        Append(code, 16);
        Append(code, MoveAddressD0ToA0); // private base
        Append(code, MoveAddressA0ToA2); // preserve base for FreeMem
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, 0);
        Append(code, CompareImmediateWordD3);
        Append(code, NativeBitMapMarker);
        Append(code, BranchNotEqualWord);
        var markerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(markerBranchExtensionOffset);

        // The terminal arm must not retire an unsupported private depth.
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, 6);
        Append(code, CompareImmediateWordD3);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD1);
        Append(code, 8); // exact private span
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 0x38);
        Append(code, BranchCarryWord);
        var shortSpanBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(shortSpanBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddSpanBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddSpanBranchExtensionOffset);

        // The validated stored span must cover every public-header read.
        Append(code, MoveLongD1ToD4);
        Append(code, SubQuickOneLongD4);
        Append(code, AddLongD0ToD4);
        Append(code, BranchCarryWord);
        var wrappedEnvelopeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedEnvelopeBranchExtensionOffset);

        // Validate the one-plane publication pointer before releasing the
        // aggregate allocation.  This catches a caller-corrupted header or
        // foreign BitMap that happens to carry the private marker.
        Append(code, MoveAddressA0ToA1);
        for (var index = 0; index < 4; index++)
            Append(code, AddQuickFourLongA1); // public BitMap = base + 16
        // Keep the stored Exec size in D1 while recomputing the public geometry.
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveWordA1DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, MultiplyUnsignedWordD4ToD3);
        Append(code, AddImmediateLongD3);
        Append(code, 0);
        Append(code, 0x38);
        Append(code, CompareLongD3ToD1);
        Append(code, BranchNotEqualWord);
        var aggregateSpanBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(aggregateSpanBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, MoveAddressA1ToA0);
        for (var index = 0; index < 10; index++)
        {
            Append(code, AddQuickOneLongA0);
            Append(code, AddQuickOneLongA0);
            Append(code, AddQuickOneLongA0);
            Append(code, AddQuickOneLongA0);
        } // expected public BitMap + 0x28
        Append(code, MoveLongA0ToD0);
        Append(code, MoveLongD0ToD3);
        Append(code, MoveLongD2ToD0);
        Append(code, CompareLongD0ToD3);
        Append(code, BranchNotEqualWord);
        var planeMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeMismatchBranchExtensionOffset);

        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongA0ToD0);
        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, MoveLongD0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongA0ToD0); // restore private base for FreeMem
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x449C);
        Append(code, ReturnFromSubroutine);

        var nullBitMapOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x449C);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x449C);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, nullBitMapBranchExtensionOffset, nullBitMapOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendFreeBitMapNull(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;

        // FreeBitMap(NULL) is the successful empty teardown form.  Keep the
        // native body read-free and leave every non-NULL bitmap to the
        // instance ownership and CyberGraphX/provider boundary.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var fallbackBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, fallbackBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    private static int AppendFreeDBufInfoNull(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;

        // FreeDBufInfo(NULL) is a successful no-op.  Do not inspect a
        // DBufInfo envelope or its message ports here: non-NULL teardown
        // still belongs to the cancellation-aware portable/provider owner.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var fallbackBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, fallbackBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    private static int AppendAllocDBufInfoNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(12);

        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x3D02); // MOVEM.L D2-D5/D7/A6,-(A7), reversed save mask

        // AllocDBufInfo consumes only the ViewPort's public RasInfo link and
        // the extended-mode byte before asking Exec for a cleared DBufInfo.
        // Preserve the incoming D0 on every decline. A0 remains the caller's
        // ViewPort during preflight, but Exec may clobber volatile A0/A1.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullViewPortBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddViewPortBranchExtensionOffset);
        // Both fields below reside in the public 0x28-byte ViewPort
        // envelope.  A 32-bit wrap here could otherwise turn a malformed
        // high address into valid low-memory RasInfo state.
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // ViewPortSize (0x28) envelope
        Append(code, BranchHighWord);
        var wrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedViewPortBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestByteD4);
        Append(code, BranchNotEqualWord);
        var extendedModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(extendedModesBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullRasInfoBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRasInfoBranchExtensionOffset);
        // RasInfo contributes four scalar fields through offset 0x0A.  Keep
        // that complete public envelope inside the 32-bit guest range before
        // any A1 displacement can alias the low address space.
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // RasInfoSize (0x0C) envelope
        Append(code, BranchHighWord);
        var wrappedRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedRasInfoBranchExtensionOffset);
        Append(code, MoveAddressD4ToA1);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var linkedRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(linkedRasInfoBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoBitMap));
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoRxOffset));
        Append(code, MoveWordA1DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoRyOffset));

        // SysBase is the longword at absolute address four.  Keep the exact
        // complete allocation size in D5 for odd/wrapping-result rollback.
        // FreeDBufInfo uses the same fixed prefix-plus-public-structure span.
        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongImmediateD0);
        Append(code, 0);
        Append(code, checked((ushort)(GraphicsLayouts.DBufInfoSize + 4)));
        Append(code, MoveLongD0ToD5);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0001); // PUBLIC | CLEAR
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var allocationFailureBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        // The complete 88-byte private/public envelope may end at the last
        // guest byte, but must not wrap before any marker/message publication.
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFA8); // UINT32_MAX - (DBufInfoSize + 4 - 1)
        Append(code, BranchHighWord);
        var wrappedAllocationBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var skipAllocationCleanupBranchExtensionOffset = code.Count;
        Append(code, 0);

        var allocationCleanupOffset = code.Count;
        Append(code, MoveLongD5ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, BranchAlwaysWord);
        var allocationCleanupJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, NativeDBufInfoMarker);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 0);
        Append(code, AddQuickOneLongA0);
        Append(code, AddQuickOneLongA0);
        Append(code, AddQuickOneLongA0);
        Append(code, AddQuickOneLongA0);
        Append(code, MoveImmediateWordD0);
        Append(code, checked((ushort)GraphicsLayouts.ExecMessageSize));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)(GraphicsLayouts.DBufInfoSafeMessage + GraphicsLayouts.ExecMessageLength)));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)(GraphicsLayouts.DBufInfoDispMessage + GraphicsLayouts.ExecMessageLength)));
        Append(code, MoveLongA0ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40BC); // MOVEM.L (A7)+,D2-D5/D7/A6
        Append(code, ReturnFromSubroutine);

        var allocationFailureOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var allocationFailureJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x40BC);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, allocationFailureBranchExtensionOffset, allocationFailureOffset);
        PatchBranch(code, oddAllocationBranchExtensionOffset, allocationCleanupOffset);
        PatchBranch(code, wrappedAllocationBranchExtensionOffset, allocationCleanupOffset);
        PatchBranch(code, skipAllocationCleanupBranchExtensionOffset, successOffset);
        PatchBranch(code, allocationCleanupJoinBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, allocationFailureJoinBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendFreeDBufInfoNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(8);

        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x1102); // MOVEM.L D3/D7/A6,-(A7), reversed save mask

        Append(code, MoveLongD0ToD7);
        // The public DBufInfo argument is A1; A0 is only scratch after
        // admission, not an alternate handle supplied by the caller.
        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddInfoBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 4);
        // A NULL AllocMem result cannot own a private header at address zero.
        Append(code, BranchLowerOrSameWord);
        var shortInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(shortInfoBranchExtensionOffset);
        // Admit the full 84-byte public object before subtracting its private
        // prefix or reading the marker; the exact-end object remains valid.
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFAC); // UINT32_MAX - (DBufInfoSize - 1)
        Append(code, BranchHighWord);
        var wrappedInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedInfoBranchExtensionOffset);
        Append(code, SubImmediateLongD0);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, 0);
        Append(code, CompareImmediateWordD3);
        Append(code, NativeDBufInfoMarker);
        Append(code, BranchNotEqualWord);
        var markerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(markerBranchExtensionOffset);

        Append(code, MoveAddressA0ToA1);
        Append(code, MoveImmediateAddressToA6);
        Append(code, 0);
        Append(code, 4);
        Append(code, MoveLongA6IndirectToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullExecBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullExecBaseBranchExtensionOffset);
        Append(code, MoveAddressD0ToA6);
        Append(code, MoveLongA1ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, checked((ushort)(GraphicsLayouts.DBufInfoSize + 4)));
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x4088); // MOVEM.L (A7)+,D3/D7/A6
        Append(code, ReturnFromSubroutine);

        var nullInfoOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x4088);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x4088);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, nullInfoBranchExtensionOffset, nullInfoOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendFreeSpriteDataNull(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;

        // FreeSpriteData(NULL) is the documented idempotent V40 no-op.  The
        // public ExtSprite pointer is A2; do not inspect any image, plane, or
        // allocator state here.  Non-NULL handles remain on the ownership-
        // aware portable/provider path.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA2ToD4);
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var fallbackBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, fallbackBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    private static int AppendGfxLookUpNull(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;

        // GfxLookUp(NULL) is the documented empty-association query.  This
        // small native form must not inspect the compatibility registry: a
        // non-NULL key can belong to a resident library or provider-owned
        // association table and therefore remains on the shared fallback.
        // Preserve D0 for that decline exactly as the vector received it.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var fallbackBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, fallbackBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    private static int AppendFreeCopListEmpty(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(22);

        // FreeCopList's NULL head and a bounded, completely zeroed CopList
        // are read-only successful empty-list forms. Any linked, populated,
        // owner-associated, or provider-owned CopList remains on the
        // ownership-aware fallback so this body never releases storage it
        // cannot prove belongs to the native instance.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullListBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddListBranchExtensionOffset);

        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFCA); // CopList + 0x35 must remain addressable
        Append(code, BranchHighWord);
        var wrappedListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedListBranchExtensionOffset);

        // A zero-resource CopList has no chain, owner, instruction buffer,
        // cursor, or short/long copper starts. Keep every read inside the
        // public CopList envelope and reject any non-zero state.
        var longOffsets = new[]
        {
            GraphicsLayouts.CopListNext,
            GraphicsLayouts.CopListSystem,
            GraphicsLayouts.CopListViewPort,
            GraphicsLayouts.CopListCopIns,
            GraphicsLayouts.CopListCopPtr,
            GraphicsLayouts.CopListCopLStart,
            GraphicsLayouts.CopListCopSStart
        };
        foreach (var fieldOffset in longOffsets)
        {
            Append(code, MoveLongA0DisplacementToD0);
            Append(code, checked((ushort)fieldOffset));
            Append(code, TestLongD0);
            Append(code, BranchNotEqualWord);
            var fieldBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(fieldBranchExtensionOffset);
        }

        var wordOffsets = new[]
        {
            GraphicsLayouts.CopListCount,
            GraphicsLayouts.CopListMaxCount,
            GraphicsLayouts.CopListDyOffset,
            GraphicsLayouts.CopListCop2Start,
            GraphicsLayouts.CopListCop3Start,
            GraphicsLayouts.CopListCop4Start,
            GraphicsLayouts.CopListCop5Start,
            GraphicsLayouts.CopListSlRepeat,
            GraphicsLayouts.CopListFlags
        };
        foreach (var fieldOffset in wordOffsets)
        {
            Append(code, MoveWordA0DisplacementToD0);
            Append(code, checked((ushort)fieldOffset));
            Append(code, TestWordD0);
            Append(code, BranchNotEqualWord);
            var fieldBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(fieldBranchExtensionOffset);
        }

        var emptySuccessOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, nullListBranchExtensionOffset, emptySuccessOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendLoadViewEmpty(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(14);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void CheckEnvelopeAgainstVisibleViewPort(
            ushort envelopeLoadToD4,
            uint envelopeBytes)
        {
            // D2 is the visible ViewPort base and D0 its exclusive end. Keep
            // the half-open comparison so touching guest envelopes remain
            // valid while any View/ViewPort alias declines before admission.
            Append(code, MoveLongD0ToD3);
            Append(code, envelopeLoadToD4);
            Append(code, CompareLongD4ToD2); // viewport - envelope
            Append(code, BranchLowerOrSameWord);
            var viewportBeforeEnvelopeBranchExtensionOffset = code.Count;
            Append(code, 0);

            var envelopeBeforeViewportOffset = code.Count;
            Append(code, MoveLongD4ToD1);
            Append(code, AddImmediateLongD1);
            Append(code, (ushort)(envelopeBytes >> 16));
            Append(code, (ushort)envelopeBytes);
            Append(code, BranchCarryWord);
            var envelopeWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareLongD1ToD0); // viewport - envelopeEnd
            Append(code, BranchCarryWord);
            var envelopeOverlapsViewportBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BranchAlwaysWord);
            var viewportDisjointJoinBranchExtensionOffset = code.Count;
            Append(code, 0);

            var viewportBeforeEnvelopeOffset = code.Count;
            Append(code, CompareLongD0ToD4); // envelope - viewportEnd
            Append(code, BranchCarryWord);
            var viewportOverlapsEnvelopeBranchExtensionOffset = code.Count;
            Append(code, 0);

            var viewportDisjointJoinOffset = code.Count;
            PatchBranch(
                code,
                viewportBeforeEnvelopeBranchExtensionOffset,
                viewportBeforeEnvelopeOffset);
            PatchBranch(
                code,
                viewportDisjointJoinBranchExtensionOffset,
                viewportDisjointJoinOffset);
            Append(code, MoveLongD3ToD0);
            fallbackBranches.Add(envelopeWrapBranchExtensionOffset);
            fallbackBranches.Add(envelopeOverlapsViewportBranchExtensionOffset);
            fallbackBranches.Add(viewportOverlapsEnvelopeBranchExtensionOffset);
        }

        // Claim the smallest assembling-view lifecycle boundary. A NULL view
        // blanks the active-view field; a bounded, even View with NULL
        // ViewPort/LOF/SHF CPR links publishes that View as the active
        // assembling object without constructing display resources. Linked,
        // malformed, or provider-owned Views remain available to the full
        // display/provider owner.
        Append(code, MoveLongD0ToD7); // preserve the void-vector ABI on decline
        Append(code, MoveLongA1ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullViewSkipBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddViewBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFEE); // View + 0x11 must remain addressable
        Append(code, BranchHighWord);
        var wrappedViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedViewBranchExtensionOffset);

        // A non-NULL View may also carry a bounded hidden ViewPort chain while
        // it is being assembled.  LoadView's resident traversal consumes only
        // vp_Modes/vp_Next for hidden nodes; keep that read-only form native,
        // while visible or richer chains remain on the display owner.
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var emptyViewBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Admission starts with the complete ViewPort envelope.  Do this
        // before the hidden/visible split so an aliased visible ViewPort
        // cannot reach a richer arm merely because its mode word is empty.
        Append(code, MoveLongD0ToD2);
        Append(code, AddImmediateLongD0);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortSize));
        Append(code, BranchCarryWord);
        var viewPortEnvelopeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(viewPortEnvelopeWrapBranchExtensionOffset);
        Append(code, CompareLongD6ToD2); // viewport - root View
        Append(code, BranchEqualWord);
        var viewPortRootEqualBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(viewPortRootEqualBranchExtensionOffset);
        Append(code, BranchCarryWord);
        var viewPortBeforeRootBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD6ToD4);
        Append(code, MoveLongImmediateD1);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.ViewSize));
        Append(code, AddLongD1ToD4);
        Append(code, BranchCarryWord);
        var viewPortRootEndWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(viewPortRootEndWrapBranchExtensionOffset);
        Append(code, CompareLongD2ToD4); // root end - viewport
        Append(code, BranchHighWord);
        var viewPortRootOverlapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(viewPortRootOverlapBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var viewPortEnvelopeJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        var viewPortBeforeRootOffset = code.Count;
        Append(code, CompareLongD6ToD0); // viewport end - root
        Append(code, BranchHighWord);
        var rootOverlapsViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rootOverlapsViewPortBranchExtensionOffset);
        var viewPortEnvelopeJoinOffset = code.Count;
        PatchBranch(code, viewPortBeforeRootBranchExtensionOffset, viewPortBeforeRootOffset);
        PatchBranch(code, viewPortEnvelopeJoinBranchExtensionOffset, viewPortEnvelopeJoinOffset);
        Append(code, MoveLongD2ToD0);

        Append(code, MoveAddressD0ToA0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var hiddenViewPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(hiddenViewPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD at +0x20..+0x21 envelope
        Append(code, BranchHighWord);
        var hiddenViewPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(hiddenViewPortWrapBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var visibleViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var hiddenViewChainDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Admit one additional hidden node.  A successor beyond this bound,
        // or a visible/ill-formed second node, remains provider-owned.
        Append(code, MoveLongD1ToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var secondHiddenViewPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondHiddenViewPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var secondHiddenViewPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondHiddenViewPortWrapBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var secondVisibleViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleViewPortBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var secondHiddenViewChainDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var thirdHiddenViewPortEntryBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A third hidden node is admitted as another bounded link. Its
        // public mode/next pair is the complete native read envelope; a
        // visible or malformed node remains provider-owned. A fourth node is
        // admitted below as the terminal hidden form.
        var thirdHiddenViewPortOffset = code.Count;
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var thirdHiddenViewPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(thirdHiddenViewPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var thirdHiddenViewPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(thirdHiddenViewPortWrapBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var thirdHiddenViewPortVisibleBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(thirdHiddenViewPortVisibleBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var thirdHiddenViewPortSuccessorBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var thirdHiddenViewChainDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A fourth hidden node is another bounded link. Its public mode/next
        // pair is still the only guest state consumed here; a visible,
        // malformed, wrapped, or linked successor remains on the provider /
        // display owner. A fifth node is admitted below as the terminal form
        // so LoadView keeps the same bounded hidden-chain envelope as MrgCop.
        var fourthHiddenViewPortOffset = code.Count;
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fourthHiddenViewPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthHiddenViewPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var fourthHiddenViewPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthHiddenViewPortWrapBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var fourthHiddenViewPortVisibleBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthHiddenViewPortVisibleBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var fifthHiddenViewPortEntryBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var fourthHiddenViewChainDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A fifth hidden node is another bounded link. Its public mode/next
        // pair is the complete read envelope; odd, wrapped, or visible forms
        // retain the provider/display owner. A sixth node below is the
        // terminal form for this native chain slice.
        var fifthHiddenViewPortOffset = code.Count;
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fifthHiddenViewPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fifthHiddenViewPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var fifthHiddenViewPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fifthHiddenViewPortWrapBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var fifthHiddenViewPortVisibleBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fifthHiddenViewPortVisibleBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var sixthHiddenViewPortEntryBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var fifthHiddenViewChainDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A sixth hidden node is the next bounded native link. Its public
        // mode/next pair is the complete read envelope; odd, wrapped, or
        // visible forms retain the provider/display owner. A seventh node is
        // admitted below as the terminal hidden form.
        var sixthHiddenViewPortOffset = code.Count;
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var sixthHiddenViewPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sixthHiddenViewPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var sixthHiddenViewPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sixthHiddenViewPortWrapBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var sixthHiddenViewPortVisibleBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sixthHiddenViewPortVisibleBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var sixthHiddenViewPortLinkedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var sixthHiddenViewChainDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A seventh hidden node is another bounded native link. Its public
        // mode/next pair is the complete read envelope; odd, wrapped, or
        // visible forms retain the provider/display owner. An eighth node is
        // admitted below as the terminal hidden form.
        var seventhHiddenViewPortOffset = code.Count;
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var seventhHiddenViewPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(seventhHiddenViewPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var seventhHiddenViewPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(seventhHiddenViewPortWrapBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var seventhHiddenViewPortVisibleBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(seventhHiddenViewPortVisibleBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var seventhHiddenViewPortLinkedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var seventhHiddenViewChainDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        // An eighth hidden node remains a bounded native link. Its public
        // mode/next pair is the complete read envelope; a ninth terminal
        // node is admitted below without constructing display resources.
        var eighthHiddenViewPortOffset = code.Count;
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var eighthHiddenViewPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(eighthHiddenViewPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var eighthHiddenViewPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(eighthHiddenViewPortWrapBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var eighthHiddenViewPortVisibleBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(eighthHiddenViewPortVisibleBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var eighthHiddenViewPortLinkedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var eighthHiddenViewChainDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A ninth hidden node is the terminal native lifecycle cell. Its
        // public mode/next pair is the complete read envelope; odd, wrapped,
        // visible, or linked forms retain the provider/display owner.
        var ninthHiddenViewPortOffset = code.Count;
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var ninthHiddenViewPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ninthHiddenViewPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFDE); // vp_Modes WORD envelope
        Append(code, BranchHighWord);
        var ninthHiddenViewPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ninthHiddenViewPortWrapBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD1);
        Append(code, 13);
        Append(code, BranchEqualWord);
        var ninthHiddenViewPortVisibleBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ninthHiddenViewPortVisibleBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var ninthHiddenViewPortLinkedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ninthHiddenViewPortLinkedBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var ninthHiddenViewChainDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(
            code,
            seventhHiddenViewPortLinkedBranchExtensionOffset,
            eighthHiddenViewPortOffset);
        PatchBranch(
            code,
            eighthHiddenViewPortLinkedBranchExtensionOffset,
            ninthHiddenViewPortOffset);

        // A visible singleton is admitted as an assembling ViewPort with
        // either no copper resource or the exact preallocated blank envelope
        // emitted by MakeVPort.  Richer display/provider ownership remains on
        // the complete LoadView owner.
        var visibleViewPortValidationOffset = code.Count;
        // The native resident path consumes the complete visible ViewPort
        // envelope below. Reject a ViewPort that aliases the root View before
        // any of those fields can be interpreted as display state.
        Append(code, MoveWordD1ToD5); // preserve vp_Modes for the join below
        Append(code, MoveLongA0ToD2);
        Append(code, MoveLongD2ToD0);
        Append(code, AddImmediateLongD0);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortSize));
        Append(code, BranchCarryWord);
        var visibleViewPortSpanWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleViewPortSpanWrapBranchExtensionOffset);
        // Equal bases are the smallest alias form and are rejected
        // explicitly before the general half-open span comparison.
        Append(code, CompareLongD6ToD2);
        Append(code, BranchEqualWord);
        var visibleViewPortEqualAliasBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleViewPortEqualAliasBranchExtensionOffset);
        CheckEnvelopeAgainstVisibleViewPort(
            MoveLongD6ToD4,
            (uint)GraphicsLayouts.ViewSize);
        Append(code, MoveWordD5ToD1);
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var visibleModeBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Non-zero viewport modes are admitted only for the generated
        // standard-planar copper form.  The later generated arm repeats the
        // complete raw/geometry validation; this short gate prevents a
        // marker-only DspIns from claiming an interlace mode and keeps the
        // classic zero-mode assembling form unchanged.
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var visibleModeDspInsNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleModeDspInsNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var visibleModeDspInsOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleModeDspInsOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFCA);
        Append(code, BranchHighWord);
        var visibleModeDspInsRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleModeDspInsRangeBranchExtensionOffset);
        Append(code, MoveAddressD1ToA2);
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, CompareImmediateWordD1);
        Append(code, 12);
        Append(code, BranchNotEqualWord);
        var visibleModeDspInsCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleModeDspInsCountBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var visibleNonZeroModeJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var visibleZeroModeOffset = code.Count;
        PatchBranch(code, visibleModeBranchExtensionOffset, visibleZeroModeOffset);
        PatchBranch(code, visibleNonZeroModeJoinBranchExtensionOffset, visibleZeroModeOffset);
        Append(code, MoveQuickZeroD1);
        Append(code, MoveByteA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var visibleExtendedModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleExtendedModesBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDWidth));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var visibleWidthZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleWidthZeroBranchExtensionOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 4096);
        Append(code, BranchHighWord);
        var visibleWidthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleWidthRangeBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDHeight));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var visibleHeightZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleHeightZeroBranchExtensionOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 4096);
        Append(code, BranchHighWord);
        var visibleHeightRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleHeightRangeBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // ViewPortSize (0x28) envelope
        Append(code, BranchHighWord);
        var visibleViewPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleViewPortWrapBranchExtensionOffset);

        var visibleViewPortNullFields = new[]
        {
            GraphicsLayouts.ViewPortColorMap,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };
        foreach (var fieldOffset in visibleViewPortNullFields)
        {
            Append(code, MoveLongA0DisplacementToD1);
            Append(code, checked((ushort)fieldOffset));
            Append(code, TestLongD1);
            Append(code, BranchNotEqualWord);
            var fieldBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(fieldBranchExtensionOffset);
        }

        // A preallocated blank DspIns may accompany this single visible
        // viewport.  Keep the admission read-only and transactional: the
        // CopList must point back to this ViewPort, expose one shared even raw
        // stream through CopPtr/CopLStart/CopSStart, have Count==0 and a
        // positive MaxCount, and begin with the canonical copper terminator.
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var visibleDspInsNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var visibleDspInsOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFCA); // CopListSize (0x36) envelope
        Append(code, BranchHighWord);
        var visibleDspInsRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsRangeBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var visibleDspInsRasInfoNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsRasInfoNullBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var visibleDspInsRasInfoOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsRasInfoOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD2);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // RasInfoSize (0x0C) envelope
        Append(code, BranchHighWord);
        var visibleDspInsRasInfoRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsRasInfoRangeBranchExtensionOffset);
        Append(code, MoveAddressD1ToA2);
        Append(code, MoveLongA0ToD2); // retain the ViewPort backlink target
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
        Append(code, CompareLongD6ToD2);
        Append(code, BranchNotEqualWord);
        var visibleDspInsViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsViewPortBranchExtensionOffset);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var visibleDspInsCopPtrNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsCopPtrNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var visibleDspInsCopPtrOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsCopPtrOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // raw terminator envelope
        Append(code, BranchHighWord);
        var visibleDspInsCopPtrRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsCopPtrRangeBranchExtensionOffset);
        Append(code, MoveLongD6ToD0); // compare all starts to the raw pointer
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopLStart));
        Append(code, CompareLongD6ToD0);
        Append(code, BranchNotEqualWord);
        var visibleDspInsLofStartBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsLofStartBranchExtensionOffset);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopSStart));
        Append(code, CompareLongD6ToD0);
        Append(code, BranchNotEqualWord);
        var visibleDspInsShfStartBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsShfStartBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, CompareImmediateWordD1);
        Append(code, 12);
        Append(code, BranchEqualWord);
        var visibleDspInsGeneratedEntryBranchExtensionOffset = code.Count;
        Append(code, 0);
        // The Exec-backed display-resource allocator emits a deliberately
        // tiny marker-only CopList (two raw terminator words).  Admit that
        // form here only when its private ownership marker and embedded
        // Screen identity are intact; all other Count==2/foreign forms stay
        // on the provider-owned fallback path.
        Append(code, CompareImmediateWordD1);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var visibleDspInsNativeEntryBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, TestWordD1);
        Append(code, BranchNotEqualWord);
        var visibleDspInsCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsCountBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var visibleDspInsCapacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsCapacityBranchExtensionOffset);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, GraphicsLayouts.CopperEndWait);
        Append(code, BranchNotEqualWord);
        var visibleDspInsWaitBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsWaitBranchExtensionOffset);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, 2);
        Append(code, CompareImmediateWordD4);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, BranchNotEqualWord);
        var visibleDspInsMaskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsMaskBranchExtensionOffset);

        // Count==12 selects the exact bounded standard-planar program emitted
        // by MakeVPort. Admit the marker-only Count==2 arm above only after
        // checking its ownership tag and Screen identity. The generated and
        // marker paths rejoin the common RasInfo/CPR validation below.
        Append(code, BranchAlwaysWord);
        var visibleDspInsMarkerJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        var visibleDspInsNativeValidationOffset = code.Count;
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListFlags));
        Append(code, CompareImmediateWordD1);
        Append(code, NativeDisplayResourceMarker);
        Append(code, BranchNotEqualWord);
        var visibleDspInsNativeMarkerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsNativeMarkerBranchExtensionOffset);
        // The native allocator stores Screen in CopList.System.  At this
        // point D2 still holds the current ViewPort; its enclosing Screen is
        // the fixed ScreenViewPort prefix immediately before it. Preserve the
        // raw stream pointer in D4 while deriving and checking that identity.
        Append(code, MoveLongD0ToD4);
        Append(code, MoveLongD2ToD0);
        Append(code, SubImmediateLongD0);
        Append(code, 0x0000);
        Append(code, checked((ushort)GraphicsLayouts.ScreenViewPort));
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.CopListSystem));
        Append(code, CompareLongD6ToD0);
        Append(code, BranchNotEqualWord);
        var visibleDspInsNativeSystemBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsNativeSystemBranchExtensionOffset);
        Append(code, MoveLongD4ToD0);
        Append(code, BranchAlwaysWord);
        var visibleDspInsNativeJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        var visibleDspInsGeneratedValidationOffset = code.Count;
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD1);
        Append(code, 11);
        Append(code, BranchLowerOrSameWord);
        var visibleDspInsGeneratedCapacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsGeneratedCapacityBranchExtensionOffset);
        Append(code, MoveLongD0ToD6); // raw pointer remains in D0
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD0); // twelve instructions occupy 48 bytes
        Append(code, BranchHighWord);
        var visibleDspInsGeneratedRawRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleDspInsGeneratedRawRangeBranchExtensionOffset);

        var generatedCopperChecks = new[]
        {
            (Offset: 0, Value: (ushort)0x008E),
            (Offset: 2, Value: (ushort)0x2C81),
            (Offset: 4, Value: (ushort)0x0090),
