            code,
            visibleRasInfoBeforeViewPortBranchExtensionOffset,
            visibleRasInfoDisjointOffset);
        PatchBranch(
            code,
            visibleViewPortBeforeRasInfoBranchExtensionOffset,
            visibleRasInfoDisjointOffset);
        Append(code, MoveLongD4ToD1); // restore RasInfo pointer
        Append(code, MoveAddressD1ToA2);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var visibleRasInfoNextBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleRasInfoNextBranchExtensionOffset);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoBitMap));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var visibleRasInfoBitMapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleRasInfoBitMapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var visibleRasInfoBitMapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleRasInfoBitMapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var visibleRasInfoBitMapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleRasInfoBitMapRangeBranchExtensionOffset);

        // A bitmap is a public envelope of its own.  Keep the native
        // assembling arm from interpreting a BitMap that aliases the root
        // View, the selected ViewPort, or the RasInfo node that supplied it.
        // The pointer in D6 remains untouched so the existing geometry and
        // plane checks can consume it after all three half-open span proofs.
        Append(code, MoveLongD6ToD0); // BitMap end
        Append(code, AddImmediateLongD0);
        Append(code, 0);
        Append(code, checked((ushort)GraphicsLayouts.BitMapSize));
        Decline(BranchCarryWord);

        void RejectBitmapOverlapWith(ushort loadStart, ushort envelopeSize)
        {
            Append(code, loadStart); // candidate envelope start -> D1
            Append(code, MoveLongD1ToD2); // candidate envelope end -> D2
            Append(code, AddImmediateLongD2);
            Append(code, 0);
            Append(code, envelopeSize);
            Decline(BranchCarryWord);

            // If candidate end <= bitmap base, the spans are disjoint.  If
            // bitmap end <= candidate start, they are disjoint as well;
            // otherwise the two half-open envelopes overlap and decline.
            Append(code, CompareLongD6ToD2); // candidate end - bitmap base
            Append(code, BranchLowerOrSameWord);
            var candidateBeforeBitmapJoinBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareLongD0ToD1); // candidate start - bitmap end
            Append(code, BranchCarryWord);
            var bitmapOverlapsCandidateBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(bitmapOverlapsCandidateBranchExtensionOffset);
            var candidateBeforeBitmapJoinOffset = code.Count;
            PatchBranch(
                code,
                candidateBeforeBitmapJoinBranchExtensionOffset,
                candidateBeforeBitmapJoinOffset);
        }

        void AppendVisibleRasInfoDisjointProof()
        {
            // Keep the candidate RasInfo base in D3.  The proof itself uses
            // D0/D1/D2/D4, leaving D1 restored for the existing A2 read and
            // D3 available to the following BitMap envelope proof.
            Append(code, MoveLongD1ToD3);
            Append(code, MoveLongD1ToD0);
            Append(code, AddImmediateLongD0);
            Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.RasInfoSize);
            Decline(BranchCarryWord);

            Append(code, MoveLongA1ToD1); // root View base
            Append(code, MoveLongD1ToD2);
            Append(code, AddImmediateLongD2);
            Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.ViewSize); // root View end
            Decline(BranchCarryWord);
            Append(code, CompareLongD1ToD0); // RasInfo end - root base
            Append(code, BranchLowerOrSameWord);
            var rasInfoBeforeRootDisjointBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveLongD3ToD4);
            Append(code, CompareLongD4ToD2); // root end - RasInfo base
            Append(code, BranchLowerOrSameWord);
            var rootBeforeRasInfoDisjointBranchExtensionOffset = code.Count;
            Append(code, 0);
            Decline(BranchAlwaysWord);

            var rasInfoRootDisjointOffset = code.Count;
            PatchBranch(
                code,
                rasInfoBeforeRootDisjointBranchExtensionOffset,
                rasInfoRootDisjointOffset);
            PatchBranch(
                code,
                rootBeforeRasInfoDisjointBranchExtensionOffset,
                rasInfoRootDisjointOffset);

            Append(code, MoveLongA0ToD1); // selected ViewPort base
            Append(code, MoveLongD1ToD2);
            Append(code, AddImmediateLongD2);
            Append(code, 0);
            Append(code, (ushort)GraphicsLayouts.ViewPortSize); // viewport end
            Decline(BranchCarryWord);
            Append(code, CompareLongD1ToD0); // RasInfo end - viewport base
            Append(code, BranchLowerOrSameWord);
            var rasInfoBeforeViewPortDisjointBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveLongD3ToD4);
            Append(code, CompareLongD4ToD2); // viewport end - RasInfo base
            Append(code, BranchLowerOrSameWord);
            var viewPortBeforeRasInfoDisjointBranchExtensionOffset = code.Count;
            Append(code, 0);
            Decline(BranchAlwaysWord);

            var rasInfoViewPortDisjointOffset = code.Count;
            PatchBranch(
                code,
                rasInfoBeforeViewPortDisjointBranchExtensionOffset,
                rasInfoViewPortDisjointOffset);
            PatchBranch(
                code,
                viewPortBeforeRasInfoDisjointBranchExtensionOffset,
                rasInfoViewPortDisjointOffset);
            Append(code, MoveLongD3ToD1); // restore RasInfo pointer
        }

        RejectBitmapOverlapWith(
            MoveLongA1ToD1,
            checked((ushort)GraphicsLayouts.ViewSize));
        RejectBitmapOverlapWith(
            MoveLongA0ToD1,
            checked((ushort)GraphicsLayouts.ViewPortSize));
        RejectBitmapOverlapWith(
            MoveLongD4ToD1,
            checked((ushort)GraphicsLayouts.RasInfoSize));

        Append(code, MoveAddressD6ToA3);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var visibleRasInfoStrideZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleRasInfoStrideZeroBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var visibleRasInfoStrideOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleRasInfoStrideOddBranchExtensionOffset);
        Append(code, MoveByteA3DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD3);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var visibleRasInfoDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleRasInfoDepthBranchExtensionOffset);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var visibleRasInfoRowsZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleRasInfoRowsZeroBranchExtensionOffset);
        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var visibleRasInfoPlaneNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleRasInfoPlaneNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var visibleRasInfoPlaneOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleRasInfoPlaneOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // first row plus the bounded second byte
        Append(code, BranchHighWord);
        var visibleRasInfoPlaneRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleRasInfoPlaneRangeBranchExtensionOffset);
        var visibleRasInfoValidationEndOffset = code.Count;
        PatchBranch(
            code,
            visibleRasInfoNullBranchExtensionOffset,
            visibleRasInfoValidationEndOffset);

        // A visible assembling ViewPort may be followed by one additional
        // visible empty node.  The first node has already passed the complete
        // geometry/link envelope above; this bounded extension follows its
        // successor and requires the second node's Next/RasInfo/display links
        // to remain NULL.  Richer chains remain on the lifecycle owner.
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var visibleSuccessorNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var visibleSuccessorOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleSuccessorOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // ViewPortSize (0x28) envelope
        Append(code, BranchHighWord);
        var visibleSuccessorWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(visibleSuccessorWrapBranchExtensionOffset);
        Append(code, MoveAddressD0ToA0);
        Append(code, BranchAlwaysWord);
        var visibleSuccessorValidationJumpExtensionOffset = code.Count;
        Append(code, 0);

        var visibleSuccessorSkipValidationOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var visibleSuccessorSkipValidationJumpExtensionOffset = code.Count;
        Append(code, 0);
        var secondVisibleViewPortValidationOffset = code.Count;
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var secondVisibleViewPortModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleViewPortModesBranchExtensionOffset);
        Append(code, MoveQuickZeroD1);
        Append(code, MoveByteA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var secondVisibleViewPortExtendedModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleViewPortExtendedModesBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDWidth));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var secondVisibleViewPortWidthZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleViewPortWidthZeroBranchExtensionOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 4096);
        Append(code, BranchHighWord);
        var secondVisibleViewPortWidthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleViewPortWidthRangeBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDHeight));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var secondVisibleViewPortHeightZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleViewPortHeightZeroBranchExtensionOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 4096);
        Append(code, BranchHighWord);
        var secondVisibleViewPortHeightRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleViewPortHeightRangeBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, MoveLongD1ToD5);

        var secondVisibleViewPortNullFields = new[]
        {
            GraphicsLayouts.ViewPortColorMap,
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };
        foreach (var fieldOffset in secondVisibleViewPortNullFields)
        {
            Append(code, MoveLongA0DisplacementToD1);
            Append(code, checked((ushort)fieldOffset));
            Append(code, TestLongD1);
            Append(code, BranchNotEqualWord);
            var fieldBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(fieldBranchExtensionOffset);
        }

        // The successor may carry one complete standard-planar RasInfo node,
        // matching the first visible node's strict display topology.  NULL
        // remains the ordinary assembling form; linked, malformed, and
        // multi-plane/empty bitmap forms stay on the complete owner.
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var secondVisibleRasInfoNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var secondVisibleRasInfoOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleRasInfoOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // RasInfoSize (0x0C) envelope
        Append(code, BranchHighWord);
        var secondVisibleRasInfoRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleRasInfoRangeBranchExtensionOffset);
        AppendVisibleRasInfoDisjointProof();
        Append(code, MoveAddressD1ToA2);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var secondVisibleRasInfoNextBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleRasInfoNextBranchExtensionOffset);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoBitMap));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var secondVisibleRasInfoBitMapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleRasInfoBitMapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var secondVisibleRasInfoBitMapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleRasInfoBitMapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var secondVisibleRasInfoBitMapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleRasInfoBitMapRangeBranchExtensionOffset);
        RejectBitmapOverlapWith(
            MoveLongA1ToD1,
            checked((ushort)GraphicsLayouts.ViewSize));
        RejectBitmapOverlapWith(
            MoveLongA0ToD1,
            checked((ushort)GraphicsLayouts.ViewPortSize));
        RejectBitmapOverlapWith(
            MoveLongD3ToD1,
            checked((ushort)GraphicsLayouts.RasInfoSize));
        Append(code, MoveAddressD6ToA3);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var secondVisibleRasInfoStrideZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleRasInfoStrideZeroBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var secondVisibleRasInfoStrideOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleRasInfoStrideOddBranchExtensionOffset);
        Append(code, MoveByteA3DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD3);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var secondVisibleRasInfoDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleRasInfoDepthBranchExtensionOffset);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var secondVisibleRasInfoRowsZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleRasInfoRowsZeroBranchExtensionOffset);
        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var secondVisibleRasInfoPlaneNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleRasInfoPlaneNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var secondVisibleRasInfoPlaneOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleRasInfoPlaneOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // first row plus the bounded second byte
        Append(code, BranchHighWord);
        var secondVisibleRasInfoPlaneRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondVisibleRasInfoPlaneRangeBranchExtensionOffset);

        var secondVisibleViewPortValidationEndOffset = code.Count;

        // If the second visible node has a successor, validate one or two
        // terminal empty successors. Keep the third pointer in D5 while the
        // complete second-node envelope above reuses D1/D6/A2/A3.
        Append(code, MoveLongD5ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var thirdVisibleViewPortSkipBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var thirdVisibleViewPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(thirdVisibleViewPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // ViewPortSize (0x28) envelope
        Append(code, BranchHighWord);
        var thirdVisibleViewPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(thirdVisibleViewPortWrapBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var thirdVisibleViewPortModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(thirdVisibleViewPortModesBranchExtensionOffset);
        Append(code, MoveQuickZeroD1);
        Append(code, MoveByteA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var thirdVisibleViewPortExtendedModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(thirdVisibleViewPortExtendedModesBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDWidth));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var thirdVisibleViewPortWidthZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(thirdVisibleViewPortWidthZeroBranchExtensionOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 4096);
        Append(code, BranchHighWord);
        var thirdVisibleViewPortWidthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(thirdVisibleViewPortWidthRangeBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDHeight));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var thirdVisibleViewPortHeightZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(thirdVisibleViewPortHeightZeroBranchExtensionOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 4096);
        Append(code, BranchHighWord);
        var thirdVisibleViewPortHeightRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(thirdVisibleViewPortHeightRangeBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, MoveLongD1ToD5);
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var thirdVisibleViewPortNoFourthBranchExtensionOffset = code.Count;
        Append(code, 0);
        var thirdVisibleViewPortNullFields = new[]
        {
            GraphicsLayouts.ViewPortColorMap,
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns,
            GraphicsLayouts.ViewPortRasInfo
        };
        foreach (var fieldOffset in thirdVisibleViewPortNullFields)
        {
            Append(code, MoveLongA0DisplacementToD1);
            Append(code, checked((ushort)fieldOffset));
            Append(code, TestLongD1);
            Append(code, BranchNotEqualWord);
            var fieldBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(fieldBranchExtensionOffset);
        }

        // A third visible node may itself point to one terminal fourth empty
        // node. The fourth node is guarded by the same read-only geometry and
        // NULL-resource envelope; richer or linked forms remain fallback-
        // owned. D5 retains the fourth pointer across the third-node reads.
        Append(code, MoveLongD5ToD1);
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fourthVisibleViewPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleViewPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // ViewPortSize (0x28) envelope
        Append(code, BranchHighWord);
        var fourthVisibleViewPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleViewPortWrapBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fourthVisibleViewPortModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleViewPortModesBranchExtensionOffset);
        Append(code, MoveQuickZeroD1);
        Append(code, MoveByteA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var fourthVisibleViewPortExtendedModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleViewPortExtendedModesBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDWidth));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var fourthVisibleViewPortWidthZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleViewPortWidthZeroBranchExtensionOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 4096);
        Append(code, BranchHighWord);
        var fourthVisibleViewPortWidthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleViewPortWidthRangeBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDHeight));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var fourthVisibleViewPortHeightZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleViewPortHeightZeroBranchExtensionOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 4096);
        Append(code, BranchHighWord);
        var fourthVisibleViewPortHeightRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleViewPortHeightRangeBranchExtensionOffset);
        var fourthVisibleViewPortNullFields = new[]
        {
            GraphicsLayouts.ViewPortColorMap,
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns
        };
        foreach (var fieldOffset in fourthVisibleViewPortNullFields)
        {
            Append(code, MoveLongA0DisplacementToD1);
            Append(code, checked((ushort)fieldOffset));
            Append(code, TestLongD1);
            Append(code, BranchNotEqualWord);
            var fieldBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(fieldBranchExtensionOffset);
        }

        // A terminal fourth visible node may carry the same single
        // standard-planar RasInfo/BitMap prefix as the earlier visible cells.
        // Keep the optional topology read-only and bounded: a linked RasInfo,
        // malformed bitmap, or multi-plane storage remains on the complete
        // lifecycle/provider owner.
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var fourthVisibleRasInfoNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fourthVisibleRasInfoOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleRasInfoOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // RasInfoSize (0x0C) envelope
        Append(code, BranchHighWord);
        var fourthVisibleRasInfoRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleRasInfoRangeBranchExtensionOffset);
        AppendVisibleRasInfoDisjointProof();
        Append(code, MoveAddressD1ToA2);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var fourthVisibleRasInfoNextBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleRasInfoNextBranchExtensionOffset);
        Append(code, MoveLongA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoBitMap));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var fourthVisibleRasInfoBitMapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleRasInfoBitMapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fourthVisibleRasInfoBitMapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleRasInfoBitMapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var fourthVisibleRasInfoBitMapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleRasInfoBitMapRangeBranchExtensionOffset);
        Append(code, MoveAddressD6ToA3);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var fourthVisibleRasInfoStrideZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleRasInfoStrideZeroBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fourthVisibleRasInfoStrideOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleRasInfoStrideOddBranchExtensionOffset);
        Append(code, MoveByteA3DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD3);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var fourthVisibleRasInfoDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleRasInfoDepthBranchExtensionOffset);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var fourthVisibleRasInfoRowsZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleRasInfoRowsZeroBranchExtensionOffset);
        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var fourthVisibleRasInfoPlaneNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleRasInfoPlaneNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fourthVisibleRasInfoPlaneOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleRasInfoPlaneOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // first row plus the bounded second byte
        Append(code, BranchHighWord);
        var fourthVisibleRasInfoPlaneRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fourthVisibleRasInfoPlaneRangeBranchExtensionOffset);

        // The fourth node may point at one final empty visible node.  Keep
        // the fourth RasInfo/BitMap validation above intact, then dispatch on
        // its public Next link before the shared chain-validation end.
        var fourthVisibleRasInfoValidationEndOffset = code.Count;
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var fourthVisibleViewPortNoFifthBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fifthVisibleViewPortValidationOffset = code.Count;
        Append(code, MoveAddressD1ToA0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fifthVisibleViewPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fifthVisibleViewPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // ViewPortSize (0x28) envelope
        Append(code, BranchHighWord);
        var fifthVisibleViewPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fifthVisibleViewPortWrapBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fifthVisibleViewPortModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fifthVisibleViewPortModesBranchExtensionOffset);
        Append(code, MoveQuickZeroD1);
        Append(code, MoveByteA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var fifthVisibleViewPortExtendedModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fifthVisibleViewPortExtendedModesBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDWidth));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var fifthVisibleViewPortWidthZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fifthVisibleViewPortWidthZeroBranchExtensionOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 4096);
        Append(code, BranchHighWord);
        var fifthVisibleViewPortWidthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fifthVisibleViewPortWidthRangeBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDHeight));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var fifthVisibleViewPortHeightZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fifthVisibleViewPortHeightZeroBranchExtensionOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 4096);
        Append(code, BranchHighWord);
        var fifthVisibleViewPortHeightRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fifthVisibleViewPortHeightRangeBranchExtensionOffset);
        var fifthVisibleViewPortNullFields = new[]
        {
            GraphicsLayouts.ViewPortNext,
            GraphicsLayouts.ViewPortColorMap,
            GraphicsLayouts.ViewPortDspIns,
            GraphicsLayouts.ViewPortSprIns,
            GraphicsLayouts.ViewPortClrIns,
            GraphicsLayouts.ViewPortUCopIns,
            GraphicsLayouts.ViewPortRasInfo
        };
        foreach (var fieldOffset in fifthVisibleViewPortNullFields)
        {
            Append(code, MoveLongA0DisplacementToD1);
            Append(code, checked((ushort)fieldOffset));
            Append(code, TestLongD1);
            Append(code, BranchNotEqualWord);
            var fieldBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(fieldBranchExtensionOffset);
        }

        var fifthVisibleViewPortValidationEndOffset = code.Count;
        var fourthVisibleViewPortValidationEndOffset = fifthVisibleViewPortValidationEndOffset;
        var thirdVisibleViewPortValidationEndOffset = fourthVisibleViewPortValidationEndOffset;
        PatchBranch(
            code,
            secondVisibleRasInfoNullBranchExtensionOffset,
            secondVisibleViewPortValidationEndOffset);
        PatchBranch(
            code,
            thirdVisibleViewPortNoFourthBranchExtensionOffset,
            thirdVisibleViewPortValidationEndOffset);
        PatchBranch(
            code,
            visibleSuccessorNullBranchExtensionOffset,
            visibleSuccessorSkipValidationOffset);
        PatchBranch(
            code,
            visibleSuccessorValidationJumpExtensionOffset,
            secondVisibleViewPortValidationOffset);
        PatchBranch(
            code,
            visibleSuccessorSkipValidationJumpExtensionOffset,
            thirdVisibleViewPortValidationEndOffset);
        PatchBranch(
            code,
            fourthVisibleRasInfoNullBranchExtensionOffset,
            fourthVisibleRasInfoValidationEndOffset);
        PatchBranch(
            code,
            fourthVisibleViewPortNoFifthBranchExtensionOffset,
            fourthVisibleViewPortValidationEndOffset);

        var viewPortChainValidationEndOffset = thirdVisibleViewPortValidationEndOffset;
        PatchBranch(code, visibleViewPortBranchExtensionOffset, visibleViewPortValidationOffset);
        PatchBranch(
            code,
            secondVisibleViewPortBranchExtensionOffset,
            secondVisibleViewPortValidationOffset);
        PatchBranch(
            code,
            hiddenViewChainDoneBranchExtensionOffset,
            viewPortChainValidationEndOffset);
        PatchBranch(
            code,
            secondHiddenViewChainDoneBranchExtensionOffset,
            viewPortChainValidationEndOffset);
        PatchBranch(
            code,
            thirdHiddenViewPortEntryBranchExtensionOffset,
            thirdHiddenViewPortOffset);
        PatchBranch(
            code,
            thirdHiddenViewPortSuccessorBranchExtensionOffset,
            fourthHiddenViewPortOffset);
        PatchBranch(
            code,
            fifthHiddenViewPortEntryBranchExtensionOffset,
            fifthHiddenViewPortOffset);
        PatchBranch(
            code,
            sixthHiddenViewPortEntryBranchExtensionOffset,
            sixthHiddenViewPortOffset);
        PatchBranch(
            code,
            sixthHiddenViewPortLinkedBranchExtensionOffset,
            seventhHiddenViewPortOffset);
        PatchBranch(
            code,
            thirdHiddenViewChainDoneBranchExtensionOffset,
            viewPortChainValidationEndOffset);
        PatchBranch(
            code,
            fourthHiddenViewChainDoneBranchExtensionOffset,
            viewPortChainValidationEndOffset);
        PatchBranch(
            code,
            sixthHiddenViewChainDoneBranchExtensionOffset,
            viewPortChainValidationEndOffset);
        PatchBranch(
            code,
            seventhHiddenViewChainDoneBranchExtensionOffset,
            viewPortChainValidationEndOffset);
        PatchBranch(
            code,
            eighthHiddenViewChainDoneBranchExtensionOffset,
            viewPortChainValidationEndOffset);
        PatchBranch(
            code,
            ninthHiddenViewChainDoneBranchExtensionOffset,
            viewPortChainValidationEndOffset);
        PatchBranch(
            code,
            fifthHiddenViewChainDoneBranchExtensionOffset,
            viewPortChainValidationEndOffset);
        PatchBranch(
            code,
            emptyViewBranchExtensionOffset,
            viewPortChainValidationEndOffset);

        // A NULL ViewPort is the ordinary empty assembling form.  LOF/SHF
        // CPR links remain NULL there; a singleton visible ViewPort may carry
        // the two preallocated wrappers that share the already-admitted raw
        // stream. Hidden, linked, split, or provider-owned forms retain the
        // NULL-only envelope below.
        void AppendPreallocatedCprValidation()
        {
            Append(code, BitTestImmediateD0);
            Append(code, 0);
            Append(code, BranchNotEqualWord);
            var oddBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(oddBranchExtensionOffset);
            Append(code, CompareImmediateLongD0);
            Append(code, 0xFFFF);
            Append(code, 0xFFF4); // CprListSize (0x0C) envelope
            Append(code, BranchHighWord);
            var rangeBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(rangeBranchExtensionOffset);
            Append(code, MoveAddressD0ToA2);
            Append(code, MoveLongA2DisplacementToD6);
            Append(code, checked((ushort)GraphicsLayouts.CprListStart));
            Append(code, TestLongD6);
            Append(code, BranchEqualWord);
            var startNullBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(startNullBranchExtensionOffset);
            Append(code, BitTestImmediateD6);
            Append(code, 0);
            Append(code, BranchNotEqualWord);
            var startOddBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(startOddBranchExtensionOffset);
            Append(code, CompareImmediateLongD6);
            Append(code, 0xFFFF);
            Append(code, 0xFFFC); // raw start envelope
            Append(code, BranchHighWord);
            var startRangeBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(startRangeBranchExtensionOffset);
            Append(code, CompareLongD6ToD2);
            Append(code, BranchNotEqualWord);
            var startMismatchBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(startMismatchBranchExtensionOffset);
            Append(code, MoveWordA2DisplacementToD1);
            Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
            Append(code, TestWordD1);
            Append(code, BranchEqualWord);
            var capacityBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(capacityBranchExtensionOffset);
            Append(code, MoveLongA2DisplacementToD1);
            Append(code, checked((ushort)GraphicsLayouts.CprListNext));
            Append(code, TestLongD1);
            Append(code, BranchNotEqualWord);
            var nextBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(nextBranchExtensionOffset);
        }

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var cprNullOnlyFromNullViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, BitTestImmediateD3);
        Append(code, 13);
        Append(code, BranchNotEqualWord);
        var cprNullOnlyFromHiddenViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortNext));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var cprNullOnlyFromLinkedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var cprNullOnlyFromEmptyDspInsBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD1ToA2);
        Append(code, MoveLongA2DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var cprResourceInvalidBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(cprResourceInvalidBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var cprRawOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(cprRawOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var cprRawRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(cprRawRangeBranchExtensionOffset);
        Append(code, MoveLongD0ToD2);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewLoFCprList));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var cprLoFNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        AppendPreallocatedCprValidation();
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewShFCprList));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var cprShFRequiredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(cprShFRequiredBranchExtensionOffset);
        AppendPreallocatedCprValidation();
        Append(code, BranchAlwaysWord);
        var cprPairSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);

        var cprLoFNullOffset = code.Count;
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewShFCprList));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var cprShFUnexpectedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(cprShFUnexpectedBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var cprNullOnlySuccessBranchExtensionOffset = code.Count;
        Append(code, 0);

        var viewValidationEndOffset = code.Count;
        PatchBranch(code, cprNullOnlyFromNullViewBranchExtensionOffset, cprLoFNullOffset);
        PatchBranch(code, cprNullOnlyFromHiddenViewBranchExtensionOffset, cprLoFNullOffset);
        PatchBranch(code, cprNullOnlyFromLinkedViewPortBranchExtensionOffset, cprLoFNullOffset);
        PatchBranch(code, cprNullOnlyFromEmptyDspInsBranchExtensionOffset, cprLoFNullOffset);
        PatchBranch(code, cprLoFNullBranchExtensionOffset, cprLoFNullOffset);
        PatchBranch(code, cprPairSuccessBranchExtensionOffset, viewValidationEndOffset);
        PatchBranch(code, cprNullOnlySuccessBranchExtensionOffset, viewValidationEndOffset);
        PatchBranch(code, nullViewSkipBranchExtensionOffset, viewValidationEndOffset);

        // Preserve the validated A1 View pointer while A1 is rebound to the
        // native GfxBase for the publication store below.  A NULL A1 remains
        // the blanking form; a non-NULL empty View must publish its own guest
        // address rather than being collapsed into the NULL result.
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveLongA6ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var baseNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(baseNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var baseOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(baseOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFDA); // GfxBase + 0x22 must leave a four-byte field
        Append(code, BranchHighWord);
        var baseRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(baseRangeBranchExtensionOffset);

        // Reading the public field keeps a malformed/unmapped native base
        // outside this body before the publication store.  The value itself
        // is intentionally ignored; the A1 form below selects either the
        // NULL blank result or the validated non-NULL assembling View.
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseActiView));
        Append(code, MoveLongA6ToD6);
        Append(code, MoveAddressD6ToA1);

        Append(code, MoveLongA0ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullActiveViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseActiView));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var nullActiveViewOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseActiView));
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, nullActiveViewBranchExtensionOffset, nullActiveViewOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendMakeVPortNoViewPortExtraStatus(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(18);

        // MakeVPort returns MVP_NO_VPE for a NULL View or ViewPort before
        // touching guest memory or invoking copper construction.  The same
        // status is also the portable result for a completely addressable
        // viewport that is still being assembled with a NULL RasInfo. Claim
        // only those read-only failure forms; malformed envelopes and any
        // resource-bearing viewport remain available to the complete
        // validation/provider owner.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullViewBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddViewBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFEE); // ViewSize (0x12) envelope
        Append(code, BranchHighWord);
        var wrappedViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedViewBranchExtensionOffset);

        // Read the complete public View envelope consumed by the portable
        // MakeVPort validator. These reads are side-effect free; an
        // unmapped/truncated View remains on the provider path.
        // Requiring the View's public ViewPort link to name A1 keeps an
        // otherwise unmapped/sparse pair on the complete owner. MakeVPort's
        // portable path accepts a detached View, but this native read-only
        // status arm deliberately claims only the linked assembling form.
        Append(code, MoveLongA1ToD2);
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, CompareLongD2ToD4);
        Append(code, BranchNotEqualWord);
        var detachedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(detachedViewPortBranchExtensionOffset);

        var viewLongOffsets = new[]
        {
            GraphicsLayouts.ViewLoFCprList,
            GraphicsLayouts.ViewShFCprList
        };
        foreach (var fieldOffset in viewLongOffsets)
        {
            Append(code, MoveLongA0DisplacementToD4);
            Append(code, checked((ushort)fieldOffset));
        }

        var viewWordOffsets = new[]
        {
            GraphicsLayouts.ViewDyOffset,
            GraphicsLayouts.ViewDxOffset,
            GraphicsLayouts.ViewModes
        };
        foreach (var fieldOffset in viewWordOffsets)
        {
            Append(code, MoveWordA0DisplacementToD4);
            Append(code, checked((ushort)fieldOffset));
        }

        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddViewPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // ViewPortSize (0x28) envelope
        Append(code, BranchHighWord);
        var wrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedViewPortBranchExtensionOffset);

        // Read the public geometry/mode fields consumed by
        // ValidateViewPortForScroll. This is an ownership probe only; no
        // geometry is changed by this native status arm.
        var viewPortWordOffsets = new[]
        {
            GraphicsLayouts.ViewPortDWidth,
            GraphicsLayouts.ViewPortDHeight,
            GraphicsLayouts.ViewPortDxOffset,
            GraphicsLayouts.ViewPortDyOffset,
            GraphicsLayouts.ViewPortModes
        };
        foreach (var fieldOffset in viewPortWordOffsets)
        {
            Append(code, MoveWordA1DisplacementToD4);
            Append(code, checked((ushort)fieldOffset));
        }

        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var extendedModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(extendedModesBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var resourceBearingBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(resourceBearingBranchExtensionOffset);

        var noViewPortExtraOffset = code.Count;
        Append(code, MoveQuickTwoD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, nullViewBranchExtensionOffset, noViewPortExtraOffset);
        PatchBranch(code, nullViewPortBranchExtensionOffset, noViewPortExtraOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendMakeVPortPreallocatedBlankResources(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(28);

        List<int> EmitSpanDisjointCheck(
            ushort compareSpanBaseToTargetBase,
            ushort compareTargetBaseToSpanEnd,
            ushort moveTargetBaseToD3,
            uint targetBytes)
        {
            var disjointBranches = new List<int>(2);

            // If the target begins after the span, the span end must be at or
            // below the target base. Otherwise the target begins at or before
            // the span and its exclusive end must be at or below the span
            // base. Both arms use unsigned half-open comparisons.
            Append(code, compareSpanBaseToTargetBase);
            Append(code, BranchLowerOrSameWord);
            var targetBeforeSpanBranchExtensionOffset = code.Count;
            Append(code, 0);

            Append(code, compareTargetBaseToSpanEnd);
            Append(code, BranchLowerOrSameWord);
            var spanBeforeTargetDisjointBranchExtensionOffset = code.Count;
            Append(code, 0);
            disjointBranches.Add(spanBeforeTargetDisjointBranchExtensionOffset);
            Append(code, BranchAlwaysWord);
            var spanBeforeTargetOverlapBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(spanBeforeTargetOverlapBranchExtensionOffset);

            var targetBeforeSpanOffset = code.Count;
            PatchBranch(
                code,
                targetBeforeSpanBranchExtensionOffset,
                targetBeforeSpanOffset);
            Append(code, moveTargetBaseToD3);
            Append(code, AddImmediateLongD3);
            Append(code, (ushort)(targetBytes >> 16));
            Append(code, (ushort)targetBytes);
            Append(code, BranchCarryWord);
            var targetEndWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(targetEndWrapBranchExtensionOffset);
            Append(code, CompareLongD0ToD3);
            Append(code, BranchLowerOrSameWord);
            var targetBeforeSpanDisjointBranchExtensionOffset = code.Count;
            Append(code, 0);
            disjointBranches.Add(targetBeforeSpanDisjointBranchExtensionOffset);
            Append(code, BranchAlwaysWord);
            var targetBeforeSpanOverlapBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(targetBeforeSpanOverlapBranchExtensionOffset);

            return disjointBranches;
        }

        // This is the first native resource-construction form.  It does not
        // call an allocator: the caller supplies both CPR wrappers, one
        // CopList, and a raw copper buffer.  The body validates that the
        // public links agree, writes a canonical four-byte copper terminator,
        // and publishes the small guest envelopes.  Any absent, malformed,
        // split, or wrapped resource remains available to the complete
        // CopperScreen/CopperSharp68k owner.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA1ToD2); // retain ViewPort for fallback and CopList validation

        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullViewBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddViewBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFEE); // ViewSize (0x12) envelope
        Append(code, BranchHighWord);
        var wrappedViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedViewBranchExtensionOffset);

        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullViewPortBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddViewPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // ViewPortSize (0x28) envelope
        Append(code, BranchHighWord);
        var wrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedViewPortBranchExtensionOffset);

        // The native preallocated form owns both public envelopes.  Reject a
        // wrapping or partially overlapping View/ViewPort pair before reading
        // any resource link or writing the copper terminator.  The comparison
        // is half-open: touching envelopes remain valid, while either interval
        // containing the other declines to the provider/native owner.
        Append(code, MoveLongA0ToD4); // restore the root View base
        Append(code, MoveLongD2ToD0); // ViewPort base -> exclusive end
        Append(code, AddImmediateLongD0);
        Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.ViewPortSize);
        Append(code, BranchCarryWord);
        var wrappedViewPortEndBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedViewPortEndBranchExtensionOffset);

        Append(code, CompareLongD4ToD2); // ViewPort base - View base
        Append(code, BranchLowerOrSameWord);
        var viewPortBeforeOrEqualViewBranchExtensionOffset = code.Count;
        Append(code, 0);

        // View starts before ViewPort.  The pair is disjoint only when the
        // View's exclusive end is at or below the ViewPort base.
        Append(code, MoveLongD4ToD1);
        Append(code, AddImmediateLongD1);
        Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.ViewSize);
        Append(code, BranchCarryWord);
        var wrappedViewEndBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedViewEndBranchExtensionOffset);
        Append(code, CompareLongD1ToD2); // ViewPort base - View end
        Append(code, BranchCarryWord);
        var viewPortInsideViewBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(viewPortInsideViewBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var viewBeforeViewPortDisjointBranchExtensionOffset = code.Count;
        Append(code, 0);

        // ViewPort starts before (or at) View.  Its exclusive end must be at
        // or below the View base for the two public envelopes to be disjoint.
        var viewPortBeforeOrEqualViewOffset = code.Count;
        Append(code, CompareLongD4ToD0); // ViewPort end - View base
        Append(code, BranchLowerOrSameWord);
        var viewPortBeforeViewDisjointBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var viewOverlapsViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(viewOverlapsViewPortBranchExtensionOffset);

        var viewViewPortDisjointOffset = code.Count;
        PatchBranch(
            code,
            viewPortBeforeOrEqualViewBranchExtensionOffset,
            viewPortBeforeOrEqualViewOffset);
        PatchBranch(
            code,
            viewBeforeViewPortDisjointBranchExtensionOffset,
            viewViewPortDisjointOffset);
        PatchBranch(
            code,
            viewPortBeforeViewDisjointBranchExtensionOffset,
            viewViewPortDisjointOffset);

        // The supplied ViewPort must be the View's public head and must carry
        // a non-NULL RasInfo marker.  The marker deliberately identifies the
        // resource-bearing preallocated form; its nested bitmap is not
        // decoded by this blank-list constructor.
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, MoveLongA1ToD1);
        Append(code, CompareLongD0ToD1);
        Append(code, BranchNotEqualWord);
        var detachedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(detachedViewPortBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullRasInfoBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRasInfoBranchExtensionOffset);

        // Keep the linked RasInfo envelope separate from the root View and
        // ViewPort before any copper-resource field can be observed.  This is
        // an admission check only; the provider remains responsible for the
        // nested bitmap's geometry and plane ownership.
        Append(code, MoveLongD0ToD1);
        Append(code, AddImmediateLongD1);
        Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.RasInfoSize);
        Append(code, BranchCarryWord);
        var wrappedRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedRasInfoBranchExtensionOffset);

        var rasInfoViewDisjointBranches = EmitSpanDisjointCheck(
            CompareLongD0ToD4,
            CompareLongD4ToD1,
            MoveLongD4ToD3,
            (uint)GraphicsLayouts.ViewSize);
        var afterRasInfoViewCheckOffset = code.Count;
        foreach (var branchExtensionOffset in rasInfoViewDisjointBranches)
            PatchBranch(code, branchExtensionOffset, afterRasInfoViewCheckOffset);

        var rasInfoViewPortDisjointBranches = EmitSpanDisjointCheck(
            CompareLongD0ToD2,
            CompareLongD2ToD1,
            MoveLongD2ToD3,
            (uint)GraphicsLayouts.ViewPortSize);
        var afterRasInfoViewPortCheckOffset = code.Count;
        foreach (var branchExtensionOffset in rasInfoViewPortDisjointBranches)
            PatchBranch(code, branchExtensionOffset, afterRasInfoViewPortCheckOffset);

        // Preserve the root View for the later generated BitMap admission;
        // D3 is otherwise unused after these range checks.
        Append(code, MoveLongD4ToD3);

        // A preallocated CopList is carried by vp_DspIns.
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullCopListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullCopListBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddCopListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddCopListBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFCA); // CopListSize (0x36) envelope
        Append(code, BranchHighWord);
        var wrappedCopListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedCopListBranchExtensionOffset);
        Append(code, MoveAddressD0ToA2);

        // LOF and SHF must both name preallocated CPR wrappers.  Their Start
        // pointers must resolve to the same raw copper buffer for this first
        // blank-list unit, so frame selection cannot expose two owners.
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewLoFCprList));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullLofCprBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullLofCprBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddLofCprBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddLofCprBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // CprListSize (0x0C) envelope
        Append(code, BranchHighWord);
        var wrappedLofCprBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedLofCprBranchExtensionOffset);
        Append(code, MoveAddressD1ToA3);

        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewShFCprList));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullShfCprBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullShfCprBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddShfCprBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddShfCprBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // CprListSize (0x0C) envelope
        Append(code, BranchHighWord);
        var wrappedShfCprBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedShfCprBranchExtensionOffset);
        Append(code, MoveAddressD0ToA4);

        // Validate the LOF wrapper and retain its raw start/max-count.
        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CprListStart));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullLofRawBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullLofRawBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddLofRawBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddLofRawBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // four-byte raw terminator envelope
        Append(code, BranchHighWord);
        var wrappedLofRawBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedLofRawBranchExtensionOffset);
        Append(code, MoveLongD1ToD6);
        Append(code, MoveWordA3DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        Append(code, TestWordD5);
        Append(code, BranchEqualWord);
        var emptyLofCapacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(emptyLofCapacityBranchExtensionOffset);

        // The CopList's public view/pointer fields must agree with the CPR
        // start before the body writes any ownership link.
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
        Append(code, CompareLongD2ToD4);
        Append(code, BranchNotEqualWord);
        var foreignCopListBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(foreignCopListBranchExtensionOffset);
        Append(code, MoveLongA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        Append(code, CompareLongD6ToD1);
        Append(code, BranchNotEqualWord);
        var splitCopPtrBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(splitCopPtrBranchExtensionOffset);

        // Inspect the SHF wrapper without letting its temporary A1 binding
        // leak into a fallback path. The shared fallback restores A1 from D2.
        Append(code, MoveAddressA4ToA1);
        Append(code, MoveLongA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CprListStart));
        Append(code, CompareLongD6ToD1);
        Append(code, BranchNotEqualWord);
        var splitShfRawBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(splitShfRawBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var emptyShfCapacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(emptyShfCapacityBranchExtensionOffset);

        // A larger preallocated buffer can carry one of the bounded canonical
        // standard-planar display resources: 16x1, 320x200, PAL 320x256,
        // PAL/NTSC 320x512/400 lores interlace, 640x200, PAL 640x256, or
        // PAL/NTSC 640x512/400 hires interlace. Keep the original marker-only form below
        // as the compatibility arm for every other capacity or geometry; this
        // specialization is deliberately read/validate/write transactional
        // and never calls an allocator.
        var generatedFallbackBranches = new List<int>(32);
        Append(code, CompareImmediateWordD5);
        Append(code, 11); // twelve copper instructions including END
        Append(code, BranchLowerOrSameWord);
        var generatedLofCapacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedLofCapacityBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD1);
        Append(code, 11);
        Append(code, BranchLowerOrSameWord);
        var generatedCopCapacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedCopCapacityBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, TestWordD1);
        Append(code, BranchNotEqualWord);
        var generatedPopulatedBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedPopulatedBranchExtensionOffset);

        Append(code, MoveAddressD2ToA1);

        // A present BitMap is another public envelope in the nested display
        // topology.  Probe only its address span here; geometry, depth, and
        // plane ownership remain part of the generated canonical arm below.
        // This keeps the marker/blank form from publishing a bitmap that
        // aliases the root View or ViewPort while retaining provider fallback
        // for all richer bitmap layouts.
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoBitMap));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var bitmapAliasCheckSkippedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD1ToD0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapAliasOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapAliasOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, (ushort)(0x10000 - GraphicsLayouts.BitMapSize));
        Append(code, BranchHighWord);
        var bitmapAliasWrappedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapAliasWrappedBranchExtensionOffset);
        Append(code, MoveLongD0ToD1);
        Append(code, AddImmediateLongD1);
        Append(code, 0);
        Append(code, (ushort)GraphicsLayouts.BitMapSize);
        Append(code, BranchCarryWord);
        var bitmapAliasEndWrappedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapAliasEndWrappedBranchExtensionOffset);
        Append(code, MoveLongD3ToD4);
        var bitmapViewDisjointBranches = EmitSpanDisjointCheck(
            CompareLongD0ToD4,
            CompareLongD4ToD1,
            MoveLongD4ToD3,
            (uint)GraphicsLayouts.ViewSize);
        var afterBitmapViewCheckOffset = code.Count;
        foreach (var branchExtensionOffset in bitmapViewDisjointBranches)
            PatchBranch(code, branchExtensionOffset, afterBitmapViewCheckOffset);

        var bitmapViewPortDisjointBranches = EmitSpanDisjointCheck(
            CompareLongD0ToD2,
            CompareLongD2ToD1,
            MoveLongD2ToD3,
            (uint)GraphicsLayouts.ViewPortSize);
        var afterBitmapViewPortCheckOffset = code.Count;
        foreach (var branchExtensionOffset in bitmapViewPortDisjointBranches)
            PatchBranch(code, branchExtensionOffset, afterBitmapViewPortCheckOffset);
        PatchBranch(
            code,
            bitmapAliasCheckSkippedBranchExtensionOffset,
            afterBitmapViewPortCheckOffset);

        // Select a compact mode token in D4 from the exact ViewPort
        // width/height pair.  The token is retained through bitmap and raw
        // copper validation, then selects the matching register stream.
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDWidth));
        Append(code, CompareImmediateWordD1);
        Append(code, 16);
        Append(code, BranchEqualWord);
        var generatedSmallWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 320);
        Append(code, BranchEqualWord);
        var generatedWideWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 640);
        Append(code, BranchEqualWord);
        var generatedHiresWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var generatedWidthFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedWidthFallbackBranchExtensionOffset);

        var generatedSmallWidthOffset = code.Count;
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDHeight));
        Append(code, CompareImmediateWordD1);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var generatedSmallHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var generatedSmallHeightFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedSmallHeightFallbackBranchExtensionOffset);

        var generatedWideWidthOffset = code.Count;
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDHeight));
        Append(code, CompareImmediateWordD1);
        Append(code, 200);
        Append(code, BranchEqualWord);
        var generatedWideHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 256);
        Append(code, BranchEqualWord);
        var generatedPalWideHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 512);
        Append(code, BranchEqualWord);
        var generatedPalLoresLaceHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 400);
        Append(code, BranchEqualWord);
        var generatedNtscLoresLaceHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var generatedWideHeightFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedWideHeightFallbackBranchExtensionOffset);

        var generatedHiresWidthOffset = code.Count;
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDHeight));
        Append(code, CompareImmediateWordD1);
        Append(code, 200);
        Append(code, BranchEqualWord);
        var generatedHiresHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 256);
        Append(code, BranchEqualWord);
        var generatedPalHiresHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 512);
        Append(code, BranchEqualWord);
        var generatedPalHiresLaceHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 400);
        Append(code, BranchEqualWord);
        var generatedNtscHiresLaceHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var generatedHiresHeightFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedHiresHeightFallbackBranchExtensionOffset);

        int AppendGeneratedMode(byte mode)
        {
            Append(code, MoveImmediateWordD0);
            Append(code, mode);
            Append(code, MoveWordD0ToD4);
            Append(code, BranchAlwaysWord);
            var branchExtensionOffset = code.Count;
            Append(code, 0);
            return branchExtensionOffset;
        }

        var generatedSmallModeOffset = code.Count;
        var generatedSmallModeJoinBranchExtensionOffset = AppendGeneratedMode(0);
        var generatedWideModeOffset = code.Count;
        var generatedWideModeJoinBranchExtensionOffset = AppendGeneratedMode(1);
        var generatedPalWideModeOffset = code.Count;
        var generatedPalWideModeJoinBranchExtensionOffset = AppendGeneratedMode(2);
        var generatedHiresModeOffset = code.Count;
        var generatedHiresModeJoinBranchExtensionOffset = AppendGeneratedMode(3);
        var generatedPalHiresModeOffset = code.Count;
        var generatedPalHiresModeJoinBranchExtensionOffset = AppendGeneratedMode(4);
        var generatedPalLoresLaceModeOffset = code.Count;
        var generatedPalLoresLaceModeJoinBranchExtensionOffset = AppendGeneratedMode(5);
        var generatedNtscLoresLaceModeOffset = code.Count;
        var generatedNtscLoresLaceModeJoinBranchExtensionOffset = AppendGeneratedMode(6);
        var generatedPalHiresLaceModeOffset = code.Count;
        var generatedPalHiresLaceModeJoinBranchExtensionOffset = AppendGeneratedMode(7);
        var generatedNtscHiresLaceModeOffset = code.Count;
        var generatedNtscHiresLaceModeJoinBranchExtensionOffset = AppendGeneratedMode(8);
