        PatchBranch(code, generatedSmallWidthBranchExtensionOffset, generatedSmallWidthOffset);
        PatchBranch(code, generatedWideWidthBranchExtensionOffset, generatedWideWidthOffset);
        PatchBranch(code, generatedHiresWidthBranchExtensionOffset, generatedHiresWidthOffset);
        PatchBranch(code, generatedSmallHeightBranchExtensionOffset, generatedSmallModeOffset);
        PatchBranch(code, generatedWideHeightBranchExtensionOffset, generatedWideModeOffset);
        PatchBranch(code, generatedPalWideHeightBranchExtensionOffset, generatedPalWideModeOffset);
        PatchBranch(code, generatedPalLoresLaceHeightBranchExtensionOffset, generatedPalLoresLaceModeOffset);
        PatchBranch(code, generatedNtscLoresLaceHeightBranchExtensionOffset, generatedNtscLoresLaceModeOffset);
        PatchBranch(code, generatedHiresHeightBranchExtensionOffset, generatedHiresModeOffset);
        PatchBranch(code, generatedPalHiresHeightBranchExtensionOffset, generatedPalHiresModeOffset);
        PatchBranch(code, generatedPalHiresLaceHeightBranchExtensionOffset, generatedPalHiresLaceModeOffset);
        PatchBranch(code, generatedNtscHiresLaceHeightBranchExtensionOffset, generatedNtscHiresLaceModeOffset);
        PatchBranch(code, generatedSmallModeJoinBranchExtensionOffset, generatedModeJoinOffset);
        PatchBranch(code, generatedWideModeJoinBranchExtensionOffset, generatedModeJoinOffset);
        PatchBranch(code, generatedPalWideModeJoinBranchExtensionOffset, generatedModeJoinOffset);
        PatchBranch(code, generatedHiresModeJoinBranchExtensionOffset, generatedModeJoinOffset);
        PatchBranch(code, generatedPalHiresModeJoinBranchExtensionOffset, generatedModeJoinOffset);
        PatchBranch(code, generatedPalLoresLaceModeJoinBranchExtensionOffset, generatedModeJoinOffset);
        PatchBranch(code, generatedNtscLoresLaceModeJoinBranchExtensionOffset, generatedModeJoinOffset);
        PatchBranch(code, generatedPalHiresLaceModeJoinBranchExtensionOffset, generatedModeJoinOffset);
        PatchBranch(code, generatedNtscHiresLaceModeJoinBranchExtensionOffset, generatedModeJoinOffset);

        var generatedCommonGeometryChecks = new[]
        {
            (GraphicsLayouts.ViewPortDxOffset, (ushort)0),
            (GraphicsLayouts.ViewPortDyOffset, (ushort)0)
        };
        foreach (var (fieldOffset, expected) in generatedCommonGeometryChecks)
        {
            Append(code, MoveWordA1DisplacementToD1);
