        Append(code, MoveWordA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateWordD1);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var generatedStandardModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, GraphicsModeIds.InterlaceMode);
        Append(code, BranchEqualWord);
        var generatedInterlaceModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
