        Append(code, BranchNotEqualWord);
        var generatedHiresInterlaceModeValueBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedHiresInterlaceModeValueBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 7);
        Append(code, BranchEqualWord);
        var generatedPalHiresInterlaceTokenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 8);
        Append(code, BranchNotEqualWord);
        var generatedNtscHiresInterlaceTokenBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedNtscHiresInterlaceTokenBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var generatedHiresInterlaceJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var generatedInterlaceModesCheckOffset = code.Count;
        PatchBranch(code, generatedInterlaceModesBranchExtensionOffset, generatedInterlaceModesCheckOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 5);
        Append(code, BranchEqualWord);
        var generatedInterlaceTokenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 6);
        Append(code, BranchEqualWord);
        var generatedNtscInterlaceTokenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var generatedLegacyInterlaceTokenBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedLegacyInterlaceTokenBranchExtensionOffset);

        var generatedModesJoinOffset = code.Count;
        PatchBranch(code, generatedStandardModesBranchExtensionOffset, generatedModesJoinOffset);
        PatchBranch(code, generatedHiresInterlaceJoinBranchExtensionOffset, generatedModesJoinOffset);
        PatchBranch(code, generatedPalHiresInterlaceTokenBranchExtensionOffset, generatedModesJoinOffset);
        PatchBranch(code, generatedInterlaceTokenBranchExtensionOffset, generatedModesJoinOffset);
        PatchBranch(code, generatedNtscInterlaceTokenBranchExtensionOffset, generatedModesJoinOffset);
        Append(code, MoveByteA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, CompareImmediateByteD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var generatedExtendedModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedExtendedModesBranchExtensionOffset);

        // Decode the standard one-node RasInfo/BitMap envelope. The bitmap is
        // one plane with an exact stride/row pair for the selected canonical
        // mode and no displayable/interleaved flag. The generic blank arm
        // still handles all other caller/provider forms.
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var generatedRasInfoNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedRasInfoNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var generatedRasInfoOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedRasInfoOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // RasInfoSize (0x0C) envelope
        Append(code, BranchHighWord);
        var generatedRasInfoWrappedBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedRasInfoWrappedBranchExtensionOffset);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var generatedRasInfoLinkedBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedRasInfoLinkedBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoBitMap));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var generatedBitMapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedBitMapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var generatedBitMapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedBitMapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var generatedBitMapWrappedBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedBitMapWrappedBranchExtensionOffset);
        Append(code, MoveAddressD1ToA0);

        // Match the bitmap envelope to the selected mode.  The stride and
        // row checks are deliberately separate so an otherwise valid width
        // cannot borrow a different mode's plane layout.
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD1);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var generatedSmallStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 40);
        Append(code, BranchEqualWord);
        var generatedWideStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 80);
        Append(code, BranchEqualWord);
        var generatedHiresStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var generatedStrideFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedStrideFallbackBranchExtensionOffset);

        var generatedSmallStrideCheckOffset = code.Count;
        Append(code, CompareImmediateWordD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var generatedSmallStrideAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var generatedSmallStrideRejectedBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedSmallStrideRejectedBranchExtensionOffset);

        var generatedWideStrideCheckOffset = code.Count;
        Append(code, CompareImmediateWordD4);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var generatedWideStrideAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var generatedPalWideStrideAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 5);
        Append(code, BranchEqualWord);
        var generatedPalLoresLaceStrideAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 6);
        Append(code, BranchEqualWord);
        var generatedNtscLoresLaceStrideAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var generatedWideStrideRejectedBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedWideStrideRejectedBranchExtensionOffset);

        var generatedHiresStrideCheckOffset = code.Count;
        Append(code, CompareImmediateWordD4);
        Append(code, 3);
        Append(code, BranchEqualWord);
        var generatedHiresStrideAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 4);
        Append(code, BranchEqualWord);
        var generatedPalHiresStrideAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 7);
        Append(code, BranchEqualWord);
        var generatedPalHiresLaceStrideAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 8);
        Append(code, BranchEqualWord);
        var generatedNtscHiresLaceStrideAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var generatedHiresStrideRejectedBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedHiresStrideRejectedBranchExtensionOffset);

        var generatedStrideJoinOffset = code.Count;
        PatchBranch(code, generatedSmallStrideBranchExtensionOffset, generatedSmallStrideCheckOffset);
        PatchBranch(code, generatedWideStrideBranchExtensionOffset, generatedWideStrideCheckOffset);
        PatchBranch(code, generatedHiresStrideBranchExtensionOffset, generatedHiresStrideCheckOffset);
        PatchBranch(code, generatedSmallStrideAcceptedBranchExtensionOffset, generatedStrideJoinOffset);
        PatchBranch(code, generatedWideStrideAcceptedBranchExtensionOffset, generatedStrideJoinOffset);
        PatchBranch(code, generatedPalWideStrideAcceptedBranchExtensionOffset, generatedStrideJoinOffset);
        PatchBranch(code, generatedPalLoresLaceStrideAcceptedBranchExtensionOffset, generatedStrideJoinOffset);
        PatchBranch(code, generatedNtscLoresLaceStrideAcceptedBranchExtensionOffset, generatedStrideJoinOffset);
        PatchBranch(code, generatedHiresStrideAcceptedBranchExtensionOffset, generatedStrideJoinOffset);
        PatchBranch(code, generatedPalHiresStrideAcceptedBranchExtensionOffset, generatedStrideJoinOffset);
        PatchBranch(code, generatedPalHiresLaceStrideAcceptedBranchExtensionOffset, generatedStrideJoinOffset);
        PatchBranch(code, generatedNtscHiresLaceStrideAcceptedBranchExtensionOffset, generatedStrideJoinOffset);

        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD1);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var generatedSmallRowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 200);
        Append(code, BranchEqualWord);
        var generatedRows200BranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 256);
        Append(code, BranchEqualWord);
        var generatedRows256BranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 512);
        Append(code, BranchEqualWord);
        var generatedRows512BranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 400);
        Append(code, BranchEqualWord);
        var generatedRows400BranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var generatedRowsFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedRowsFallbackBranchExtensionOffset);

        var generatedSmallRowsCheckOffset = code.Count;
        Append(code, CompareImmediateWordD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var generatedSmallRowsAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var generatedSmallRowsRejectedBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedSmallRowsRejectedBranchExtensionOffset);

        var generatedRows200CheckOffset = code.Count;
        Append(code, CompareImmediateWordD4);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var generatedWideRows200AcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 3);
        Append(code, BranchEqualWord);
        var generatedHiresRows200AcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var generatedRows200RejectedBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedRows200RejectedBranchExtensionOffset);

        var generatedRows256CheckOffset = code.Count;
        Append(code, CompareImmediateWordD4);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var generatedPalWideRows256AcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 4);
        Append(code, BranchEqualWord);
        var generatedPalHiresRows256AcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var generatedRows512CheckOffset = code.Count;
        Append(code, CompareImmediateWordD4);
        Append(code, 5);
        Append(code, BranchEqualWord);
        var generatedPalLoresLaceRows512AcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 6);
        Append(code, BranchEqualWord);
        var generatedNtscLoresLaceRows400AcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 7);
        Append(code, BranchEqualWord);
        var generatedPalHiresLaceRows512AcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 8);
        Append(code, BranchEqualWord);
        var generatedNtscHiresLaceRows400AcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var generatedRows256RejectedBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedRows256RejectedBranchExtensionOffset);

        var generatedRowsJoinOffset = code.Count;
        PatchBranch(code, generatedSmallRowsBranchExtensionOffset, generatedSmallRowsCheckOffset);
        PatchBranch(code, generatedRows200BranchExtensionOffset, generatedRows200CheckOffset);
        PatchBranch(code, generatedRows256BranchExtensionOffset, generatedRows256CheckOffset);
        PatchBranch(code, generatedRows512BranchExtensionOffset, generatedRows512CheckOffset);
        PatchBranch(code, generatedRows400BranchExtensionOffset, generatedRows512CheckOffset);
        PatchBranch(code, generatedSmallRowsAcceptedBranchExtensionOffset, generatedRowsJoinOffset);
        PatchBranch(code, generatedWideRows200AcceptedBranchExtensionOffset, generatedRowsJoinOffset);
        PatchBranch(code, generatedHiresRows200AcceptedBranchExtensionOffset, generatedRowsJoinOffset);
        PatchBranch(code, generatedPalWideRows256AcceptedBranchExtensionOffset, generatedRowsJoinOffset);
        PatchBranch(code, generatedPalHiresRows256AcceptedBranchExtensionOffset, generatedRowsJoinOffset);
        PatchBranch(code, generatedPalLoresLaceRows512AcceptedBranchExtensionOffset, generatedRowsJoinOffset);
        PatchBranch(code, generatedNtscLoresLaceRows400AcceptedBranchExtensionOffset, generatedRowsJoinOffset);
        PatchBranch(code, generatedPalHiresLaceRows512AcceptedBranchExtensionOffset, generatedRowsJoinOffset);
        PatchBranch(code, generatedNtscHiresLaceRows400AcceptedBranchExtensionOffset, generatedRowsJoinOffset);
        Append(code, MoveByteA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, AndImmediateWordD1);
        Append(code, 0x0006); // reject BMF_DISPLAYABLE/BMF_INTERLEAVED
        Append(code, TestWordD1);
        Append(code, BranchNotEqualWord);
        var generatedBitmapFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedBitmapFlagsBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD1);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var generatedBitmapDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedBitmapDepthBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var generatedPlaneNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedPlaneNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var generatedPlaneOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedPlaneOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // one plane LONG envelope
        Append(code, BranchHighWord);
        var generatedPlaneWrappedBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedPlaneWrappedBranchExtensionOffset);

        // Every canonical stream occupies 48 bytes (twelve instructions).
        // Keep the address check explicit so a later display publication
        // cannot wrap into low memory while the CPU is writing the resource.
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD0);
        Append(code, BranchHighWord);
        var generatedRawWrappedBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedRawWrappedBranchExtensionOffset);

        var generatedSuccessOffset = code.Count;
        Append(code, MoveAddressD6ToA0);

        // Dispatch the validated mode token to the matching canonical copper
        // stream.  All nine forms share the same raw envelope and plane
        // pointer encoding; only the timing and BPLCON0 words differ.
        var generatedProgramBranchExtensions = new List<int>(9);
        foreach (var mode in new byte[] { 0, 1, 2, 3, 4, 5, 6, 7, 8 })
        {
            Append(code, CompareImmediateWordD4);
            Append(code, mode);
            Append(code, BranchEqualWord);
            generatedProgramBranchExtensions.Add(code.Count);
            Append(code, 0);
        }
        Append(code, BranchAlwaysWord);
        var generatedProgramFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        generatedFallbackBranches.Add(generatedProgramFallbackBranchExtensionOffset);

        var generatedProgramJoinBranchExtensions = new List<int>(8);

        void AppendGeneratedCopperProgram(
            ushort diwStop,
            ushort ddfStart,
            ushort ddfStop,
            ushort bplcon0)
        {
            var planarMoves = new[]
            {
                (Register: (ushort)0x008E, Value: (ushort)0x2C81),
                (Register: (ushort)0x0090, Value: diwStop),
                (Register: (ushort)0x0092, Value: ddfStart),
                (Register: (ushort)0x0094, Value: ddfStop),
                (Register: (ushort)0x0108, Value: (ushort)0x0000),
                (Register: (ushort)0x010A, Value: (ushort)0x0000),
                (Register: (ushort)0x0100, Value: bplcon0),
                (Register: (ushort)0x0102, Value: (ushort)0x0000),
                (Register: (ushort)0x0104, Value: (ushort)0x0000)
            };
            for (var index = 0; index < planarMoves.Length; index++)
            {
                var (register, value) = planarMoves[index];
                var registerOffset = index * 4;
                Append(code, MoveImmediateWordD0);
                Append(code, register);
                Append(code, MoveWordD0ToA0Displacement);
                Append(code, checked((ushort)registerOffset));
                Append(code, MoveImmediateWordD0);
                Append(code, value);
                Append(code, MoveWordD0ToA0Displacement);
                Append(code, checked((ushort)(registerOffset + 2)));
            }

            // BPL1PTH/BPL1PTL carry the caller-owned chip plane address.
            Append(code, MoveImmediateWordD0);
            Append(code, 0x00E0);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, 36);
            Append(code, MoveLongD1ToD0);
            Append(code, SwapD0);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, 38);
            Append(code, MoveImmediateWordD0);
            Append(code, 0x00E2);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, 40);
            Append(code, MoveLongD1ToD0);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, 42);
            Append(code, MoveImmediateWordD0);
            Append(code, GraphicsLayouts.CopperEndWait);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, 44);
            Append(code, MoveImmediateWordD0);
            Append(code, GraphicsLayouts.CopperEndMask);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, 46);
            Append(code, BranchAlwaysWord);
            var joinBranchExtensionOffset = code.Count;
            Append(code, 0);
            generatedProgramJoinBranchExtensions.Add(joinBranchExtensionOffset);
        }

        var generatedSmallProgramOffset = code.Count;
        AppendGeneratedCopperProgram(0x2D00, 0x0038, 0x0038, 0x1000);
        var generatedWideProgramOffset = code.Count;
        AppendGeneratedCopperProgram(0xF4C1, 0x0038, 0x00D0, 0x1000);
        var generatedPalWideProgramOffset = code.Count;
        AppendGeneratedCopperProgram(0xF4C1, 0x0038, 0x00D0, 0x1000);
        var generatedHiresProgramOffset = code.Count;
        AppendGeneratedCopperProgram(0xF4C1, 0x003C, 0x00D4, 0x9000);
        var generatedPalHiresProgramOffset = code.Count;
        AppendGeneratedCopperProgram(0xF4C1, 0x003C, 0x00D4, 0x9000);
        var generatedPalLoresLaceProgramOffset = code.Count;
        AppendGeneratedCopperProgram(0xF4C1, 0x0038, 0x00D0, 0x1004);
        var generatedNtscLoresLaceProgramOffset = code.Count;
        AppendGeneratedCopperProgram(0xF4C1, 0x0038, 0x00D0, 0x1004);
        var generatedPalHiresLaceProgramOffset = code.Count;
        AppendGeneratedCopperProgram(0xF4C1, 0x003C, 0x00D4, 0x9004);
        var generatedNtscHiresLaceProgramOffset = generatedPalHiresLaceProgramOffset;
        var generatedProgramJoinOffset = code.Count;
        PatchBranch(code, generatedProgramBranchExtensions[0], generatedSmallProgramOffset);
        PatchBranch(code, generatedProgramBranchExtensions[1], generatedWideProgramOffset);
        PatchBranch(code, generatedProgramBranchExtensions[2], generatedPalWideProgramOffset);
        PatchBranch(code, generatedProgramBranchExtensions[3], generatedHiresProgramOffset);
        PatchBranch(code, generatedProgramBranchExtensions[4], generatedPalHiresProgramOffset);
        PatchBranch(code, generatedProgramBranchExtensions[5], generatedPalLoresLaceProgramOffset);
        PatchBranch(code, generatedProgramBranchExtensions[6], generatedNtscLoresLaceProgramOffset);
        PatchBranch(code, generatedProgramBranchExtensions[7], generatedPalHiresLaceProgramOffset);
        PatchBranch(code, generatedProgramBranchExtensions[8], generatedNtscHiresLaceProgramOffset);
        foreach (var branchExtensionOffset in generatedProgramJoinBranchExtensions)
            PatchBranch(code, branchExtensionOffset, generatedProgramJoinOffset);
        Append(code, MoveImmediateWordD0);
        Append(code, 12);
        Append(code, MoveWordD0ToD4);
        Append(code, BranchAlwaysWord);
        var generatedPublicationBranchExtensionOffset = code.Count;
        Append(code, 0);

        var blankSuccessOffset = code.Count;

        // Emit the canonical Copper end marker into the caller-owned raw
        // buffer for the original marker-only form.
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToD4);
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndWait);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 2);

        var publicationOffset = code.Count;

        // Publish the LOF CPR wrapper.
        Append(code, MoveAddressA3ToA1);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CprListStart));
        Append(code, MoveLongD5ToD0);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CprListNext));

        // Publish the SHF CPR wrapper with the same raw stream/max count.
        Append(code, MoveAddressA4ToA1);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CprListStart));
        Append(code, MoveLongD5ToD0);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CprListNext));

        // Publish the CopList envelope and leave the caller's ViewPort
        // DspIns link pointing at this already-validated structure.
        Append(code, MoveAddressA2ToA1);
        Append(code, MoveLongD2ToD0);
        Append(code, MoveLongD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
        Append(code, MoveLongD6ToD0);
        foreach (var fieldOffset in new[]
        {
            GraphicsLayouts.CopListCopPtr,
            GraphicsLayouts.CopListCopLStart,
            GraphicsLayouts.CopListCopSStart
        })
        {
            Append(code, MoveLongD0ToA1Displacement);
            Append(code, checked((ushort)fieldOffset));
        }
        Append(code, MoveQuickZeroD0);
        foreach (var fieldOffset in new[]
        {
            GraphicsLayouts.CopListNext,
            GraphicsLayouts.CopListSystem,
            GraphicsLayouts.CopListCount
        })
        {
            if (fieldOffset == GraphicsLayouts.CopListCount)
            {
                Append(code, MoveWordD0ToA1Displacement);
            }
            else
            {
                Append(code, MoveLongD0ToA1Displacement);
            }
            Append(code, checked((ushort)fieldOffset));
        }
        Append(code, MoveLongD5ToD0);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));
        Append(code, CompareImmediateWordD4);
        Append(code, 12);
        Append(code, BranchEqualWord);
        var generatedCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var generatedCountOffset = code.Count;
        Append(code, MoveImmediateWordD0);
        Append(code, 12);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveAddressD2ToA1);
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, generatedPublicationBranchExtensionOffset, publicationOffset);
        PatchBranch(code, generatedCountBranchExtensionOffset, generatedCountOffset);
        foreach (var branchExtensionOffset in generatedFallbackBranches)
            PatchBranch(code, branchExtensionOffset, blankSuccessOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendChangeVPBitMapGeometryOnly(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(18);

        // Claim only the assembling-display form of ChangeVPBitMap: a
        // standard, depth-one through depth-eight geometry bitmap replaces a NULL
        // RasInfo link, with no DBufInfo synchronization or display-DMA
        // handoff.  The complete exchange path remains on the
        // portable/provider boundary.
        Append(code, MoveLongD0ToD7);

        // A2 is the optional DBufInfo.  A non-NULL object requires ownership,
        // message, and frame-order state that this read-only native slice
        // cannot prove.
        Append(code, MoveLongA2ToD6);
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var dbufBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(dbufBranchExtensionOffset);

        // A1 is the replacement BitMap.  This narrow form consumes a full
        // standard header, a nonzero even BytesPerRow, depth one through eight, and
        // no displayable/interleaved flags; linked display resources stay
        // with the complete scheduler-aware implementation.
        Append(code, MoveLongA1ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullBitMapBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddBitMapBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var wrappedBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedBitMapBranchExtensionOffset);

        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD2);
        Append(code, BranchEqualWord);
        var zeroStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(zeroStrideBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddStrideBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, AndImmediateWordD3);
        Append(code, 0x0006); // reject BMF_DISPLAYABLE and BMF_INTERLEAVED
        Append(code, CompareImmediateByteD3);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var unsupportedFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedFlagsBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var depthOneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var depthTwoBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 3);
        Append(code, BranchEqualWord);
        var depthThreeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 4);
        Append(code, BranchEqualWord);
        var depthFourBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 5);
        Append(code, BranchEqualWord);
        var depthFiveBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 6);
        Append(code, BranchEqualWord);
        var depthSixBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 7);
        Append(code, BranchEqualWord);
        var depthSevenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 8);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);
        PatchBranch(code, depthTwoBranchExtensionOffset, code.Count);
        PatchBranch(code, depthThreeBranchExtensionOffset, code.Count);
        PatchBranch(code, depthFourBranchExtensionOffset, code.Count);
        PatchBranch(code, depthFiveBranchExtensionOffset, code.Count);
        PatchBranch(code, depthSixBranchExtensionOffset, code.Count);
        PatchBranch(code, depthSevenBranchExtensionOffset, code.Count);
        // Read Rows and validate the selected inline plane slots so the native
        // body retains a complete bounded header/plane fault boundary for
        // all admitted depths.
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var replacementPlaneNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var replacementPlaneOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var replacementPlaneWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneWrapBranchExtensionOffset);
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var replacementDepthOneReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 4)));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var replacementPlaneTwoNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneTwoNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var replacementPlaneTwoOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneTwoOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var replacementPlaneTwoWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneTwoWrapBranchExtensionOffset);
        Append(code, CompareImmediateByteD4);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var replacementDepthTwoReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 8)));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var replacementPlaneThreeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneThreeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var replacementPlaneThreeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneThreeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var replacementPlaneThreeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneThreeWrapBranchExtensionOffset);
        Append(code, CompareImmediateByteD4);
        Append(code, 3);
        Append(code, BranchEqualWord);
        var replacementDepthThreeReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 12)));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var replacementPlaneFourNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneFourNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var replacementPlaneFourOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneFourOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var replacementPlaneFourWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneFourWrapBranchExtensionOffset);
        Append(code, CompareImmediateByteD4);
        Append(code, 4);
        Append(code, BranchEqualWord);
        var replacementDepthFourReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 16)));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var replacementPlaneFiveNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneFiveNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var replacementPlaneFiveOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneFiveOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var replacementPlaneFiveWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneFiveWrapBranchExtensionOffset);
        Append(code, CompareImmediateByteD4);
        Append(code, 5);
        Append(code, BranchEqualWord);
        var replacementDepthFiveReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 20)));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var replacementPlaneSixNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneSixNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var replacementPlaneSixOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneSixOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var replacementPlaneSixWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneSixWrapBranchExtensionOffset);
        Append(code, CompareImmediateByteD4);
        Append(code, 6);
        Append(code, BranchEqualWord);
        var replacementDepthSixReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 24)));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var replacementPlaneSevenNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneSevenNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var replacementPlaneSevenOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneSevenOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var replacementPlaneSevenWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneSevenWrapBranchExtensionOffset);
        Append(code, CompareImmediateByteD4);
        Append(code, 7);
        Append(code, BranchEqualWord);
        var replacementDepthSevenReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 28)));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var replacementPlaneEightNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneEightNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var replacementPlaneEightOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneEightOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var replacementPlaneEightWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(replacementPlaneEightWrapBranchExtensionOffset);
        var replacementPlaneValidationDoneOffset = code.Count;
        PatchBranch(code, depthOneBranchExtensionOffset, replacementPlaneValidationDoneOffset);
        PatchBranch(code, replacementDepthOneReadyBranchExtensionOffset, replacementPlaneValidationDoneOffset);
        PatchBranch(code, replacementDepthTwoReadyBranchExtensionOffset, replacementPlaneValidationDoneOffset);
        PatchBranch(code, replacementDepthThreeReadyBranchExtensionOffset, replacementPlaneValidationDoneOffset);
        PatchBranch(code, replacementDepthFourReadyBranchExtensionOffset, replacementPlaneValidationDoneOffset);
        PatchBranch(code, replacementDepthFiveReadyBranchExtensionOffset, replacementPlaneValidationDoneOffset);
        PatchBranch(code, replacementDepthSixReadyBranchExtensionOffset, replacementPlaneValidationDoneOffset);
        PatchBranch(code, replacementDepthSevenReadyBranchExtensionOffset, replacementPlaneValidationDoneOffset);

        // A0 is the ViewPort.  Only the standard-mode RasInfo link and its
        // empty first node are admitted; linked or displayable state falls
        // through to the complete exchange path with D0 restored.
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullViewPortBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddViewPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // ViewPortSize (0x28) envelope
        Append(code, BranchHighWord);
        var wrappedViewPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedViewPortBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, CompareImmediateByteD3);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var extendedModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(extendedModesBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullRasInfoBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRasInfoBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // RasInfoSize (0x0C) envelope
        Append(code, BranchHighWord);
        var wrappedRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedRasInfoBranchExtensionOffset);

        Append(code, MoveAddressD6ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoNext));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var linkedRasInfoBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(linkedRasInfoBranchExtensionOffset);

        // Keep the replacement BitMap pointer while inspecting an existing
        // RasInfo bitmap.  The old pointer is optional for the assembling
        // display form, but when present it must still be a bounded,
        // standard one- through eight-plane bitmap before the native exchange can
        // claim the structure.
        Append(code, MoveAddressA1ToA4);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoBitMap));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var noExistingBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddExistingBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddExistingBitMapBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var wrappedExistingBitMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedExistingBitMapBranchExtensionOffset);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveByteA3DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD3);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var existingDepthOneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD3);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var existingDepthTwoBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD3);
        Append(code, 3);
        Append(code, BranchEqualWord);
        var existingDepthThreeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD3);
        Append(code, 4);
        Append(code, BranchEqualWord);
        var existingDepthFourBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD3);
        Append(code, 5);
        Append(code, BranchEqualWord);
        var existingDepthFiveBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD3);
        Append(code, 6);
        Append(code, BranchEqualWord);
        var existingDepthSixBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD3);
        Append(code, 7);
        Append(code, BranchEqualWord);
        var existingDepthSevenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD3);
        Append(code, 8);
        Append(code, BranchNotEqualWord);
        var existingDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingDepthBranchExtensionOffset);
        PatchBranch(code, existingDepthTwoBranchExtensionOffset, code.Count);
        PatchBranch(code, existingDepthThreeBranchExtensionOffset, code.Count);
        PatchBranch(code, existingDepthFourBranchExtensionOffset, code.Count);
        PatchBranch(code, existingDepthFiveBranchExtensionOffset, code.Count);
        PatchBranch(code, existingDepthSixBranchExtensionOffset, code.Count);
        PatchBranch(code, existingDepthSevenBranchExtensionOffset, code.Count);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var existingZeroStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingZeroStrideBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var existingOddStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingOddStrideBranchExtensionOffset);
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var existingZeroRowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingZeroRowsBranchExtensionOffset);
        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddExistingPlaneBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddExistingPlaneBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // first plane pointer envelope
        Append(code, BranchHighWord);
        var wrappedExistingPlaneBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedExistingPlaneBranchExtensionOffset);
        Append(code, CompareImmediateByteD3);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var existingDepthOneReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 4)));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var existingPlaneTwoNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneTwoNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var existingPlaneTwoOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneTwoOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var existingPlaneTwoWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneTwoWrapBranchExtensionOffset);
        Append(code, CompareImmediateByteD3);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var existingDepthTwoReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 8)));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var existingPlaneThreeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneThreeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var existingPlaneThreeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneThreeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var existingPlaneThreeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneThreeWrapBranchExtensionOffset);
        Append(code, CompareImmediateByteD3);
        Append(code, 3);
        Append(code, BranchEqualWord);
        var existingDepthThreeReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 12)));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var existingPlaneFourNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneFourNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var existingPlaneFourOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneFourOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var existingPlaneFourWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneFourWrapBranchExtensionOffset);
        Append(code, CompareImmediateByteD3);
        Append(code, 4);
        Append(code, BranchEqualWord);
        var existingDepthFourReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 16)));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var existingPlaneFiveNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneFiveNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var existingPlaneFiveOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneFiveOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var existingPlaneFiveWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneFiveWrapBranchExtensionOffset);
        Append(code, CompareImmediateByteD3);
        Append(code, 5);
        Append(code, BranchEqualWord);
        var existingDepthFiveReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 20)));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var existingPlaneSixNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneSixNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var existingPlaneSixOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneSixOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var existingPlaneSixWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneSixWrapBranchExtensionOffset);
        Append(code, CompareImmediateByteD3);
        Append(code, 6);
        Append(code, BranchEqualWord);
        var existingDepthSixReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 24)));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var existingPlaneSevenNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneSevenNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var existingPlaneSevenOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneSevenOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var existingPlaneSevenWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneSevenWrapBranchExtensionOffset);
        Append(code, CompareImmediateByteD3);
        Append(code, 7);
        Append(code, BranchEqualWord);
        var existingDepthSevenReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + 28)));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var existingPlaneEightNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneEightNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var existingPlaneEightOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneEightOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var existingPlaneEightWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(existingPlaneEightWrapBranchExtensionOffset);
        var existingPlaneValidationDoneOffset = code.Count;
        PatchBranch(code, existingDepthOneBranchExtensionOffset, existingPlaneValidationDoneOffset);
        PatchBranch(code, existingDepthOneReadyBranchExtensionOffset, existingPlaneValidationDoneOffset);
        PatchBranch(code, existingDepthTwoReadyBranchExtensionOffset, existingPlaneValidationDoneOffset);
        PatchBranch(code, existingDepthThreeReadyBranchExtensionOffset, existingPlaneValidationDoneOffset);
        PatchBranch(code, existingDepthFourReadyBranchExtensionOffset, existingPlaneValidationDoneOffset);
        PatchBranch(code, existingDepthFiveReadyBranchExtensionOffset, existingPlaneValidationDoneOffset);
        PatchBranch(code, existingDepthSixReadyBranchExtensionOffset, existingPlaneValidationDoneOffset);
        PatchBranch(code, existingDepthSevenReadyBranchExtensionOffset, existingPlaneValidationDoneOffset);

        var restoreReplacementBitMapOffset = code.Count;
        Append(code, MoveLongA4ToD1);
        Append(code, MoveWordA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoRxOffset));
        Append(code, MoveWordA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoRyOffset));

        Append(code, MoveLongD1ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoBitMap));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, noExistingBitMapBranchExtensionOffset, restoreReplacementBitMapOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendInitRastPort(List<byte> code)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(3);

        // D6 is scratch here, but callee-saved at both public entry routes.
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x0200); // D6

        // Clear the complete 100-byte public RastPort with 25 longword stores,
        // then publish the classic no-font defaults.  A native vector enters
        // with A6 as GfxBase, so the final block mirrors SetFont's public
        // metric cache when GfxBase->DefaultFont is present.
        Append(code, MoveLongA1ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullDescriptorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullDescriptorBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddDescriptorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddDescriptorBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, unchecked((ushort)(uint.MaxValue - (GraphicsLayouts.RastPortSize - 1))));
        Append(code, BranchHighWord);
        var wrappedDescriptorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedDescriptorBranchExtensionOffset);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveImmediateWordD1);
        Append(code, checked((ushort)(GraphicsLayouts.RastPortSize / sizeof(uint) - 1)));
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, DecrementBranchD1);
        Append(code, 0xFFFC); // DBRA back to the first longword store

        Append(code, MoveQuickMinusOneD0);
        AppendSetByteBody(code, GraphicsLayouts.RastPortMask);
        AppendSetByteBody(code, GraphicsLayouts.RastPortFgPen);
        AppendSetByteBody(code, GraphicsLayouts.RastPortOutlinePen);
        Append(code, MoveQuickZeroD0);
        AppendSetByteBody(code, GraphicsLayouts.RastPortBgPen);
        Append(code, MoveQuickOneD0);
        AppendSetByteBody(code, GraphicsLayouts.RastPortDrawMode);
        Append(code, MoveQuickMinusOneD0);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePattern));
        Append(code, MoveLongImmediateD0);
        Append(code, 0xCACA);
        Append(code, 0xCACA);
        Append(code, MoveLongD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMinterms));
        Append(code, MoveLongD0ToA1Displacement);
        Append(code, checked((ushort)(GraphicsLayouts.RastPortMinterms + 4)));

        Append(code, MoveLongA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseDefaultFont));
        Append(code, MoveLongD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFont));
        Append(code, TestLongD0);
        Append(code, (ushort)(BranchEqualShort | 0x0020)); // skip metrics
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontYSize));
        Append(code, MoveWordD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextHeight));
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontXSize));
        Append(code, MoveWordD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextWidth));
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontBaseline));
        Append(code, MoveWordD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextBaseline));
        Append(code, MoveQuickZeroD0);
        AppendSetByteBody(code, GraphicsLayouts.RastPortAlgoStyle);
        Append(code, MoveQuickZeroD0);
        var restoreOffset = code.Count;
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x0040); // D6; preserve success/decline D0 and CCR
        Append(code, ReturnFromSubroutine);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, restoreOffset);
        return offset;
    }

    /// <summary>
    /// Emits the bounded native guest-only InitGels sentinel lifecycle.
    /// ABI: A0=head VSprite, A1=tail VSprite, A2=GelsInfo.  The native arm
    /// claims only three distinct, ordered standard envelopes whose complete
    /// spans do not overlap and whose collision-handler field is zero.  That
    /// deliberately leaves resident collision tables and non-canonical guest
    /// layouts to the portable/provider owner.  On success both VSprite
    /// envelopes are cleared, the classic sentinel links/coordinates are
    /// published, and GelsInfo Head/Tail/Flags are initialized.  D0 is zero
    /// on success and is restored before the compatibility fallback.
    /// </summary>
    private static int AppendInitGels(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(16);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        // Keep the caller-visible D0 intact on every native decline.  The
        // vector is void-shaped, but preserving the register makes the native
        // arm transparent when its narrow guest-only admission is not met.
        Append(code, MoveLongD0ToPreDecrementA7);

        // Preserve the three descriptor bases while A0/D0/D1 are used as
        // structural-validation scratch registers.
        Append(code, MoveLongA0ToA3);
        Append(code, MoveAddressA1ToA4);
        Append(code, MoveAddressA2ToA6);

        void CheckEnvelope(ushort selectAddress, ushort maximumLowWord)
        {
            Append(code, selectAddress);
            Append(code, MoveLongA0ToD0);
            Append(code, TestLongD0);
            Decline(BranchEqualWord);
            Append(code, BitTestImmediateD0);
            Append(code, 0);
            Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD0);
            Append(code, 0xFFFF);
            Append(code, maximumLowWord);
            Decline(BranchHighWord);
        }

        CheckEnvelope(MoveAddressA3ToA0, 0xFFC4); // VSprite head (0x3C)
        CheckEnvelope(MoveAddressA4ToA0, 0xFFC4); // VSprite tail (0x3C)
        CheckEnvelope(MoveAddressA6ToA0, 0xFFDA); // GelsInfo (0x26)

        // Require a canonical, non-overlapping order.  The inclusive end
        // checks admit an exactly adjacent envelope while rejecting every
        // possible overlap before the first guest write.
        Append(code, MoveAddressA3ToA0);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0);
        Append(code, MoveLongA0ToD0);
        Append(code, MoveLongA4ToD1);
        Append(code, CompareLongD0ToD1);
        Decline(BranchCarryWord);

        Append(code, MoveAddressA4ToA0);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickEightLongA0);
        Append(code, AddQuickTwoLongA0);
        Append(code, AddQuickTwoLongA0);
        Append(code, MoveLongA0ToD0);
        Append(code, MoveLongA6ToD1);
        Append(code, CompareLongD0ToD1);
        Decline(BranchCarryWord);

        // The narrow native arm does not clear or invoke a resident
        // collision table.  A non-null handler therefore remains with the
        // portable transaction, which can validate and clear that table.
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.GelsInfoCollisionHandler));
        Append(code, TestLongD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveQuickZeroD0);

        // Clear the complete standard VSprite envelopes (0x3C = 15 LONGs)
        // before publishing the reciprocal links and sentinel coordinates.
        void ClearVSprite(ushort selectAddress)
        {
            Append(code, selectAddress);
            for (var index = 0; index < GraphicsLayouts.VSpriteSize / sizeof(uint); index++)
                Append(code, MoveLongD0ToA0PostIncrement);
        }

        ClearVSprite(MoveAddressA3ToA0);
        ClearVSprite(MoveAddressA4ToA0);

        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteClearPath));
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));

        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));

        Append(code, MoveAddressA3ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, 0x8000);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteOldY));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteOldX));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteY));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteX));

        Append(code, MoveAddressA4ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, 0x7FFF);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteOldY));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteOldX));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteY));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteX));

        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.GelsInfoHead));
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.GelsInfoTail));
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.GelsInfoFlags));

        // Success consumes the saved D0 and returns the classic void result.
        var successOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    /// <summary>
    /// Emits the bounded native SetCollision table-entry update.
    ///
    /// ABI: D0=collision number, A0=routine, A1=GelsInfo.  The native arm
    /// claims the standard sixteen-entry table form only when the selected
    /// GelsInfo and handler-table envelopes are even, non-wrapping guest
    /// addresses.  It writes exactly one handler LONG and otherwise restores
    /// D0 before tailing to the portable/provider owner.  The routine pointer
    /// itself is intentionally opaque; Kickstart stores it without trying to
    /// validate or invoke it here.
    /// </summary>
    private static int AppendSetCollision(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(12);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        // SetCollision is void-shaped, but preserve the incoming selector so
        // an unclaimed layout is indistinguishable from the provider path.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD0ToD7); // selector scratch
        Append(code, MoveLongA0ToA3); // opaque routine pointer
        Append(code, MoveAddressA1ToA4); // GelsInfo base

        // The public collision table has sixteen LONG entries (0..15).
        Append(code, CompareImmediateLongD7);
        Append(code, 0x0000);
        Append(code, (ushort)(GraphicsLayouts.CollisionTableEntries - 1));
        Decline(BranchHighWord);

        // GelsInfo is a standard 0x26-byte envelope.  Require a long-aligned
        // non-null base so every direct 68000 access below is bus-safe.
        Append(code, MoveLongA4ToD6);
        Append(code, TestLongD6);
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFDA); // GelsInfoSize (0x26) envelope
        Decline(BranchHighWord);

        // GelsInfo->CollisionHandler points at the selected table.  A
        // FFFFFFC0 ceiling covers all 16*4 bytes plus the final LONG read,
        // preventing ADD.L wraparound before the indirect publication.
        Append(code, MoveLongA4DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.GelsInfoCollisionHandler));
        Append(code, TestLongD6);
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFC0);
        Decline(BranchHighWord);

        // D7*4 is the byte offset of the selected collision LONG.
        Append(code, MoveLongD7ToD0);
        Append(code, ShiftLeftLongD0);
        Append(code, ShiftLeftLongD0);
        Append(code, AddLongD0ToD6);
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToA0); // publish routine pointer

        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    /// <summary>
    /// Emits the bounded native one-word InitMasks slice.
    ///
    /// ABI: A0=VSprite.  The native arm claims only an explicit VSprite
    /// (VSPRITE flag set) whose width, height, and depth are all one.  It
    /// reads the single image word, mirrors it to BorderLine and CollMask,
    /// and keeps Bob/ImageShadow resolution plus multi-word/multi-plane mask
    /// construction on the portable/provider owner.
    /// </summary>
    private static int AppendInitMasksOneWord(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(20);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        // Preserve the void-vector D0 result across every structural decline.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA0ToA3);

        // VSpriteSize is 0x3C bytes.  Keep all direct LONG/WORD accesses
        // aligned and inside the 32-bit guest envelope.
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFC4); // VSpriteSize (0x3C) envelope
        Decline(BranchHighWord);

        // The one-word native form has no Bob indirection and therefore
        // requires an explicit VSprite plus the exact 1x1x1 dimensions.
        Append(code, MoveWordA3DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteFlags));
        Append(code, CompareImmediateWordD5);
        Append(code, GraphicsLayouts.VSpriteFlag);
        Decline(BranchNotEqualWord);

        void RequireOne(ushort displacement)
        {
            Append(code, MoveWordA3DisplacementToD5);
            Append(code, displacement);
            Append(code, CompareImmediateWordD5);
            Append(code, 0x0001);
            Decline(BranchNotEqualWord);
        }

        RequireOne((ushort)GraphicsLayouts.VSpriteHeight);
        RequireOne((ushort)GraphicsLayouts.VSpriteWidth);
        RequireOne((ushort)GraphicsLayouts.VSpriteDepth);

        void CapturePointer(ushort displacement, ushort destinationAddressMove)
        {
            Append(code, MoveLongA3DisplacementToD4);
            Append(code, displacement);
            Append(code, TestLongD4);
            Decline(BranchEqualWord);
            Append(code, BitTestImmediateD4);
            Append(code, 0);
            Decline(BranchNotEqualWord);
            Append(code, CompareImmediateLongD4);
            Append(code, 0xFFFF);
            Append(code, 0xFFFD); // two-byte word envelope
            Decline(BranchHighWord);
            Append(code, destinationAddressMove);
        }

        CapturePointer(
            (ushort)GraphicsLayouts.VSpriteImageData,
            MoveAddressD4ToA4);
        CapturePointer(
            (ushort)GraphicsLayouts.VSpriteBorderLine,
            MoveAddressD4ToA5);
        CapturePointer(
            (ushort)GraphicsLayouts.VSpriteCollMask,
            MoveAddressD4ToA6);

        // Read the single planar image word once, then publish it to both
        // caller-owned destination words.  No write occurs before all three
        // destination pointers have passed structural admission.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, 0);
        Append(code, MoveWordD0ToD7);

        Append(code, MoveAddressA5ToA0);
        Append(code, MoveWordD7ToD0);
        Append(code, MoveWordD0ToA0);

        Append(code, MoveAddressA6ToA0);
        Append(code, MoveWordD7ToD0);
        Append(code, MoveWordD0ToA0);

        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    /// <summary>
    /// Emits the bounded native RemVSprite reciprocal unlink.
    ///
    /// ABI: A0=VSprite.  The native arm claims one already-linked sprite
    /// whose Prev/Next neighbors are complete, aligned VSprite envelopes and
    /// whose reciprocal links point back to the sprite.  It rewrites the two
    /// neighbor links and clears the removed sprite's links; malformed,
    /// self-linked, odd, or wrapping chains restore D0 and use the portable
    /// owner.
    /// </summary>
    private static int AppendRemVSprite(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(24);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void CheckEnvelope(ushort testOpcode, ushort compareOpcode)
        {
            Append(code, testOpcode);
            Decline(BranchEqualWord);
            Append(code, BitTestImmediateD4);
            Append(code, 0);
            Decline(BranchNotEqualWord);
            Append(code, compareOpcode);
            Append(code, 0xFFFF);
            Append(code, 0xFFC4); // VSpriteSize (0x3C) envelope
            Decline(BranchHighWord);
        }

        // Preserve the void-vector D0 result and the removed sprite identity.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA0ToD7);
        Append(code, MoveLongA0ToA3);

        // Validate the removed sprite before reading either link.
        Append(code, MoveLongA0ToD4);
        CheckEnvelope(TestLongD4, CompareImmediateLongD4);

        // Previous is retained in D4/A4; Next is retained in D5.  Both
        // pointers are checked before any neighbor field is dereferenced.
        Append(code, MoveLongA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        CheckEnvelope(TestLongD4, CompareImmediateLongD4);
        Append(code, MoveLongD7ToD0);
        Append(code, CompareLongD4ToD0);
        Decline(BranchEqualWord);
        Append(code, MoveAddressD4ToA4);

        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, TestLongD5);
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD5);
        Append(code, 0);
        Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD5);
        Append(code, 0xFFFF);
        Append(code, 0xFFC4);
        Decline(BranchHighWord);
        Append(code, MoveLongD7ToD0);
        Append(code, CompareLongD5ToD0);
        Decline(BranchEqualWord);
        Append(code, CompareLongD5ToD4);
        Decline(BranchEqualWord);

        // Neighbor links must be reciprocal before publication.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveLongD7ToD0);
        Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, MoveLongD7ToD0);
        Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        // Publish previous.Next=next and next.Prev=previous, then clear both
        // links in the removed sprite.  All destination spans were checked
        // structurally before the first store.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));

        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));

        Append(code, MoveAddressA3ToA0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));

        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    /// <summary>
    /// Emits the bounded native AddVSprite insertion for empty and singleton
    /// lists.
    ///
    /// ABI: A0=VSprite, A1=RastPort.  The native arm admits only a valid
    /// RastPort/GelsInfo whose list is exactly Head->Tail or Head->Node->Tail,
    /// whose outer sentinel links are NULL, and an unlinked VSprite.  It
    /// publishes the corresponding insertion and preserves only the caller's
    /// user flag bits; longer sorted insertion stays with the portable/provider
    /// owner.
    /// </summary>
    private static int AppendAddVSpriteBoundedList(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(32);

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void CheckEnvelope(ushort compareOpcode, ushort maximumLowWord)
        {
            Append(code, TestLongD6);
            Decline(BranchEqualWord);
            Append(code, BitTestImmediateD6);
            Append(code, 0);
            Decline(BranchNotEqualWord);
            Append(code, compareOpcode);
            Append(code, 0xFFFF);
            Append(code, maximumLowWord);
            Decline(BranchHighWord);
        }

        // Preserve D0 and the caller-owned sprite identity.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongA0ToD7);
        Append(code, MoveLongA0ToD6);
        CheckEnvelope(CompareImmediateLongD6, 0xFFC4); // VSpriteSize
        Append(code, MoveLongA0ToA3);

        // A1 is the RastPort; retain it in A4 while resolving GelsInfo.
        Append(code, MoveAddressA1ToA4);
        Append(code, MoveLongA4ToD6);
        CheckEnvelope(
            CompareImmediateLongD6,
            unchecked((ushort)(uint.MaxValue - (GraphicsLayouts.RastPortMinimumSize - 1))));
        Append(code, MoveLongA4DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortGelsInfo));
        CheckEnvelope(CompareImmediateLongD6, 0xFFDA); // GelsInfoSize
        Append(code, MoveAddressD6ToA5);

        // Resolve and retain the standard head and tail sentinels.
        Append(code, MoveLongA5DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.GelsInfoHead));
        CheckEnvelope(CompareImmediateLongD6, 0xFFC4);
        Append(code, MoveAddressD6ToA6);

        Append(code, MoveLongA5DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.GelsInfoTail));
        CheckEnvelope(CompareImmediateLongD6, 0xFFC4);
        Append(code, MoveAddressD6ToA2);
        Append(code, MoveLongA6ToD0);
        Append(code, CompareLongD6ToD0);
        Decline(BranchEqualWord);

        // Both sentinel boundary links must be clear before either the empty
        // or singleton insertion can claim the list.  The native publication
        // writes only the forward Head link and the backward Tail link, so a
        // stale outer link would otherwise survive the mutation.
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, TestLongD4);
        Decline(BranchNotEqualWord);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, TestLongD4);
        Decline(BranchNotEqualWord);

        // The empty Head->Tail topology joins the existing publication body;
        // a non-empty link continues through the bounded singleton arm below.
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveLongA2ToD0);
        Append(code, CompareLongD6ToD0);
        Append(code, BranchEqualWord);
        var emptyBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Singleton existing node: validate its complete reciprocal topology
        // and retain it in A4 while the new sprite remains in A3.
        Append(code, TestLongD6);
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFC4);
        Decline(BranchHighWord);
        Append(code, MoveAddressD6ToA4);
        Append(code, MoveLongA4DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, MoveLongA6ToD0);
        Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveLongA2ToD0);
        Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, MoveLongA4ToD0);
        Append(code, CompareLongD6ToD0);
        Decline(BranchNotEqualWord);

        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, TestLongD6);
        Decline(BranchNotEqualWord);

        // The inserted sprite must not already be linked in either form.
        Append(code, MoveLongA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, TestLongD4);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, TestLongD4);
        Decline(BranchNotEqualWord);

        Append(code, MoveWordA3DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteFlags));
        Append(code, AndImmediateWordD5);
        Append(code, GraphicsLayouts.VSpriteUserFlags);

        // Compare the new sprite with the existing node by signed Y then X.
        Append(code, MoveWordA4DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteY));
        Append(code, MoveWordA3DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteY));
        Append(code, CompareWordD4ToD6);
        Append(code, BranchMinusWord);
        var singletonBeforeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchEqualWord);
        var singletonTieBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var singletonAfterBranchExtensionOffset = code.Count;
        Append(code, 0);

        var singletonTieOffset = code.Count;
        Append(code, MoveWordA4DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteX));
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteX));
        Append(code, CompareWordD5ToD4);
        Append(code, BranchMinusWord);
        var singletonBeforeFromXBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var singletonAfterFromXBranchExtensionOffset = code.Count;
        Append(code, 0);

        var singletonBeforeOffset = code.Count;
        // Head -> new -> existing -> Tail.
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA6ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, BranchAlwaysWord);
        var singletonBeforeJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var singletonAfterOffset = code.Count;
        // Head -> existing -> new -> Tail.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA6ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, MoveLongA2ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, BranchAlwaysWord);
        var singletonAfterJoinBranchExtensionOffset = code.Count;
        Append(code, 0);

        var singletonFlagPublishOffset = code.Count;
        Append(code, MoveWordD5ToA3Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteFlags));
        Append(code, BranchAlwaysWord);
        var singletonSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);

        var emptyInsertionOffset = code.Count;
        // Empty Head->Tail insertion continues with the original body.

        Append(code, MoveLongA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, TestLongD4);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, TestLongD4);
        Decline(BranchNotEqualWord);

        Append(code, MoveWordA3DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteFlags));
        Append(code, AndImmediateWordD5);
        Append(code, GraphicsLayouts.VSpriteUserFlags);

        // Head->Sprite->Tail and reciprocal links.
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA6ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, MoveLongA2ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));

        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));

        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));

        Append(code, MoveWordD5ToA3Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteFlags));

        var successOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, emptyBranchExtensionOffset, emptyInsertionOffset);
        PatchBranch(code, singletonTieBranchExtensionOffset, singletonTieOffset);
        PatchBranch(code, singletonBeforeBranchExtensionOffset, singletonBeforeOffset);
        PatchBranch(code, singletonBeforeFromXBranchExtensionOffset, singletonBeforeOffset);
        PatchBranch(code, singletonAfterBranchExtensionOffset, singletonAfterOffset);
        PatchBranch(code, singletonAfterFromXBranchExtensionOffset, singletonAfterOffset);
        PatchBranch(code, singletonBeforeJoinBranchExtensionOffset, singletonFlagPublishOffset);
        PatchBranch(code, singletonAfterJoinBranchExtensionOffset, singletonFlagPublishOffset);
        PatchBranch(code, singletonSuccessBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    /// <summary>
    /// Emits the bounded native SortGList arm for empty, singleton, and
    /// exactly-two/three-node chains.
    ///
    /// ABI: A1=RastPort.  Empty and singleton lists are validated read-only
    /// no-ops.  Two- and three-node chains are sorted by signed Y then signed
    /// X, with stable order for equal positions.  Longer, malformed, odd,
    /// wrapping, provider, RTG, and CyberGraphX chains retain the
    /// portable/provider sorter.
    /// </summary>
    private static int AppendSortGListBoundedNative(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(40);

        (List<int> Less, List<int> NotLess) AppendStrictPositionLess(
            ushort leftY,
            ushort leftX,
            ushort rightY,
            ushort rightX)
        {
            var lessBranches = new List<int>(2);
            var notLessBranches = new List<int>(2);

            Append(code, leftY);
            Append(code, checked((ushort)GraphicsLayouts.VSpriteY));
            Append(code, rightY);
            Append(code, checked((ushort)GraphicsLayouts.VSpriteY));
            Append(code, CompareWordD4ToD6);
            Append(code, BranchMinusWord);
            lessBranches.Add(code.Count);
            Append(code, 0);
            Append(code, BranchEqualWord);
            var tieExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BranchAlwaysWord);
            notLessBranches.Add(code.Count);
            Append(code, 0);

            var tieOffset = code.Count;
            Append(code, leftX);
            Append(code, checked((ushort)GraphicsLayouts.VSpriteX));
            Append(code, rightX);
            Append(code, checked((ushort)GraphicsLayouts.VSpriteX));
            Append(code, CompareWordD5ToD4);
            Append(code, BranchMinusWord);
            lessBranches.Add(code.Count);
            Append(code, 0);
            Append(code, BranchAlwaysWord);
            notLessBranches.Add(code.Count);
            Append(code, 0);
            PatchBranch(code, tieExtensionOffset, tieOffset);
            return (lessBranches, notLessBranches);
        }

        void Decline(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(extensionOffset);
        }

        void CheckEnvelope(ushort compareOpcode, ushort maximumLowWord)
        {
            Append(code, TestLongD6);
            Decline(BranchEqualWord);
            Append(code, BitTestImmediateD6);
            Append(code, 0);
            Decline(BranchNotEqualWord);
            Append(code, compareOpcode);
            Append(code, 0xFFFF);
            Append(code, maximumLowWord);
            Decline(BranchHighWord);
        }

        // Preserve the void-shaped D0 result while all list fields are read.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveAddressA1ToA4);
        Append(code, MoveLongA4ToD6);
        CheckEnvelope(
            CompareImmediateLongD6,
            unchecked((ushort)(uint.MaxValue - (GraphicsLayouts.RastPortMinimumSize - 1))));

        Append(code, MoveLongA4DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortGelsInfo));
        CheckEnvelope(CompareImmediateLongD6, 0xFFDA); // GelsInfoSize
        Append(code, MoveAddressD6ToA5);

        Append(code, MoveLongA5DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.GelsInfoHead));
        CheckEnvelope(CompareImmediateLongD6, 0xFFC4); // VSpriteSize
        Append(code, MoveAddressD6ToA6); // Head

        Append(code, MoveLongA5DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.GelsInfoTail));
        CheckEnvelope(CompareImmediateLongD6, 0xFFC4); // VSpriteSize
        Append(code, MoveAddressD6ToA2); // Tail; D6 retains Tail

        // Keep Head in D1.  The first Head.Next pointer distinguishes the
        // empty form from a one- or two-node chain.
        Append(code, MoveLongA6ToD1);
        Append(code, CompareLongD6ToD1);
        Decline(BranchEqualWord);
        Append(code, MoveLongA6DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, CompareLongD6ToD4);
        Append(code, BranchEqualWord);
        var emptyBranchExtensionOffset = code.Count;
        Append(code, 0);

        // First node must be a distinct, complete, even VSprite whose Prev
        // points back to Head.
        Append(code, TestLongD4);
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFC4);
        Decline(BranchHighWord);
        Append(code, CompareLongD4ToD1);
        Decline(BranchEqualWord);
        Append(code, MoveAddressD4ToA3); // first node
        Append(code, MoveLongA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, CompareLongD4ToD1);
        Decline(BranchNotEqualWord);

        // First.Next == Tail is the validated singleton form.  Otherwise D4
        // is the second node and must pass the same envelope checks.
        Append(code, MoveLongA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, CompareLongD6ToD4);
        Append(code, BranchEqualWord);
        var singletonBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, TestLongD4);
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFC4);
        Decline(BranchHighWord);
        Append(code, CompareLongD4ToD1); // reject a second Head self-link
        Decline(BranchEqualWord);
        Append(code, MoveAddressD4ToA5); // second node

        // The second node must point back to the first.  A direct Tail link is
        // the two-node form; otherwise D4 is a candidate third node.
        Append(code, MoveLongA3ToD1); // D1 = first (Head no longer needed)
        Append(code, MoveLongA5DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, CompareLongD4ToD1);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA5DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, CompareLongD6ToD4);
        Append(code, BranchEqualWord);
        var twoNodeBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Third node: distinct, complete, even, and reciprocal with the
        // second node.  It must terminate directly at Tail.
        Append(code, TestLongD4);
        Decline(BranchEqualWord);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Decline(BranchNotEqualWord);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFC4);
        Decline(BranchHighWord);
        Append(code, CompareLongD4ToD1); // reject a third Head/first self-link
        Decline(BranchEqualWord);
        Append(code, MoveLongA5ToD0);
        Append(code, CompareLongD4ToD0); // reject a third second-node link
        Decline(BranchEqualWord);
        Append(code, MoveLongA6ToD0);
        Append(code, CompareLongD4ToD0); // reject a third Head link
        Decline(BranchEqualWord);
        Append(code, MoveAddressD4ToA4); // third node
        Append(code, MoveLongA4DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, MoveLongA5ToD0);
        Append(code, CompareLongD4ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA4DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, CompareLongD6ToD4);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, MoveLongA4ToD0);
        Append(code, CompareLongD4ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, TestLongD4);
        Decline(BranchNotEqualWord);
        Append(code, BranchAlwaysWord);
        var threeNodeBranchExtensionOffset = code.Count;
        Append(code, 0);

        var twoNodeOffset = code.Count;
        // Two-node tail: Tail must point back to the second and terminate the
        // chain.
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, MoveLongA5ToD0);
        Append(code, CompareLongD4ToD0);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, TestLongD4);
        Decline(BranchNotEqualWord);

        // Compare signed node positions.  D4/D5 hold first Y/X and D6/D4
        // hold second Y/X.  A negative result means the second node sorts
        // before the first and selects the six-link swap below.
        Append(code, MoveWordA3DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteY));
        Append(code, MoveWordA5DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteY));
        Append(code, CompareWordD4ToD6);
        Append(code, BranchMinusWord);
        var swapFromYBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchEqualWord);
        var tieXBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var keepOrderFromYBranchExtensionOffset = code.Count;
        Append(code, 0);

        var tieXOffset = code.Count;
        Append(code, MoveWordA3DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteX));
        Append(code, MoveWordA5DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteX));
        Append(code, CompareWordD5ToD4);
        Append(code, BranchMinusWord);
        var swapFromXBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var keepOrderFromXBranchExtensionOffset = code.Count;
        Append(code, 0);

        var swapOffset = code.Count;
        // Head.Next = second, second.Prev = Head, second.Next = first.
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongA5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA6ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));

        // First.Prev = second, first.Next = Tail, Tail.Prev = first.
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, MoveLongA2ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));

        var successOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var threeNodeOffset = code.Count;
        // Preserve the original node identities while the position compares
        // reuse D4/D5/D6 as signed WORD temporaries.  A0 carries the third
        // node; D0 and D1 carry the first and second nodes respectively.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongA5ToD1);

        // Stable insertion ordering: first order node 1/2, then insert node
        // 3 into that pair.  The strict comparator treats equal Y/X as
        // not-less, retaining the original order.
        var secondBeforeFirst = AppendStrictPositionLess(
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD5,
            MoveWordA5DisplacementToD6,
            MoveWordA5DisplacementToD4);
        var pairKeepOffset = code.Count;
        foreach (var extensionOffset in secondBeforeFirst.NotLess)
            PatchBranch(code, extensionOffset, pairKeepOffset);

        var thirdBeforeFirst = AppendStrictPositionLess(
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD5,
            MoveWordA4DisplacementToD6,
            MoveWordA4DisplacementToD4);
        var thirdBeforeSecondOffset = code.Count;
        foreach (var extensionOffset in thirdBeforeFirst.NotLess)
            PatchBranch(code, extensionOffset, thirdBeforeSecondOffset);

        var thirdBeforeSecond = AppendStrictPositionLess(
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD5,
            MoveWordA4DisplacementToD6,
            MoveWordA4DisplacementToD4);

        var secondBeforeOffset = code.Count;
        foreach (var extensionOffset in secondBeforeFirst.Less)
            PatchBranch(code, extensionOffset, secondBeforeOffset);

        var thirdBeforeSecondNode = AppendStrictPositionLess(
            MoveWordA5DisplacementToD4,
            MoveWordA5DisplacementToD5,
            MoveWordA4DisplacementToD6,
            MoveWordA4DisplacementToD4);
        var thirdBeforeFirstAfterSecondOffset = code.Count;
        foreach (var extensionOffset in thirdBeforeSecondNode.NotLess)
            PatchBranch(code, extensionOffset, thirdBeforeFirstAfterSecondOffset);

        var thirdBeforeFirstAfterSecond = AppendStrictPositionLess(
            MoveWordA3DisplacementToD4,
            MoveWordA3DisplacementToD5,
            MoveWordA4DisplacementToD6,
            MoveWordA4DisplacementToD4);

        // Each outcome arranges A3/A5/A4 as sorted first/second/third and
        // joins the single publication block below.
        var orderBranches = new List<int>(6);

        var orderThirdFirstSecondOffset = code.Count;
        foreach (var extensionOffset in thirdBeforeFirst.Less)
            PatchBranch(code, extensionOffset, orderThirdFirstSecondOffset);
        Append(code, MoveAddressA0ToA3);
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveAddressD1ToA4);
        Append(code, BranchAlwaysWord);
        orderBranches.Add(code.Count);
        Append(code, 0);

        var orderFirstThirdSecondOffset = code.Count;
        foreach (var extensionOffset in thirdBeforeSecond.Less)
            PatchBranch(code, extensionOffset, orderFirstThirdSecondOffset);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveAddressA0ToA5);
        Append(code, MoveAddressD1ToA4);
        Append(code, BranchAlwaysWord);
        orderBranches.Add(code.Count);
        Append(code, 0);

        var orderFirstSecondThirdOffset = code.Count;
        foreach (var extensionOffset in thirdBeforeSecond.NotLess)
            PatchBranch(code, extensionOffset, orderFirstSecondThirdOffset);
        Append(code, MoveAddressD0ToA3);
        Append(code, MoveAddressD1ToA5);
        Append(code, MoveAddressA0ToA4);
        Append(code, BranchAlwaysWord);
        orderBranches.Add(code.Count);
        Append(code, 0);

        var orderThirdSecondFirstOffset = code.Count;
        foreach (var extensionOffset in thirdBeforeSecondNode.Less)
            PatchBranch(code, extensionOffset, orderThirdSecondFirstOffset);
        Append(code, MoveAddressA0ToA3);
        Append(code, MoveAddressD1ToA5);
        Append(code, MoveAddressD0ToA4);
        Append(code, BranchAlwaysWord);
        orderBranches.Add(code.Count);
        Append(code, 0);

        var orderSecondThirdFirstOffset = code.Count;
        foreach (var extensionOffset in thirdBeforeFirstAfterSecond.Less)
            PatchBranch(code, extensionOffset, orderSecondThirdFirstOffset);
        Append(code, MoveAddressD1ToA3);
        Append(code, MoveAddressA0ToA5);
        Append(code, MoveAddressD0ToA4);
        Append(code, BranchAlwaysWord);
        orderBranches.Add(code.Count);
        Append(code, 0);

        var orderSecondFirstThirdOffset = code.Count;
        foreach (var extensionOffset in thirdBeforeFirstAfterSecond.NotLess)
            PatchBranch(code, extensionOffset, orderSecondFirstThirdOffset);
        Append(code, MoveAddressD1ToA3);
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveAddressA0ToA4);
        Append(code, BranchAlwaysWord);
        orderBranches.Add(code.Count);
        Append(code, 0);

        var threeNodePublishOffset = code.Count;
        // Publish Head -> A3 -> A5 -> A4 -> Tail and all reciprocal Prev
        // links only after sorting has completed without a decline.
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA6ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA3ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA2ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, BranchAlwaysWord);
        var threeNodeSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);

        foreach (var extensionOffset in orderBranches)
            PatchBranch(code, extensionOffset, threeNodePublishOffset);

        var emptyOffset = code.Count;
        // Empty: Tail.Prev = Head and Tail.Next = NULL.
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, CompareLongD4ToD1);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, TestLongD4);
        Decline(BranchNotEqualWord);
        Append(code, BranchAlwaysWord);
        var emptySuccessBranchExtensionOffset = code.Count;
        Append(code, 0);

        var singletonOffset = code.Count;
        // Singleton: Tail.Prev = first and Tail.Next = NULL.
        Append(code, MoveLongA3ToD1);
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpritePrev));
        Append(code, CompareLongD4ToD1);
        Decline(BranchNotEqualWord);
        Append(code, MoveLongA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.VSpriteNext));
        Append(code, TestLongD4);
        Decline(BranchNotEqualWord);
        Append(code, BranchAlwaysWord);
        var singletonSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, emptyBranchExtensionOffset, emptyOffset);
        PatchBranch(code, singletonBranchExtensionOffset, singletonOffset);
        PatchBranch(code, twoNodeBranchExtensionOffset, twoNodeOffset);
        PatchBranch(code, threeNodeBranchExtensionOffset, threeNodeOffset);
        PatchBranch(code, threeNodeSuccessBranchExtensionOffset, successOffset);
        PatchBranch(code, tieXBranchExtensionOffset, tieXOffset);
        PatchBranch(code, keepOrderFromYBranchExtensionOffset, successOffset);
        PatchBranch(code, keepOrderFromXBranchExtensionOffset, successOffset);
        PatchBranch(code, swapFromYBranchExtensionOffset, swapOffset);
        PatchBranch(code, swapFromXBranchExtensionOffset, swapOffset);
        PatchBranch(code, emptySuccessBranchExtensionOffset, successOffset);
        PatchBranch(code, singletonSuccessBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    /// <summary>
    /// Emits the private native half of the first screen lifecycle unit.
    ///
    /// ABI (for a future native OpenScreen owner): A0=View, A1=ViewPort,
    /// A2=RasInfo, A3=BitMap, D0=width, D1=height, D2=plane0. The body owns
    /// only the four public envelopes and publishes one standard-planar link;
    /// allocation, display-DMA admission, and plane ownership remain outside
    /// this ROM body. D0 returns one on success and zero when the preflight
    /// rejects the descriptors or geometry. No public LVO points here.
    /// </summary>
    private static int AppendInitScreenResourceChain(List<byte> code)
    {
        var offset = code.Count;
        var failureBranches = new List<int>(24);

        void BranchToFailure(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            failureBranches.Add(extensionOffset);
        }

        void CheckAddress(ushort selectAddress, uint maximumAddress)
        {
            Append(code, selectAddress);
            Append(code, MoveLongA0ToD7);
            Append(code, TestLongD7);
            BranchToFailure(BranchEqualWord);
            Append(code, BitTestImmediateD7);
            Append(code, 0);
            BranchToFailure(BranchNotEqualWord);
            Append(code, CompareImmediateLongD7);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            BranchToFailure(BranchHighWord);
        }

        void CheckUnsignedWord(ushort testOpcode, ushort compareOpcode)
        {
            Append(code, testOpcode);
            BranchToFailure(BranchEqualWord);
            Append(code, compareOpcode);
            Append(code, 0x0000);
            Append(code, 0xFFFF);
            BranchToFailure(BranchHighWord);
        }

        // Preserve all four descriptor bases in address registers before the
        // preflight starts using A0/D7 as scratch.
        Append(code, MoveAddressA0ToA4);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveAddressA0ToA5);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveAddressA0ToA6);

        CheckAddress(MoveAddressA4ToA0, 0xFFFF_FFEEu); // ViewSize
        CheckAddress(MoveAddressA5ToA0, 0xFFFF_FFD8u); // ViewPortSize
        CheckAddress(MoveAddressA6ToA0, 0xFFFF_FFF4u); // RasInfoSize
        CheckAddress(MoveAddressA3ToA0, 0xFFFF_FFD8u); // BitMapSize
        CheckUnsignedWord(TestLongD0, CompareImmediateLongD0);
        CheckUnsignedWord(TestLongD1, CompareImmediateLongD1);
        Append(code, TestLongD2);
        BranchToFailure(BranchEqualWord);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        BranchToFailure(BranchNotEqualWord);

        // The four public envelopes and the caller-owned plane span are one
        // transaction.  Do not clear or link any descriptor until every
        // range is known to be disjoint.  This mirrors the portable screen
        // registry's span admission and prevents an aliased ViewPort/RasInfo
        // or plane buffer from being partially rewritten by this private
        // native constructor.
        void CheckDisjoint(
            ushort firstLoadToD4,
            ushort secondLoadToD5,
            uint firstBytes,
            uint secondBytes)
        {
            Append(code, firstLoadToD4);
            Append(code, secondLoadToD5);
            Append(code, CompareLongD5ToD4); // first - second
            Append(code, BranchCarryWord);
            var firstBeforeSecondBranchExtensionOffset = code.Count;
            Append(code, 0);

            // second <= first: reject when second + size crosses first.
            Append(code, MoveLongD5ToD6);
            Append(code, AddImmediateLongD6);
            Append(code, (ushort)(secondBytes >> 16));
            Append(code, (ushort)secondBytes);
            Append(code, BranchCarryWord);
            var secondWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareLongD6ToD4); // first - secondEnd
            Append(code, BranchCarryWord);
            var secondOverlapsFirstBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BranchAlwaysWord);
            var disjointJoinBranchExtensionOffset = code.Count;
            Append(code, 0);

            // first < second: reject when first + size crosses second.
            var firstBeforeSecondOffset = code.Count;
            Append(code, MoveLongD4ToD6);
            Append(code, AddImmediateLongD6);
            Append(code, (ushort)(firstBytes >> 16));
            Append(code, (ushort)firstBytes);
            Append(code, BranchCarryWord);
            var firstWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareLongD6ToD5); // second - firstEnd
            Append(code, BranchCarryWord);
            var firstOverlapsSecondBranchExtensionOffset = code.Count;
            Append(code, 0);

            var disjointJoinOffset = code.Count;
            PatchBranch(
                code,
                firstBeforeSecondBranchExtensionOffset,
                firstBeforeSecondOffset);
            PatchBranch(code, disjointJoinBranchExtensionOffset, disjointJoinOffset);
            failureBranches.Add(secondWrapBranchExtensionOffset);
            failureBranches.Add(secondOverlapsFirstBranchExtensionOffset);
            failureBranches.Add(firstWrapBranchExtensionOffset);
            failureBranches.Add(firstOverlapsSecondBranchExtensionOffset);
        }

        void CheckPlaneAgainst(
            ushort envelopeLoadToD4,
            uint envelopeBytes)
        {
            // D2 is the plane base and D7 is the already-computed exclusive
            // plane end.  The two half-open ranges may touch but must not
            // overlap.
            Append(code, envelopeLoadToD4);
            Append(code, CompareLongD4ToD2); // plane - envelope
            Append(code, BranchLowerOrSameWord);
            var planeBeforeEnvelopeBranchExtensionOffset = code.Count;
            Append(code, 0);

            var envelopeBeforePlaneOffset = code.Count;
            Append(code, MoveLongD4ToD6);
            Append(code, AddImmediateLongD6);
            Append(code, (ushort)(envelopeBytes >> 16));
            Append(code, (ushort)envelopeBytes);
            Append(code, BranchCarryWord);
            var envelopeWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareLongD6ToD2); // plane - envelopeEnd
            Append(code, BranchCarryWord);
            var envelopeOverlapsPlaneBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BranchAlwaysWord);
            var planeDisjointJoinBranchExtensionOffset = code.Count;
            Append(code, 0);

            var planeBeforeEnvelopeOffset = code.Count;
            Append(code, CompareLongD7ToD4); // envelope - planeEnd
            Append(code, BranchCarryWord);
            var planeOverlapsEnvelopeBranchExtensionOffset = code.Count;
            Append(code, 0);

            var planeDisjointJoinOffset = code.Count;
            PatchBranch(
                code,
                planeBeforeEnvelopeBranchExtensionOffset,
                envelopeBeforePlaneOffset);
            PatchBranch(
                code,
                planeDisjointJoinBranchExtensionOffset,
                planeDisjointJoinOffset);
            failureBranches.Add(envelopeWrapBranchExtensionOffset);
            failureBranches.Add(envelopeOverlapsPlaneBranchExtensionOffset);
            failureBranches.Add(planeOverlapsEnvelopeBranchExtensionOffset);
        }

        CheckDisjoint(MoveLongA4ToD4, MoveLongA5ToD5,
            (uint)GraphicsLayouts.ViewSize, (uint)GraphicsLayouts.ViewPortSize);
        CheckDisjoint(MoveLongA4ToD4, MoveLongA6ToD5,
            (uint)GraphicsLayouts.ViewSize, (uint)GraphicsLayouts.RasInfoSize);
        CheckDisjoint(MoveLongA4ToD4, MoveLongA3ToD5,
            (uint)GraphicsLayouts.ViewSize, (uint)GraphicsLayouts.BitMapSize);
        CheckDisjoint(MoveLongA5ToD4, MoveLongA6ToD5,
            (uint)GraphicsLayouts.ViewPortSize, (uint)GraphicsLayouts.RasInfoSize);
        CheckDisjoint(MoveLongA5ToD4, MoveLongA3ToD5,
            (uint)GraphicsLayouts.ViewPortSize, (uint)GraphicsLayouts.BitMapSize);
        CheckDisjoint(MoveLongA6ToD4, MoveLongA3ToD5,
            (uint)GraphicsLayouts.RasInfoSize, (uint)GraphicsLayouts.BitMapSize);

        // Plane bytes are BytesPerRow * height, where BytesPerRow is the
        // smallest even standard-planar stride covering the requested width.
        // D0/D1/D2 remain intact for the descriptor initialization below.
        Append(code, MoveLongD0ToD4);
        Append(code, AddImmediateWordD4);
        Append(code, 0x000F);
        Append(code, ShiftRightWordD4Count1);
        Append(code, ShiftRightWordD4Count1);
        Append(code, ShiftRightWordD4Count1);
        Append(code, ShiftRightWordD4Count1);
        Append(code, AddLongD4ToD4);
        Append(code, MoveLongD1ToD5);
        Append(code, MoveLongD5ToD6);
        Append(code, MultiplyUnsignedWordD4ToD6);
        Append(code, MoveLongD2ToD7);
        Append(code, AddLongD6ToD7);
        Append(code, BranchCarryWord);
        var planeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        CheckPlaneAgainst(MoveLongA4ToD4, (uint)GraphicsLayouts.ViewSize);
        CheckPlaneAgainst(MoveLongA5ToD4, (uint)GraphicsLayouts.ViewPortSize);
        CheckPlaneAgainst(MoveLongA6ToD4, (uint)GraphicsLayouts.RasInfoSize);
        CheckPlaneAgainst(MoveLongA3ToD4, (uint)GraphicsLayouts.BitMapSize);
        failureBranches.Add(planeWrapBranchExtensionOffset);

        // Keep the caller's geometry and plane live while the four envelopes
        // are cleared. The stores below intentionally mirror the portable
        // InitializeScreenResourceChain layout contract.
        Append(code, MoveLongD0ToD5);
        Append(code, MoveLongD1ToD6);

        Append(code, MoveAddressA4ToA0);
        AppendClearLongWords(code, 0x7803); // four LONGs
        Append(code, MoveWordD0ToA0);       // trailing View word
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, 0x002C);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewDyOffset));
        Append(code, MoveImmediateWordD0);
        Append(code, 0x0081);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewDxOffset));

        Append(code, MoveAddressA5ToA0);
        AppendClearLongWords(code, 0x7809); // ten LONGs
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.ViewPortDefaultSpritePriorities);
        Append(code, 0x1140); // MOVE.B D0,(d16,A0)
        Append(code, checked((ushort)GraphicsLayouts.ViewPortSpritePriorities));
        Append(code, MoveLongD5ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDWidth));
        Append(code, MoveLongD6ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDHeight));

        Append(code, MoveAddressA6ToA0);
        AppendClearLongWords(code, 0x7802); // three LONGs

        Append(code, MoveAddressA3ToA0);
        AppendClearLongWords(code, 0x7809); // ten LONGs
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongD5ToD1);
        Append(code, AddImmediateWordD1);
        Append(code, 0x000F);
        Append(code, ShiftRightWordD1);
        Append(code, ShiftRightWordD1);
        Append(code, ShiftRightWordD1);
        Append(code, ShiftRightWordD1);
        Append(code, AddWordD1ToD1);
        Append(code, MoveWordD1ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveLongD6ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, 0x7008); // BMF_STANDARD
        Append(code, 0x1140);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, MoveQuickOneD3);
        Append(code, MoveByteD3ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongD2ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));

        // Publish the one-way View -> ViewPort -> RasInfo -> BitMap links
        // only after all four envelopes have been initialized.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA6ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0ToD0);
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoBitMap));
        Append(code, MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        var failureOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        foreach (var branchExtensionOffset in failureBranches)
            PatchBranch(code, branchExtensionOffset, failureOffset);

        return offset;
    }

    private static void AppendClearLongWords(List<byte> code, ushort dbraCount)
    {
        Append(code, MoveQuickZeroD0);
        Append(code, dbraCount);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, DecrementBranchD4);
        Append(code, 0xFFFC);
    }

    /// <summary>
    /// Emits the private native retire half of the screen lifecycle unit.
    /// ABI: A0=View, A1=ViewPort, A2=RasInfo, A3=BitMap. The exact three-link
    /// topology is checked before any envelope is cleared; D0 returns one on
    /// success and zero for malformed, replaced, or provider-owned links.
    /// Plane storage is never touched.
    /// </summary>
    private static int AppendTeardownScreenResourceChain(List<byte> code)
    {
        var offset = code.Count;
        var failureBranches = new List<int>(20);

        void BranchToFailure(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            failureBranches.Add(extensionOffset);
        }

        void CheckAddress(ushort selectAddress, uint maximumAddress)
        {
            Append(code, selectAddress);
            Append(code, MoveLongA0ToD7);
            Append(code, TestLongD7);
            BranchToFailure(BranchEqualWord);
            Append(code, BitTestImmediateD7);
            Append(code, 0);
            BranchToFailure(BranchNotEqualWord);
            Append(code, CompareImmediateLongD7);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            BranchToFailure(BranchHighWord);
        }

        Append(code, MoveAddressA0ToA4);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveAddressA0ToA5);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveAddressA0ToA6);

        CheckAddress(MoveAddressA4ToA0, 0xFFFF_FFEEu); // ViewSize
        CheckAddress(MoveAddressA5ToA0, 0xFFFF_FFD8u); // ViewPortSize
        CheckAddress(MoveAddressA6ToA0, 0xFFFF_FFF4u); // RasInfoSize
        CheckAddress(MoveAddressA3ToA0, 0xFFFF_FFD8u); // BitMapSize

        // Preserve the caller's exact link identities in D6 while the actual
        // guest fields are read through A0. A non-equal link declines before
        // any clear, matching the portable teardown ownership boundary.
        Append(code, MoveLongA5ToD6);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchNotEqualWord);

        Append(code, MoveLongA6ToD6);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchNotEqualWord);

        Append(code, MoveLongA3ToD6);
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoBitMap));
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchNotEqualWord);

        Append(code, MoveAddressA4ToA0);
        AppendClearLongWords(code, 0x7803); // four LONGs
        Append(code, MoveWordD0ToA0);
        Append(code, MoveAddressA5ToA0);
        AppendClearLongWords(code, 0x7809); // ten LONGs
        Append(code, MoveAddressA6ToA0);
        AppendClearLongWords(code, 0x7802); // three LONGs
        Append(code, MoveAddressA3ToA0);
        AppendClearLongWords(code, 0x7809); // ten LONGs
        Append(code, MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        var failureOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        foreach (var branchExtensionOffset in failureBranches)
            PatchBranch(code, branchExtensionOffset, failureOffset);

        return offset;
    }

    /// <summary>
    /// Emits the native Exec-backed display-resource allocator. It composes
    /// the one-plane Screen-prefix allocator, then acquires the display-side
    /// CopList, LOF/SHF CprLists, and a caller-sized raw copper envelope.
    /// The raw envelope starts with the canonical END marker; a bounded
    /// 16x1, 320x200, PAL 320x256, 640x200, or PAL 640x256 one-plane form may replace it with the native
    /// standard-planar register program. ABI: A6=ExecBase,
    /// D0/D1=width/height, D2=plane bytes, D3=copper bytes (even and >=4).
    /// Success returns Screen, View, RasInfo, plane, CopList, LOF CprList,
    /// SHF CprList, and raw copper in D0..D7. Every acquired block is freed
    /// on a later allocation failure, and all View/CopList/CprList links are
    /// published only after the complete bundle exists.
    /// </summary>
    private static int AppendAllocateDisplayResourcesExec(
        List<byte> code,
        int screenPrefixAllocatorOffset)
    {
        var offset = code.Count;
        var rawSizeBranches = new List<int>(4);
        var generatedEligibilityBranches = new List<int>(3);
        var wideGeneratedEligibilityBranches = new List<int>(3);
        var palWideGeneratedEligibilityBranches = new List<int>(3);
        var palLoresLaceGeneratedEligibilityBranches = new List<int>(3);
        var ntscLoresLaceGeneratedEligibilityBranches = new List<int>(3);
        var hiresGeneratedEligibilityBranches = new List<int>(3);
        var palHiresGeneratedEligibilityBranches = new List<int>(3);
        var palHiresLaceGeneratedEligibilityBranches = new List<int>(3);
        var ntscHiresLaceGeneratedEligibilityBranches = new List<int>(3);
        var prefixFailureBranches = new List<int>(1);
        var copFailureBranches = new List<int>(1);
        var lofFailureBranches = new List<int>(1);
        var shfFailureBranches = new List<int>(1);
        var rawFailureBranches = new List<int>(1);

        void AppendBranch(ushort opcode, List<int> branches)
        {
            Append(code, opcode);
            branches.Add(code.Count);
            Append(code, 0);
        }

        void AppendAllocMem(int byteCount, uint flags, List<int> failureBranches)
        {
            Append(code, MoveLongImmediateD0);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)(flags >> 16));
            Append(code, (ushort)flags);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
            Append(code, TestLongD0);
            AppendBranch(BranchEqualWord, failureBranches);
            Append(code, MoveLongD0ToPreDecrementA7);
        }

        void AppendFreeMemFromStack(int byteCount)
        {
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            AppendExecFreeMemFromD0D1PreservingA1(code);
        }

        // The raw copper envelope is part of the ABI, so reject malformed
        // sizes before the first Exec call. The upper bound keeps the body
        // within a 68000-addressable public allocation while still allowing
        // the full compatibility span used by host-side screen assembly.
        Append(code, MoveLongD3ToD4);
        Append(code, TestLongD4);
        AppendBranch(BranchEqualWord, rawSizeBranches);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        AppendBranch(BranchNotEqualWord, rawSizeBranches);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0003);
        AppendBranch(BranchLowerOrSameWord, rawSizeBranches);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0001);
        Append(code, 0x0000);
        AppendBranch(BranchHighWord, rawSizeBranches);

        // Keep the requested raw size and the plane allocation size below
        // the prefix allocator's private stack frame while it acquires
        // Screen/View/RasInfo/plane. Exec preserves D7, so the recovered
        // plane size can serve every dynamic FreeMem rollback below.
        Append(code, MoveLongD2ToD7);
        Append(code, MoveLongD7ToPreDecrementA7);
        Append(code, MoveLongD4ToPreDecrementA7);
        AppendJsrPcRelative(code, screenPrefixAllocatorOffset);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, prefixFailureBranches);
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveLongA7PostIncrementToD7);

        // The first native display-program slice is intentionally bounded to
        // nine canonical twelve-instruction standard-planar forms: the small
        // 16x1 lores probe, common 320x200/PAL 320x256 lores screens, PAL
        // 320x512 PAL / 320x400 NTSC lores interlace, and 640x200/PAL
        // 640x256 hires screen plus PAL 640x512/NTSC 640x400
        // hires-interlace screens. All
        // other geometry keeps the canonical
        // marker-only bundle and remains available to a later general
        // display-program owner.
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenWidth));
        Append(code, CompareImmediateWordD6);
        Append(code, 16);
        AppendBranch(BranchNotEqualWord, generatedEligibilityBranches);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenHeight));
        Append(code, CompareImmediateWordD6);
        Append(code, 1);
        AppendBranch(BranchNotEqualWord, generatedEligibilityBranches);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x002F);
        AppendBranch(BranchLowerOrSameWord, generatedEligibilityBranches);
        Append(code, CompareImmediateLongD7);
        Append(code, 0x0000);
        Append(code, 0x0001);
        AppendBranch(BranchLowerOrSameWord, generatedEligibilityBranches);
        Append(code, MoveQuickOneD6);
        Append(code, BranchAlwaysWord);
        var generatedModeJumpExtensionOffset = code.Count;
        Append(code, 0);

        var wideGeneratedModeOffset = code.Count;
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenWidth));
        Append(code, CompareImmediateWordD6);
        Append(code, 320);
        AppendBranch(BranchNotEqualWord, wideGeneratedEligibilityBranches);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenHeight));
        Append(code, CompareImmediateWordD6);
        Append(code, 200);
        AppendBranch(BranchNotEqualWord, wideGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x002F);
        AppendBranch(BranchLowerOrSameWord, wideGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD7);
        Append(code, 0x0000);
        Append(code, 0x1F3F); // reject below 40 bytes/row * 200 rows
        AppendBranch(BranchLowerOrSameWord, wideGeneratedEligibilityBranches);
        Append(code, MoveQuickTwoD6);
        Append(code, BranchAlwaysWord);
        var wideGeneratedModeJumpExtensionOffset = code.Count;
        Append(code, 0);

        var palWideGeneratedModeOffset = code.Count;
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenWidth));
        Append(code, CompareImmediateWordD6);
        Append(code, 320);
        AppendBranch(BranchNotEqualWord, palWideGeneratedEligibilityBranches);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenHeight));
        Append(code, CompareImmediateWordD6);
        Append(code, 256);
        AppendBranch(BranchNotEqualWord, palWideGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x002F);
        AppendBranch(BranchLowerOrSameWord, palWideGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD7);
        Append(code, 0x0000);
        Append(code, 0x27FF); // reject below 40 bytes/row * 256 rows
        AppendBranch(BranchLowerOrSameWord, palWideGeneratedEligibilityBranches);
        Append(code, MoveQuickFourD6);
        Append(code, BranchAlwaysWord);
        var palWideGeneratedModeJumpExtensionOffset = code.Count;
        Append(code, 0);

        var palLoresLaceGeneratedModeOffset = code.Count;
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenWidth));
        Append(code, CompareImmediateWordD6);
        Append(code, 320);
        AppendBranch(BranchNotEqualWord, palLoresLaceGeneratedEligibilityBranches);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenHeight));
        Append(code, CompareImmediateWordD6);
        Append(code, 512);
        AppendBranch(BranchNotEqualWord, palLoresLaceGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x002F);
        AppendBranch(BranchLowerOrSameWord, palLoresLaceGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD7);
        Append(code, 0x0000);
        Append(code, 0x4FFF); // reject below 40 bytes/row * 512 rows
        AppendBranch(BranchLowerOrSameWord, palLoresLaceGeneratedEligibilityBranches);
        Append(code, MoveQuickSixD6);
        Append(code, BranchAlwaysWord);
        var palLoresLaceGeneratedModeJumpExtensionOffset = code.Count;
        Append(code, 0);

        var ntscLoresLaceGeneratedModeOffset = code.Count;
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenWidth));
        Append(code, CompareImmediateWordD6);
        Append(code, 320);
        AppendBranch(BranchNotEqualWord, ntscLoresLaceGeneratedEligibilityBranches);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenHeight));
        Append(code, CompareImmediateWordD6);
        Append(code, 400);
        AppendBranch(BranchNotEqualWord, ntscLoresLaceGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x002F);
        AppendBranch(BranchLowerOrSameWord, ntscLoresLaceGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD7);
        Append(code, 0x0000);
        Append(code, 0x3E7F); // reject below 40 bytes/row * 400 rows
        AppendBranch(BranchLowerOrSameWord, ntscLoresLaceGeneratedEligibilityBranches);
        Append(code, MoveQuickSevenD6);
        Append(code, BranchAlwaysWord);
        var ntscLoresLaceGeneratedModeJumpExtensionOffset = code.Count;
        Append(code, 0);

        var hiresGeneratedModeOffset = code.Count;
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenWidth));
        Append(code, CompareImmediateWordD6);
        Append(code, 640);
        AppendBranch(BranchNotEqualWord, hiresGeneratedEligibilityBranches);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenHeight));
        Append(code, CompareImmediateWordD6);
        Append(code, 200);
        AppendBranch(BranchNotEqualWord, hiresGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x002F);
        AppendBranch(BranchLowerOrSameWord, hiresGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD7);
        Append(code, 0x0000);
        Append(code, 0x3E7F); // reject below 80 bytes/row * 200 rows
        AppendBranch(BranchLowerOrSameWord, hiresGeneratedEligibilityBranches);
        Append(code, MoveQuickThreeD6);
        Append(code, BranchAlwaysWord);
        var hiresGeneratedModeJumpExtensionOffset = code.Count;
        Append(code, 0);

        var palHiresGeneratedModeOffset = code.Count;
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenWidth));
        Append(code, CompareImmediateWordD6);
        Append(code, 640);
        AppendBranch(BranchNotEqualWord, palHiresGeneratedEligibilityBranches);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenHeight));
        Append(code, CompareImmediateWordD6);
        Append(code, 256);
        AppendBranch(BranchNotEqualWord, palHiresGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x002F);
        AppendBranch(BranchLowerOrSameWord, palHiresGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD7);
        Append(code, 0x0000);
        Append(code, 0x4FFF); // reject below 80 bytes/row * 256 rows
        AppendBranch(BranchLowerOrSameWord, palHiresGeneratedEligibilityBranches);
        Append(code, MoveQuickFiveD6);
        Append(code, BranchAlwaysWord);
        var palHiresGeneratedModeJumpExtensionOffset = code.Count;
        Append(code, 0);

        var palHiresLaceGeneratedModeOffset = code.Count;
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenWidth));
        Append(code, CompareImmediateWordD6);
        Append(code, 640);
        AppendBranch(BranchNotEqualWord, palHiresLaceGeneratedEligibilityBranches);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenHeight));
        Append(code, CompareImmediateWordD6);
        Append(code, 512);
        AppendBranch(BranchNotEqualWord, palHiresLaceGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x002F);
        AppendBranch(BranchLowerOrSameWord, palHiresLaceGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD7);
        Append(code, 0x0000);
        Append(code, 0x9FFF); // reject below 80 bytes/row * 512 rows
        AppendBranch(BranchLowerOrSameWord, palHiresLaceGeneratedEligibilityBranches);
        Append(code, MoveQuickEightD6);
        Append(code, BranchAlwaysWord);
        var palHiresLaceGeneratedModeJumpExtensionOffset = code.Count;
        Append(code, 0);

        var ntscHiresLaceGeneratedModeOffset = code.Count;
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenWidth));
        Append(code, CompareImmediateWordD6);
        Append(code, 640);
        AppendBranch(BranchNotEqualWord, ntscHiresLaceGeneratedEligibilityBranches);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ScreenHeight));
        Append(code, CompareImmediateWordD6);
        Append(code, 400);
        AppendBranch(BranchNotEqualWord, ntscHiresLaceGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x002F);
        AppendBranch(BranchLowerOrSameWord, ntscHiresLaceGeneratedEligibilityBranches);
        Append(code, CompareImmediateLongD7);
        Append(code, 0x0000);
        Append(code, 0x7CFF); // reject below 80 bytes/row * 400 rows
        AppendBranch(BranchLowerOrSameWord, ntscHiresLaceGeneratedEligibilityBranches);
        Append(code, MoveQuickNineD6);
        Append(code, BranchAlwaysWord);
        var ntscHiresLaceGeneratedModeJumpExtensionOffset = code.Count;
        Append(code, 0);

        var blankModeOffset = code.Count;
        Append(code, MoveQuickZeroD6);
        var modePushOffset = code.Count;
        Append(code, MoveLongD6ToPreDecrementA7);
        PatchBranch(code, generatedModeJumpExtensionOffset, modePushOffset);
        PatchBranch(code, wideGeneratedModeJumpExtensionOffset, modePushOffset);
        PatchBranch(code, hiresGeneratedModeJumpExtensionOffset, modePushOffset);
        PatchBranch(code, palHiresGeneratedModeJumpExtensionOffset, modePushOffset);
        PatchBranch(code, palHiresLaceGeneratedModeJumpExtensionOffset, modePushOffset);
        PatchBranch(code, ntscHiresLaceGeneratedModeJumpExtensionOffset, modePushOffset);
        PatchBranch(code, palLoresLaceGeneratedModeJumpExtensionOffset, modePushOffset);
        PatchBranch(code, ntscLoresLaceGeneratedModeJumpExtensionOffset, modePushOffset);
        foreach (var branch in generatedEligibilityBranches)
            PatchBranch(code, branch, wideGeneratedModeOffset);
        foreach (var branch in wideGeneratedEligibilityBranches)
            PatchBranch(code, branch, palWideGeneratedModeOffset);
        foreach (var branch in palWideGeneratedEligibilityBranches)
            PatchBranch(code, branch, palLoresLaceGeneratedModeOffset);
        foreach (var branch in palLoresLaceGeneratedEligibilityBranches)
            PatchBranch(code, branch, ntscLoresLaceGeneratedModeOffset);
        foreach (var branch in ntscLoresLaceGeneratedEligibilityBranches)
            PatchBranch(code, branch, hiresGeneratedModeOffset);
        foreach (var branch in hiresGeneratedEligibilityBranches)
            PatchBranch(code, branch, palHiresGeneratedModeOffset);
        foreach (var branch in palHiresGeneratedEligibilityBranches)
            PatchBranch(code, branch, palHiresLaceGeneratedModeOffset);
        foreach (var branch in palHiresLaceGeneratedEligibilityBranches)
            PatchBranch(code, branch, ntscHiresLaceGeneratedModeOffset);
        foreach (var branch in ntscHiresLaceGeneratedEligibilityBranches)
            PatchBranch(code, branch, blankModeOffset);
        PatchBranch(code, palWideGeneratedModeJumpExtensionOffset, modePushOffset);

        // The raw size is the bottom of the ownership frame. The four
        // prefix outputs sit above it and every display allocation is pushed
        // above those outputs, allowing one straight-line rollback per
        // failure point.
        Append(code, MoveLongD4ToPreDecrementA7);
        Append(code, MoveLongD0ToPreDecrementA7); // Screen
        Append(code, MoveLongD1ToPreDecrementA7); // View
        Append(code, MoveLongD2ToPreDecrementA7); // RasInfo
        Append(code, MoveLongD3ToPreDecrementA7); // plane

        AppendAllocMem(GraphicsLayouts.CopListSize, 0x0001_0001u, copFailureBranches);
        AppendAllocMem(GraphicsLayouts.CprListSize, 0x0001_0001u, lofFailureBranches);
        AppendAllocMem(GraphicsLayouts.CprListSize, 0x0001_0001u, shfFailureBranches);

        // D4 still carries the validated raw byte count across the descriptor
        // allocations; Exec preserves the nonvolatile data registers.
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0003); // PUBLIC | CHIP | CLEAR
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, rawFailureBranches);
        Append(code, MoveLongD0ToPreDecrementA7); // raw copper

        // Pop into the public return registers. The final raw-size pop is a
        // discard; the CopList and raw pointers are retained in A5/A4 while
        // D0/D1/D4/D7 serve as initialization scratch.
        Append(code, MoveLongA7PostIncrementToD7); // raw
        Append(code, MoveLongA7PostIncrementToD6); // SHF CprList
        Append(code, MoveLongA7PostIncrementToD5); // LOF CprList
        Append(code, MoveLongA7PostIncrementToD4); // CopList
        Append(code, MoveAddressD4ToA5);
        Append(code, MoveLongA7PostIncrementToD3); // plane
        Append(code, MoveLongA7PostIncrementToD2); // RasInfo
        Append(code, MoveLongA7PostIncrementToD1); // View
        Append(code, MoveLongA7PostIncrementToD0); // Screen
        Append(code, MoveLongA7PostIncrementToD4); // raw-size discard

        Append(code, MoveAddressD0ToA1); // Screen
        Append(code, MoveAddressD1ToA2); // View
        Append(code, MoveAddressD2ToA3); // RasInfo
        Append(code, MoveAddressD7ToA4); // raw copper

        // Derive ViewPort = View + 0x28 and link the display resources into
        // the classic View/CopList/CprList topology.
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveLongImmediateD7);
        Append(code, 0x0000);
        Append(code, checked((ushort)GraphicsLayouts.ScreenViewPort));
        Append(code, AddLongD7ToA0);
        Append(code, MoveLongA0ToD1); // viewport scratch
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToD7); // restore raw pointer after offset math

        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewLoFCprList));
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewShFCprList));

        Append(code, MoveAddressD1ToA0);
        Append(code, MoveLongA5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDspIns));

        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongD1ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListViewPort));
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopIns));
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopPtr));
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopLStart));
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCopSStart));
        Append(code, MoveImmediateWordD0);
        Append(code, 0x0002);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));

        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CprListStart));
        Append(code, MoveImmediateWordD0);
        Append(code, 0x0002);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));

        Append(code, MoveAddressD6ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CprListStart));
        Append(code, MoveImmediateWordD0);
        Append(code, 0x0002);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));

        // Tag the CopList with the Screen owner and a private marker.  The
        // paired teardown validates this identity before releasing any of
        // the eight Exec-owned blocks, so a provider/RTG CopList can never be
        // mistaken for this native bundle.
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA1ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListSystem));
        Append(code, MoveImmediateWordD0);
        Append(code, NativeDisplayResourceMarker);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListFlags));

        // A minimal canonical raw stream is enough for a later MrgCop or
        // display-program owner to extend in place: WAIT $FFFF/$FFFE.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndWait);
        Append(code, MoveWordD0ToA0);
        Append(code, MoveLongImmediateD7);
        Append(code, 0x0000);
        Append(code, 0x0002);
        Append(code, AddLongD7ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.CopperEndMask);
        Append(code, MoveWordD0ToA0);

        // If a bounded standard-planar form was selected, replace the
        // marker-only stream with the native register program. The existing
        // View/CopList/CprList links remain the same; only the raw words and
        // their published capacities/count are extended.
        Append(code, MoveLongA7PostIncrementToD4); // generated-mode flag
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var blankModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        void AppendPlanarProgram(
            ushort diwStop,
            ushort ddfStart,
            ushort ddfStop,
            ushort bplcon0)
        {
            Append(code, MoveAddressA4ToA0);
            var planarMoves = new[]
            {
                (Register: (ushort)0x008E, Value: (ushort)0x2C81),
                (Register: (ushort)0x0090, Value: diwStop),
                (Register: (ushort)0x0092, Value: ddfStart),
                (Register: (ushort)0x0094, Value: ddfStop),
                (Register: (ushort)0x0108, Value: (ushort)0x0000),
                (Register: (ushort)0x010A, Value: (ushort)0x0000),
                (Register: (ushort)0x0100, Value: bplcon0),
                (Register: (ushort)0x0102, Value: (ushort)0x0000),
                (Register: (ushort)0x0104, Value: (ushort)0x0000)
            };
            for (var index = 0; index < planarMoves.Length; index++)
            {
                var (register, value) = planarMoves[index];
                var registerOffset = index * 4;
                Append(code, MoveImmediateWordD0);
                Append(code, register);
                Append(code, MoveWordD0ToA0Displacement);
                Append(code, checked((ushort)registerOffset));
                Append(code, MoveImmediateWordD0);
                Append(code, value);
                Append(code, MoveWordD0ToA0Displacement);
                Append(code, checked((ushort)(registerOffset + 2)));
            }
            Append(code, MoveImmediateWordD0);
            Append(code, 0x00E0);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, 36);
            Append(code, MoveLongD3ToD0);
            Append(code, SwapD0);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, 38);
            Append(code, MoveImmediateWordD0);
            Append(code, 0x00E2);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, 40);
            Append(code, MoveLongD3ToD0);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, 42);
            Append(code, MoveImmediateWordD0);
            Append(code, GraphicsLayouts.CopperEndWait);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, 44);
            Append(code, MoveImmediateWordD0);
            Append(code, GraphicsLayouts.CopperEndMask);
            Append(code, MoveWordD0ToA0Displacement);
            Append(code, 46);
        }

        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0006);
        Append(code, BranchEqualWord);
        var palLoresLaceModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0007);
        Append(code, BranchEqualWord);
        var ntscLoresLaceModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0008);
        Append(code, BranchEqualWord);
        var palHiresLaceModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0009);
        Append(code, BranchNotEqualWord);
        var ntscHiresLaceModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        var palLoresLaceModesWriteOffset = code.Count;
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsModeIds.InterlaceMode);
        Append(code, MoveAddressD1ToA0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0008);
        Append(code, BranchEqualWord);
        var palHiresLaceModesRewriteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0009);
        Append(code, BranchNotEqualWord);
        var ntscHiresLaceModesRewriteBranchExtensionOffset = code.Count;
        Append(code, 0);
        var palHiresLaceModesRewriteOffset = code.Count;
        Append(code, MoveImmediateWordD0);
        Append(code, (ushort)(GraphicsModeIds.HiresMode | GraphicsModeIds.InterlaceMode));
        Append(code, MoveAddressD1ToA0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        var palLoresLaceModesJoinOffset = code.Count;

        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0003);
        Append(code, BranchEqualWord);
        var hiresProgramBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0005);
        Append(code, BranchEqualWord);
        var palHiresProgramBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0002);
        Append(code, BranchEqualWord);
        var wideProgramBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0004);
        Append(code, BranchEqualWord);
        var palWideProgramBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0006);
        Append(code, BranchEqualWord);
        var palLoresLaceProgramBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0007);
        Append(code, BranchEqualWord);
        var ntscLoresLaceProgramBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0008);
        Append(code, BranchEqualWord);
        var palHiresLaceProgramBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0009);
        Append(code, BranchEqualWord);
        var ntscHiresLaceProgramBranchExtensionOffset = code.Count;
        Append(code, 0);
        AppendPlanarProgram(0x2D00, 0x0038, 0x0038, 0x1000);
        Append(code, BranchAlwaysWord);
        var generatedProgramJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        var wideProgramOffset = code.Count;
        AppendPlanarProgram(0xF4C1, 0x0038, 0x00D0, 0x1000);
        Append(code, BranchAlwaysWord);
        var hiresProgramJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        var hiresProgramOffset = code.Count;
        AppendPlanarProgram(0xF4C1, 0x003C, 0x00D4, 0x9000);
        Append(code, BranchAlwaysWord);
        var hiresProgramJoinToLaceBranchExtensionOffset = code.Count;
        Append(code, 0);
        var palLoresLaceProgramOffset = code.Count;
        AppendPlanarProgram(0xF4C1, 0x0038, 0x00D0, 0x1004);
        Append(code, BranchAlwaysWord);
        var loresLaceProgramJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        var palHiresLaceProgramOffset = code.Count;
        AppendPlanarProgram(0xF4C1, 0x003C, 0x00D4, 0x9004);
        var generatedProgramJoinOffset = code.Count;
        var ntscHiresLaceProgramOffset = palHiresLaceProgramOffset;
        PatchBranch(code, palLoresLaceModesBranchExtensionOffset, palLoresLaceModesWriteOffset);
        PatchBranch(code, ntscLoresLaceModesBranchExtensionOffset, palLoresLaceModesWriteOffset);
        PatchBranch(code, palHiresLaceModesBranchExtensionOffset, palLoresLaceModesWriteOffset);
        PatchBranch(code, palHiresLaceModesRewriteBranchExtensionOffset, palHiresLaceModesRewriteOffset);
        PatchBranch(code, ntscHiresLaceModesRewriteBranchExtensionOffset, palLoresLaceModesJoinOffset);
        PatchBranch(code, ntscHiresLaceModesBranchExtensionOffset, palLoresLaceModesJoinOffset);
        PatchBranch(code, wideProgramBranchExtensionOffset, wideProgramOffset);
        PatchBranch(code, palWideProgramBranchExtensionOffset, wideProgramOffset);
        PatchBranch(code, hiresProgramBranchExtensionOffset, hiresProgramOffset);
        PatchBranch(code, palHiresProgramBranchExtensionOffset, hiresProgramOffset);
        PatchBranch(code, palLoresLaceProgramBranchExtensionOffset, palLoresLaceProgramOffset);
        PatchBranch(code, ntscLoresLaceProgramBranchExtensionOffset, palLoresLaceProgramOffset);
        PatchBranch(code, palHiresLaceProgramBranchExtensionOffset, palHiresLaceProgramOffset);
        PatchBranch(code, ntscHiresLaceProgramBranchExtensionOffset, ntscHiresLaceProgramOffset);
        PatchBranch(code, loresLaceProgramJoinBranchExtensionOffset, generatedProgramJoinOffset);
        PatchBranch(code, hiresProgramJoinToLaceBranchExtensionOffset, generatedProgramJoinOffset);
        PatchBranch(code, generatedProgramJoinBranchExtensionOffset, generatedProgramJoinOffset);
        PatchBranch(code, hiresProgramJoinBranchExtensionOffset, generatedProgramJoinOffset);

        Append(code, MoveImmediateWordD0);
        Append(code, 12);
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CprListMaxCount));
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListCount));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.CopListMaxCount));

        var restoreResultsOffset = code.Count;
        PatchBranch(code, blankModeBranchExtensionOffset, restoreResultsOffset);

        // Restore the eight public results. D2/D3 and D5/D6 were never used
        // as scratch after the ownership frame was popped.
        Append(code, MoveLongA1ToD0); // Screen
        Append(code, MoveLongA2ToD1); // View
        Append(code, MoveLongA5ToD4); // CopList
        Append(code, MoveLongA4ToD0);
        Append(code, MoveLongD0ToD7); // raw copper
        Append(code, MoveLongA1ToD0); // restore Screen after raw copy
        Append(code, ReturnFromSubroutine);

        var rawFailureOffset = code.Count;
        AppendFreeMemFromStack(GraphicsLayouts.CprListSize); // SHF
        AppendFreeMemFromStack(GraphicsLayouts.CprListSize); // LOF
        AppendFreeMemFromStack(GraphicsLayouts.CopListSize);
        Append(code, MoveLongA7PostIncrementToD0); // plane
        Append(code, MoveLongD7ToD1);              // plane bytes
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeMemFromStack(GraphicsLayouts.RasInfoSize);
        AppendFreeMemFromStack(GraphicsLayouts.ViewSize);
        AppendFreeMemFromStack(GraphicsLayouts.ScreenSize);
        Append(code, MoveLongA7PostIncrementToD7); // raw-size discard
        Append(code, MoveLongA7PostIncrementToD4); // generated-mode discard
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var shfFailureOffset = code.Count;
        AppendFreeMemFromStack(GraphicsLayouts.CprListSize); // LOF
        AppendFreeMemFromStack(GraphicsLayouts.CopListSize);
        Append(code, MoveLongA7PostIncrementToD0); // plane
        Append(code, MoveLongD7ToD1);              // plane bytes
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeMemFromStack(GraphicsLayouts.RasInfoSize);
        AppendFreeMemFromStack(GraphicsLayouts.ViewSize);
        AppendFreeMemFromStack(GraphicsLayouts.ScreenSize);
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var lofFailureOffset = code.Count;
        AppendFreeMemFromStack(GraphicsLayouts.CopListSize);
        Append(code, MoveLongA7PostIncrementToD0); // plane
        Append(code, MoveLongD7ToD1);              // plane bytes
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeMemFromStack(GraphicsLayouts.RasInfoSize);
        AppendFreeMemFromStack(GraphicsLayouts.ViewSize);
        AppendFreeMemFromStack(GraphicsLayouts.ScreenSize);
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var copFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // plane
        Append(code, MoveLongD7ToD1);              // plane bytes
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeMemFromStack(GraphicsLayouts.RasInfoSize);
        AppendFreeMemFromStack(GraphicsLayouts.ViewSize);
        AppendFreeMemFromStack(GraphicsLayouts.ScreenSize);
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var prefixFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD4); // raw-size discard
        Append(code, MoveLongA7PostIncrementToD7); // plane-size discard
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var rawSizeFailureOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        foreach (var branch in rawSizeBranches)
            PatchBranch(code, branch, rawSizeFailureOffset);
        foreach (var branch in prefixFailureBranches)
            PatchBranch(code, branch, prefixFailureOffset);
        foreach (var branch in copFailureBranches)
            PatchBranch(code, branch, copFailureOffset);
        foreach (var branch in lofFailureBranches)
            PatchBranch(code, branch, lofFailureOffset);
        foreach (var branch in shfFailureBranches)
            PatchBranch(code, branch, shfFailureOffset);
        foreach (var branch in rawFailureBranches)
            PatchBranch(code, branch, rawFailureOffset);

        return offset;
    }

    /// <summary>
    /// Emits a bounded native depth-two Screen-prefix allocator. The body
    /// reuses the one-plane allocator for the classic envelopes and first
    /// chip plane, then acquires a caller-visible plane table and second chip
    /// plane before publishing both links transactionally. ABI: A6=ExecBase,
    /// D0/D1=width/height, D2=bytes per plane, D3=depth (exactly two);
    /// success returns Screen, View, RasInfo, table, plane zero, and plane
    /// one in D0..D5.
    /// </summary>
    private static int AppendAllocateScreenPrefixMultiPlaneExec(
        List<byte> code,
        int onePlaneAllocatorOffset,
        int publisherOffset)
    {
        var offset = code.Count;
        var validationBranches = new List<int>(1);
        var prefixFailureBranches = new List<int>(1);
        var tableFailureBranches = new List<int>(1);
        var planeFailureBranches = new List<int>(1);
        var publishFailureBranches = new List<int>(1);

        void AppendBranch(ushort opcode, List<int> branches)
        {
            Append(code, opcode);
            branches.Add(code.Count);
            Append(code, 0);
        }

        void AppendAllocMem(int byteCount, uint flags, List<int> failureBranches)
        {
            Append(code, MoveLongImmediateD0);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)(flags >> 16));
            Append(code, (ushort)flags);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
            Append(code, TestLongD0);
            AppendBranch(BranchEqualWord, failureBranches);
            Append(code, MoveLongD0ToPreDecrementA7);
        }

        void AppendFreeMemFromStack(int byteCount)
        {
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            AppendExecFreeMemFromD0D1PreservingA1(code);
        }

        // Keep the first unit deliberately narrow.  The depth-sized table
        // and rollback frame are already independent; later units can extend
        // this exact ABI to depths three through eight without changing the
        // one-plane or public vector contracts.
        Append(code, CompareImmediateLongD3);
        Append(code, 0x0000);
        Append(code, 0x0002);
        AppendBranch(BranchNotEqualWord, validationBranches);

        // The one-plane allocator owns and validates Screen/View/RasInfo and
        // plane zero.  Save the two dynamic inputs across that private call.
        Append(code, MoveLongD3ToPreDecrementA7); // depth
        Append(code, MoveLongD2ToPreDecrementA7); // bytes per plane
        AppendJsrPcRelative(code, onePlaneAllocatorOffset);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, prefixFailureBranches);
        Append(code, MoveLongA7PostIncrementToD7); // bytes per plane
        Append(code, MoveLongA7PostIncrementToD6); // depth

        // Preserve the four one-plane envelopes while the table and second
        // plane are acquired.  The stack is [Screen, View, RasInfo, Plane0].
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongD2ToPreDecrementA7);
        Append(code, MoveLongD3ToPreDecrementA7);

        AppendAllocMem(8, 0x0001_0001u, tableFailureBranches); // public table

        // Plane one uses the caller-requested byte count and therefore keeps
        // the size in D7 rather than materializing a fixed immediate.
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0003); // PUBLIC | CHIP | CLEAR
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, planeFailureBranches);
        Append(code, MoveLongD0ToPreDecrementA7);

        // Pop the acquired pointers into a stable register ABI.  Build the
        // rollback frame before using D0/D1 as scratch for table publication;
        // the dynamic size is duplicated at its top so a failed publisher
        // can still free both chip planes.
        Append(code, MoveLongA7PostIncrementToD5); // plane one
        Append(code, MoveLongA7PostIncrementToD4); // plane table
        Append(code, MoveLongA7PostIncrementToD3); // plane zero
        Append(code, MoveLongA7PostIncrementToD2); // RasInfo
        Append(code, MoveLongA7PostIncrementToD1); // View
        Append(code, MoveLongA7PostIncrementToD0); // Screen
        Append(code, MoveLongD0ToD6); // retain Screen while D0 fills table
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongD2ToPreDecrementA7);
        Append(code, MoveLongD4ToPreDecrementA7);
        Append(code, MoveLongD3ToPreDecrementA7);
        Append(code, MoveLongD5ToPreDecrementA7);
        Append(code, MoveLongD7ToPreDecrementA7); // bytes per plane

        // Fill the eight-byte table only after both plane allocations exist.
        // The publisher then preflights the table and embedded Screen before
        // changing any public link.
        Append(code, MoveLongD4ToD0);
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveLongD3ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveAddressD0ToA0); // Screen
        Append(code, MoveLongD4ToD0);
        Append(code, MoveAddressD0ToA1); // table
        Append(code, MoveQuickTwoD0); // depth
        AppendJsrPcRelative(code, publisherOffset);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, publishFailureBranches);

        // Success: consume the rollback frame and return the complete owned
        // topology in D0..D5.  ExecBase remains in A6 throughout publisher.
        Append(code, MoveLongA7PostIncrementToD7); // size discard
        Append(code, MoveLongA7PostIncrementToD5); // plane one
        Append(code, MoveLongA7PostIncrementToD4); // plane zero
        Append(code, MoveLongA7PostIncrementToD3); // table
        Append(code, MoveLongA7PostIncrementToD2); // RasInfo
        Append(code, MoveLongA7PostIncrementToD1); // View
        Append(code, MoveLongA7PostIncrementToD0); // Screen
        Append(code, ReturnFromSubroutine);

        var publishFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD7); // bytes per plane
        Append(code, MoveLongA7PostIncrementToD0); // plane one
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeMemFromStack(8); // table
        AppendFreeMemFromStack(GraphicsLayouts.RasInfoSize);
        AppendFreeMemFromStack(GraphicsLayouts.ViewSize);
        AppendFreeMemFromStack(GraphicsLayouts.ScreenSize);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var planeFailureOffset = code.Count;
        AppendFreeMemFromStack(8); // table
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeMemFromStack(GraphicsLayouts.RasInfoSize);
        AppendFreeMemFromStack(GraphicsLayouts.ViewSize);
        AppendFreeMemFromStack(GraphicsLayouts.ScreenSize);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var tableFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // plane zero
        Append(code, MoveLongD7ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeMemFromStack(GraphicsLayouts.RasInfoSize);
        AppendFreeMemFromStack(GraphicsLayouts.ViewSize);
        AppendFreeMemFromStack(GraphicsLayouts.ScreenSize);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var prefixFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0); // bytes discard
        Append(code, MoveLongA7PostIncrementToD0); // depth discard
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var validationFailureOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        foreach (var branch in publishFailureBranches)
            PatchBranch(code, branch, publishFailureOffset);
        foreach (var branch in planeFailureBranches)
            PatchBranch(code, branch, planeFailureOffset);
        foreach (var branch in tableFailureBranches)
            PatchBranch(code, branch, tableFailureOffset);
        foreach (var branch in prefixFailureBranches)
            PatchBranch(code, branch, prefixFailureOffset);
        foreach (var branch in validationBranches)
            PatchBranch(code, branch, validationFailureOffset);

        return offset;
    }

    /// <summary>
    /// Emits a private native one-plane Screen-prefix allocator. The body
    /// keeps ExecBase in A6 for the four AllocMem calls, saves all ownership
    /// pointers on the caller stack, composes the preallocated constructor,
    /// and frees every acquired envelope if either allocation or construction
    /// declines. ABI: A6=ExecBase, D0/D1=width/height, D2=plane bytes;
    /// success returns Screen/View/RasInfo/plane in D0..D3.
    /// </summary>
    private static int AppendAllocateScreenPrefixExec(
        List<byte> code,
        int constructorOffset)
    {
        var offset = code.Count;
        var screenFailureBranches = new List<int>(1);
        var viewFailureBranches = new List<int>(1);
        var rasInfoFailureBranches = new List<int>(1);
        var planeFailureBranches = new List<int>(1);

        void AppendBranch(ushort opcode, List<int> branches)
        {
            Append(code, opcode);
            branches.Add(code.Count);
            Append(code, 0);
        }

        void AppendAllocMem(int byteCount, uint flags)
        {
            Append(code, MoveLongImmediateD0);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)(flags >> 16));
            Append(code, (ushort)flags);
            AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        }

        void AppendFreeMemFromStack(int byteCount)
        {
            Append(code, MoveLongA7PostIncrementToD0);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            AppendExecFreeMemFromD0D1PreservingA1(code);
        }

        void AppendFreeMemFromAddress(ushort addressToA0, int byteCount)
        {
            Append(code, addressToA0);
            Append(code, MoveLongA0ToD0);
            Append(code, MoveLongImmediateD1);
            Append(code, (ushort)((uint)byteCount >> 16));
            Append(code, (ushort)byteCount);
            AppendExecFreeMemFromD0D1PreservingA1(code);
        }

        // Keep the Exec base below every ownership frame.  D4..D6 are
        // Exec's preserved data registers and carry the requested sizes
        // across each AllocMem call and the composed constructor.
        Append(code, MoveLongD0ToD5);
        Append(code, MoveLongD1ToD6);
        Append(code, MoveLongD2ToD4);
        Append(code, MoveLongA6ToD0);
        Append(code, MoveLongD0ToPreDecrementA7);

        AppendAllocMem(GraphicsLayouts.ScreenSize, 0x0001_0001u); // PUBLIC | CLEAR
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, screenFailureBranches);
        Append(code, MoveLongD0ToPreDecrementA7);

        AppendAllocMem(GraphicsLayouts.ViewSize, 0x0001_0001u);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, viewFailureBranches);
        Append(code, MoveLongD0ToPreDecrementA7);

        AppendAllocMem(GraphicsLayouts.RasInfoSize, 0x0001_0001u); // PUBLIC | CLEAR
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, rasInfoFailureBranches);
        Append(code, MoveLongD0ToPreDecrementA7);

        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, 0x0001);
        Append(code, 0x0003); // PUBLIC | CHIP | CLEAR
        AppendJsrA6Displacement(code, ExecAllocMemDisplacement);
        Append(code, TestLongD0);
        AppendBranch(BranchEqualWord, planeFailureBranches);
        Append(code, MoveLongD0ToPreDecrementA7);

        // Convert the four allocation-stack entries to constructor inputs,
        // leaving ExecBase as the only item below the later cleanup frame.
        Append(code, MoveLongA7PostIncrementToD2); // plane
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA2); // RasInfo
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA1); // View
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA0); // Screen

        // Cleanup frame: size, plane, RasInfo, View, Screen, ExecBase.
        Append(code, MoveLongA0ToD1);
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongA1ToD1);
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongA2ToD1);
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongD2ToPreDecrementA7);
        Append(code, MoveLongD4ToPreDecrementA7);

        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD6ToD1);
        AppendJsrPcRelative(code, constructorOffset);
        Append(code, TestLongD0);
        var constructorFailureBranch = code.Count;
        Append(code, BranchEqualWord);
        var constructorFailureExtension = code.Count;
        Append(code, 0);

        // Success: consume the cleanup frame and restore the Exec base.
        Append(code, MoveLongA7PostIncrementToD7); // plane byte count
        Append(code, MoveLongA7PostIncrementToD3); // plane
        Append(code, MoveLongA7PostIncrementToD2); // RasInfo
        Append(code, MoveLongA7PostIncrementToD1); // View
        Append(code, MoveLongA7PostIncrementToD0); // Screen
        Append(code, MoveLongA7PostIncrementToD7); // ExecBase
        Append(code, MoveAddressD7ToA6);
        Append(code, ReturnFromSubroutine);

        var constructorFailureOffset = code.Count;
        // Constructor has changed A6 to Screen. Recover all pointers and the
        // Exec base before issuing the FreeMem calls.
        Append(code, MoveLongA7PostIncrementToD4); // plane byte count
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA3); // plane
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA2); // RasInfo
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA1); // View
        Append(code, MoveLongA6ToD3); // Screen
        Append(code, MoveLongA7PostIncrementToD0); // discard Screen copy
        Append(code, MoveLongA7PostIncrementToD7); // ExecBase
        Append(code, MoveAddressD7ToA6);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0ToD0);
        Append(code, MoveLongD4ToD1);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        AppendFreeMemFromAddress(MoveAddressA2ToA0, GraphicsLayouts.RasInfoSize);
        AppendFreeMemFromAddress(MoveAddressA1ToA0, GraphicsLayouts.ViewSize);
        Append(code, MoveLongD3ToD0);
        Append(code, MoveLongImmediateD1);
        Append(code, (ushort)(GraphicsLayouts.ScreenSize >> 16));
        Append(code, (ushort)GraphicsLayouts.ScreenSize);
        AppendExecFreeMemFromD0D1PreservingA1(code);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var planeFailureOffset = code.Count;
        AppendFreeMemFromStack(GraphicsLayouts.RasInfoSize);
        AppendFreeMemFromStack(GraphicsLayouts.ViewSize);
        AppendFreeMemFromStack(GraphicsLayouts.ScreenSize);
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveAddressD7ToA6);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var rasInfoFailureOffset = code.Count;
        AppendFreeMemFromStack(GraphicsLayouts.ViewSize);
        AppendFreeMemFromStack(GraphicsLayouts.ScreenSize);
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveAddressD7ToA6);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var viewFailureOffset = code.Count;
        AppendFreeMemFromStack(GraphicsLayouts.ScreenSize);
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveAddressD7ToA6);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var screenFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveAddressD7ToA6);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        PatchBranch(code, constructorFailureExtension, constructorFailureOffset);
        foreach (var branch in screenFailureBranches)
            PatchBranch(code, branch, screenFailureOffset);
        foreach (var branch in viewFailureBranches)
            PatchBranch(code, branch, viewFailureOffset);
        foreach (var branch in rasInfoFailureBranches)
            PatchBranch(code, branch, rasInfoFailureOffset);
        foreach (var branch in planeFailureBranches)
            PatchBranch(code, branch, planeFailureOffset);

        return offset;
    }

    /// <summary>
    /// Emits the private native constructor for a preallocated classic
    /// Intuition Screen prefix. ABI: A0=Screen, A1=View, A2=RasInfo,
    /// D0=width, D1=height, D2=plane0. The Screen's embedded ViewPort,
    /// RastPort, and BitMap are addressed at their public Kickstart offsets;
    /// no Exec allocation or provider surface is claimed here.
    /// </summary>
    private static int AppendInitScreenPrefix(List<byte> code)
    {
        var offset = code.Count;
        var failureBranches = new List<int>(24);

        void BranchToFailure(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            failureBranches.Add(extensionOffset);
        }

        void CheckAddress(ushort selectAddress, uint maximumAddress)
        {
            Append(code, selectAddress);
            Append(code, MoveLongA0ToD7);
            Append(code, TestLongD7);
            BranchToFailure(BranchEqualWord);
            Append(code, BitTestImmediateD7);
            Append(code, 0);
            BranchToFailure(BranchNotEqualWord);
            Append(code, CompareImmediateLongD7);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            BranchToFailure(BranchHighWord);
        }

        void CheckUnsignedDimension(ushort preservedRegister)
        {
            Append(code, preservedRegister);
            Append(code, TestLongD0);
            BranchToFailure(BranchEqualWord);
            Append(code, CompareImmediateLongD0);
            Append(code, 0x0000);
            Append(code, 0xFFFF);
            BranchToFailure(BranchHighWord);
        }

        // Keep the Screen base in A6 while A0 becomes the scratch register
        // used by the guarded envelope checks. Preserve geometry and plane in
        // D5/D6/D3 so the clears cannot alter the public ABI values.
        Append(code, MoveAddressA0ToA6);
        Append(code, MoveLongD0ToD5);
        Append(code, MoveLongD1ToD6);
        Append(code, MoveLongD2ToD3);

        CheckAddress(MoveAddressA6ToA0, 0xFFFF_FEA6u); // ScreenSize 0x15A
        CheckAddress(MoveAddressA1ToA0, 0xFFFF_FFEEu); // ViewSize
        CheckAddress(MoveAddressA2ToA0, 0xFFFF_FFF4u); // RasInfoSize
        CheckUnsignedDimension(MoveLongD5ToD0);
        CheckUnsignedDimension(MoveLongD6ToD0);
        Append(code, TestLongD3);
        BranchToFailure(BranchEqualWord);
        Append(code, BitTestImmediateD3);
        Append(code, 0);
        BranchToFailure(BranchNotEqualWord);

        // Treat the embedded Screen envelope, external View/RasInfo records,
        // and caller-owned plane storage as one transactional address space.
        // No public field is cleared until every half-open range is proven
        // disjoint, matching the standalone native screen-resource body.
        void CheckDisjoint(
            ushort firstLoadToD0,
            ushort secondLoadToD4,
            uint firstBytes,
            uint secondBytes)
        {
            Append(code, firstLoadToD0);
            Append(code, secondLoadToD4);
            Append(code, CompareLongD4ToD0); // first - second
            Append(code, BranchCarryWord);
            var firstBeforeSecondBranchExtensionOffset = code.Count;
            Append(code, 0);

            // second <= first: reject when second + size crosses first.
            Append(code, MoveLongD4ToD1);
            Append(code, AddImmediateLongD1);
            Append(code, (ushort)(secondBytes >> 16));
            Append(code, (ushort)secondBytes);
            Append(code, BranchCarryWord);
            var secondWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareLongD1ToD0); // first - secondEnd
            Append(code, BranchCarryWord);
            var secondOverlapsFirstBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BranchAlwaysWord);
            var disjointJoinBranchExtensionOffset = code.Count;
            Append(code, 0);

            // first < second: reject when first + size crosses second.
            var firstBeforeSecondOffset = code.Count;
            Append(code, MoveLongD0ToD1);
            Append(code, AddImmediateLongD1);
            Append(code, (ushort)(firstBytes >> 16));
            Append(code, (ushort)firstBytes);
            Append(code, BranchCarryWord);
            var firstWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareLongD4ToD1); // firstEnd - second
            Append(code, BranchHighWord);
            var firstOverlapsSecondBranchExtensionOffset = code.Count;
            Append(code, 0);

            var disjointJoinOffset = code.Count;
            PatchBranch(
                code,
                firstBeforeSecondBranchExtensionOffset,
                firstBeforeSecondOffset);
            PatchBranch(code, disjointJoinBranchExtensionOffset, disjointJoinOffset);
            failureBranches.Add(secondWrapBranchExtensionOffset);
            failureBranches.Add(secondOverlapsFirstBranchExtensionOffset);
            failureBranches.Add(firstWrapBranchExtensionOffset);
            failureBranches.Add(firstOverlapsSecondBranchExtensionOffset);
        }

        void CheckPlaneAgainst(ushort envelopeLoadToD0, uint envelopeBytes)
        {
            // D2 is the plane base and D7 is the exclusive plane end. The
            // ranges may touch, but they may not share a byte.
            Append(code, envelopeLoadToD0);
            Append(code, CompareLongD0ToD2); // plane - envelope
            Append(code, BranchLowerOrSameWord);
            var planeBeforeEnvelopeBranchExtensionOffset = code.Count;
            Append(code, 0);

            // envelope <= plane: require envelopeEnd <= plane.
            var envelopeBeforePlaneOffset = code.Count;
            Append(code, MoveLongD0ToD1);
            Append(code, AddImmediateLongD1);
            Append(code, (ushort)(envelopeBytes >> 16));
            Append(code, (ushort)envelopeBytes);
            Append(code, BranchCarryWord);
            var envelopeWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveLongD1ToD0);
            Append(code, CompareLongD0ToD2); // plane - envelopeEnd
            Append(code, BranchCarryWord);
            var envelopeOverlapsPlaneBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BranchAlwaysWord);
            var planeDisjointJoinBranchExtensionOffset = code.Count;
            Append(code, 0);

            // plane < envelope: require planeEnd <= envelope.
            var planeBeforeEnvelopeOffset = code.Count;
            Append(code, MoveLongD7ToD1);
            Append(code, CompareLongD1ToD0); // envelope - planeEnd
            Append(code, BranchCarryWord);
            var planeOverlapsEnvelopeBranchExtensionOffset = code.Count;
            Append(code, 0);

            var planeDisjointJoinOffset = code.Count;
            PatchBranch(
                code,
                planeBeforeEnvelopeBranchExtensionOffset,
                envelopeBeforePlaneOffset);
            PatchBranch(
                code,
                planeDisjointJoinBranchExtensionOffset,
                planeDisjointJoinOffset);
            failureBranches.Add(envelopeWrapBranchExtensionOffset);
            failureBranches.Add(envelopeOverlapsPlaneBranchExtensionOffset);
            failureBranches.Add(planeOverlapsEnvelopeBranchExtensionOffset);
        }

        CheckDisjoint(MoveLongA6ToD0, MoveLongA1ToD4,
            (uint)GraphicsLayouts.ScreenSize, (uint)GraphicsLayouts.ViewSize);
        CheckDisjoint(MoveLongA6ToD0, MoveLongA2ToD4,
            (uint)GraphicsLayouts.ScreenSize, (uint)GraphicsLayouts.RasInfoSize);
        CheckDisjoint(MoveLongA1ToD0, MoveLongA2ToD4,
            (uint)GraphicsLayouts.ViewSize, (uint)GraphicsLayouts.RasInfoSize);

        // Compute the caller-owned one-plane span from the preserved width and
        // height. Keep the original plane in D4 while D3 becomes the byte
        // count and D7 becomes the exclusive end.
        Append(code, MoveLongD3ToD4);
        Append(code, MoveLongD5ToD1);
        Append(code, AddImmediateWordD1);
        Append(code, 0x000F);
        Append(code, ShiftRightWordD1);
        Append(code, ShiftRightWordD1);
        Append(code, ShiftRightWordD1);
        Append(code, ShiftRightWordD1);
        Append(code, MoveLongD1ToD2);
        Append(code, AddLongD1ToD2);
        Append(code, MoveLongD6ToD0);
        Append(code, MultiplyUnsignedWordD2ToD3);
        Append(code, MoveLongD4ToD7);
        Append(code, AddLongD3ToD7);
        Append(code, BranchCarryWord);
        var planeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD4ToD2);
        CheckPlaneAgainst(MoveLongA6ToD0, (uint)GraphicsLayouts.ScreenSize);
        CheckPlaneAgainst(MoveLongA1ToD0, (uint)GraphicsLayouts.ViewSize);
        CheckPlaneAgainst(MoveLongA2ToD0, (uint)GraphicsLayouts.RasInfoSize);
        Append(code, MoveLongD2ToD3); // restore caller plane for publication
        failureBranches.Add(planeWrapBranchExtensionOffset);

        // Compute the embedded ViewPort and RastPort addresses before the
        // Screen clear. A6 remains the Screen base; A5/A4 retain the nested
        // addresses for the publication phase.
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveAddressA0ToA5);
        Append(code, MoveLongImmediateD0);
        Append(code, 0x0000);
        Append(code, checked((ushort)GraphicsLayouts.ScreenViewPort));
        Append(code, MoveLongD0ToD4);
        Append(code, AddLongD4ToA5);

        Append(code, MoveAddressA6ToA0);
        Append(code, MoveAddressA0ToA4);
        Append(code, MoveLongImmediateD0);
        Append(code, 0x0000);
        Append(code, checked((ushort)GraphicsLayouts.ScreenRastPort));
        Append(code, MoveLongD0ToD4);
        Append(code, AddLongD4ToA4);

        // Clear the complete Screen envelope, including its embedded public
        // structures, then restore the trailing two-byte alignment remainder.
        Append(code, MoveAddressA6ToA0);
        AppendClearLongWords(code, 0x7855); // 86 LONGs = 0x158 bytes
        Append(code, MoveWordD0ToA0);        // trailing Screen byte pair

        // View: four LONGs plus the trailing word and standard DIW origin.
        Append(code, MoveAddressA1ToA0);
        AppendClearLongWords(code, 0x7803);
        Append(code, MoveWordD0ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, 0x002C);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewDyOffset));
        Append(code, MoveImmediateWordD0);
        Append(code, 0x0081);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewDxOffset));

        // Embedded ViewPort: ten LONGs, classic sprite priority, and the
        // requested display geometry.
        Append(code, MoveAddressA5ToA0);
        AppendClearLongWords(code, 0x7809);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveImmediateWordD0);
        Append(code, GraphicsLayouts.ViewPortDefaultSpritePriorities);
        Append(code, 0x1140);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortSpritePriorities));
        Append(code, MoveLongD5ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDWidth));
        Append(code, MoveLongD6ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortDHeight));

        // External RasInfo.
        Append(code, MoveAddressA2ToA0);
        AppendClearLongWords(code, 0x7802);

        // Embedded RastPort. Keep the public no-font defaults that InitRastPort
        // guarantees; font/metric publication remains the owning Intuition
        // or font-list boundary.
        Append(code, MoveAddressA4ToA0);
        AppendClearLongWords(code,
            checked((ushort)(0x7800 | (GraphicsLayouts.RastPortSize / sizeof(uint) - 1))));
        Append(code, MoveAddressA4ToA0); // Clear advanced A0; defaults are RP-relative.
        Append(code, MoveQuickMinusOneD0);
        Append(code, 0x1140); // MOVE.B D0,(d16,A0)
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, 0x1140); // MOVE.B D0,(d16,A0)
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, 0x1140); // MOVE.B D0,(d16,A0)
        Append(code, checked((ushort)GraphicsLayouts.RastPortOutlinePen));
        Append(code, MoveQuickZeroD0);
        Append(code, 0x1140); // MOVE.B D0,(d16,A0)
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, MoveQuickOneD0);
        Append(code, 0x1140); // MOVE.B D0,(d16,A0)
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, MoveQuickMinusOneD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePattern));

        // Embedded standard-planar BitMap.
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongImmediateD0);
        Append(code, 0x0000);
        Append(code, checked((ushort)GraphicsLayouts.ScreenBitMap));
        Append(code, MoveLongD0ToD7);
        Append(code, AddLongD7ToA0);
        AppendClearLongWords(code, 0x7809);
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongImmediateD0);
        Append(code, 0x0000);
        Append(code, checked((ushort)GraphicsLayouts.ScreenBitMap));
        Append(code, MoveLongD0ToD7);
        Append(code, AddLongD7ToA0);
        Append(code, MoveLongD5ToD1);
        Append(code, AddImmediateWordD1);
        Append(code, 0x000F);
        Append(code, ShiftRightWordD1);
        Append(code, ShiftRightWordD1);
        Append(code, ShiftRightWordD1);
        Append(code, ShiftRightWordD1);
        Append(code, AddWordD1ToD1);
        Append(code, MoveWordD1ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveLongD6ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, 0x7008); // BMF_STANDARD
        Append(code, 0x1140);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, MoveQuickOneD0);
        Append(code, 0x1140); // MOVE.B D0,(d16,A0)
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, MoveLongD3ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, MoveLongA0ToA3); // retain embedded BitMap identity

        // Screen geometry and the four public links are published last.
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ScreenWidth));
        Append(code, MoveLongD6ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ScreenHeight));

        Append(code, MoveAddressA1ToA0);
        Append(code, MoveLongA5ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA2ToD6);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongA3ToD1);
        Append(code, MoveLongD1ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoBitMap));
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA3ToD1);
        Append(code, MoveLongD1ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        var failureOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        foreach (var branchExtensionOffset in failureBranches)
            PatchBranch(code, branchExtensionOffset, failureOffset);
        return offset;
    }

    /// <summary>
    /// Emits the matching private Screen-prefix teardown. ABI: A0=Screen,
    /// A1=View, A2=RasInfo, D0=plane0. Exact embedded links and plane identity
    /// are checked before any envelope is cleared; plane bytes are untouched.
    /// </summary>
    private static int AppendTeardownScreenPrefix(List<byte> code)
    {
        var offset = code.Count;
        var failureBranches = new List<int>(20);

        void BranchToFailure(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            failureBranches.Add(extensionOffset);
        }

        void CheckAddress(ushort selectAddress, uint maximumAddress)
        {
            Append(code, selectAddress);
            Append(code, MoveLongA0ToD7);
            Append(code, TestLongD7);
            BranchToFailure(BranchEqualWord);
            Append(code, BitTestImmediateD7);
            Append(code, 0);
            BranchToFailure(BranchNotEqualWord);
            Append(code, CompareImmediateLongD7);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            BranchToFailure(BranchHighWord);
        }

        Append(code, MoveAddressA0ToA6);
        Append(code, MoveLongD0ToD3); // preserve expected plane
        CheckAddress(MoveAddressA6ToA0, 0xFFFF_FEA6u); // ScreenSize
        CheckAddress(MoveAddressA1ToA0, 0xFFFF_FFEEu); // ViewSize
        CheckAddress(MoveAddressA2ToA0, 0xFFFF_FFF4u); // RasInfoSize
        Append(code, TestLongD3);
        BranchToFailure(BranchEqualWord);
        Append(code, BitTestImmediateD3);
        Append(code, 0);
        BranchToFailure(BranchNotEqualWord);

        // Derive the embedded addresses while retaining the external bases.
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveAddressA0ToA5);
        Append(code, MoveLongImmediateD0);
        Append(code, 0x0000);
        Append(code, checked((ushort)GraphicsLayouts.ScreenViewPort));
        Append(code, MoveLongD0ToD4);
        Append(code, AddLongD4ToA5);
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveAddressA0ToA4);
        Append(code, MoveLongImmediateD0);
        Append(code, 0x0000);
        Append(code, checked((ushort)GraphicsLayouts.ScreenRastPort));
        Append(code, MoveLongD0ToD5);
        Append(code, AddLongD5ToA4);
        Append(code, MoveAddressA6ToA3);
        Append(code, MoveLongImmediateD0);
        Append(code, 0x0000);
        Append(code, checked((ushort)GraphicsLayouts.ScreenBitMap));
        Append(code, MoveLongD0ToD5);
        Append(code, AddLongD5ToA3);
        Append(code, MoveLongD3ToD7); // preserve the expected plane

        // View -> embedded ViewPort.
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewViewPort));
        Append(code, MoveLongA5ToD6);
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchNotEqualWord);
        // ViewPort -> external RasInfo.
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortRasInfo));
        Append(code, MoveLongA2ToD6);
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchNotEqualWord);
        // RasInfo -> embedded BitMap.
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RasInfoBitMap));
        Append(code, MoveLongA3ToD6);
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchNotEqualWord);
        // RastPort -> embedded BitMap.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, MoveLongA3ToD6);
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchNotEqualWord);
        // BitMap -> expected caller/provider plane.
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, MoveLongD7ToD6);
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchNotEqualWord);

        Append(code, MoveAddressA6ToA0);
        AppendClearLongWords(code, 0x7855);
        Append(code, MoveWordD0ToA0);
        Append(code, MoveAddressA1ToA0);
        AppendClearLongWords(code, 0x7803);
        Append(code, MoveWordD0ToA0);
        Append(code, MoveAddressA2ToA0);
        AppendClearLongWords(code, 0x7802);
        Append(code, MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        var failureOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        foreach (var branchExtensionOffset in failureBranches)
            PatchBranch(code, branchExtensionOffset, failureOffset);
        return offset;
    }

    /// <summary>
    /// Emits the native multi-plane publisher used by a future native
    /// Screen/BitMap owner. ABI: A0=BitMap, A1=plane-pointer table,
    /// D0=depth (1..8). Every descriptor and every table entry is validated
    /// before the first BitMap.Planes[] store. The table is caller-owned and
    /// is never cleared or freed; this body publishes its pointers and the
    /// matching BitMap.Depth into the already allocated envelope. D0 returns
    /// one on success and zero on decline.
    ///
    /// The table envelope check reserves the full eight-plane span for every
    /// call (A1 at or below $FFFFFFE0), which keeps the 68000 preflight branch-free
    /// with respect to the selected depth while retaining a strict bounded
    /// read window. Host/native allocation owners can impose a tighter
    /// depth-specific envelope before entering this helper.
    /// </summary>
    private static int AppendPublishBitMapPlaneTable(List<byte> code)
    {
        var offset = code.Count;
        var failureBranches = new List<int>(18);

        void BranchToFailure(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            failureBranches.Add(extensionOffset);
        }

        void CheckDisjoint(
            ushort firstLoadToD0,
            ushort secondLoadToD4,
            uint firstBytes,
            uint secondBytes)
        {
            Append(code, firstLoadToD0);
            Append(code, secondLoadToD4);
            Append(code, CompareLongD4ToD0); // first - second
            Append(code, BranchCarryWord);
            var firstBeforeSecondBranchExtensionOffset = code.Count;
            Append(code, 0);

            Append(code, MoveLongD4ToD1);
            Append(code, AddImmediateLongD1);
            Append(code, (ushort)(secondBytes >> 16));
            Append(code, (ushort)secondBytes);
            Append(code, BranchCarryWord);
            var secondWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareLongD1ToD0); // first - secondEnd
            Append(code, BranchCarryWord);
            var secondOverlapsFirstBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BranchAlwaysWord);
            var disjointJoinBranchExtensionOffset = code.Count;
            Append(code, 0);

            var firstBeforeSecondOffset = code.Count;
            Append(code, MoveLongD0ToD1);
            Append(code, AddImmediateLongD1);
            Append(code, (ushort)(firstBytes >> 16));
            Append(code, (ushort)firstBytes);
            Append(code, BranchCarryWord);
            var firstWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareLongD4ToD1); // firstEnd - second
            Append(code, BranchHighWord);
            var firstOverlapsSecondBranchExtensionOffset = code.Count;
            Append(code, 0);

            var disjointJoinOffset = code.Count;
            PatchBranch(
                code,
                firstBeforeSecondBranchExtensionOffset,
                firstBeforeSecondOffset);
            PatchBranch(code, disjointJoinBranchExtensionOffset, disjointJoinOffset);
            failureBranches.Add(secondWrapBranchExtensionOffset);
            failureBranches.Add(secondOverlapsFirstBranchExtensionOffset);
            failureBranches.Add(firstWrapBranchExtensionOffset);
            failureBranches.Add(firstOverlapsSecondBranchExtensionOffset);
        }

        // BitMap envelope: non-null, 68000-aligned, and safe for the public
        // BitMapSize bytes accessed by the publisher.
        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        BranchToFailure(BranchEqualWord);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        BranchToFailure(BranchNotEqualWord);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        BranchToFailure(BranchHighWord);

        // Caller-owned table envelope. Reserve the complete eight-plane
        // span so all depth values share one bounded pointer check.
        Append(code, MoveLongA1ToD6);
        Append(code, TestLongD6);
        BranchToFailure(BranchEqualWord);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        BranchToFailure(BranchNotEqualWord);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFE0);
        BranchToFailure(BranchHighWord);

        // The caller-owned pointer table must not alias the descriptor that
        // receives its published links. Reject the overlap before reading any
        // pointer or writing BitMap.Planes[].
        Append(code, MoveLongD0ToD6);
        CheckDisjoint(
            MoveLongA0ToD0,
            MoveLongA1ToD4,
            (uint)GraphicsLayouts.BitMapSize,
            (uint)(sizeof(uint) * 8));

        Append(code, TestLongD6);
        BranchToFailure(BranchEqualWord);
        Append(code, CompareImmediateLongD6);
        Append(code, 0x0000);
        Append(code, 0x0008);
        BranchToFailure(BranchHighWord);

        // Preserve the descriptor bases and depth while the two passes use
        // A1/D1 and D5 as streaming scratch registers.
        Append(code, MoveAddressA0ToA2);
        Append(code, MoveAddressA1ToA3);

        Append(code, MoveLongD6ToD1);
        Append(code, SubQuickOneLongD1);
        var preflightLoopOffset = code.Count;
        Append(code, MoveLongA1PostIncrementToD5);
        Append(code, TestLongD5);
        BranchToFailure(BranchEqualWord);
        Append(code, BitTestImmediateD5);
        Append(code, 0);
        BranchToFailure(BranchNotEqualWord);
        Append(code, DecrementBranchD1);
        Append(code, unchecked((ushort)(preflightLoopOffset - code.Count)));

        // Rewind the table and point A0 at BitMap.Planes[0].
        Append(code, MoveAddressA3ToA1);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongImmediateD0);
        Append(code, 0x0000);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, MoveLongD0ToD7);
        Append(code, AddLongD7ToA0);

        Append(code, MoveLongD6ToD1);
        Append(code, SubQuickOneLongD1);
        var publishLoopOffset = code.Count;
        Append(code, MoveLongA1PostIncrementToD5);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, DecrementBranchD1);
        Append(code, unchecked((ushort)(publishLoopOffset - code.Count)));

        // Publish the matching standard-planar depth only after every plane
        // pointer has passed preflight and has been linked.  The descriptor
        // remains the caller's envelope; this keeps the header and table
        // transactionally coherent without claiming allocation ownership.
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveByteD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));

        Append(code, MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        var failureOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        foreach (var branchExtensionOffset in failureBranches)
            PatchBranch(code, branchExtensionOffset, failureOffset);

        return offset;
    }

    /// <summary>
    /// Emits the private native Screen-prefix multi-plane publisher. ABI:
    /// A0=Screen, A1=caller-owned plane-pointer table, D0=depth (1..8).
    /// The body validates the classic Screen envelope, the complete
    /// eight-entry table window, and every selected plane before publishing
    /// the links and matching depth at the embedded Screen BitMap. Screen,
    /// table, and plane storage remain caller/provider-owned; no Exec
    /// allocation or clear is inferred by this helper.
    /// </summary>
    private static int AppendPublishScreenPrefixPlaneTable(List<byte> code)
    {
        var offset = code.Count;
        var failureBranches = new List<int>(18);

        void BranchToFailure(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            failureBranches.Add(extensionOffset);
        }

        void CheckDisjoint(
            ushort firstLoadToD0,
            ushort secondLoadToD4,
            uint firstBytes,
            uint secondBytes)
        {
            Append(code, firstLoadToD0);
            Append(code, secondLoadToD4);
            Append(code, CompareLongD4ToD0); // first - second
            Append(code, BranchCarryWord);
            var firstBeforeSecondBranchExtensionOffset = code.Count;
            Append(code, 0);

            Append(code, MoveLongD4ToD1);
            Append(code, AddImmediateLongD1);
            Append(code, (ushort)(secondBytes >> 16));
            Append(code, (ushort)secondBytes);
            Append(code, BranchCarryWord);
            var secondWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareLongD1ToD0); // first - secondEnd
            Append(code, BranchCarryWord);
            var secondOverlapsFirstBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BranchAlwaysWord);
            var disjointJoinBranchExtensionOffset = code.Count;
            Append(code, 0);

            var firstBeforeSecondOffset = code.Count;
            Append(code, MoveLongD0ToD1);
            Append(code, AddImmediateLongD1);
            Append(code, (ushort)(firstBytes >> 16));
            Append(code, (ushort)firstBytes);
            Append(code, BranchCarryWord);
            var firstWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, CompareLongD4ToD1); // firstEnd - second
            Append(code, BranchHighWord);
            var firstOverlapsSecondBranchExtensionOffset = code.Count;
            Append(code, 0);

            var disjointJoinOffset = code.Count;
            PatchBranch(
                code,
                firstBeforeSecondBranchExtensionOffset,
                firstBeforeSecondOffset);
            PatchBranch(code, disjointJoinBranchExtensionOffset, disjointJoinOffset);
            failureBranches.Add(secondWrapBranchExtensionOffset);
            failureBranches.Add(secondOverlapsFirstBranchExtensionOffset);
            failureBranches.Add(firstWrapBranchExtensionOffset);
            failureBranches.Add(firstOverlapsSecondBranchExtensionOffset);
        }

        // Preserve the Screen and table bases in address registers while the
        // descriptor checks and two bounded table passes use data registers.
        Append(code, MoveAddressA0ToA2);
        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        BranchToFailure(BranchEqualWord);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        BranchToFailure(BranchNotEqualWord);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFEA6); // ScreenSize (0x15A) envelope
        BranchToFailure(BranchHighWord);

        Append(code, MoveAddressA1ToA3);
        Append(code, MoveLongA1ToD6);
        Append(code, TestLongD6);
        BranchToFailure(BranchEqualWord);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        BranchToFailure(BranchNotEqualWord);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFE0); // conservative eight-plane table span
        BranchToFailure(BranchHighWord);

        // Preserve the requested depth before the range preflight uses D0/D1
        // as address arithmetic scratch.
        Append(code, MoveLongD0ToD5);

        // The caller-owned table is a publication input, not a scratch
        // buffer. Reject any overlap with the embedded Screen envelope before
        // reading table entries or writing BitMap.Planes[].
        CheckDisjoint(
            MoveLongA0ToD0,
            MoveLongA1ToD4,
            (uint)GraphicsLayouts.ScreenSize,
            (uint)(sizeof(uint) * 8));

        Append(code, TestLongD5);
        BranchToFailure(BranchEqualWord);
        Append(code, CompareImmediateLongD5);
        Append(code, 0x0000);
        Append(code, 0x0008);
        BranchToFailure(BranchHighWord);

        // Preflight every selected pointer before the first embedded bitmap
        // store. A depth-minus-one DBRA count executes exactly depth passes.
        Append(code, MoveLongD5ToD1);
        Append(code, SubQuickOneLongD1);
        var preflightLoopOffset = code.Count;
        Append(code, MoveLongA3PostIncrementToD4);
        Append(code, TestLongD4);
        BranchToFailure(BranchEqualWord);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        BranchToFailure(BranchNotEqualWord);
        Append(code, DecrementBranchD1);
        var preflightLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Rewind the caller table and derive the embedded BitMap address
        // from Screen+ScreenBitMap before publishing all selected planes.
        Append(code, MoveAddressA1ToA3);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongImmediateD0);
        Append(code, 0x0000);
        Append(
            code,
            checked((ushort)(GraphicsLayouts.ScreenBitMap + GraphicsLayouts.BitMapPlanes)));
        Append(code, MoveLongD0ToD7);
        Append(code, AddLongD7ToA0);

        Append(code, MoveLongD5ToD1);
        Append(code, SubQuickOneLongD1);
        var publishLoopOffset = code.Count;
        Append(code, MoveLongA3PostIncrementToD4);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, DecrementBranchD1);
        var publishLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Keep the embedded BitMap header consistent with the published
        // plane count.  This write is deliberately after the complete
        // preflight/publish sequence so malformed tables leave the Screen
        // envelope untouched.
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveByteD0ToA0Displacement);
        Append(
            code,
            checked((ushort)(GraphicsLayouts.ScreenBitMap + GraphicsLayouts.BitMapDepth)));

        Append(code, MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        var failureOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, preflightLoopBranchExtensionOffset, preflightLoopOffset);
        PatchBranch(code, publishLoopBranchExtensionOffset, publishLoopOffset);
        foreach (var branchExtensionOffset in failureBranches)
            PatchBranch(code, branchExtensionOffset, failureOffset);

        return offset;
    }

    /// <summary>
    /// Composes the preallocated classic Screen-prefix constructor with the
    /// native multi-plane publisher. ABI: A0=Screen, A1=View, A2=RasInfo,
    /// A3=caller-owned plane table, D0/D1=geometry, D2=depth. The table and
    /// every selected plane are preflighted before the classic constructor is
    /// entered; no Exec allocation or provider storage is inferred.
    /// </summary>
    private static int AppendInitScreenPrefixMultiPlane(
        List<byte> code,
        int classicConstructorOffset,
        int publisherOffset)
    {
        var offset = code.Count;
        var validationBranches = new List<int>(16);

        void BranchToValidationFailure(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            validationBranches.Add(extensionOffset);
        }

        void CheckPlaneAgainst(
            ushort envelopeLoadToD4,
            uint envelopeBytes)
        {
            // D2 is the current caller plane base and D0 is its exclusive
            // end. D4/D1 are scratch envelope values. Keep this check
            // allocation-free and half-open so touching spans remain valid.
            Append(code, MoveLongD0ToD7);
            Append(code, envelopeLoadToD4);
            Append(code, CompareLongD4ToD2); // plane - envelope
            Append(code, BranchLowerOrSameWord);
            var planeBeforeEnvelopeBranchExtensionOffset = code.Count;
            Append(code, 0);

            // envelope <= plane: reject when plane starts before envelope end.
            var envelopeBeforePlaneOffset = code.Count;
            Append(code, MoveLongD4ToD1);
            Append(code, AddImmediateLongD1);
            Append(code, (ushort)(envelopeBytes >> 16));
            Append(code, (ushort)envelopeBytes);
            Append(code, BranchCarryWord);
            var envelopeWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveLongD2ToD0);
            Append(code, CompareLongD1ToD0); // plane - envelopeEnd
            Append(code, BranchCarryWord);
            var envelopeOverlapsPlaneBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BranchAlwaysWord);
            var planeDisjointJoinBranchExtensionOffset = code.Count;
            Append(code, 0);

            // plane < envelope: reject when the plane reaches into it.
            var planeBeforeEnvelopeOffset = code.Count;
            Append(code, CompareLongD0ToD4); // envelope - planeEnd
            Append(code, BranchCarryWord);
            var planeOverlapsEnvelopeBranchExtensionOffset = code.Count;
            Append(code, 0);

            var planeDisjointJoinOffset = code.Count;
            PatchBranch(
                code,
                planeBeforeEnvelopeBranchExtensionOffset,
                planeBeforeEnvelopeOffset);
            PatchBranch(
                code,
                planeDisjointJoinBranchExtensionOffset,
                planeDisjointJoinOffset);
            Append(code, MoveLongD7ToD0);
            validationBranches.Add(envelopeWrapBranchExtensionOffset);
            validationBranches.Add(envelopeOverlapsPlaneBranchExtensionOffset);
            validationBranches.Add(planeOverlapsEnvelopeBranchExtensionOffset);
        }

        Append(code, MoveLongD2ToD6);
        Append(code, MoveAddressA3ToA4);
        // Retain the original geometry while the per-plane span checks use
        // D0/D1 as arithmetic scratch. The classic constructor still owns
        // the final width/height validation before any public clear.
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveAddressD1ToA6);
        Append(code, MoveLongA3ToD2);
        Append(code, MoveLongD2ToPreDecrementA7);
        Append(code, MoveLongD6ToD2);
        Append(code, MoveLongA3ToD4);
        Append(code, TestLongD4);
        BranchToValidationFailure(BranchEqualWord);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        BranchToValidationFailure(BranchNotEqualWord);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFE0);
        BranchToValidationFailure(BranchHighWord);
        Append(code, TestLongD2);
        BranchToValidationFailure(BranchEqualWord);
        Append(code, CompareImmediateLongD2);
        Append(code, 0x0000);
        Append(code, 0x0008);
        BranchToValidationFailure(BranchHighWord);

        // The caller-owned plane table is also part of the input envelope.
        // Reject a wrapping table or one that aliases Screen/View/RasInfo
        // before the classic constructor can clear any of those structures.
        Append(code, MoveLongA3ToD2);
        Append(code, MoveLongD2ToD0);
        Append(code, MoveLongD6ToD1);
        Append(code, ShiftLeftLongD1);
        Append(code, ShiftLeftLongD1);
        Append(code, AddLongD1ToD0);
        BranchToValidationFailure(BranchCarryWord);
        CheckPlaneAgainst(MoveLongA0ToD4, (uint)GraphicsLayouts.ScreenSize);
        CheckPlaneAgainst(MoveLongA1ToD4, (uint)GraphicsLayouts.ViewSize);
        CheckPlaneAgainst(MoveLongA2ToD4, (uint)GraphicsLayouts.RasInfoSize);

        Append(code, MoveLongD6ToD7);
        Append(code, SubQuickOneLongD7);
        var preflightLoopOffset = code.Count;
        Append(code, MoveLongA3PostIncrementToD4);
        Append(code, TestLongD4);
        BranchToValidationFailure(BranchEqualWord);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        BranchToValidationFailure(BranchNotEqualWord);
        Append(code, DecrementBranchD7);
        var preflightBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A plane span is BytesPerRow * height. Restrict the native arithmetic
        // to the same bounded WORD geometry accepted by the classic
        // constructor; larger/provider-specific forms stay on the fallback.
        Append(code, MoveLongA5ToD0);
        Append(code, TestLongD0);
        BranchToValidationFailure(BranchEqualWord);
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0000);
        Append(code, 0xFFF0);
        BranchToValidationFailure(BranchHighWord);
        Append(code, MoveLongA6ToD0);
        Append(code, TestLongD0);
        BranchToValidationFailure(BranchEqualWord);
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0000);
        Append(code, 0xFFFF);
        BranchToValidationFailure(BranchHighWord);

        Append(code, MoveLongA5ToD0);
        Append(code, MoveLongD0ToD3);
        Append(code, AddImmediateWordD3);
        Append(code, 0x000F);
        Append(code, ShiftRightLongD3);
        Append(code, ShiftRightLongD3);
        Append(code, ShiftRightLongD3);
        Append(code, ShiftRightLongD3);
        Append(code, ShiftLeftLongD3);
        Append(code, MoveLongA6ToD4);
        Append(code, MultiplyUnsignedWordD4ToD3);
        Append(code, TestLongD3);
        BranchToValidationFailure(BranchEqualWord);

        // Validate every selected plane, not just the first plane passed to
        // the classic constructor. This prevents a later table entry from
        // aliasing an envelope that the constructor is about to clear.
        Append(code, MoveAddressA4ToA3);
        Append(code, MoveLongD6ToD5);
        Append(code, SubQuickOneLongD5);
        var planeSpanLoopOffset = code.Count;
        Append(code, MoveLongA3PostIncrementToD4);
        Append(code, MoveLongD4ToD2);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongD3ToD7);
        Append(code, AddLongD7ToD0);
        BranchToValidationFailure(BranchCarryWord);
        CheckPlaneAgainst(MoveLongA0ToD4, (uint)GraphicsLayouts.ScreenSize);
        CheckPlaneAgainst(MoveLongA1ToD4, (uint)GraphicsLayouts.ViewSize);
        CheckPlaneAgainst(MoveLongA2ToD4, (uint)GraphicsLayouts.RasInfoSize);
        Append(code, DecrementBranchD5);
        var planeSpanBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveLongA5ToD5);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD0ToD2);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongA6ToD1);
        Append(code, MoveLongD6ToPreDecrementA7);
        AppendJsrPcRelative(code, classicConstructorOffset);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var constructorFailureBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveAddressD7ToA1);
        Append(code, MoveAddressA6ToA0);
        AppendJsrPcRelative(code, publisherOffset);
        Append(code, ReturnFromSubroutine);

        var constructorFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var validationFailureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        PatchBranch(code, preflightBranchExtensionOffset, preflightLoopOffset);
        PatchBranch(code, planeSpanBranchExtensionOffset, planeSpanLoopOffset);
        PatchBranch(
            code,
            constructorFailureBranchExtensionOffset,
            constructorFailureOffset);
        foreach (var branchExtensionOffset in validationBranches)
            PatchBranch(code, branchExtensionOffset, validationFailureOffset);
        return offset;
    }

    /// <summary>
    /// Validates all caller-owned plane links in a Screen-prefix table before
    /// composing the exact classic teardown. ABI: A0=Screen, A1=View,
    /// A2=RasInfo, A3=plane table, D0=depth. A replaced or malformed link
    /// declines without clearing any public envelope or plane storage.
    /// </summary>
    private static int AppendTeardownScreenPrefixMultiPlane(
        List<byte> code,
        int classicTeardownOffset)
    {
        var offset = code.Count;
        var failureBranches = new List<int>(16);

        void BranchToFailure(ushort branchOpcode)
        {
            Append(code, branchOpcode);
            var extensionOffset = code.Count;
            Append(code, 0);
            failureBranches.Add(extensionOffset);
        }

        void CheckAddress(ushort selectAddress, uint maximumAddress)
        {
            Append(code, selectAddress);
            Append(code, MoveLongA0ToD6);
            Append(code, TestLongD6);
            BranchToFailure(BranchEqualWord);
            Append(code, BitTestImmediateD6);
            Append(code, 0);
            BranchToFailure(BranchNotEqualWord);
            Append(code, CompareImmediateLongD6);
            Append(code, (ushort)(maximumAddress >> 16));
            Append(code, (ushort)maximumAddress);
            BranchToFailure(BranchHighWord);
        }

        void CheckTableAgainst(ushort envelopeLoadToD4, uint envelopeBytes)
        {
            // D2 is the caller table base and D0 is its exclusive end. Keep
            // the check half-open so touching spans remain valid while any
            // actual alias fails before the classic teardown clears data.
            Append(code, MoveLongD0ToD7);
            Append(code, envelopeLoadToD4);
            Append(code, CompareLongD4ToD2); // table - envelope
            Append(code, BranchLowerOrSameWord);
            var tableBeforeEnvelopeBranchExtensionOffset = code.Count;
            Append(code, 0);

            var envelopeBeforeTableOffset = code.Count;
            Append(code, MoveLongD4ToD1);
            Append(code, AddImmediateLongD1);
            Append(code, (ushort)(envelopeBytes >> 16));
            Append(code, (ushort)envelopeBytes);
            Append(code, BranchCarryWord);
            var envelopeWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveLongD2ToD0);
            Append(code, CompareLongD1ToD0); // table - envelopeEnd
            Append(code, BranchCarryWord);
            var envelopeOverlapsTableBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BranchAlwaysWord);
            var tableDisjointJoinBranchExtensionOffset = code.Count;
            Append(code, 0);

            var tableBeforeEnvelopeOffset = code.Count;
            Append(code, CompareLongD0ToD4); // envelope - tableEnd
            Append(code, BranchCarryWord);
            var tableOverlapsEnvelopeBranchExtensionOffset = code.Count;
            Append(code, 0);

            var tableDisjointJoinOffset = code.Count;
            PatchBranch(
                code,
                tableBeforeEnvelopeBranchExtensionOffset,
                tableBeforeEnvelopeOffset);
            PatchBranch(
                code,
                tableDisjointJoinBranchExtensionOffset,
                tableDisjointJoinOffset);
            Append(code, MoveLongD7ToD0);
            failureBranches.Add(envelopeWrapBranchExtensionOffset);
            failureBranches.Add(envelopeOverlapsTableBranchExtensionOffset);
            failureBranches.Add(tableOverlapsEnvelopeBranchExtensionOffset);
        }

        Append(code, MoveLongD0ToD5);
        Append(code, MoveLongA3ToD4);
        Append(code, MoveLongD4ToPreDecrementA7);
        Append(code, MoveAddressA0ToA6);
        CheckAddress(MoveAddressA6ToA0, 0xFFFF_FEA6u);
        Append(code, MoveLongD5ToD0);
        Append(code, TestLongD0);
        BranchToFailure(BranchEqualWord);
        Append(code, CompareImmediateLongD0);
        Append(code, 0x0000);
        Append(code, 0x0008);
        BranchToFailure(BranchHighWord);

        // The table is caller/provider-owned input. Reject a wrapping table
        // or an alias with any public envelope before reading it or clearing
        // the exact classic topology.
        Append(code, MoveLongA3ToD2);
        Append(code, MoveLongD2ToD0);
        Append(code, MoveLongD5ToD1);
        Append(code, ShiftLeftLongD1);
        Append(code, ShiftLeftLongD1);
        Append(code, AddLongD1ToD0);
        BranchToFailure(BranchCarryWord);
        CheckTableAgainst(MoveLongA0ToD4, (uint)GraphicsLayouts.ScreenSize);
        CheckTableAgainst(MoveLongA1ToD4, (uint)GraphicsLayouts.ViewSize);
        CheckTableAgainst(MoveLongA2ToD4, (uint)GraphicsLayouts.RasInfoSize);

        // The embedded header is part of the exact multi-plane topology:
        // a caller changing BitMap.Depth must decline before any clear.
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongImmediateD0);
        Append(code, 0x0000);
        Append(
            code,
            checked((ushort)(GraphicsLayouts.ScreenBitMap + GraphicsLayouts.BitMapDepth)));
        Append(code, MoveLongD0ToD7);
        Append(code, AddLongD7ToA0);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, 0);
        Append(code, MoveLongD5ToD0);
        Append(code, CompareLongD6ToD0);
        BranchToFailure(BranchNotEqualWord);

        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongImmediateD0);
        Append(code, 0x0000);
        Append(
            code,
            checked((ushort)(GraphicsLayouts.ScreenBitMap + GraphicsLayouts.BitMapPlanes)));
        Append(code, MoveLongD0ToD7);
        Append(code, AddLongD7ToA0);
        Append(code, MoveLongD5ToD1);
        Append(code, SubQuickOneLongD1);
        var compareLoopOffset = code.Count;
        Append(code, MoveLongA3PostIncrementToD4);
        Append(code, MoveLongA0PostIncrementToD0);
        Append(code, MoveLongD4ToD6);
        Append(code, CompareLongD6ToD0);
        Append(code, BranchNotEqualWord);
        var compareFailureBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, DecrementBranchD1);
        var compareBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveAddressD7ToA3);
        Append(code, MoveLongA3PostIncrementToD0);
        Append(code, MoveAddressA6ToA0);
        AppendJsrPcRelative(code, classicTeardownOffset);
        Append(code, ReturnFromSubroutine);

        var failureOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD7);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, compareFailureBranchExtensionOffset, failureOffset);
        PatchBranch(code, compareBranchExtensionOffset, compareLoopOffset);
        foreach (var branchExtensionOffset in failureBranches)
            PatchBranch(code, branchExtensionOffset, failureOffset);
        return offset;
    }

    private static int AppendInitView(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(3);

        // View is 0x12 bytes: clear four longwords and the trailing word,
        // then publish the standard DIW origin words.
        Append(code, MoveLongA1ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullDescriptorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullDescriptorBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddDescriptorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddDescriptorBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFEE); // ViewSize (0x12) envelope
        Append(code, BranchHighWord);
        var wrappedDescriptorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedDescriptorBranchExtensionOffset);
        Append(code, MoveAddressA1ToA0);
        Append(code, MoveQuickZeroD0);
        Append(code, 0x7203); // four longword iterations: DBRA counts down
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, DecrementBranchD1);
        Append(code, 0xFFFC);
        Append(code, MoveWordD0ToA0);
        Append(code, 0x702C);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewDyOffset));
        Append(code, MoveImmediateWordD0);
        Append(code, 0x0081);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.ViewDxOffset));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendInitVPort(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(3);

        // ViewPort is 0x28 bytes, or ten longwords.  InitVPort then publishes
        // only the classic sprite-priority byte at offset 0x22.
        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullDescriptorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullDescriptorBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddDescriptorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddDescriptorBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // ViewPortSize (0x28) envelope
        Append(code, BranchHighWord);
        var wrappedDescriptorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedDescriptorBranchExtensionOffset);
        Append(code, MoveQuickZeroD0);
        Append(code, 0x7209); // ten longword iterations
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, DecrementBranchD1);
        Append(code, 0xFFFC);
        Append(code, 0x7024);
        Append(code, 0x1140); // MOVE.B D0,-6(A0) after the clear loop
        Append(code, unchecked((ushort)(GraphicsLayouts.ViewPortSpritePriorities - GraphicsLayouts.ViewPortSize)));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendInitBitMap(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(5);

        // InitBitMap publishes only the geometry/header prefix; Planes[] is
        // caller-owned and remains untouched.  Compute BytesPerRow as the
        // classic ((width + 15) >> 4) * 2 in D1.
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullDescriptorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullDescriptorBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddDescriptorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddDescriptorBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8); // eight-byte public prefix must not wrap
        Append(code, BranchHighWord);
        var wrappedDescriptorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedDescriptorBranchExtensionOffset);
        Append(code, MoveLongD0ToD3); // preserve depth while D0 becomes flags
        Append(code, CompareImmediateByteD3);
        Append(code, 0x0000);
        Append(code, BranchEqualWord);
        var zeroDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(zeroDepthBranchExtensionOffset);
        Append(code, CompareImmediateByteD3);
        Append(code, 0x0008);
        Append(code, BranchHighWord);
        var highDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(highDepthBranchExtensionOffset);
        // Keep the native arithmetic in its 16-bit safe range. Larger widths
        // remain available to the portable/provider implementation rather than
        // allowing the WORD add below to wrap before BytesPerRow is published.
        Append(code, CompareImmediateWordD1);
        Append(code, 0xFFF0);
        Append(code, BranchHighWord);
        var widthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthRangeBranchExtensionOffset);
        Append(code, AddImmediateWordD1);
        Append(code, 0x000F);
        Append(code, ShiftRightWordD1);
        Append(code, ShiftRightWordD1);
        Append(code, ShiftRightWordD1);
        Append(code, ShiftRightWordD1);
        Append(code, AddWordD1ToD1);
        Append(code, MoveWordD1ToA0Displacement);
        Append(code, 0x0000);
        Append(code, MoveWordD2ToA0Displacement);
        Append(code, 0x0002);
        Append(code, MoveByteD3ToA0Displacement);
        Append(code, 0x0005);
        Append(code, 0x7008); // BMF_STANDARD
        Append(code, 0x1140);
        Append(code, 0x0004);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 0x0006);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendInitTmpRas(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(3);

        // InitTmpRas stores only the caller-owned descriptor pair; it does
        // not dereference the backing buffer at A1.
        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullDescriptorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullDescriptorBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddDescriptorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddDescriptorBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8); // two LONG fields must stay inside 32-bit space
        Append(code, BranchHighWord);
        var wrappedDescriptorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedDescriptorBranchExtensionOffset);
        Append(code, MoveLongA1ToD1);
        Append(code, MoveLongD1ToA0Displacement);
        Append(code, 0x0000);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, 0x0004);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendInitArea(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;

        // InitArea publishes the classic AreaInfo envelope.  The caller owns
        // the coordinate/flag storage, so only its derived flag-table pointer
        // is computed here; no backing bytes are touched.  D0 is the signed
        // MAXVECTORS word, A0 is the descriptor, and A1 is the vector table.
        Append(code, TestWordD0);
        Append(code, BranchMinusWord);
        var negativeCapacityBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressA0ToA2);
        Append(code, MoveQuickZeroD3);
        Append(code, 0x7805); // six longwords: AreaInfoSize (0x18 bytes)
        Append(code, MoveLongD3ToA2PostIncrement);
        Append(code, DecrementBranchD4);
        Append(code, 0xFFFC);

        Append(code, MoveLongA1ToD1);
        Append(code, MoveLongD0ToD2);
        Append(code, ExtendLongD2);
        Append(code, AddLongD2ToD2);
        Append(code, AddLongD2ToD2);
        Append(code, AddLongD2ToD1);
        Append(code, MoveLongA1ToA0Displacement);
        Append(code, 0x0000);
        Append(code, MoveLongA1ToA0Displacement);
        Append(code, 0x0004);
        Append(code, MoveLongD1ToA0Displacement);
        Append(code, 0x0008);
        Append(code, MoveLongD1ToA0Displacement);
        Append(code, 0x000C);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 0x0012);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 0x0010);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 0x0014);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, 0x0016);
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, negativeCapacityBranchExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendReadPixelLine8(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(28);

        // Keep the native pixel-array line form bounded to width 1..128 over
        // the two-row, two-/four-/eight-/sixteen-byte-stride standard one-plane form,
        // where x is 0 or the byte-aligned second cell at 8. The caller's chunky bytes
        // are written only after the RastPort, BitMap, plane, and output
        // envelopes have been checked.  Every other geometry, temporary
        // workspace, or ownership form returns through the shared fallback
        // with the original D0 argument intact.
        Append(code, MoveLongD0ToD7); // preserve the caller's x/result word

        Append(code, TestWordD2);
        Append(code, BranchEqualWord);
        var widthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthBranchExtensionOffset);
        Append(code, CompareImmediateWordD2);
        Append(code, 128);
        Append(code, BranchHighWord);
        var widthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthRangeBranchExtensionOffset);

        Append(code, MoveLongA1ToD6); // temporary RastPort must be NULL
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var temporaryBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(temporaryBranchExtensionOffset);

        Append(code, MoveLongA2ToD6); // caller-owned output byte
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var arrayNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(arrayNullBranchExtensionOffset);

        // The native body emits at most one-hundred-twenty-eight bytes.  Keep the guest output
        // pointer arithmetic non-wrapping before any byte is published.
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF80);
        Append(code, BranchHighWord);
        var arrayRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(arrayRangeBranchExtensionOffset);

        Append(code, MoveAddressD0ToA3); // retain x for the byte offset
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var xZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 8); // byte-aligned second cell
        Append(code, BranchNotEqualWord);
        var xBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xBranchExtensionOffset);
        var xValidatedOffset = code.Count;
        PatchBranch(code, xZeroBranchExtensionOffset, xValidatedOffset);
        // Preserve a zero-extended copy of the low-WORD Y before D1 is
        // reused for the width.  A4 carries only the admitted row selector.
        Append(code, MoveQuickZeroD3);
        Append(code, MoveWordD1ToD3);
        Append(code, MoveLongD3ToD0);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongD7ToD0);
        Append(code, CompareImmediateWordD1);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var yZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 1); // bounded second row only
        Append(code, BranchNotEqualWord);
        var yBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yBranchExtensionOffset);
        var yValidatedOffset = code.Count;
        PatchBranch(code, yZeroBranchExtensionOffset, yValidatedOffset);
        Append(code, MoveQuickZeroD1);
        Append(code, MoveWordD2ToD1); // retain zero-extended width before D2 becomes BitMap

        // Standard, even, bounded RastPort envelope.
        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0x0000);
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var layerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layerBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD2);
        Append(code, 0xFFFF);
        Append(code, 0x0000);
        Append(code, BranchHighWord);
        var bitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapRangeBranchExtensionOffset);
        Append(code, MoveAddressD2ToA0);

        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD3);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);

        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));

        // Widths 32, 64, and 128 are exact aligned wide forms.  They stay on
        // the same line loop, but require x=0 and a stride that can hold the
        // selected byte span.  Narrow widths retain the earlier 2/4-byte
        // behavior and may still use x=8.
        Append(code, CompareImmediateWordD1);
        Append(code, 128);
        Append(code, BranchEqualWord);
        var widthOneHundredTwentyEightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 64);
        Append(code, BranchEqualWord);
        var widthSixtyFourBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 32);
        Append(code, BranchEqualWord);
        var widthThirtyTwoBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 16);
        Append(code, BranchHighWord);
        var unsupportedMidWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedMidWidthBranchExtensionOffset);

        Append(code, CompareImmediateWordD4);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var narrowTwoByteStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 4);
        Append(code, BranchEqualWord);
        var narrowFourByteStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 8);
        Append(code, BranchNotEqualWord);
        var narrowBytesPerRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(narrowBytesPerRowBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var narrowReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var narrowTwoByteStrideCheckOffset = code.Count;
        PatchBranch(code, narrowTwoByteStrideBranchExtensionOffset, narrowTwoByteStrideCheckOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 16);
        Append(code, BranchNotEqualWord);
        var widthNotSixteenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 8);
        Append(code, BranchEqualWord);
        var xEightWidthSixteenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xEightWidthSixteenBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var narrowTwoByteReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthThirtyTwoOffset = code.Count;
        PatchBranch(code, widthThirtyTwoBranchExtensionOffset, widthThirtyTwoOffset);
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var widthThirtyTwoXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthThirtyTwoXBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 4);
        Append(code, BranchEqualWord);
        var widthThirtyTwoFourByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 8);
        Append(code, BranchNotEqualWord);
        var widthThirtyTwoStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthThirtyTwoStrideBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var widthThirtyTwoReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthOneHundredTwentyEightOffset = code.Count;
        PatchBranch(
            code,
            widthOneHundredTwentyEightBranchExtensionOffset,
            widthOneHundredTwentyEightOffset);
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var widthOneHundredTwentyEightXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthOneHundredTwentyEightXBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 16);
        Append(code, BranchNotEqualWord);
        var widthOneHundredTwentyEightStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthOneHundredTwentyEightStrideBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var widthOneHundredTwentyEightReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthSixtyFourOffset = code.Count;
        PatchBranch(code, widthSixtyFourBranchExtensionOffset, widthSixtyFourOffset);
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var widthSixtyFourXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthSixtyFourXBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 8);
        Append(code, BranchNotEqualWord);
        var widthSixtyFourStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthSixtyFourStrideBranchExtensionOffset);
        var bytesPerRowReadyOffset = code.Count;
        PatchBranch(code, narrowReadyBranchExtensionOffset, bytesPerRowReadyOffset);
        PatchBranch(code, widthNotSixteenBranchExtensionOffset, bytesPerRowReadyOffset);
        PatchBranch(code, narrowFourByteStrideBranchExtensionOffset, bytesPerRowReadyOffset);
        PatchBranch(code, narrowTwoByteReadyBranchExtensionOffset, bytesPerRowReadyOffset);
        PatchBranch(code, widthThirtyTwoFourByteBranchExtensionOffset, bytesPerRowReadyOffset);
        PatchBranch(code, widthThirtyTwoReadyBranchExtensionOffset, bytesPerRowReadyOffset);
        PatchBranch(
            code,
            widthOneHundredTwentyEightReadyBranchExtensionOffset,
            bytesPerRowReadyOffset);

        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, MoveLongA4ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rowZeroRowsValidationBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Y=1 needs a second bitmap row; Y=0 remains compatible with the
        // one-row ReadPixelArray8 fixtures and callers.
        Append(code, CompareImmediateWordD5);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var rowOneRowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowOneRowsBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var rowOneRowsValidBranchExtensionOffset = code.Count;
        Append(code, 0);

        var rowZeroRowsValidationOffset = code.Count;
        Append(code, CompareImmediateWordD5);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var rowZeroOneRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD5);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var rowZeroRowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowZeroRowsBranchExtensionOffset);

        var rowsValidatedOffset = code.Count;
        PatchBranch(code, rowZeroRowsValidationBranchExtensionOffset, rowZeroRowsValidationOffset);
        PatchBranch(code, rowOneRowsValidBranchExtensionOffset, rowsValidatedOffset);
        PatchBranch(code, rowZeroOneRowBranchExtensionOffset, rowsValidatedOffset);

        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFE0); // sixteen-byte span plus the optional second row
        Append(code, BranchHighWord);
        var planeRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeRangeBranchExtensionOffset);

        // The planar byte uses Amiga's MSB-first bit numbering. Stage it in
        // D6, then emit one chunky pen byte per requested pixel while shifting
        // toward the next bit. D7 is rebound to the successful sample count
        // only after every fallback branch above has become unreachable.
        Append(code, MoveAddressD6ToA0);
        Append(code, MoveLongA4ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rowZeroAddressBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressA0ToA5);
        Append(code, AddLongD4ToA5);
        Append(code, MoveAddressA5ToA0);
        var rowAddressReadyOffset = code.Count;
        PatchBranch(code, rowZeroAddressBranchExtensionOffset, rowAddressReadyOffset);
        Append(code, MoveAddressA3ToA5);
        Append(code, MoveLongA0ToA3);
        Append(code, MoveAddressA3ToA4);
        Append(code, MoveLongA5ToD0);
        Append(code, ShiftRightWordD0Count3);
        Append(code, ExtendLongD0);
        Append(code, AddLongD0ToA4);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA0PostIncrementToD6);
        // A0 is repurposed for the caller-owned chunky output below. Keep
        // the planar cursor in A5 so a sixteen-pixel slice can reload its
        // second source byte after the first eight pixels.
        Append(code, MoveAddressA0ToA5);
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveWordD1ToD3);
        Append(code, SubQuickOneWordD3);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveLongD1ToD4); // retain the width for the line loop
        Append(code, MoveQuickZeroD7);
        Append(code, MoveWordD1ToD7);
        Append(code, MoveQuickEightD5); // reload source after each eight pixels

        var pixelLoopOffset = code.Count;
        Append(code, BitTestImmediateD6);
        Append(code, 7);
        Append(code, BranchEqualWord);
        var zeroPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickOneD0);
        Append(code, BranchAlwaysWord);
        var storePixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        var zeroPixelOffset = code.Count;
        Append(code, MoveQuickZeroD0);

        var storePixelOffset = code.Count;
        Append(code, MoveLongD0ToD1);
        Append(code, MoveByteD1ToA0PostIncrement);
        Append(code, ShiftLeftLongD6);
        Append(code, SubQuickOneWordD5);
        Append(code, CompareImmediateWordD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var reloadByteCounterBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD3);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var reloadByteLastPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressA0ToA4);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA0PostIncrementToD6);
        Append(code, MoveAddressA0ToA5);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveQuickEightD5);
        var reloadByteReadyOffset = code.Count;
        PatchBranch(code, reloadByteCounterBranchExtensionOffset, reloadByteReadyOffset);
        PatchBranch(code, reloadByteLastPixelBranchExtensionOffset, reloadByteReadyOffset);
        Append(code, DecrementBranchD3);
        var pixelLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD7ToD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, zeroPixelBranchExtensionOffset, zeroPixelOffset);
        PatchBranch(code, storePixelBranchExtensionOffset, storePixelOffset);
        PatchBranch(code, pixelLoopBranchExtensionOffset, pixelLoopOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendReadPixelArray8(
        List<byte> code,
        int fallbackEntryOffset,
        int readPixelLine8EntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(5);

        // ReadPixelArray8 shares the V36 byte-array ABI with ReadPixelLine8,
        // but carries an inclusive rectangle in D0..D3.  Keep the native
        // slice to the two bounded rows (xStart,y)-(xStop,y), y 0..1, where
        // the origin is either byte cell 0 or byte cell 8 for narrow spans,
        // while exact thirty-two/sixty-four/one-hundred-twenty-eight-pixel
        // spans require x=0. Enter the already validated line body after
        // translating D2 to width 1..128. Any other rectangle remains
        // transparent to the portable/provider owner.
        Append(code, MoveLongD0ToD7); // preserve xStart/result on decline

        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var xZeroStartBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 8); // byte-aligned second cell
        Append(code, BranchNotEqualWord);
        var xStartBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xStartBranchExtensionOffset);
        var xStartValidatedOffset = code.Count;
        PatchBranch(code, xZeroStartBranchExtensionOffset, xStartValidatedOffset);

        Append(code, CompareWordD1ToD3);
        Append(code, BranchNotEqualWord);
        var yBoundsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yBoundsBranchExtensionOffset);

        Append(code, CompareImmediateWordD1);
        Append(code, 2); // yStart == yStop == 0 or 1
        Append(code, BranchHighWord);
        var yRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yRangeBranchExtensionOffset);

        Append(code, MoveWordD0ToD5);
        Append(code, SubWordD5ToD2); // xStop - xStart
        Append(code, CompareImmediateWordD2);
        Append(code, 127); // inclusive span width-1 <= 127
        Append(code, BranchHighWord);
        var xStopBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xStopBranchExtensionOffset);

        Append(code, AddImmediateWordD2);
        Append(code, 1); // line body consumes width = xStop - xStart + 1
        Append(code, CompareImmediateWordD2);
        Append(code, 128);
        Append(code, BranchEqualWord);
        var widthOneHundredTwentyEightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 64);
        Append(code, BranchEqualWord);
        var widthSixtyFourBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 32);
        Append(code, BranchEqualWord);
        var widthThirtyTwoBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 16);
        Append(code, BranchHighWord);
        var unsupportedMidWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedMidWidthBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var lineBodyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthThirtyTwoOffset = code.Count;
        Append(code, CompareImmediateWordD5);
        Append(code, 0); // wide rectangles are admitted only from x=0
        Append(code, BranchNotEqualWord);
        var widthThirtyTwoXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthThirtyTwoXBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var widthThirtyTwoLineBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthSixtyFourOffset = code.Count;
        Append(code, CompareImmediateWordD5);
        Append(code, 0); // wide rectangles are admitted only from x=0
        Append(code, BranchNotEqualWord);
        var widthSixtyFourXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthSixtyFourXBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var widthSixtyFourLineBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthOneHundredTwentyEightOffset = code.Count;
        Append(code, CompareImmediateWordD5);
        Append(code, 0); // wide rectangles are admitted only from x=0
        Append(code, BranchNotEqualWord);
        var widthOneHundredTwentyEightXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthOneHundredTwentyEightXBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var widthOneHundredTwentyEightLineBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, lineBodyBranchExtensionOffset, readPixelLine8EntryOffset);
        PatchBranch(code, widthThirtyTwoBranchExtensionOffset, widthThirtyTwoOffset);
        PatchBranch(code, widthSixtyFourBranchExtensionOffset, widthSixtyFourOffset);
        PatchBranch(
            code,
            widthOneHundredTwentyEightBranchExtensionOffset,
            widthOneHundredTwentyEightOffset);
        PatchBranch(code, widthThirtyTwoLineBranchExtensionOffset, readPixelLine8EntryOffset);
        PatchBranch(code, widthSixtyFourLineBranchExtensionOffset, readPixelLine8EntryOffset);
        PatchBranch(
            code,
            widthOneHundredTwentyEightLineBranchExtensionOffset,
            readPixelLine8EntryOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendWritePixelLine8(
        List<byte> code,
        int fallbackEntryOffset,
        bool requireTemporaryRastPort = true,
        bool voidResult = false)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(28);

        // Symmetric with the bounded ReadPixelLine8 slice: claim only
        // WritePixelLine8(A0,x,y,width,A2,NULL), y=0 or 1, width 1..128, on a
        // standard one-plane BitMap with a two-, four-, eight-, or sixteen-byte
        // row stride. Narrow x is 0 or the byte-aligned second cell at 8; exact
        // thirty-two/sixty-four/one-hundred-twenty-eight-pixel forms require x=0. Each source byte's
        // low pen bit selects one MSB-first planar bit; higher planes,
        // clipping, temporary workspaces, and provider-owned surfaces remain
        // on the shared fallback owner.
        Append(code, MoveLongD0ToD7); // preserve the caller's x/result word

        Append(code, TestWordD2);
        Append(code, BranchEqualWord);
        var widthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthBranchExtensionOffset);
        Append(code, CompareImmediateWordD2);
        Append(code, 128);
        Append(code, BranchHighWord);
        var widthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthRangeBranchExtensionOffset);

        if (requireTemporaryRastPort)
        {
            Append(code, MoveLongA1ToD6); // temporary RastPort must be NULL
            Append(code, TestLongD6);
            Append(code, BranchNotEqualWord);
            var temporaryBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(temporaryBranchExtensionOffset);
        }

        Append(code, MoveLongA2ToD6); // caller-owned source byte
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var arrayNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(arrayNullBranchExtensionOffset);

        // The source is one byte per pixel.  Guard the maximum one-hundred-
        // twenty-eight-byte
        // source span before A2 is post-incremented in the native loop.
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF80);
        Append(code, BranchHighWord);
        var arrayRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(arrayRangeBranchExtensionOffset);

        Append(code, MoveAddressD0ToA3); // retain x for the byte offset
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var xZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 8); // byte-aligned second cell
        Append(code, BranchNotEqualWord);
        var xBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xBranchExtensionOffset);
        var xValidatedOffset = code.Count;
        PatchBranch(code, xZeroBranchExtensionOffset, xValidatedOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var yZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 1); // bounded second row only
        Append(code, BranchNotEqualWord);
        var yBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yBranchExtensionOffset);
        // Preserve a zero-extended copy of Y for the row-address addition;
        // D0 is restored from D7 before the existing X/result shadow is used.
        var yValidatedOffset = code.Count;
        PatchBranch(code, yZeroBranchExtensionOffset, yValidatedOffset);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveWordD1ToD3);
        Append(code, MoveLongD3ToD0);
        Append(code, MoveAddressD0ToA4);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveWordD2ToD1); // retain width before D2 becomes BitMap

        // Standard, even, bounded, non-layered RastPort envelope.
        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0x0000);
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var layerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layerBranchExtensionOffset);

        // The first plane must be selected by rp_Mask; higher bits do not
        // select any native plane in this one-plane body.
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD2);
        Append(code, 0xFFFF);
        Append(code, 0x0000);
        Append(code, BranchHighWord);
        var bitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapRangeBranchExtensionOffset);
        Append(code, MoveAddressD2ToA0);

        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD3);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD1);
        Append(code, 128);
        Append(code, BranchEqualWord);
        var widthOneHundredTwentyEightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 64);
        Append(code, BranchEqualWord);
        var widthSixtyFourBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 32);
        Append(code, BranchEqualWord);
        var widthThirtyTwoBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 16);
        Append(code, BranchHighWord);
        var unsupportedMidWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedMidWidthBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var twoByteStrideReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 4);
        Append(code, BranchNotEqualWord);
        var bytesPerRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bytesPerRowBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var fourByteStrideReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var twoByteStrideCheckOffset = code.Count;
        PatchBranch(code, twoByteStrideReadyBranchExtensionOffset, twoByteStrideCheckOffset);
        Append(code, CompareImmediateWordD1);
        Append(code, 16);
        Append(code, BranchHighWord);
        var unsupportedNarrowWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedNarrowWidthBranchExtensionOffset);
        Append(code, BranchNotEqualWord);
        var widthNotSixteenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 8);
        Append(code, BranchEqualWord);
        var xEightWidthSixteenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xEightWidthSixteenBranchExtensionOffset);
        var bytesPerRowReadyOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var bytesPerRowReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, widthNotSixteenBranchExtensionOffset, bytesPerRowReadyOffset);
        PatchBranch(code, fourByteStrideReadyBranchExtensionOffset, bytesPerRowReadyOffset);

        var widthThirtyTwoOffset = code.Count;
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var widthThirtyTwoXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthThirtyTwoXBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 4);
        Append(code, BranchEqualWord);
        var widthThirtyTwoFourByteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 8);
        Append(code, BranchNotEqualWord);
        var widthThirtyTwoStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthThirtyTwoStrideBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var widthThirtyTwoReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthOneHundredTwentyEightOffset = code.Count;
        PatchBranch(
            code,
            widthOneHundredTwentyEightBranchExtensionOffset,
            widthOneHundredTwentyEightOffset);
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var widthOneHundredTwentyEightXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthOneHundredTwentyEightXBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 16);
        Append(code, BranchNotEqualWord);
        var widthOneHundredTwentyEightStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthOneHundredTwentyEightStrideBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var widthOneHundredTwentyEightReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthSixtyFourOffset = code.Count;
        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var widthSixtyFourXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthSixtyFourXBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 8);
        Append(code, BranchNotEqualWord);
        var widthSixtyFourStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthSixtyFourStrideBranchExtensionOffset);
        PatchBranch(code, widthThirtyTwoFourByteBranchExtensionOffset, bytesPerRowReadyOffset);
        PatchBranch(code, widthThirtyTwoReadyBranchExtensionOffset, bytesPerRowReadyOffset);
        PatchBranch(code, widthThirtyTwoBranchExtensionOffset, widthThirtyTwoOffset);
        PatchBranch(code, widthSixtyFourBranchExtensionOffset, widthSixtyFourOffset);
        var commonBytesPerRowReadyOffset = code.Count;
        PatchBranch(code, bytesPerRowReadyBranchExtensionOffset, commonBytesPerRowReadyOffset);
        PatchBranch(
            code,
            widthOneHundredTwentyEightReadyBranchExtensionOffset,
            commonBytesPerRowReadyOffset);

        Append(code, MoveWordA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestWordD5);
        Append(code, BranchEqualWord);
        var rowZeroRowsValidationBranchExtensionOffset = code.Count;
        Append(code, 0);
        // Y=1 needs a second bitmap row; Y=0 remains compatible with the
        // existing one-row writer form and also accepts a two-row bitmap.
        Append(code, MoveLongA4ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rowZeroYRowsValidationBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD5);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var rowOneRowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowOneRowsBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var rowOneRowsValidBranchExtensionOffset = code.Count;
        Append(code, 0);

        var rowZeroRowsValidationOffset = code.Count;
        Append(code, CompareImmediateWordD5);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var rowZeroOneRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD5);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var rowZeroRowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowZeroRowsBranchExtensionOffset);

        var rowsValidatedOffset = code.Count;
        PatchBranch(code, rowZeroRowsValidationBranchExtensionOffset, rowZeroRowsValidationOffset);
        PatchBranch(code, rowZeroYRowsValidationBranchExtensionOffset, rowZeroRowsValidationOffset);
        PatchBranch(code, rowOneRowsValidBranchExtensionOffset, rowsValidatedOffset);
        PatchBranch(code, rowZeroOneRowBranchExtensionOffset, rowsValidatedOffset);

        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFE0); // sixteen-byte span plus the optional second row
        Append(code, BranchHighWord);
        var planeRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeRangeBranchExtensionOffset);

        // Read one source pen byte per iteration, then set or clear the
        // corresponding MSB-first bit in the destination plane. D6 starts at
        // bit seven and is decremented only after the current bit is updated;
        // whenever it reaches -1, the next eight-pixel cell advances the
        // destination byte and resets D6 to bit seven. D7 is rebound to the
        // successful sample count after all fallback branches are unreachable.
        Append(code, MoveLongD6ToD5); // preserve the validated plane pointer
        Append(code, MoveQuickZeroD3);
        Append(code, MoveWordD1ToD3);
        Append(code, SubQuickOneWordD3);
        Append(code, MoveQuickZeroD7);
        Append(code, MoveWordD1ToD7);
        Append(code, MoveQuickSevenD6);
        Append(code, MoveAddressD5ToA0);
        Append(code, MoveLongA4ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rowZeroAddressBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressA0ToA5);
        Append(code, AddLongD4ToA5);
        Append(code, MoveAddressA5ToA0);
        var rowAddressReadyOffset = code.Count;
        PatchBranch(code, rowZeroAddressBranchExtensionOffset, rowAddressReadyOffset);
        Append(code, MoveAddressA3ToA5);
        Append(code, MoveLongA0ToA3);
        Append(code, MoveAddressA3ToA4);
        Append(code, MoveLongA5ToD0);
        Append(code, ShiftRightWordD0Count3);
        Append(code, ExtendLongD0);
        Append(code, AddLongD0ToA4);
        Append(code, MoveAddressA4ToA0);

        var pixelLoopOffset = code.Count;
        Append(code, CompareImmediateWordD6);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var reloadByteCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, AddQuickOneLongA0);
        Append(code, MoveQuickSevenD6);
        var reloadByteReadyOffset = code.Count;
        PatchBranch(code, reloadByteCountBranchExtensionOffset, reloadByteReadyOffset);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA2PostIncrementToD0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var clearPixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitSetDynamicD6AtA0);
        Append(code, BranchAlwaysWord);
        var updatePixelBranchExtensionOffset = code.Count;
        Append(code, 0);
        var clearPixelOffset = code.Count;
        Append(code, BitClearDynamicD6AtA0);

        var updatePixelOffset = code.Count;
        Append(code, SubQuickOneWordD6);
        Append(code, DecrementBranchD3);
        var pixelLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, voidResult ? MoveQuickZeroD0 : MoveLongD7ToD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, clearPixelBranchExtensionOffset, clearPixelOffset);
        PatchBranch(code, updatePixelBranchExtensionOffset, updatePixelOffset);
        PatchBranch(code, pixelLoopBranchExtensionOffset, pixelLoopOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendWriteChunkyPixels(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(10);

        // V40 WriteChunkyPixels has signed LONG rectangle coordinates and an
        // explicit signed LONG stride. Claim only one byte-aligned planar cell
        // at x=0 or x=8, y=0 or y=1, with narrow inclusive widths of one through
        // sixteen and exact aligned thirty-two/sixty-four/one-hundred-twenty-eight-pixel widths from
        // x=0. The source stride must equal the admitted width. The writer
        // body below is the same checked one-plane publication used by
        // WritePixelLine8, but does not inspect A1 (the V40 ABI has no
        // temporary RastPort) and returns the vector's void D0 shape.
        Append(code, MoveLongD0ToD7); // preserve xStart on geometry decline

        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var xZeroStartBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD0);
        Append(code, 0);
        Append(code, 8); // byte-aligned second cell
        Append(code, BranchNotEqualWord);
        var xStartBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xStartBranchExtensionOffset);
        var xStartValidatedOffset = code.Count;
        PatchBranch(code, xZeroStartBranchExtensionOffset, xStartValidatedOffset);

        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var yStartZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var yStartBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yStartBranchExtensionOffset);
        var yStartValidatedOffset = code.Count;
        PatchBranch(code, yStartZeroBranchExtensionOffset, yStartValidatedOffset);

        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 127); // wide forms retain the bounded 128-pixel envelope
        Append(code, BranchHighWord);
        var xStopBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xStopBranchExtensionOffset);

        Append(code, CompareImmediateLongD3);
        Append(code, 0);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var yStopZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD3);
        Append(code, 0);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var yStopBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yStopBranchExtensionOffset);
        var yStopValidatedOffset = code.Count;
        PatchBranch(code, yStopZeroBranchExtensionOffset, yStopValidatedOffset);
        Append(code, CompareWordD1ToD3);
        Append(code, BranchNotEqualWord);
        var yBoundsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yBoundsBranchExtensionOffset);

        Append(code, MoveWordD0ToD5);
        Append(code, SubWordD5ToD2); // xStop - xStart
        Append(code, CompareImmediateWordD2);
        Append(code, 127); // inclusive span width-1 <= 127
        Append(code, BranchHighWord);
        var widthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthBranchExtensionOffset);
        Append(code, AddImmediateWordD2);
        Append(code, 1); // width = xStop - xStart + 1
        Append(code, CompareImmediateWordD2);
        Append(code, 128);
        Append(code, BranchEqualWord);
        var widthOneHundredTwentyEightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 64);
        Append(code, BranchEqualWord);
        var widthSixtyFourBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 32);
        Append(code, BranchEqualWord);
        var widthThirtyTwoBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 16);
        Append(code, BranchHighWord);
        var unsupportedMidWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedMidWidthBranchExtensionOffset);

        // Narrow source rows retain the existing explicit-stride equality.
        Append(code, MoveLongD2ToD5);
        Append(code, CompareLongD5ToD4);
        Append(code, BranchNotEqualWord);
        var strideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(strideBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var bodyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthThirtyTwoOffset = code.Count;
        Append(code, CompareImmediateWordD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var widthThirtyTwoXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthThirtyTwoXBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 32);
        Append(code, BranchNotEqualWord);
        var widthThirtyTwoStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthThirtyTwoStrideBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var widthThirtyTwoBodyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthSixtyFourOffset = code.Count;
        Append(code, CompareImmediateWordD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var widthSixtyFourXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthSixtyFourXBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 64);
        Append(code, BranchNotEqualWord);
        var widthSixtyFourStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthSixtyFourStrideBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var widthSixtyFourBodyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthOneHundredTwentyEightOffset = code.Count;
        Append(code, CompareImmediateWordD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var widthOneHundredTwentyEightXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthOneHundredTwentyEightXBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 128);
        Append(code, BranchNotEqualWord);
        var widthOneHundredTwentyEightStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthOneHundredTwentyEightStrideBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var widthOneHundredTwentyEightBodyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        var bodyOffset = AppendWritePixelLine8(
            code,
            fallbackEntryOffset,
            requireTemporaryRastPort: false,
            voidResult: true);

        PatchBranchPreferShort(code, bodyBranchExtensionOffset, bodyOffset);
        PatchBranchPreferShort(code, widthThirtyTwoBranchExtensionOffset, widthThirtyTwoOffset);
        PatchBranchPreferShort(code, widthSixtyFourBranchExtensionOffset, widthSixtyFourOffset);
        PatchBranchPreferShort(
            code,
            widthOneHundredTwentyEightBranchExtensionOffset,
            widthOneHundredTwentyEightOffset);
        PatchBranchPreferShort(code, widthThirtyTwoBodyBranchExtensionOffset, bodyOffset);
        PatchBranchPreferShort(code, widthSixtyFourBodyBranchExtensionOffset, bodyOffset);
        PatchBranchPreferShort(
            code,
            widthOneHundredTwentyEightBodyBranchExtensionOffset,
            bodyOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranchPreferShort(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendWritePixelArray8(
        List<byte> code,
        int fallbackEntryOffset,
        int writePixelLine8EntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(5);

        // WritePixelArray8 has the same inclusive D0..D3 rectangle as the
        // reader. Claim only one of the two bounded rows, with a byte-aligned
        // origin at x=0 or x=8 for narrow spans and x=0 for exact
        // thirty-two/sixty-four/one-hundred-twenty-eight-pixel spans; translate it into the line
        // body's width register and leave all clipping, strides, masks, and
        // other geometry on the existing owner.
        Append(code, MoveLongD0ToD7); // preserve xStart/result on decline

        Append(code, CompareImmediateWordD0);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var xZeroStartBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 8); // byte-aligned second cell
        Append(code, BranchNotEqualWord);
        var xStartBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xStartBranchExtensionOffset);
        var xStartValidatedOffset = code.Count;
        PatchBranch(code, xZeroStartBranchExtensionOffset, xStartValidatedOffset);

        Append(code, CompareWordD1ToD3);
        Append(code, BranchNotEqualWord);
        var yBoundsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yBoundsBranchExtensionOffset);

        Append(code, CompareImmediateWordD1);
        Append(code, 2); // yStart == yStop == 0 or 1
        Append(code, BranchHighWord);
        var yRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yRangeBranchExtensionOffset);

        Append(code, MoveWordD0ToD5);
        Append(code, SubWordD5ToD2); // xStop - xStart
        Append(code, CompareImmediateWordD2);
        Append(code, 127); // inclusive span width-1 <= 127
        Append(code, BranchHighWord);
        var xStopBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xStopBranchExtensionOffset);

        Append(code, AddImmediateWordD2);
        Append(code, 1); // width = xStop - xStart + 1
        Append(code, CompareImmediateWordD2);
        Append(code, 128);
        Append(code, BranchEqualWord);
        var widthOneHundredTwentyEightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 64);
        Append(code, BranchEqualWord);
        var widthSixtyFourBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 32);
        Append(code, BranchEqualWord);
        var widthThirtyTwoBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD2);
        Append(code, 16);
        Append(code, BranchHighWord);
        var unsupportedMidWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedMidWidthBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var lineBodyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthThirtyTwoOffset = code.Count;
        Append(code, CompareImmediateWordD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var widthThirtyTwoXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthThirtyTwoXBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var widthThirtyTwoLineBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthSixtyFourOffset = code.Count;
        Append(code, CompareImmediateWordD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var widthSixtyFourXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthSixtyFourXBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var widthSixtyFourLineBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthOneHundredTwentyEightOffset = code.Count;
        Append(code, CompareImmediateWordD5);
        Append(code, 0); // wide rectangles are admitted only from x=0
        Append(code, BranchNotEqualWord);
        var widthOneHundredTwentyEightXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthOneHundredTwentyEightXBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var widthOneHundredTwentyEightLineBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, lineBodyBranchExtensionOffset, writePixelLine8EntryOffset);
        PatchBranch(code, widthThirtyTwoBranchExtensionOffset, widthThirtyTwoOffset);
        PatchBranch(code, widthSixtyFourBranchExtensionOffset, widthSixtyFourOffset);
        PatchBranch(
            code,
            widthOneHundredTwentyEightBranchExtensionOffset,
            widthOneHundredTwentyEightOffset);
        PatchBranch(code, widthThirtyTwoLineBranchExtensionOffset, writePixelLine8EntryOffset);
        PatchBranch(code, widthSixtyFourLineBranchExtensionOffset, writePixelLine8EntryOffset);
        PatchBranch(
            code,
            widthOneHundredTwentyEightLineBranchExtensionOffset,
            writePixelLine8EntryOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendReadPixel(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(25);

        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x3D20); // D2-D5/D7/A2, reversed predecrement mask

        // Claim only a complete, ordinary non-layered OCS/ECS planar cell.
        // The stack frame preserves both caller coordinates on every decline;
        // native fallback therefore observes the exact original ABI even
        // after this body has used D0/D1 for offset/result calculation.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFF9C); // RastPortSize (0x64) envelope
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var layerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layerBranchExtensionOffset);
        Append(code, TestWordD0);
        Append(code, BranchMinusWord);
        var xSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xSignBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchMinusWord);
        var ySignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ySignBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var bitmapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD2);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var bitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapRangeBranchExtensionOffset);

        Append(code, MoveAddressD2ToA0);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, TestLongD3);
        Append(code, BranchNotEqualWord);
        var flagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(flagsBranchExtensionOffset);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, TestLongD3);
        Append(code, BranchEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);
        Append(code, CompareImmediateByteD3);
        Append(code, 8);
        Append(code, BranchHighWord);
        var depthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthRangeBranchExtensionOffset);

        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var strideZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(strideZeroBranchExtensionOffset);
        Append(code, TestWordD4);
        Append(code, BranchMinusWord);
        var strideSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(strideSignBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var strideOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(strideOddBranchExtensionOffset);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestWordD5);
        Append(code, BranchEqualWord);
        var rowsZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsZeroBranchExtensionOffset);
        Append(code, TestWordD5);
        Append(code, BranchMinusWord);
        var rowsSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsSignBranchExtensionOffset);
        Append(code, CompareWordD1ToD5);
        Append(code, BranchLowerOrSameWord);
        var yRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yRangeBranchExtensionOffset);
        // Preserve x&7 for the MSB-first memory bit while D0 becomes the byte
        // offset and D1 becomes row-plus-byte displacement.
        Append(code, MoveLongD0ToD5);
        Append(code, AndImmediateWordD5);
        Append(code, 0x0007);
        Append(code, MultiplySignedWordD4ToD1);
        Append(code, ShiftRightWordD0Count3);
        Append(code, ExtendLongD0);
        Append(code, CompareLongD0ToD4);
        Append(code, BranchLowerOrSameWord);
        var xByteRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xByteRangeBranchExtensionOffset);
        Append(code, AddLongD0ToD1);
        Append(code, BranchCarryWord);
        var offsetCarryBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(offsetCarryBranchExtensionOffset);

        Append(code, MoveAddressA0ToA2);
        Append(code, AddQuickEightLongA2);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveQuickOneD7);

        var loopEntryOffset = code.Count;
        Append(code, MoveLongA2PostIncrementToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var planeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, AddLongD1ToD4);
        Append(code, BranchCarryWord);
        var planeAddressCarryBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeAddressCarryBranchExtensionOffset);
        Append(code, MoveAddressD4ToA0);
        Append(code, MoveByteA0IndirectToD4);
        // The AccurateM68000 backend's dynamic BTST data-register path does
        // not retain the required byte-form result here. Select one of the
        // eight documented immediate register tests instead; each is the
        // same MSB-first planar test and is directly representable in a
        // future CopperSharp68k body.
        var bitTestBranches = new List<int>(7);
        for (var xMod = 0; xMod < 7; xMod++)
        {
            Append(code, CompareImmediateWordD5);
            Append(code, checked((ushort)xMod));
            Append(code, BranchEqualWord);
            bitTestBranches.Add(code.Count);
            Append(code, 0);
        }
        Append(code, BranchAlwaysWord);
        var lastBitTestBranchExtensionOffset = code.Count;
        Append(code, 0);

        var bitTestOffsets = new int[8];
        var bitTestContinueBranches = new List<int>(16);
        for (var xMod = 0; xMod < 8; xMod++)
        {
            bitTestOffsets[xMod] = code.Count;
            Append(code, BitTestImmediateD4);
            Append(code, checked((ushort)(7 - xMod)));
            Append(code, BranchEqualWord);
            bitTestContinueBranches.Add(code.Count);
            Append(code, 0);
            Append(code, OrLongD7ToD0);
            Append(code, BranchAlwaysWord);
            bitTestContinueBranches.Add(code.Count);
            Append(code, 0);
        }

        var bitTestContinueOffset = code.Count;
        Append(code, ShiftLeftLongD7);
        Append(code, SubQuickOneWordD3);
        Append(code, BranchNotEqualWord);
        var loopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x04BC); // retain accumulated D0 and existing CCR
        Append(code, ReturnFromSubroutine);

        for (var xMod = 0; xMod < bitTestBranches.Count; xMod++)
            PatchBranch(code, bitTestBranches[xMod], bitTestOffsets[xMod]);
        PatchBranch(code, lastBitTestBranchExtensionOffset, bitTestOffsets[7]);
        foreach (var branchExtensionOffset in bitTestContinueBranches)
            PatchBranch(code, branchExtensionOffset, bitTestContinueOffset);
        PatchBranch(code, loopBranchExtensionOffset, loopEntryOffset);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD1);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x04BC); // after both coordinate restores, before fallback
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    private static int AppendWritePixelDispatch(
        List<byte> code,
        int multiPlaneEntryOffset)
    {
        var offset = code.Count;

        // Admission is deliberately centralized in the transactional writer:
        // it must inspect the complete RastPort and BitMap envelopes before
        // dereferencing either.  This thin vector stub does not claim any
        // state by itself.
        Append(code, BranchAlwaysWord);
        var writerJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, writerJumpExtensionOffset, multiPlaneEntryOffset);

        return offset;
    }

    private static int AppendWritePixelMultiPlane(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(24);

        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x3F20); // D2-D7/A2, reversed predecrement mask

        // Claim one ordinary planar pixel on depth-1..8 bitmaps.  The
        // address and every selected plane link are preflighted before any
        // destination bit is changed.  Clipping, layers, interleaved/RTG
        // maps, and richer provider-owned forms stay on the shared portable
        // fallback boundary.  Preserve both public coordinate registers so a
        // decline has exactly the original graphics.library ABI.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongD0ToD2); // retain x while D0 inspects bitmap fields

        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFF9C); // RastPortSize (0x64) envelope
        Append(code, BranchHighWord);
        var rastPortRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortRangeBranchExtensionOffset);

        Append(code, TestWordD0);
        Append(code, BranchMinusWord);
        var xSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xSignBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchMinusWord);
        var ySignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ySignBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var bitmapRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapRangeBranchExtensionOffset);
        Append(code, MoveAddressD0ToA0);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var layerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layerBranchExtensionOffset);

        // RPF_NO_PENS denotes a private/provider colour sidecar.  Native
        // planar publication must not consume the public APen/BPen fields in
        // that representation.
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, BitTestImmediateD0);
        Append(code, 14); // RPF_NO_PENS
        Append(code, BranchNotEqualWord);
        var noPensBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(noPensBranchExtensionOffset);

        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var flagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(flagsBranchExtensionOffset);

        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, TestLongD3);
        Append(code, BranchEqualWord);
        var depthLowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthLowBranchExtensionOffset);
        Append(code, CompareImmediateByteD3);
        Append(code, 8);
        Append(code, BranchHighWord);
        var depthHighBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthHighBranchExtensionOffset);
        Append(code, SubQuickOneWordD3);

        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var strideZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(strideZeroBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var strideOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(strideOddBranchExtensionOffset);
        Append(code, TestWordD4);
        Append(code, BranchMinusWord);
        var strideSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(strideSignBranchExtensionOffset);

        // Reject y >= Rows and x/8 >= BytesPerRow before calculating the
        // guest address.  CMP.W source,Dn compares Dn-source, so lower-or-
        // same is the unsigned out-of-range case for both checks below.
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestWordD6);
        Append(code, BranchEqualWord);
        var rowsZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsZeroBranchExtensionOffset);
        Append(code, TestWordD6);
        Append(code, BranchMinusWord);
        var rowsSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsSignBranchExtensionOffset);
        Append(code, MoveQuickZeroD7);
        Append(code, MoveWordD1ToD7);
        Append(code, CompareWordD7ToD6);
        Append(code, BranchLowerOrSameWord);
        var yRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yRangeBranchExtensionOffset);

        // Capture the MSB-first bit selector in D7 while D5 is reused for
        // x/8 and D6 becomes the complete byte offset.
        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordD2ToD5);
        Append(code, AndImmediateWordD5);
        Append(code, 0x0007);
        Append(code, MoveQuickSevenD6);
        Append(code, SubWordD5ToD6);
        Append(code, MoveLongD6ToD7);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordD2ToD5);
        Append(code, ShiftRightWordD5Count3);
        Append(code, CompareWordD5ToD4);
        Append(code, BranchLowerOrSameWord);
        var xByteRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xByteRangeBranchExtensionOffset);

        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordD1ToD6);
        Append(code, MultiplyUnsignedWordD4ToD6);
        Append(code, AddLongD5ToD6);
        Append(code, BranchCarryWord);
        var offsetCarryBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(offsetCarryBranchExtensionOffset);

        Append(code, MoveLongD7ToD5);

        // A zero effective mask is a validated no-op and must not read the
        // inline plane table.  The loop below only visits the declared depth.
        Append(code, MoveQuickZeroD2);
        Append(code, MoveByteA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var zeroMaskBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveAddressA0ToA2);
        Append(code, AddQuickEightLongA2);
        Append(code, MoveQuickZeroD7);
        var preflightLoopOffset = code.Count;
        Append(code, MoveLongA2IndirectToD1);
        Append(code, MoveLongD2ToD0);
        Append(code, BitTestDynamicD7ToD0);
        Append(code, BranchEqualWord);
        var preflightSkipPlaneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, MoveLongD6ToD0);
        Append(code, AddLongD0ToD1);
        Append(code, BranchCarryWord);
        var planeAddressCarryBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeAddressCarryBranchExtensionOffset);

        var preflightNextPlaneOffset = code.Count;
        Append(code, AddQuickFourLongA2);
        Append(code, AddQuickOneLongD7);
        Append(code, DecrementBranchD3);
        var preflightLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Re-read the draw mode after preflight.  The three publication
        // paths retain the classic JAM/APen/BPen, COMPLEMENT, and INVERSVID
        // source selection without sharing mutable operation state.
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, BitTestImmediateD0);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var nonComplementBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var complementInverseBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var complementBranchExtensionOffset = code.Count;
        Append(code, 0);

        var nonComplementOffset = code.Count;
        PatchBranch(code, nonComplementBranchExtensionOffset, nonComplementOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var foregroundBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var inverseJam1BranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, AndImmediateWordD4);
        Append(code, 0x00FF);
        Append(code, BranchAlwaysWord);
        var bPenBranchExtensionOffset = code.Count;
        Append(code, 0);

        var foregroundOffset = code.Count;
        PatchBranch(code, foregroundBranchExtensionOffset, foregroundOffset);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, AndImmediateWordD4);
        Append(code, 0x00FF);
        Append(code, BranchAlwaysWord);
        var foregroundPublicationBranchExtensionOffset = code.Count;
        Append(code, 0);

        var complementOffset = code.Count;
        PatchBranch(code, complementBranchExtensionOffset, complementOffset);
        Append(code, BranchAlwaysWord);
        var complementPublicationBranchExtensionOffset = code.Count;
        Append(code, 0);

        var noOpOffset = code.Count;
        PatchBranch(code, complementInverseBranchExtensionOffset, noOpOffset);
        PatchBranch(code, inverseJam1BranchExtensionOffset, noOpOffset);
        Append(code, BranchAlwaysWord);
        var noOpSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);

        var complementPublicationOffset = code.Count;
        PatchBranch(code, complementPublicationBranchExtensionOffset, complementPublicationOffset);
        Append(code, MoveAddressA0ToA2);
        Append(code, AddQuickEightLongA2);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, SubQuickOneWordD3);
        Append(code, MoveQuickZeroD7);
        var complementLoopOffset = code.Count;
        Append(code, MoveLongA2IndirectToD1);
        Append(code, MoveLongD2ToD0);
        Append(code, BitTestDynamicD7ToD0);
        Append(code, BranchEqualWord);
        var complementSkipPlaneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD6ToD0);
        Append(code, AddLongD0ToD1);
        Append(code, MoveAddressD1ToA0);
        Append(code, BitChangeDynamicD5AtA0);
        var complementNextPlaneOffset = code.Count;
        Append(code, AddQuickFourLongA2);
        Append(code, AddQuickOneLongD7);
        Append(code, DecrementBranchD3);
        var complementLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var complementSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);

        var penPublicationOffset = code.Count;
        PatchBranch(code, bPenBranchExtensionOffset, penPublicationOffset);
        PatchBranch(code, foregroundPublicationBranchExtensionOffset, penPublicationOffset);
        Append(code, MoveAddressA0ToA2);
        Append(code, AddQuickEightLongA2);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, SubQuickOneWordD3);
        Append(code, MoveQuickZeroD7);
        var penLoopOffset = code.Count;
        Append(code, MoveLongA2IndirectToD1);
        Append(code, MoveLongD2ToD0);
        Append(code, BitTestDynamicD7ToD0);
        Append(code, BranchEqualWord);
        var penSkipPlaneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD6ToD0);
        Append(code, AddLongD0ToD1);
        Append(code, MoveAddressD1ToA0);
        Append(code, MoveLongD4ToD0);
        Append(code, BitTestDynamicD7ToD0);
        Append(code, BranchEqualWord);
        var penClearBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitSetDynamicD5AtA0);
        Append(code, BranchAlwaysWord);
        var penNextPlaneBranchExtensionOffset = code.Count;
        Append(code, 0);
        var penClearOffset = code.Count;
        Append(code, BitClearDynamicD5AtA0);
        var penNextPlaneOffset = code.Count;
        Append(code, AddQuickFourLongA2);
        Append(code, AddQuickOneLongD7);
        Append(code, DecrementBranchD3);
        var penLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveLongA7PostIncrementToD4);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x04FC); // retain existing success result and CCR behavior
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD1);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x04FC); // after both coordinate restores, before fallback
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, preflightSkipPlaneBranchExtensionOffset, preflightNextPlaneOffset);
        PatchBranch(code, preflightLoopBranchExtensionOffset, preflightLoopOffset);
        PatchBranch(code, zeroMaskBranchExtensionOffset, successOffset);
        PatchBranch(code, complementInverseBranchExtensionOffset, noOpOffset);
        PatchBranch(code, inverseJam1BranchExtensionOffset, noOpOffset);
        PatchBranch(code, complementSkipPlaneBranchExtensionOffset, complementNextPlaneOffset);
        PatchBranch(code, complementLoopBranchExtensionOffset, complementLoopOffset);
        PatchBranch(code, complementSuccessBranchExtensionOffset, successOffset);
        PatchBranch(code, penSkipPlaneBranchExtensionOffset, penNextPlaneOffset);
        PatchBranch(code, penClearBranchExtensionOffset, penClearOffset);
        PatchBranch(code, penNextPlaneBranchExtensionOffset, penNextPlaneOffset);
        PatchBranch(code, penLoopBranchExtensionOffset, penLoopOffset);
        PatchBranch(code, noOpSuccessBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendWritePixel(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(8);

        // This native body claims the one-plane, in-bounds WritePixel cell.
        // Its implicit source is one: ordinary JAM1 uses APen, JAM2 with
        // INVERSVID uses BPen, source-zero JAM1 is a successful no-op, and
        // COMPLEMENT toggles the selected destination bit.  The adapter still
        // owns clipping, layers/providers, and multi-plane admission.
        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var bitmapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapBranchExtensionOffset);

        Append(code, MoveAddressD2ToA0);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, SubQuickOneWordD3);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);

        // Keep DrawMode in D2; the bitmap pointer has already been copied to
        // A0 and D2 is otherwise dead for the remainder of this body.
        Append(code, MoveByteA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));

        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA1DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BitTestImmediateD3);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);

        Append(code, MoveLongD0ToD5);
        Append(code, AndImmediateWordD5);
        Append(code, 0x0007);

        Append(code, MoveWordA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var planeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeBranchExtensionOffset);

        Append(code, MoveQuickSevenD7);
        Append(code, SubWordD5ToD7);
        Append(code, MoveLongD7ToD5);
        Append(code, MultiplySignedWordD3ToD1);
        Append(code, ShiftRightWordD0Count3);
        Append(code, ExtendLongD0);
        Append(code, AddLongD1ToD4);
        Append(code, AddLongD0ToD4);
        Append(code, MoveAddressD4ToA0);

        // COMPLEMENT is independent of the pen colours.  With INVERSVID the
        // implicit source becomes zero, so the classic minterm is a successful
        // no-op; otherwise toggle the selected destination bit in place.
        Append(code, BitTestImmediateD2);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var nonComplementExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD2);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var complementNoOpExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitChangeDynamicD5AtA0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        // Ordinary source-one path: APen selects the destination value.
        var foregroundPathOffset = code.Count;
        Append(code, BitTestImmediateD2);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var inverseDispatchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, AndImmediateWordD6);
        Append(code, 0x0001);
        Append(code, BranchAlwaysWord);
        var foregroundWriteExtensionOffset = code.Count;
        Append(code, 0);

        // INVERSVID selects source zero.  JAM1 therefore does not touch the
        // destination; JAM2 uses BPen for the selected bit.
        var inversePathOffset = code.Count;
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var inverseNoOpExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, AndImmediateWordD6);
        Append(code, 0x0001);

        var writePathOffset = code.Count;
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var clearBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitSetDynamicD5AtA0);
        Append(code, BranchAlwaysWord);
        var successOffset = code.Count;
        Append(code, 0);
        var clearEntryOffset = code.Count;
        Append(code, BitClearDynamicD5AtA0);
        Append(code, BranchAlwaysWord);
        var clearSuccessExtensionOffset = code.Count;
        Append(code, 0);

        var returnOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        PatchBranch(code, nonComplementExtensionOffset, foregroundPathOffset);
        PatchBranch(code, inverseDispatchExtensionOffset, inversePathOffset);
        PatchBranch(code, complementNoOpExtensionOffset, returnOffset);
        PatchBranch(code, foregroundWriteExtensionOffset, writePathOffset);
        PatchBranch(code, inverseNoOpExtensionOffset, returnOffset);
        PatchBranch(code, clearBranchExtensionOffset, clearEntryOffset);
        PatchBranch(code, successOffset, returnOffset);
        PatchBranch(code, clearSuccessExtensionOffset, returnOffset);

        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    private static int AppendDrawEllipse(
        List<byte> code,
        int fallbackEntryOffset,
        int drawEntryTargetIslandOffset,
        NativeGraphicsBranchIslandAllocator relayAllocator,
        out int drawTailIslandOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(24);

        // This native DrawEllipse slice owns one-plane radius-one, equal
        // radius-two, and the bounded mixed (2,1)/(1,2)/(1,3)/(1,4)/(1,5)/
        // (1,6)/(1,7)/(1,8)/(1,9)/(1,10)/(1,11)/(1,12)/(1,13)/(1,14)/
        // (1,15)/(1,16)/(1,17)/(1,18)/(1,19)/(1,20)/(1,21)/(1,22)/(1,23)/
        // (1,24)/(1,25)/(1,26)/(3,1)/(2,3)/(3,2)/(4,1)
        // integer-symmetry
        // outlines.
        // It publishes the samples without touching the RastPort cursor or
        // line-pattern state.  Other mixed/larger radii, multi-plane maps,
        // layers, and provider-owned clipping remain on the portable/provider
        // owner until their dedicated native units exist.
        Append(code, MoveLongD0ToPreDecrementA7);
        // The public coordinates are WORDs while the radii are UWORDs.  Do
        // not let unspecified high halves from a caller's data registers
        // turn an otherwise valid point into a fallback.
        Append(code, MoveWordD0ToD4); // center X
        Append(code, ExtendLongD4);
        Append(code, MoveWordD1ToD5); // center Y
        Append(code, ExtendLongD5);
        Append(code, MoveWordD2ToD6); // radius X
        Append(code, AndImmediateLongD6);
        Append(code, 0);
        Append(code, 0xFFFF);
        Append(code, MoveWordD3ToD7); // radius Y
        Append(code, AndImmediateLongD7);
        Append(code, 0);
        Append(code, 0xFFFF);
        Append(code, CompareImmediateLongD6);
        Append(code, 0);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var radiusXZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(radiusXZeroBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var radiusXOneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD6);
        Append(code, 0);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var radiusTwoCheckBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD6);
        Append(code, 0);
        Append(code, 3);
        Append(code, BranchEqualWord);
        var radiusThreeCheckBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD6);
        Append(code, 0);
        Append(code, 4);
        Append(code, BranchNotEqualWord);
        var radiusXRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(radiusXRangeBranchExtensionOffset);

        // Radius-X-four owns only the exact portable `(4,1)` outline.
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var radiusFourYRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(radiusFourYRangeBranchExtensionOffset);
        Append(code, MoveQuickZeroD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, BranchAlwaysWord);
        var radiusFourOneReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var radiusThreeCheckOffset = code.Count;

        // Radius-X-three owns only the exact portable `(3,1)`, `(3,2)`, and
        // `(3,3)` outlines. Keep the marker distinct so its X bound and point
        // sequence cannot borrow either radius-two form.
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var radiusThreeOneCheckBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var radiusThreeTwoCheckBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 3);
        Append(code, BranchNotEqualWord);
        var radiusThreeYRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(radiusThreeYRangeBranchExtensionOffset);
        Append(code, MoveQuickZeroD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, BranchAlwaysWord);
        var radiusThreeThreeReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var radiusThreeTwoOffset = code.Count;
        Append(code, MoveQuickZeroD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, BranchAlwaysWord);
