        var radiusThreeOneOffset = code.Count;
        Append(code, MoveQuickZeroD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, BranchAlwaysWord);
        var radiusThreeOneReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var radiusTwoCheckOffset = code.Count;

        // Keep one compact marker in D1 for the point and bound dispatch:
        // 1=(1,1), 2=(2,2), 3=(2,1), 4=(1,2), 5=(1,3), 6=(3,1),
        // 7=(2,3), 8=(3,2), 9=(3,3), 10=(4,1), 11=(1,4), 12=(1,5),
        // 13=(1,6), 14=(1,7), 15=(1,8), 16=(1,9), 17=(1,10),
        // 18=(1,11), 19=(1,12), 20=(1,13), 21=(1,14), 22=(1,15),
        // 23=(1,16), 24=(1,17), 25=(1,18), 26=(1,19), 27=(1,20),
        // 28=(1,21), 29=(1,22), 30=(1,23), 31=(1,24), 32=(1,25),
        // 33=(1,26), 34=(1,27), 35=(1,28), 36=(1,29), 37=(1,30), and
        // 38=(1,31), 39=(1,32), 40=(1,33), 41=(1,34), 42=(1,35), and
        // 43=(1,36), 44=(1,37), 45=(1,38), 46=(1,39), 47=(1,40), and
        // 48=(1,41), 49=(1,42), 50=(1,43), 51=(1,44), 52=(1,45), and
        // 53=(1,46), 54=(1,47), 55=(1,48), 56=(1,49), 57=(1,50),
        // 58=(1,51), 59=(1,52), 60=(1,53), 61=(1,54), 62=(1,55),
        // 63=(1,56), 64=(1,57), 65=(1,58), 66=(1,59), 67=(1,60),
        // 68=(1,61), and 69=(1,62).
