        Append(code, 0);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var radiusTwoOneCheckBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 3);
        Append(code, BranchNotEqualWord);
        var radiusTwoYRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(radiusTwoYRangeBranchExtensionOffset);
        Append(code, MoveQuickZeroD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, BranchAlwaysWord);
        var radiusTwoThreeReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var radiusTwoOneOffset = code.Count;
        Append(code, MoveQuickZeroD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, AddQuickOneLongD1);
        Append(code, BranchAlwaysWord);
        var radiusTwoOneReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var radiusOneCheckOffset = code.Count;
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var radiusOneOneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var radiusOneTwoCheckBranchExtensionOffset = code.Count;
        Append(code, 0);
