        Append(code, 0);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 6);
        Append(code, BranchEqualWord);
        var radiusOneSixCheckBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
        Append(code, 7);
        Append(code, BranchEqualWord);
        var radiusOneSevenCheckBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD7);
        Append(code, 0);
