            radiusOneFiftyTwoBodySuccessMidIslandExtensionOffset,
            radiusOneFiftyTwoBodySuccessPostIslandExtensionOffset,
            radiusOneFiftyThreeBodySuccessPreIslandExtensionOffset,
            radiusOneFiftyThreeBodySuccessMidIslandExtensionOffset,
            radiusOneFiftyThreeBodySuccessPostIslandExtensionOffset,
            radiusOneFiftyFourBodySuccessPreIslandExtensionOffset,
            radiusOneFiftyFourBodySuccessMidIslandExtensionOffset,
            radiusOneFiftyFourBodySuccessPostIslandExtensionOffset,
            radiusOneSeventyFourSuccessDispatchBridgeRelayExtensionOffset,
            radiusOneSeventyThreeSuccessDispatchBridgeRelayExtensionOffset,
            radiusOneSeventyTwoSuccessDispatchBridgeRelayExtensionOffset,
            radiusOneSeventyOneSuccessDispatchBridgeRelayExtensionOffset,
            radiusOneSeventySuccessDispatchBridgeRelayExtensionOffset,
            radiusOneSixtyNineSuccessDispatchBridgeRelayExtensionOffset,
            radiusOneSixtyEightSuccessLateRelayExtensionOffset,
            radiusOneSixtySevenSuccessLateRelayExtensionOffset,
            radiusOneFiftyFiveBodySuccessPreIslandExtensionOffset,
            radiusOneFiftyFiveBodySuccessMidIslandExtensionOffset,
