        relayAllocator.Link(ellipseSuccessIslandExtensionOffset, successOffset);
        PatchBranch(code, complementModeBranchExtensionOffset, complementModeOffset);
        PatchBranch(code, modeJoinBranchExtensionOffset, pointSequenceOffset);
        relayAllocator.LinkChain(
            ellipseFallbackEarlyIslandExtensionOffset,
            ellipseFallbackMidIslandOffset,
            ellipseFallbackBridgeIslandExtensionOffset,
            ellipseFallbackLateBridgeIslandExtensionOffset,
            ellipseFallbackLateTargetIslandExtensionOffset,
            ellipseFallbackMiddleTargetIslandExtensionOffset,
            ellipseFallbackNearTargetIslandExtensionOffset,
            ellipseFallbackChainTailIslandExtensionOffset,
            ellipseFallbackChainTail2IslandExtensionOffset,
            ellipseFallbackChainTail3IslandExtensionOffset,
            ellipseFallbackChainTail4IslandExtensionOffset,
            ellipseFallbackChainTail4MidIslandExtensionOffset,
            ellipseFallbackChainTail5IslandExtensionOffset,
            ellipseFallbackChainTail5BridgeIslandExtensionOffset,
            ellipseFallbackChainTail5MidIslandExtensionOffset,
            ellipseFallbackPostThirtyFiveIslandExtensionOffset,
            ellipseFallbackPostThirtySixIslandExtensionOffset,
            ellipseFallbackPostThirtySevenIslandExtensionOffset,
            ellipseFallbackPostThirtyEightIslandExtensionOffset,
            radiusOneFortyBodyFallbackPreIslandExtensionOffset,
            radiusOneFortyBodyFallbackMidIslandExtensionOffset,
            radiusOneFortyBodyFallbackPostIslandExtensionOffset,
            radiusOneFortyOneBodyFallbackPreIslandExtensionOffset,
            radiusOneFortyOneBodyFallbackMidIslandExtensionOffset,
            radiusOneFortyOneBodyFallbackPostIslandExtensionOffset,
            radiusOneFortyTwoBodyFallbackPreIslandExtensionOffset,
            radiusOneFortyTwoBodyFallbackMidIslandExtensionOffset,
            radiusOneFortyTwoBodyFallbackPostIslandExtensionOffset,
            radiusOneFortyThreeBodyFallbackPreIslandExtensionOffset,
            radiusOneFortyThreeBodyFallbackMidIslandExtensionOffset,
            radiusOneFortyThreeBodyFallbackPostIslandExtensionOffset,
            radiusOneFortyFourBodyFallbackPreIslandExtensionOffset,
            radiusOneFortyFourBodyFallbackMidIslandExtensionOffset,
            radiusOneFortyFourBodyFallbackPostIslandExtensionOffset,
            radiusOneFortyFiveBodyFallbackPreIslandExtensionOffset,
            radiusOneFortyFiveBodyFallbackMidIslandExtensionOffset,
            radiusOneFortyFiveBodyFallbackPostIslandExtensionOffset,
            radiusOneFortySixBodyFallbackPreIslandExtensionOffset,
            radiusOneFortySixBodyFallbackMidIslandExtensionOffset,
            radiusOneFortySixBodyFallbackPostIslandExtensionOffset,
            radiusOneFortySevenBodyFallbackPreIslandExtensionOffset,
            radiusOneFortySevenBodyFallbackMidIslandExtensionOffset,
            radiusOneFortySevenBodyFallbackPostIslandExtensionOffset,
            radiusOneFortyEightBodyFallbackPreIslandExtensionOffset,
            radiusOneFortyEightBodyFallbackMidIslandExtensionOffset,
            radiusOneFortyEightBodyFallbackPostIslandExtensionOffset,
            radiusOneFortyNineBodyFallbackPreIslandExtensionOffset,
            radiusOneFortyNineBodyFallbackMidIslandExtensionOffset,
            radiusOneFortyNineBodyFallbackPostIslandExtensionOffset,
            radiusOneFiftyBodyFallbackPreIslandExtensionOffset,
            radiusOneFiftyBodyFallbackMidIslandExtensionOffset,
            radiusOneFiftyBodyFallbackPostIslandExtensionOffset,
            radiusOneFiftyOneBodyFallbackPreIslandExtensionOffset,
            radiusOneFiftyOneBodyFallbackMidIslandExtensionOffset,
            radiusOneFiftyOneBodyFallbackPostIslandExtensionOffset,
            radiusOneFiftyTwoBodyFallbackPreIslandExtensionOffset,
            radiusOneFiftyTwoBodyFallbackMidIslandExtensionOffset,
            radiusOneFiftyTwoBodyFallbackPostIslandExtensionOffset,
            radiusOneFiftyThreeBodyFallbackPreIslandExtensionOffset,
            radiusOneFiftyThreeBodyFallbackMidIslandExtensionOffset,
            radiusOneFiftyThreeBodyFallbackPostIslandExtensionOffset,
            radiusOneFiftyFourBodyFallbackPreIslandExtensionOffset,
            radiusOneFiftyFourBodyFallbackMidIslandExtensionOffset,
            radiusOneFiftyFourBodyFallbackPostIslandExtensionOffset,
            radiusOneSeventyFourFallbackDispatchBridgeRelayExtensionOffset,
            radiusOneSeventyThreeFallbackDispatchBridgeRelayExtensionOffset,
            radiusOneSeventyTwoFallbackDispatchBridgeRelayExtensionOffset,
            radiusOneSeventyOneFallbackDispatchBridgeRelayExtensionOffset,
            radiusOneSeventyFallbackDispatchBridgeRelayExtensionOffset,
            radiusOneSixtyNineFallbackDispatchBridgeRelayExtensionOffset,
            radiusOneSixtyEightFallbackLateRelayExtensionOffset,
            radiusOneSixtySevenFallbackLateRelayExtensionOffset,
            radiusOneFiftyFiveBodyFallbackPreIslandExtensionOffset,
            radiusOneFiftyFiveBodyFallbackMidIslandExtensionOffset,
            radiusOneFiftyFiveBodyFallbackPostIslandExtensionOffset,
            radiusOneThirtyNineBodyFallbackMidIslandExtensionOffset,
            ellipseFallbackPostThirtyNineIslandExtensionOffset);
        relayAllocator.Link(ellipseFallbackMidIslandExtensionOffset, ellipseFallbackTailIslandOffset);
        relayAllocator.Link(ellipseFallbackTailIslandExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
        {
            var targetOffset = Math.Abs(ellipseFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                ? ellipseFallbackMidIslandOffset
                : Math.Abs(ellipseFallbackMiddleTargetIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? ellipseFallbackMiddleTargetIslandOffset
                : Math.Abs(ellipseFallbackLateBridgeIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? ellipseFallbackLateBridgeIslandOffset
                : Math.Abs(ellipseFallbackChainTailIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? ellipseFallbackChainTailIslandOffset
                : Math.Abs(ellipseFallbackChainTail3IslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? ellipseFallbackChainTail3IslandOffset
                : Math.Abs(ellipseFallbackChainTail4IslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? ellipseFallbackChainTail4IslandOffset
                : Math.Abs(ellipseFallbackChainTail5IslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? ellipseFallbackChainTail5IslandOffset
                : Math.Abs(ellipseFallbackPostThirtyFiveIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? ellipseFallbackPostThirtyFiveIslandOffset
                : Math.Abs(radiusOneFiftyThreeBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFiftyThreeBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneFiftyFourBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFiftyFourBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneFiftyFiveBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFiftyFiveBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneFiftyOneBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFiftyOneBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneFiftyTwoBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFiftyTwoBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneFiftyBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFiftyBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneFortyNineBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFortyNineBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneFortyEightBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFortyEightBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneFortySevenBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFortySevenBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneFortySixBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFortySixBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneFortyFiveBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFortyFiveBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneFortyFourBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFortyFourBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneFortyThreeBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFortyThreeBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneFortyTwoBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFortyTwoBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneFortyOneBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFortyOneBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneFortyBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneFortyBodyFallbackMidIslandOffset
                : Math.Abs(radiusOneThirtyNineBodyFallbackMidIslandOffset - branchExtensionOffset) <= short.MaxValue
                    ? radiusOneThirtyNineBodyFallbackMidIslandOffset
                : ellipseFallbackEarlyIslandOffset;
            PatchBranch(code, branchExtensionOffset, targetOffset);
        }

        return offset;

        void AppendRadiusOneTallPointSequence(
            List<byte> target,
            int radius,
            Action<List<byte>>? onAfterInitialPoints = null,
            int? splitBeforeDelta = null,
            Action<List<byte>>? onSplit = null,
            int? secondSplitBeforeDelta = null,
            Action<List<byte>>? onSecondSplit = null)
        {
            var negativeDeltas = new ushort[radius];
            var positiveDeltas = new ushort[radius];
            Array.Fill(negativeDeltas, SubQuickOneLongD1);
            Array.Fill(positiveDeltas, AddQuickOneLongD1);
            AppendPoint(target, MoveLongD4ToD0, MoveLongD4ToD0, MoveLongD5ToD1,
                yDeltas: negativeDeltas);
            AppendPoint(target, MoveLongD4ToD0, MoveLongD4ToD0, MoveLongD5ToD1,
                yDeltas: positiveDeltas);
            onAfterInitialPoints?.Invoke(target);

            for (var delta = radius - 1; delta > 0; delta--)
            {
                if (splitBeforeDelta == delta)
                    onSplit?.Invoke(target);
                if (secondSplitBeforeDelta == delta)
                    onSecondSplit?.Invoke(target);
                var negativeRowDeltas = new ushort[delta];
                var positiveRowDeltas = new ushort[delta];
                Array.Fill(negativeRowDeltas, SubQuickOneLongD1);
                Array.Fill(positiveRowDeltas, AddQuickOneLongD1);
                AppendPoint(target, MoveLongD4ToD0, SubQuickOneLongD0, MoveLongD5ToD1,
                    yDeltas: negativeRowDeltas);
                AppendPoint(target, MoveLongD4ToD0, AddQuickOneLongD0, MoveLongD5ToD1,
                    yDeltas: negativeRowDeltas);
                AppendPoint(target, MoveLongD4ToD0, SubQuickOneLongD0, MoveLongD5ToD1,
                    yDeltas: positiveRowDeltas);
                AppendPoint(target, MoveLongD4ToD0, AddQuickOneLongD0, MoveLongD5ToD1,
                    yDeltas: positiveRowDeltas);
            }

            AppendPoint(target, MoveLongD4ToD0, SubQuickOneLongD0, MoveLongD5ToD1);
            AppendPoint(target, MoveLongD4ToD0, AddQuickOneLongD0, MoveLongD5ToD1);
        }

        void AppendPoint(
            List<byte> target,
            ushort xLoad,
            ushort xAdjustment,
            ushort yLoad,
            ushort? xAdjustment2 = null,
            ushort? xAdjustment3 = null,
            ushort? xAdjustment4 = null,
            ushort? yDelta = null,
            ushort? yDelta2 = null,
            ushort? yDelta3 = null,
            ushort? yDelta4 = null,
            ushort? yDelta5 = null,
            ushort? yDelta6 = null,
            ushort? yDelta7 = null,
            ushort? yDelta8 = null,
            ushort? yDelta9 = null,
            ushort[]? yDeltas = null)
        {
            Append(target, xLoad);
            Append(target, xAdjustment);
            if (xAdjustment2.HasValue)
                Append(target, xAdjustment2.Value);
            if (xAdjustment3.HasValue)
                Append(target, xAdjustment3.Value);
            if (xAdjustment4.HasValue)
                Append(target, xAdjustment4.Value);
            Append(target, yLoad);
            if (yDelta.HasValue)
                Append(target, yDelta.Value);
            if (yDelta2.HasValue)
                Append(target, yDelta2.Value);
            if (yDelta3.HasValue)
                Append(target, yDelta3.Value);
            if (yDelta4.HasValue)
                Append(target, yDelta4.Value);
            if (yDelta5.HasValue)
                Append(target, yDelta5.Value);
            if (yDelta6.HasValue)
                Append(target, yDelta6.Value);
            if (yDelta7.HasValue)
                Append(target, yDelta7.Value);
            if (yDelta8.HasValue)
                Append(target, yDelta8.Value);
            if (yDelta9.HasValue)
                Append(target, yDelta9.Value);
            if (yDeltas is not null)
            {
                foreach (var yDeltaValue in yDeltas)
                    Append(target, yDeltaValue);
            }

            // D0 holds X and D1 holds Y. D7 is the preserved row stride. The
            // computed byte address is A3; D0 becomes the MSB-first bit index.
            Append(target, MoveLongD0ToD2);
            Append(target, AndImmediateWordD2);
            Append(target, 7);
            Append(target, ShiftRightLongD0);
            Append(target, ShiftRightLongD0);
            Append(target, ShiftRightLongD0);
            Append(target, MultiplyUnsignedWordD7ToD1);
            Append(target, AddLongD0ToD1);
            // ADD.L to an address register does not update the CCR on a real
            // 68000. Form the candidate address in a data register, then
            // compare it against the original plane base before publishing it
            // to A3. A wrapped candidate therefore retains the provider/native
            // fallback boundary without relying on stale address-add flags.
            Append(target, MoveLongA2ToD6);
            Append(target, AddLongD1ToD6);
            Append(target, MoveLongA2ToD1);
            Append(target, CompareLongD6ToD1);
            Append(target, BranchHighWord);
            var pointWrapBranchExtensionOffset = target.Count;
            Append(target, 0);
            fallbackBranches.Add(pointWrapBranchExtensionOffset);
            Append(target, MoveAddressD6ToA3);
            Append(target, MoveQuickSevenD0);
            Append(target, SubWordD2ToD0);
            Append(target, CompareImmediateWordD3);
            Append(target, 2);
            Append(target, BranchEqualWord);
            var complementBranchExtensionOffset = target.Count;
            Append(target, 0);
            Append(target, TestLongD3);
            Append(target, BranchEqualWord);
            var clearBranchExtensionOffset = target.Count;
            Append(target, 0);
            Append(target, BitSetDynamicD0AtA3);
            Append(target, BranchAlwaysWord);
            var pointDoneFromSetBranchExtensionOffset = target.Count;
            Append(target, 0);

            var clearOffset = target.Count;
            Append(target, BitClearDynamicD0AtA3);
            Append(target, BranchAlwaysWord);
            var pointDoneFromClearBranchExtensionOffset = target.Count;
            Append(target, 0);

            var complementOffset = target.Count;
            Append(target, BitChangeDynamicD0AtA3);
            var pointDoneOffset = target.Count;

            PatchBranch(target, complementBranchExtensionOffset, complementOffset);
            PatchBranch(target, clearBranchExtensionOffset, clearOffset);
            PatchBranch(target, pointDoneFromSetBranchExtensionOffset, pointDoneOffset);
            PatchBranch(target, pointDoneFromClearBranchExtensionOffset, pointDoneOffset);
        }
    }

    private static int AppendScrollRasterNoOp(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(8);

        // A zero displacement is the documented ScrollRaster/ScrollRasterBF
        // no-op. Claim only this read-free state transition; real movement,
        // clipping, backfill, layers, and provider-owned storage stay on the
        // portable/provider owner.
        Append(code, MoveLongD0ToD7); // preserve incoming D0 on every decline
        Append(code, TestWordD0);
        Append(code, BranchNotEqualWord);
        var deltaXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaXBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchNotEqualWord);
        var deltaYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaYBranchExtensionOffset);

        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var rastPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortWrapBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var layeredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layeredBranchExtensionOffset);

        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendScrollRasterDiagonalOnePixel(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(32);

        // Bounded mixed-displacement companion: a complete eight-pixel
        // column of a two-row, one-plane standard bitmap, with both deltas
        // exactly +1 or -1.  The row copy is performed before the vacated
        // row is filled, while the horizontal bit shift is kept in the same
        // MSB-first form as the horizontal ScrollRaster arms.
        Append(code, MoveLongD0ToD7);
        Append(code, TestWordD0);
        Append(code, BranchEqualWord);
        var deltaXZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaXZeroBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var deltaYZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaYZeroBranchExtensionOffset);

        Append(code, CompareImmediateWordD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var xMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD3);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var yMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 7);
        Append(code, BranchNotEqualWord);
        var xMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMaxBranchExtensionOffset);
        Append(code, CompareImmediateWordD5);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var yMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMaxBranchExtensionOffset);

        // D3 and D5 are free after the geometry envelope.  Keep the
        // horizontal and vertical signs there while the public structures
        // are validated below.
        Append(code, CompareImmediateWordD0);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var positiveDeltaXBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var unsupportedDeltaXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedDeltaXBranchExtensionOffset);
        Append(code, MoveQuickOneD3);
        Append(code, BranchAlwaysWord);
        var negativeDeltaXToDeltaYExtensionOffset = code.Count;
        Append(code, 0);

        var positiveDeltaXOffset = code.Count;
        Append(code, MoveQuickZeroD3);
        var deltaYSelectionOffset = code.Count;
        Append(code, CompareImmediateWordD1);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var positiveDeltaYBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var unsupportedDeltaYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedDeltaYBranchExtensionOffset);
        Append(code, MoveQuickOneD5);
        Append(code, BranchAlwaysWord);
        var negativeDeltaYToValidationExtensionOffset = code.Count;
        Append(code, 0);

        var positiveDeltaYOffset = code.Count;
        Append(code, MoveQuickZeroD5);
        var validationOffset = code.Count;

        // RastPort and BitMap public envelopes.
        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var rastPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortWrapBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var layeredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layeredBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var bitmapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapWrapBranchExtensionOffset);
        Append(code, MoveAddressD0ToA0);

        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD6);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var bytesPerRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bytesPerRowBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD6);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var bitmapFlagsReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD6);
        Append(code, 0x08);
        Append(code, BranchNotEqualWord);
        var bitmapFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapFlagsBranchExtensionOffset);
        var bitmapFlagsReadyOffset = code.Count;
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE);
        Append(code, BranchHighWord);
        var planeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeWrapBranchExtensionOffset);
        Append(code, MoveAddressD6ToA3);

        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundPenZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var backgroundPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(backgroundPenBranchExtensionOffset);

        var backgroundPenOneOffset = code.Count;
        Append(code, MoveImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, MoveWordD0ToD4);
        Append(code, BranchAlwaysWord);
        var backgroundReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var backgroundPenZeroOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToD4);
        var readyOffset = code.Count;
        Append(code, MoveQuickTwoD6);
        Append(code, MoveLongD6ToD2); // exact two-byte row stride

        // Select one of the four direction-specific operation blocks.  The
        // blocks are intentionally separate so every pointer walk remains
        // visible to the relocation and signed-branch audits.
        Append(code, TestWordD5);
        Append(code, BranchEqualWord);
        var positiveDeltaYDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, TestWordD3);
        Append(code, BranchEqualWord);
        var negativeDeltaYPositiveXBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var negativeDeltaYNegativeXBranchExtensionOffset = code.Count;
        Append(code, 0);

        var positiveDeltaYDispatchOffset = code.Count;
        Append(code, TestWordD3);
        Append(code, BranchEqualWord);
        var positiveDeltaYPositiveXBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var positiveDeltaYNegativeXBranchExtensionOffset = code.Count;
        Append(code, 0);

        var positiveDeltaYPositiveXOffset = AppendScrollRasterDiagonalOperation(
            code,
            positiveX: true,
            positiveY: true);
        var positiveDeltaYNegativeXOffset = AppendScrollRasterDiagonalOperation(
            code,
            positiveX: false,
            positiveY: true);
        var negativeDeltaYPositiveXOffset = AppendScrollRasterDiagonalOperation(
            code,
            positiveX: true,
            positiveY: false);
        var negativeDeltaYNegativeXOffset = AppendScrollRasterDiagonalOperation(
            code,
            positiveX: false,
            positiveY: false);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, deltaXZeroBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, deltaYZeroBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, positiveDeltaXBranchExtensionOffset, positiveDeltaXOffset);
        PatchBranch(code, negativeDeltaXToDeltaYExtensionOffset, deltaYSelectionOffset);
        PatchBranch(code, positiveDeltaYBranchExtensionOffset, positiveDeltaYOffset);
        PatchBranch(code, negativeDeltaYToValidationExtensionOffset, validationOffset);
        PatchBranch(code, bitmapFlagsReadyBranchExtensionOffset, bitmapFlagsReadyOffset);
        PatchBranch(code, backgroundPenZeroBranchExtensionOffset, backgroundPenZeroOffset);
        PatchBranch(code, backgroundReadyBranchExtensionOffset, readyOffset);
        PatchBranch(code, positiveDeltaYDispatchBranchExtensionOffset, positiveDeltaYDispatchOffset);
        PatchBranch(code, negativeDeltaYPositiveXBranchExtensionOffset, negativeDeltaYPositiveXOffset);
        PatchBranch(code, negativeDeltaYNegativeXBranchExtensionOffset, negativeDeltaYNegativeXOffset);
        PatchBranch(code, positiveDeltaYPositiveXBranchExtensionOffset, positiveDeltaYPositiveXOffset);
        PatchBranch(code, positiveDeltaYNegativeXBranchExtensionOffset, positiveDeltaYNegativeXOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendScrollRasterDiagonalOperation(
        List<byte> code,
        bool positiveX,
        bool positiveY)
    {
        var offset = code.Count;

        if (positiveY)
        {
            Append(code, MoveAddressA3ToA4);
            Append(code, MoveAddressA4ToA6);
            Append(code, MoveAddressA3ToA5);
            Append(code, AddLongD2ToA5);
            // Keep the fill pointer in A4; A0 is the byte-write scratch
            // register used by the shifted-copy helper.
        }
        else
        {
            Append(code, MoveAddressA3ToA4);
            Append(code, MoveLongD2ToD3);
            Append(code, AddLongD3ToA4);
            Append(code, MoveAddressA4ToA6);
            // A4 remains the vacated row-one fill pointer.
            Append(code, MoveAddressA3ToA5);
        }

        for (var index = 0; index < 1; index++)
        {
            var shiftedDoneBranchExtensionOffset =
                AppendScrollRasterDiagonalShiftByte(code, positiveX);
            PatchBranch(code, shiftedDoneBranchExtensionOffset, code.Count);
            if (index == 0)
            {
                Append(code, AddQuickOneLongA6);
                Append(code, MoveAddressA5ToA3);
                Append(code, AddQuickOneLongA3);
                Append(code, MoveAddressA3ToA5);
            }
        }

        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveByteD0ToA0);
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        return offset;
    }

    private static int AppendScrollRasterDiagonalShiftByte(
        List<byte> code,
        bool positiveX)
    {
        Append(code, MoveByteA6IndirectToD6);
        Append(code, AndImmediateLongD6);
        Append(code, 0x0000);
        Append(code, 0x00FF);
        Append(code, MoveLongD6ToD5);
        Append(code, positiveX ? ShiftLeftLongD5 : ShiftRightLongD5);
        Append(code, AndImmediateWordD5);
        Append(code, positiveX ? (ushort)0x00FE : (ushort)0x007F);
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD5ToD0);
        Append(code, OrImmediateWordD0);
        Append(code, positiveX ? (ushort)1 : (ushort)0x0080);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveByteD0ToA0);
        Append(code, BranchAlwaysWord);
        var shiftedDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        var backgroundZeroOffset = code.Count;
        Append(code, MoveLongD5ToD0);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveByteD0ToA0);
        PatchBranch(code, backgroundZeroBranchExtensionOffset, backgroundZeroOffset);
        return shiftedDoneBranchExtensionOffset;
    }

    private static int AppendScrollRasterClippedOnePixel(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(24);

        // Exact clipped horizontal arms: the six-pixel rectangle x=1..6, the
        // sixteen-pixel rectangle x=1..14, the four-byte thirty-pixel
        // rectangle x=1..30, and the eight-byte sixty-two-pixel rectangle
        // x=1..62 in a single row. The outside bits and any stride bytes
        // beyond the admitted span are preserved, while the vacated interior
        // edge receives the binary background pen.
        Append(code, MoveLongD0ToD7);
        Append(code, TestWordD0);
        Append(code, BranchEqualWord);
        var deltaXZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaXZeroBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchNotEqualWord);
        var deltaYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaYBranchExtensionOffset);

        Append(code, CompareImmediateWordD2);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var xMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD3);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var yMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 62);
        Append(code, BranchEqualWord);
        var xMaxSixtyTwoReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 6);
        Append(code, BranchEqualWord);
        var xMaxSixReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 14);
        Append(code, BranchEqualWord);
        var xMaxFourteenReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 30);
        Append(code, BranchNotEqualWord);
        var xMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMaxBranchExtensionOffset);
        var xMaxSixReadyOffset = code.Count;
        Append(code, CompareImmediateWordD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var yMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMaxBranchExtensionOffset);

        // Retain the admitted xMax selector in D1 before D4 is reused for
        // the normalized background pen during the public-envelope checks.
        Append(code, MoveLongD4ToD1);

        Append(code, CompareImmediateWordD0);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var positiveDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var unsupportedDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedDirectionBranchExtensionOffset);
        Append(code, MoveQuickOneD3);
        Append(code, BranchAlwaysWord);
        var negativeDirectionToValidationBranchExtensionOffset = code.Count;
        Append(code, 0);

        var positiveDirectionOffset = code.Count;
        Append(code, MoveQuickZeroD3);
        var validationOffset = code.Count;

        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C);
        Append(code, BranchHighWord);
        var rastPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortWrapBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var layeredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layeredBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var bitmapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapWrapBranchExtensionOffset);
        Append(code, MoveAddressD0ToA0);

        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD6);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var bytesPerRowTwoReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 4);
        Append(code, BranchEqualWord);
        var bytesPerRowFourReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD6);
        Append(code, 8);
        Append(code, BranchNotEqualWord);
        var bytesPerRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bytesPerRowBranchExtensionOffset);
        var bytesPerRowReadyOffset = code.Count;
        Append(code, MoveWordD6ToD5);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var bitmapFlagsReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD6);
        Append(code, 0x08);
        Append(code, BranchNotEqualWord);
        var bitmapFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapFlagsBranchExtensionOffset);
        var bitmapFlagsReadyOffset = code.Count;
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE);
        Append(code, BranchHighWord);
        var planeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeWrapBranchExtensionOffset);
        Append(code, MoveAddressD6ToA3);

        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundPenZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var backgroundPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(backgroundPenBranchExtensionOffset);
        var backgroundPenOneOffset = code.Count;
        Append(code, MoveImmediateWordD0);
        Append(code, 1);
        Append(code, MoveWordD0ToD4);
        Append(code, BranchAlwaysWord);
        var backgroundReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var backgroundPenZeroOffset = code.Count;
        Append(code, MoveQuickZeroD4);
        var readyOffset = code.Count;

        Append(code, CompareImmediateWordD1);
        Append(code, 62);
        Append(code, BranchEqualWord);
        var eightDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 30);
        Append(code, BranchEqualWord);
        var quadDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 14);
        Append(code, BranchEqualWord);
        var wideDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        var sixDispatchOffset = code.Count;
        Append(code, TestWordD3);
        Append(code, BranchEqualWord);
        var positiveDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var negativeDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        var positiveOperationOffset = AppendScrollRasterClippedOperation(
            code,
            positiveX: true);
        var negativeOperationOffset = AppendScrollRasterClippedOperation(
            code,
            positiveX: false);
        var wideDispatchOffset = code.Count;
        Append(code, TestWordD3);
        Append(code, BranchEqualWord);
        var widePositiveDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var wideNegativeDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        var widePositiveOperationOffset = AppendScrollRasterClippedWideOperation(
            code,
            positiveX: true);
        var wideNegativeOperationOffset = AppendScrollRasterClippedWideOperation(
            code,
            positiveX: false);
        var quadDispatchOffset = code.Count;
        Append(code, CompareImmediateWordD5);
        Append(code, 4);
        Append(code, BranchCarryWord);
        var quadRowStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(quadRowStrideBranchExtensionOffset);
        Append(code, MoveLongA3ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var quadPlaneWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(quadPlaneWrapBranchExtensionOffset);
        Append(code, TestWordD3);
        Append(code, BranchEqualWord);
        var quadPositiveDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var quadNegativeDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        var quadPositiveOperationOffset = AppendScrollRasterClippedQuadOperation(
            code,
            positiveX: true);
        var quadNegativeOperationOffset = AppendScrollRasterClippedQuadOperation(
            code,
            positiveX: false);

        var eightDispatchOffset = code.Count;
        Append(code, CompareImmediateWordD5);
        Append(code, 8);
        Append(code, BranchCarryWord);
        var eightRowStrideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(eightRowStrideBranchExtensionOffset);
        Append(code, MoveLongA3ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8);
        Append(code, BranchHighWord);
        var eightPlaneWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(eightPlaneWrapBranchExtensionOffset);
        Append(code, TestWordD3);
        Append(code, BranchEqualWord);
        var eightPositiveDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var eightNegativeDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        var eightPositiveOperationOffset = AppendScrollRasterClippedEightOperation(
            code,
            positiveX: true);
        var eightNegativeOperationOffset = AppendScrollRasterClippedEightOperation(
            code,
            positiveX: false);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, positiveDirectionBranchExtensionOffset, positiveDirectionOffset);
        PatchBranch(code, negativeDirectionToValidationBranchExtensionOffset, validationOffset);
        PatchBranch(code, xMaxSixtyTwoReadyBranchExtensionOffset, xMaxSixReadyOffset);
        PatchBranch(code, bytesPerRowTwoReadyBranchExtensionOffset, bytesPerRowReadyOffset);
        PatchBranch(code, bytesPerRowFourReadyBranchExtensionOffset, bytesPerRowReadyOffset);
        PatchBranch(code, xMaxFourteenReadyBranchExtensionOffset, xMaxSixReadyOffset);
        PatchBranch(code, xMaxSixReadyBranchExtensionOffset, xMaxSixReadyOffset);
        PatchBranch(code, bitmapFlagsReadyBranchExtensionOffset, bitmapFlagsReadyOffset);
        PatchBranch(code, backgroundPenZeroBranchExtensionOffset, backgroundPenZeroOffset);
        PatchBranch(code, backgroundReadyBranchExtensionOffset, readyOffset);
        PatchBranch(code, positiveDispatchBranchExtensionOffset, positiveOperationOffset);
        PatchBranch(code, negativeDispatchBranchExtensionOffset, negativeOperationOffset);
        PatchBranch(code, wideDispatchBranchExtensionOffset, wideDispatchOffset);
        PatchBranch(code, widePositiveDispatchBranchExtensionOffset, widePositiveOperationOffset);
        PatchBranch(code, wideNegativeDispatchBranchExtensionOffset, wideNegativeOperationOffset);
        PatchBranch(code, quadDispatchBranchExtensionOffset, quadDispatchOffset);
        PatchBranch(code, quadPositiveDispatchBranchExtensionOffset, quadPositiveOperationOffset);
        PatchBranch(code, quadNegativeDispatchBranchExtensionOffset, quadNegativeOperationOffset);
        PatchBranch(code, eightDispatchBranchExtensionOffset, eightDispatchOffset);
        PatchBranch(code, eightPositiveDispatchBranchExtensionOffset, eightPositiveOperationOffset);
        PatchBranch(code, eightNegativeDispatchBranchExtensionOffset, eightNegativeOperationOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendScrollRasterClippedWideOperation(
        List<byte> code,
        bool positiveX)
    {
        var offset = code.Count;
        Append(code, MoveAddressA3ToA5);
        Append(code, AddLongD2ToA5);

        if (positiveX)
        {
            // Form byte zero from the sixteen-bit left shift, retaining x=0
            // and carrying the old byte-one MSB into the interior boundary.
            Append(code, MoveByteA3IndirectToD6);
            Append(code, MoveLongD6ToD5);
            Append(code, MoveLongD5ToD0);
            Append(code, AndImmediateWordD0);
            Append(code, 0x0080);
            Append(code, MoveLongD0ToD1);
            Append(code, MoveLongD5ToD0);
            Append(code, ShiftLeftLongD0);
            Append(code, AndImmediateWordD0);
            Append(code, 0x007F);
            Append(code, MoveLongD0ToD5);
            Append(code, MoveByteA5IndirectToD6);
            for (var index = 0; index < 7; index++)
                Append(code, ShiftRightLongD6);
            Append(code, OrLongD6ToD5);
            Append(code, MoveLongD1ToD0);
            Append(code, OrLongD0ToD5);
            Append(code, CompareImmediateByteD4);
            Append(code, 0);
            Append(code, BranchEqualWord);
            var backgroundZeroBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveLongD5ToD0);
            Append(code, OrImmediateWordD0);
            Append(code, 0x0040);
            Append(code, MoveLongD0ToD5);
            var backgroundZeroOffset = code.Count;
            PatchBranch(code, backgroundZeroBranchExtensionOffset, backgroundZeroOffset);
            Append(code, MoveAddressA3ToA0);
            Append(code, MoveLongD5ToD0);
            Append(code, MoveByteD0ToA0);

            // Byte one is the low half of the shifted source word. Its x=15
            // edge bit is retained; the vacated x=14 edge is in byte zero.
            Append(code, MoveByteA5IndirectToD6);
            Append(code, MoveLongD6ToD0);
            Append(code, AndImmediateWordD0);
            Append(code, 0x0001);
            Append(code, MoveLongD0ToD1);
            Append(code, MoveLongD6ToD0);
            Append(code, ShiftLeftLongD0);
            Append(code, AndImmediateWordD0);
            Append(code, 0x00FE);
            Append(code, MoveLongD0ToD5);
            Append(code, MoveLongD1ToD0);
            Append(code, OrLongD0ToD5);
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveLongD5ToD0);
            Append(code, MoveByteD0ToA0);
        }
        else
        {
            // Byte zero is the high half of the shifted source word. Only
            // x=0 is outside this byte's admitted interior.
            Append(code, MoveByteA3IndirectToD6);
            Append(code, MoveLongD6ToD5);
            Append(code, MoveLongD5ToD0);
            Append(code, AndImmediateWordD0);
            Append(code, 0x0080);
            Append(code, MoveLongD0ToD1);
            Append(code, MoveLongD5ToD0);
            Append(code, ShiftRightLongD0);
            Append(code, AndImmediateWordD0);
            Append(code, 0x007F);
            Append(code, MoveLongD0ToD5);
            Append(code, AndImmediateWordD6);
            Append(code, 0x0001);
            for (var index = 0; index < 7; index++)
                Append(code, ShiftLeftLongD6);
            Append(code, MoveLongD6ToD2);
            Append(code, MoveLongD2ToD0);
            Append(code, OrLongD0ToD5);
            Append(code, MoveAddressA3ToA0);
            Append(code, MoveLongD5ToD0);
            Append(code, MoveByteD0ToA0);

            // Byte one receives the old byte-zero LSB as its MSB. BPen fills
            // the vacated x=14 interior bit (bit 1) when requested.
            Append(code, MoveByteA5IndirectToD6);
            Append(code, MoveLongD6ToD5);
            Append(code, MoveLongD5ToD0);
            Append(code, AndImmediateWordD0);
            Append(code, 0x0001);
            Append(code, MoveLongD0ToD1);
            Append(code, MoveLongD5ToD0);
            Append(code, ShiftRightLongD0);
            Append(code, AndImmediateWordD0);
            Append(code, 0x00FE);
            Append(code, MoveLongD0ToD5);
            Append(code, MoveLongD2ToD0);
            Append(code, OrLongD0ToD5);
            Append(code, MoveLongD1ToD0);
            Append(code, OrLongD0ToD5);
            Append(code, MoveLongD6ToD0);
            Append(code, AndImmediateWordD0);
            Append(code, 0x0001);
            Append(code, OrLongD0ToD5);
            Append(code, CompareImmediateByteD4);
            Append(code, 0);
            Append(code, BranchEqualWord);
            var backgroundZeroBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveLongD5ToD0);
            Append(code, OrImmediateWordD0);
            Append(code, 0x0002);
            Append(code, MoveLongD0ToD5);
            var backgroundZeroOffset = code.Count;
            PatchBranch(code, backgroundZeroBranchExtensionOffset, backgroundZeroOffset);
            Append(code, MoveAddressA5ToA0);
            Append(code, MoveLongD5ToD0);
            Append(code, MoveByteD0ToA0);
        }

        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        return offset;
    }

    private static int AppendScrollRasterClippedEightOperation(
        List<byte> code,
        bool positiveX)
    {
        var offset = code.Count;

        // The x=1..62 form spans two complete longs. Keep both source longs
        // live while carrying the MSB across the long boundary, preserving
        // x=0 and x=63 and filling the vacated interior edge from BPen.
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0PostIncrementToD0);
        Append(code, MoveLongD0ToD5);
        Append(code, MoveLongA0PostIncrementToD0);
        Append(code, MoveLongD0ToD6);

        if (positiveX)
        {
            Append(code, MoveLongD5ToD0);
            Append(code, ShiftLeftLongD0);
            Append(code, AndImmediateLongD0);
            Append(code, 0x7FFF);
            Append(code, 0xFFFF);
            Append(code, MoveLongD6ToD7);
            for (var index = 0; index < 31; index++)
                Append(code, ShiftRightLongD7);
            Append(code, OrLongD7ToD0);
            Append(code, MoveLongD5ToD7);
            Append(code, AndImmediateLongD7);
            Append(code, 0x8000);
            Append(code, 0x0000);
            Append(code, OrLongD7ToD0);

            Append(code, MoveLongD6ToD1);
            Append(code, ShiftLeftLongD1);
            Append(code, AndImmediateLongD1);
            Append(code, 0xFFFF);
            Append(code, 0xFFFE);
            Append(code, MoveLongD6ToD7);
            Append(code, AndImmediateLongD7);
            Append(code, 0x0000);
            Append(code, 0x0001);
            Append(code, OrLongD7ToD1);

            Append(code, CompareImmediateByteD4);
            Append(code, 0);
            Append(code, BranchEqualWord);
            var backgroundZeroBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveLongImmediateD7);
            Append(code, 0x4000);
            Append(code, 0x0000);
            Append(code, OrLongD7ToD0);
            var backgroundZeroOffset = code.Count;
            PatchBranch(code, backgroundZeroBranchExtensionOffset, backgroundZeroOffset);
        }
        else
        {
            Append(code, MoveLongD6ToD1);
            Append(code, ShiftRightLongD1);
            Append(code, AndImmediateLongD1);
            Append(code, 0xFFFF);
            Append(code, 0xFFFE);
            Append(code, MoveLongD5ToD7);
            for (var index = 0; index < 31; index++)
                Append(code, ShiftLeftLongD7);
            Append(code, OrLongD7ToD1);
            Append(code, MoveLongD6ToD7);
            Append(code, AndImmediateLongD7);
            Append(code, 0x0000);
            Append(code, 0x0001);
            Append(code, OrLongD7ToD1);

            Append(code, MoveLongD5ToD0);
            Append(code, ShiftRightLongD0);
            Append(code, AndImmediateLongD0);
            Append(code, 0x7FFF);
            Append(code, 0xFFFF);
            Append(code, MoveLongD5ToD7);
            Append(code, AndImmediateLongD7);
            Append(code, 0x8000);
            Append(code, 0x0000);
            Append(code, OrLongD7ToD0);

            Append(code, CompareImmediateByteD4);
            Append(code, 0);
            Append(code, BranchEqualWord);
            var backgroundZeroBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveLongImmediateD7);
            Append(code, 0x0000);
            Append(code, 0x0002);
            Append(code, OrLongD7ToD1);
            var backgroundZeroOffset = code.Count;
            PatchBranch(code, backgroundZeroBranchExtensionOffset, backgroundZeroOffset);
        }

        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD1ToA0PostIncrement);
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        return offset;
    }

    private static int AppendScrollRasterClippedQuadOperation(
        List<byte> code,
        bool positiveX)
    {
        var offset = code.Count;

        // The x=1..30 form spans one complete four-byte row.  A single long
        // snapshot keeps the source stable while the MSB-first shift is
        // assembled, preserving the two outside pixels (x=0 and x=31) and
        // filling the vacated interior edge from BPen.
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0PostIncrementToD0);
        Append(code, MoveLongD0ToD5);
        Append(code, MoveLongD5ToD6);
        Append(code, MoveLongD5ToD0);
        Append(code, positiveX ? ShiftLeftLongD0 : ShiftRightLongD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0x7FFF);
        Append(code, 0xFFFE);
        Append(code, MoveLongD0ToD5);

        Append(code, MoveLongD6ToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0x8000);
        Append(code, 0x0001);
        Append(code, OrLongD0ToD5);

        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongImmediateD0);
        if (positiveX)
        {
            Append(code, 0x4000);
            Append(code, 0x0000);
        }
        else
        {
            Append(code, 0x0000);
            Append(code, 0x0002);
        }
        Append(code, OrLongD0ToD5);
        var backgroundZeroOffset = code.Count;
        PatchBranch(code, backgroundZeroBranchExtensionOffset, backgroundZeroOffset);

        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        return offset;
    }

    private static int AppendScrollRasterClippedOperation(
        List<byte> code,
        bool positiveX)
    {
        var offset = code.Count;
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveByteA3IndirectToD6);
        Append(code, AndImmediateLongD6);
        Append(code, 0x0000);
        Append(code, 0x00FF);
        Append(code, MoveLongD6ToD5);
        Append(code, AndImmediateWordD5);
        Append(code, 0x0081); // preserve x=0 and x=7
        Append(code, MoveLongD6ToD0);
        Append(code, positiveX ? ShiftLeftLongD0 : ShiftRightLongD0);
        Append(code, AndImmediateWordD0);
        Append(code, positiveX ? (ushort)0x003E : (ushort)0x007C);
        Append(code, OrLongD0ToD5);
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD5ToD0);
        Append(code, OrImmediateWordD0);
        Append(code, positiveX ? (ushort)0x0040 : (ushort)0x0002);
        Append(code, MoveByteD0ToA0);
        Append(code, BranchAlwaysWord);
        var operationDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        var backgroundZeroOffset = code.Count;
        Append(code, MoveLongD5ToD0);
        Append(code, MoveByteD0ToA0);
        var successOffset = code.Count;
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, backgroundZeroBranchExtensionOffset, backgroundZeroOffset);
        PatchBranch(code, operationDoneBranchExtensionOffset, successOffset);
        return offset;
    }

    private static int AppendScrollRasterClippedVerticalQuad(
        List<byte> code,
        int fallbackEntryOffset,
        bool wide = false)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(32);

        // Exact clipped vertical arm for a thirty- or sixty-two-pixel
        // interior in a two-row, four- or eight-byte-stride standard-planar
        // rectangle.  Long
        // snapshots keep each source row stable while the two outside pixels
        // (x=0 and x=31) remain caller-owned.
        Append(code, MoveLongD0ToD7);
        Append(code, TestWordD0);
        Append(code, BranchNotEqualWord);
        var deltaXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaXBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var deltaYZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaYZeroBranchExtensionOffset);
        Append(code, CompareImmediateWordD2);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var xMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD3);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var yMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, wide ? (ushort)62 : (ushort)30);
        Append(code, BranchNotEqualWord);
        var xMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMaxBranchExtensionOffset);
        Append(code, CompareImmediateWordD5);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var yMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMaxBranchExtensionOffset);

        Append(code, CompareImmediateWordD1);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var positiveDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var unsupportedDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedDirectionBranchExtensionOffset);
        Append(code, MoveQuickOneD5);
        Append(code, BranchAlwaysWord);
        var negativeDirectionToValidationBranchExtensionOffset = code.Count;
        Append(code, 0);
        var positiveDirectionOffset = code.Count;
        Append(code, MoveQuickZeroD5);
        var validationOffset = code.Count;

        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C);
        Append(code, BranchHighWord);
        var rastPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortWrapBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var layeredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layeredBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var bitmapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapWrapBranchExtensionOffset);
        Append(code, MoveAddressD0ToA0);

        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD6);
        Append(code, wide ? (ushort)8 : (ushort)4);
        Append(code, BranchNotEqualWord);
        var bytesPerRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bytesPerRowBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD6);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var bitmapFlagsReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD6);
        Append(code, 0x08);
        Append(code, BranchNotEqualWord);
        var bitmapFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapFlagsBranchExtensionOffset);
        var bitmapFlagsReadyOffset = code.Count;
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, wide ? (ushort)0xFFF0 : (ushort)0xFFF8);
        Append(code, BranchHighWord);
        var planeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeWrapBranchExtensionOffset);
        Append(code, MoveAddressD6ToA3);

        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundPenZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var backgroundPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(backgroundPenBranchExtensionOffset);

        var backgroundPenOneOffset = code.Count;
        Append(code, MoveImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, MoveWordD0ToD4);
        Append(code, BranchAlwaysWord);
        var backgroundReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var backgroundPenZeroOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToD4);
        var readyOffset = code.Count;
        Append(code, wide ? MoveQuickEightD6 : MoveQuickFourD6);
        Append(code, MoveLongD6ToD2);

        Append(code, TestWordD5);
        Append(code, BranchNotEqualWord);
        var negativeOperationBranchExtensionOffset = code.Count;
        Append(code, 0);
        var positiveOperationOffset = wide
            ? AppendScrollRasterClippedVerticalEightOperation(code, positiveY: true)
            : AppendScrollRasterClippedVerticalQuadOperation(code, positiveY: true);
        var negativeOperationOffset = wide
            ? AppendScrollRasterClippedVerticalEightOperation(code, positiveY: false)
            : AppendScrollRasterClippedVerticalQuadOperation(code, positiveY: false);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, positiveDirectionBranchExtensionOffset, positiveDirectionOffset);
        PatchBranch(code, negativeDirectionToValidationBranchExtensionOffset, validationOffset);
        PatchBranch(code, bitmapFlagsReadyBranchExtensionOffset, bitmapFlagsReadyOffset);
        PatchBranch(code, backgroundPenZeroBranchExtensionOffset, backgroundPenZeroOffset);
        PatchBranch(code, backgroundReadyBranchExtensionOffset, readyOffset);
        PatchBranch(code, negativeOperationBranchExtensionOffset, negativeOperationOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendScrollRasterClippedVerticalQuadOperation(
        List<byte> code,
        bool positiveY)
    {
        var offset = code.Count;
        if (positiveY)
        {
            Append(code, MoveAddressA3ToA4);
            Append(code, MoveAddressA4ToA6);
            Append(code, MoveAddressA3ToA5);
            Append(code, AddLongD2ToA5);
            Append(code, MoveAddressA5ToA3);
        }
        else
        {
            Append(code, MoveAddressA3ToA4);
            Append(code, MoveLongD2ToD3);
            Append(code, AddLongD3ToA4);
            Append(code, MoveAddressA4ToA6);
        }

        // Copy the source row's x=1..30 interior into the destination while
        // retaining the destination's x=0/x=31 pixels.
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongA0PostIncrementToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0x7FFF);
        Append(code, 0xFFFE);
        Append(code, MoveLongD0ToD5);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0PostIncrementToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0x8000);
        Append(code, 0x0001);
        Append(code, OrLongD0ToD5);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongD0ToA0PostIncrement);

        // Fill the vacated row's interior from BPen, preserving its outside
        // pixels.  BPen is constrained by the entry validator to 0 or 1.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0PostIncrementToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0x8000);
        Append(code, 0x0001);
        Append(code, MoveLongD0ToD5);
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongImmediateD0);
        Append(code, 0x7FFF);
        Append(code, 0xFFFE);
        Append(code, OrLongD0ToD5);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, BranchAlwaysWord);
        var operationDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        var backgroundZeroOffset = code.Count;
        Append(code, MoveLongD5ToD0);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongD0ToA0PostIncrement);
        var successOffset = code.Count;
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, backgroundZeroBranchExtensionOffset, backgroundZeroOffset);
        PatchBranch(code, operationDoneBranchExtensionOffset, successOffset);
        return offset;
    }

    private static int AppendScrollRasterClippedVerticalEightOperation(
        List<byte> code,
        bool positiveY)
    {
        var offset = code.Count;
        if (positiveY)
        {
            Append(code, MoveAddressA3ToA4);
            Append(code, MoveAddressA4ToA6);
            Append(code, MoveAddressA3ToA5);
            Append(code, AddLongD2ToA5);
            Append(code, MoveAddressA5ToA3);
        }
        else
        {
            Append(code, MoveAddressA3ToA4);
            Append(code, MoveLongD2ToD3);
            Append(code, AddLongD3ToA4);
            Append(code, MoveAddressA4ToA6);
        }

        // Copy both longs from the source row to the destination row. The
        // high long preserves x=0 and the low long preserves x=63; every
        // other bit is replaced by the source row's interior.
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveLongA0PostIncrementToD0);
        Append(code, MoveLongA0PostIncrementToD1);
        Append(code, AndImmediateLongD0);
        Append(code, 0x7FFF);
        Append(code, 0xFFFF);
        Append(code, MoveLongD0ToD5);
        Append(code, AndImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE);
        Append(code, MoveLongD1ToD6);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0PostIncrementToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0x8000);
        Append(code, 0x0000);
        Append(code, OrLongD0ToD5);
        Append(code, MoveLongA0PostIncrementToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0x0000);
        Append(code, 0x0001);
        Append(code, MoveLongD0ToD7);
        Append(code, OrLongD7ToD6);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);

        // Fill the vacated row from BPen while retaining its x=0/x=63
        // outside pixels. BPen is constrained to zero or one by validation.
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongA0PostIncrementToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0x8000);
        Append(code, 0x0000);
        Append(code, MoveLongD0ToD5);
        Append(code, MoveLongA0PostIncrementToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0x0000);
        Append(code, 0x0001);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var fillHighZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongImmediateD0);
        Append(code, 0x7FFF);
        Append(code, 0xFFFF);
        Append(code, OrLongD0ToD5);
        Append(code, MoveLongImmediateD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE);
        Append(code, MoveLongD0ToD7);
        Append(code, OrLongD7ToD6);
        var fillHighZeroOffset = code.Count;
        PatchBranch(code, fillHighZeroBranchExtensionOffset, fillHighZeroOffset);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveLongD0ToA0PostIncrement);

        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        return offset;
    }

    private static int AppendScrollRasterClippedVerticalTwoByte(
        List<byte> code,
        int fallbackEntryOffset,
        int quadEntryOffset,
        int wideEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(32);

        // Exact clipped vertical arm for a sixteen-pixel interior: x=1..14
        // in a two-row, two-byte-stride standard-planar rectangle.  Byte zero
        // preserves x=0, byte one preserves x=15; only the six/seven interior
        // bits in each byte are copied or filled.
        Append(code, MoveLongD0ToD7);
        Append(code, TestWordD0);
        Append(code, BranchNotEqualWord);
        var deltaXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaXBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var deltaYZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaYZeroBranchExtensionOffset);
        Append(code, CompareImmediateWordD2);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var xMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD3);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var yMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 14);
        Append(code, BranchEqualWord);
        var xMaxFourteenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 62);
        Append(code, BranchEqualWord);
        var xMaxSixtyTwoBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 30);
        Append(code, BranchEqualWord);
        var xMaxThirtyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var xMaxUnsupportedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMaxUnsupportedBranchExtensionOffset);
        var xMaxFourteenOffset = code.Count;
        Append(code, CompareImmediateWordD5);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var yMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMaxBranchExtensionOffset);

        Append(code, CompareImmediateWordD1);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var positiveDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var unsupportedDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedDirectionBranchExtensionOffset);
        Append(code, MoveQuickOneD5);
        Append(code, BranchAlwaysWord);
        var negativeDirectionToValidationBranchExtensionOffset = code.Count;
        Append(code, 0);
        var positiveDirectionOffset = code.Count;
        Append(code, MoveQuickZeroD5);
        var validationOffset = code.Count;

        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C);
        Append(code, BranchHighWord);
        var rastPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortWrapBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var layeredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layeredBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var bitmapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapWrapBranchExtensionOffset);
        Append(code, MoveAddressD0ToA0);

        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD6);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var bytesPerRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bytesPerRowBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD6);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var bitmapFlagsReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD6);
        Append(code, 0x08);
        Append(code, BranchNotEqualWord);
        var bitmapFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapFlagsBranchExtensionOffset);
        var bitmapFlagsReadyOffset = code.Count;
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var planeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeWrapBranchExtensionOffset);
        Append(code, MoveAddressD6ToA3);

        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundPenZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var backgroundPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(backgroundPenBranchExtensionOffset);

        var backgroundPenOneOffset = code.Count;
        Append(code, MoveImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, MoveWordD0ToD4);
        Append(code, BranchAlwaysWord);
        var backgroundReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var backgroundPenZeroOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToD4);
        var readyOffset = code.Count;
        Append(code, MoveQuickTwoD6);
        Append(code, MoveLongD6ToD2);

        Append(code, TestWordD5);
        Append(code, BranchNotEqualWord);
        var negativeOperationBranchExtensionOffset = code.Count;
        Append(code, 0);
        var positiveOperationOffset = AppendScrollRasterClippedVerticalTwoByteOperation(
            code,
            positiveY: true);
        var negativeOperationOffset = AppendScrollRasterClippedVerticalTwoByteOperation(
            code,
            positiveY: false);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, positiveDirectionBranchExtensionOffset, positiveDirectionOffset);
        PatchBranch(code, negativeDirectionToValidationBranchExtensionOffset, validationOffset);
        PatchBranch(code, xMaxFourteenBranchExtensionOffset, xMaxFourteenOffset);
        PatchBranch(code, xMaxSixtyTwoBranchExtensionOffset, wideEntryOffset);
        PatchBranch(code, xMaxThirtyBranchExtensionOffset, quadEntryOffset);
        PatchBranch(code, bitmapFlagsReadyBranchExtensionOffset, bitmapFlagsReadyOffset);
        PatchBranch(code, backgroundPenZeroBranchExtensionOffset, backgroundPenZeroOffset);
        PatchBranch(code, backgroundReadyBranchExtensionOffset, readyOffset);
        PatchBranch(code, negativeOperationBranchExtensionOffset, negativeOperationOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendScrollRasterClippedVerticalTwoByteOperation(
        List<byte> code,
        bool positiveY)
    {
        var offset = code.Count;
        if (positiveY)
        {
            Append(code, MoveAddressA3ToA4);
            Append(code, MoveAddressA4ToA6);
            Append(code, MoveAddressA3ToA5);
            Append(code, AddLongD2ToA5);
            Append(code, MoveAddressA5ToA3);
        }
        else
        {
            Append(code, MoveAddressA3ToA4);
            Append(code, MoveLongD2ToD3);
            Append(code, AddLongD3ToA4);
            Append(code, MoveAddressA4ToA6);
        }

        AppendClippedVerticalByte(code, 0x7F, 0x80);
        Append(code, AddQuickOneLongA3);
        Append(code, AddQuickOneLongA4);
        Append(code, AddQuickOneLongA6);
        AppendClippedVerticalByte(code, 0xFE, 0x01);

        // The byte-copy stride leaves A4 one byte past the row origin.  Walk
        // it back before filling the first byte; each fill writes through
        // post-increment A0 so the second byte follows without another
        // address-register branch seam.
        Append(code, SubQuickOneLongA4);
        var fillFirstDone = AppendClippedVerticalFillByte(code, 0x7F, 0x80, loadAddress: true);
        var fillSecondDone = AppendClippedVerticalFillByte(code, 0xFE, 0x01, loadAddress: false);
        var successOffset = code.Count;
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        PatchBranch(code, fillFirstDone.BranchToDoneExtensionOffset, fillSecondDone.StartOffset);
        PatchBranch(code, fillSecondDone.BranchToDoneExtensionOffset, successOffset);
        return offset;

        static void AppendClippedVerticalByte(
            List<byte> target,
            byte interiorMask,
            byte outsideMask)
        {
            Append(target, MoveByteA6IndirectToD6);
            Append(target, AndImmediateLongD6);
            Append(target, 0);
            Append(target, 0x00FF);
            Append(target, AndImmediateWordD6);
            Append(target, interiorMask);
            Append(target, MoveLongD6ToD5);
            Append(target, MoveByteA3IndirectToD6);
            Append(target, AndImmediateLongD6);
            Append(target, 0);
            Append(target, 0x00FF);
            Append(target, AndImmediateWordD6);
            Append(target, outsideMask);
            Append(target, OrLongD6ToD5);
            Append(target, MoveAddressA3ToA0);
            Append(target, MoveLongD5ToD0);
            Append(target, MoveByteD0ToA0);
        }

        static (int StartOffset, int BranchToDoneExtensionOffset) AppendClippedVerticalFillByte(
            List<byte> target,
            byte interiorMask,
            byte outsideMask,
            bool loadAddress)
        {
            var startOffset = target.Count;
            if (loadAddress)
                Append(target, MoveAddressA4ToA0);
            Append(target, MoveByteA0DisplacementToD6);
            Append(target, 0);
            Append(target, AndImmediateLongD6);
            Append(target, 0);
            Append(target, 0x00FF);
            Append(target, AndImmediateWordD6);
            Append(target, outsideMask);
            Append(target, MoveLongD6ToD5);
            Append(target, CompareImmediateByteD4);
            Append(target, 0);
            Append(target, BranchEqualWord);
            var backgroundZeroBranchExtensionOffset = target.Count;
            Append(target, 0);
            Append(target, MoveLongD5ToD0);
            Append(target, OrImmediateWordD0);
            Append(target, interiorMask);
            Append(target, MoveLongD0ToD1);
            Append(target, MoveByteD1ToA0PostIncrement);
            Append(target, BranchAlwaysWord);
            var branchToDoneExtensionOffset = target.Count;
            Append(target, 0);
            var backgroundZeroOffset = target.Count;
            Append(target, MoveLongD5ToD0);
            Append(target, MoveLongD0ToD1);
            Append(target, MoveByteD1ToA0PostIncrement);
            PatchBranch(target, backgroundZeroBranchExtensionOffset, backgroundZeroOffset);
            return (startOffset, branchToDoneExtensionOffset);
        }
    }

    private static int AppendScrollRasterClippedVerticalOneRow(
        List<byte> code,
        int fallbackEntryOffset,
        int twoByteEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(32);

        // Exact clipped vertical arm: x=1..6 in a two-row, eight-pixel
        // standard-planar rectangle.  The selected six bits are copied from
        // one row to the other; both outside bits and the stride byte remain
        // caller-owned.
        Append(code, MoveLongD0ToD7);
        Append(code, TestWordD0);
        Append(code, BranchNotEqualWord);
        var deltaXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaXBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var deltaYZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaYZeroBranchExtensionOffset);
        Append(code, CompareImmediateWordD2);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var xMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD3);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var yMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 6);
        Append(code, BranchNotEqualWord);
        var xMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, xMaxBranchExtensionOffset, twoByteEntryOffset);
        Append(code, CompareImmediateWordD5);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var yMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMaxBranchExtensionOffset);

        Append(code, CompareImmediateWordD1);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var positiveDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var unsupportedDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedDirectionBranchExtensionOffset);
        Append(code, MoveQuickOneD5);
        Append(code, BranchAlwaysWord);
        var negativeDirectionToValidationBranchExtensionOffset = code.Count;
        Append(code, 0);
        var positiveDirectionOffset = code.Count;
        Append(code, MoveQuickZeroD5);
        var validationOffset = code.Count;

        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C);
        Append(code, BranchHighWord);
        var rastPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortWrapBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var layeredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layeredBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var bitmapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapWrapBranchExtensionOffset);
        Append(code, MoveAddressD0ToA0);

        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD6);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var bytesPerRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bytesPerRowBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD6);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var bitmapFlagsReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD6);
        Append(code, 0x08);
        Append(code, BranchNotEqualWord);
        var bitmapFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapFlagsBranchExtensionOffset);
        var bitmapFlagsReadyOffset = code.Count;
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var planeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeWrapBranchExtensionOffset);
        Append(code, MoveAddressD6ToA3);

        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundPenZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var backgroundPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(backgroundPenBranchExtensionOffset);
        var backgroundPenOneOffset = code.Count;
        Append(code, MoveImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, MoveWordD0ToD4);
        Append(code, BranchAlwaysWord);
        var backgroundReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var backgroundPenZeroOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToD4);
        var readyOffset = code.Count;
        Append(code, MoveQuickTwoD6);
        Append(code, MoveLongD6ToD2);

        Append(code, TestWordD5);
        Append(code, BranchNotEqualWord);
        var negativeOperationBranchExtensionOffset = code.Count;
        Append(code, 0);
        var positiveOperationOffset = AppendScrollRasterClippedVerticalOperation(
            code,
            positiveY: true);
        var negativeOperationOffset = AppendScrollRasterClippedVerticalOperation(
            code,
            positiveY: false);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, positiveDirectionBranchExtensionOffset, positiveDirectionOffset);
        PatchBranch(code, negativeDirectionToValidationBranchExtensionOffset, validationOffset);
        PatchBranch(code, bitmapFlagsReadyBranchExtensionOffset, bitmapFlagsReadyOffset);
        PatchBranch(code, backgroundPenZeroBranchExtensionOffset, backgroundPenZeroOffset);
        PatchBranch(code, backgroundReadyBranchExtensionOffset, readyOffset);
        PatchBranch(code, negativeOperationBranchExtensionOffset, negativeOperationOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendScrollRasterClippedVerticalOperation(
        List<byte> code,
        bool positiveY)
    {
        var offset = code.Count;
        if (positiveY)
        {
            Append(code, MoveAddressA3ToA4);
            Append(code, MoveAddressA4ToA6);
            Append(code, MoveAddressA3ToA5);
            Append(code, AddLongD2ToA5);
        }
        else
        {
            Append(code, MoveAddressA3ToA4);
            Append(code, MoveLongD2ToD3);
            Append(code, AddLongD3ToA4);
            Append(code, MoveAddressA4ToA6);
            Append(code, MoveAddressA3ToA5);
        }

        Append(code, MoveByteA6IndirectToD6);
        Append(code, AndImmediateLongD6);
        Append(code, 0x0000);
        Append(code, 0x00FF);
        Append(code, MoveLongD6ToD5);
        Append(code, AndImmediateWordD5);
        Append(code, 0x007E);
        Append(code, MoveByteA5IndirectToD6);
        Append(code, AndImmediateLongD6);
        Append(code, 0x0000);
        Append(code, 0x00FF);
        Append(code, AndImmediateWordD6);
        Append(code, 0x0081);
        Append(code, OrLongD6ToD5);
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveByteD0ToA0);

        Append(code, MoveAddressA4ToA0);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, 0);
        Append(code, AndImmediateLongD6);
        Append(code, 0x0000);
        Append(code, 0x00FF);
        Append(code, AndImmediateWordD6);
        Append(code, 0x0081);
        Append(code, MoveLongD6ToD5);
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD5ToD0);
        Append(code, OrImmediateWordD0);
        Append(code, 0x007E);
        Append(code, MoveByteD0ToA0);
        Append(code, BranchAlwaysWord);
        var operationDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        var backgroundZeroOffset = code.Count;
        Append(code, MoveLongD5ToD0);
        Append(code, MoveByteD0ToA0);
        var successOffset = code.Count;
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, backgroundZeroBranchExtensionOffset, backgroundZeroOffset);
        PatchBranch(code, operationDoneBranchExtensionOffset, successOffset);
        return offset;
    }

    private static int AppendScrollRasterVerticalOneRow(
        List<byte> code,
        int fallbackEntryOffset,
        int noOpEntryOffset,
        int clippedEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(32);

        // Bounded vertical companion for the native ScrollRaster slice:
        // one 8-pixel row, two rows of word-aligned standard planar storage,
        // and a displacement of exactly +1 or -1.  The source row is copied
        // before the vacated row is filled, so the overlap direction is
        // deterministic on the guest bus.  Clipping, layers, richer BF
        // backfill, and all other geometry remain portable/provider-owned.
        Append(code, MoveLongD0ToD7);
        Append(code, TestWordD0);
        Append(code, BranchNotEqualWord);
        var deltaXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaXBranchExtensionOffset);

        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var zeroDeltaYBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, CompareImmediateWordD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var xMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD3);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var yMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 7);
        Append(code, BranchNotEqualWord);
        var xMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMaxBranchExtensionOffset);
        Append(code, CompareImmediateWordD5);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var yMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMaxBranchExtensionOffset);

        Append(code, CompareImmediateWordD1);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var positiveDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var unsupportedDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedDirectionBranchExtensionOffset);
        Append(code, MoveQuickOneD5);
        Append(code, BranchAlwaysWord);
        var negativeDirectionToValidationBranchExtensionOffset = code.Count;
        Append(code, 0);

        var positiveDirectionOffset = code.Count;
        Append(code, MoveQuickZeroD5);
        var validationOffset = code.Count;

        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var rastPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortWrapBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var layeredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layeredBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var bitmapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapWrapBranchExtensionOffset);
        Append(code, MoveAddressD0ToA0);

        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD6);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var bytesPerRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bytesPerRowBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD6);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var bitmapFlagsReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD6);
        Append(code, 0x08); // BMF_STANDARD is also a native-compatible form.
        Append(code, BranchNotEqualWord);
        var bitmapFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapFlagsBranchExtensionOffset);
        var bitmapFlagsReadyOffset = code.Count;
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // two rows at a two-byte stride
        Append(code, BranchHighWord);
        var planeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeWrapBranchExtensionOffset);
        Append(code, MoveAddressD6ToA3);

        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundPenOneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var backgroundPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(backgroundPenBranchExtensionOffset);

        var backgroundPenOneOffset = code.Count;
        Append(code, MoveImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, MoveWordD0ToD4);
        Append(code, BranchAlwaysWord);
        var backgroundReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var backgroundPenZeroOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToD4);
        var readyOffset = code.Count;
        Append(code, MoveAddressA3ToA4); // retain the first row for +1
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveLongD6ToD1);
        Append(code, TestWordD5);
        Append(code, BranchNotEqualWord);
        var negativeMoveBranchExtensionOffset = code.Count;
        Append(code, 0);

        // +1: source row 0 -> row 1, then fill row 0 with BPen.
        Append(code, MoveByteA3IndirectToD6);
        Append(code, AddLongD1ToA3);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveByteD0ToA0);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveByteD0ToA0);
        Append(code, BranchAlwaysWord);
        var successBranchExtensionOffset = code.Count;
        Append(code, 0);

        // -1: source row 1 -> row 0, then fill row 1 with BPen.
        var negativeMoveOffset = code.Count;
        Append(code, AddLongD1ToA3);
        Append(code, MoveByteA3IndirectToD6);
        Append(code, MoveAddressA4ToA0);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveByteD0ToA0);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongD4ToD0);
        Append(code, MoveByteD0ToA0);
        var successOffset = code.Count;
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, zeroDeltaYBranchExtensionOffset, noOpEntryOffset);
        PatchBranch(code, xMinBranchExtensionOffset, clippedEntryOffset);
        PatchBranch(code, positiveDirectionBranchExtensionOffset, positiveDirectionOffset);
        PatchBranch(code, negativeDirectionToValidationBranchExtensionOffset, validationOffset);
        PatchBranch(code, negativeMoveBranchExtensionOffset, negativeMoveOffset);
        PatchBranch(code, successBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, bitmapFlagsReadyBranchExtensionOffset, bitmapFlagsReadyOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        // The positive direction arm clears D5 after geometry validation;
        // the negative arm leaves D5 nonzero for the move-direction test.
        PatchBranch(code, backgroundPenOneBranchExtensionOffset, backgroundPenZeroOffset);
        PatchBranch(code, backgroundReadyBranchExtensionOffset, readyOffset);

        return offset;
    }

    private static int AppendScrollRasterVerticalByteSpan(
        List<byte> code,
        int fallbackEntryOffset,
        int noOpEntryOffset,
        int byteWidth)
    {
        if (byteWidth is not (2 or 4 or 8))
            throw new ArgumentOutOfRangeException(nameof(byteWidth));

        var offset = code.Count;
        var fallbackBranches = new List<int>(32);
        var xMax = checked(byteWidth * 8 - 1);
        var planeByteCount = checked(byteWidth * 2);

        // Wider vertical companion for the native ScrollRaster slice.  The
        // row stride is exactly the admitted byte width and the operation is
        // deliberately un-clipped: the source and destination rows are
        // disjoint, so a forward byte copy is atomic with respect to the
        // public plane span.  The 8-pixel body above owns its smaller form;
        // this arm handles 16, 32, and 64 pixels only.
        Append(code, MoveLongD0ToD7);
        Append(code, TestWordD0);
        Append(code, BranchNotEqualWord);
        var deltaXBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaXBranchExtensionOffset);

        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var zeroDeltaYBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, CompareImmediateWordD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var xMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD3);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var yMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, checked((ushort)xMax));
        Append(code, BranchNotEqualWord);
        var xMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMaxBranchExtensionOffset);
        Append(code, CompareImmediateWordD5);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var yMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMaxBranchExtensionOffset);

        Append(code, CompareImmediateWordD1);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var positiveDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var unsupportedDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedDirectionBranchExtensionOffset);
        Append(code, MoveQuickOneD5);
        Append(code, BranchAlwaysWord);
        var negativeDirectionToValidationBranchExtensionOffset = code.Count;
        Append(code, 0);

        var positiveDirectionOffset = code.Count;
        Append(code, MoveQuickZeroD5);
        var validationOffset = code.Count;

        // RastPort and BitMap public envelopes.
        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C);
        Append(code, BranchHighWord);
        var rastPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortWrapBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var layeredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layeredBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var bitmapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapWrapBranchExtensionOffset);
        Append(code, MoveAddressD0ToA0);

        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD6);
        Append(code, checked((ushort)byteWidth));
        Append(code, BranchNotEqualWord);
        var bytesPerRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bytesPerRowBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD6);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var bitmapFlagsReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD6);
        Append(code, 0x08); // BMF_STANDARD
        Append(code, BranchNotEqualWord);
        var bitmapFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapFlagsBranchExtensionOffset);
        var bitmapFlagsReadyOffset = code.Count;

        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, unchecked((ushort)(uint.MaxValue - (uint)(planeByteCount - 1))));
        Append(code, BranchHighWord);
        var planeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeWrapBranchExtensionOffset);
        Append(code, MoveAddressD6ToA3);

        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundPenZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var backgroundPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(backgroundPenBranchExtensionOffset);

        var backgroundPenOneOffset = code.Count;
        Append(code, MoveImmediateWordD0);
        Append(code, 0x00FF);
        Append(code, MoveWordD0ToD4);
        Append(code, BranchAlwaysWord);
        var backgroundReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        var backgroundPenZeroOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToD4);
        var readyOffset = code.Count;

        // Keep the first row in A5. A6 is the source cursor, A0 the
        // destination/fill cursor, and A4 is only a one-byte increment
        // scratch register.
        Append(code, MoveAddressA3ToA5);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, MoveLongD6ToD1);
        Append(code, TestWordD5);
        Append(code, BranchNotEqualWord);
        var negativeMoveBranchExtensionOffset = code.Count;
        Append(code, 0);

        // +1: row zero -> row one, then fill row zero.
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveAddressA0ToA6);
        Append(code, AddLongD1ToA3);
        Append(code, MoveAddressA3ToA0);
        AppendScrollRasterVerticalCopyBytes(code, byteWidth);
        Append(code, MoveAddressA5ToA0);
        AppendScrollRasterVerticalFillBytes(code, byteWidth);
        Append(code, BranchAlwaysWord);
        var successBranchExtensionOffset = code.Count;
        Append(code, 0);

        // -1: row one -> row zero, then fill row one.
        var negativeMoveOffset = code.Count;
        Append(code, AddLongD1ToA3);
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveAddressA0ToA6);
        Append(code, MoveAddressA5ToA0);
        AppendScrollRasterVerticalCopyBytes(code, byteWidth);
        Append(code, MoveAddressA3ToA0);
        AppendScrollRasterVerticalFillBytes(code, byteWidth);
        var successOffset = code.Count;
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, zeroDeltaYBranchExtensionOffset, noOpEntryOffset);
        PatchBranch(code, positiveDirectionBranchExtensionOffset, positiveDirectionOffset);
        PatchBranch(code, negativeDirectionToValidationBranchExtensionOffset, validationOffset);
        PatchBranch(code, negativeMoveBranchExtensionOffset, negativeMoveOffset);
        PatchBranch(code, successBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, bitmapFlagsReadyBranchExtensionOffset, bitmapFlagsReadyOffset);
        PatchBranch(code, backgroundPenZeroBranchExtensionOffset, backgroundPenZeroOffset);
        PatchBranch(code, backgroundReadyBranchExtensionOffset, readyOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static void AppendScrollRasterVerticalCopyBytes(
        List<byte> code,
        int byteWidth)
    {
        for (var index = 0; index < byteWidth; index++)
        {
            Append(code, MoveByteA6IndirectToD6);
            Append(code, MoveLongD6ToD0);
            Append(code, MoveByteD0ToA0);
            if (index + 1 < byteWidth)
            {
                Append(code, AddQuickOneLongA6);
                Append(code, MoveAddressA0ToA4);
                Append(code, AddQuickOneLongA4);
                Append(code, MoveAddressA4ToA0);
            }
        }
    }

    private static void AppendScrollRasterVerticalFillBytes(
        List<byte> code,
        int byteWidth)
    {
        for (var index = 0; index < byteWidth; index++)
        {
            Append(code, MoveLongD4ToD0);
            Append(code, MoveByteD0ToA0);
            if (index + 1 < byteWidth)
            {
                Append(code, MoveAddressA0ToA4);
                Append(code, AddQuickOneLongA4);
                Append(code, MoveAddressA4ToA0);
            }
        }
    }

    private static int AppendScrollRasterOnePixel(
        List<byte> code,
        int fallbackEntryOffset,
        int verticalEntryOffset,
        int diagonalEntryOffset,
        int clippedEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(32);

        // Keep the dispatch and each mutating native ScrollRaster slice
        // independently auditable.  Horizontal arms cover complete standard
        // one-plane rows at the admitted byte widths; zero-horizontal and
        // mixed ±1 cases are handed to their bounded vertical/diagonal
        // companions.  The portable/provider owner remains authoritative for
        // clipping, richer displacement, layers, and BF's EraseRect semantics.
        Append(code, MoveLongD0ToD7); // preserve the complete incoming D0
        Append(code, TestWordD0);
        Append(code, BranchEqualWord);
        var zeroDisplacementBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, TestWordD1);
        Append(code, BranchNotEqualWord);
        var deltaYBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, CompareImmediateWordD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var xMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD3);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var yMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 7);
        Append(code, BranchNotEqualWord);
        var xMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMaxBranchExtensionOffset);
        Append(code, CompareImmediateWordD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var yMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMaxBranchExtensionOffset);

        // Retain the direction in D5 after geometry validation.  D5 is free
        // from this point onward; the original D0 remains in D7 for decline.
        Append(code, CompareImmediateWordD0);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var positiveDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var unsupportedDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedDirectionBranchExtensionOffset);
        Append(code, MoveQuickOneD6);
        Append(code, MoveWordD6ToD5);
        Append(code, BranchAlwaysWord);
        var negativeDirectionToValidationBranchExtensionOffset = code.Count;
        Append(code, 0);

        var positiveDirectionOffset = code.Count;
        Append(code, MoveQuickZeroD5);
        var validationOffset = code.Count;

        // Validate the complete RastPort/BitMap envelope before touching the
        // plane byte.  The checks mirror the public guest layout and reject
        // wrapped or odd addresses without changing caller memory.
        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C); // RastPortMinimumSize (0xB4) envelope
        Append(code, BranchHighWord);
        var rastPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortWrapBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var layeredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layeredBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope
        Append(code, BranchHighWord);
        var bitmapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapWrapBranchExtensionOffset);
        Append(code, MoveAddressD0ToA0);

        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD6);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var bytesPerRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bytesPerRowBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, AndImmediateWordD6);
        Append(code, 0x0007); // no clear/displayable/interleaved variant
        Append(code, TestWordD6);
        Append(code, BranchNotEqualWord);
        var bitmapFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapFlagsBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE); // one two-byte row envelope
        Append(code, BranchHighWord);
        var planeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeWrapBranchExtensionOffset);
        Append(code, MoveAddressD6ToA3);

        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD6);
        Append(code, 0); // JAM1 only; BF's richer EraseRect path declines
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundPenOneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var backgroundPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(backgroundPenBranchExtensionOffset);

        var backgroundPenReadyOffset = code.Count;
        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, TestWordD5);
        Append(code, BranchEqualWord);
        var positiveTailBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Negative one-pixel shift: source >> 1, with BPen entering bit 7.
        Append(code, MoveByteA3IndirectToD6);
        Append(code, AndImmediateLongD6);
        Append(code, 0x0000);
        Append(code, 0x00FF);
        Append(code, MoveLongD6ToD5);
        Append(code, ShiftRightLongD5);
        Append(code, AndImmediateWordD5);
        Append(code, 0x007F);
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var negativeBpenZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD5ToD0);
        Append(code, OrImmediateWordD0);
        Append(code, 0x0080);
        Append(code, MoveByteD0ToA0);
        Append(code, BranchAlwaysWord);
        var negativeDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        var negativeBpenZeroOffset = code.Count;
        Append(code, MoveLongD5ToD0);
        Append(code, MoveByteD0ToA0);
        Append(code, BranchAlwaysWord);
        var negativeZeroDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Positive one-pixel shift: source << 1, with BPen entering bit 0.
        var positiveTailOffset = code.Count;
        Append(code, MoveByteA3IndirectToD6);
        Append(code, AndImmediateLongD6);
        Append(code, 0x0000);
        Append(code, 0x00FF);
        Append(code, MoveLongD6ToD5);
        Append(code, ShiftLeftLongD5);
        Append(code, AndImmediateWordD5);
        Append(code, 0x00FE);
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var positiveBpenZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD5ToD0);
        Append(code, OrImmediateWordD0);
        Append(code, 1);
        Append(code, MoveByteD0ToA0);
        Append(code, BranchAlwaysWord);
        var positiveDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        var positiveBpenZeroOffset = code.Count;
        Append(code, MoveLongD5ToD0);
        Append(code, MoveByteD0ToA0);
        var successOffset = code.Count;
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, zeroDisplacementBranchExtensionOffset, verticalEntryOffset);
        PatchBranch(code, deltaYBranchExtensionOffset, diagonalEntryOffset);
        PatchBranch(code, xMinBranchExtensionOffset, clippedEntryOffset);
        PatchBranch(code, positiveDirectionBranchExtensionOffset, positiveDirectionOffset);
        PatchBranch(code, negativeDirectionToValidationBranchExtensionOffset, validationOffset);
        PatchBranch(code, positiveTailBranchExtensionOffset, positiveTailOffset);
        PatchBranch(code, negativeBpenZeroBranchExtensionOffset, negativeBpenZeroOffset);
        PatchBranch(code, negativeDoneBranchExtensionOffset, successOffset);
        PatchBranch(code, negativeZeroDoneBranchExtensionOffset, successOffset);
        PatchBranch(code, positiveBpenZeroBranchExtensionOffset, positiveBpenZeroOffset);
        PatchBranch(code, positiveDoneBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        // BPen==0 skips the BPen==1 rejection branch and enters the shared
        // operation tail.  BPen==1 simply falls through to that same tail.
        PatchBranch(code, backgroundPenOneBranchExtensionOffset, backgroundPenReadyOffset);

        return offset;
    }

    private static int AppendScrollRasterTwoByte(
        List<byte> code,
        int fallbackEntryOffset,
        int noOpEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(32);

        // A second, still deliberately bounded, native slice for a complete
        // sixteen-pixel row.  Keeping each width separate makes the admitted
        // spans independently auditable; clipped, mixed-displacement, and
        // provider-shaped forms remain on the portable/provider owner.
        Append(code, MoveLongD0ToD7);
        Append(code, TestWordD0);
        Append(code, BranchEqualWord);
        var zeroDisplacementBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, TestWordD1);
        Append(code, BranchNotEqualWord);
        var deltaYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaYBranchExtensionOffset);

        Append(code, CompareImmediateWordD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var xMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD3);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var yMinBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMinBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 15);
        Append(code, BranchNotEqualWord);
        var xMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(xMaxBranchExtensionOffset);
        Append(code, CompareImmediateWordD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var yMaxBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(yMaxBranchExtensionOffset);

        Append(code, CompareImmediateWordD0);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var positiveDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var unsupportedDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedDirectionBranchExtensionOffset);
        Append(code, MoveQuickOneD6);
        Append(code, MoveWordD6ToD5);
        Append(code, BranchAlwaysWord);
        var negativeDirectionToValidationBranchExtensionOffset = code.Count;
        Append(code, 0);

        var positiveDirectionOffset = code.Count;
        Append(code, MoveQuickZeroD5);
        var validationOffset = code.Count;

        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C);
        Append(code, BranchHighWord);
        var rastPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortWrapBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var layeredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layeredBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var bitmapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapWrapBranchExtensionOffset);
        Append(code, MoveAddressD0ToA0);

        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD6);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var bytesPerRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bytesPerRowBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        // Compare the byte directly.  Keeping the flags admission byte-sized
        // avoids carrying the bitmap pointer's upper bytes through a
        // word-sized mask on the narrow native path.
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapFlagsBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE);
        Append(code, BranchHighWord);
        var planeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeWrapBranchExtensionOffset);
        Append(code, MoveAddressD6ToA3);

        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundPenReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var backgroundPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(backgroundPenBranchExtensionOffset);
        var backgroundPenReadyOffset = code.Count;

        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, TestWordD5);
        Append(code, BranchEqualWord);
        var positiveTailBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Negative: form a big-endian 16-bit row, shift right, and insert
        // BPen in the vacated most-significant pixel.
        Append(code, MoveByteA3IndirectToD6);
        Append(code, AndImmediateLongD6);
        Append(code, 0);
        Append(code, 0x00FF);
        Append(code, MoveLongD6ToD5);
        for (var index = 0; index < 8; index++)
            Append(code, ShiftLeftLongD5);
        Append(code, MoveByteA3DisplacementToD4);
        Append(code, 1);
        Append(code, AndImmediateWordD4);
        Append(code, 0x00FF);
        Append(code, MoveWordD4ToD6);
        Append(code, OrLongD6ToD5);
        Append(code, ShiftRightLongD5);
        Append(code, AndImmediateWordD5);
        Append(code, 0x7FFF);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var negativeBpenZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD5ToD0);
        Append(code, OrImmediateWordD0);
        Append(code, 0x8000);
        Append(code, MoveLongD0ToD5);
        var negativeBpenZeroOffset = code.Count;
        Append(code, MoveLongD5ToD0);
        for (var index = 0; index < 8; index++)
            Append(code, ShiftRightLongD0);
        Append(code, MoveByteD0ToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveByteD0ToA0Displacement);
        Append(code, 1);
        Append(code, BranchAlwaysWord);
        var negativeDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Positive: form the same row, shift left, and insert BPen in the
        // vacated least-significant pixel.
        var positiveTailOffset = code.Count;
        Append(code, MoveByteA3IndirectToD6);
        Append(code, AndImmediateLongD6);
        Append(code, 0);
        Append(code, 0x00FF);
        Append(code, MoveLongD6ToD5);
        for (var index = 0; index < 8; index++)
            Append(code, ShiftLeftLongD5);
        Append(code, MoveByteA3DisplacementToD4);
        Append(code, 1);
        Append(code, AndImmediateWordD4);
        Append(code, 0x00FF);
        Append(code, MoveWordD4ToD6);
        Append(code, OrLongD6ToD5);
        Append(code, ShiftLeftLongD5);
        Append(code, AndImmediateWordD5);
        Append(code, 0xFFFE);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var positiveBpenZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD5ToD0);
        Append(code, OrImmediateWordD0);
        Append(code, 1);
        Append(code, MoveLongD0ToD5);
        var positiveBpenZeroOffset = code.Count;
        Append(code, MoveLongD5ToD0);
        for (var index = 0; index < 8; index++)
            Append(code, ShiftRightLongD0);
        Append(code, MoveByteD0ToA0);
        Append(code, MoveLongD5ToD0);
        Append(code, MoveByteD0ToA0Displacement);
        Append(code, 1);
        var successOffset = code.Count;
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, zeroDisplacementBranchExtensionOffset, noOpEntryOffset);
        PatchBranch(code, positiveDirectionBranchExtensionOffset, positiveDirectionOffset);
        PatchBranch(code, negativeDirectionToValidationBranchExtensionOffset, validationOffset);
        PatchBranch(code, positiveTailBranchExtensionOffset, positiveTailOffset);
        PatchBranch(code, negativeBpenZeroBranchExtensionOffset, negativeBpenZeroOffset);
        PatchBranch(code, negativeDoneBranchExtensionOffset, successOffset);
        PatchBranch(code, positiveBpenZeroBranchExtensionOffset, positiveBpenZeroOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, backgroundPenReadyBranchExtensionOffset, backgroundPenReadyOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendScrollRasterByteSpan(
        List<byte> code,
        int fallbackEntryOffset,
        int noOpEntryOffset,
        int byteWidth)
    {
        if (byteWidth is not (4 or 8))
            throw new ArgumentOutOfRangeException(nameof(byteWidth));

        var offset = code.Count;
        var fallbackBranches = new List<int>(32);
        var xMax = checked((ushort)(byteWidth * 8 - 1));
        var maximumPlaneAddress = uint.MaxValue - (uint)(byteWidth - 1);

        // This generator admits complete 32- and 64-pixel rows.  Positive
        // shifts walk from the first byte forward, so the next source byte is
        // still untouched; negative shifts start at the last byte and walk
        // backward for the symmetric reason.  Each byte is staged in data
        // registers before publication, preserving overlap semantics without
        // introducing a host pointer or absolute relocation.
        Append(code, MoveLongD0ToD7);
        Append(code, TestWordD0);
        Append(code, BranchEqualWord);
        var zeroDisplacementBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, TestWordD1);
        Append(code, BranchNotEqualWord);
        var deltaYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(deltaYBranchExtensionOffset);

        foreach (var (registerOpcode, value) in new[]
        {
            (CompareImmediateWordD2, (ushort)0),
            (CompareImmediateWordD3, (ushort)0),
            (CompareImmediateWordD4, xMax),
            (CompareImmediateWordD5, (ushort)0)
        })
        {
            Append(code, registerOpcode);
            Append(code, value);
            Append(code, BranchNotEqualWord);
            var branchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(branchExtensionOffset);
        }

        Append(code, CompareImmediateWordD0);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var positiveDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD0);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var unsupportedDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedDirectionBranchExtensionOffset);
        Append(code, MoveQuickOneD6);
        Append(code, MoveWordD6ToD5);
        Append(code, BranchAlwaysWord);
        var negativeDirectionToValidationBranchExtensionOffset = code.Count;
        Append(code, 0);

        var positiveDirectionOffset = code.Count;
        Append(code, MoveQuickZeroD5);
        var validationOffset = code.Count;

        Append(code, MoveLongA1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var rastPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var rastPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF4C);
        Append(code, BranchHighWord);
        var rastPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rastPortWrapBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var layeredBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layeredBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8);
        Append(code, BranchHighWord);
        var bitmapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapWrapBranchExtensionOffset);
        Append(code, MoveAddressD0ToA0);

        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, CompareImmediateWordD6);
        Append(code, checked((ushort)byteWidth));
        Append(code, BranchNotEqualWord);
        var bytesPerRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bytesPerRowBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var bitmapFlagsReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD6);
        Append(code, 0x08); // BMF_STANDARD is the only nonzero flag bit admitted here.
        Append(code, BranchNotEqualWord);
        var bitmapFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapFlagsBranchExtensionOffset);
        var bitmapFlagsReadyOffset = code.Count;
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var planeNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var planeOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, (ushort)(maximumPlaneAddress >> 16));
        Append(code, (ushort)maximumPlaneAddress);
        Append(code, BranchHighWord);
        var planeWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(planeWrapBranchExtensionOffset);
        Append(code, MoveAddressD6ToA3);

        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);

        // Preserve BPen in D2 after geometry/pointer validation.  Use D4 for
        // the byte admission (the established native slices already exercise
        // CMPI.B D4); D2 is then a clean long-sized edge value for the shift
        // tails below.
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, CompareImmediateByteD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var backgroundPenReadyBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var backgroundPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(backgroundPenBranchExtensionOffset);
        var backgroundPenReadyOffset = code.Count;
        Append(code, MoveLongD4ToD2);

        Append(code, MoveLongD7ToD0);
        Append(code, TestWordD5);
        Append(code, BranchEqualWord);
        var positiveTailBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Negative shift, from the last byte toward the first.  The previous
        // source byte is read at -1(A3) before A3 is decremented, so overlap
        // never feeds a published byte back into the source stream.
        if (byteWidth == 4)
            Append(code, AddQuickFourLongA3);
        else
        {
            Append(code, AddQuickFourLongA3);
            Append(code, AddQuickFourLongA3);
        }
        // A3 must address the final byte, not the first byte past the row.
        // Subtracting one after the width-sized advance keeps this generic
        // path independent of a separate ADDQ #3 encoding.
        Append(code, SubQuickOneLongA3);

        for (var index = byteWidth - 1; index >= 0; index--)
        {
            Append(code, MoveByteA3IndirectToD6);
            Append(code, AndImmediateLongD6);
            Append(code, 0);
            Append(code, 0x00FF);
            Append(code, ShiftRightLongD6);
            Append(code, AndImmediateWordD6);
            Append(code, 0x007F);

            Append(code, MoveQuickZeroD4);
            if (index > 0)
            {
                Append(code, MoveAddressA3ToA0);
                Append(code, MoveByteA0DisplacementToD4);
                Append(code, 0xFFFF);
                for (var shift = 0; shift < 7; shift++)
                    Append(code, ShiftLeftLongD4);
                Append(code, AndImmediateWordD4);
                Append(code, 0x0080);
            }
            else
            {
                Append(code, MoveLongD2ToD4);
                for (var shift = 0; shift < 7; shift++)
                    Append(code, ShiftLeftLongD4);
                Append(code, AndImmediateWordD4);
                Append(code, 0x0080);
            }
            Append(code, MoveQuickZeroD5);
            Append(code, OrLongD6ToD5);
            Append(code, MoveLongD4ToD6);
            Append(code, OrLongD6ToD5);
            Append(code, MoveLongD5ToD0);
            Append(code, MoveAddressA3ToA0);
            Append(code, MoveByteD0ToA0);
            if (index > 0)
                Append(code, SubQuickOneLongA3);
        }

        Append(code, BranchAlwaysWord);
        var negativeDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Positive shift, from the first byte toward the last.  The next
        // source byte remains untouched until its own turn.
        var positiveTailOffset = code.Count;
        for (var index = 0; index < byteWidth; index++)
        {
            Append(code, MoveByteA3IndirectToD6);
            Append(code, AndImmediateLongD6);
            Append(code, 0);
            Append(code, 0x00FF);
            Append(code, ShiftLeftLongD6);
            Append(code, AndImmediateWordD6);
            Append(code, 0x00FE);

            Append(code, MoveQuickZeroD4);
            if (index < byteWidth - 1)
            {
                Append(code, MoveAddressA3ToA0);
                Append(code, MoveByteA0DisplacementToD4);
                Append(code, 1);
                for (var shift = 0; shift < 7; shift++)
                    Append(code, ShiftRightLongD4);
                Append(code, AndImmediateWordD4);
                Append(code, 1);
            }
            else
            {
                Append(code, MoveLongD2ToD4);
            }
            Append(code, MoveQuickZeroD5);
            Append(code, OrLongD6ToD5);
            Append(code, MoveLongD4ToD6);
            Append(code, OrLongD6ToD5);
            Append(code, MoveLongD5ToD0);
            Append(code, MoveAddressA3ToA0);
            Append(code, MoveByteD0ToA0);
            if (index < byteWidth - 1)
                Append(code, AddQuickOneLongA3);
        }

        var successOffset = code.Count;
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, zeroDisplacementBranchExtensionOffset, noOpEntryOffset);
        PatchBranch(code, positiveDirectionBranchExtensionOffset, positiveDirectionOffset);
        PatchBranch(code, negativeDirectionToValidationBranchExtensionOffset, validationOffset);
        PatchBranch(code, positiveTailBranchExtensionOffset, positiveTailOffset);
        PatchBranch(code, negativeDoneBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, backgroundPenReadyBranchExtensionOffset, backgroundPenReadyOffset);
        PatchBranch(code, bitmapFlagsReadyBranchExtensionOffset, bitmapFlagsReadyOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendTextMultiPlaneOneRow(
        List<byte> code,
        int onePlaneEntryOffset,
        int expectedCount,
        int currentXByteOffset = 0,
        int currentXBitOffset = 0,
        bool runtimeByteAlignedX = false)
    {
        // Keep the fallback route relocatable as the exact-count family grows.
        // The first relay sits beside the preceding owner; a second skipped
        // relay is inserted after source preflight so the final failure hop
        // remains inside the signed-WORD branch envelope.
        var fallbackRelayOffset = AppendUnpatchedBranchIsland(
            code,
            out var fallbackRelayExtensionOffset);
        PatchBranch(code, fallbackRelayExtensionOffset, onePlaneEntryOffset);
        var offset = code.Count;
        var fallbackBranches = new List<int>(96);

        // This native multi-plane Text slice intentionally admits a bounded
        // fixed-cell 8x1 glyph span in a standard planar bitmap.  The
        // generated entry is specialized for one through sixteen glyphs at
        // the selected byte-/bit-aligned origin; the current non-origin
        // extensions admit one- through seven-pixel offsets for one glyph
        // plus the two-glyph x=1 through x=16 forms (including byte-aligned
        // x=8 and x=16), and the three-glyph byte-aligned  forms; the
        // The ladder now also includes the x=1032, x=1040, x=1048, x=1056,
        // x=1064, x=1072, x=1080, x=1088, x=1096, x=1104, x=1112, x=1120,
        // x=1128, x=1136, x=1144, x=1152, x=1160, x=1168, x=1176, x=1184,
        // x=1192, x=1200, x=1208, and x=1216 byte-aligned forms. The
        // one-plane body remains the owner for longer strings,
        // nonzero origins, proportional fonts, styles, clipping, layers, and
        // richer minterm/background semantics.  Every selected plane is
        // preflighted before the first destination byte is touched.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveAddressA0ToA5);
        Append(code, CompareImmediateWordD0);
        Append(code, (ushort)expectedCount);
        Append(code, BranchNotEqualWord);
        var countBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(countBranchExtensionOffset);

        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var sourceNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceNullBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        var sourceEnvelopeLimit = checked((ushort)(0x10000 - expectedCount));
        Append(code, sourceEnvelopeLimit); // the complete fixed-cell source span remains addressable.
        Append(code, BranchHighWord);
        var sourceWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceWrapBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var layerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(layerBranchExtensionOffset);

        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, BitTestImmediateD4);
        Append(code, 14); // RPF_NO_PENS belongs to the provider/native owner.
        Append(code, BranchNotEqualWord);
        var noPensBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(noPensBranchExtensionOffset);

        Append(code, MoveQuickZeroD5);
        Append(code, MoveByteA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var maskBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maskBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, CompareImmediateByteD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var foregroundPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(foregroundPenBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawModeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawModeBranchExtensionOffset);

        // The bounded renderer normally starts at a selected byte-/bit-aligned
        // CurrentX. Runtime fixed-cell arms admit a byte-aligned position
        // through the last byte that keeps their complete span within a
        // 256-byte conservative plane envelope. D0 carries that checked byte
        // offset until the destination transaction and final cursor
        // publication; all other forms retain the existing fixed selector.
        Append(code, MoveWordA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentX));
        if (runtimeByteAlignedX)
        {
            Append(code, TestWordD6);
            Append(code, BranchMinusWord);
            var currentXNegativeBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(currentXNegativeBranchExtensionOffset);
            Append(code, MoveLongD6ToD5);
            Append(code, AndImmediateLongD5);
            Append(code, 0);
            Append(code, 7);
            Append(code, TestLongD5);
            Append(code, BranchNotEqualWord);
            var currentXAlignmentBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(currentXAlignmentBranchExtensionOffset);
            Append(code, CompareImmediateWordD6);
            Append(code, checked((ushort)((256 - expectedCount) * 8)));
            Append(code, BranchHighWord);
            var currentXLimitBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(currentXLimitBranchExtensionOffset);
            Append(code, MoveLongD6ToD0);
            Append(code, ShiftRightLongD0);
            Append(code, ShiftRightLongD0);
            Append(code, ShiftRightLongD0);
        }
        else
        {
            Append(code, CompareImmediateWordD6);
            Append(code, checked((ushort)(currentXByteOffset * 8 + currentXBitOffset)));
            Append(code, BranchNotEqualWord);
            var currentXBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(currentXBranchExtensionOffset);
        }
        Append(code, MoveWordA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentY));
        Append(code, CompareImmediateWordD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var currentYBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(currentYBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextBaseline));
        Append(code, CompareImmediateWordD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var baselineBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(baselineBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextSpacing));
        Append(code, CompareImmediateWordD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var spacingBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(spacingBranchExtensionOffset);

        Append(code, MoveLongA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFont));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var fontNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fontAlignmentBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontAlignmentBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFCC); // TextFontMinimumSize (0x34) envelope.
        Append(code, BranchHighWord);
        var fontWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontWrapBranchExtensionOffset);
        Append(code, MoveAddressD1ToA2);
        Append(code, MoveWordA2DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontYSize));
        Append(code, CompareImmediateWordD3);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var fontHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontHeightBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontXSize));
        Append(code, CompareImmediateWordD3);
        Append(code, 8);
        Append(code, BranchNotEqualWord);
        var fontWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontWidthBranchExtensionOffset);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.TextFontStyle));
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var fontStyleBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontStyleBranchExtensionOffset);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA2DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.TextFontFlags));
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var fontFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontFlagsBranchExtensionOffset);
        Append(code, MoveWordA2DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontModulo));
        Append(code, CompareImmediateWordD3);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var fontModuloBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontModuloBranchExtensionOffset);

        // Consume exactly one source character after all fixed-font state has
        // been admitted.  The one-byte modulo arm keeps the CharData offset
        // arithmetic bounded to the declared byte range.
        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA0PostIncrementToD6);
        Append(code, MoveLongD6ToD5);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, CompareByteD4ToD6);
        Append(code, BranchCarryWord);
        var lowCharBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowCharBranchExtensionOffset);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
        Append(code, CompareByteD4ToD6);
        Append(code, BranchHighWord);
        var highCharBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(highCharBranchExtensionOffset);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, MoveWordD6ToD5);
        Append(code, SubWordD4ToD5);
        Append(code, ExtendLongD5);
        Append(code, MoveLongA2DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharData));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var charDataNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(charDataNullBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFF00); // one-byte source envelope after char offset.
        Append(code, BranchHighWord);
        var charDataWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(charDataWrapBranchExtensionOffset);
        Append(code, MoveAddressD1ToA3);
        Append(code, AddLongD5ToA3);
        Append(code, MoveByteA3IndirectToD6);
        Append(code, MoveLongD6ToD4); // preserve the glyph across plane checks.

        if (expectedCount > 1)
        {
            // Preflight every remaining source character and fixed-cell strike
            // before the bitmap/plane transaction begins. Rendering reloads
            // the same bytes after this pass, so a malformed later glyph can
            // never leave an earlier destination byte published.
            for (var glyphIndex = 1; glyphIndex < expectedCount; glyphIndex++)
            {
                Append(code, MoveAddressA5ToA0);
                for (var sourceOffset = 0; sourceOffset < glyphIndex; sourceOffset++)
                    Append(code, AddQuickOneLongA0);
                Append(code, MoveByteA0PostIncrementToD6);
                Append(code, MoveLongD6ToD5);
                // D4 retains glyph zero for the later publication pass.
                // The remaining source preflight uses D3, which is reloaded
                // from BitMap.Rows before any destination arithmetic.
                Append(code, MoveQuickZeroD3);
                Append(code, MoveByteA2DisplacementToD3);
                Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
                Append(code, CompareByteD3ToD6);
                Append(code, BranchCarryWord);
                var subGlyphLowCharBranchExtensionOffset = code.Count;
                Append(code, 0);
                fallbackBranches.Add(subGlyphLowCharBranchExtensionOffset);
                Append(code, MoveQuickZeroD3);
                Append(code, MoveByteA2DisplacementToD3);
                Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
                Append(code, CompareByteD3ToD6);
                Append(code, BranchHighWord);
                var subGlyphHighCharBranchExtensionOffset = code.Count;
                Append(code, 0);
                fallbackBranches.Add(subGlyphHighCharBranchExtensionOffset);
                Append(code, MoveQuickZeroD3);
                Append(code, MoveByteA2DisplacementToD3);
                Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
                Append(code, MoveWordD6ToD5);
                Append(code, SubWordD3ToD5);
                Append(code, ExtendLongD5);
                Append(code, MoveLongA2DisplacementToD1);
                Append(code, checked((ushort)GraphicsLayouts.TextFontCharData));
                Append(code, TestLongD1);
                Append(code, BranchEqualWord);
                var subGlyphCharDataNullBranchExtensionOffset = code.Count;
                Append(code, 0);
                fallbackBranches.Add(subGlyphCharDataNullBranchExtensionOffset);
                Append(code, CompareImmediateLongD1);
                Append(code, 0xFFFF);
                Append(code, 0xFF00);
                Append(code, BranchHighWord);
                var subGlyphCharDataWrapBranchExtensionOffset = code.Count;
                Append(code, 0);
                fallbackBranches.Add(subGlyphCharDataWrapBranchExtensionOffset);
                Append(code, MoveAddressD1ToA3);
                Append(code, AddLongD5ToA3);
                Append(code, MoveByteA3IndirectToD6);
            }
        }

        Append(code, BranchAlwaysWord);
        var fallbackRelaySkipExtensionOffset = code.Count;
        Append(code, 0);
        var intermediateFallbackRelayOffset = AppendUnpatchedBranchIsland(
            code,
            out var intermediateFallbackRelayExtensionOffset);
        var fallbackRelayResumeOffset = code.Count;
        PatchBranch(code, fallbackRelaySkipExtensionOffset, fallbackRelayResumeOffset);
        PatchBranch(
            code,
            intermediateFallbackRelayExtensionOffset,
            fallbackRelayOffset);

        Append(code, MoveLongA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var bitmapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var bitmapAlignmentBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapAlignmentBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFD8); // BitMapSize (0x28) envelope.
        Append(code, BranchHighWord);
        var bitmapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapWrapBranchExtensionOffset);
        Append(code, MoveAddressD1ToA4);
        Append(code, MoveByteA4DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var standardFlagBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD6);
        Append(code, 0x08); // BMF_STANDARD.
        Append(code, BranchNotEqualWord);
        var bitmapFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(bitmapFlagsBranchExtensionOffset);
        var standardFlagReadyOffset = code.Count;
        PatchBranch(code, standardFlagBranchExtensionOffset, standardFlagReadyOffset);
        Append(code, MoveQuickZeroD2);
        Append(code, MoveByteA4DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, MoveLongD6ToD2);
        Append(code, CompareImmediateWordD2);
        Append(code, 2);
        Append(code, BranchCarryWord);
        var depthLowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthLowBranchExtensionOffset);
        Append(code, CompareImmediateWordD2);
        Append(code, 8);
        Append(code, BranchHighWord);
        var depthHighBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(depthHighBranchExtensionOffset);
        Append(code, MoveWordA4DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, CompareImmediateWordD3);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var rowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rowsBranchExtensionOffset);
        // The runtime arm limits its offset to 256 minus its glyph count, so
        // its complete one-, two-, or three-byte strike remains inside the
        // fixed 256-byte pointer-envelope preflight below. Fixed arms
        // preserve their exact immediate envelope.
        var requiredDestinationBytes = runtimeByteAlignedX
            ? 256
            : checked(
                currentXByteOffset +
                ((currentXBitOffset + (expectedCount * 8) + 7) >> 3));
        Append(code, MoveWordA4DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        if (runtimeByteAlignedX)
        {
            Append(code, MoveLongD0ToD5);
            for (var requiredByte = 0; requiredByte < expectedCount; requiredByte++)
                Append(code, AddQuickOneLongD5);
            Append(code, CompareWordD5ToD6);
            Append(code, BranchCarryWord);
            var bytesPerRowBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(bytesPerRowBranchExtensionOffset);
        }
        else
        {
            Append(code, CompareImmediateWordD6);
            Append(code, checked((ushort)requiredDestinationBytes));
            Append(code, BranchNotEqualWord);
            var bytesPerRowBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(bytesPerRowBranchExtensionOffset);
        }
        // BitMap.Planes is the inline eight-LONG array in the public guest
        // layout, so keep A3 on the validated BitMap and address each slot by
        // its public offset below.
        Append(code, MoveAddressA4ToA3);
        // Source-char offset arithmetic reuses D5, so re-load the selected
        // plane mask immediately before the all-plane transaction.
        Append(code, MoveQuickZeroD5);
        Append(code, MoveByteA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));

        // Validate every plane selected by Mask before rendering any one of
        // them.  This is the atomicity boundary for caller-owned planar data.
        Append(code, MoveAddressA4ToA3);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveByteA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        for (var planeIndex = 0; planeIndex < 8; planeIndex++)
        {
            Append(code, CompareImmediateWordD2);
            Append(code, (ushort)(planeIndex + 1));
            Append(code, BranchCarryWord);
            var depthSkipBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, BitTestImmediateD5);
            Append(code, (ushort)planeIndex);
            Append(code, BranchEqualWord);
            var maskSkipBranchExtensionOffset = code.Count;
            Append(code, 0);
            Append(code, MoveLongA3DisplacementToD1);
            Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + (planeIndex * 4))));
            Append(code, TestLongD1);
            Append(code, BranchEqualWord);
            var planeNullBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(planeNullBranchExtensionOffset);
            Append(code, BitTestImmediateD1);
            Append(code, 0);
            Append(code, BranchNotEqualWord);
            var planeAlignmentBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(planeAlignmentBranchExtensionOffset);
            Append(code, CompareImmediateLongD1);
            Append(code, 0xFFFF);
            var destinationEnvelopeLimit = checked((ushort)(
                0x10000 - requiredDestinationBytes));
            Append(code, destinationEnvelopeLimit);
            Append(code, BranchHighWord);
            var planeWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(planeWrapBranchExtensionOffset);
            var nextPlaneOffset = code.Count;
            PatchBranch(code, depthSkipBranchExtensionOffset, nextPlaneOffset);
            PatchBranch(code, maskSkipBranchExtensionOffset, nextPlaneOffset);
        }

        // JAM1/APen=1 sets source-one pixels and leaves source-zero pixels
        // unchanged.  The destination byte is read for each set bit so the
        // arm preserves the background in every selected plane.  Each
        // generated glyph is decoded again after the complete source/strike
        // preflight, keeping the publication transaction atomic.
        for (var glyphIndex = 0; glyphIndex < expectedCount; glyphIndex++)
        {
            if (expectedCount > 1 && glyphIndex > 0)
            {
                Append(code, MoveAddressA5ToA0);
                for (var sourceOffset = 0; sourceOffset < glyphIndex; sourceOffset++)
                    Append(code, AddQuickOneLongA0);
                Append(code, MoveByteA0PostIncrementToD6);
                Append(code, MoveLongD6ToD5);
                Append(code, MoveQuickZeroD4);
                Append(code, MoveByteA2DisplacementToD4);
                Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
                Append(code, MoveWordD6ToD5);
                Append(code, SubWordD4ToD5);
                Append(code, ExtendLongD5);
                Append(code, MoveLongA2DisplacementToD1);
                Append(code, checked((ushort)GraphicsLayouts.TextFontCharData));
                Append(code, MoveAddressD1ToA3);
                Append(code, AddLongD5ToA3);
                Append(code, MoveByteA3IndirectToD6);
                Append(code, MoveLongD6ToD4);
            }

            Append(code, MoveAddressA4ToA3);
            Append(code, MoveQuickZeroD5);
            Append(code, MoveByteA1DisplacementToD5);
            Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
            for (var planeIndex = 0; planeIndex < 8; planeIndex++)
            {
                Append(code, CompareImmediateWordD2);
                Append(code, (ushort)(planeIndex + 1));
                Append(code, BranchCarryWord);
                var depthSkipBranchExtensionOffset = code.Count;
                Append(code, 0);
                Append(code, BitTestImmediateD5);
                Append(code, (ushort)planeIndex);
                Append(code, BranchEqualWord);
                var maskSkipBranchExtensionOffset = code.Count;
                Append(code, 0);
                Append(code, MoveLongA3DisplacementToD1);
                Append(code, checked((ushort)(GraphicsLayouts.BitMapPlanes + (planeIndex * 4))));
                Append(code, MoveAddressD1ToA0);
                if (runtimeByteAlignedX)
                {
                    Append(code, AddLongD0ToA0);
                    for (var destinationAdvance = 0; destinationAdvance < glyphIndex; destinationAdvance++)
                        Append(code, AddQuickOneLongA0);
                }
                else
                {
                    var destinationOffset = currentXByteOffset + glyphIndex;
                    if (destinationOffset != 0)
                    {
                        Append(code, AddImmediateLongToA0);
                        Append(code, 0);
                        Append(code, checked((ushort)destinationOffset));
                    }
                }

                var destinationByteOffset = 0;
                for (var bit = 0; bit < 8; bit++)
                {
                    var sourceMask = (ushort)(0x80 >> bit);
                    var requiredDestinationByteOffset =
                        (currentXBitOffset + bit) >> 3;
                    var destinationBit = (currentXBitOffset + bit) & 7;
                    var destinationMask = (ushort)(0x80 >> destinationBit);
                    if (requiredDestinationByteOffset > destinationByteOffset)
                    {
                        Append(code, AddQuickOneLongA0);
                        destinationByteOffset = requiredDestinationByteOffset;
                    }
                    Append(code, MoveLongD4ToD6);
                    Append(code, AndImmediateLongD6);
                    Append(code, 0);
                    Append(code, sourceMask);
                    Append(code, TestLongD6);
                    Append(code, BranchEqualWord);
                    var pixelSkipBranchExtensionOffset = code.Count;
                    Append(code, 0);
                    Append(code, MoveByteA0IndirectToD1);
                    Append(code, OrImmediateByteD1);
                    Append(code, destinationMask);
                    Append(code, MoveByteD1ToA0Displacement);
                    Append(code, 0);
                    PatchBranch(code, pixelSkipBranchExtensionOffset, code.Count);
                }

                var nextPlaneOffset = code.Count;
                PatchBranch(code, depthSkipBranchExtensionOffset, nextPlaneOffset);
                PatchBranch(code, maskSkipBranchExtensionOffset, nextPlaneOffset);
            }
        }

        if (runtimeByteAlignedX)
        {
            Append(code, MoveLongD0ToD6);
            Append(code, ShiftLeftLongD6);
            Append(code, ShiftLeftLongD6);
            Append(code, ShiftLeftLongD6);
            Append(code, AddImmediateWordD6);
            Append(code, checked((ushort)(expectedCount * 8)));
            Append(code, MoveWordD6ToA1Displacement);
        }
        else
        {
            Append(code, MoveImmediateWordD0);
            Append(code, checked((ushort)(
                currentXByteOffset * 8 +
                currentXBitOffset +
                (expectedCount * 8))));
            Append(code, MoveWordD0ToA1Displacement);
        }
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentX));
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, OrImmediateWordD1);
        Append(code, GraphicsLayouts.RastPortFirstDot);
        Append(code, MoveWordD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, intermediateFallbackRelayOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendText(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(32);
        var emptySuccessBranches = new List<int>(1);

        // This is intentionally a narrow native Text body. It handles fixed
        // eight-pixel cells in a standard one-plane bitmap, with JAM1/JAM2,
        // non-inverse COMPLEMENT modes 2/3, INVERSVID modes 4/5, and exact
        // byte-aligned 8/16/24/32/40/48/56/64/72/80/88/96-pixel inter-cell spacing extensions for JAM1.
        // Fixed-cell fonts may use the
        // documented extra default-glyph slot for bytes outside LoChar..HiChar.
        // The portable/provider implementation remains authoritative for
        // proportional fonts, variable cell widths, styles, combined
        // COMPLEMENT|INVERSVID, clipping, and RTG or layered RastPorts.
        Append(code, TestWordD0);
        Append(code, BranchMinusWord);
        var negativeCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(negativeCountBranchExtensionOffset);
        Append(code, BranchEqualWord);
        var emptyCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        emptySuccessBranches.Add(emptyCountBranchExtensionOffset);
        // Keep the shared count envelope wide enough for the fixed-cell
        // 4096-byte source arm, but retain the conservative one-glyph
        // proportional pointer probe. The proportional multi-glyph arm adds
        // its stricter 1024-byte source-wrap check after dispatch, so a valid
        // stream at 0xFFFFFC00 remains claimable here.
        Append(code, CompareImmediateWordD0);
        Append(code, 4096);
        Append(code, BranchHighWord);
        var sourceCountLimitBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceCountLimitBranchExtensionOffset);
        Append(code, MoveLongA0ToD7);
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var sourceNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceNullBranchExtensionOffset);
        Append(code, CompareImmediateLongD7);
        Append(code, 0xFFFF);
        Append(code, 0xFE00); // proportional 512 source bytes remain addressable
        Append(code, BranchHighWord);
        var sourceWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceWrapBranchExtensionOffset);
        // D7 is reused below for byte-sized font flags, so clear the upper
        // 24 bits left by the source-pointer probe before any MOVE.B loads.
        Append(code, MoveQuickZeroD7);

        Append(code, MoveLongA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFont));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var fontBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fontAlignmentBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontAlignmentBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFCC); // TextFontMinimumSize (0x34) envelope
        Append(code, BranchHighWord);
        var fontWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontWrapBranchExtensionOffset);
        Append(code, MoveAddressD1ToA2);

        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD2);
        Append(code, BranchNotEqualWord);
        var layerBranchExtensionOffset = code.Count;
        Append(code, 0);
