        Append(code, MoveQuickZeroD5);
        Append(code, MoveByteA2DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA2DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
        Append(code, CompareByteD5ToD6);
        Append(code, BranchCarryWord);
        var proportionalTwoPreflightLowRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalTwoFallbackBranches.Add(proportionalTwoPreflightLowRangeBranchExtensionOffset);
        Append(code, CompareByteD4ToD6);
        Append(code, BranchHighWord);
        var proportionalTwoPreflightHighRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalTwoFallbackBranches.Add(proportionalTwoPreflightHighRangeBranchExtensionOffset);
        Append(code, SubByteD5ToD6);
        Append(code, ExtendLongD6);
        Append(code, MoveLongD6ToD0);
        Append(code, ShiftLeftLongD0);
        Append(code, ShiftLeftLongD0);
        Append(code, MoveAddressA6ToA2);
        Append(code, MoveLongA2DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharLoc));
        Append(code, MoveAddressD7ToA2);
        Append(code, AddLongD0ToA2);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, 0);
        Append(code, MoveWordA2DisplacementToD5);
        Append(code, 2);
        Append(code, TestWordD5);
        Append(code, BranchEqualWord);
        var proportionalTwoPreflightWidthZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalTwoFallbackBranches.Add(proportionalTwoPreflightWidthZeroBranchExtensionOffset);
        Append(code, CompareImmediateWordD5);
        Append(code, 8);
        Append(code, BranchHighWord);
        var proportionalTwoPreflightWidthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalTwoFallbackBranches.Add(proportionalTwoPreflightWidthRangeBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 7);
        Append(code, BranchHighWord);
        var proportionalTwoPreflightOffsetRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalTwoFallbackBranches.Add(proportionalTwoPreflightOffsetRangeBranchExtensionOffset);
        // A one-byte strike may start at a nonzero bit offset only when the
        // complete glyph remains inside that byte. Compute offset+width in a
        // scratch WORD and retain the original width for the pixel loop.
        Append(code, MoveWordD4ToD6);
        Append(code, NegWordD5);
        Append(code, SubWordD5ToD6);
        Append(code, CompareImmediateWordD6);
        Append(code, 8);
        Append(code, BranchHighWord);
        var proportionalTwoPreflightStrikeSpanBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalTwoFallbackBranches.Add(proportionalTwoPreflightStrikeSpanBranchExtensionOffset);
        Append(code, NegWordD5);
        Append(code, MoveWordD5ToD4);
        Append(code, MoveWordD2ToD6);
        Append(code, AndImmediateWordD6);
        Append(code, 7);
        Append(code, TestWordD6);
        Append(code, BranchNotEqualWord);
        var proportionalTwoPreflightAdvanceAlignmentBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalTwoFallbackBranches.Add(proportionalTwoPreflightAdvanceAlignmentBranchExtensionOffset);
        Append(code, MoveWordD2ToD6);
        Append(code, ShiftRightWordD6Count3);
        Append(code, MoveLongD1ToD4);
        Append(code, CompareWordD4ToD6);
        Append(code, BranchHighWord);
        var proportionalTwoPreflightXValidBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchEqualWord);
        var proportionalTwoPreflightXEqualBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalTwoFallbackBranches.Add(proportionalTwoPreflightXEqualBranchExtensionOffset);
        var proportionalTwoPreflightXValidOffset = code.Count;
        PatchBranch(
            code,
            proportionalTwoPreflightXValidBranchExtensionOffset,
            proportionalTwoPreflightXValidOffset);
        Append(code, ShiftRightLongD0);
        Append(code, MoveAddressA6ToA2);
        Append(code, MoveLongA2DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharSpace));
        Append(code, MoveAddressD7ToA2);
        Append(code, AddLongD0ToA2);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, 0);
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var proportionalTwoPreflightAdvanceZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalTwoFallbackBranches.Add(proportionalTwoPreflightAdvanceZeroBranchExtensionOffset);
        Append(code, CompareImmediateWordD4);
        Append(code, 32);
        Append(code, BranchHighWord);
        var proportionalTwoPreflightAdvanceRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalTwoFallbackBranches.Add(proportionalTwoPreflightAdvanceRangeBranchExtensionOffset);
        Append(code, ExtendLongD4);
        Append(code, MoveLongD4ToD6);
        Append(code, AddLongD6ToD2);
        Append(code, CompareImmediateLongD2);
        Append(code, 0x0000);
        Append(code, 0xFFFF);
        Append(code, BranchHighWord);
        var proportionalTwoPreflightCursorRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalTwoFallbackBranches.Add(proportionalTwoPreflightCursorRangeBranchExtensionOffset);
        Append(code, DecrementBranchD3);
        var proportionalTwoPreflightLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Restore the original source pointer for the rendering pass. The
        // caller's complete D0 remains in A5 until preflight has succeeded;
        // the rendering pass can then reuse A5 as the strike pointer.
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveAddressA6ToA2);
        Append(code, MoveLongA2DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharData));
        Append(code, MoveAddressD7ToA5);
        Append(code, MoveQuickZeroD2);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentX));
        Append(code, MoveLongA4ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0);
        Append(code, 3);
        Append(code, BranchEqualWord);
        var proportionalTwoRenderThreeCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD6);
        Append(code, 0);
        Append(code, 4);
        Append(code, BranchEqualWord);
        var proportionalTwoRenderFourCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD6);
        Append(code, 0);
        Append(code, 4);
        Append(code, BranchHighWord);
        var proportionalTwoRenderWideCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickOneD3);
        Append(code, BranchAlwaysWord);
        var proportionalTwoRenderCountJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        var proportionalTwoRenderFourCountOffset = code.Count;
        Append(code, MoveQuickTwoD3);
        Append(code, AddQuickOneWordD3);
        Append(code, BranchAlwaysWord);
        var proportionalTwoRenderFourCountJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        var proportionalTwoRenderWideCountOffset = code.Count;
        Append(code, MoveLongD6ToD0);
        Append(code, SubQuickOneLongD0);
        Append(code, MoveLongD0ToD3);
        Append(code, BranchAlwaysWord);
        var proportionalTwoRenderWideCountJoinBranchExtensionOffset = code.Count;
        Append(code, 0);
        var proportionalTwoRenderThreeCountOffset = code.Count;
        Append(code, MoveQuickTwoD3);
        var proportionalTwoRenderCountJoinOffset = code.Count;
        PatchBranch(
            code,
            proportionalTwoRenderThreeCountBranchExtensionOffset,
            proportionalTwoRenderThreeCountOffset);
        PatchBranch(
            code,
            proportionalTwoRenderFourCountBranchExtensionOffset,
            proportionalTwoRenderFourCountOffset);
        PatchBranch(
            code,
            proportionalTwoRenderWideCountBranchExtensionOffset,
            proportionalTwoRenderWideCountOffset);
        PatchBranch(
            code,
            proportionalTwoRenderCountJoinBranchExtensionOffset,
            proportionalTwoRenderCountJoinOffset);
        PatchBranch(
            code,
            proportionalTwoRenderFourCountJoinBranchExtensionOffset,
            proportionalTwoRenderCountJoinOffset);
        PatchBranch(
            code,
            proportionalTwoRenderWideCountJoinBranchExtensionOffset,
            proportionalTwoRenderCountJoinOffset);

        var proportionalTwoRenderLoopOffset = code.Count;
        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA0PostIncrementToD6);
        Append(code, MoveAddressA6ToA2);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveByteA2DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, MoveLongD6ToD7);
        Append(code, SubByteD5ToD6);
        Append(code, ExtendLongD6);
        Append(code, MoveLongD6ToD0);
        Append(code, ShiftLeftLongD0);
        Append(code, ShiftLeftLongD0);
        Append(code, MoveAddressA6ToA2);
        Append(code, MoveLongA2DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharLoc));
        Append(code, MoveAddressD7ToA2);
        Append(code, AddLongD0ToA2);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, 0);
        Append(code, MoveWordA2DisplacementToD5);
        Append(code, 2);
        Append(code, ShiftRightLongD0);
        Append(code, MoveAddressA6ToA2);
        Append(code, MoveLongA2DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharSpace));
        Append(code, MoveAddressD7ToA2);
        Append(code, AddLongD0ToA2);
        Append(code, MoveWordA2DisplacementToD5); // D5 = advance
        Append(code, 0);
        Append(code, MoveWordD2ToD6);
        Append(code, ShiftRightWordD6Count3);
        Append(code, ExtendLongD6);
        Append(code, MoveAddressA3ToA4);
        Append(code, AddLongD6ToA4);
        // Preflight has proved offset+width <= 8.  Align the source strike
        // left by the CharLoc offset so the existing MSB-first pixel loop can
        // keep one destination bit cursor (D7) for every glyph.
        Append(code, MoveByteA5IndirectToD6);
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var proportionalTwoRenderOffsetZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, SubQuickOneWordD4);
        var proportionalTwoRenderOffsetShiftLoopOffset = code.Count;
        Append(code, ShiftLeftLongD6);
        Append(code, DecrementBranchD4);
        var proportionalTwoRenderOffsetShiftLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(
            code,
            proportionalTwoRenderOffsetShiftLoopBranchExtensionOffset,
            proportionalTwoRenderOffsetShiftLoopOffset);
        var proportionalTwoRenderOffsetReadyOffset = code.Count;
        PatchBranch(
            code,
            proportionalTwoRenderOffsetZeroBranchExtensionOffset,
            proportionalTwoRenderOffsetReadyOffset);
        Append(code, MoveQuickSevenD7);
        Append(code, MoveWordD5ToD4); // D4 = glyph width
        Append(code, SubQuickOneWordD4);
        var proportionalTwoPixelLoopOffset = code.Count;
        Append(code, BitTestDynamicD7ToD6);
        Append(code, BranchEqualWord);
        var proportionalTwoPixelZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitSetDynamicD7AtA4);
        var proportionalTwoPixelNextOffset = code.Count;
        PatchBranch(code, proportionalTwoPixelZeroBranchExtensionOffset, proportionalTwoPixelNextOffset);
        Append(code, SubQuickOneWordD7);
        Append(code, DecrementBranchD4);
        var proportionalTwoPixelLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, proportionalTwoPixelLoopBranchExtensionOffset, proportionalTwoPixelLoopOffset);
        Append(code, ExtendLongD5);
        Append(code, AddLongD5ToD2);
        Append(code, DecrementBranchD3);
        var proportionalTwoRenderLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveWordD2ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortCurrentX));
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, OrImmediateWordD0);
        Append(code, GraphicsLayouts.RastPortFirstDot);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var proportionalTwoFallbackRestoreOffset = code.Count;
        Append(code, MoveAddressA5ToA0);
        Append(code, MoveLongA4ToD0);
        Append(code, BranchAlwaysWord);
        var proportionalTwoFallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, proportionalTwoPreflightLoopBranchExtensionOffset, proportionalTwoPreflightLoopOffset);
        PatchBranch(code, proportionalTwoRenderLoopBranchExtensionOffset, proportionalTwoRenderLoopOffset);
        foreach (var branchExtensionOffset in proportionalTwoFallbackBranches)
            PatchBranch(code, branchExtensionOffset, proportionalTwoFallbackRestoreOffset);
        PatchBranch(code, proportionalTwoFallbackJumpExtensionOffset, fallbackEntryOffset);

        var proportionalFallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var proportionalFallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        foreach (var branch in sourceBitBranches)
            PatchBranch(code, branch.Extension, branch.Target);
        foreach (var branch in complementBranches)
            PatchBranch(code, branch.Extension, branch.Target);
        foreach (var branch in inverseBranches)
            PatchBranch(code, branch.Extension, branch.Target);
        foreach (var branch in resolvedBranches)
            PatchBranch(code, branch.Extension, branch.Target);
        PatchBranch(code, rowLoopBranchExtensionOffset, rowLoopOffset);
        PatchBranch(code, charLoopBranchExtensionOffset, charLoopOffset);
        PatchBranch(code, zeroSpacingBranchExtensionOffset, spacingValidationOffset);
        PatchBranch(code, spacingTwentyFourAcceptedBranchExtensionOffset, spacingEightAcceptedOffset);
        PatchBranch(code, zeroSpacingWidthBranchExtensionOffset, spacingWidthValidationOffset);
        PatchBranch(code, emptyCountBranchExtensionOffset, emptySuccessOffset);
        PatchBranch(code, drawModeValidationBranchExtensionOffset, drawModeValidationOffset);
        PatchBranch(code, preflightLoopBranchExtensionOffset, preflightLoopOffset);
        PatchBranch(code, proportionalDispatchBranchExtensionOffset, proportionalSelectOffset);
        PatchBranch(code, proportionalSelectOneBranchExtensionOffset, proportionalEntryOffset);
        PatchBranch(code, proportionalSelectTwoBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectThreeBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectFourBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectFiveBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectSixBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectSevenBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectEightBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectNineBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectTenBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectElevenBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectTwelveBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectThirteenBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectFourteenBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectFifteenBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectSixteenBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectSeventeenBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectEighteenBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectNineteenBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectTwentyBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectTwentyOneBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectTwentyTwoBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectTwentyThreeBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectTwentyFourBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectTwentyFiveBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectTwentySixBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectTwentySevenBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectTwentyEightBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectTwentyNineBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectThirtyBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectThirtyOneBranchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectThirtyTwoBranchExtensionOffset, proportionalTwoEntryOffset);
        foreach (var branchExtensionOffset in proportionalSelectExtendedBranchExtensions)
            PatchBranch(code, branchExtensionOffset, proportionalTwoEntryOffset);
        PatchBranch(code, proportionalSelectFallbackBranchExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, proportionalFallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in emptySuccessBranches)
            PatchBranch(code, branchExtensionOffset, emptySuccessOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in proportionalFallbackBranches)
            PatchBranch(code, branchExtensionOffset, proportionalFallbackRestoreOffset);

        return offset;
    }

    private static int AppendTextLength(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var rastPortFallbackBranches = new List<int>(3);
        var successBranches = new List<int>(5);

        // Every native TextLength arm consumes a field from A1, and the
        // widest one reaches the signed TxSpacing WORD at 0x40.  Reject a
        // NULL, odd, or logically wrapping RastPort before preserving any
        // body-local scratch so a decline keeps the original D0/A0 and the
        // complete public callee-save set intact.
        Append(code, MoveLongA1ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        rastPortFallbackBranches.Add(nullRastPortBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        rastPortFallbackBranches.Add(oddRastPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFBE); // Last even base through RP.TxSpacing at 0x40.
        Append(code, BranchHighWord);
        var wrappedRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        rastPortFallbackBranches.Add(wrappedRastPortBranchExtensionOffset);

        // Save original D0 as well as the complete public callee-save set.
        // The proportional default-slot and walk arms reuse D7/A5, so those
        // body shadows cannot provide reliable fallback arguments. A6 is
        // saved before temporarily retaining the original volatile A0.
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0xBF3E); // MOVEM.L D0/D2-D7/A2-A6,-(A7), reversed mask.
        Append(code, MoveAddressA0ToA6);

        // Keep the caller's complete D0 and source pointer available while
        // the selected-font arm decides whether the bounded proportional
        // form can be claimed.  Fixed-cell and NULL-font paths restore D0
        // before using the existing signed-WORD count arithmetic.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveAddressA0ToA5);

        // Fixed-cell TextLength is safe to keep in the native body when the
        // selected TextFont does not advertise FPF_PROPORTIONAL.  A
        // proportional font enters the bounded one-glyph arm below; richer
        // strings and table/provider forms still retain the shared fallback
        // ownership for CharSpace, CharKern, reverse-path, and color-font
        // semantics.
        Append(code, MoveLongA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFont));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFCC); // TextFontMinimumSize (0x34) envelope
        Append(code, BranchHighWord);
        var wrappedFontBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveAddressD1ToA0);
        Append(code, MoveQuickZeroD2);
        Append(code, MoveByteA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.TextFontFlags));
        Append(code, BitTestImmediateD2);
        Append(code, 5); // FPF_PROPORTIONAL
        Append(code, BranchNotEqualWord);
        var proportionalBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveLongD7ToD0);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontXSize));
        Append(code, ExtendLongD1);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextSpacing));
        Append(code, ExtendLongD2);
        Append(code, AddLongD2ToD1);
        Append(code, MultiplySignedWordD0ToD1);
        Append(code, MoveLongD1ToD0);
        Append(code, BranchAlwaysWord);
        var fixedSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        successBranches.Add(fixedSuccessBranchExtensionOffset);

        // Split proportional dispatch before the forward table arm so a
        // bounded reverse-path one-glyph form can claim its signed movement
        // without changing the existing forward-walk ownership.
        var proportionalDispatchOffset = code.Count;
        Append(code, MoveQuickZeroD2);
        Append(code, MoveByteA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.TextFontFlags));
        Append(code, BitTestImmediateD2);
        Append(code, 2); // FPF_REVPATH
        Append(code, BranchNotEqualWord);
        var proportionalReverseDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var proportionalForwardDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Bounded reverse proportional TextLength.  This arm claims one
        // readable byte, complete CharSpace/CharKern table spans, and a
        // negative movement cell.  Richer reverse walks and provider forms
        // remain on the portable owner.
        var proportionalReverseEntryOffset = code.Count;
        var proportionalReverseFallbackBranches = new List<int>(20);
        Append(code, MoveLongD7ToD0);
        Append(code, CompareImmediateWordD0);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var proportionalReverseCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCountBranchExtensionOffset);

        Append(code, MoveLongA5ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var proportionalReverseTextNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseTextNullBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8); // one source byte remains addressable
        Append(code, BranchHighWord);
        var proportionalReverseTextWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseTextWrapBranchExtensionOffset);

        Append(code, MoveQuickZeroD1);
        Append(code, MoveByteA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontStyle));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var proportionalReverseFontStyleBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseFontStyleBranchExtensionOffset);
        Append(code, MoveQuickZeroD1);
        Append(code, MoveByteA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAlgoStyle));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var proportionalReverseAlgoStyleBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseAlgoStyleBranchExtensionOffset);

        Append(code, MoveQuickZeroD5);
        Append(code, MoveByteA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
        Append(code, CompareByteD5ToD4);
        Append(code, BranchCarryWord);
        var proportionalReverseRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseRangeBranchExtensionOffset);

        // A3/A4 retain the two metric table bases while D6 holds the complete
        // declared-range-plus-default span in bytes.
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharSpace));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var proportionalReverseCharSpaceNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharSpaceNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalReverseCharSpaceOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharSpaceOddBranchExtensionOffset);
        Append(code, MoveAddressD1ToA3);

        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharKern));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var proportionalReverseCharKernNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharKernNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalReverseCharKernOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharKernOddBranchExtensionOffset);
        Append(code, MoveAddressD1ToA4);

        Append(code, MoveLongD4ToD6);
        Append(code, SubWordD5ToD6);
        Append(code, AddQuickOneLongD6);
        Append(code, AddQuickOneLongD6);
        Append(code, ShiftLeftLongD6); // table WORD span
        Append(code, MoveLongA3ToD1);
        Append(code, AddLongD6ToD1);
        Append(code, BranchCarryWord);
        var proportionalReverseCharSpaceWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharSpaceWrapBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE);
        Append(code, BranchHighWord);
        var proportionalReverseCharSpaceEndBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharSpaceEndBranchExtensionOffset);

        Append(code, MoveLongA4ToD1);
        Append(code, AddLongD6ToD1);
        Append(code, BranchCarryWord);
        var proportionalReverseCharKernWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharKernWrapBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE);
        Append(code, BranchHighWord);
        var proportionalReverseCharKernEndBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharKernEndBranchExtensionOffset);

        Append(code, MoveByteA5IndirectToD6);
        Append(code, CompareByteD5ToD6);
        Append(code, BranchCarryWord);
        var proportionalReverseDefaultBelowBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareByteD4ToD6);
        Append(code, BranchHighWord);
        var proportionalReverseDefaultAboveBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, SubByteD5ToD6);
        Append(code, BranchAlwaysWord);
        var proportionalReverseMetricJumpExtensionOffset = code.Count;
        Append(code, 0);

        var proportionalReverseDefaultSlotOffset = code.Count;
        Append(code, MoveLongD4ToD6);
        Append(code, SubWordD5ToD6);
        Append(code, AddQuickOneLongD6);

        var proportionalReverseMetricOffset = code.Count;
        Append(code, ShiftLeftLongD6);
        Append(code, MoveAddressA3ToA2);
        Append(code, AddLongD6ToA2);
        Append(code, MoveWordA2ToD1);
        Append(code, ExtendLongD1);
        Append(code, MoveAddressA4ToA2);
        Append(code, AddLongD6ToA2);
        Append(code, MoveWordA2ToD2);
        Append(code, ExtendLongD2);
        Append(code, AddLongD2ToD1);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextSpacing));
        Append(code, ExtendLongD2);
        Append(code, AddLongD2ToD1);
        Append(code, TestLongD1);
        Append(code, BranchMinusWord);
        var proportionalReverseNonNegativeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var proportionalReverseNonNegativeFallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        var proportionalReverseSuccessOffset = code.Count;
        Append(code, MoveLongD1ToD0);
        Append(code, BranchAlwaysWord);
        var proportionalReverseSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        successBranches.Add(proportionalReverseSuccessBranchExtensionOffset);

        var proportionalEntryOffset = code.Count;

        // The first proportional native slice is deliberately one glyph:
        // count=1, any declared character (with its table slot), or the
        // documented extra default-glyph slot for an out-of-range byte. Full
        // table walks and richer kerning/spacing combinations remain on the
        // portable owner.
        var proportionalFallbackBranches = new List<int>(10);
        Append(code, MoveLongD7ToD0);
        Append(code, CompareImmediateWordD0);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var proportionalCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA5ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var proportionalTextNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalTextNullBranchExtensionOffset);

        Append(code, MoveQuickZeroD5);
        Append(code, MoveByteA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
        Append(code, CompareByteD5ToD4);
        Append(code, BranchCarryWord);
        var proportionalRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalRangeBranchExtensionOffset);
        Append(code, MoveQuickZeroD6);
        Append(code, MoveByteA5IndirectToD6);
        Append(code, CompareByteD5ToD6);
        Append(code, BranchCarryWord);
        var proportionalBelowRangeBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BranchEqualWord);
        var proportionalLoCharBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareByteD4ToD6);
        Append(code, BranchHighWord);
        var proportionalAboveRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, SubWordD5ToD6);
        Append(code, ShiftLeftLongD6);
        Append(code, BranchAlwaysWord);
        var proportionalDeclaredSlotBranchExtensionOffset = code.Count;
        Append(code, 0);

        var proportionalLoCharEntryOffset = code.Count;
        Append(code, MoveQuickZeroD6);
        Append(code, BranchAlwaysWord);
        var proportionalLoCharEntryJumpExtensionOffset = code.Count;
        Append(code, 0);

        var proportionalDefaultEntryOffset = code.Count;
        Append(code, MoveQuickZeroD7);
        Append(code, MoveByteA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
        Append(code, SubWordD5ToD7);
        Append(code, AddQuickOneLongD7);
        Append(code, ShiftLeftLongD7);
        Append(code, MoveLongD7ToD6);

        var proportionalTableEntryOffset = code.Count;

        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharSpace));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var proportionalCharSpaceNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharSpaceNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalCharSpaceOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharSpaceOddBranchExtensionOffset);
        Append(code, MoveLongD6ToD0);
        Append(code, AddLongD0ToD1);
        Append(code, BranchCarryWord);
        var proportionalCharSpaceWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharSpaceWrapBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE); // selected table word must remain addressable
        Append(code, BranchHighWord);
        var proportionalCharSpaceEndBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharSpaceEndBranchExtensionOffset);
        Append(code, MoveAddressD1ToA3);

        Append(code, MoveLongA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharKern));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var proportionalCharKernNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharKernNullBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalCharKernOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharKernOddBranchExtensionOffset);
        Append(code, MoveLongD6ToD0);
        Append(code, AddLongD0ToD2);
        Append(code, BranchCarryWord);
        var proportionalCharKernWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharKernWrapBranchExtensionOffset);
        Append(code, CompareImmediateLongD2);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE);
        Append(code, BranchHighWord);
        var proportionalCharKernEndBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharKernEndBranchExtensionOffset);
        Append(code, MoveAddressD2ToA0);

        Append(code, MoveWordA3DisplacementToD5);
        Append(code, 0);
        Append(code, ExtendLongD5);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, 0);
        Append(code, ExtendLongD4);
        Append(code, AddLongD4ToD5);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextSpacing));
        Append(code, ExtendLongD2);
        Append(code, AddLongD2ToD5);
        Append(code, MoveLongD5ToD0);
        Append(code, BranchAlwaysWord);
        var proportionalOneSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        successBranches.Add(proportionalOneSuccessBranchExtensionOffset);

        // A bounded forward proportional walk is the next native slice.  It
        // admits two through two hundred fifty-six characters after the one-glyph arm above;
        // the complete table span is preflighted before the first read so a
        // later glyph cannot leave a partial native result.
        var proportionalWalkEntryOffset = code.Count;
        var proportionalWalkFallbackBranches = new List<int>(16);
        Append(code, MoveLongD7ToD0);
        Append(code, CompareImmediateWordD0);
        Append(code, 1);
        Append(code, BranchLowerOrSameWord);
        var proportionalWalkShortCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalWalkFallbackBranches.Add(proportionalWalkShortCountBranchExtensionOffset);
        Append(code, CompareImmediateWordD0);
        Append(code, 256);
        Append(code, BranchHighWord);
        var proportionalWalkLongCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalWalkFallbackBranches.Add(proportionalWalkLongCountBranchExtensionOffset);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveWordD0ToD3);
        Append(code, MoveLongA5ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var proportionalWalkTextNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalWalkFallbackBranches.Add(proportionalWalkTextNullBranchExtensionOffset);
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFF00); // two hundred fifty-six bytes remain addressable
        Append(code, BranchHighWord);
        var proportionalWalkTextWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalWalkFallbackBranches.Add(proportionalWalkTextWrapBranchExtensionOffset);

        Append(code, MoveQuickZeroD1);
        Append(code, MoveByteA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, MoveQuickZeroD2);
        Append(code, MoveByteA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
        Append(code, MoveLongD1ToD5);
        Append(code, MoveLongD2ToD4);
        Append(code, CompareByteD5ToD4);
        Append(code, BranchCarryWord);
        var proportionalWalkRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalWalkFallbackBranches.Add(proportionalWalkRangeBranchExtensionOffset);

        // CharSpace and CharKern both need the extra default slot, so reject a
        // base whose complete `(range + 1) * 2` WORD span cannot be addressed.
        Append(code, MoveLongD2ToD5);
        Append(code, SubWordD1ToD5);
        Append(code, AddQuickOneLongD5);
        Append(code, ShiftLeftLongD5);
        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharSpace));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var proportionalWalkCharSpaceNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalWalkFallbackBranches.Add(proportionalWalkCharSpaceNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalWalkCharSpaceOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalWalkFallbackBranches.Add(proportionalWalkCharSpaceOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, AddLongD5ToD6);
        Append(code, BranchCarryWord);
        var proportionalWalkCharSpaceWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalWalkFallbackBranches.Add(proportionalWalkCharSpaceWrapBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE);
        Append(code, BranchHighWord);
        var proportionalWalkCharSpaceEndBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalWalkFallbackBranches.Add(proportionalWalkCharSpaceEndBranchExtensionOffset);
        Append(code, MoveAddressD0ToA3);

        Append(code, MoveLongA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharKern));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var proportionalWalkCharKernNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalWalkFallbackBranches.Add(proportionalWalkCharKernNullBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalWalkCharKernOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalWalkFallbackBranches.Add(proportionalWalkCharKernOddBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, AddLongD5ToD6);
        Append(code, BranchCarryWord);
        var proportionalWalkCharKernWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalWalkFallbackBranches.Add(proportionalWalkCharKernWrapBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFE);
        Append(code, BranchHighWord);
        var proportionalWalkCharKernEndBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalWalkFallbackBranches.Add(proportionalWalkCharKernEndBranchExtensionOffset);
        Append(code, MoveAddressD0ToA0);

        Append(code, MoveQuickZeroD4); // accumulated signed movement
        Append(code, MoveQuickZeroD7); // first-glyph flag

        var proportionalWalkLoopOffset = code.Count;
        Append(code, MoveByteA5IndirectToD6);
        Append(code, MoveLongA5ToD0);
        Append(code, AddQuickOneLongD0);
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveLongD1ToD5);
        Append(code, CompareByteD5ToD6);
        Append(code, BranchCarryWord);
        var proportionalWalkDefaultBelowBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchEqualWord);
        var proportionalWalkDeclaredZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD2ToD5);
        Append(code, CompareByteD5ToD6);
        Append(code, BranchHighWord);
        var proportionalWalkDefaultAboveBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD1ToD5);
        Append(code, SubWordD5ToD6);
        Append(code, ShiftLeftLongD6);
        Append(code, MoveLongD6ToD5);
        Append(code, BranchAlwaysWord);
        var proportionalWalkTableBranchExtensionOffset = code.Count;
        Append(code, 0);

        var proportionalWalkDeclaredZeroOffset = code.Count;
        Append(code, MoveQuickZeroD5);
        Append(code, BranchAlwaysWord);
        var proportionalWalkDeclaredZeroJumpExtensionOffset = code.Count;
        Append(code, 0);

        var proportionalWalkDefaultOffset = code.Count;
        Append(code, MoveLongD2ToD5);
        Append(code, SubWordD1ToD5);
        Append(code, AddQuickOneLongD5);
        Append(code, ShiftLeftLongD5);

        var proportionalWalkTableOffset = code.Count;
        Append(code, MoveAddressA3ToA2);
        Append(code, AddLongD5ToA2);
        Append(code, MoveWordA2ToD6);
        Append(code, ExtendLongD6);
        Append(code, AddLongD6ToD4);
        Append(code, MoveAddressA0ToA2);
        Append(code, AddLongD5ToA2);
        Append(code, MoveWordA2ToD6);
        Append(code, ExtendLongD6);
        Append(code, TestLongD7);
        Append(code, BranchNotEqualWord);
        var proportionalWalkAddFirstKernBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, TestLongD6);
        Append(code, BranchMinusWord);
        var proportionalWalkSkipFirstKernBranchExtensionOffset = code.Count;
        Append(code, 0);

        var proportionalWalkAddKernOffset = code.Count;
        Append(code, AddLongD6ToD4);
        var proportionalWalkAfterKernOffset = code.Count;
        Append(code, MoveWordA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextSpacing));
        Append(code, ExtendLongD6);
        Append(code, AddLongD6ToD4);
        Append(code, MoveQuickOneD7);
        Append(code, SubQuickOneWordD3);
        Append(code, BranchNotEqualWord);
        var proportionalWalkLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD4ToD0);
        Append(code, BranchAlwaysWord);
        var proportionalWalkSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        successBranches.Add(proportionalWalkSuccessBranchExtensionOffset);

        var proportionalFallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var proportionalFallbackJumpExtensionOffset = code.Count;
        Append(code, 0);


        var nullEntryOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextWidth));
        Append(code, ExtendLongD1);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextSpacing));
        Append(code, ExtendLongD2);
        Append(code, AddLongD2ToD1);
        Append(code, MultiplySignedWordD0ToD1);
        Append(code, MoveLongD1ToD0);
        Append(code, BranchAlwaysWord);
        var nullSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        successBranches.Add(nullSuccessBranchExtensionOffset);

        var successRestoreOffset = code.Count;
        Append(code, MoveLongD0ToD1);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFD); // MOVEM.L (A7)+,D0/D2-D7/A2-A6.
        Append(code, MoveLongD1ToD0);
        Append(code, ReturnFromSubroutine);

        var declineRestoreOffset = code.Count;
        Append(code, MoveAddressA6ToA0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFD); // Restore original D0/A6 and every callee-save register.
        Append(code, BranchAlwaysWord);
        var declineFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);

        // The 68000 branch base is the address immediately after the opcode;
        // the extension word is fetched from that address and the signed
        // displacement is still added to the opcode-end PC.
        var nullBranchDisplacement = checked(nullEntryOffset - nullBranchExtensionOffset);
        if (nullBranchDisplacement < short.MinValue || nullBranchDisplacement > short.MaxValue)
            throw new InvalidOperationException("Native TextLength fallback is out of branch range.");

        code[nullBranchExtensionOffset] = (byte)((ushort)nullBranchDisplacement >> 8);
        code[nullBranchExtensionOffset + 1] = (byte)nullBranchDisplacement;

        var proportionalBranchDisplacement = checked(proportionalDispatchOffset - proportionalBranchExtensionOffset);
        if (proportionalBranchDisplacement < short.MinValue || proportionalBranchDisplacement > short.MaxValue)
            throw new InvalidOperationException("Native TextLength proportional arm is out of branch range.");

        code[proportionalBranchExtensionOffset] = (byte)((ushort)proportionalBranchDisplacement >> 8);
        code[proportionalBranchExtensionOffset + 1] = (byte)proportionalBranchDisplacement;
        PatchBranch(code, proportionalReverseDispatchBranchExtensionOffset, proportionalReverseEntryOffset);
        PatchBranch(code, proportionalForwardDispatchBranchExtensionOffset, proportionalEntryOffset);
        PatchBranch(code, proportionalReverseMetricJumpExtensionOffset, proportionalReverseMetricOffset);
        PatchBranch(code, proportionalReverseDefaultBelowBranchExtensionOffset, proportionalReverseDefaultSlotOffset);
        PatchBranch(code, proportionalReverseDefaultAboveBranchExtensionOffset, proportionalReverseDefaultSlotOffset);
        PatchBranch(code, proportionalReverseNonNegativeBranchExtensionOffset, proportionalReverseSuccessOffset);
        PatchBranch(code, proportionalReverseNonNegativeFallbackJumpExtensionOffset, proportionalFallbackRestoreOffset);
        PatchBranch(code, oddFontBranchExtensionOffset, declineRestoreOffset);
        PatchBranch(code, wrappedFontBranchExtensionOffset, declineRestoreOffset);
        PatchBranch(code, proportionalCountBranchExtensionOffset, proportionalWalkEntryOffset);
        PatchBranch(code, proportionalBelowRangeBranchExtensionOffset, proportionalDefaultEntryOffset);
        PatchBranch(code, proportionalAboveRangeBranchExtensionOffset, proportionalDefaultEntryOffset);
        PatchBranch(code, proportionalLoCharBranchExtensionOffset, proportionalLoCharEntryOffset);
        PatchBranch(code, proportionalDeclaredSlotBranchExtensionOffset, proportionalTableEntryOffset);
        PatchBranch(code, proportionalLoCharEntryJumpExtensionOffset, proportionalTableEntryOffset);
        PatchBranch(code, proportionalWalkDeclaredZeroBranchExtensionOffset, proportionalWalkDeclaredZeroOffset);
        PatchBranch(code, proportionalWalkDefaultBelowBranchExtensionOffset, proportionalWalkDefaultOffset);
        PatchBranch(code, proportionalWalkDefaultAboveBranchExtensionOffset, proportionalWalkDefaultOffset);
        PatchBranch(code, proportionalWalkTableBranchExtensionOffset, proportionalWalkTableOffset);
        PatchBranch(code, proportionalWalkDeclaredZeroJumpExtensionOffset, proportionalWalkTableOffset);
        PatchBranch(code, proportionalWalkAddFirstKernBranchExtensionOffset, proportionalWalkAddKernOffset);
        PatchBranch(code, proportionalWalkSkipFirstKernBranchExtensionOffset, proportionalWalkAfterKernOffset);
        PatchBranch(code, proportionalWalkLoopBranchExtensionOffset, proportionalWalkLoopOffset);
        foreach (var branchExtensionOffset in proportionalWalkFallbackBranches)
            PatchBranch(code, branchExtensionOffset, proportionalFallbackRestoreOffset);
        PatchBranch(code, proportionalFallbackJumpExtensionOffset, declineRestoreOffset);
        foreach (var branchExtensionOffset in proportionalFallbackBranches)
            PatchBranch(code, branchExtensionOffset, proportionalFallbackRestoreOffset);
        foreach (var branchExtensionOffset in proportionalReverseFallbackBranches)
            PatchBranch(code, branchExtensionOffset, proportionalFallbackRestoreOffset);
        foreach (var branchExtensionOffset in successBranches)
            PatchBranch(code, branchExtensionOffset, successRestoreOffset);
        PatchBranch(code, declineFallbackBranchExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in rastPortFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendTextExtent(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var rastPortFallbackBranches = new List<int>(3);
        var successBranches = new List<int>(3);

        // Every TextExtent arm consumes A1, with the widest read reaching the
        // signed TxSpacing WORD at 0x40. Reject NULL, odd and logically
        // wrapping RastPorts before the existing D7/A3 body captures so an
        // admission decline remains a complete original-call tail chain.
        Append(code, MoveLongA1ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        rastPortFallbackBranches.Add(nullRastPortBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        rastPortFallbackBranches.Add(oddRastPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFBE); // Last even base through RP.TxSpacing at 0x40.
        Append(code, BranchHighWord);
        var wrappedRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        rastPortFallbackBranches.Add(wrappedRastPortBranchExtensionOffset);

        // Save the original count/source plus the complete public callee-save
        // set once A1 has passed admission.  The proportional paths reuse all
        // of D2-D7/A2-A6, while the reverse arm nests one private A2 pointer on
        // A7; its early/late restores are balanced before this outer frame is
        // unwound.  Retaining volatile A0 also keeps successful native calls
        // observationally identical to the public graphics.library entry.
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
