        var proportionalReverseCharSpaceOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseLateFallbackBranches.Add(proportionalReverseCharSpaceOddBranchExtensionOffset);
        Append(code, MoveAddressD1ToA5);

        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharKern));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var proportionalReverseCharKernNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseLateFallbackBranches.Add(proportionalReverseCharKernNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalReverseCharKernOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseLateFallbackBranches.Add(proportionalReverseCharKernOddBranchExtensionOffset);
        Append(code, MoveAddressD1ToA6);

        // Validate all table spans before reading the selected slot.  D5 is
        // the total slot count; the three end-address checks are unsigned and
        // therefore also catch 32-bit wraparound.
        Append(code, MoveLongD5ToD6);
        Append(code, ShiftLeftLongD6);
        Append(code, ShiftLeftLongD6);
        Append(code, MoveLongA4ToD1);
        Append(code, AddLongD6ToD1);
        Append(code, BranchCarryWord);
        var proportionalReverseCharLocWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseLateFallbackBranches.Add(proportionalReverseCharLocWrapBranchExtensionOffset);

        Append(code, MoveLongD5ToD6);
        Append(code, ShiftLeftLongD6);
        Append(code, MoveLongA5ToD1);
        Append(code, AddLongD6ToD1);
        Append(code, BranchCarryWord);
        var proportionalReverseCharSpaceWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseLateFallbackBranches.Add(proportionalReverseCharSpaceWrapBranchExtensionOffset);

        Append(code, MoveLongD5ToD6);
        Append(code, ShiftLeftLongD6);
        Append(code, MoveLongA6ToD1);
        Append(code, AddLongD6ToD1);
        Append(code, BranchCarryWord);
        var proportionalReverseCharKernWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseLateFallbackBranches.Add(proportionalReverseCharKernWrapBranchExtensionOffset);

        Append(code, MoveByteA3IndirectToD6);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, CompareByteD4ToD6);
        Append(code, BranchCarryWord);
        var proportionalReverseDefaultBelowBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
        Append(code, CompareByteD4ToD6);
        Append(code, BranchHighWord);
        var proportionalReverseDefaultAboveBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Declared slot: (character-LoChar).  The default branches below use
        // the extra slot at (HiChar-LoChar+1).
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, MoveLongD6ToD1);
        Append(code, SubLongD3ToD1);
        Append(code, BranchAlwaysWord);
        var proportionalReverseMetricJumpExtensionOffset = code.Count;
        Append(code, 0);

        var proportionalReverseDefaultSlotOffset = code.Count;
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, MoveLongD4ToD1);
        Append(code, SubLongD3ToD1);
        Append(code, NegLongD1);
        Append(code, AddQuickOneLongD1);

        var proportionalReverseMetricReadOffset = code.Count;
        Append(code, MoveLongD1ToD5);
        Append(code, ShiftLeftLongD5);
        Append(code, MoveAddressA5ToA2);
        Append(code, AddLongD5ToA2);
        Append(code, MoveWordA2ToD6);
        Append(code, ExtendLongD6);
        Append(code, MoveAddressA6ToA2);
        Append(code, AddLongD5ToA2);
        Append(code, MoveWordA2ToD2);
        Append(code, ExtendLongD2);
        Append(code, AddLongD2ToD6);
        Append(code, MoveWordA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextSpacing));
        Append(code, ExtendLongD1);
        Append(code, AddLongD1ToD6);
        Append(code, TestLongD6);
        Append(code, BranchMinusWord);
        var proportionalReverseNonNegativeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0x8000); // signed WORD lower bound
        Append(code, BranchCarryWord);
        var proportionalReverseWidthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseLateFallbackBranches.Add(proportionalReverseWidthRangeBranchExtensionOffset);

        // Restore A2 from the transaction stack and publish the signed
        // movement envelope.  MaxX is the final pixel edge (-1), while MinX
        // and Width carry the negative reverse movement.
        var proportionalReversePublicationOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontYSize));
        Append(code, BitTestImmediateD4);
        Append(code, 15);
        Append(code, BranchNotEqualWord);
        var proportionalReverseHeightRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseEarlyFallbackBranches.Add(proportionalReverseHeightRangeBranchExtensionOffset);
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var proportionalReverseHeightZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseEarlyFallbackBranches.Add(proportionalReverseHeightZeroBranchExtensionOffset);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.TextFontBaseline));
        Append(code, BitTestImmediateD5);
        Append(code, 15);
        Append(code, BranchNotEqualWord);
        var proportionalReverseBaselineRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseEarlyFallbackBranches.Add(proportionalReverseBaselineRangeBranchExtensionOffset);
        Append(code, CompareWordD5ToD4);
        Append(code, BranchLowerOrSameWord);
        var proportionalReverseBaselineEnvelopeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseEarlyFallbackBranches.Add(proportionalReverseBaselineEnvelopeBranchExtensionOffset);

        Append(code, MoveWordD6ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentWidth));
        Append(code, MoveWordD4ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentHeight));
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinX));
        Append(code, MoveQuickMinusOneD0);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxX));
        Append(code, MoveLongD4ToD0);
        Append(code, MoveLongD5ToD2);
        Append(code, SubWordD2ToD0);
        Append(code, SubQuickOneWordD0);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxY));
        Append(code, NegWordD5);
        Append(code, MoveWordD5ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinY));
        Append(code, MoveQuickZeroD0);
        Append(code, BranchAlwaysWord);
        var proportionalReverseSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);
        successBranches.Add(proportionalReverseSuccessBranchExtensionOffset);

        var proportionalReverseLateFallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var proportionalReverseLateFallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        var proportionalFallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var proportionalFallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        var successRestoreOffset = code.Count;
        Append(code, MoveLongD0ToD1);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7DFD); // MOVEM.L (A7)+,D0/D2-D7/A0/A2-A6.
        Append(code, MoveLongD1ToD0);
        Append(code, ReturnFromSubroutine);

        var declineRestoreOffset = code.Count;
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7DFD); // Restore original D0/A0 and every callee-save register.
        Append(code, BranchAlwaysWord);
        var declineFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, proportionalDeclaredSlotJumpExtensionOffset, proportionalMetricReadOffset);
        PatchBranch(code, proportionalDefaultBelowBranchExtensionOffset, proportionalDefaultSlotOffset);
        PatchBranch(code, proportionalDefaultAboveBranchExtensionOffset, proportionalDefaultSlotOffset);
        PatchBranch(code, proportionalLoopBranchExtensionOffset, proportionalLoopOffset);
        PatchBranch(code, proportionalFallbackJumpExtensionOffset, declineRestoreOffset);
        foreach (var branchExtensionOffset in proportionalFallbackBranches)
            PatchBranch(code, branchExtensionOffset, proportionalFallbackRestoreOffset);

        PatchBranch(code, proportionalReversePathBranchExtensionOffset, proportionalReverseEntryOffset);
        PatchBranch(code, proportionalReverseMetricJumpExtensionOffset, proportionalReverseMetricReadOffset);
        PatchBranch(code, proportionalReverseDefaultBelowBranchExtensionOffset, proportionalReverseDefaultSlotOffset);
        PatchBranch(code, proportionalReverseDefaultAboveBranchExtensionOffset, proportionalReverseDefaultSlotOffset);
        PatchBranch(code, proportionalReverseNonNegativeBranchExtensionOffset, proportionalReversePublicationOffset);
        PatchBranch(code, proportionalReverseLateFallbackJumpExtensionOffset, proportionalFallbackRestoreOffset);
        foreach (var branchExtensionOffset in proportionalReverseEarlyFallbackBranches)
            PatchBranch(code, branchExtensionOffset, proportionalFallbackRestoreOffset);
        foreach (var branchExtensionOffset in proportionalReverseLateFallbackBranches)
            PatchBranch(code, branchExtensionOffset, proportionalReverseLateFallbackRestoreOffset);

        PatchBranch(code, nullBranchExtensionOffset, declineRestoreOffset);

        var proportionalBranchDisplacement = checked(proportionalEntryOffset - proportionalBranchExtensionOffset);
        if (proportionalBranchDisplacement < short.MinValue || proportionalBranchDisplacement > short.MaxValue)
            throw new InvalidOperationException("Native TextExtent proportional arm is out of branch range.");

        code[proportionalBranchExtensionOffset] = (byte)((ushort)proportionalBranchDisplacement >> 8);
        code[proportionalBranchExtensionOffset + 1] = (byte)proportionalBranchDisplacement;
        PatchBranch(code, oddFontBranchExtensionOffset, declineRestoreOffset);
        PatchBranch(code, wrappedFontBranchExtensionOffset, declineRestoreOffset);
        foreach (var branchExtensionOffset in successBranches)
            PatchBranch(code, branchExtensionOffset, successRestoreOffset);
        PatchBranch(code, declineFallbackBranchExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in rastPortFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendFontExtent(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var preAdmissionFallbackBranches = new List<int>(6);
        var fallbackBranches = new List<int>(12);
        var successBranches = new List<int>(4);

        // Keep this native FontExtent slice deliberately narrow: a bounded
        // declared fixed-cell range, with an optional FPF_REVPATH envelope,
        // and no proportional/CharSpace/CharKern tables. The portable/provider
        // owner retains the full variable-width and kerning envelope.
        // Admit the complete A0 TextFont prefix and packed A1 result before
        // capturing original D0 in callee-saved D7.  These early exits can
        // therefore tail-chain with the caller's complete public frame intact.
        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(nullFontBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddFontBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFCC); // TextFontMinimumSize (0x34) envelope
        Append(code, BranchHighWord);
        var wrappedFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedFontBranchExtensionOffset);

        Append(code, MoveLongA1ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullExtentBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(nullExtentBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddExtentBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddExtentBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // Last even base through the 12-byte TextExtent.
        Append(code, BranchHighWord);
        var wrappedExtentBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedExtentBranchExtensionOffset);

        // Once both public pointers are admitted, save original D0/A0 and the
        // complete callee-save set.  D2 must start as initialized scratch:
        // subsequent MOVE.B Flags/LoChar loads otherwise inherit caller bits
        // 8..15 and can change the declared-range decision.
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0xBFBE); // MOVEM.L D0/D2-D7/A0/A2-A6,-(A7), reversed mask.
        Append(code, MoveQuickZeroD2);

        Append(code, MoveByteA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.TextFontFlags));
        Append(code, BitTestImmediateD2);
        Append(code, 2); // FPF_REVPATH
        Append(code, BranchEqualWord);
        var forwardPathMarkerBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickMinusOneD6); // fixed-cell reverse-path marker
        Append(code, BranchAlwaysWord);
        var reversePathMarkerContinueBranchExtensionOffset = code.Count;
        Append(code, 0);
        var forwardPathMarkerOffset = code.Count;
        Append(code, MoveQuickZeroD6); // fixed-cell forward marker
        var pathMarkerContinueOffset = code.Count;
        PatchBranch(code, forwardPathMarkerBranchExtensionOffset, forwardPathMarkerOffset);
        PatchBranch(code, reversePathMarkerContinueBranchExtensionOffset, pathMarkerContinueOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 5); // FPF_PROPORTIONAL
        Append(code, BranchNotEqualWord);
        var proportionalBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharSpace));
        Append(code, TestLongD5);
        Append(code, BranchNotEqualWord);
        var charSpaceBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(charSpaceBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharKern));
        Append(code, TestLongD5);
        Append(code, BranchNotEqualWord);
        var charKernBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(charKernBranchExtensionOffset);

        Append(code, MoveByteA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
        Append(code, CompareWordD2ToD3);
        Append(code, BranchCarryWord);
        var rangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rangeBranchExtensionOffset);
        // A fixed-cell FontExtent envelope is independent of the individual
        // declared glyph bytes. Keep the native walk bounded while leaving
        // proportional and richer table forms to the owner.
        Append(code, MoveWordD3ToD5);
        Append(code, SubWordD2ToD5);
        Append(code, AddQuickOneWordD5);
        Append(code, CompareImmediateWordD5);
        Append(code, 8);
        Append(code, BranchHighWord);
        var rangeLimitBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(rangeLimitBranchExtensionOffset);

        Append(code, MoveWordA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.TextFontYSize));
        Append(code, TestWordD2);
        Append(code, BranchMinusWord);
        var heightSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(heightSignBranchExtensionOffset);
        Append(code, BranchEqualWord);
        var heightZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(heightZeroBranchExtensionOffset);

        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontXSize));
        Append(code, TestWordD4);
        Append(code, BranchMinusWord);
        var widthSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthSignBranchExtensionOffset);
        Append(code, BranchEqualWord);
        var widthZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthZeroBranchExtensionOffset);

        Append(code, MoveWordA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontBaseline));
        Append(code, TestWordD3);
        Append(code, BranchMinusWord);
        var baselineSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(baselineSignBranchExtensionOffset);

        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var reverseFixedEnvelopeBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveWordD4ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentWidth));
        Append(code, MoveWordD2ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentHeight));
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinX));
        Append(code, MoveWordD3ToD5);
        Append(code, NegWordD3);
        Append(code, MoveWordD3ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinY));
        Append(code, SubQuickOneWordD4);
        Append(code, MoveWordD4ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxX));
        Append(code, SubWordD5ToD2);
        Append(code, SubQuickOneWordD2);
        Append(code, MoveWordD2ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxY));
        Append(code, MoveQuickZeroD0);
        AppendSuccessBranch(code, successBranches);

        var reverseFixedEnvelopeOffset = code.Count;
        Append(code, MoveWordD4ToD5); // retain nominal cell width
        Append(code, NegWordD5);
        Append(code, MoveWordD2ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentHeight));
        Append(code, MoveWordD5ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentWidth));
        Append(code, MoveWordD5ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinX));
        Append(code, MoveWordD2ToD4);
        Append(code, SubWordD3ToD4);
        Append(code, SubQuickOneWordD4);
        Append(code, MoveWordD4ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxY));
        Append(code, NegWordD3);
        Append(code, MoveWordD3ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinY));
        Append(code, MoveQuickMinusOneD0);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxX));
        Append(code, MoveQuickZeroD0);
        AppendSuccessBranch(code, successBranches);

        // Consume the reverse marker only after the proportional flag has
        // selected that arm. Fixed-cell reverse output is handled above;
        // proportional reverse remains on the shared provider/native owner.
        var proportionalDirectionCheckOffset = code.Count;
        Append(code, TestLongD6);
        Append(code, BranchNotEqualWord);
        var reverseProportionalBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var proportionalDirectionContinueBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A bounded proportional reverse-path FontExtent arm.  FontExtent
        // publishes the font-wide movement envelope, but this native slice
        // deliberately claims only a one-character declared range.  The
        // complete declared-plus-default table spans are still proven before
        // the selected negative movement cell is read; larger ranges and
        // richer glyph/provider ownership remain on the portable owner.
        var proportionalReverseEntryOffset = code.Count;
        var proportionalReverseFallbackBranches = new List<int>(16);

        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
        Append(code, CompareByteD4ToD3);
        Append(code, BranchNotEqualWord);
        var proportionalReverseRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseRangeBranchExtensionOffset);

        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontStyle));
        Append(code, TestByteD4);
        Append(code, BranchNotEqualWord);
        var proportionalReverseStyleBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseStyleBranchExtensionOffset);

        // A one-declared-glyph font has two WORD metric slots (declared plus
        // default) and two LONG CharLoc entries.  Reject odd, NULL, or
        // wrapping table bases before any metric read.
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharLoc));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var proportionalReverseCharLocNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharLocNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalReverseCharLocOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharLocOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8); // two LONG entries remain addressable
        Append(code, BranchHighWord);
        var proportionalReverseCharLocWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharLocWrapBranchExtensionOffset);
        Append(code, MoveAddressD1ToA2);
        Append(code, MoveLongA2IndirectToD1);
        Append(code, AddQuickFourLongA2);
        Append(code, MoveLongA2IndirectToD1);

        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharSpace));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var proportionalReverseCharSpaceNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharSpaceNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalReverseCharSpaceOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharSpaceOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // two WORD entries remain addressable
        Append(code, BranchHighWord);
        var proportionalReverseCharSpaceWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharSpaceWrapBranchExtensionOffset);
        Append(code, MoveAddressD1ToA2);
        Append(code, MoveWordA2ToD1);
        Append(code, ExtendLongD1);
        Append(code, MoveLongD1ToD0);

        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharKern));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var proportionalReverseCharKernNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharKernNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalReverseCharKernOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharKernOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var proportionalReverseCharKernWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharKernWrapBranchExtensionOffset);
        Append(code, MoveAddressD1ToA3);
        Append(code, MoveWordA3DisplacementToD5);
        Append(code, 0);
        Append(code, ExtendLongD5);
        Append(code, AddLongD5ToD0);
        Append(code, TestLongD0);
        Append(code, BranchMinusWord);
        var proportionalReverseNegativeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var proportionalReverseNonNegativeJumpExtensionOffset = code.Count;
        Append(code, 0);

        var proportionalReverseVerticalValidationOffset = code.Count;

        // Keep the vertical envelope identical to the other native
        // FontExtent arms and reject a malformed baseline before publishing.
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontYSize));
        Append(code, TestWordD4);
        Append(code, BranchMinusWord);
        var proportionalReverseHeightSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseHeightSignBranchExtensionOffset);
        Append(code, BranchEqualWord);
        var proportionalReverseHeightZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseHeightZeroBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontBaseline));
        Append(code, TestWordD3);
        Append(code, BranchMinusWord);
        var proportionalReverseBaselineSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseBaselineSignBranchExtensionOffset);
        Append(code, MoveWordD3ToD5);
        Append(code, CompareWordD5ToD4);
        Append(code, BranchLowerOrSameWord);
        var proportionalReverseBaselineEnvelopeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseBaselineEnvelopeBranchExtensionOffset);

        // D0 is the signed reverse movement.  Keep it in D6 while the
        // complete 12-byte result envelope is written.
        Append(code, MoveLongD0ToD6);
        Append(code, MoveWordD4ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentHeight));
        Append(code, MoveWordD6ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentWidth));
        Append(code, MoveWordD6ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinX));
        Append(code, MoveWordD3ToD5);
        Append(code, NegWordD5);
        Append(code, MoveWordD5ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinY));
        Append(code, MoveWordD4ToD5);
        Append(code, SubWordD3ToD5);
        Append(code, SubQuickOneWordD5);
        Append(code, MoveWordD5ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxY));
        Append(code, MoveQuickMinusOneD0);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxX));
        Append(code, MoveQuickZeroD0);
        AppendSuccessBranch(code, successBranches);

        // The first proportional FontExtent slice is deliberately bounded:
        // walk one through eight declared entries, prove all three explicit
        // tables are readable, and publish their maximum positive movement
        // as a movement-cell envelope.  Glyph ink bounds, reverse-path and
        // styled/provider forms remain on the shared owner.
        var proportionalEntryOffset = code.Count;
        var proportionalFallbackBranches = new List<int>(32);

        Append(code, MoveAddressA0ToA6);

        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontStyle));
        Append(code, TestByteD4);
        Append(code, BranchNotEqualWord);
        var proportionalStyleBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalStyleBranchExtensionOffset);

        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
        Append(code, CompareByteD4ToD3);
        Append(code, BranchCarryWord);
        var proportionalRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalRangeBranchExtensionOffset);

        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordD3ToD5);
        Append(code, SubWordD4ToD5);
        Append(code, AddQuickOneWordD5);
        Append(code, CompareImmediateWordD5);
        Append(code, 8);
        Append(code, BranchHighWord);
        var proportionalRangeLimitBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalRangeLimitBranchExtensionOffset);
        Append(code, MoveLongD5ToD7); // retain declared count across baseline scratch
        Append(code, AddQuickOneLongD0); // include the proportional default slot

        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharLoc));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var proportionalCharLocNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharLocNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalCharLocOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharLocOddBranchExtensionOffset);
        Append(code, MoveAddressD1ToA3);

        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharSpace));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var proportionalCharSpaceNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharSpaceNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalCharSpaceOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharSpaceOddBranchExtensionOffset);
        Append(code, MoveAddressD1ToA4);

        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharKern));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var proportionalCharKernNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharKernNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalCharKernOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharKernOddBranchExtensionOffset);
        Append(code, MoveAddressD1ToA5);

        Append(code, MoveAddressA3ToA0);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharLoc));
        Append(code, MoveAddressD1ToA0);

        Append(code, MoveLongD5ToD4);
        Append(code, ShiftLeftLongD4);
        Append(code, ShiftLeftLongD4);
        Append(code, MoveLongA3ToD6);
        Append(code, AddLongD4ToD6);
        Append(code, BranchCarryWord);
        var proportionalCharLocWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharLocWrapBranchExtensionOffset);

        Append(code, MoveLongD5ToD4);
        Append(code, ShiftLeftLongD4);
        Append(code, MoveLongA4ToD6);
        Append(code, AddLongD4ToD6);
        Append(code, BranchCarryWord);
        var proportionalCharSpaceWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharSpaceWrapBranchExtensionOffset);

        Append(code, MoveLongD5ToD4);
        Append(code, ShiftLeftLongD4);
        Append(code, MoveLongA5ToD6);
        Append(code, AddLongD4ToD6);
        Append(code, BranchCarryWord);
        var proportionalCharKernWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalCharKernWrapBranchExtensionOffset);

        Append(code, MoveAddressA6ToA0);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontYSize));
        Append(code, TestWordD4);
        Append(code, BranchMinusWord);
        var proportionalHeightSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalHeightSignBranchExtensionOffset);
        Append(code, BranchEqualWord);
        var proportionalHeightZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalHeightZeroBranchExtensionOffset);

        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.TextFontBaseline));
        Append(code, TestWordD5);
        Append(code, BranchMinusWord);
        var proportionalBaselineSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalBaselineSignBranchExtensionOffset);
        Append(code, CompareWordD5ToD4);
        Append(code, BranchLowerOrSameWord);
        var proportionalBaselineEnvelopeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalBaselineEnvelopeBranchExtensionOffset);

        Append(code, MoveQuickZeroD6);

        var proportionalLoopOffset = code.Count;
        Append(code, MoveAddressA3ToA2);
        Append(code, MoveLongA2PostIncrementToD4);
        Append(code, MoveAddressA4ToA2);
        Append(code, MoveWordA2ToD1);
        Append(code, ExtendLongD1);
        Append(code, MoveAddressA5ToA2);
        Append(code, MoveWordA2ToD2);
        Append(code, ExtendLongD2);
        Append(code, AddLongD1ToD2);
        Append(code, TestLongD2);
        Append(code, BranchMinusWord);
        var proportionalMovementSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalMovementSignBranchExtensionOffset);
        Append(code, CompareLongD6ToD2);
        Append(code, BranchHighWord);
        var proportionalMovementKeepBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var proportionalMovementAfterUpdateBranchExtensionOffset = code.Count;
        Append(code, 0);
        var proportionalMovementUpdateOffset = code.Count;
        Append(code, MoveLongD2ToD6);
        var proportionalMovementAfterUpdateOffset = code.Count;

        Append(code, AddQuickFourLongA3);
        Append(code, AddQuickTwoLongA4);
        Append(code, AddQuickTwoLongA5);
        Append(code, SubQuickOneWordD7);
        Append(code, BranchNotEqualWord);
        var proportionalLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveAddressA6ToA0);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontYSize));
        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.TextFontBaseline));

        Append(code, CompareImmediateLongD6);
        Append(code, 0x0000);
        Append(code, 0x8000);
        Append(code, BranchHighWord);
        var proportionalWidthLimitBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalWidthLimitBranchExtensionOffset);

        Append(code, MoveWordD6ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentWidth));
        Append(code, MoveWordD4ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentHeight));
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinX));
        Append(code, MoveLongD4ToD2);
        Append(code, SubWordD5ToD2);
        Append(code, SubQuickOneWordD2);
        Append(code, MoveWordD2ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxY));
        Append(code, NegWordD5);
        Append(code, MoveWordD5ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinY));
        Append(code, MoveLongD6ToD2);
        Append(code, SubQuickOneLongD2);
        Append(code, MoveWordD2ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxX));
        Append(code, MoveQuickZeroD0);
        AppendSuccessBranch(code, successBranches);

        var proportionalFallbackRestoreOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var proportionalFallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, proportionalMovementKeepBranchExtensionOffset, proportionalMovementUpdateOffset);
        PatchBranch(code, proportionalMovementAfterUpdateBranchExtensionOffset, proportionalMovementAfterUpdateOffset);
        PatchBranch(code, proportionalLoopBranchExtensionOffset, proportionalLoopOffset);
        foreach (var branchExtensionOffset in proportionalFallbackBranches)
            PatchBranch(code, branchExtensionOffset, proportionalFallbackRestoreOffset);
        PatchBranch(code, reverseFixedEnvelopeBranchExtensionOffset, reverseFixedEnvelopeOffset);
        PatchBranch(code, proportionalDirectionContinueBranchExtensionOffset, proportionalEntryOffset);
        PatchBranch(code, reverseProportionalBranchExtensionOffset, proportionalReverseEntryOffset);
        PatchBranch(code, proportionalReverseNegativeBranchExtensionOffset, proportionalReverseVerticalValidationOffset);
        PatchBranch(code, proportionalReverseNonNegativeJumpExtensionOffset, proportionalFallbackRestoreOffset);
        foreach (var branchExtensionOffset in proportionalReverseFallbackBranches)
            PatchBranch(code, branchExtensionOffset, proportionalFallbackRestoreOffset);

        var proportionalBranchDisplacement = checked(proportionalDirectionCheckOffset - proportionalBranchExtensionOffset);
        if (proportionalBranchDisplacement < short.MinValue || proportionalBranchDisplacement > short.MaxValue)
            throw new InvalidOperationException("Native FontExtent proportional arm is out of branch range.");

        code[proportionalBranchExtensionOffset] = (byte)((ushort)proportionalBranchDisplacement >> 8);
        code[proportionalBranchExtensionOffset + 1] = (byte)proportionalBranchDisplacement;

        var fallbackRestoreOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        var successRestoreOffset = code.Count;
        Append(code, MoveLongD0ToD1);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7DFD); // MOVEM.L (A7)+,D0/D2-D7/A0/A2-A6.
        Append(code, MoveLongD1ToD0);
        Append(code, ReturnFromSubroutine);

        var declineRestoreOffset = code.Count;
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7DFD); // Restore original D0/A0 and every callee-save register.
        Append(code, BranchAlwaysWord);
        var declineFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, proportionalFallbackJumpExtensionOffset, declineRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, declineRestoreOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        foreach (var branchExtensionOffset in preAdmissionFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in successBranches)
            PatchBranch(code, branchExtensionOffset, successRestoreOffset);
        PatchBranch(code, declineFallbackBranchExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    private static int AppendScalerDiv(List<byte> code)
    {
        var offset = code.Count;
        var invalidBranches = new List<int>(6);

        // ScalerDiv receives UWORD factor, numerator, and denominator in
        // D0/D1/D2.  The public helper admits only the classic 14-bit
        // domain, returns zero for a zero input/denominator, and publishes a
        // word-sized quotient (including the low-word wrap of a widened
        // product).  Keep the invalid path local so this arithmetic-only
        // vector does not claim a provider-owned operation.
        Append(code, CompareImmediateWordD0);
        Append(code, 0x3FFF);
        Append(code, BranchHighWord);
        var factorRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        invalidBranches.Add(factorRangeBranchExtensionOffset);
        Append(code, TestWordD0);
        Append(code, BranchEqualWord);
        var factorZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        invalidBranches.Add(factorZeroBranchExtensionOffset);

        Append(code, CompareImmediateWordD1);
        Append(code, 0x3FFF);
        Append(code, BranchHighWord);
        var numeratorRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        invalidBranches.Add(numeratorRangeBranchExtensionOffset);
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var numeratorZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        invalidBranches.Add(numeratorZeroBranchExtensionOffset);

        Append(code, CompareImmediateWordD2);
        Append(code, 0x3FFF);
        Append(code, BranchHighWord);
        var denominatorRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        invalidBranches.Add(denominatorRangeBranchExtensionOffset);
        Append(code, TestWordD2);
        Append(code, BranchEqualWord);
        var denominatorZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        invalidBranches.Add(denominatorZeroBranchExtensionOffset);

        // MULU.W leaves the complete product in D0.  The following bounded
        // restoring divide runs for 32 bits, so quotient overflow cannot
        // raise a DIVU exception; retaining D3's low word gives the native
        // UWORD ABI even for the documented wrapping case.
        Append(code, MultiplyUnsignedWordD1ToD0);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveQuickThirtyOneD5);

        var divideLoopOffset = code.Count;
        Append(code, BitTestImmediateD0);
        Append(code, 31);
        Append(code, BranchNotEqualWord);
        var inputBitSetBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, AddLongD4ToD4);
        Append(code, BranchAlwaysWord);
        var inputBitDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        var inputBitSetOffset = code.Count;
        Append(code, AddLongD4ToD4);
        Append(code, AddQuickOneLongD4);

        var inputBitDoneOffset = code.Count;
        Append(code, AddLongD0ToD0);
        Append(code, CompareLongD2ToD4);
        Append(code, BranchCarryWord);
        var quotientZeroBitBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, SubLongD2ToD4);
        Append(code, AddLongD3ToD3);
        Append(code, AddQuickOneLongD3);
        Append(code, BranchAlwaysWord);
        var quotientBitDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        var quotientZeroBitOffset = code.Count;
        Append(code, AddLongD3ToD3);

        var quotientBitDoneOffset = code.Count;
        Append(code, DecrementBranchD5);
        var divideLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, TestLongD3);
        Append(code, BranchEqualWord);
        var minimumResultBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveWordD2ToD5);
        Append(code, AddQuickOneWordD5);
        Append(code, ShiftRightWordD5);
        Append(code, CompareWordD5ToD4);
        Append(code, BranchCarryWord);
        var noRoundBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, AddQuickOneLongD3);

        var noRoundOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD3ToD0);
        Append(code, ReturnFromSubroutine);

        var minimumResultOffset = code.Count;
        Append(code, MoveQuickOneD0);
        Append(code, ReturnFromSubroutine);

        var invalidOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        PatchBranch(code, inputBitSetBranchExtensionOffset, inputBitSetOffset);
        PatchBranch(code, inputBitDoneBranchExtensionOffset, inputBitDoneOffset);
        PatchBranch(code, quotientZeroBitBranchExtensionOffset, quotientZeroBitOffset);
        PatchBranch(code, quotientBitDoneBranchExtensionOffset, quotientBitDoneOffset);
        PatchBranch(code, divideLoopBranchExtensionOffset, divideLoopOffset);
        PatchBranch(code, minimumResultBranchExtensionOffset, minimumResultOffset);
        PatchBranch(code, noRoundBranchExtensionOffset, noRoundOffset);
        foreach (var branchExtensionOffset in invalidBranches)
            PatchBranch(code, branchExtensionOffset, invalidOffset);

        return offset;
    }

    private static int AppendLoadRgb4(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(18);

        // LoadRGB4 receives a ViewPort in A0, a UWORD source table in A1,
        // and a signed WORD count in D0.  Claim only a direct standard
        // ColorMap whose complete destination spans can be checked before
        // the first store.  Type zero updates ColorTable; Type two also
        // clears the corresponding LowColorBits words.  Unsupported/provider
        // forms preserve the incoming D0 and remain available to the owner.
        Append(code, MoveLongD0ToD7); // preserve the void-vector fallback ABI
        Append(code, MoveLongD0ToD5);
        Append(code, TestWordD5);
        Append(code, BranchEqualWord);
        var zeroCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchMinusWord);
        var negativeCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(negativeCountBranchExtensionOffset);

        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var viewportNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(viewportNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var viewportOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(viewportOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8); // vp_ColorMap is the last field read
        Append(code, BranchHighWord);
        var viewportWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(viewportWrapBranchExtensionOffset);

        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var extendedModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(extendedModesBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortColorMap));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var mapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(mapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var mapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(mapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF0); // ColorMap fields through LowColorBits
        Append(code, BranchHighWord);
        var mapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(mapWrapBranchExtensionOffset);
        Append(code, MoveAddressD6ToA0);

        // A positive count must fit the public map count before any source or
        // destination address is advanced.  Recompute the byte span once and
        // use it for the source and ColorTable envelope checks.
        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapCount));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var mapCountZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(mapCountZeroBranchExtensionOffset);
        Append(code, MoveLongD5ToD6);
        Append(code, CompareWordD4ToD6);
        Append(code, BranchHighWord);
        var countRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(countRangeBranchExtensionOffset);

        Append(code, MoveLongD5ToD4);
        Append(code, AddLongD4ToD4);
        Append(code, MoveLongA1ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var sourceNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var sourceOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceOddBranchExtensionOffset);
        Append(code, AddLongD4ToD6);
        Append(code, BranchCarryWord);
        var sourceWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(sourceWrapBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapColorTable));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var tableNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var tableOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableOddBranchExtensionOffset);
        Append(code, MoveAddressD6ToA2);
        Append(code, AddLongD4ToD6);
        Append(code, BranchCarryWord);
        var tableWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableWrapBranchExtensionOffset);

        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapType));
        Append(code, CompareImmediateWordD4);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var typeZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD4);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var unsupportedTypeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedTypeBranchExtensionOffset);

        // Type two maps publish a cleared LowColorBits entry for every
        // loaded color.  Its complete span is checked before entering the
        // common publication loop.
        Append(code, MoveLongD5ToD4);
        Append(code, AddLongD4ToD4);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapLowColorBits));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var lowNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var lowOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowOddBranchExtensionOffset);
        Append(code, MoveAddressD6ToA3);
        Append(code, AddLongD4ToD6);
        Append(code, BranchCarryWord);
        var lowWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowWrapBranchExtensionOffset);

        var typeTwoCommitOffset = code.Count;
        Append(code, SubQuickOneWordD5);
        var typeTwoLoopOffset = code.Count;
        Append(code, MoveWordA1PostIncrementToD4);
        Append(code, AndImmediateWordD4);
        Append(code, 0x0FFF);
        Append(code, MoveWordA2ToD6);
        Append(code, AndImmediateWordD6);
        Append(code, 0xF000);
        Append(code, OrWordD4ToD6);
        Append(code, MoveWordD6ToA2);
        Append(code, AddQuickTwoLongA2);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordD4ToA3);
        Append(code, AddQuickTwoLongA3);
        Append(code, DecrementBranchD5);
        var typeTwoLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var typeTwoDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        var typeZeroCommitOffset = code.Count;
        Append(code, SubQuickOneWordD5);
        var typeZeroLoopOffset = code.Count;
        Append(code, MoveWordA1PostIncrementToD4);
        Append(code, AndImmediateWordD4);
        Append(code, 0x0FFF);
        Append(code, MoveWordA2ToD6);
        Append(code, AndImmediateWordD6);
        Append(code, 0xF000);
        Append(code, OrWordD4ToD6);
        Append(code, MoveWordD6ToA2);
        Append(code, AddQuickTwoLongA2);
        Append(code, DecrementBranchD5);
        var typeZeroLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, zeroCountBranchExtensionOffset, successOffset);
        PatchBranch(code, typeZeroBranchExtensionOffset, typeZeroCommitOffset);
        PatchBranch(code, typeTwoLoopBranchExtensionOffset, typeTwoLoopOffset);
        PatchBranch(code, typeTwoDoneBranchExtensionOffset, successOffset);
        PatchBranch(code, typeZeroLoopBranchExtensionOffset, typeZeroLoopOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendLoadRgb32(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(64);

        // Keep the caller's D0 balanced across every decline.  LoadRGB32 has
        // no scalar result, so successful native publication clears D0 while
        // the shared owner still sees the original register on fallback.
        Append(code, MoveLongD0ToPreDecrementA7);

        // A NULL table is the documented no-op form and must not require a
        // readable ViewPort or ColorMap envelope.
        Append(code, MoveLongA1ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullTableBranchExtensionOffset = code.Count;
        Append(code, 0);

        // A non-NULL RGB32 table is a longword stream consumed by 68000
        // accesses.  Check the initial address and every post-read advance so
        // a malformed guest pointer never wraps back into low memory.
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddTableBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddTableBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFFB);
        Append(code, BranchHighWord);
        var tableWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableWrapBranchExtensionOffset);
        Append(code, MoveAddressA1ToA4);

        // Claim only a standard, directly linked ViewPort/ColorMap envelope.
        // Provider/RTG and monitor ExtendedModes state remains available to
        // the native/provider owner.
        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var viewPortNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(viewPortNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var viewPortOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(viewPortOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8);
        Append(code, BranchHighWord);
        var viewPortWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(viewPortWrapBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var extendedModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(extendedModesBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortColorMap));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var colorMapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(colorMapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var colorMapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(colorMapOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF0);
        Append(code, BranchHighWord);
        var colorMapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(colorMapWrapBranchExtensionOffset);
        Append(code, MoveAddressD6ToA0);

        // ColorMap count and ColorTable envelope.  The complete map span is
        // checked once, which makes every later A2 publication increment
        // wrap-safe after the descriptor index has been range-checked.
        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapCount));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var colorMapCountZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(colorMapCountZeroBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapColorTable));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var colorTableNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(colorTableNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var colorTableOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(colorTableOddBranchExtensionOffset);
        Append(code, MoveAddressD6ToA5);
        Append(code, AddLongD4ToD4);
        Append(code, BranchCarryWord);
        var colorTableSpanBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(colorTableSpanBranchExtensionOffset);
        Append(code, MoveLongA5ToD6);
        Append(code, AddLongD4ToD6);
        Append(code, BranchCarryWord);
        var colorTableWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(colorTableWrapBranchExtensionOffset);

        // Only legacy Type 0 and V36 Type 2 maps are claimed.  Type 2 also
        // requires a complete, carry-safe LowColorBits span.
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapType));
        Append(code, CompareImmediateByteD6);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var typeZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD6);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var unsupportedTypeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedTypeBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapLowColorBits));
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var lowTableNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowTableNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var lowTableOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowTableOddBranchExtensionOffset);
        Append(code, MoveAddressD6ToA6);
        Append(code, MoveLongA6ToD6);
        Append(code, AddLongD4ToD6);
        Append(code, BranchCarryWord);
        var lowTableWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowTableWrapBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var typeReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var typeZeroReadyOffset = code.Count;
        Append(code, MoveQuickZeroD6);
        Append(code, MoveAddressD6ToA6);

        var firstPassSetupOffset = code.Count;
        Append(code, MoveAddressA4ToA1);
        Append(code, MoveImmediateWordD7);
        Append(code, 0x0FFF);

        // First pass: consume every descriptor and RGB triplet, checking the
        // descriptor index/count envelope and every source longword address
        // without publishing a ColorMap word.
        var firstRecordLoopOffset = code.Count;
        Append(code, MoveLongA1IndirectToD0);
        Append(code, MoveLongA1ToD6);
        Append(code, AddQuickFourLongD6);
        Append(code, BranchCarryWord);
        var firstDescriptorAdvanceBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(firstDescriptorAdvanceBranchExtensionOffset);
        Append(code, MoveAddressD6ToA1);
        Append(code, MoveLongD0ToD4);
        AppendShiftRightLongD4(16);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordD0ToD5);
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var firstTerminatorBranchExtensionOffset = code.Count;
        Append(code, 0);

        AppendDescriptorBounds(code, fallbackBranches);
        Append(code, SubQuickOneWordD4);
        var firstEntryLoopOffset = code.Count;
        AppendReadLongAndAdvance(MoveLongA1IndirectToD1);
        AppendReadLongAndAdvance(MoveLongA1IndirectToD2);
        AppendReadLongAndAdvance(MoveLongA1IndirectToD3);
        Append(code, DecrementBranchD4);
        var firstEntryLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, DecrementBranchD7);
        var firstRecordLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var firstRecordLimitBranchExtensionOffset = code.Count;
        Append(code, 0);

        var secondPassSetupOffset = code.Count;
        Append(code, MoveAddressA4ToA1);
        Append(code, MoveImmediateWordD7);
        Append(code, 0x0FFF);

        // Second pass: the same validated stream is replayed, this time
        // publishing ColorTable words and (for Type 2) LowColorBits words.
        var secondRecordLoopOffset = code.Count;
        Append(code, MoveLongA1IndirectToD0);
        Append(code, MoveLongA1ToD6);
        Append(code, AddQuickFourLongD6);
        Append(code, BranchCarryWord);
        var secondDescriptorAdvanceBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(secondDescriptorAdvanceBranchExtensionOffset);
        Append(code, MoveAddressD6ToA1);
        Append(code, MoveLongD0ToD4);
        AppendShiftRightLongD4(16);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordD0ToD5);
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var secondTerminatorBranchExtensionOffset = code.Count;
        Append(code, 0);

        AppendDescriptorBounds(code, fallbackBranches);
        Append(code, MoveAddressA5ToA2);
        Append(code, AddLongD5ToD5);
        Append(code, MoveLongA5ToD6);
        Append(code, AddLongD5ToD6);
        Append(code, BranchCarryWord);
        var destinationOffsetBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(destinationOffsetBranchExtensionOffset);
        Append(code, MoveAddressD6ToA2);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapType));
        Append(code, CompareImmediateByteD6);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var typeTwoDestinationBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var entrySetupBranchExtensionOffset = code.Count;
        Append(code, 0);

        var typeTwoDestinationSetupOffset = code.Count;
        Append(code, MoveAddressA6ToA3);
        Append(code, MoveLongA3ToD6);
        Append(code, AddLongD5ToD6);
        Append(code, BranchCarryWord);
        var lowDestinationOffsetBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowDestinationOffsetBranchExtensionOffset);
        Append(code, MoveAddressD6ToA3);

        var entrySetupOffset = code.Count;
        Append(code, MoveLongD4ToD0);
        Append(code, SubQuickOneWordD0);

        var secondEntryLoopOffset = code.Count;
        AppendReadLongAndAdvance(MoveLongA1IndirectToD1);
        AppendReadLongAndAdvance(MoveLongA1IndirectToD2);
        AppendReadLongAndAdvance(MoveLongA1IndirectToD3);

        Append(code, MoveWordA2ToD4);
        Append(code, AndImmediateWordD4);
        Append(code, 0xF000);
        Append(code, MoveQuickZeroD5);

        // Convert the high and low nibbles of each RGB32 component.  SWAP
        // exposes the source byte as AB00; the shifts below place its high or
        // low nibble into the legacy ColorTable/LowColorBits slots.
        Append(code, MoveLongD1ToD6);
        Append(code, SwapD6);
        AppendShiftRightWordD6(4);
        Append(code, AndImmediateWordD6);
        Append(code, 0x0F00);
        Append(code, OrLongD6ToD4);
        Append(code, MoveLongD1ToD6);
        Append(code, SwapD6);
        Append(code, AndImmediateWordD6);
        Append(code, 0x0F00);
        Append(code, OrLongD6ToD5);

        Append(code, MoveLongD2ToD6);
        Append(code, SwapD6);
        AppendShiftRightWordD6(8);
        Append(code, AndImmediateWordD6);
        Append(code, 0x00F0);
        Append(code, OrLongD6ToD4);
        Append(code, MoveLongD2ToD6);
        Append(code, SwapD6);
        AppendShiftRightWordD6(4);
        Append(code, AndImmediateWordD6);
        Append(code, 0x00F0);
        Append(code, OrLongD6ToD5);

        Append(code, MoveLongD3ToD6);
        Append(code, SwapD6);
        AppendShiftRightWordD6(12);
        Append(code, AndImmediateWordD6);
        Append(code, 0x000F);
        Append(code, OrLongD6ToD4);
        Append(code, MoveLongD3ToD6);
        Append(code, SwapD6);
        AppendShiftRightWordD6(8);
        Append(code, AndImmediateWordD6);
        Append(code, 0x000F);
        Append(code, OrLongD6ToD5);

        Append(code, MoveWordD4ToA2);
        Append(code, MoveByteA0DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapType));
        Append(code, CompareImmediateByteD6);
        Append(code, 2);
        Append(code, BranchEqualWord);
        var lowStoreBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var commonEntryAdvanceBranchExtensionOffset = code.Count;
        Append(code, 0);

        var lowStoreOffset = code.Count;
        Append(code, MoveWordD5ToA3);
        Append(code, AddQuickTwoLongA3);

        var commonEntryAdvanceOffset = code.Count;
        Append(code, AddQuickTwoLongA2);
        Append(code, DecrementBranchD0);
        var secondEntryLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, DecrementBranchD7);
        var secondRecordLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var secondRecordLimitBranchExtensionOffset = code.Count;
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, nullTableBranchExtensionOffset, successOffset);
        PatchBranch(code, typeZeroBranchExtensionOffset, typeZeroReadyOffset);
        PatchBranch(code, firstTerminatorBranchExtensionOffset, secondPassSetupOffset);
        PatchBranch(code, secondTerminatorBranchExtensionOffset, successOffset);
        PatchBranch(code, typeReadyBranchExtensionOffset, firstPassSetupOffset);
        PatchBranch(code, firstEntryLoopBranchExtensionOffset, firstEntryLoopOffset);
        PatchBranch(code, firstRecordLoopBranchExtensionOffset, firstRecordLoopOffset);
        PatchBranch(code, firstRecordLimitBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, typeTwoDestinationBranchExtensionOffset, typeTwoDestinationSetupOffset);
        PatchBranch(code, entrySetupBranchExtensionOffset, entrySetupOffset);
        PatchBranch(code, lowStoreBranchExtensionOffset, lowStoreOffset);
        PatchBranch(code, commonEntryAdvanceBranchExtensionOffset, commonEntryAdvanceOffset);
        PatchBranch(code, secondEntryLoopBranchExtensionOffset, secondEntryLoopOffset);
        PatchBranch(code, secondRecordLoopBranchExtensionOffset, secondRecordLoopOffset);
        PatchBranch(code, secondRecordLimitBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;

        void AppendReadLongAndAdvance(ushort loadOpcode)
        {
            Append(code, MoveLongA1ToD6);
            Append(code, CompareImmediateLongD6);
            Append(code, 0xFFFF);
            Append(code, 0xFFFB);
            Append(code, BranchHighWord);
            var preReadWrapBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(preReadWrapBranchExtensionOffset);
            Append(code, loadOpcode);
            Append(code, MoveLongA1ToD6);
            Append(code, AddQuickFourLongD6);
            Append(code, BranchCarryWord);
            var advanceBranchExtensionOffset = code.Count;
            Append(code, 0);
            fallbackBranches.Add(advanceBranchExtensionOffset);
            Append(code, MoveAddressD6ToA1);
        }

        void AppendDescriptorBounds(List<byte> targetCode, List<int> targetFallbackBranches)
        {
            Append(targetCode, MoveLongD5ToD6);
            Append(targetCode, AddLongD4ToD6);
            Append(targetCode, BranchCarryWord);
            var sumCarryBranchExtensionOffset = targetCode.Count;
            Append(targetCode, 0);
            targetFallbackBranches.Add(sumCarryBranchExtensionOffset);
            Append(targetCode, CompareImmediateLongD6);
            Append(targetCode, 0);
            Append(targetCode, 0xFFFF);
            Append(targetCode, BranchHighWord);
            var sumWordBranchExtensionOffset = targetCode.Count;
            Append(targetCode, 0);
            targetFallbackBranches.Add(sumWordBranchExtensionOffset);
            Append(targetCode, MoveQuickZeroD0);
            Append(targetCode, MoveWordA0DisplacementToD0);
            Append(targetCode, checked((ushort)GraphicsLayouts.ColorMapCount));
            Append(targetCode, CompareWordD0ToD6);
            Append(targetCode, BranchHighWord);
            var countBranchExtensionOffset = targetCode.Count;
            Append(targetCode, 0);
            targetFallbackBranches.Add(countBranchExtensionOffset);
        }

        void AppendShiftRightWordD6(int count)
        {
            for (var index = 0; index < count; index++)
                Append(code, ShiftRightWordD6);
        }

        void AppendShiftRightLongD4(int count)
        {
            for (var index = 0; index < count; index++)
                Append(code, ShiftRightLongD4);
        }
    }

    private static int AppendGetRgb4(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(12);

        // GetRGB4 is a pure legacy ColorMap read.  Claim only an even,
        // non-null map whose UWORD entry index is in the public count and
        // whose ColorTable pointer is even/non-null.  The table entry is
        // masked to RGB4; ownership, V36 LowColorBits, and provider/RTG maps
        // remain outside this native body.
        Append(code, MoveLongD0ToD5); // preserve the incoming D0 on decline
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var mapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(mapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var mapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(mapOddBranchExtensionOffset);

        Append(code, MoveLongD0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchMinusWord);
        var indexNegativeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(indexNegativeBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0);
        Append(code, 0xFFFF);
        Append(code, BranchHighWord);
        var indexWideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(indexWideBranchExtensionOffset);

        Append(code, MoveQuickZeroD2);
        Append(code, MoveWordA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapCount));
        Append(code, TestWordD2);
        Append(code, BranchEqualWord);
        var countZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(countZeroBranchExtensionOffset);
        Append(code, CompareLongD6ToD2);
        Append(code, BranchLowerOrSameWord);
        var indexRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(indexRangeBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapColorTable));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var tableNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var tableOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableOddBranchExtensionOffset);

        Append(code, ShiftLeftLongD6);
        Append(code, AddLongD6ToD4);
        Append(code, BranchCarryWord);
        var tableWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableWrapBranchExtensionOffset);
        Append(code, MoveAddressD4ToA1);
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, 0);
        Append(code, AndImmediateWordD0);
        Append(code, 0x0FFF);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD5ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        return offset;
    }

    private static int AppendSetRgb4Cm(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(18);

        // Claim only the public RGB4 write envelope.  Type zero maps need
        // only ColorTable; V36/V39-style maps additionally preflight the
        // LowColorBits pointer because an RGB4 write clears that entry.
        // All checks precede the first store so malformed state cannot leave
        // a partially updated palette.
        Append(code, MoveLongD0ToD5);
        Append(code, MoveAddressD2ToA3); // preserve green while D2 holds count
        Append(code, MoveLongA0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var mapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(mapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var mapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(mapOddBranchExtensionOffset);

        Append(code, MoveLongD0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchMinusWord);
        var indexNegativeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(indexNegativeBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0);
        Append(code, 0xFFFF);
        Append(code, BranchHighWord);
        var indexWideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(indexWideBranchExtensionOffset);

        Append(code, MoveQuickZeroD2);
        Append(code, MoveWordA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapCount));
        Append(code, TestWordD2);
        Append(code, BranchEqualWord);
        var countZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(countZeroBranchExtensionOffset);
        Append(code, CompareLongD6ToD2);
        Append(code, BranchLowerOrSameWord);
        var indexRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(indexRangeBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapColorTable));
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var tableNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableNullBranchExtensionOffset);
        Append(code, BitTestImmediateD7);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var tableOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableOddBranchExtensionOffset);
        Append(code, ShiftLeftLongD6);
        Append(code, AddLongD6ToD7);
        Append(code, BranchCarryWord);
        var tableWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableWrapBranchExtensionOffset);
        Append(code, MoveAddressD7ToA1);
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, 0);

        Append(code, MoveQuickZeroD7);
        Append(code, MoveByteA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapType));
        Append(code, CompareImmediateWordD7);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var typeZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD7);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var typeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(typeBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapLowColorBits));
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var lowTableNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowTableNullBranchExtensionOffset);
        Append(code, BitTestImmediateD7);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var lowTableOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowTableOddBranchExtensionOffset);
        Append(code, AddLongD6ToD7);
        Append(code, BranchCarryWord);
        var lowTableWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowTableWrapBranchExtensionOffset);
        Append(code, MoveAddressD7ToA2);
        Append(code, MoveQuickTwoD7); // retain the V36/V39 type marker

        var colorBuildOffset = code.Count;
        Append(code, MoveLongA3ToD2);
        Append(code, AndImmediateWordD4);
        Append(code, 0xF000);
        Append(code, AndImmediateLongD1);
        Append(code, 0);
        Append(code, 0x000F);
        for (var index = 0; index < 8; index++)
            Append(code, ShiftLeftLongD1);
        Append(code, OrLongD1ToD4);
        Append(code, AndImmediateLongD2);
        Append(code, 0);
        Append(code, 0x000F);
        for (var index = 0; index < 4; index++)
            Append(code, ShiftLeftLongD2);
        Append(code, OrLongD2ToD4);
        Append(code, AndImmediateLongD3);
        Append(code, 0);
        Append(code, 0x000F);
        Append(code, OrLongD3ToD4);
        Append(code, MoveWordD4ToA1Displacement);
        Append(code, 0);
        Append(code, TestWordD7);
        Append(code, BranchEqualWord);
        var typeZeroStoreBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveAddressA2ToA1);
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD5ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, typeZeroBranchExtensionOffset, colorBuildOffset);
        PatchBranch(code, typeZeroStoreBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendSetRgb4(
        List<byte> code,
        int fallbackEntryOffset,
        int colorMapEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(8);

        // SetRGB4 carries a ViewPort in A0 but publishes one legacy RGB4
        // entry through SetRGB4CM.  Claim only a bounded, standard ViewPort
        // whose ColorMap link is a direct, even guest map; monitor/RTG
        // ExtendedModes and malformed/provider links remain on the original
        // vector owner.
        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullViewportBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullViewportBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddViewportBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddViewportBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8); // vp_ColorMap is the last field read
        Append(code, BranchHighWord);
        var viewportWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(viewportWrapBranchExtensionOffset);

        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD4);
        Append(code, BranchNotEqualWord);
        var extendedModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(extendedModesBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortColorMap));
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var nullMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullMapBranchExtensionOffset);
        Append(code, BitTestImmediateD7);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddMapBranchExtensionOffset);
        Append(code, CompareImmediateLongD7);
        Append(code, 0xFFFF);
        Append(code, 0xFFF0); // ColorMap fields through LowColorBits
        Append(code, BranchHighWord);
        var mapWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(mapWrapBranchExtensionOffset);

        Append(code, MoveAddressD7ToA0);
        Append(code, BranchAlwaysWord);
        var colorMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, colorMapBranchExtensionOffset, colorMapEntryOffset);
        return offset;
    }

    private static int AppendSetRgb32(
        List<byte> code,
        int fallbackEntryOffset,
