    private static int AppendSetRgb32Cm(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(18);

        // SetRGB32CM receives a ColorMap in A0, an entry in D0, and three
        // 0xRRGGBB00-style channel LONGs in D1/D2/D3.  Preserve the incoming
        // index in A5 and the red channel in A4 while the count and entry
        // address are preflighted.  Type 0 publishes only ColorTable; Type 2
        // additionally validates and publishes LowColorBits.  Other map
        // types remain available to the provider/native owner.
        Append(code, MoveAddressD0ToA5);
        Append(code, MoveAddressD1ToA4);
        Append(code, MoveLongA0ToD7);
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var mapNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(mapNullBranchExtensionOffset);
        Append(code, BitTestImmediateD7);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var mapOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(mapOddBranchExtensionOffset);

        Append(code, MoveLongD0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchMinusWord);
        var indexNegativeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(indexNegativeBranchExtensionOffset);
        Append(code, MoveQuickZeroD1);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapCount));
        Append(code, TestWordD1);
        Append(code, BranchEqualWord);
        var countZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(countZeroBranchExtensionOffset);
        Append(code, CompareLongD6ToD1);
        Append(code, BranchLowerOrSameWord);
        var indexRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(indexRangeBranchExtensionOffset);
        Append(code, ShiftLeftLongD6);

        Append(code, MoveLongA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapColorTable));
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var tableNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableNullBranchExtensionOffset);
        Append(code, BitTestImmediateD7);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var tableOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableOddBranchExtensionOffset);
        Append(code, AddLongD6ToD7);
        Append(code, BranchCarryWord);
        var tableWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(tableWrapBranchExtensionOffset);
        Append(code, MoveAddressD7ToA2);

        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA2DisplacementToD4);
        Append(code, 0);
        Append(code, AndImmediateWordD4);
        Append(code, 0xF000);

        Append(code, MoveQuickZeroD7);
        Append(code, MoveByteA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapType));
        Append(code, CompareImmediateWordD7);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var typeZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD7);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var typeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(typeBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.ColorMapLowColorBits));
        Append(code, TestLongD7);
        Append(code, BranchEqualWord);
        var lowNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowNullBranchExtensionOffset);
        Append(code, BitTestImmediateD7);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var lowOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowOddBranchExtensionOffset);
        Append(code, AddLongD6ToD7);
        Append(code, BranchCarryWord);
        var lowWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(lowWrapBranchExtensionOffset);
        Append(code, MoveAddressD7ToA3);
        Append(code, MoveQuickZeroD5);
        Append(code, BranchAlwaysWord);
        var lowReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var lowReadyOffset = code.Count;
        Append(code, MoveLongA4ToD1);

        // Red: high nibble -> ColorTable bits 11..8, low nibble ->
        // LowColorBits bits 11..8.
        Append(code, MoveLongD1ToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0xF000);
        Append(code, 0x0000);
        for (var index = 0; index < 20; index++)
            Append(code, ShiftRightLongD0);
        Append(code, OrLongD0ToD4);
        Append(code, MoveLongD1ToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0x0F00);
        Append(code, 0x0000);
        for (var index = 0; index < 16; index++)
            Append(code, ShiftRightLongD0);
        Append(code, OrLongD0ToD5);

        // Green: high nibble -> ColorTable bits 7..4, low nibble ->
        // LowColorBits bits 7..4.
        Append(code, MoveLongD2ToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0xF000);
        Append(code, 0x0000);
        for (var index = 0; index < 24; index++)
            Append(code, ShiftRightLongD0);
        Append(code, OrLongD0ToD4);
        Append(code, MoveLongD2ToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0x0F00);
        Append(code, 0x0000);
        for (var index = 0; index < 20; index++)
            Append(code, ShiftRightLongD0);
        Append(code, OrLongD0ToD5);

        // Blue: high nibble -> ColorTable bits 3..0, low nibble ->
        // LowColorBits bits 3..0.
        Append(code, MoveLongD3ToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0xF000);
        Append(code, 0x0000);
        for (var index = 0; index < 28; index++)
            Append(code, ShiftRightLongD0);
        Append(code, OrLongD0ToD4);
        Append(code, MoveLongD3ToD0);
        Append(code, AndImmediateLongD0);
        Append(code, 0x0F00);
        Append(code, 0x0000);
        for (var index = 0; index < 24; index++)
            Append(code, ShiftRightLongD0);
        Append(code, OrLongD0ToD5);

        Append(code, MoveAddressA2ToA1);
        Append(code, MoveWordD4ToA1Displacement);
        Append(code, 0);
        Append(code, TestWordD7);
        Append(code, BranchEqualWord);
        var typeZeroStoreBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressA3ToA1);
        Append(code, MoveWordD5ToA1Displacement);
        Append(code, 0);

        var successOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongA5ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, typeZeroBranchExtensionOffset, lowReadyOffset);
        PatchBranch(code, lowReadyBranchExtensionOffset, lowReadyOffset);
        PatchBranch(code, typeZeroStoreBranchExtensionOffset, successOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendGetVpModeId(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(8);

        // Claim only the assembling standard ViewPort form whose mode can be
        // read without consulting a monitor, ColorMap, or provider backend.
        // A non-null ColorMap may encode a VideoControl override, while
        // ExtendedModes belongs to the monitor/RTG owner; both stay on the
        // shared fallback.  The complete ViewPort envelope is bounded before
        // any field read so malformed high guest addresses cannot wrap.
        Append(code, MoveLongD0ToD7); // preserve the incoming D0 on decline
        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFDC); // vp_ExtendedModes is the last byte read
        Append(code, BranchHighWord);
        var wrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrapBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortColorMap));
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var colorMapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(colorMapBranchExtensionOffset);

        Append(code, MoveQuickZeroD2);
        Append(code, MoveByteA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortExtendedModes));
        Append(code, TestLongD2);
        Append(code, BranchNotEqualWord);
        var extendedModesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(extendedModesBranchExtensionOffset);

        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.ViewPortModes));
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendGetBitMapAttr(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(16);

        // The scalar BMA_HEIGHT/BMA_DEPTH/BMA_WIDTH queries read only their
        // requested public fields.  Non-displayable standard flags are also
        // safe to mask locally.  A separate depth-one displayable form below
        // proves the minimum standard-planar envelope before retaining the
        // capability bit; richer/provider-owned forms remain unclaimed.
        Append(code, MoveLongD0ToD6);
        Append(code, MoveLongA0ToD0);
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var nullBitmapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullBitmapBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBitmapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddBitmapBranchExtensionOffset);

        Append(code, CompareImmediateWordD1);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var heightBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 4);
        Append(code, BranchEqualWord);
        var depthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 8);
        Append(code, BranchEqualWord);
        var widthBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 12);
        Append(code, BranchEqualWord);
        var flagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var unsupportedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var heightOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, ReturnFromSubroutine);

        var depthOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, ReturnFromSubroutine);

        var widthOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD0);
        Append(code, BranchEqualWord);
        var widthZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthZeroBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var widthOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthOddBranchExtensionOffset);
        Append(code, AddLongD0ToD0);
        Append(code, AddLongD0ToD0);
        Append(code, AddLongD0ToD0);
        Append(code, ReturnFromSubroutine);

        var flagsOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, BitTestImmediateD0);
        Append(code, 1); // BMF_DISPLAYABLE
        Append(code, BranchNotEqualWord);
        var displayableDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD0);
        Append(code, 2); // BMF_INTERLEAVED
        Append(code, BranchNotEqualWord);
        var interleavedFlagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(interleavedFlagsBranchExtensionOffset);
        Append(code, AndImmediateWordD0);
        Append(code, 0x000E); // public BMF_DISPLAYABLE|INTERLEAVED|STANDARD
        Append(code, ReturnFromSubroutine);

        var displayableOffset = code.Count;
        Append(code, BitTestImmediateD0);
        Append(code, 2); // BMF_INTERLEAVED
        Append(code, BranchNotEqualWord);
        var displayableInterleavedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(displayableInterleavedBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 3); // BMF_STANDARD
        Append(code, BranchEqualWord);
        var displayableStandardBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(displayableStandardBranchExtensionOffset);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, TestByteD4);
        Append(code, BranchEqualWord);
        var displayableDepthZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateByteD4);
        Append(code, 8); // admit standard planar depths one through eight
        Append(code, BranchHighWord);
        var displayableDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(displayableDepthZeroBranchExtensionOffset);
        fallbackBranches.Add(displayableDepthBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var displayableRowsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(displayableRowsBranchExtensionOffset);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestWordD4);
        Append(code, BranchEqualWord);
        var displayableStrideZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(displayableStrideZeroBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var displayableStrideOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(displayableStrideOddBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.BitMapPlanes));
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var displayablePlanesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(displayablePlanesBranchExtensionOffset);
        Append(code, BitTestImmediateD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var displayablePlanesOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(displayablePlanesOddBranchExtensionOffset);
        // Plane zero was checked directly above.  For depths two through
        // eight, walk the remaining inline Planes[] entries with a bounded
        // DBRA loop.  The depth-minus-two counter yields exactly depth-1
        // iterations while the depth-one branch skips the loop entirely.
        Append(code, MoveQuickZeroD7);
        Append(code, MoveByteA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, CompareImmediateByteD7);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var displayableSinglePlaneSkipBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, SubQuickTwoWordD7);
        Append(code, MoveAddressA0ToA1);
        Append(code, AddQuickFourLongA1);
        Append(code, AddQuickFourLongA1);
        Append(code, AddQuickFourLongA1);

        var displayablePlaneLoopOffset = code.Count;
        Append(code, MoveLongA1PostIncrementToD5);
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var displayableLaterPlaneBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(displayableLaterPlaneBranchExtensionOffset);
        Append(code, BitTestImmediateD5);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var displayableLaterPlaneOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(displayableLaterPlaneOddBranchExtensionOffset);
        Append(code, DecrementBranchD7);
        var displayablePlaneLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var displayablePublishOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, AndImmediateWordD0);
        Append(code, 0x000E);
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD6ToD0);
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, heightBranchExtensionOffset, heightOffset);
        PatchBranch(code, depthBranchExtensionOffset, depthOffset);
        PatchBranch(code, widthBranchExtensionOffset, widthOffset);
        PatchBranch(code, flagsBranchExtensionOffset, flagsOffset);
        PatchBranch(code, displayableDispatchBranchExtensionOffset, displayableOffset);
        PatchBranch(code, displayableSinglePlaneSkipBranchExtensionOffset, displayablePublishOffset);
        PatchBranch(code, displayablePlaneLoopBranchExtensionOffset, displayablePlaneLoopOffset);
        PatchBranch(code, unsupportedBranchExtensionOffset, fallbackRestoreOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendTextFit(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(20);
        var rastPortFallbackBranches = new List<int>(3);
        var successBranches = new List<int>(8);

        // Every native TextFit arm reads A1, with the widest path reaching the
        // signed TxSpacing WORD at 0x40. D1 is the live direction argument, so
        // preserve it around this exact NULL/alignment/wrap admission instead
        // of borrowing a callee-save register or folding in TextFit's wider
        // public frame. An invalid A1 therefore tail-chains with the complete
        // original call, before the existing body reuses A6 for the source.
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveLongA1ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        rastPortFallbackBranches.Add(nullRastPortBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        rastPortFallbackBranches.Add(oddRastPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFBE); // Last even base through RP.TxSpacing at 0x40.
        Append(code, BranchHighWord);
        var wrappedRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        rastPortFallbackBranches.Add(wrappedRastPortBranchExtensionOffset);
        Append(code, MoveLongA7PostIncrementToD1);

        // D1 is a volatile input but must be recovered on provider decline;
        // save it separately, then snapshot original D0 plus the complete
        // public callee-save set. Reverse TextFit nests one A2 result pointer
        // and the multi-glyph arm nests one D7 value above this frame. Their
        // existing local restores run before either common outer epilogue.
        Append(code, MoveLongD1ToPreDecrementA7);
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0xBFBE); // MOVEM.L D0/D2-D7/A0/A2-A6,-(A7), reversed mask.

        // Keep the original source pointer available to the bounded
        // proportional arm.  The fixed-cell path deliberately continues to
        // use the classic A0 font walk below.
        Append(code, MoveAddressA0ToA6);

        // Keep this native body deliberately narrow. It owns only the
        // fixed-cell, forward/reverse, alternate-width/height form with no
        // algorithmic style. Explicit TextExtent constraints, proportional
        // reverse direction, REVPATH fonts, and signed spacing that stalls
        // the cursor remain on the portable/provider implementation.
        Append(code, CompareImmediateWordD1);
        Append(code, 1);
        Append(code, BranchEqualWord);
        var forwardDirectionBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateWordD1);
        Append(code, 0xFFFF); // documented reverse direction (-1)
        Append(code, BranchNotEqualWord);
        var directionBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(directionBranchExtensionOffset);
        Append(code, MoveQuickMinusOneD5); // marker: reverse fixed-cell form
        Append(code, BranchAlwaysWord);
        var reverseDirectionContinueBranchExtensionOffset = code.Count;
        Append(code, 0);
        var forwardDirectionSetupOffset = code.Count;
        Append(code, MoveQuickZeroD5); // marker: forward form
        var directionContinueOffset = code.Count;
        PatchBranch(code, forwardDirectionBranchExtensionOffset, forwardDirectionSetupOffset);
        PatchBranch(code, reverseDirectionContinueBranchExtensionOffset, directionContinueOffset);

        Append(code, MoveLongA3ToD1);
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var constraintBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(constraintBranchExtensionOffset);

        // The low words are the ABI fields.  Reject dimensions with bit 15
        // set because the portable alternate-box contract is 0..32767.
        Append(code, BitTestImmediateD2);
        Append(code, 15);
        Append(code, BranchNotEqualWord);
        var widthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(widthRangeBranchExtensionOffset);
        Append(code, BitTestImmediateD3);
        Append(code, 15);
        Append(code, BranchNotEqualWord);
        var heightRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(heightRangeBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 15);
        Append(code, BranchNotEqualWord);
        var countRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(countRangeBranchExtensionOffset);
        Append(code, MoveWordD2ToD6);
        Append(code, ExtendLongD6);

        // Non-empty calls must have a readable string pointer.  A zero count
        // intentionally skips that dereference and still publishes an empty
        // TextExtent, matching the portable metric boundary.
        Append(code, TestWordD0);
        Append(code, BranchEqualWord);
        var emptyTextPointerBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var textPointerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(textPointerBranchExtensionOffset);
        var afterTextPointerGuardOffset = code.Count;

        Append(code, MoveLongA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFont));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var fontBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fontAlignmentBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontAlignmentBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFCC); // TextFontMinimumSize (0x34) envelope
        Append(code, BranchHighWord);
        var fontWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontWrapBranchExtensionOffset);
        Append(code, MoveAddressD1ToA0);

        Append(code, MoveQuickZeroD2);
        Append(code, MoveByteA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.TextFontFlags));
        Append(code, BitTestImmediateD2);
        Append(code, 2); // FPF_REVPATH
        Append(code, BranchNotEqualWord);
        var reversePathBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(reversePathBranchExtensionOffset);
        Append(code, MoveLongD0ToD7); // proportional arm's decline ABI
        Append(code, BitTestImmediateD2);
        Append(code, 5); // FPF_PROPORTIONAL
        Append(code, BranchNotEqualWord);
        var proportionalBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveQuickZeroD2);
        Append(code, MoveByteA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAlgoStyle));
        Append(code, TestLongD2);
        Append(code, BranchNotEqualWord);
        var styleBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(styleBranchExtensionOffset);

        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontYSize));
        Append(code, BitTestImmediateD1);
        Append(code, 15);
        Append(code, BranchNotEqualWord);
        var fontHeightRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontHeightRangeBranchExtensionOffset);
        Append(code, ExtendLongD1);
        Append(code, TestLongD1);
        Append(code, BranchMinusWord);
        var fontHeightSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontHeightSignBranchExtensionOffset);
        Append(code, BranchEqualWord);
        var fontHeightZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontHeightZeroBranchExtensionOffset);

        Append(code, MoveWordD3ToD4);
        Append(code, ExtendLongD4);
        Append(code, SubLongD1ToD4);
        Append(code, BranchMinusWord);
        var constraintHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(constraintHeightBranchExtensionOffset);

        Append(code, MoveWordA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontBaseline));
        Append(code, ExtendLongD3);
        Append(code, NegLongD3);
        Append(code, MoveWordA0DisplacementToD7);
        Append(code, checked((ushort)GraphicsLayouts.TextFontXSize));
        Append(code, BitTestImmediateD7);
        Append(code, 15);
        Append(code, BranchNotEqualWord);
        var fontWidthRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontWidthRangeBranchExtensionOffset);
        Append(code, ExtendLongD7);
        Append(code, TestLongD7);
        Append(code, BranchMinusWord);
        var fontWidthSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontWidthSignBranchExtensionOffset);
        Append(code, BranchEqualWord);
        var fontWidthZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontWidthZeroBranchExtensionOffset);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextSpacing));
        Append(code, ExtendLongD2);
        Append(code, AddLongD2ToD7);
        Append(code, TestLongD7);
        Append(code, BranchMinusWord);
        var stepSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(stepSignBranchExtensionOffset);
        Append(code, BranchEqualWord);
        var stepZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(stepZeroBranchExtensionOffset);

        Append(code, MoveWordD0ToD4);
        Append(code, ExtendLongD4);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveQuickZeroD2);

        var fitLoopOffset = code.Count;
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var countExhaustedBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, AddLongD7ToD2);
        Append(code, CompareLongD6ToD2);
        Append(code, BranchHighWord);
        var widthExceededBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, AddQuickOneLongD5);
        Append(code, SubQuickOneLongD4);
        Append(code, BranchAlwaysWord);
        var fitLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        var widthExceededOffset = code.Count;
        Append(code, SubLongD7ToD2);
        Append(code, BranchAlwaysWord);
        var widthExceededFinishBranchExtensionOffset = code.Count;
        Append(code, 0);

        var finishOffset = code.Count;
        Append(code, TestLongD5);
        Append(code, BranchEqualWord);
        var emptyResultBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveAddressA2ToA0);
        Append(code, MoveWordD2ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentWidth));
        Append(code, MoveWordD1ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentHeight));
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinX));
        Append(code, MoveWordD3ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinY));
        Append(code, SubQuickOneLongD2);
        Append(code, MoveWordD2ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxX));
        Append(code, AddLongD3ToD1);
        Append(code, SubQuickOneLongD1);
        Append(code, MoveWordD1ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxY));
        Append(code, MoveLongD5ToD0);
        AppendSuccessBranch(code, successBranches);

        var emptyResultOffset = code.Count;
        Append(code, MoveAddressA2ToA0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentWidth));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentHeight));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinX));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinY));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxX));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxY));
        AppendSuccessBranch(code, successBranches);

        // A reverse marker is checked only after the proportional flag has
        // selected this arm. Fixed-cell reverse TextFit must continue through
        // the common body, while proportional reverse remains on the
        // portable/provider owner until its richer envelope is native.
        var proportionalDirectionCheckOffset = code.Count;
        Append(code, TestLongD5);
        Append(code, BranchNotEqualWord);
        var reverseProportionalBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var proportionalDirectionContinueBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Bounded proportional reverse-direction TextFit.  This arm claims
        // only one declared glyph in the alternate width/height form.  The
        // selected movement cell must be negative; richer reverse walks,
        // explicit TextExtent constraints, REVPATH fonts, styles, and
        // provider-owned forms remain on the existing owner.
        var proportionalReverseEntryOffset = code.Count;
        var proportionalReverseEarlyFallbackBranches = new List<int>(8);
        var proportionalReverseFallbackBranches = new List<int>(24);
        var proportionalReverseNoFitBranches = new List<int>(4);

        Append(code, MoveLongD7ToD1);
        Append(code, CompareImmediateWordD1);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var proportionalReverseCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseEarlyFallbackBranches.Add(proportionalReverseCountBranchExtensionOffset);

        // The common TextFit gate has already required the alternate form
        // (A3 == NULL), but the result descriptor is still caller-owned and
        // must be proven before the reverse arm pushes a stack shadow.
        Append(code, MoveLongA2ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var proportionalReverseExtentNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseEarlyFallbackBranches.Add(proportionalReverseExtentNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalReverseExtentOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseEarlyFallbackBranches.Add(proportionalReverseExtentOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // complete twelve-byte TextExtent envelope
        Append(code, BranchHighWord);
        var proportionalReverseExtentWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseEarlyFallbackBranches.Add(proportionalReverseExtentWrapBranchExtensionOffset);

        Append(code, MoveLongA6ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var proportionalReverseTextNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseEarlyFallbackBranches.Add(proportionalReverseTextNullBranchExtensionOffset);

        // Preserve the alternate height while D3/D4/D5 are used for the
        // bounded font and table checks.  A3 is NULL on every admitted call;
        // the late fallback restores it after the stack shadow is removed.
        Append(code, MoveLongD3ToD2);
        Append(code, MoveLongA2ToD1);
        Append(code, MoveLongD1ToPreDecrementA7);

        // Require one declared glyph (LoChar == HiChar) and select exactly
        // that source byte.  The default slot remains part of the proven
        // table envelope, but is deliberately not claimed by this slice.
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
        Append(code, CompareByteD4ToD3);
        Append(code, BranchNotEqualWord);
        var proportionalReverseRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseRangeBranchExtensionOffset);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA6IndirectToD0);
        Append(code, CompareByteD4ToD0);
        Append(code, BranchNotEqualWord);
        var proportionalReverseCharacterBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharacterBranchExtensionOffset);
        Append(code, MoveLongD7ToD0);
        Append(code, MoveLongD2ToD3); // restore the alternate height

        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontStyle));
        Append(code, TestByteD4);
        Append(code, BranchNotEqualWord);
        var proportionalReverseFontStyleBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseFontStyleBranchExtensionOffset);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAlgoStyle));
        Append(code, TestByteD4);
        Append(code, BranchNotEqualWord);
        var proportionalReverseAlgoStyleBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseAlgoStyleBranchExtensionOffset);

        // Prove the complete declared-plus-default table spans before
        // selecting the first movement cell.  CharLoc is LONG-based; the
        // metric tables are WORD-based and all three bases must be even.
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharLoc));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var proportionalReverseCharLocNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharLocNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalReverseCharLocOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharLocOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8); // two LONG entries remain addressable
        Append(code, BranchHighWord);
        var proportionalReverseCharLocWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharLocWrapBranchExtensionOffset);
        Append(code, MoveAddressD1ToA3);

        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharSpace));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var proportionalReverseCharSpaceNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharSpaceNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalReverseCharSpaceOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharSpaceOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // two WORD entries remain addressable
        Append(code, BranchHighWord);
        var proportionalReverseCharSpaceWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharSpaceWrapBranchExtensionOffset);
        Append(code, MoveAddressD1ToA4);

        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharKern));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var proportionalReverseCharKernNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharKernNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalReverseCharKernOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharKernOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC);
        Append(code, BranchHighWord);
        var proportionalReverseCharKernWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseCharKernWrapBranchExtensionOffset);
        Append(code, MoveAddressD1ToA5);

        // Read both CharLoc entries to prove the complete LONG span, then
        // read both metric entries while retaining the selected negative
        // movement in D0.  The default cells are intentionally read only as
        // an addressability proof; their values do not affect this one-glyph
        // declared-slot claim.
        Append(code, MoveAddressA3ToA2);
        Append(code, MoveLongA2IndirectToD1);
        Append(code, AddQuickFourLongA2);
        Append(code, MoveLongA2IndirectToD1);

        Append(code, MoveAddressA4ToA2);
        Append(code, MoveWordA2ToD1);
        Append(code, ExtendLongD1);
        Append(code, MoveLongD1ToD0);
        Append(code, AddQuickTwoLongA2);
        Append(code, MoveWordA2ToD1);

        Append(code, MoveAddressA5ToA2);
        Append(code, MoveWordA2ToD1);
        Append(code, ExtendLongD1);
        Append(code, AddLongD1ToD0);
        Append(code, AddQuickTwoLongA2);
        Append(code, MoveWordA2ToD1);

        Append(code, TestLongD0);
        Append(code, BranchMinusWord);
        var proportionalReverseNegativeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var proportionalReverseNonNegativeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseNonNegativeBranchExtensionOffset);
        var proportionalReverseMovementValidationOffset = code.Count;

        // A negative movement cell fits the alternate width when its
        // positive magnitude is no larger than the caller's width box.
        Append(code, MoveLongD0ToD1);
        Append(code, NegLongD1);
        Append(code, CompareLongD6ToD1);
        Append(code, BranchHighWord);
        var proportionalReverseWidthNoFitBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseNoFitBranches.Add(proportionalReverseWidthNoFitBranchExtensionOffset);

        // Validate the vertical envelope after the movement cell is known.
        // A too-short alternate box is a valid empty fit; malformed font
        // dimensions and baselines remain transparent fallback cases.
        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontYSize));
        Append(code, TestWordD4);
        Append(code, BranchMinusWord);
        var proportionalReverseHeightSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseHeightSignBranchExtensionOffset);
        Append(code, BranchEqualWord);
        var proportionalReverseHeightZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseHeightZeroBranchExtensionOffset);
        Append(code, CompareLongD2ToD4);
        Append(code, BranchHighWord);
        var proportionalReverseHeightNoFitBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseNoFitBranches.Add(proportionalReverseHeightNoFitBranchExtensionOffset);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.TextFontBaseline));
        Append(code, TestWordD5);
        Append(code, BranchMinusWord);
        var proportionalReverseBaselineSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseBaselineSignBranchExtensionOffset);
        Append(code, CompareWordD5ToD4);
        Append(code, BranchLowerOrSameWord);
        var proportionalReverseBaselineEnvelopeBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalReverseFallbackBranches.Add(proportionalReverseBaselineEnvelopeBranchExtensionOffset);

        // Keep the selected negative movement in D1 and derive the signed
        // result envelope.  The extent pointer is restored from the stack
        // shadow before any caller-owned bytes are written.
        Append(code, NegLongD1);
        Append(code, MoveWordD4ToD6);
        Append(code, SubWordD5ToD6);
        Append(code, SubQuickOneWordD6);
        Append(code, NegWordD5);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveWordD1ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentWidth));
        Append(code, MoveWordD4ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentHeight));
        Append(code, MoveWordD1ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinX));
        Append(code, MoveWordD5ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinY));
        Append(code, MoveWordD6ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxY));
        Append(code, MoveQuickMinusOneD0);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxX));
        Append(code, MoveQuickOneD0);
        AppendSuccessBranch(code, successBranches);

        var proportionalReverseNoFitOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveAddressD0ToA2);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentWidth));
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentHeight));
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinX));
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinY));
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxX));
        Append(code, MoveWordD0ToA2Displacement);
