        var proportionalTextWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalTextWrapBranchExtensionOffset);
        Append(code, MoveAddressA3ToA0);

        Append(code, MoveLongA2ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var proportionalExtentNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalExtentNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var proportionalExtentOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalExtentOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // complete twelve-byte TextExtent envelope
        Append(code, BranchHighWord);
        var proportionalExtentWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalExtentWrapBranchExtensionOffset);

        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontStyle));
        Append(code, TestByteD4);
        Append(code, BranchNotEqualWord);
        var proportionalFontStyleBranchExtensionOffset = code.Count;
        Append(code, 0);
        proportionalFallbackBranches.Add(proportionalFontStyleBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAlgoStyle));
        Append(code, TestByteD4);
