        Append(code, MoveLongD7ToPreDecrementA7);
        Append(code, MoveLongD6ToD2); // saved alternate width
        Append(code, MoveWordD3ToD5);
        Append(code, ExtendLongD5); // saved alternate height
        Append(code, TestWordD7);
        Append(code, BranchEqualWord);
        var multiTextFitZeroCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitZeroCountBranchExtensionOffset);
        Append(code, CompareImmediateWordD7);
        Append(code, 256);
        Append(code, BranchHighWord);
        var multiTextFitCountLimitBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitCountLimitBranchExtensionOffset);

        Append(code, MoveLongA6ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var multiTextFitTextNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitTextNullBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFF00);
        Append(code, BranchHighWord);
        var multiTextFitTextWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitTextWrapBranchExtensionOffset);

        Append(code, MoveLongA2ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var multiTextFitExtentNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitExtentNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var multiTextFitExtentOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitExtentOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4);
        Append(code, BranchHighWord);
        var multiTextFitExtentWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitExtentWrapBranchExtensionOffset);

        Append(code, MoveLongA0ToA3);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontStyle));
        Append(code, TestByteD4);
        Append(code, BranchNotEqualWord);
        var multiTextFitFontStyleBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitFontStyleBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAlgoStyle));
        Append(code, TestByteD4);
        Append(code, BranchNotEqualWord);
        var multiTextFitAlgoStyleBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitAlgoStyleBranchExtensionOffset);

        // Range and table bases.  The declared range is capped at two hundred fifty-six and
        // all spans include the additional default slot.
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA3DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, MoveLongD3ToD4); // preserve the low character
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA3DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
        Append(code, CompareByteD4ToD3);
        Append(code, BranchCarryWord);
        var multiTextFitRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitRangeBranchExtensionOffset);
        Append(code, MoveLongD3ToD0);
        Append(code, MoveLongD4ToD1);
        Append(code, SubLongD1ToD0);
        Append(code, AddQuickOneLongD0);
        Append(code, CompareImmediateWordD0);
        Append(code, 256);
        Append(code, BranchHighWord);
        var multiTextFitRangeLimitBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitRangeLimitBranchExtensionOffset);
        Append(code, AddQuickOneLongD0); // include the proportional default slot

        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharLoc));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var multiTextFitCharLocNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitCharLocNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var multiTextFitCharLocOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitCharLocOddBranchExtensionOffset);
        Append(code, MoveAddressD1ToA0);

        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharSpace));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var multiTextFitCharSpaceNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitCharSpaceNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var multiTextFitCharSpaceOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitCharSpaceOddBranchExtensionOffset);
        Append(code, MoveAddressD1ToA4);

        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharKern));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var multiTextFitCharKernNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitCharKernNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var multiTextFitCharKernOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitCharKernOddBranchExtensionOffset);
        Append(code, MoveAddressD1ToA5);

        // Restore CharLoc in A0 after loading the other table bases.
        Append(code, MoveLongA3DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontCharLoc));
        Append(code, MoveAddressD1ToA0);

        // Preflight the complete LONG/WORD table spans.
        Append(code, MoveLongD0ToD1);
        Append(code, ShiftLeftLongD1);
        Append(code, ShiftLeftLongD1);
        Append(code, MoveLongA0ToD4);
        Append(code, AddLongD1ToD4);
        Append(code, BranchCarryWord);
        var multiTextFitCharLocWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitCharLocWrapBranchExtensionOffset);
        Append(code, MoveLongD0ToD1);
        Append(code, ShiftLeftLongD1);
        Append(code, MoveLongA4ToD4);
        Append(code, AddLongD1ToD4);
        Append(code, BranchCarryWord);
        var multiTextFitCharSpaceWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitCharSpaceWrapBranchExtensionOffset);
        Append(code, MoveLongD0ToD1);
        Append(code, ShiftLeftLongD1);
        Append(code, MoveLongA5ToD4);
        Append(code, AddLongD1ToD4);
        Append(code, BranchCarryWord);
        var multiTextFitCharKernWrapBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitCharKernWrapBranchExtensionOffset);

        Append(code, MoveQuickZeroD4); // accumulated movement
        Append(code, SubQuickOneWordD7); // DBRA count = n - 1
        var multiTextFitLoopOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA6IndirectToD0);
        Append(code, AddQuickOneLongA6);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA3DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, CompareByteD3ToD0);
        Append(code, BranchCarryWord);
        var multiTextFitDefaultSlotBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA3DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
        Append(code, CompareByteD3ToD0);
        Append(code, BranchHighWord);
        var multiTextFitDefaultSlotHighBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA3DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, MoveLongD0ToD1);
        Append(code, SubLongD3ToD1);
        Append(code, BranchAlwaysWord);
        var multiTextFitSlotSelectedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var multiTextFitDefaultSlotOffset = code.Count;
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA3DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontLoChar));
        Append(code, MoveLongD3ToD1); // preserve the low character
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA3DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontHiChar));
        Append(code, MoveLongD3ToD0);
        Append(code, SubLongD1ToD0);
        Append(code, AddQuickOneLongD0);
        Append(code, MoveLongD0ToD1);

        // Read CharLoc, CharSpace, CharKern, and TxSpacing for the selected
        // slot. Each cell must be positive in this bounded native form.
        var multiTextFitMetricOffset = code.Count;
        Append(code, MoveLongD1ToD3); // preserve the selected table index
        Append(code, MoveLongD3ToD0);
        Append(code, ShiftLeftLongD0);
        Append(code, ShiftLeftLongD0);
        Append(code, MoveAddressA0ToA2);
        Append(code, AddLongD0ToA2);
        Append(code, MoveLongA2IndirectToD1);
        Append(code, MoveLongD3ToD0);
        Append(code, ShiftLeftLongD0);
        Append(code, MoveAddressA4ToA2);
        Append(code, AddLongD0ToA2);
        Append(code, MoveWordA2ToD1);
        Append(code, ExtendLongD1);
        Append(code, MoveLongD1ToD0);
        Append(code, MoveLongD3ToD1);
        Append(code, ShiftLeftLongD1);
        Append(code, MoveAddressA5ToA2);
        Append(code, AddLongD1ToA2);
        Append(code, MoveWordA2ToD1);
        Append(code, ExtendLongD1);
        Append(code, AddLongD1ToD0);
        Append(code, MoveWordA1DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextSpacing));
        Append(code, ExtendLongD3);
        Append(code, MoveLongD3ToD1);
        Append(code, AddLongD1ToD0);
        Append(code, TestLongD0);
        Append(code, BranchMinusWord);
        var multiTextFitMetricNegativeBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitMetricNegativeBranchExtensionOffset);
        Append(code, BranchEqualWord);
        var multiTextFitMetricZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitMetricZeroBranchExtensionOffset);
        Append(code, AddLongD0ToD4);
        Append(code, TestLongD4);
        Append(code, BranchMinusWord);
        var multiTextFitAccumulationBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitAccumulationBranchExtensionOffset);
        Append(code, DecrementBranchD7);
        var multiTextFitLoopBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, CompareLongD2ToD4);
        Append(code, BranchHighWord);
        var multiTextFitNoFitBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveAddressA3ToA0);
        Append(code, MoveQuickZeroD3);
        Append(code, MoveWordA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextFontYSize));
        Append(code, TestWordD3);
        Append(code, BranchMinusWord);
        var multiTextFitHeightSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitHeightSignBranchExtensionOffset);
        Append(code, BranchEqualWord);
        var multiTextFitHeightZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitHeightZeroBranchExtensionOffset);
        Append(code, MoveLongD3ToD1);
        Append(code, CompareLongD5ToD1);
        Append(code, BranchHighWord);
        var multiTextFitHeightLimitBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitHeightLimitBranchExtensionOffset);
        Append(code, MoveQuickZeroD5);
        Append(code, MoveWordA0DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.TextFontBaseline));
        Append(code, TestWordD5);
        Append(code, BranchMinusWord);
        var multiTextFitBaselineSignBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitBaselineSignBranchExtensionOffset);
        Append(code, CompareWordD5ToD3);
        Append(code, BranchLowerOrSameWord);
        var multiTextFitBaselineEnvelopeBranchExtensionOffset = code.Count;
        Append(code, 0);
        multiTextFitFallbackBranches.Add(multiTextFitBaselineEnvelopeBranchExtensionOffset);

        Append(code, MoveLongD4ToD2);
        Append(code, MoveAddressD6ToA2);
        Append(code, MoveWordD2ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentWidth));
        Append(code, MoveWordD3ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentHeight));
        Append(code, MoveQuickZeroD4);
        Append(code, MoveWordD4ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinX));
        Append(code, MoveLongD3ToD4);
        Append(code, SubWordD5ToD4);
        Append(code, SubQuickOneWordD4);
        Append(code, MoveWordD4ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxY));
        Append(code, NegWordD5);
        Append(code, MoveWordD5ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinY));
        Append(code, MoveLongD2ToD4);
        Append(code, SubQuickOneLongD4);
        Append(code, MoveWordD4ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxX));
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickOneD0);
        AppendSuccessBranch(code, successBranches);

        var multiTextFitNoFitOffset = code.Count;
        Append(code, MoveAddressD6ToA2);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentWidth));
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentHeight));
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinX));
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMinY));
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxX));
        Append(code, MoveWordD0ToA2Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextExtentMaxY));
        AppendSuccessBranch(code, successBranches);

        var multiTextFitFallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, BranchAlwaysWord);
        var multiTextFitFallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        var successRestoreOffset = code.Count;
        Append(code, MoveLongD0ToD1);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7DFD); // MOVEM.L (A7)+,D0/D2-D7/A0/A2-A6.
        Append(code, MoveLongA7PostIncrementToD0); // discard saved original D1
        Append(code, MoveLongD1ToD0);
        Append(code, ReturnFromSubroutine);

        var declineRestoreOffset = code.Count;
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7DFD); // Restore original D0/A0 and every callee-save register.
        Append(code, MoveLongA7PostIncrementToD1); // restore direction/input provenance
        Append(code, BranchAlwaysWord);
        var declineFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);

        var rastPortFallbackRestoreOffset = code.Count;
        Append(code, MoveLongA7PostIncrementToD1);
        Append(code, BranchAlwaysWord);
        var rastPortFallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, emptyTextPointerBranchExtensionOffset, afterTextPointerGuardOffset);
        PatchBranch(code, countExhaustedBranchExtensionOffset, finishOffset);
        PatchBranch(code, widthExceededBranchExtensionOffset, widthExceededOffset);
        PatchBranch(code, fitLoopBranchExtensionOffset, fitLoopOffset);
        PatchBranch(code, widthExceededFinishBranchExtensionOffset, finishOffset);
        PatchBranch(code, emptyResultBranchExtensionOffset, emptyResultOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, declineRestoreOffset);

        PatchBranch(code, proportionalSlotSelectedBranchExtensionOffset, proportionalMetricOffset);
        PatchBranch(code, proportionalDefaultSlotBranchExtensionOffset, proportionalDefaultSlotOffset);
        PatchBranch(code, proportionalDefaultSlotHighBranchExtensionOffset, proportionalDefaultSlotOffset);
        PatchBranch(code, proportionalNoFitBranchExtensionOffset, proportionalNoFitOffset);
        PatchBranch(code, proportionalFallbackJumpExtensionOffset, declineRestoreOffset);
        foreach (var branchExtensionOffset in proportionalFallbackBranches)
            PatchBranch(code, branchExtensionOffset, proportionalFallbackRestoreOffset);
        PatchBranch(code, reverseProportionalBranchExtensionOffset, proportionalReverseEntryOffset);

        foreach (var branchExtensionOffset in proportionalReverseEarlyFallbackBranches)
            PatchBranch(code, branchExtensionOffset, declineRestoreOffset);
        foreach (var branchExtensionOffset in proportionalReverseFallbackBranches)
            PatchBranch(code, branchExtensionOffset, proportionalReverseFallbackRestoreOffset);
        foreach (var branchExtensionOffset in proportionalReverseNoFitBranches)
            PatchBranch(code, branchExtensionOffset, proportionalReverseNoFitOffset);
        PatchBranch(code, proportionalReverseNegativeBranchExtensionOffset, proportionalReverseMovementValidationOffset);
        PatchBranch(code, proportionalReverseFallbackJumpExtensionOffset, declineRestoreOffset);

        PatchBranch(code, proportionalCountBranchExtensionOffset, multiTextFitEntryOffset);
        PatchBranch(code, multiTextFitDefaultSlotBranchExtensionOffset, multiTextFitDefaultSlotOffset);
        PatchBranch(code, multiTextFitDefaultSlotHighBranchExtensionOffset, multiTextFitDefaultSlotOffset);
        PatchBranch(code, multiTextFitSlotSelectedBranchExtensionOffset, multiTextFitMetricOffset);
        PatchBranch(code, multiTextFitLoopBranchExtensionOffset, multiTextFitLoopOffset);
        PatchBranch(code, multiTextFitNoFitBranchExtensionOffset, multiTextFitNoFitOffset);
        PatchBranch(code, multiTextFitFallbackJumpExtensionOffset, declineRestoreOffset);
        foreach (var branchExtensionOffset in multiTextFitFallbackBranches)
            PatchBranch(code, branchExtensionOffset, multiTextFitFallbackRestoreOffset);

        PatchBranch(code, proportionalDirectionContinueBranchExtensionOffset, proportionalEntryOffset);

        foreach (var branchExtensionOffset in successBranches)
            PatchBranch(code, branchExtensionOffset, successRestoreOffset);
        PatchBranch(code, declineFallbackBranchExtensionOffset, fallbackEntryOffset);

        foreach (var branchExtensionOffset in rastPortFallbackBranches)
            PatchBranch(code, branchExtensionOffset, rastPortFallbackRestoreOffset);
        PatchBranch(code, rastPortFallbackJumpExtensionOffset, fallbackEntryOffset);

        var proportionalBranchDisplacement = checked(proportionalDirectionCheckOffset - proportionalBranchExtensionOffset);
        if (proportionalBranchDisplacement < short.MinValue || proportionalBranchDisplacement > short.MaxValue)
            throw new InvalidOperationException("Native TextFit proportional arm is out of branch range.");

        code[proportionalBranchExtensionOffset] = (byte)((ushort)proportionalBranchDisplacement >> 8);
        code[proportionalBranchExtensionOffset + 1] = (byte)proportionalBranchDisplacement;

        return offset;
    }

    private static int AppendSetFont(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(12);

        // A non-NULL, word-aligned, non-wrapping TextFont public prefix is the
        // direct body-local form. NULL is the classic SetFont(NULL) spelling
        // for GfxBase->DefaultFont; the bounded resolver below admits that
        // form without traversing the font list.
        Append(code, MoveLongD0ToPreDecrementA7);
        Append(code, MoveLongD6ToPreDecrementA7);
        Append(code, MoveLongA1ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullRastPortBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRastPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFC0); // Last even base through RP.TextBaseline at 0x3E.
        Append(code, BranchHighWord);
        var wrappedRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedRastPortBranchExtensionOffset);
        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFCC); // TextFontMinimumSize (0x34) envelope
        Append(code, BranchHighWord);
        var wrappedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedBranchExtensionOffset);

        var fontStoreOffset = code.Count;
        Append(code, MoveLongA0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFont));
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAlgoStyle));

        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontYSize));
        Append(code, MoveWordD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextHeight));
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontXSize));
        Append(code, MoveWordD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextWidth));
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontBaseline));
        Append(code, MoveWordD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortTextBaseline));
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        // SetFont(NULL) resolves the active default through A6, the classic
        // graphics.library base register.  Guard the public GfxBase prefix
        // through DefaultFont (offset 0x9A), then validate the selected
        // TextFont envelope before reusing the ordinary store arm.  A missing
        // or malformed base/default remains available to native/provider
        // ownership and preserves the caller's D0.
        var defaultResolveOffset = code.Count;
        PatchBranch(code, nullBranchExtensionOffset, defaultResolveOffset);
        Append(code, MoveLongA6ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var defaultBaseNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(defaultBaseNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var defaultBaseOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(defaultBaseOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF62); // GfxBase->DefaultFont long envelope
        Append(code, BranchHighWord);
        var defaultBaseWrappedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(defaultBaseWrappedBranchExtensionOffset);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseDefaultFont));
        Append(code, MoveLongD0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var defaultFontNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(defaultFontNullBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var defaultFontOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(defaultFontOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFCC); // TextFontMinimumSize (0x34) envelope
        Append(code, BranchHighWord);
        var defaultFontWrappedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(defaultFontWrappedBranchExtensionOffset);
        Append(code, MoveAddressD1ToA0);
        Append(code, BranchAlwaysWord);
        var defaultFontStoreBranchExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, defaultFontStoreBranchExtensionOffset, fontStoreOffset);
        var restoreD0Offset = code.Count;
        Append(code, MoveLongA7PostIncrementToD6);
        Append(code, MoveLongA7PostIncrementToD0);
        Append(code, ReturnFromSubroutine);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, restoreD0Offset);
        return offset;
    }

    private static int AppendAskFont(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var preAdmissionFallbackBranches = new List<int>(9);

        // AskFont publishes the selected TextFont's four public TextAttr
        // fields.  Keep the native body limited to the fields it actually
        // reads and writes; provider lookup, mapped-memory faults, and the
        // portable transactional rollback remain outside this ROM slice.

        // A0 is the caller-owned TextAttr destination.  Its eight-byte
        // envelope must be even-aligned and non-wrapping before any store.
        // D1 is volatile AskFont scratch, so a malformed call reaches its
        // owner without first leaking D4/D6/D7 or changing the original D0.
        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullTextAttrBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(nullTextAttrBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddTextAttrBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddTextAttrBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8); // TextAttrSize (0x08) envelope
        Append(code, BranchHighWord);
        var wrappedTextAttrBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedTextAttrBranchExtensionOffset);

        // A1 is the RastPort.  AskFont only consumes the Font pointer at
        // RastPort+0x34, so guard that four-byte read rather than demanding a
        // larger host-side allocation than the public operation needs.
        Append(code, MoveLongA1ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(nullRastPortBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddRastPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFC8); // RastPort.Font at offset 0x34
        Append(code, BranchHighWord);
        var wrappedRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedRastPortBranchExtensionOffset);

        // Read and validate the selected TextFont pointer.  The last native
        // byte read is TextFontFlags at +0x17, hence the 0x18-byte envelope.
        Append(code, MoveLongA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFont));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(nullFontBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddFontBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFE8); // TextFontFlags at offset 0x17
        Append(code, BranchHighWord);
        var wrappedFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedFontBranchExtensionOffset);

        // All public pointer admission is complete.  The publication body
        // uses D2 and A2 as scratch, while D3-D7/A3-A6 stay framed as part of
        // the complete 68000 callee-save contract.
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x3F3E); // MOVEM.L D2-D7/A2-A6,-(A7), reversed mask.

        // Preserve the TextAttr destination while A0 becomes the font and A1
        // becomes the destination for the existing 68000 store encodings.
        Append(code, MoveAddressA0ToA2);
        Append(code, MoveAddressD1ToA0);

        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontName));
        Append(code, MoveLongD1ToD0);
        Append(code, MoveAddressA2ToA1);
        Append(code, MoveLongD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextAttrName));

        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextFontYSize));
        Append(code, MoveWordD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextAttrYSize));

        Append(code, MoveQuickZeroD2);
        Append(code, MoveByteA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.TextFontStyle));
        Append(code, MoveByteD2ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextAttrStyle));
        Append(code, MoveQuickZeroD2);
        Append(code, MoveByteA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.TextFontFlags));
        Append(code, MoveByteD2ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextAttrFlags));
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6.
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        foreach (var branchExtensionOffset in preAdmissionFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    private static int AppendNullVoidVector(
        List<byte> code,
        int fallbackEntryOffset,
        ushort loadPointerOpcode)
    {
        var offset = code.Count;

        // StripFont(NULL) is a documented idempotent teardown form.  Keep the
        // native claim read-free for the sentinel and use only volatile D1;
        // non-NULL pointers still require lifecycle ownership and extension
        // teardown, so they retain original D0 and tail-chain unchanged.
        Append(code, loadPointerOpcode);
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var fallbackBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fallbackOffset = code.Count;
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        PatchBranch(code, fallbackBranchExtensionOffset, fallbackOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);

        return offset;
    }

    private static int AppendOpenMonitorDefault(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var preAdmissionFallbackBranches = new List<int>(8);
        var fallbackBranches = new List<int>(1);

        // Names select the first exact registered list node, except the
        // case-insensitive default alias. Nonzero IDs select through CMDB3;
        // exact zero retains the default pointer. Neither path allocates nodes.

        // A supplied name takes precedence over the ID.
        Append(code, MoveLongA1ToD1);
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var namedBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Original Kickstart 3.1 rejects NULL/INVALID_ID. This is a complete
        // native result, not provider fallback; names were handled first because
        // a supplied name takes precedence over the ID. No GfxBase read needed.
        Append(code, CompareImmediateLongD0);
        Append(code, 0xFFFF);
        Append(code, 0xFFFF);
        Append(code, BranchNotEqualWord);
        var notInvalidBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, 0x7000); // MOVEQ #0,D0
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, notInvalidBranchExtensionOffset, code.Count);

        AppendMonitorIdSyntaxAdmission(code, fallbackEntryOffset);
        var registeredSelectionBranch = AppendRegisteredMonitorIdSelection(code, fallbackEntryOffset);

        PatchBranch(code, namedBranchExtensionOffset, code.Count);
        var namedSelectionBranch = AppendMonitorNameSelection(code, fallbackEntryOffset);

        // A6 is the graphics.library base.  Guard the default-monitor field
        // before its displacement read so malformed native envelopes decline
        // instead of turning into a bus error.
        Append(code, MoveLongA6ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(nullBaseBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddBaseBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        var maximumBase = uint.MaxValue -
                          (uint)(GraphicsLayouts.GfxBaseDefaultMonitor + 3);
        Append(code, (ushort)(maximumBase >> 16));
        Append(code, (ushort)maximumBase);
        Append(code, BranchHighWord);
        var wrappedBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedBaseBranchExtensionOffset);

        // Admit the complete selected MonitorSpec through volatile D1 before
        // D7 retains the requested display id for saturation fallback.
        Append(code, MoveLongA6DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseDefaultMonitor));
        PatchBranch(code, namedSelectionBranch, code.Count);
        PatchBranch(code, registeredSelectionBranch, code.Count);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullMonitorBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(nullMonitorBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddMonitorBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddMonitorBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        var maximumMonitor = uint.MaxValue -
                             (uint)(GraphicsLayouts.MonitorSpecSize - 1);
        Append(code, (ushort)(maximumMonitor >> 16));
        Append(code, (ushort)maximumMonitor);
        Append(code, BranchHighWord);
        var wrappedMonitorBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedMonitorBranchExtensionOffset);

        // All request, GfxBase, and selected MonitorSpec admission is now
        // complete.  Frame the resident open-count path so success and the
        // late saturation decline preserve D2-D7/A2-A6 without imposing a
        // stack access on malformed requests that must tail-chain untouched.
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x3F3E); // MOVEM.L D2-D7/A2-A6,-(A7), reversed mask.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongD1ToD0);
        // A resident MonitorSpec is ref-counted in place.  Saturation is a
        // decline rather than a wrap, matching the portable registry's
        // admission rule while keeping this native arm allocation-free.
        Append(code, MoveAddressD0ToA0);
        Append(code, MoveWordA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.MonitorSpecOpenCount));
        Append(code, CompareImmediateWordD1);
        Append(code, 0xFFFF);
        Append(code, BranchEqualWord);
        var saturatedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(saturatedBranchExtensionOffset);
        Append(code, AddImmediateWordD1);
        Append(code, 1);
        Append(code, MoveWordD1ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.MonitorSpecOpenCount));
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6.
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6.
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in preAdmissionFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendCloseMonitorDefault(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var preAdmissionFallbackBranches = new List<int>(6);
        var fallbackBranches = new List<int>(2);

        // CloseMonitor(NULL) is the classic idempotent no-op.  For a
        // non-NULL pointer this native arm only decrements the resident
        // default MonitorSpec.  Named/foreign/provider monitors and any
        // list teardown remain with the portable lifecycle owner.  NULL and
        // the A6 field and selected MonitorSpec boundaries complete through
        // volatile D1 before D7 or any other callee-saved scratch is reused.
        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullMonitorInputBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveLongA6ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(nullBaseBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddBaseBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        var maximumBase = uint.MaxValue -
                          (uint)(GraphicsLayouts.GfxBaseDefaultMonitor + 3);
        Append(code, (ushort)(maximumBase >> 16));
        Append(code, (ushort)maximumBase);
        Append(code, BranchHighWord);
        var wrappedBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedBaseBranchExtensionOffset);

        Append(code, MoveLongA6DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseDefaultMonitor));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var missingDefaultBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(missingDefaultBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddDefaultBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddDefaultBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        var maximumMonitor = uint.MaxValue -
                             (uint)(GraphicsLayouts.MonitorSpecSize - 1);
        Append(code, (ushort)(maximumMonitor >> 16));
        Append(code, (ushort)maximumMonitor);
        Append(code, BranchHighWord);
        var wrappedDefaultBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedDefaultBranchExtensionOffset);

        // All public pointer admission is complete.  Frame resident identity
        // and open-count handling so decrement success and every late decline
        // preserve D2-D7/A2-A6.  CloseMonitor(NULL) remains on its separate
        // read-free, unframed exit.
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x3F3E); // MOVEM.L D2-D7/A2-A6,-(A7), reversed mask.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongD1ToD0);
        Append(code, MoveLongA0ToD1);
        Append(code, CompareLongD0ToD1);
        Append(code, BranchNotEqualWord);
        var foreignMonitorBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(foreignMonitorBranchExtensionOffset);

        Append(code, MoveAddressD1ToA1);
        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.MonitorSpecOpenCount));
        Append(code, TestWordD2);
        Append(code, BranchEqualWord);
        var zeroOpenCountBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(zeroOpenCountBranchExtensionOffset);
        Append(code, SubQuickOneWordD2);
        Append(code, MoveWordD2ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.MonitorSpecOpenCount));

        var successOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6.
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6.
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        var nullSuccessOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, nullMonitorInputBranchExtensionOffset, nullSuccessOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in preAdmissionFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendOpenFontDefault(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var preAdmissionFallbackBranches = new List<int>(9);
        var fallbackBranches = new List<int>(7);

        // This native arm claims the smallest useful ROM form of OpenFont:
        // the request is an ordinary eight-byte TextAttr whose name pointer is
        // exactly the resident default font's tf_Name pointer, and all four
        // public attributes match.  String walks, tagged TTextAttr/DPI
        // matching, allocation, and provider-owned fonts remain with the
        // portable lifecycle owner.  D7 preserves D0 only after request,
        // GfxBase-field, and selected-font admission; malformed A0/A6/font
        // calls reach their owner before that callee-save scratch.

        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullTextAttrBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(nullTextAttrBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddTextAttrBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddTextAttrBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        var maximumTextAttr = uint.MaxValue -
                              (uint)(GraphicsLayouts.TextAttrSize - 1);
        Append(code, (ushort)(maximumTextAttr >> 16));
        Append(code, (ushort)maximumTextAttr);
        Append(code, BranchHighWord);
        var wrappedTextAttrBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedTextAttrBranchExtensionOffset);

        Append(code, MoveLongA6ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(nullBaseBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddBaseBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        var maximumBase = uint.MaxValue -
                          (uint)(GraphicsLayouts.GfxBaseDefaultFont + 3);
        Append(code, (ushort)(maximumBase >> 16));
        Append(code, (ushort)maximumBase);
        Append(code, BranchHighWord);
        var wrappedBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedBaseBranchExtensionOffset);

        // Load the selected default and admit the complete public TextFont
        // prefix while D1 is still the only scratch register.  In particular,
        // do not read the request into D2 or preserve D0 in D7 until a NULL,
        // odd, or wrapping font can no longer decline.
        Append(code, MoveLongA6DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseDefaultFont));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(nullFontBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddFontBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        var maximumFont = uint.MaxValue -
                          (uint)(GraphicsLayouts.TextFontMinimumSize - 1);
        Append(code, (ushort)(maximumFont >> 16));
        Append(code, (ushort)maximumFont);
        Append(code, BranchHighWord);
        var wrappedFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedFontBranchExtensionOffset);

        // All public pointer admission is complete.  Frame the complete match
        // and accessor publication so both the selected-font result and every
        // late decline obey the D2-D7/A2-A6 callee-save contract.
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x3F3E); // MOVEM.L D2-D7/A2-A6,-(A7), reversed mask.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongD1ToD0);
        Append(code, MoveAddressD1ToA1);

        Append(code, MoveLongA0DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.TextAttrName));
        Append(code, MoveWordA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.TextAttrYSize));

        Append(code, MoveLongA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.TextFontName));
        Append(code, CompareLongD5ToD1);
        Append(code, BranchNotEqualWord);
        var nameMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nameMismatchBranchExtensionOffset);

        Append(code, MoveWordA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.TextFontYSize));
        Append(code, MoveWordD6ToD3);
        Append(code, CompareWordD2ToD3);
        Append(code, BranchNotEqualWord);
        var ySizeMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ySizeMismatchBranchExtensionOffset);

        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextAttrStyle));
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontStyle));
        Append(code, CompareByteD4ToD3);
        Append(code, BranchNotEqualWord);
        var styleMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(styleMismatchBranchExtensionOffset);

        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextAttrFlags));
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextFontFlags));
        Append(code, CompareByteD4ToD3);
        Append(code, BranchNotEqualWord);
        var flagsMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(flagsMismatchBranchExtensionOffset);

        Append(code, MoveWordA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.TextFontAccessors));
        Append(code, CompareImmediateWordD6);
        Append(code, 0xFFFF);
        Append(code, BranchEqualWord);
        var saturatedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(saturatedBranchExtensionOffset);
        Append(code, AddImmediateWordD6);
        Append(code, 1);
        Append(code, MoveWordD6ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextFontAccessors));
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6.
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6.
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in preAdmissionFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendCloseFontDefault(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var preAdmissionFallbackBranches = new List<int>(6);
        var fallbackBranches = new List<int>(4);

        // CloseFont(NULL) remains the classic idempotent no-op.  For a
        // non-NULL pointer this native arm only decrements the resident
        // default font; list removal and all foreign/provider fonts remain
        // with the portable lifecycle owner.  NULL and the A6 field boundary
        // complete before D7 or any other callee-saved scratch is reused.
        Append(code, MoveLongA1ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullFontInputBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, MoveLongA6ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(nullBaseBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddBaseBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        var maximumBase = uint.MaxValue -
                          (uint)(GraphicsLayouts.GfxBaseDefaultFont + 3);
        Append(code, (ushort)(maximumBase >> 16));
        Append(code, (ushort)maximumBase);
        Append(code, BranchHighWord);
        var wrappedBaseBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedBaseBranchExtensionOffset);

        // Admit the complete selected TextFont prefix through volatile D1.
        // Only after this check may D7 preserve the incoming D0 for identity
        // or accessor declines.
        Append(code, MoveLongA6DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseDefaultFont));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var missingDefaultBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(missingDefaultBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddDefaultBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddDefaultBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        var maximumFont = uint.MaxValue -
                          (uint)(GraphicsLayouts.TextFontMinimumSize - 1);
        Append(code, (ushort)(maximumFont >> 16));
        Append(code, (ushort)maximumFont);
        Append(code, BranchHighWord);
        var wrappedDefaultBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedDefaultBranchExtensionOffset);

        // All public pointer admission is complete.  Frame the resident-font
        // identity/accessor path so success and every late decline preserve
        // D2-D7/A2-A6.  CloseFont(NULL) remains on its separate unframed exit.
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x3F3E); // MOVEM.L D2-D7/A2-A6,-(A7), reversed mask.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongD1ToD0);
        Append(code, MoveLongA1ToD1);
        Append(code, CompareLongD0ToD1);
        Append(code, BranchNotEqualWord);
        var foreignFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(foreignFontBranchExtensionOffset);

        Append(code, MoveWordA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.TextFontAccessors));
        Append(code, CompareImmediateWordD2);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var zeroAccessorBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, SubQuickOneWordD2);
        Append(code, MoveWordD2ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.TextFontAccessors));

        var successOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6.
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, zeroAccessorBranchExtensionOffset, successOffset);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6.
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);

        var nullSuccessOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, nullFontInputBranchExtensionOffset, nullSuccessOffset);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in preAdmissionFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendWeighTAMatchExact(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var preAdmissionFallbackBranches = new List<int>(7);
        var fallbackBranches = new List<int>(5);

        // WeighTAMatch has a large style/size/DPI ranking surface.  The
        // native ROM slice claims only the exact, untagged metric: A0/A1 are
        // complete eight-byte TextAttrs, A2 is NULL, and YSize/style/flags
        // match bit-for-bit.  A successful exact pair has Kickstart's
        // MAXFONTMATCHWEIGHT (32767); all richer or unsuitable forms retain
        // their original D0 and fall through to the portable matcher.
        // Reject tags and guard both complete TextAttrs through volatile D1.
        // No callee-saved ranking scratch may be touched until this complete
        // public-input admission phase has succeeded.
        Append(code, MoveLongA2ToD1);
        Append(code, TestLongD1);
        Append(code, BranchNotEqualWord);
        var targetTagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(targetTagsBranchExtensionOffset);

        Append(code, MoveLongA0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullRequestedBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(nullRequestedBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRequestedBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddRequestedBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        var maximumTextAttr = uint.MaxValue -
                              (uint)(GraphicsLayouts.TextAttrSize - 1);
        Append(code, (ushort)(maximumTextAttr >> 16));
        Append(code, (ushort)maximumTextAttr);
        Append(code, BranchHighWord);
        var wrappedRequestedBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedRequestedBranchExtensionOffset);

        Append(code, MoveLongA1ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullTargetBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(nullTargetBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddTargetBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(oddTargetBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, (ushort)(maximumTextAttr >> 16));
        Append(code, (ushort)maximumTextAttr);
        Append(code, BranchHighWord);
        var wrappedTargetBranchExtensionOffset = code.Count;
        Append(code, 0);
        preAdmissionFallbackBranches.Add(wrappedTargetBranchExtensionOffset);

        // All public inputs are admitted.  Frame the exact ranking path so
        // its terminal result and every late owner decline preserve the full
        // D2-D7/A2-A6 public callee-save set.
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x3F3E); // MOVEM.L D2-D7/A2-A6,-(A7), reversed mask.
        Append(code, MoveLongD0ToD7);

        Append(code, MoveWordA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextAttrYSize));
        Append(code, MoveWordA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextAttrYSize));
        Append(code, CompareWordD3ToD4);
        Append(code, BranchNotEqualWord);
        var ySizeMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(ySizeMismatchBranchExtensionOffset);

        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextAttrStyle));
        Append(code, BitTestImmediateD3);
        Append(code, 7);
        Append(code, BranchNotEqualWord);
        var taggedRequestedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(taggedRequestedBranchExtensionOffset);
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextAttrStyle));
        Append(code, BitTestImmediateD4);
        Append(code, 7);
        Append(code, BranchNotEqualWord);
        var taggedTargetBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(taggedTargetBranchExtensionOffset);
        Append(code, CompareByteD4ToD3);
        Append(code, BranchNotEqualWord);
        var styleMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(styleMismatchBranchExtensionOffset);

        Append(code, MoveByteA0DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.TextAttrFlags));
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.TextAttrFlags));
        Append(code, CompareByteD4ToD3);
        Append(code, BranchNotEqualWord);
        var flagsMismatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(flagsMismatchBranchExtensionOffset);

        Append(code, MoveQuickZeroD0);
        Append(code, MoveImmediateWordD0);
        Append(code, 0x7FFF);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6.
        Append(code, ReturnFromSubroutine);

        var fallbackRestoreOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x7CFC); // MOVEM.L (A7)+,D2-D7/A2-A6.
        Append(code, BranchAlwaysWord);
        var fallbackJumpExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, fallbackJumpExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in preAdmissionFallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, fallbackRestoreOffset);

        return offset;
    }

    private static int AppendGetRpAttrsAPen(
        List<byte> code,
        int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(10);

        // This native slice owns one bounded query shape only:
        //   A0 -> { RPTAG_Font/RPTAG_SoftStyle/RPTAG_APen/RPTAG_BPen/RPTAG_DrMd/
        //           RPTAG_OutlinePen/RPTAG_WriteMask/RPTAG_MaxPen/
        //           RPTAG_DrawBounds,
        //           output ULONG pointer,
        //           TAG_DONE, 0 }
        // A NULL tag pointer is the empty-list spelling, but the RastPort
        // alignment/envelope still belongs to the query ABI.  Unknown tags,
        // chains, extra items, and malformed output destinations remain on
        // the portable/provider boundary.
        Append(code, MoveLongD0ToD7);

        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullTagsBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddTagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddTagsBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // two TagItems (0x0C) envelope
        Append(code, BranchHighWord);
        var wrappedTagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedTagsBranchExtensionOffset);

        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullRastPortBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRastPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFE6); // RastPort.FgPen at offset 0x19
        Append(code, BranchHighWord);
        var wrappedRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedRastPortBranchExtensionOffset);

        // A NULL list and a first TAG_DONE both produce the empty successful
        // query result after the RastPort envelope has been checked. The
        // Font arm reads only RastPort.Font; SoftStyle remains a guarded
        // TextFont query.
        Append(code, MoveLongA0DisplacementToD2);
        Append(code, 0);
        Append(code, MoveLongD2ToD3);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var doneTagBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0000); // RPTAG_Font
        Append(code, BranchNotEqualWord);
        var checkSoftStyleBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var fontAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkSoftStyleOffset = code.Count;
        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0001); // RPTAG_SoftStyle
        Append(code, BranchNotEqualWord);
        var checkAPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var softStyleAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkAPenOffset = code.Count;
        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0002); // RPTAG_APen
        Append(code, BranchNotEqualWord);
        var checkBPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var apenAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkBPenOffset = code.Count;
        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0003); // RPTAG_BPen
        Append(code, BranchNotEqualWord);
        var checkDrMdBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var bpenAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkDrMdOffset = code.Count;
        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0004); // RPTAG_DrMd
        Append(code, BranchNotEqualWord);
        var checkOutlinePenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var drMdAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkOutlinePenOffset = code.Count;
        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0005); // RPTAG_OutlinePen
        Append(code, BranchNotEqualWord);
        var checkWriteMaskBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var outlinePenAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkWriteMaskOffset = code.Count;
        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0006); // RPTAG_WriteMask
        Append(code, BranchNotEqualWord);
        var checkMaxPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var writeMaskAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkMaxPenOffset = code.Count;
        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0007); // RPTAG_MaxPen
        Append(code, BranchNotEqualWord);
        var checkDrawBoundsBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var maxPenAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkDrawBoundsOffset = code.Count;
        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0008); // RPTAG_DrawBounds
        Append(code, BranchNotEqualWord);
        var unsupportedTagBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedTagBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var drawBoundsAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        var tagAcceptedOffset = code.Count;
        PatchBranch(code, checkBPenBranchExtensionOffset, checkBPenOffset);
        PatchBranch(code, checkDrMdBranchExtensionOffset, checkDrMdOffset);
        PatchBranch(code, checkOutlinePenBranchExtensionOffset, checkOutlinePenOffset);
        PatchBranch(code, checkWriteMaskBranchExtensionOffset, checkWriteMaskOffset);
        PatchBranch(code, checkMaxPenBranchExtensionOffset, checkMaxPenOffset);
        PatchBranch(code, checkDrawBoundsBranchExtensionOffset, checkDrawBoundsOffset);
        PatchBranch(code, checkSoftStyleBranchExtensionOffset, checkSoftStyleOffset);
        PatchBranch(code, fontAcceptedBranchExtensionOffset, tagAcceptedOffset);
        PatchBranch(code, apenAcceptedBranchExtensionOffset, tagAcceptedOffset);
        PatchBranch(code, bpenAcceptedBranchExtensionOffset, tagAcceptedOffset);
        PatchBranch(code, drMdAcceptedBranchExtensionOffset, tagAcceptedOffset);
        PatchBranch(code, outlinePenAcceptedBranchExtensionOffset, tagAcceptedOffset);
        PatchBranch(code, writeMaskAcceptedBranchExtensionOffset, tagAcceptedOffset);
        PatchBranch(code, maxPenAcceptedBranchExtensionOffset, tagAcceptedOffset);
        PatchBranch(code, drawBoundsAcceptedBranchExtensionOffset, tagAcceptedOffset);
        PatchBranch(code, checkAPenBranchExtensionOffset, checkAPenOffset);
        PatchBranch(code, softStyleAcceptedBranchExtensionOffset, tagAcceptedOffset);

        // Admit exactly one Font/SoftStyle/APen/BPen/DrMd/OutlinePen/WriteMask/
        // MaxPen/DrawBounds item.
        // The second TagItem must terminate the list; TAG_MORE/TAG_SKIP and
        // provider-private chains are declined.
        Append(code, MoveLongA0DisplacementToD2);
        Append(code, 8);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var trailingTagBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(trailingTagBranchExtensionOffset);

        // Font and SoftStyle read RastPort.Font at +0x34.  The common
        // RastPort guard above is intentionally sparse for scalar fields, so
        // extend the envelope only for these two text-query arms.
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0000); // RPTAG_Font
        Append(code, BranchNotEqualWord);
        var checkSoftStyleEnvelopeBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFC8); // RastPort.Font long envelope
        Append(code, BranchHighWord);
        var fontEnvelopeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontEnvelopeBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var fontEnvelopeDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkSoftStyleEnvelopeOffset = code.Count;
        PatchBranch(code, checkSoftStyleEnvelopeBranchExtensionOffset, checkSoftStyleEnvelopeOffset);
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0001); // RPTAG_SoftStyle
        Append(code, BranchNotEqualWord);
        var softStyleTagSkipBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFC8); // RastPort.Font long envelope
        Append(code, BranchHighWord);
        var softStyleEnvelopeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(softStyleEnvelopeBranchExtensionOffset);
        var textEnvelopeDoneOffset = code.Count;
        PatchBranch(code, fontEnvelopeDoneBranchExtensionOffset, textEnvelopeDoneOffset);
        PatchBranch(code, softStyleTagSkipBranchExtensionOffset, textEnvelopeDoneOffset);

        // The scalar Data field is a guest ULONG destination.  RPTAG_MaxPen
        // additionally permits a NULL destination as a successful no-op;
        // DrawBounds requires an aligned, non-wrapping eight-byte Rectangle;
        // all other admitted tags require the complete aligned four-byte
        // store.
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, 4);
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0008); // RPTAG_DrawBounds
        Append(code, BranchNotEqualWord);
        var scalarOutputCheckBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var drawBoundsNullOutputBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsNullOutputBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawBoundsOddOutputBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsOddOutputBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFF8); // Rectangle envelope
        Append(code, BranchHighWord);
        var drawBoundsWrappedOutputBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsWrappedOutputBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var drawBoundsOutputReadyBranchExtensionOffset = code.Count;
        Append(code, 0);

        var scalarOutputCheckOffset = code.Count;
        PatchBranch(code, scalarOutputCheckBranchExtensionOffset, scalarOutputCheckOffset);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var zeroOutputBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddOutputBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddOutputBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFFC); // ULONG output envelope
        Append(code, BranchHighWord);
        var wrappedOutputBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedOutputBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var normalDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);

        var maxPenNullCheckOffset = code.Count;
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0007); // RPTAG_MaxPen
        Append(code, BranchNotEqualWord);
        var maxPenNullFallbackBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maxPenNullFallbackBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var maxPenNullSuccessBranchExtensionOffset = code.Count;
        Append(code, 0);

        var normalDispatchOffset = code.Count;
        PatchBranch(code, zeroOutputBranchExtensionOffset, maxPenNullCheckOffset);
        PatchBranch(code, normalDispatchBranchExtensionOffset, normalDispatchOffset);
        PatchBranch(code, drawBoundsOutputReadyBranchExtensionOffset, normalDispatchOffset);

        Append(code, MoveQuickZeroD0);
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0008); // RPTAG_DrawBounds
        Append(code, BranchNotEqualWord);
        var drawBoundsDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);

        // Standard-planar DrawBounds is the bitmap rectangle. A non-NULL
        // Layer belongs to layers.library/provider clipping and declines
        // before any result write. Both dimensions retain the signed-WORD
        // result contract of the portable path.
        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLayer));
        Append(code, TestLongD2);
        Append(code, BranchNotEqualWord);
        var drawBoundsLayerBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsLayerBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBitMap));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var drawBoundsNullBitmapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsNullBitmapBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawBoundsOddBitmapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsOddBitmapBranchExtensionOffset);
        Append(code, CompareImmediateLongD2);
        Append(code, 0xFFFF);
        Append(code, 0xFFFA); // BitMap depth byte envelope
        Append(code, BranchHighWord);
        var drawBoundsWrappedBitmapBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsWrappedBitmapBranchExtensionOffset);
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveWordA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.BitMapBytesPerRow));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var drawBoundsZeroWidthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsZeroWidthBranchExtensionOffset);
        Append(code, BitTestImmediateD0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var drawBoundsOddBytesPerRowBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsOddBytesPerRowBranchExtensionOffset);
        Append(code, MoveLongD0ToD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0x0000);
        Append(code, 0x1000); // width is BytesPerRow * 8
        Append(code, BranchHighWord);
        var drawBoundsWideBytesBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsWideBytesBranchExtensionOffset);
        Append(code, ShiftLeftLongD6);
        Append(code, ShiftLeftLongD6);
        Append(code, ShiftLeftLongD6);
        Append(code, CompareImmediateLongD6);
        Append(code, 0x0000);
        Append(code, 0x8000); // width must fit signed max edge after -1
        Append(code, BranchHighWord);
        var drawBoundsWideBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsWideBranchExtensionOffset);
        Append(code, SubQuickOneWordD6);
        Append(code, MoveQuickZeroD2);
        Append(code, MoveWordA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.BitMapRows));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var drawBoundsZeroHeightBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsZeroHeightBranchExtensionOffset);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapFlags));
        Append(code, BitTestImmediateD4);
        Append(code, 2); // BMF_INTERLEAVED remains provider/native-owned
        Append(code, BranchNotEqualWord);
        var drawBoundsInterleavedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsInterleavedBranchExtensionOffset);
        Append(code, MoveQuickZeroD4);
        Append(code, MoveByteA0DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.BitMapDepth));
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var drawBoundsZeroDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsZeroDepthBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0x0000);
        Append(code, 0x0008); // OCS/ECS depth range
        Append(code, BranchHighWord);
        var drawBoundsWideDepthBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsWideDepthBranchExtensionOffset);
        Append(code, CompareImmediateLongD2);
        Append(code, 0x0000);
        Append(code, 0x8000); // height must fit signed max edge after -1
        Append(code, BranchHighWord);
        var drawBoundsHighBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(drawBoundsHighBranchExtensionOffset);
        Append(code, SubQuickOneWordD2);
        Append(code, MoveAddressD1ToA0);
        Append(code, MoveLongD6ToD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMaxX));
        Append(code, MoveQuickZeroD0);
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMinX));
        Append(code, MoveWordD0ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMinY));
        Append(code, MoveWordD2ToA0Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RectangleMaxY));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var fontDispatchOffset = code.Count;
        PatchBranch(code, drawBoundsDispatchBranchExtensionOffset, fontDispatchOffset);
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0000); // RPTAG_Font
        Append(code, BranchNotEqualWord);
        var fontReadBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFont));
        Append(code, BranchAlwaysWord);
        var fontReadStoreBranchExtensionOffset = code.Count;
        Append(code, 0);

        var softStyleDispatchOffset = code.Count;
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0001); // RPTAG_SoftStyle
        Append(code, BranchNotEqualWord);
        var softStyleReadBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFont));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var softStyleNullFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var softStyleOddFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, CompareImmediateLongD2);
        Append(code, 0xFFFF);
        Append(code, 0xFFCC); // TextFontMinimumSize (0x34) envelope
        Append(code, BranchHighWord);
        var softStyleWrappedFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveQuickMinusOneD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.TextFontStyle));
        Append(code, NotByteD0);
        Append(code, BranchAlwaysWord);
        var softStyleReadDoneBranchExtensionOffset = code.Count;
        Append(code, 0);

        var softStyleReadDoneOffset = code.Count;
        PatchBranch(code, softStyleReadBranchExtensionOffset, softStyleReadDoneOffset);

        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0002); // RPTAG_APen
        Append(code, BranchNotEqualWord);
        var bpenReadBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, BranchAlwaysWord);
        var afterPenReadBranchExtensionOffset = code.Count;
        Append(code, 0);
        var bpenReadTarget = code.Count;
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0003); // RPTAG_BPen
        Append(code, BranchNotEqualWord);
        var drMdReadBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, BranchAlwaysWord);
        var afterBpenReadBranchExtensionOffset = code.Count;
        Append(code, 0);
        var drMdReadTarget = code.Count;
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0004); // RPTAG_DrMd
        Append(code, BranchNotEqualWord);
        var outlinePenReadBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, BranchAlwaysWord);
        var afterDrMdReadBranchExtensionOffset = code.Count;
        Append(code, 0);
        var outlinePenReadTarget = code.Count;
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0005); // RPTAG_OutlinePen
        Append(code, BranchNotEqualWord);
        var writeMaskReadBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortOutlinePen));
        Append(code, BranchAlwaysWord);
        var afterOutlinePenReadBranchExtensionOffset = code.Count;
        Append(code, 0);
        var writeMaskReadTarget = code.Count;
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0006); // RPTAG_WriteMask
        Append(code, BranchNotEqualWord);
        var maxPenReadBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BranchAlwaysWord);
        var afterWriteMaskReadBranchExtensionOffset = code.Count;
        Append(code, 0);
        var maxPenReadTarget = code.Count;
        Append(code, MoveLongD1ToD6);
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, TestLongD0);
        Append(code, BranchEqualWord);
        var zeroMaskBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveQuickOneD1);
        var maxPenLoopOffset = code.Count;
        Append(code, ShiftRightLongD0);
        Append(code, ShiftLeftLongD1);
        Append(code, TestLongD0);
        Append(code, BranchNotEqualWord);
        var maxPenLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var afterMaxPenCalcBranchExtensionOffset = code.Count;
        Append(code, 0);
        var zeroMaskTarget = code.Count;
        Append(code, MoveQuickOneD1);
        for (var shift = 0; shift < 8; shift++)
            Append(code, ShiftLeftLongD1);
        var maxPenResultToD0Offset = code.Count;
        Append(code, MoveLongD1ToD0);
        Append(code, MoveLongD6ToD1);
        Append(code, BranchAlwaysWord);
        var maxPenResultStoreBranchExtensionOffset = code.Count;
        Append(code, 0);
        var afterPenReadOffset = code.Count;
        PatchBranch(code, bpenReadBranchExtensionOffset, bpenReadTarget);
        PatchBranch(code, afterPenReadBranchExtensionOffset, afterPenReadOffset);
        PatchBranch(code, afterBpenReadBranchExtensionOffset, afterPenReadOffset);
        PatchBranch(code, drMdReadBranchExtensionOffset, drMdReadTarget);
        PatchBranch(code, outlinePenReadBranchExtensionOffset, outlinePenReadTarget);
        PatchBranch(code, afterDrMdReadBranchExtensionOffset, afterPenReadOffset);
        PatchBranch(code, writeMaskReadBranchExtensionOffset, writeMaskReadTarget);
        PatchBranch(code, afterOutlinePenReadBranchExtensionOffset, afterPenReadOffset);
        PatchBranch(code, maxPenReadBranchExtensionOffset, maxPenReadTarget);
        PatchBranch(code, afterWriteMaskReadBranchExtensionOffset, afterPenReadOffset);
        PatchBranch(code, zeroMaskBranchExtensionOffset, zeroMaskTarget);
        PatchBranch(code, maxPenLoopBranchExtensionOffset, maxPenLoopOffset);
        PatchBranch(code, afterMaxPenCalcBranchExtensionOffset, maxPenResultToD0Offset);
        PatchBranch(code, maxPenResultStoreBranchExtensionOffset, afterPenReadOffset);
        PatchBranch(code, fontReadBranchExtensionOffset, softStyleDispatchOffset);
        PatchBranch(code, fontReadStoreBranchExtensionOffset, afterPenReadOffset);
        PatchBranch(code, softStyleNullFontBranchExtensionOffset, afterPenReadOffset);
        PatchBranch(code, softStyleReadDoneBranchExtensionOffset, afterPenReadOffset);
        Append(code, MoveAddressD1ToA0);
        Append(code, MoveLongD0ToA0Displacement);
        Append(code, 0);
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var emptySuccessOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);
        PatchBranch(code, maxPenNullSuccessBranchExtensionOffset, emptySuccessOffset);

        var malformedOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var malformedBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, malformedBranchExtensionOffset, fallbackEntryOffset);
        PatchBranch(code, softStyleOddFontBranchExtensionOffset, malformedOffset);
        PatchBranch(code, softStyleWrappedFontBranchExtensionOffset, malformedOffset);

        PatchBranch(code, nullTagsBranchExtensionOffset, emptySuccessOffset);
        PatchBranch(code, doneTagBranchExtensionOffset, emptySuccessOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, malformedOffset);

        return offset;
    }

    private static int AppendSetRpAttrsAPen(
        List<byte> code,
        int fallbackEntryOffset,
        int setFontEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(11);
        var successBranches = new List<int>(6);
        var scalarSuccessBranches = new List<int>(4);

        // This native slice owns one bounded setter shape only:
        //   A0 -> { RPTAG_APen/RPTAG_BPen/RPTAG_DrMd/RPTAG_OutlinePen/
        //           RPTAG_WriteMask/RPTAG_MaxPen, value, TAG_DONE, 0 }
        // A1 is the caller-owned RastPort.  APen/BPen/DrMd publish their
        // byte, restart the line-pattern phase, regenerate all eight public
        // minterms, and clear the private no-pens bit.  OutlinePen, WriteMask,
        // and MaxPen are scalar paths and do not enter that minterm update.
        // Unknown tags, chains, extra items, and malformed envelopes stay on
        // the portable/provider boundary.
        Append(code, MoveLongD0ToD7);

        // Empty tag lists still require the classic non-NULL, even RastPort
        // ABI, but no RastPort field is touched until an APen item is seen.
        // The SoftStyle tag is admitted by the same bounded parser below;
        // font access remains guarded at its scalar dispatch arm.
        Append(code, MoveLongA1ToD4);
        Append(code, TestLongD4);
        Append(code, BranchEqualWord);
        var nullRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullRastPortBranchExtensionOffset);
        Append(code, BitTestImmediateD4);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRastPortBranchExtensionOffset);

        Append(code, MoveLongA0ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var nullTagsBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddTagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddTagsBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFFF4); // two TagItems (0x0C) envelope
        Append(code, BranchHighWord);
        var wrappedTagsBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedTagsBranchExtensionOffset);

        Append(code, MoveLongA0DisplacementToD2);
        Append(code, 0);
        Append(code, MoveLongD2ToD3);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 0);
        Append(code, BranchEqualWord);
        var doneTagBranchExtensionOffset = code.Count;
        Append(code, 0);

        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0000); // RPTAG_Font
        Append(code, BranchNotEqualWord);
        var checkSoftStyleBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var fontAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkSoftStyleOffset = code.Count;
        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0001); // RPTAG_SoftStyle
        Append(code, BranchNotEqualWord);
        var checkAPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var softStyleAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkAPenOffset = code.Count;
        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0002); // RPTAG_APen
        Append(code, BranchNotEqualWord);
        var checkBPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var apenAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkBPenOffset = code.Count;
        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0003); // RPTAG_BPen
        Append(code, BranchNotEqualWord);
        var checkDrMdBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var bpenAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkDrMdOffset = code.Count;
        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0004); // RPTAG_DrMd
        Append(code, BranchNotEqualWord);
        var checkOutlinePenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var drMdAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkOutlinePenOffset = code.Count;
        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0005); // RPTAG_OutlinePen
        Append(code, BranchNotEqualWord);
        var checkWriteMaskBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var outlinePenAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkWriteMaskOffset = code.Count;
        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0006); // RPTAG_WriteMask
        Append(code, BranchNotEqualWord);
        var checkMaxPenBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BranchAlwaysWord);
        var writeMaskAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);

        var checkMaxPenOffset = code.Count;
        Append(code, CompareImmediateLongD2);
        Append(code, 0x8000);
        Append(code, 0x0007); // RPTAG_MaxPen
        Append(code, BranchNotEqualWord);
        var unsupportedTagBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(unsupportedTagBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var maxPenAcceptedBranchExtensionOffset = code.Count;
        Append(code, 0);
        var tagAcceptedOffset = code.Count;
        PatchBranch(code, checkBPenBranchExtensionOffset, checkBPenOffset);
        PatchBranch(code, checkDrMdBranchExtensionOffset, checkDrMdOffset);
        PatchBranch(code, checkOutlinePenBranchExtensionOffset, checkOutlinePenOffset);
        PatchBranch(code, checkWriteMaskBranchExtensionOffset, checkWriteMaskOffset);
        PatchBranch(code, checkMaxPenBranchExtensionOffset, checkMaxPenOffset);
        PatchBranch(code, apenAcceptedBranchExtensionOffset, tagAcceptedOffset);
        PatchBranch(code, bpenAcceptedBranchExtensionOffset, tagAcceptedOffset);
        PatchBranch(code, drMdAcceptedBranchExtensionOffset, tagAcceptedOffset);
        PatchBranch(code, outlinePenAcceptedBranchExtensionOffset, tagAcceptedOffset);
        PatchBranch(code, writeMaskAcceptedBranchExtensionOffset, tagAcceptedOffset);
        PatchBranch(code, maxPenAcceptedBranchExtensionOffset, tagAcceptedOffset);
        PatchBranch(code, checkAPenBranchExtensionOffset, checkAPenOffset);
        PatchBranch(code, softStyleAcceptedBranchExtensionOffset, tagAcceptedOffset);
        PatchBranch(code, checkSoftStyleBranchExtensionOffset, checkSoftStyleOffset);
        PatchBranch(code, fontAcceptedBranchExtensionOffset, tagAcceptedOffset);

        // Validate the second TagItem before any RastPort write.  The selected
        // pen value is an ULONG and intentionally truncates to the public byte
        // field, matching SetAPen/SetBPen's classic ABI.
        Append(code, MoveLongA0DisplacementToD2);
        Append(code, 8);
        Append(code, CompareImmediateLongD2);
        Append(code, 0);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var trailingTagBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(trailingTagBranchExtensionOffset);
        Append(code, MoveLongA0DisplacementToD1);
        Append(code, 4);

        // APen's largest native write is Minterms[0..7] at offset 0x28.  The
        // maximum valid even base is therefore FFFF:FFD0.
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFD0); // RastPort.Minterms end at offset 0x2F
        Append(code, BranchHighWord);
        var wrappedRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedRastPortBranchExtensionOffset);

        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0000); // RPTAG_Font
        Append(code, BranchNotEqualWord);
        var softStyleDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);

        var fontValidationOffset = code.Count;
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var fontNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var fontOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFCC); // TextFontMinimumSize (0x34) envelope
        Append(code, BranchHighWord);
        var fontWrappedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontWrappedBranchExtensionOffset);
        Append(code, CompareImmediateLongD4);
        Append(code, 0xFFFF);
        Append(code, 0xFFC0); // RastPort.TextBaseline end at offset 0x3F
        Append(code, BranchHighWord);
        var fontRastPortWrappedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(fontRastPortWrappedBranchExtensionOffset);
        Append(code, MoveAddressD1ToA0);
        Append(code, BranchAlwaysWord);
        var fontSetBranchExtensionOffset = code.Count;
        Append(code, 0);

        // RPTAG_Font=0 is SetFont(NULL)'s classic GfxBase default-font form.
        // Resolve it through the library base in A6 only after the caller's
        // RastPort/tag envelopes have passed.  The pointer and public prefix
        // are then rechecked by the shared font-validation arm above.
        var fontDefaultResolveOffset = code.Count;
        PatchBranch(code, fontNullBranchExtensionOffset, fontDefaultResolveOffset);
        Append(code, MoveLongA6ToD6);
        Append(code, TestLongD6);
        Append(code, BranchEqualWord);
        var defaultBaseNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(defaultBaseNullBranchExtensionOffset);
        Append(code, BitTestImmediateD6);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var defaultBaseOddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(defaultBaseOddBranchExtensionOffset);
        Append(code, CompareImmediateLongD6);
        Append(code, 0xFFFF);
        Append(code, 0xFF62); // GfxBase->DefaultFont long envelope
        Append(code, BranchHighWord);
        var defaultBaseWrappedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(defaultBaseWrappedBranchExtensionOffset);
        Append(code, MoveLongA6DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.GfxBaseDefaultFont));
        Append(code, MoveLongD0ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var resolvedDefaultNullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(resolvedDefaultNullBranchExtensionOffset);
        Append(code, BranchAlwaysWord);
        var defaultFontValidationBranchExtensionOffset = code.Count;
        Append(code, 0);

        var softStyleDispatchOffset = code.Count;
        PatchBranch(code, defaultFontValidationBranchExtensionOffset, fontValidationOffset);
        PatchBranch(code, softStyleDispatchBranchExtensionOffset, softStyleDispatchOffset);
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0001); // RPTAG_SoftStyle
        Append(code, BranchNotEqualWord);
        var apenDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);

        // The SetRPAttrsA SoftStyle arm uses the classic full enable mask
        // contract. Guard the selected TextFont envelope before reading its
        // intrinsic style byte, then publish AlgoStyle and return success.
        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFont));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var softStyleNullFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(softStyleNullFontBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var softStyleOddFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(softStyleOddFontBranchExtensionOffset);
        Append(code, CompareImmediateLongD2);
        Append(code, 0xFFFF);
        Append(code, 0xFFCC); // TextFontMinimumSize (0x34) envelope
        Append(code, BranchHighWord);
        var softStyleWrappedFontBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(softStyleWrappedFontBranchExtensionOffset);
        Append(code, MoveLongD1ToD0);
        Append(code, MoveQuickMinusOneD1);
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveQuickZeroD2);
        Append(code, MoveByteA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.TextFontStyle));
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA1DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAlgoStyle));
        Append(code, MoveLongD2ToD4);
        Append(code, NotLongD4);
        Append(code, AndLongD1ToD4);
        Append(code, MoveLongD4ToD5);
        Append(code, NotLongD5);
        Append(code, AndLongD3ToD5);
        Append(code, MoveLongD4ToD6);
        Append(code, AndLongD0ToD6);
        Append(code, OrLongD6ToD5);
        Append(code, MoveByteD5ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAlgoStyle));
        Append(code, MoveQuickZeroD0);
        Append(code, BranchAlwaysWord);
        scalarSuccessBranches.Add(code.Count);
        Append(code, 0);

        var apenDispatchOffset = code.Count;
        PatchBranch(code, apenDispatchBranchExtensionOffset, apenDispatchOffset);
        PatchBranch(code, fontSetBranchExtensionOffset, setFontEntryOffset);

        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0002); // RPTAG_APen
        Append(code, BranchNotEqualWord);
        var bpenWriteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));
        Append(code, BranchAlwaysWord);
        var afterPenWriteBranchExtensionOffset = code.Count;
        Append(code, 0);
        var bpenWriteTarget = code.Count;
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0003); // RPTAG_BPen
        Append(code, BranchNotEqualWord);
        var drMdWriteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, BranchAlwaysWord);
        var afterBpenWriteBranchExtensionOffset = code.Count;
        Append(code, 0);
        var drMdWriteTarget = code.Count;
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0004); // RPTAG_DrMd
        Append(code, BranchNotEqualWord);
        var outlinePenWriteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, BranchAlwaysWord);
        var afterPenWriteBranchExtensionOffset2 = code.Count;
        Append(code, 0);

        var outlinePenWriteTarget = code.Count;
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0005); // RPTAG_OutlinePen
        Append(code, BranchNotEqualWord);
        var writeMaskWriteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortOutlinePen));
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, OrImmediateWordD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAreaOutline));
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, BranchAlwaysWord);
        scalarSuccessBranches.Add(code.Count);
        Append(code, 0);

        var writeMaskWriteTarget = code.Count;
        Append(code, CompareImmediateLongD3);
        Append(code, 0x8000);
        Append(code, 0x0006); // RPTAG_WriteMask
        Append(code, BranchNotEqualWord);
        var maxPenWriteBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveByteD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BranchAlwaysWord);
        scalarSuccessBranches.Add(code.Count);
        Append(code, 0);

        var maxPenWriteTarget = code.Count;
        // SetMaxPen accepts a pen limit in the byte range.  Keep larger
        // ULONG requests on the provider/native boundary instead of
        // silently narrowing them to RastPort->Mask.
        Append(code, CompareImmediateLongD1);
        Append(code, 0);
        Append(code, 0x00FF);
        Append(code, BranchHighWord);
        var maxPenRangeBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(maxPenRangeBranchExtensionOffset);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var maxPenZeroBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, MoveLongD1ToD0);
        Append(code, MoveQuickOneD1);
        var maxPenLoopOffset = code.Count;
        Append(code, ShiftRightLongD0);
        Append(code, BranchEqualWord);
        var maxPenDoneBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, ShiftLeftLongD1);
        Append(code, OrImmediateByteD1);
        Append(code, 1);
        Append(code, BranchAlwaysWord);
        var maxPenLoopBranchExtensionOffset = code.Count;
        Append(code, 0);
        var maxPenDoneOffset = code.Count;
        Append(code, MoveByteD1ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortMask));
        Append(code, BranchAlwaysWord);
        scalarSuccessBranches.Add(code.Count);
        Append(code, 0);
        var maxPenZeroOffset = code.Count;
        Append(code, BranchAlwaysWord);
        scalarSuccessBranches.Add(code.Count);
        Append(code, 0);
        var afterPenWriteOffset = code.Count;
        PatchBranch(code, bpenWriteBranchExtensionOffset, bpenWriteTarget);
        PatchBranch(code, afterPenWriteBranchExtensionOffset, afterPenWriteOffset);
        PatchBranch(code, drMdWriteBranchExtensionOffset, drMdWriteTarget);
        PatchBranch(code, afterBpenWriteBranchExtensionOffset, afterPenWriteOffset);
        PatchBranch(code, outlinePenWriteBranchExtensionOffset, outlinePenWriteTarget);
        PatchBranch(code, afterPenWriteBranchExtensionOffset2, afterPenWriteOffset);
        PatchBranch(code, writeMaskWriteBranchExtensionOffset, writeMaskWriteTarget);
        PatchBranch(code, maxPenWriteBranchExtensionOffset, maxPenWriteTarget);
        Append(code, MoveQuickFifteenD0);
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortLinePatternCount));
        Append(code, MoveByteA1DisplacementToD5);
        Append(code, checked((ushort)GraphicsLayouts.RastPortBgPen));
        Append(code, MoveByteA1DisplacementToD6);
        Append(code, checked((ushort)GraphicsLayouts.RastPortDrawMode));
        Append(code, MoveByteA1DisplacementToD4);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFgPen));

        // Dispatch the four non-complement minterm tables first; complement
        // mode is independent of both pens and only depends on INVERSVID.
        Append(code, BitTestImmediateD6);
        Append(code, 4);
        Append(code, BranchNotEqualWord);
        var complementDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD6);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var inverseDispatchBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var jam2DispatchBranchExtensionOffset = code.Count;
        Append(code, 0);

        AppendMintermsByForeground(
            code,
            GraphicsLayouts.RastPortMinterms,
            0x2A,
            0xEA);
        AppendSuccessBranch(code, successBranches);

        var jam2Target = code.Count;
        AppendMintermsByPens(
            code,
            GraphicsLayouts.RastPortMinterms,
            0x0A,
            0x3A,
            0xCA,
            0xFA);
        AppendSuccessBranch(code, successBranches);

        var inverseTarget = code.Count;
        Append(code, BitTestImmediateD6);
        Append(code, 1);
        Append(code, BranchNotEqualWord);
        var inverseJam2BranchExtensionOffset = code.Count;
        Append(code, 0);
        AppendMintermsByForeground(
            code,
            GraphicsLayouts.RastPortMinterms,
            0x8A,
            0xBA);
        AppendSuccessBranch(code, successBranches);

        var inverseJam2Target = code.Count;
        AppendMintermsByPens(
            code,
            GraphicsLayouts.RastPortMinterms,
            0x0A,
            0xCA,
            0x3A,
            0xFA);
        AppendSuccessBranch(code, successBranches);

        var complementTarget = code.Count;
        Append(code, BitTestImmediateD6);
        Append(code, 2);
        Append(code, BranchNotEqualWord);
        var complementInverseBranchExtensionOffset = code.Count;
        Append(code, 0);
        AppendMintermsConstant(code, GraphicsLayouts.RastPortMinterms, 0x9A);
        AppendSuccessBranch(code, successBranches);

        var complementInverseTarget = code.Count;
        AppendMintermsConstant(code, GraphicsLayouts.RastPortMinterms, 0x6A);
        AppendSuccessBranch(code, successBranches);

        var successOffset = code.Count;
        Append(code, MoveWordA1DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, AndImmediateWordD0);
        Append(code, 0xBFFF); // clear RPF_NO_PENS
        Append(code, MoveWordD0ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFlags));
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var scalarSuccessOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var emptySuccessOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, ReturnFromSubroutine);

        var malformedOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, BranchAlwaysWord);
        var malformedBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, malformedBranchExtensionOffset, fallbackEntryOffset);

        PatchBranch(code, nullTagsBranchExtensionOffset, emptySuccessOffset);
        PatchBranch(code, doneTagBranchExtensionOffset, emptySuccessOffset);
        PatchBranch(code, complementDispatchBranchExtensionOffset, complementTarget);
        PatchBranch(code, inverseDispatchBranchExtensionOffset, inverseTarget);
        PatchBranch(code, jam2DispatchBranchExtensionOffset, jam2Target);
        PatchBranch(code, inverseJam2BranchExtensionOffset, inverseJam2Target);
        PatchBranch(code, complementInverseBranchExtensionOffset, complementInverseTarget);
        PatchBranch(code, maxPenRangeBranchExtensionOffset, malformedOffset);
        PatchBranch(code, maxPenZeroBranchExtensionOffset, maxPenZeroOffset);
        PatchBranch(code, maxPenDoneBranchExtensionOffset, maxPenDoneOffset);
        PatchBranch(code, maxPenLoopBranchExtensionOffset, maxPenLoopOffset);
        foreach (var branchExtensionOffset in successBranches)
            PatchBranch(code, branchExtensionOffset, successOffset);
        foreach (var branchExtensionOffset in scalarSuccessBranches)
            PatchBranch(code, branchExtensionOffset, scalarSuccessOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, malformedOffset);

        return offset;
    }

    private static void AppendSuccessBranch(
        List<byte> code,
        List<int> successBranches)
    {
        Append(code, BranchAlwaysWord);
        successBranches.Add(code.Count);
        Append(code, 0);
    }

    private static void AppendMintermsConstant(
        List<byte> code,
        int firstOffset,
        byte value)
    {
        for (var plane = 0; plane < 8; plane++)
            AppendMintermStore(code, firstOffset + plane, value);
    }

    private static void AppendMintermsByForeground(
        List<byte> code,
        int firstOffset,
        byte foregroundZero,
        byte foregroundOne)
    {
        for (var plane = 0; plane < 8; plane++)
        {
            Append(code, MoveQuickImmediateD0(foregroundZero));
            Append(code, BitTestImmediateD4);
            Append(code, checked((ushort)plane));
            Append(code, BranchNotEqualWord);
            var foregroundOneBranchExtensionOffset = code.Count;
            Append(code, 0);
            AppendMintermStore(code, firstOffset + plane, foregroundZero);
            Append(code, BranchAlwaysWord);
            var nextPlaneBranchExtensionOffset = code.Count;
            Append(code, 0);
            var foregroundOneOffset = code.Count;
            AppendMintermStore(code, firstOffset + plane, foregroundOne);
            var nextPlaneOffset = code.Count;
            PatchBranch(code, foregroundOneBranchExtensionOffset, foregroundOneOffset);
            PatchBranch(code, nextPlaneBranchExtensionOffset, nextPlaneOffset);
        }
    }

    private static void AppendMintermsByPens(
        List<byte> code,
        int firstOffset,
        byte foregroundZeroBackgroundZero,
        byte foregroundZeroBackgroundOne,
        byte foregroundOneBackgroundZero,
        byte foregroundOneBackgroundOne)
    {
        for (var plane = 0; plane < 8; plane++)
        {
            Append(code, BitTestImmediateD4);
            Append(code, checked((ushort)plane));
            Append(code, BranchNotEqualWord);
            var foregroundOneBranchExtensionOffset = code.Count;
            Append(code, 0);

            Append(code, BitTestImmediateD5);
            Append(code, checked((ushort)plane));
            Append(code, BranchNotEqualWord);
            var foregroundZeroBackgroundOneBranchExtensionOffset = code.Count;
            Append(code, 0);
            AppendMintermStore(
                code,
                firstOffset + plane,
                foregroundZeroBackgroundZero);
            Append(code, BranchAlwaysWord);
            var foregroundZeroDoneBranchExtensionOffset = code.Count;
            Append(code, 0);

            var foregroundZeroBackgroundOneOffset = code.Count;
            AppendMintermStore(
                code,
                firstOffset + plane,
                foregroundZeroBackgroundOne);
            Append(code, BranchAlwaysWord);
            var foregroundZeroBackgroundOneDoneBranchExtensionOffset = code.Count;
            Append(code, 0);

            var foregroundOneOffset = code.Count;
            Append(code, BitTestImmediateD5);
            Append(code, checked((ushort)plane));
            Append(code, BranchNotEqualWord);
            var foregroundOneBackgroundOneBranchExtensionOffset = code.Count;
            Append(code, 0);
            AppendMintermStore(
                code,
                firstOffset + plane,
                foregroundOneBackgroundZero);
            Append(code, BranchAlwaysWord);
            var foregroundOneBackgroundZeroDoneBranchExtensionOffset = code.Count;
            Append(code, 0);

            var foregroundOneBackgroundOneOffset = code.Count;
            AppendMintermStore(
                code,
                firstOffset + plane,
                foregroundOneBackgroundOne);
            var nextPlaneOffset = code.Count;

            PatchBranch(code, foregroundOneBranchExtensionOffset, foregroundOneOffset);
            PatchBranch(
                code,
                foregroundZeroBackgroundOneBranchExtensionOffset,
                foregroundZeroBackgroundOneOffset);
            PatchBranch(
                code,
                foregroundZeroDoneBranchExtensionOffset,
                nextPlaneOffset);
            PatchBranch(
                code,
                foregroundZeroBackgroundOneDoneBranchExtensionOffset,
                nextPlaneOffset);
            PatchBranch(
                code,
                foregroundOneBackgroundOneBranchExtensionOffset,
                foregroundOneBackgroundOneOffset);
            PatchBranch(
                code,
                foregroundOneBackgroundZeroDoneBranchExtensionOffset,
                nextPlaneOffset);
        }
    }

    private static void AppendMintermStore(
        List<byte> code,
        int offset,
        byte value)
    {
        Append(code, MoveQuickImmediateD0(value));
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)offset));
    }

    private static ushort MoveQuickImmediateD0(byte value)
        => (ushort)(0x7000 | value);

    private static int AppendAskSoftStyle(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(5);
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x0100); // D7, reversed predecrement mask.

        // A NULL Font is the readable empty-RastPort query and returns no
        // available algorithmic styles.  A selected font returns the
        // complement of its intrinsic style byte, matching AskSoftStyle's
        // ULONG result shape, after a public TextFont envelope guard.
        Append(code, MoveLongD0ToD7);
        Append(code, MoveLongA1ToD1);
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullRastPortBranchExtensionOffset);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRastPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFC8); // RP.Font LONG at 0x34; do not require the whole RastPort.
        Append(code, BranchHighWord);
        var wrappedRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedRastPortBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD1);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFont));
        Append(code, TestLongD1);
        Append(code, BranchEqualWord);
        var nullBranchExtensionOffset = code.Count;
        Append(code, 0);
        Append(code, BitTestImmediateD1);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddBranchExtensionOffset);
        Append(code, CompareImmediateLongD1);
        Append(code, 0xFFFF);
        Append(code, 0xFFCC); // TextFontMinimumSize (0x34) envelope
        Append(code, BranchHighWord);
        var wrappedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedBranchExtensionOffset);
        Append(code, MoveAddressD1ToA0);
        Append(code, MoveQuickMinusOneD0);
        Append(code, MoveByteA0DisplacementToD0);
        Append(code, checked((ushort)GraphicsLayouts.TextFontStyle));
        Append(code, NotByteD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x0080); // Restore public D7 without changing the result or CCR.
        Append(code, ReturnFromSubroutine);

        var nullEntryOffset = code.Count;
        Append(code, MoveQuickZeroD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x0080); // Restore public D7 without changing the result or CCR.
        Append(code, ReturnFromSubroutine);

        PatchBranch(code, nullBranchExtensionOffset, nullEntryOffset);
        var malformedOffset = code.Count;
        Append(code, MoveLongD7ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x0080); // Recover the original D0 before restoring public D7.
        Append(code, BranchAlwaysWord);
        var malformedBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, malformedBranchExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, malformedOffset);
        return offset;
    }

    private static int AppendSetSoftStyle(List<byte> code, int fallbackEntryOffset)
    {
        var offset = code.Count;
        var fallbackBranches = new List<int>(6);
        Append(code, MoveMultipleLongRegistersToPreDecrementA7);
        Append(code, 0x3E00); // D2-D6, reversed predecrement mask.

        // SetSoftStyle is meaningful only with a selected TextFont.  Keep the
        // NULL-font form on the shared fallback; the selected-font body uses
        // the public intrinsic-style byte and AlgoStyle field to perform the
        // classic enable-mask merge.
        Append(code, MoveLongA1ToD2);
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var nullRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullRastPortBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddRastPortBranchExtensionOffset);
        Append(code, CompareImmediateLongD2);
        Append(code, 0xFFFF);
        Append(code, 0xFFC6); // RP.AlgoStyle byte at 0x38; last valid even base.
        Append(code, BranchHighWord);
        var wrappedRastPortBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedRastPortBranchExtensionOffset);
        Append(code, MoveLongA1DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.RastPortFont));
        Append(code, TestLongD2);
        Append(code, BranchEqualWord);
        var nullBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(nullBranchExtensionOffset);
        Append(code, BitTestImmediateD2);
        Append(code, 0);
        Append(code, BranchNotEqualWord);
        var oddBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(oddBranchExtensionOffset);
        Append(code, CompareImmediateLongD2);
        Append(code, 0xFFFF);
        Append(code, 0xFFCC); // TextFontMinimumSize (0x34) envelope
        Append(code, BranchHighWord);
        var wrappedBranchExtensionOffset = code.Count;
        Append(code, 0);
        fallbackBranches.Add(wrappedBranchExtensionOffset);
        Append(code, MoveAddressD2ToA0);
        Append(code, MoveQuickZeroD2);
        Append(code, MoveByteA0DisplacementToD2);
        Append(code, checked((ushort)GraphicsLayouts.TextFontStyle));
        Append(code, MoveQuickZeroD3);
        Append(code, MoveByteA1DisplacementToD3);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAlgoStyle));
        Append(code, MoveLongD2ToD4);
        Append(code, NotLongD4);
        Append(code, AndLongD1ToD4);
        Append(code, MoveLongD4ToD5);
        Append(code, NotLongD5);
        Append(code, AndLongD3ToD5);
        Append(code, MoveLongD4ToD6);
        Append(code, AndLongD0ToD6);
        Append(code, OrLongD6ToD5);
        Append(code, MoveByteD5ToA1Displacement);
        Append(code, checked((ushort)GraphicsLayouts.RastPortAlgoStyle));
        Append(code, MoveQuickZeroD0);
        Append(code, MoveByteD5ToD0);
        Append(code, OrByteD2ToD0);
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x007C); // Preserve the combined style result and CCR.
        Append(code, ReturnFromSubroutine);

        var declineOffset = code.Count;
        Append(code, MoveMultipleLongA7PostIncrementToRegisters);
        Append(code, 0x007C); // All font guards retain original D0/D1 before unwinding.
        Append(code, BranchAlwaysWord);
        var declineBranchExtensionOffset = code.Count;
        Append(code, 0);
        PatchBranch(code, declineBranchExtensionOffset, fallbackEntryOffset);
        foreach (var branchExtensionOffset in fallbackBranches)
            PatchBranch(code, branchExtensionOffset, declineOffset);
        return offset;
    }

    private static void AppendSetByteBody(List<byte> code, int rastPortOffset)
    {
        Append(code, MoveByteD0ToA1Displacement);
        Append(code, checked((ushort)rastPortOffset));
    }

    private static void Append(List<byte> code, ushort opcode, ushort extension)
    {
        Append(code, opcode);
        Append(code, extension);
    }

    private static int Append(List<byte> code, ushort word)
    {
        var offset = code.Count;
        code.Add((byte)(word >> 8));
        code.Add((byte)word);
        return offset;
    }
}
